--
-- Name: abonar_transacao_pendente(bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.abonar_transacao_pendente(p_transacao_id bigint, p_abonado_por uuid DEFAULT NULL::uuid, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_atual public.transacao%ROWTYPE;
  v_transacao public.transacao%ROWTYPE;
BEGIN
  IF p_transacao_id IS NULL OR p_transacao_id <= 0 THEN
    RAISE EXCEPTION 'Transação inválida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_atual FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_atual.pendente, false) THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  IF upper(v_atual.tipo::text) <> 'RECEITA' THEN
    RAISE EXCEPTION 'Só é possível abonar uma cobrança a receber.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.ordemservicoid IS NULL AND v_atual.vendaid IS NULL THEN
    RAISE EXCEPTION 'Este lançamento não está ligado a uma OS ou venda.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.evento_financeiro_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este lançamento é um evento financeiro da OS, não uma cobrança avulsa.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.adiantamento_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Este título está ligado à antecipação #%. Desfaça a antecipação primeiro.',
      v_atual.adiantamento_id USING ERRCODE = '22023';
  END IF;
  IF coalesce(v_atual.eh_adiantamento, false) THEN
    RAISE EXCEPTION 'Isto é uma antecipação, não uma cobrança avulsa.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.pagamento_multiplo_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta cobrança faz parte do pagamento múltiplo #%. Desfaça o grupo primeiro.',
      v_atual.pagamento_multiplo_id USING ERRCODE = '22023';
  END IF;

  UPDATE public.transacao
     SET pendente = false,
         banco_id = NULL,
         metodopagamento = NULL,
         baixado_por = NULL,
         pago_em = now(),
         abonado = true,
         abonado_por = p_abonado_por,
         abonado_em = now(),
         abono_motivo = nullif(btrim(coalesce(p_motivo, '')), ''),
         updated_at = now()
   WHERE id = p_transacao_id
     AND pendente = true
     AND is_deleted = false
  RETURNING * INTO v_transacao;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
  ) VALUES (
    v_transacao.id, coalesce(v_transacao.vencimento_em, v_transacao.data), v_transacao.pago_em,
    p_abonado_por, NULL, NULL, 'ABONO'
  );

  IF v_transacao.ordemservicoid IS NOT NULL THEN
    PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
  END IF;
  IF v_transacao.vendaid IS NOT NULL THEN
    PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
  END IF;

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pendente', false,
    'abonado', true,
    'abonado_em', v_transacao.abonado_em
  );
END;
$$;


--
-- Name: FUNCTION abonar_transacao_pendente(p_transacao_id bigint, p_abonado_por uuid, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.abonar_transacao_pendente(p_transacao_id bigint, p_abonado_por uuid, p_motivo text) IS 'Perdoa um título a receber inteiro sem lançar nada no banco: pendente vira false, banco_id fica nulo, e a OS/venda continua contando o valor de face como recebido. Recusa antecipação, pagamento múltiplo e o que não for RECEITA ligado a OS/venda.';


--
-- Name: agendamento_periodo(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agendamento_periodo(p_inicio timestamp with time zone, p_fim timestamp with time zone) RETURNS tstzrange
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select tstzrange(
    p_inicio,
    coalesce(p_fim, p_inicio + interval '1 minute'),
    '[)'
  )
$$;


--
-- Name: ajustar_eventos_frete_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_eventos_frete_os(p_ordemservicoid integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_frete numeric(14,2) := 0;
  v_total numeric(14,2) := 0;
  v_bruto numeric(14,2) := 0;
  v_desconto numeric(14,2) := 0;
BEGIN
  SELECT o.status::text, round(coalesce(o.valor_frete, 0), 2), round(coalesce(o.orcamentototal, 0), 2),
         coalesce((SELECT sum(coalesce(op.precounitario, 0) * coalesce(op.quantidade, 0))
                     FROM public.osproduto op WHERE op.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(opa.precounitario, 0) * coalesce(opa.quantidade, 0))
                         FROM public.osproduto_avulso opa WHERE opa.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(os.precounitario, 0) * coalesce(os.quantidade, 0))
                         FROM public.osservico os WHERE os.ordemservicoid = o.id), 0)
    INTO v_status, v_frete, v_total, v_bruto
    FROM public.ordemservico o
   WHERE o.id = p_ordemservicoid;
  IF NOT FOUND THEN RETURN; END IF;

  IF v_status NOT IN ('ORCAMENTO_APROVADO', 'EM_ANDAMENTO', 'PAGAMENTO', 'FATURAMENTO', 'CONCLUIDO') THEN
    UPDATE public.eventos_financeiros
       SET status = 'CANCELADO', updated_at = now()
     WHERE ordemservicoid = p_ordemservicoid
       AND origem IN ('FRETE', 'DESCONTO') AND status = 'ATIVO';
    RETURN;
  END IF;

  IF v_frete > 0 THEN
    INSERT INTO public.eventos_financeiros
      (ordemservicoid, origem, natureza, natureza_dre, chave_origem, descricao,
       detalhe, valor, dados_snapshot, pode_gerar_transacao, status, updated_at)
    VALUES
      (p_ordemservicoid, 'FRETE', 'RECEITA', 'RECEITA', 'FRETE',
       'Frete - OS #' || p_ordemservicoid, 'Receita de frete da ordem de servico',
       v_frete, jsonb_build_object('valor_frete', v_frete), false, 'ATIVO', now())
    ON CONFLICT (ordemservicoid, origem, chave_origem, natureza) DO UPDATE SET
      valor = excluded.valor,
      natureza_dre = 'RECEITA',
      dados_snapshot = excluded.dados_snapshot,
      status = 'ATIVO',
      updated_at = now()
    WHERE public.eventos_financeiros.status <> 'CONVERTIDO';
  ELSE
    UPDATE public.eventos_financeiros
       SET status = 'CANCELADO', updated_at = now()
     WHERE ordemservicoid = p_ordemservicoid
       AND origem = 'FRETE' AND status <> 'CONVERTIDO';
  END IF;

  -- O total comercial inclui frete. Para recuperar o desconto sobre os itens,
  -- a formula correta e bruto + frete - total da OS.
  v_desconto := round(greatest(v_bruto + v_frete - v_total, 0), 2);
  IF v_desconto > 0 THEN
    INSERT INTO public.eventos_financeiros
      (ordemservicoid, origem, natureza, natureza_dre, chave_origem, descricao,
       detalhe, valor, dados_snapshot, pode_gerar_transacao, status, updated_at)
    VALUES
      (p_ordemservicoid, 'DESCONTO', 'DESPESA', 'DEDUCAO', 'DESCONTO',
       'Desconto concedido - OS #' || p_ordemservicoid, 'Deducao da receita bruta',
       v_desconto, jsonb_build_object('bruto', v_bruto, 'frete', v_frete, 'total_os', v_total),
       false, 'ATIVO', now())
    ON CONFLICT (ordemservicoid, origem, chave_origem, natureza) DO UPDATE SET
      valor = excluded.valor,
      natureza_dre = 'DEDUCAO',
      dados_snapshot = excluded.dados_snapshot,
      status = 'ATIVO',
      updated_at = now()
    WHERE public.eventos_financeiros.status <> 'CONVERTIDO';
  ELSE
    UPDATE public.eventos_financeiros
       SET status = 'CANCELADO', updated_at = now()
     WHERE ordemservicoid = p_ordemservicoid
       AND origem = 'DESCONTO' AND status <> 'CONVERTIDO';
  END IF;
END;
$$;


--
-- Name: ajustar_inventario_usoconsumo(integer, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_inventario_usoconsumo(p_item_id integer, p_novo_saldo integer, p_observacao text, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_item public.usoconsumo_item%ROWTYPE; v_diferenca integer; v_result jsonb;
BEGIN
  IF p_novo_saldo IS NULL OR p_novo_saldo<0 THEN RAISE EXCEPTION 'Novo saldo invalido.' USING ERRCODE='22023'; END IF;
  IF nullif(btrim(p_observacao),'') IS NULL THEN RAISE EXCEPTION 'Informe a justificativa do inventario.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_item FROM public.usoconsumo_item WHERE id=p_item_id AND ativo FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Item nao encontrado.' USING ERRCODE='P0002'; END IF;
  v_diferenca:=p_novo_saldo-v_item.estoque;
  IF v_diferenca=0 THEN RETURN jsonb_build_object('item_id',p_item_id,'saldo',p_novo_saldo,'alterado',false); END IF;
  IF v_diferenca>0 THEN
    SELECT public.registrar_entrada_usoconsumo(
      jsonb_build_object('fiscal',false,'origem','INVENTARIO','tipo','DEVOLUCAO','escopo',v_item.escopo,'created_by',p_created_by),
      jsonb_build_array(jsonb_build_object('item_id',p_item_id,'quantidade',v_diferenca,'valor_unitario_compra',coalesce(v_item.ultimovalordecompra,v_item.precocompra,0))),
      '[]'::jsonb
    ) INTO v_result;
  ELSE
    SELECT public.registrar_saida_usoconsumo(
      jsonb_build_object('motivo','AJUSTE_INVENTARIO','observacao',p_observacao,'escopo',v_item.escopo,'created_by',p_created_by),
      jsonb_build_array(jsonb_build_object('item_id',p_item_id,'quantidade',abs(v_diferenca)))
    ) INTO v_result;
  END IF;
  RETURN v_result || jsonb_build_object('item_id',p_item_id,'saldo',p_novo_saldo,'alterado',true);
END $$;


--
-- Name: ajustar_saldo_credito_cliente(integer, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_saldo_credito_cliente(p_cliente_id integer, p_sentido text, p_valor numeric, p_motivo text DEFAULT NULL::text, p_usuario uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sentido text;
  v_valor numeric(14,2);
  v_saldo_anterior numeric(14,2);
  v_saldo_resultante numeric(14,2);
  v_movimento_id bigint;
BEGIN
  v_sentido := upper(btrim(coalesce(p_sentido, '')));
  IF v_sentido NOT IN ('CREDITO', 'DEBITO') THEN
    RAISE EXCEPTION 'Informe se o ajuste adiciona (CREDITO) ou remove (DEBITO) saldo.'
      USING ERRCODE = '22023';
  END IF;

  v_valor := round(coalesce(p_valor, 0), 2);
  IF v_valor <= 0 THEN
    RAISE EXCEPTION 'O valor do ajuste deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;

  -- Trava a linha do cliente: dois ajustes simultâneos não podem ler o mesmo
  -- saldo e gravar cada um o seu.
  SELECT c.saldo_credito INTO v_saldo_anterior
    FROM public.cliente c
   WHERE c.id = p_cliente_id AND c.is_deleted = false
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  v_saldo_anterior := coalesce(v_saldo_anterior, 0);
  v_saldo_resultante := CASE
    WHEN v_sentido = 'CREDITO' THEN v_saldo_anterior + v_valor
    ELSE v_saldo_anterior - v_valor
  END;

  IF v_saldo_resultante < 0 THEN
    RAISE EXCEPTION
      'O cliente tem % de crédito: não dá para remover %.',
      to_char(v_saldo_anterior, 'FM999999990.00'), to_char(v_valor, 'FM999999990.00')
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.cliente_saldo_movimento (
    cliente_id, sentido, origem, acao, valor,
    saldo_anterior, saldo_resultante, motivo, created_by
  ) VALUES (
    p_cliente_id, v_sentido, 'MANUAL', 'REGISTRO', v_valor,
    v_saldo_anterior, round(v_saldo_resultante, 2),
    nullif(btrim(coalesce(p_motivo, '')), ''), p_usuario
  ) RETURNING id INTO v_movimento_id;

  RETURN jsonb_build_object(
    'movimento_id', v_movimento_id,
    'cliente_id', p_cliente_id,
    'sentido', v_sentido,
    'valor', v_valor,
    'saldo_anterior', v_saldo_anterior,
    'saldo', round(v_saldo_resultante, 2)
  );
END;
$$;


--
-- Name: FUNCTION ajustar_saldo_credito_cliente(p_cliente_id integer, p_sentido text, p_valor numeric, p_motivo text, p_usuario uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ajustar_saldo_credito_cliente(p_cliente_id integer, p_sentido text, p_valor numeric, p_motivo text, p_usuario uuid) IS 'Adiciona ou remove crédito do cliente à mão, gravando o movimento no razão. Recusa remoção que deixaria o saldo negativo.';


--
-- Name: ajustar_valores_transacao(jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ajustar_valores_transacao(p_itens jsonb, p_alterado_por uuid DEFAULT NULL::uuid, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET lock_timeout TO '5s'
    AS $_$
DECLARE
  v_ids bigint[];
  v_total int;
  v_qtd_os int;
  v_qtd_venda int;
  v_qtd_avulsa int;
  v_os bigint;
  v_venda bigint;
  v_esperado int;
  v_soma_atual bigint;
  v_soma_nova bigint;
  v_item record;
  v_anterior public.transacao%ROWTYPE;
  v_resultado jsonb := '[]'::jsonb;
BEGIN
  IF p_itens IS NULL
     OR jsonb_typeof(p_itens) <> 'array'
     OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Informe ao menos uma transacao para ajustar.' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg((item->>'id')::bigint)
    INTO v_ids
    FROM jsonb_array_elements(p_itens) AS item;

  v_total := array_length(v_ids, 1);

  IF v_total <> (SELECT count(DISTINCT x) FROM unnest(v_ids) AS x) THEN
    RAISE EXCEPTION 'A mesma transacao foi enviada mais de uma vez.' USING ERRCODE = '22023';
  END IF;

  -- Trava as linhas antes de qualquer leitura de soma, e sempre na mesma ordem:
  -- e a ordem que impede duas chamadas simultaneas de se travarem uma a outra.
  BEGIN
    PERFORM 1
       FROM public.transacao
      WHERE id = ANY(v_ids)
        AND is_deleted = false
      ORDER BY id
      FOR UPDATE;
  EXCEPTION
    WHEN lock_not_available THEN
      RAISE EXCEPTION
        'Outra pessoa esta salvando esta transacao neste momento. Espere alguns segundos e tente de novo.'
        USING ERRCODE = '55P03';
  END;

  SELECT
    count(*),
    count(DISTINCT ordemservicoid) FILTER (WHERE ordemservicoid IS NOT NULL),
    count(DISTINCT vendaid) FILTER (WHERE vendaid IS NOT NULL),
    count(*) FILTER (WHERE ordemservicoid IS NULL AND vendaid IS NULL),
    max(ordemservicoid),
    max(vendaid),
    coalesce(sum(round(valor * 100)), 0)
  INTO v_esperado, v_qtd_os, v_qtd_venda, v_qtd_avulsa, v_os, v_venda, v_soma_atual
  FROM public.transacao
  WHERE id = ANY(v_ids)
    AND is_deleted = false;

  IF v_esperado <> v_total THEN
    RAISE EXCEPTION 'Transacao nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  /*
   * Concorrencia: os valores precisam estar exatamente como estavam quando a
   * tela foi aberta. `coalesce(nullif("valorLiquido", 0), valor)` espelha o
   * `valorLiquidoEfetivo` do cliente — registro antigo com liquido nulo ou
   * zerado vale o bruto, dos dois lados, senao a comparacao acusaria conflito
   * onde nao existe.
   */
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_itens) AS item
      JOIN public.transacao t ON t.id = (item->>'id')::bigint
     WHERE item->>'valorAnterior' IS NULL
        OR item->>'valorLiquidoAnterior' IS NULL
        OR round(t.valor * 100) <> round((item->>'valorAnterior')::numeric * 100)
        OR round(coalesce(nullif(t."valorLiquido", 0), t.valor) * 100)
             <> round((item->>'valorLiquidoAnterior')::numeric * 100)
  ) THEN
    RAISE EXCEPTION
      'Os valores mudaram depois que esta tela foi aberta. Recarregue e refaca o rateio.'
      USING ERRCODE = '40001';
  END IF;

  IF v_qtd_os + v_qtd_venda > 1 OR ((v_qtd_os + v_qtd_venda) = 1 AND v_qtd_avulsa > 0) THEN
    RAISE EXCEPTION 'O ajuste precisa ficar dentro de um unico documento.' USING ERRCODE = '22023';
  END IF;

  IF v_qtd_os = 1 OR v_qtd_venda = 1 THEN
    -- Com documento: exige o grupo completo, senao a soma nao pode ser garantida.
    SELECT count(*)
      INTO v_esperado
      FROM public.transacao
     WHERE is_deleted = false
       AND upper(tipo::text) = 'RECEITA'
       AND evento_financeiro_id IS NULL
       AND ((v_qtd_os = 1 AND ordemservicoid = v_os)
         OR (v_qtd_venda = 1 AND vendaid = v_venda));

    IF v_esperado <> v_total THEN
      RAISE EXCEPTION
        'O ajuste precisa incluir os % pagamentos do documento; vieram %.', v_esperado, v_total
        USING ERRCODE = '22023';
    END IF;

    SELECT coalesce(sum(round((item->>'valor')::numeric * 100)), 0)
      INTO v_soma_nova
      FROM jsonb_array_elements(p_itens) AS item;

    IF v_soma_nova <> v_soma_atual THEN
      RAISE EXCEPTION
        'A soma dos valores brutos deve continuar em R$ %; foi informado R$ %.',
        replace(to_char(v_soma_atual / 100.0, 'FM999999990.00'), '.', ','),
        replace(to_char(v_soma_nova / 100.0, 'FM999999990.00'), '.', ',')
        USING ERRCODE = '22023';
    END IF;
  ELSIF v_total > 1 THEN
    RAISE EXCEPTION 'Lancamentos avulsos sao ajustados um a um.' USING ERRCODE = '22023';
  END IF;

  /*
   * Diminui (ou mantem) antes de aumentar.
   *
   * `validar_limite_pagamento_os` checa, a cada UPDATE de linha, a soma da OS
   * com o estado corrente das outras linhas — nao ve o resultado final do lote,
   * so o que ja foi escrito nesta transacao ate ali. Como a soma do grupo inteiro
   * e constante (checado acima), processar toda linha com `valor <= anterior`
   * primeiro banca essa folga antes de qualquer linha subir; dai em diante, uma
   * sequencia de incrementos que fecha exatamente no total nunca tem um passo
   * intermediario maior que o total. Sem isto, uma parcela subindo um centavo
   * podia ser escrita antes da parcela que desce compensar, e o gatilho recusava
   * um estado transitorio que o usuario nunca pediu.
   *
   * As linhas ja estao travadas (lock acima, em ordem de id): reordenar so estes
   * UPDATEs nao adquire lock novo, entao nao reabre o deadlock de 20260817120000.
   */
  FOR v_item IN
    SELECT (item->>'id')::bigint AS id,
           round((item->>'valor')::numeric, 2) AS valor,
           round(coalesce(item->>'valorLiquido', item->>'valor')::numeric, 2) AS valor_liquido,
           round((item->>'valor')::numeric, 2)
             - round((item->>'valorAnterior')::numeric, 2) AS delta
      FROM jsonb_array_elements(p_itens) AS item
     ORDER BY delta, id
  LOOP
    IF v_item.valor <= 0 THEN
      RAISE EXCEPTION 'O valor bruto da transacao % deve ser maior que zero.', v_item.id
        USING ERRCODE = '22023';
    END IF;

    IF v_item.valor_liquido <= 0 THEN
      RAISE EXCEPTION 'O valor liquido da transacao % deve ser maior que zero.', v_item.id
        USING ERRCODE = '22023';
    END IF;

    IF v_item.valor_liquido > v_item.valor THEN
      RAISE EXCEPTION 'O liquido da transacao % nao pode ser maior que o bruto.', v_item.id
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_anterior FROM public.transacao WHERE id = v_item.id;

    UPDATE public.transacao
       SET valor = v_item.valor,
           "valorLiquido" = v_item.valor_liquido,
           updated_at = now()
     WHERE id = v_item.id;

    INSERT INTO public.transacao_valor_historico (
      transacao_id, valor_anterior, valor_novo,
      valor_liquido_anterior, valor_liquido_novo, alterado_por, motivo
    ) VALUES (
      v_item.id, v_anterior.valor, v_item.valor,
      v_anterior."valorLiquido", v_item.valor_liquido, p_alterado_por, nullif(btrim(p_motivo), '')
    );

    v_resultado := v_resultado || jsonb_build_object(
      'id', v_item.id,
      'valor', v_item.valor,
      'valorLiquido', v_item.valor_liquido
    );
  END LOOP;

  /*
   * Nao revalidamos o status da OS/venda de proposito. Com documento, a soma dos
   * brutos e constante; e como toda linha precisa terminar com valor > 0, o total
   * ja baixado tambem nao pode cruzar o total devido em nenhum sentido. Ou seja,
   * o status nao tem como mudar por causa de um rateio.
   */

  RETURN jsonb_build_object('itens', v_resultado);
END;
$_$;


--
-- Name: alterar_evento_financeiro_manual_venda(bigint, bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.alterar_evento_financeiro_manual_venda(p_venda_id bigint, p_evento_id bigint, p_operacao text, p_payload jsonb, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento public.eventos_financeiros%ROWTYPE;
  v_valor numeric;
  v_descricao text;
  v_detalhe text;
BEGIN
  IF p_usuario IS NULL OR p_operacao IS NULL OR p_operacao NOT IN ('EDITAR','EXCLUIR') THEN
    RAISE EXCEPTION 'Operação inválida.' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_evento FROM public.eventos_financeiros
   WHERE id = p_evento_id AND source_type = 'VENDA' AND source_id = p_venda_id
     AND ordemservicoid IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evento financeiro não encontrado nesta venda.' USING ERRCODE = 'P0002'; END IF;
  IF NOT coalesce(v_evento.is_manual,false) OR coalesce(v_evento.chave_origem,'') NOT LIKE 'MANUAL:%'
     OR v_evento.origem = 'COMISSAO' OR (v_evento.origem = 'FRETE' AND v_evento.natureza = 'RECEITA')
     OR v_evento.consumo_saida_id IS NOT NULL OR v_evento.consumo_usoconsumo_saida_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento deve ser corrigido na origem que o criou.' USING ERRCODE = 'P0001';
  END IF;
  IF v_evento.status = 'CONVERTIDO' OR v_evento.transacaoid IS NOT NULL OR v_evento.lancamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Exclua primeiro a transação ou o lançamento financeiro vinculado.' USING ERRCODE = 'P0001';
  END IF;
  IF v_evento.status <> 'ATIVO' THEN
    RAISE EXCEPTION 'Somente eventos ativos podem ser alterados.' USING ERRCODE = 'P0001';
  END IF;
  PERFORM set_config('app.audit_user_id',p_usuario::text,true);
  IF p_operacao = 'EXCLUIR' THEN
    DELETE FROM public.eventos_financeiros WHERE id = v_evento.id;
    RETURN jsonb_build_object('evento_id',v_evento.id,'excluido',true,'estoque_devolvido',false);
  END IF;
  v_valor := (p_payload->>'valor')::numeric;
  v_descricao := btrim(coalesce(p_payload->>'descricao',v_evento.descricao));
  v_detalhe := CASE WHEN p_payload ? 'detalhe' THEN nullif(btrim(p_payload->>'detalhe'),'') ELSE v_evento.detalhe END;
  IF v_valor IS NULL OR v_valor::text IN ('NaN','Infinity','-Infinity') OR round(v_valor,2) < 0
     OR nullif(v_descricao,'') IS NULL THEN
    RAISE EXCEPTION 'Informe título e valor válidos.' USING ERRCODE = '22023';
  END IF;
  UPDATE public.eventos_financeiros SET descricao = v_descricao, detalhe = v_detalhe,
    valor = round(v_valor,2),updated_at = now(),dados_snapshot = coalesce(dados_snapshot,'{}'::jsonb)
      || jsonb_build_object('ajuste_manual',true,'ajustado_em',now(),'ajustado_por',p_usuario)
    WHERE id = v_evento.id RETURNING * INTO v_evento;
  RETURN to_jsonb(v_evento);
END;
$$;


--
-- Name: aluguel_baixar_item(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_baixar_item(p_item_id bigint, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.aluguel_item%rowtype;
  v_saida jsonb;
  v_saida_id bigint;
  v_rotulo text;
begin
  select * into v_item from public.aluguel_item where id = p_item_id for update;
  if not found then
    raise exception 'Item do aluguel nao encontrado.' using errcode = 'P0002';
  end if;
  if v_item.estoque_saida_id is not null or v_item.usoconsumo_saida_id is not null then
    return;
  end if;

  v_rotulo := 'Aluguel #' || v_item.aluguel_id;

  if v_item.tipo = 'PRODUTO' then
    v_saida := public.registrar_saida_estoque(
      v_item.produto_id, v_item.quantidade, 'ALUGUEL', v_rotulo, p_usuario
    );
    v_saida_id := (v_saida->>'saida_id')::bigint;
    update public.estoque_saida set aluguel_id = v_item.aluguel_id where id = v_saida_id;
    update public.aluguel_item set estoque_saida_id = v_saida_id, devolvido_em = null where id = p_item_id;
  elsif v_item.tipo in ('USOCONSUMO', 'GERAL') then
    v_saida := public.registrar_saida_usoconsumo(
      jsonb_build_object(
        'escopo', v_item.tipo,
        'motivo', 'ALUGUEL',
        'observacao', v_rotulo,
        'created_by', p_usuario
      ),
      jsonb_build_array(jsonb_build_object('item_id', v_item.usoconsumo_item_id, 'quantidade', v_item.quantidade))
    );
    v_saida_id := (v_saida->>'saida_id')::bigint;
    update public.usoconsumo_saida set aluguel_id = v_item.aluguel_id where id = v_saida_id;
    update public.aluguel_item set usoconsumo_saida_id = v_saida_id, devolvido_em = null where id = p_item_id;
  end if;
end;
$$;


--
-- Name: aluguel_devolver_item(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_devolver_item(p_item_id bigint, p_motivo text, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.aluguel_item%rowtype;
  v_status text;
begin
  select * into v_item from public.aluguel_item where id = p_item_id for update;
  if not found then
    raise exception 'Item do aluguel nao encontrado.' using errcode = 'P0002';
  end if;

  perform set_config('app.aluguel_estorno', 'permitido', true);

  if v_item.estoque_saida_id is not null then
    select status into v_status from public.estoque_saida where id = v_item.estoque_saida_id;
    if v_status is distinct from 'CANCELADA' then
      perform public.cancelar_saida_estoque(v_item.estoque_saida_id, p_motivo, p_usuario);
    end if;
  elsif v_item.usoconsumo_saida_id is not null then
    select status into v_status from public.usoconsumo_saida where id = v_item.usoconsumo_saida_id;
    if v_status is distinct from 'CANCELADA' then
      perform public.cancelar_saida_usoconsumo(v_item.usoconsumo_saida_id, p_motivo, p_usuario);
    end if;
  end if;

  perform set_config('app.aluguel_estorno', '', true);

  update public.aluguel_item set devolvido_em = coalesce(devolvido_em, now()) where id = p_item_id;
end;
$$;


--
-- Name: aluguel_encerrar(bigint, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_encerrar(p_id bigint, p_encerrado_em timestamp with time zone, p_observacao text, p_usuario uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.aluguel_encerrar(p_id, p_encerrado_em, p_observacao, null::jsonb, p_usuario);
$$;


--
-- Name: aluguel_encerrar(bigint, timestamp with time zone, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_encerrar(p_id bigint, p_encerrado_em timestamp with time zone, p_observacao text, p_itens jsonb, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_atual public.aluguel%rowtype;
  v_linha public.aluguel_item%rowtype;
  v_json jsonb;
  v_devolvidos integer := 0;
  v_voltou integer;
  v_nao_retornados text[] := '{}';
  v_retorno timestamptz := coalesce(p_encerrado_em, now());
  v_dia_retorno date := (coalesce(p_encerrado_em, now()) at time zone 'America/Fortaleza')::date;
  v_hoje date := public.aluguel_hoje();
  v_retornos jsonb := '{}'::jsonb;
begin
  select * into v_atual from public.aluguel where id = p_id and not is_deleted for update;
  if not found then raise exception 'Aluguel nao encontrado.' using errcode = 'P0002'; end if;
  if v_atual.status = 'ENCERRADO' then
    raise exception 'Este aluguel ja esta encerrado.' using errcode = '22023';
  end if;
  if v_dia_retorno > v_hoje then
    raise exception 'A data de retorno nao pode estar no futuro.' using errcode = '22023';
  end if;
  -- Agendado (inicio no futuro) encerra hoje; os demais, a partir do inicio.
  if v_dia_retorno < least(v_atual.data_inicio, v_hoje) then
    raise exception 'A data de retorno (%) nao pode ser anterior ao inicio do aluguel (%).',
      to_char(v_dia_retorno, 'DD/MM/YYYY'), to_char(v_atual.data_inicio, 'DD/MM/YYYY')
      using errcode = '22023';
  end if;

  if p_itens is not null and jsonb_typeof(p_itens) <> 'array' then
    raise exception 'Lista de itens do retorno invalida.' using errcode = '22023';
  end if;
  for v_json in select value from jsonb_array_elements(coalesce(p_itens, '[]'::jsonb)) loop
    if not exists (
      select 1 from public.aluguel_item
       where id = nullif(v_json->>'id', '')::bigint and aluguel_id = p_id
    ) then
      raise exception 'Item % nao pertence a este aluguel.', v_json->>'id' using errcode = 'P0002';
    end if;
    v_retornos := v_retornos || jsonb_build_object(v_json->>'id', v_json->'quantidade_devolvida');
  end loop;

  for v_linha in select * from public.aluguel_item where aluguel_id = p_id order by id for update loop
    v_voltou := coalesce(nullif(v_retornos->>(v_linha.id::text), '')::integer, v_linha.quantidade);
    if v_voltou < 0 or v_voltou > v_linha.quantidade then
      raise exception 'Retorno de "%": informe de 0 a %.', v_linha.descricao, v_linha.quantidade
        using errcode = '22023';
    end if;

    perform public.aluguel_devolver_item(v_linha.id, 'Retorno do aluguel #' || p_id, p_usuario);
    perform public.aluguel_reter_falta(v_linha.id, v_linha.quantidade - v_voltou, p_usuario);
    update public.aluguel_item set quantidade_devolvida = v_voltou where id = v_linha.id;

    v_devolvidos := v_devolvidos + 1;
    if v_voltou < v_linha.quantidade then
      v_nao_retornados := v_nao_retornados || ((v_linha.quantidade - v_voltou) || 'x ' || v_linha.descricao);
    end if;
  end loop;

  update public.aluguel
     set status = 'ENCERRADO',
         encerrado_em = v_retorno,
         encerrado_por = p_usuario,
         observacao_encerramento = nullif(btrim(coalesce(p_observacao, '')), ''),
         updated_by = p_usuario
   where id = p_id;

  insert into public.aluguel_evento (aluguel_id, tipo, dados, usuario_id)
  values (p_id, 'ENCERRADO', jsonb_build_object(
    'status_anterior', v_atual.status,
    'encerrado_em', v_retorno,
    'itens_devolvidos', v_devolvidos,
    'nao_retornados', to_jsonb(v_nao_retornados),
    'observacao', nullif(btrim(coalesce(p_observacao, '')), '')
  ), p_usuario);
end;
$$;


--
-- Name: aluguel_excluir(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_excluir(p_id bigint, p_motivo text, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_atual public.aluguel%rowtype;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_linha record;
begin
  if v_motivo is null then
    raise exception 'Informe o motivo da exclusao.' using errcode = '22023';
  end if;
  select * into v_atual from public.aluguel where id = p_id and not is_deleted for update;
  if not found then raise exception 'Aluguel nao encontrado.' using errcode = 'P0002'; end if;

  for v_linha in select id from public.aluguel_item where aluguel_id = p_id order by id loop
    perform public.aluguel_devolver_item(v_linha.id, 'Aluguel #' || p_id || ' excluido: ' || v_motivo, p_usuario);
  end loop;

  update public.aluguel
     set is_deleted = true,
         deleted_at = now(),
         deleted_by = p_usuario,
         motivo_exclusao = v_motivo,
         updated_by = p_usuario
   where id = p_id;

  insert into public.aluguel_evento (aluguel_id, tipo, dados, usuario_id)
  values (p_id, 'EXCLUIDO', jsonb_build_object('status_anterior', v_atual.status, 'motivo', v_motivo), p_usuario);
end;
$$;


--
-- Name: aluguel_hoje(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_hoje() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select (now() at time zone 'America/Fortaleza')::date;
$$;


--
-- Name: aluguel_pausar(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_pausar(p_id bigint, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_atual public.aluguel%rowtype;
begin
  select * into v_atual from public.aluguel where id = p_id and not is_deleted for update;
  if not found then raise exception 'Aluguel nao encontrado.' using errcode = 'P0002'; end if;
  if v_atual.status <> 'ATIVO' then
    raise exception 'So um aluguel ativo pode ser pausado.' using errcode = '22023';
  end if;

  update public.aluguel
     set status = 'PAUSADO', pausado_em = now(), updated_by = p_usuario
   where id = p_id;

  insert into public.aluguel_evento (aluguel_id, tipo, dados, usuario_id)
  values (p_id, 'PAUSADO', jsonb_build_object(
    'dias_restantes', v_atual.data_limite - public.aluguel_hoje()
  ), p_usuario);
end;
$$;


--
-- Name: aluguel_reiniciar(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_reiniciar(p_id bigint, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_atual public.aluguel%rowtype;
  v_hoje date := public.aluguel_hoje();
  v_duracao integer;
begin
  select * into v_atual from public.aluguel where id = p_id and not is_deleted for update;
  if not found then raise exception 'Aluguel nao encontrado.' using errcode = 'P0002'; end if;
  if v_atual.status not in ('ATIVO', 'PAUSADO') then
    raise exception 'Aluguel encerrado nao pode ser reiniciado.' using errcode = '22023';
  end if;

  v_duracao := v_atual.data_limite - v_atual.data_inicio;

  update public.aluguel
     set status = 'ATIVO',
         pausado_em = null,
         data_inicio = v_hoje,
         data_limite = v_hoje + v_duracao,
         updated_by = p_usuario
   where id = p_id;

  insert into public.aluguel_evento (aluguel_id, tipo, dados, usuario_id)
  values (p_id, 'REINICIADO', jsonb_build_object(
    'status_anterior', v_atual.status,
    'antes', jsonb_build_object('data_inicio', v_atual.data_inicio, 'data_limite', v_atual.data_limite),
    'depois', jsonb_build_object('data_inicio', v_hoje, 'data_limite', v_hoje + v_duracao),
    'duracao_dias', v_duracao
  ), p_usuario);
end;
$$;


--
-- Name: aluguel_reter_falta(bigint, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_reter_falta(p_item_id bigint, p_falta integer, p_usuario uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_item public.aluguel_item%rowtype;
  v_saida jsonb;
  v_saida_id bigint;
  v_rotulo text;
begin
  select * into v_item from public.aluguel_item where id = p_item_id for update;
  if not found then
    raise exception 'Item do aluguel nao encontrado.' using errcode = 'P0002';
  end if;
  if p_falta <= 0 or v_item.tipo not in ('PRODUTO', 'USOCONSUMO', 'GERAL') then
    return;
  end if;

  v_rotulo := 'Aluguel #' || v_item.aluguel_id || ' - nao retornou';

  if v_item.tipo = 'PRODUTO' then
    v_saida := public.registrar_saida_estoque(v_item.produto_id, p_falta, 'ALUGUEL', v_rotulo, p_usuario);
    v_saida_id := (v_saida->>'saida_id')::bigint;
    update public.estoque_saida set aluguel_id = v_item.aluguel_id where id = v_saida_id;
    update public.aluguel_item set estoque_saida_id = v_saida_id where id = p_item_id;
  else
    v_saida := public.registrar_saida_usoconsumo(
      jsonb_build_object('escopo', v_item.tipo, 'motivo', 'ALUGUEL', 'observacao', v_rotulo, 'created_by', p_usuario),
      jsonb_build_array(jsonb_build_object('item_id', v_item.usoconsumo_item_id, 'quantidade', p_falta))
    );
    v_saida_id := (v_saida->>'saida_id')::bigint;
    update public.usoconsumo_saida set aluguel_id = v_item.aluguel_id where id = v_saida_id;
    update public.aluguel_item set usoconsumo_saida_id = v_saida_id where id = p_item_id;
  end if;
end;
$$;


--
-- Name: aluguel_salvar(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_salvar(p_payload jsonb, p_usuario uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id bigint := nullif(p_payload->>'id', '')::bigint;
  v_atual public.aluguel%rowtype;
  v_inicio date := nullif(p_payload->>'data_inicio', '')::date;
  v_indeterminado boolean := coalesce(nullif(p_payload->>'indeterminado', '')::boolean, false);
  v_limite date := case when coalesce(nullif(p_payload->>'indeterminado', '')::boolean, false)
                        then null else nullif(p_payload->>'data_limite', '')::date end;
  v_cliente_id integer := nullif(p_payload->>'cliente_id', '')::integer;
  v_destinatario uuid := nullif(p_payload->>'usuario_id', '')::uuid;
  v_avulso boolean;
  v_cliente jsonb := coalesce(p_payload->'cliente', '{}'::jsonb);
  v_cliente_nome text;
  v_observacao text := nullif(btrim(coalesce(p_payload->>'observacao', '')), '');
  v_itens jsonb := coalesce(p_payload->'itens', '[]'::jsonb);
  v_json jsonb;
  v_item_id bigint;
  v_existente public.aluguel_item%rowtype;
  v_tipo text;
  v_produto integer;
  v_usoconsumo integer;
  v_veiculo integer;
  v_descricao text;
  v_identificacao text;
  v_quantidade integer;
  v_valor numeric(14,2);
  v_mantidos bigint[] := '{}';
  v_adicionados integer := 0;
  v_removidos integer := 0;
  v_desc_adicionados text[] := '{}';
  v_desc_removidos text[] := '{}';
  v_desc_trocados text[] := '{}';
  v_linha record;
  v_conflito bigint;
begin
  if v_inicio is null then
    raise exception 'Informe a data de inicio.' using errcode = '22023';
  end if;
  if v_limite is null and not v_indeterminado then
    raise exception 'Informe a data limite ou marque o prazo indeterminado.' using errcode = '22023';
  end if;
  if v_limite < v_inicio then
    raise exception 'A data limite nao pode ser anterior a data de inicio.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_itens) <> 'array' or jsonb_array_length(v_itens) = 0 then
    raise exception 'Adicione ao menos um item ao aluguel.' using errcode = '22023';
  end if;

  -- Destinatario: cliente do cadastro, usuario do sistema ou avulso; so um.
  if v_cliente_id is not null and v_destinatario is not null then
    raise exception 'Escolha um cliente ou um usuario como destinatario, nao os dois.' using errcode = '22023';
  end if;
  v_avulso := v_cliente_id is null and v_destinatario is null;
  if v_avulso then
    v_cliente_nome := nullif(btrim(coalesce(v_cliente->>'nome', '')), '');
    if v_cliente_nome is null then
      raise exception 'Selecione um cliente, um usuario ou informe o nome do cliente avulso.' using errcode = '22023';
    end if;
  elsif v_cliente_id is not null and not exists (select 1 from public.cliente where id = v_cliente_id) then
    raise exception 'Cliente nao encontrado.' using errcode = 'P0002';
  elsif v_destinatario is not null and not exists (select 1 from public.usuario where id = v_destinatario) then
    raise exception 'Usuario nao encontrado.' using errcode = 'P0002';
  end if;

  if v_id is null then
    insert into public.aluguel (
      status, data_inicio, data_limite, cliente_id, usuario_id,
      cliente_nome, cliente_documento, cliente_telefone, cliente_email,
      observacao, created_by, updated_by
    ) values (
      'ATIVO', v_inicio, v_limite, v_cliente_id, v_destinatario,
      case when v_avulso then v_cliente_nome end,
      case when v_avulso then nullif(upper(regexp_replace(coalesce(v_cliente->>'documento', ''), '[^0-9A-Za-z]', '', 'g')), '') end,
      case when v_avulso then nullif(btrim(coalesce(v_cliente->>'telefone', '')), '') end,
      case when v_avulso then nullif(btrim(coalesce(v_cliente->>'email', '')), '') end,
      v_observacao, p_usuario, p_usuario
    )
    returning id into v_id;
  else
    select * into v_atual from public.aluguel where id = v_id and not is_deleted for update;
    if not found then
      raise exception 'Aluguel nao encontrado.' using errcode = 'P0002';
    end if;
    if v_atual.status = 'ENCERRADO' then
      raise exception 'Aluguel encerrado nao pode ser editado.' using errcode = '22023';
    end if;

    update public.aluguel
       set data_inicio = v_inicio,
           data_limite = v_limite,
           cliente_id = v_cliente_id,
           usuario_id = v_destinatario,
           cliente_nome = case when v_avulso then v_cliente_nome end,
           cliente_documento = case when v_avulso then nullif(upper(regexp_replace(coalesce(v_cliente->>'documento', ''), '[^0-9A-Za-z]', '', 'g')), '') end,
           cliente_telefone = case when v_avulso then nullif(btrim(coalesce(v_cliente->>'telefone', '')), '') end,
           cliente_email = case when v_avulso then nullif(btrim(coalesce(v_cliente->>'email', '')), '') end,
           observacao = v_observacao,
           updated_by = p_usuario
     where id = v_id;

    -- Itens que sairam do payload: devolve e apaga. A descricao fica no evento.
    for v_linha in
      select ai.id, ai.descricao, ai.quantidade
        from public.aluguel_item ai
       where ai.aluguel_id = v_id
         and ai.id not in (
           select nullif(x->>'id', '')::bigint
             from jsonb_array_elements(v_itens) x
            where nullif(x->>'id', '') is not null
         )
       order by ai.id
    loop
      perform public.aluguel_devolver_item(v_linha.id, 'Item retirado do aluguel #' || v_id, p_usuario);
      delete from public.aluguel_item where id = v_linha.id;
      v_removidos := v_removidos + 1;
      v_desc_removidos := v_desc_removidos || (v_linha.quantidade || 'x ' || v_linha.descricao);
    end loop;
  end if;

  for v_json in select value from jsonb_array_elements(v_itens) loop
    v_tipo := upper(btrim(coalesce(v_json->>'tipo', '')));
    v_produto := null; v_usoconsumo := null; v_veiculo := null;
    v_quantidade := coalesce(nullif(v_json->>'quantidade', '')::integer, 1);
    v_valor := coalesce(nullif(v_json->>'valor', '')::numeric, 0);
    v_descricao := nullif(btrim(coalesce(v_json->>'descricao', '')), '');
    v_identificacao := nullif(btrim(coalesce(v_json->>'identificacao', '')), '');

    if v_quantidade <= 0 then
      raise exception 'A quantidade deve ser maior que zero.' using errcode = '22023';
    end if;
    if v_valor < 0 then
      raise exception 'O valor do item nao pode ser negativo.' using errcode = '22023';
    end if;

    if v_tipo = 'PRODUTO' then
      v_produto := nullif(v_json->>'produto_id', '')::integer;
      select coalesce(v_descricao, p.titulo) into v_descricao from public.produto p where p.id = v_produto;
      if not found then raise exception 'Produto nao encontrado.' using errcode = 'P0002'; end if;
    elsif v_tipo in ('USOCONSUMO', 'GERAL') then
      v_usoconsumo := nullif(v_json->>'usoconsumo_item_id', '')::integer;
      select coalesce(v_descricao, i.titulo) into v_descricao
        from public.usoconsumo_item i where i.id = v_usoconsumo and i.escopo = v_tipo;
      if not found then raise exception 'Item nao encontrado neste estoque.' using errcode = 'P0002'; end if;
    elsif v_tipo = 'VEICULO' then
      v_veiculo := nullif(v_json->>'veiculo_id', '')::integer;
      v_quantidade := 1;
      select coalesce(v_descricao, nullif(btrim(concat_ws(' ', v.marca, v.modelo)), ''), 'Veiculo'),
             coalesce(v_identificacao, v.placa)
        into v_descricao, v_identificacao
        from public.veiculo v where v.id = v_veiculo
        for update;
      if not found then raise exception 'Veiculo nao encontrado.' using errcode = 'P0002'; end if;

      select a.id into v_conflito
        from public.aluguel_item ai
        join public.aluguel a on a.id = ai.aluguel_id
       where ai.veiculo_id = v_veiculo
         and a.id <> v_id
         and a.status <> 'ENCERRADO'
         and not a.is_deleted
       limit 1;
      if v_conflito is not null then
        raise exception 'Este veiculo ja esta no aluguel #%, que nao foi encerrado.', v_conflito using errcode = '23505';
      end if;
    elsif v_tipo = 'AVULSO' then
      if v_descricao is null then
        raise exception 'Informe a descricao do item avulso.' using errcode = '22023';
      end if;
    else
      raise exception 'Tipo de item invalido: %.', v_tipo using errcode = '22023';
    end if;

    v_item_id := nullif(v_json->>'id', '')::bigint;

    if v_item_id is not null then
      select * into v_existente from public.aluguel_item where id = v_item_id and aluguel_id = v_id for update;
      if not found then
        raise exception 'Item % nao pertence a este aluguel.', v_item_id using errcode = 'P0002';
      end if;

      if v_existente.tipo is distinct from v_tipo
         or v_existente.produto_id is distinct from v_produto
         or v_existente.usoconsumo_item_id is distinct from v_usoconsumo
         or v_existente.veiculo_id is distinct from v_veiculo
         or v_existente.quantidade is distinct from v_quantidade then
        -- Troca de bem ou de quantidade: devolve o que saiu e baixa de novo.
        perform public.aluguel_devolver_item(v_item_id, 'Item alterado no aluguel #' || v_id, p_usuario);
        update public.aluguel_item
           set tipo = v_tipo, produto_id = v_produto, usoconsumo_item_id = v_usoconsumo,
               veiculo_id = v_veiculo, quantidade = v_quantidade, valor = v_valor,
               descricao = v_descricao, identificacao = v_identificacao,
               estoque_saida_id = null, usoconsumo_saida_id = null, devolvido_em = null
         where id = v_item_id;
        perform public.aluguel_baixar_item(v_item_id, p_usuario);
        v_desc_trocados := v_desc_trocados || (
          v_existente.quantidade || 'x ' || v_existente.descricao || ' -> ' || v_quantidade || 'x ' || v_descricao
        );
      else
        update public.aluguel_item
           set valor = v_valor, descricao = v_descricao, identificacao = v_identificacao
         where id = v_item_id;
      end if;
      v_mantidos := v_mantidos || v_item_id;
    else
      insert into public.aluguel_item (
        aluguel_id, tipo, produto_id, usoconsumo_item_id, veiculo_id,
        descricao, identificacao, quantidade, valor
      ) values (
        v_id, v_tipo, v_produto, v_usoconsumo, v_veiculo,
        v_descricao, v_identificacao, v_quantidade, v_valor
      )
      returning id into v_item_id;
      perform public.aluguel_baixar_item(v_item_id, p_usuario);
      v_mantidos := v_mantidos || v_item_id;
      v_adicionados := v_adicionados + 1;
      v_desc_adicionados := v_desc_adicionados || (v_quantidade || 'x ' || v_descricao);
    end if;
  end loop;

  update public.aluguel
     set valor_total = coalesce((
           select sum(ai.valor * ai.quantidade) from public.aluguel_item ai where ai.aluguel_id = v_id
         ), 0)
   where id = v_id;

  if v_atual.id is null then
    insert into public.aluguel_evento (aluguel_id, tipo, dados, usuario_id)
    values (v_id, 'CRIADO', jsonb_build_object(
      'data_inicio', v_inicio, 'data_limite', v_limite, 'itens', jsonb_array_length(v_itens)
    ), p_usuario);
  else
    insert into public.aluguel_evento (aluguel_id, tipo, dados, usuario_id)
    values (v_id, 'EDITADO', jsonb_build_object(
      'antes', jsonb_build_object('data_inicio', v_atual.data_inicio, 'data_limite', v_atual.data_limite),
      'depois', jsonb_build_object('data_inicio', v_inicio, 'data_limite', v_limite),
      'itens_adicionados', v_adicionados,
      'itens_removidos', v_removidos,
      'descricao_adicionados', to_jsonb(v_desc_adicionados),
      'descricao_removidos', to_jsonb(v_desc_removidos),
      'descricao_trocados', to_jsonb(v_desc_trocados)
    ), p_usuario);
  end if;

  return v_id;
end;
$$;


--
-- Name: aluguel_salvar_checklist(bigint, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aluguel_salvar_checklist(p_aluguel_id bigint, p_tipo text, p_payload jsonb, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tipo text := upper(btrim(coalesce(p_tipo, '')));
  v_itens jsonb := coalesce(p_payload->'itens', '[]'::jsonb);
  v_status_aluguel text;
  v_checklist_id bigint;
  v_json jsonb;
  v_titulo text;
  v_status text;
  v_ordem integer := 0;
  v_existente bigint;
begin
  if v_tipo not in ('SAIDA', 'RETORNO') then
    raise exception 'Tipo de checklist invalido: %.', p_tipo using errcode = '22023';
  end if;
  if jsonb_typeof(v_itens) <> 'array' or jsonb_array_length(v_itens) = 0 then
    raise exception 'O checklist precisa de ao menos um item.' using errcode = '22023';
  end if;
  select status into v_status_aluguel from public.aluguel where id = p_aluguel_id and not is_deleted for update;
  if not found then raise exception 'Aluguel nao encontrado.' using errcode = 'P0002'; end if;
  if v_tipo = 'SAIDA' and v_status_aluguel = 'ENCERRADO' then
    raise exception 'O checklist de saida nao muda depois do encerramento.' using errcode = '22023';
  end if;
  if v_tipo = 'RETORNO' and v_status_aluguel <> 'ENCERRADO' then
    raise exception 'O checklist de retorno fica disponivel depois do encerramento do aluguel.' using errcode = '22023';
  end if;

  insert into public.aluguel_checklist (aluguel_id, tipo, checklist_modelo_id, observacao, realizado_em, realizado_por)
  values (
    p_aluguel_id, v_tipo, nullif(p_payload->>'modelo_id', '')::integer,
    nullif(btrim(coalesce(p_payload->>'observacao', '')), ''), now(), p_usuario
  )
  on conflict (aluguel_id, tipo) do update
    set checklist_modelo_id = excluded.checklist_modelo_id,
        observacao = excluded.observacao,
        realizado_em = now(),
        realizado_por = excluded.realizado_por
  returning id into v_checklist_id;

  delete from public.aluguel_checklist_item
   where checklist_id = v_checklist_id
     and btrim(titulo) not in (
       select btrim(coalesce(x->>'titulo', '')) from jsonb_array_elements(v_itens) x
     );

  for v_json in select value from jsonb_array_elements(v_itens) loop
    v_titulo := nullif(btrim(coalesce(v_json->>'titulo', '')), '');
    if v_titulo is null then
      raise exception 'Item do checklist sem titulo.' using errcode = '22023';
    end if;
    v_status := nullif(upper(btrim(coalesce(v_json->>'status', ''))), '');
    v_ordem := coalesce(nullif(v_json->>'ordem', '')::integer, v_ordem + 1);

    select id into v_existente from public.aluguel_checklist_item
     where checklist_id = v_checklist_id and btrim(titulo) = v_titulo
     order by id limit 1;

    if v_existente is null then
      insert into public.aluguel_checklist_item (checklist_id, modelo_item_id, titulo, descricao, status, observacao, ordem)
      values (
        v_checklist_id, nullif(v_json->>'modelo_item_id', '')::integer, v_titulo,
        nullif(btrim(coalesce(v_json->>'descricao', '')), ''), v_status,
        nullif(btrim(coalesce(v_json->>'observacao', '')), ''), v_ordem
      );
    else
      update public.aluguel_checklist_item
         set modelo_item_id = nullif(v_json->>'modelo_item_id', '')::integer,
             descricao = nullif(btrim(coalesce(v_json->>'descricao', '')), ''),
             status = v_status,
             observacao = nullif(btrim(coalesce(v_json->>'observacao', '')), ''),
             ordem = v_ordem
       where id = v_existente;
    end if;
  end loop;

  insert into public.aluguel_evento (aluguel_id, tipo, dados, usuario_id)
  values (p_aluguel_id, 'CHECKLIST_' || v_tipo, jsonb_build_object(
    'itens', jsonb_array_length(v_itens),
    'alertas', (select count(*) from public.aluguel_checklist_item where checklist_id = v_checklist_id and status = 'ALERTA'),
    'falhas', (select count(*) from public.aluguel_checklist_item where checklist_id = v_checklist_id and status = 'FALHA')
  ), p_usuario);

  return jsonb_build_object(
    'checklist_id', v_checklist_id,
    'itens', coalesce((
      select jsonb_agg(jsonb_build_object('id', i.id, 'titulo', i.titulo) order by i.ordem, i.id)
        from public.aluguel_checklist_item i where i.checklist_id = v_checklist_id
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: aprovar_orcamento_venda(integer, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aprovar_orcamento_venda(p_venda_id integer, p_dados jsonb DEFAULT NULL::jsonb, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda public.venda%ROWTYPE;
BEGIN
  SELECT * INTO v_venda
    FROM public.venda
   WHERE id = p_venda_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_venda.status::text = 'ORCAMENTO_APROVADO' THEN
    RETURN jsonb_build_object(
      'vendaId', p_venda_id,
      'status', 'ORCAMENTO_APROVADO',
      'statusaprovacao', 'APROVADA'
    );
  END IF;
  IF v_venda.status::text NOT IN ('ORCAMENTO', 'APROVACAO_ORCAMENTO') THEN
    RAISE EXCEPTION 'Este orçamento não pode ser aprovado no status atual.' USING ERRCODE = '22023';
  END IF;

  PERFORM public.invalidar_aprovacoes_venda(p_venda_id, 'APROVACAO_INTERNA');

  UPDATE public.venda
     SET status = 'ORCAMENTO_APROVADO',
         statusaprovacao = 'APROVADA',
         forma_pagamento = CASE
           WHEN p_dados ? 'formaPagamento' THEN nullif(p_dados->>'formaPagamento', '')
           ELSE forma_pagamento END,
         pagamentos_previstos = CASE
           WHEN p_dados ? 'pagamentosPrevistos' THEN nullif(p_dados->'pagamentosPrevistos', 'null'::jsonb)
           ELSE pagamentos_previstos END,
         parcelas_pagamento = CASE
           WHEN p_dados ? 'parcelasPagamento' THEN nullif(p_dados->>'parcelasPagamento', '')::integer
           ELSE parcelas_pagamento END,
         descricao = CASE
           WHEN p_dados ? 'descricao' THEN nullif(btrim(p_dados->>'descricao'), '')
           ELSE descricao END,
         observacoes = CASE
           WHEN p_dados ? 'observacoes' THEN nullif(btrim(p_dados->>'observacoes'), '')
           ELSE observacoes END,
         descricao_financeiro = CASE
           WHEN p_dados ? 'descricaoFinanceiro' THEN nullif(btrim(p_dados->>'descricaoFinanceiro'), '')
           ELSE descricao_financeiro END,
         observacoes_fiscais = CASE
           WHEN p_dados ? 'observacoesFiscais' THEN nullif(btrim(p_dados->>'observacoesFiscais'), '')
           ELSE observacoes_fiscais END,
         garantia = CASE
           WHEN p_dados ? 'garantia' THEN nullif(btrim(p_dados->>'garantia'), '')
           ELSE garantia END,
         updated_by = coalesce(p_usuario_id, updated_by),
         updatedat = now()
   WHERE id = p_venda_id;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'ORCAMENTO_APROVADO',
    'statusaprovacao', 'APROVADA'
  );
END;
$$;


--
-- Name: assinar_checklist_remotamente(uuid, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assinar_checklist_remotamente(p_convite_public_id uuid, p_snapshot_hash text, p_signatario_nome text, p_signatario_documento text, p_signatario_qualidade text, p_qualidade_outro text, p_declaracao text, p_declaracao_hash text, p_assinatura_path text, p_assinatura_hash text, p_assinatura_vinculo_hash text, p_request_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS TABLE(assinatura_id bigint, documento_id bigint, assinado_em timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  convite public.checklist_documento_convite_assinatura%rowtype;
  doc public.checklist_documento%rowtype;
  nova_assinatura public.checklist_documento_assinatura%rowtype;
  v_documento_id bigint;
begin
  select convite_base.documento_id into v_documento_id
  from public.checklist_documento_convite_assinatura convite_base
  where convite_base.public_id = p_convite_public_id;
  if not found then
    raise exception 'Convite invalido ou indisponivel.' using errcode = 'P0002';
  end if;

  select documento.* into doc
  from public.checklist_documento documento
  where documento.id = v_documento_id
  for update;

  select convite_registro.* into convite
  from public.checklist_documento_convite_assinatura convite_registro
  where convite_registro.public_id = p_convite_public_id
    and convite_registro.documento_id = doc.id
  for update;
  if not found then
    raise exception 'Convite invalido ou indisponivel.' using errcode = 'P0002';
  end if;

  if convite.revogado_em is not null
    or convite.consumido_em is not null
    or convite.expira_em <= now() then
    raise exception 'Convite invalido ou indisponivel.' using errcode = '55000';
  end if;
  if p_snapshot_hash is distinct from doc.snapshot_hash then
    raise exception 'O snapshot do checklist foi alterado.' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.checklist_documento posterior
    where posterior.ordemservico_id = doc.ordemservico_id
      and posterior.tipo = doc.tipo
      and posterior.versao > doc.versao
  ) then
    raise exception 'Existe uma versao posterior deste checklist.' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.checklist_documento_assinatura assinatura
    where assinatura.documento_id = doc.id
  ) then
    raise exception 'Esta versao ja foi assinada.' using errcode = '23505';
  end if;

  insert into public.checklist_documento_assinatura (
    documento_id,
    signatario_nome,
    signatario_documento,
    signatario_qualidade,
    qualidade_outro,
    declaracao,
    declaracao_hash,
    metodo,
    assinatura_path,
    assinatura_hash,
    assinatura_vinculo_hash,
    snapshot_hash,
    operador_usuario_id,
    request_ip,
    user_agent,
    assinado_em,
    convite_assinatura_id
  ) values (
    doc.id,
    p_signatario_nome,
    p_signatario_documento,
    p_signatario_qualidade,
    p_qualidade_outro,
    p_declaracao,
    p_declaracao_hash,
    'REMOTA_DESENHADA',
    p_assinatura_path,
    p_assinatura_hash,
    p_assinatura_vinculo_hash,
    doc.snapshot_hash,
    null,
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    now(),
    convite.id
  ) returning * into nova_assinatura;

  update public.checklist_documento_convite_assinatura convite_registro
     set consumido_em = nova_assinatura.assinado_em,
         ultimo_acesso_em = coalesce(convite_registro.ultimo_acesso_em, nova_assinatura.assinado_em)
   where convite_registro.id = convite.id;

  insert into public.checklist_documento_evento (
    documento_id, tipo, request_ip, user_agent, metadados
  ) values (
    doc.id,
    'ASSINATURA_REMOTA_REGISTRADA',
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    jsonb_build_object(
      'convitePublicId', convite.public_id,
      'metodo', 'REMOTA_DESENHADA',
      'autenticacao', 'LINK_CPF_SENHA',
      'assinaturaHash', p_assinatura_hash,
      'assinaturaVinculoHash', p_assinatura_vinculo_hash
    )
  );

  assinatura_id := nova_assinatura.id;
  documento_id := doc.id;
  assinado_em := nova_assinatura.assinado_em;
  return next;
end;
$$;


--
-- Name: atualizar_permissoes_perfil_auditado(integer, integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.atualizar_permissoes_perfil_auditado(p_perfilid integer, p_permissoes_ids integer[], p_usuario_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_usuario_id is not null and not exists (select 1 from public.usuario where id = p_usuario_id) then
    raise exception 'Usuario responsavel invalido';
  end if;

  if p_usuario_id is not null then
    perform set_config('app.audit_user_id', p_usuario_id::text, true);
  end if;

  delete from public.perfilpermissao pp
  where pp.perfilid = p_perfilid
    and not (pp.permissaoid = any(coalesce(p_permissoes_ids, '{}'::integer[])));

  insert into public.perfilpermissao (perfilid, permissaoid, created_by, updated_by)
  select p_perfilid, permissaoid, p_usuario_id, p_usuario_id
  from unnest(coalesce(p_permissoes_ids, '{}'::integer[])) as permissaoid
  on conflict (perfilid, permissaoid) do nothing;
end;
$$;


--
-- Name: atualizar_totais_nfe(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.atualizar_totais_nfe(p_nfe_id bigint) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  UPDATE public.nfe
  SET
    total_produtos = coalesce((
      SELECT sum(ni.valor_total) FROM public.nfe_item ni WHERE ni.nfe_id = nfe.id
    ), 0),
    valor_frete = coalesce((
      SELECT sum(ni.valor_frete) FROM public.nfe_item ni WHERE ni.nfe_id = nfe.id
    ), 0),
    valor_desconto = coalesce((
      SELECT sum(ni.valor_desconto) FROM public.nfe_item ni WHERE ni.nfe_id = nfe.id
    ), 0),
    total_nfe = coalesce((
      SELECT sum(ni.valor_total - ni.valor_desconto + ni.valor_frete)
        FROM public.nfe_item ni WHERE ni.nfe_id = nfe.id
    ), 0),
    updatedat = now()
  WHERE id = p_nfe_id;
$$;


--
-- Name: auditoria_contexto_externo_requisicao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auditoria_contexto_externo_requisicao() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  claims_raw text := nullif(current_setting('request.jwt.claims', true), '');
  headers_raw text := nullif(current_setting('request.headers', true), '');
  headers_json jsonb;
  tipo text;
  nome text;
begin
  if claims_raw is null or headers_raw is null then
    return null;
  end if;
  if claims_raw::jsonb ->> 'role' <> 'service_role' then
    return null;
  end if;

  headers_json := headers_raw::jsonb;
  tipo := lower(coalesce(headers_json ->> 'x-audit-actor-type', ''));
  if tipo <> 'cliente' then
    return null;
  end if;

  nome := left(nullif(btrim(headers_json ->> 'x-audit-actor-name'), ''), 120);
  return jsonb_build_object(
    'origem', tipo,
    'nome', coalesce(nome, 'Cliente via link de aprovacao')
  );
exception when others then
  return null;
end;
$$;


--
-- Name: FUNCTION auditoria_contexto_externo_requisicao(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auditoria_contexto_externo_requisicao() IS 'Identifica atores externos confiaveis propagados por uma chamada service_role.';


--
-- Name: auditoria_json_seguro(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auditoria_json_seguro(valor jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  resultado jsonb;
begin
  if valor is null then
    return null;
  end if;

  if jsonb_typeof(valor) = 'object' then
    select coalesce(
      jsonb_object_agg(
        chave,
        case
          when lower(chave) ~ '(senha|password|secret|token|certificado|private.?key|access.?key|refresh.?key|authorization)'
            then '"[PROTEGIDO]"'::jsonb
          else public.auditoria_json_seguro(item)
        end
      ),
      '{}'::jsonb
    )
    into resultado
    from jsonb_each(valor) as entrada(chave, item);
    return resultado;
  end if;

  if jsonb_typeof(valor) = 'array' then
    select coalesce(jsonb_agg(public.auditoria_json_seguro(item)), '[]'::jsonb)
      into resultado
    from jsonb_array_elements(valor) as entrada(item);
    return resultado;
  end if;

  return valor;
end;
$$;


--
-- Name: auditoria_modulo_tabela(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auditoria_modulo_tabela(nome_tabela text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when nome_tabela ~* '^(mercadolivre|marketplace)' then 'marketplace'
    when nome_tabela ~* '^desmanche' then 'desmanche'
    when nome_tabela ~* '^(agendamento)' then 'agendamentos'
    when nome_tabela ~* '^aluguel' then 'alugueis'
    when nome_tabela ~* '^(ordemservico|os|checklist|imagemvistoria)' then 'ordens'
    when nome_tabela ~* '^(venda|categoria_venda)' then 'vendas'
    when nome_tabela ~* '^(produto|fornecedor|peca|unidademedida|produtogrupo)' then 'estoque'
    when nome_tabela ~* '^(pagamento|transacao|bancoconta|categoriatransacao)' then 'financeiro'
    when nome_tabela ~* '^(nfe|nfse|notafiscal|fiscal)' then 'fiscal'
    when nome_tabela ~* '^(veiculo|transferencias_veiculos|cores_veiculos)' then 'veiculos'
    when nome_tabela ~* '^cliente' then 'clientes'
    when nome_tabela ~* '^(usuario|perfil|permissao|perfilpermissao|setor)' then 'usuarios'
    when nome_tabela ~* '^(config|empresa|categoriaservico|tiposervico|servico|documento_modelo)' then 'configuracoes'
    else 'outros'
  end;
$$;


--
-- Name: auditoria_try_uuid(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auditoria_try_uuid(valor text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    AS $$
begin
  if valor is null or btrim(valor) = '' then
    return null;
  end if;
  return valor::uuid;
exception when invalid_text_representation then
  return null;
end;
$$;


--
-- Name: auditoria_usuario_requisicao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auditoria_usuario_requisicao() RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  claims_raw text := nullif(current_setting('request.jwt.claims', true), '');
  headers_raw text := nullif(current_setting('request.headers', true), '');
  role_requisicao text;
begin
  if claims_raw is null or headers_raw is null then
    return null;
  end if;

  role_requisicao := claims_raw::jsonb ->> 'role';
  if role_requisicao <> 'service_role' then
    return null;
  end if;

  return public.auditoria_try_uuid(headers_raw::jsonb ->> 'x-audit-user-id');
exception when others then
  return null;
end;
$$;


--
-- Name: FUNCTION auditoria_usuario_requisicao(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.auditoria_usuario_requisicao() IS 'Retorna o usuario da sessao da aplicacao propagado por uma chamada service_role.';


--
-- Name: auth_login_rate_limit_check(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_login_rate_limit_check(p_keys text[]) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    ceil(max(extract(epoch from (blocked_until - clock_timestamp()))))::integer,
    0
  )
  from public.auth_login_rate_limit
  where key_hash = any(coalesce(p_keys, array[]::text[]))
    and blocked_until > clock_timestamp();
$$;


--
-- Name: auth_login_rate_limit_clear(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_login_rate_limit_clear(p_keys text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  delete from public.auth_login_rate_limit
  where key_hash = any(coalesce(p_keys, array[]::text[]));
$$;


--
-- Name: auth_login_rate_limit_register_failure(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auth_login_rate_limit_register_failure(p_keys text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_key text;
  v_row public.auth_login_rate_limit%rowtype;
  v_now timestamptz := clock_timestamp();
  v_retry integer := 0;
  v_current_retry integer;
  v_limit integer;
  v_window interval;
  v_block_duration interval;
begin
  foreach v_key in array coalesce(p_keys, array[]::text[]) loop
    if v_key is null or length(v_key) < 4 or length(v_key) > 80 then
      continue;
    end if;

    if v_key like 'identifier:%' then
      v_limit := 5;
      v_window := interval '15 minutes';
      v_block_duration := interval '15 minutes';
    elsif v_key like 'ip:%' then
      v_limit := 30;
      v_window := interval '15 minutes';
      v_block_duration := interval '15 minutes';
    elsif v_key like 'login-global:%' then
      v_limit := 100;
      v_window := interval '5 minutes';
      v_block_duration := interval '5 minutes';
    else
      -- Mantém o contrato dos fluxos públicos que já usam estas funções.
      v_limit := 5;
      v_window := interval '15 minutes';
      v_block_duration := interval '15 minutes';
    end if;

    insert into public.auth_login_rate_limit (key_hash)
    values (v_key)
    on conflict (key_hash) do nothing;

    select * into v_row
    from public.auth_login_rate_limit
    where key_hash = v_key
    for update;

    if v_row.window_started_at <= v_now - v_window then
      v_row.failed_count := 0;
      v_row.window_started_at := v_now;
      v_row.blocked_until := null;
    end if;

    v_row.failed_count := v_row.failed_count + 1;

    if v_row.failed_count >= v_limit then
      v_row.blocked_until := v_now + v_block_duration;
    end if;

    update public.auth_login_rate_limit
    set failed_count = v_row.failed_count,
        window_started_at = v_row.window_started_at,
        blocked_until = v_row.blocked_until,
        updated_at = v_now
    where key_hash = v_key;

    if v_row.blocked_until > v_now then
      v_current_retry := ceil(extract(epoch from (v_row.blocked_until - v_now)))::integer;
      v_retry := greatest(v_retry, v_current_retry);
    end if;
  end loop;

  -- Limpeza oportunista e indexada: evita crescimento permanente sem exigir
  -- pg_cron em todos os bancos dos clientes.
  if random() < 0.01 then
    delete from public.auth_login_rate_limit
    where updated_at < v_now - interval '7 days';
  end if;

  return v_retry;
end;
$$;


--
-- Name: avancar_venda_aprovada_pagamento(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.avancar_venda_aprovada_pagamento(p_venda_id integer, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda public.venda%ROWTYPE;
BEGIN
  SELECT * INTO v_venda
    FROM public.venda
   WHERE id = p_venda_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_venda.status::text IN ('PAGAMENTO', 'PAGO', 'FINALIZADA') THEN
    RETURN jsonb_build_object(
      'vendaId', p_venda_id,
      'status', v_venda.status::text,
      'statusaprovacao', v_venda.statusaprovacao::text
    );
  END IF;
  IF v_venda.status::text <> 'ORCAMENTO_APROVADO' THEN
    RAISE EXCEPTION 'Apenas um orçamento aprovado pode avançar para pagamento.'
      USING ERRCODE = '22023';
  END IF;

  PERFORM public.fn_baixar_estoque_venda(p_venda_id);

  UPDATE public.venda
     SET status = 'PAGAMENTO',
         statusaprovacao = 'APROVADA',
         updated_by = coalesce(p_usuario_id, updated_by),
         updatedat = now()
   WHERE id = p_venda_id;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'PAGAMENTO',
    'statusaprovacao', 'APROVADA'
  );
END;
$$;


--
-- Name: baixar_com_credito_cliente(bigint, timestamp with time zone, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.baixar_com_credito_cliente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_baixado_por uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_atual public.transacao%ROWTYPE;
  v_transacao public.transacao%ROWTYPE;
  v_tipo text;
  v_cliente_id integer;
  v_sentido text;
  v_valor numeric(14,2);
  v_saldo_anterior numeric(14,2);
  v_saldo_resultante numeric(14,2);
  v_movimento_id bigint;
BEGIN
  IF p_transacao_id IS NULL OR p_transacao_id <= 0 THEN
    RAISE EXCEPTION 'Transação inválida.' USING ERRCODE = '22023';
  END IF;
  IF p_pago_em IS NULL THEN
    RAISE EXCEPTION 'Data do pagamento obrigatória.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_atual FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_atual.pendente, false) THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  v_tipo := upper(v_atual.tipo::text);
  IF v_tipo NOT IN ('RECEITA', 'DESPESA') THEN
    RAISE EXCEPTION
      'Crédito do cliente vale para título a receber ou a pagar, não para depósito ou saque.'
      USING ERRCODE = '22023';
  END IF;

  -- As mesmas recusas do abono: são conjuntos que se liquidam juntos, e mexer
  -- numa perna sozinha desmonta a conta do grupo.
  IF v_atual.baixa_de_transacao_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta linha é o dinheiro de uma baixa parcial, não um título.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.adiantamento_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Este título está ligado à antecipação #%. Desfaça a antecipação primeiro.',
      v_atual.adiantamento_id USING ERRCODE = '22023';
  END IF;
  IF coalesce(v_atual.eh_adiantamento, false) THEN
    RAISE EXCEPTION 'Isto é uma antecipação, não uma cobrança avulsa.' USING ERRCODE = '22023';
  END IF;
  IF v_atual.pagamento_multiplo_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta cobrança faz parte do pagamento múltiplo #%. Desfaça o grupo primeiro.',
      v_atual.pagamento_multiplo_id USING ERRCODE = '22023';
  END IF;
  IF v_atual.transferencia_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta linha é uma perna de transferência entre contas.' USING ERRCODE = '22023';
  END IF;
  -- O crédito quita o título inteiro, então um título que já recebeu pagamento
  -- em partes não entra: o resto dele mora nas filhas, e fechá-lo por aqui
  -- deixaria o dinheiro contado duas vezes.
  IF coalesce(v_atual.valor_baixado, 0) > 0 THEN
    RAISE EXCEPTION
      'Este título já foi pago em partes. O crédito do cliente só quita título inteiro.'
      USING ERRCODE = '22023';
  END IF;

  -- ------------------------------------------------------------- de quem é
  IF v_tipo = 'RECEITA' THEN
    v_cliente_id := coalesce(
      v_atual.cliente_id,
      (SELECT os.clienteid FROM public.ordemservico os WHERE os.id = v_atual.ordemservicoid),
      (SELECT vd.clienteid FROM public.venda vd WHERE vd.id = v_atual.vendaid)
    );
  ELSE
    -- Numa despesa o vínculo com OS/venda é do fornecedor, não do cliente: o
    -- único dono possível é o que foi gravado na própria linha.
    v_cliente_id := v_atual.cliente_id;
  END IF;

  IF v_cliente_id IS NULL THEN
    RAISE EXCEPTION
      'Este lançamento não tem cliente vinculado. Informe o cliente nele antes de usar o crédito.'
      USING ERRCODE = '22023';
  END IF;

  v_valor := round(coalesce(nullif(v_atual."valorLiquido", 0), v_atual.valor, 0), 2);
  IF v_valor <= 0 THEN
    RAISE EXCEPTION 'O título não tem valor a baixar.' USING ERRCODE = '22023';
  END IF;

  -- A receber consome a carteira; a pagar abastece.
  v_sentido := CASE WHEN v_tipo = 'RECEITA' THEN 'DEBITO' ELSE 'CREDITO' END;

  SELECT c.saldo_credito INTO v_saldo_anterior
    FROM public.cliente c
   WHERE c.id = v_cliente_id AND c.is_deleted = false
     FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  v_saldo_anterior := coalesce(v_saldo_anterior, 0);
  v_saldo_resultante := CASE
    WHEN v_sentido = 'CREDITO' THEN v_saldo_anterior + v_valor
    ELSE v_saldo_anterior - v_valor
  END;

  IF v_saldo_resultante < 0 THEN
    RAISE EXCEPTION
      'O cliente tem R$ % de crédito e este título é de R$ %.',
      to_char(v_saldo_anterior, 'FM999999990.00'),
      to_char(v_valor, 'FM999999990.00')
      USING ERRCODE = '22023';
  END IF;

  -- ------------------------------------------------------------- a baixa
  UPDATE public.transacao
     SET vencimento_em = coalesce(vencimento_em, data),
         data = p_pago_em,
         pago_em = p_pago_em,
         pendente = false,
         -- Nunca passa por conta: é isto que mantém a linha fora do Fluxo e do
         -- saldo dos bancos, como já acontece no título quitado por antecipação
         -- e no abonado.
         banco_id = NULL,
         metodopagamento = 'CREDITO CLIENTE'::public.metodo_pagamento,
         baixado_por = p_baixado_por,
         plano_de_conta_id = coalesce(p_plano_de_conta_id, plano_de_conta_id),
         centro_custo_id = coalesce(p_centro_custo_id, centro_custo_id),
         updated_at = now()
   WHERE id = p_transacao_id
     AND pendente = true
     AND is_deleted = false
  RETURNING * INTO v_transacao;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.cliente_saldo_movimento (
    cliente_id, sentido, origem, acao, valor,
    saldo_anterior, saldo_resultante, transacao_id, motivo, created_by
  ) VALUES (
    v_cliente_id, v_sentido, 'TRANSACAO', 'REGISTRO', v_valor,
    v_saldo_anterior, round(v_saldo_resultante, 2), v_transacao.id,
    CASE
      WHEN v_sentido = 'DEBITO' THEN 'Baixa do título #' || v_transacao.id
      ELSE 'Crédito gerado pelo título #' || v_transacao.id
    END,
    p_baixado_por
  ) RETURNING id INTO v_movimento_id;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
  ) VALUES (
    v_transacao.id, v_transacao.vencimento_em, v_transacao.pago_em,
    p_baixado_por, NULL, 'CREDITO CLIENTE', 'BAIXA'
  );

  IF v_tipo = 'RECEITA' AND v_transacao.evento_financeiro_id IS NULL THEN
    IF v_transacao.ordemservicoid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
    END IF;
    IF v_transacao.vendaid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pendente', false,
    'cliente_id', v_cliente_id,
    'sentido', v_sentido,
    'valor', v_valor,
    'movimento_id', v_movimento_id,
    'saldo', round(v_saldo_resultante, 2)
  );
END;
$_$;


--
-- Name: FUNCTION baixar_com_credito_cliente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_plano_de_conta_id integer, p_centro_custo_id integer, p_baixado_por uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.baixar_com_credito_cliente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_plano_de_conta_id integer, p_centro_custo_id integer, p_baixado_por uuid) IS 'Quita um título inteiro com o crédito do cliente, sem tocar em banco: a receber consome a carteira (exige saldo), a pagar credita. Grava o movimento no razão do cliente.';


--
-- Name: baixar_por_adiantamento(bigint[], jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.baixar_por_adiantamento(p_ids bigint[], p_adiantamento jsonb, p_baixado_por uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo text;
  v_qtd int;
  v_tipos_distintos int;
  v_soma_liquida numeric(14,2) := 0;
  v_adiantamento_id bigint;
  v_pago_em timestamptz := coalesce(nullif(p_adiantamento->>'pago_em', '')::timestamptz, now());
  v_metodo public.metodo_pagamento;
  v_taxa numeric(14,2);
  v_tipo_taxa integer;
  -- Manter os títulos em aberto, só marcados como antecipados.
  v_manter_pendentes boolean :=
    coalesce((p_adiantamento->>'manter_titulos_pendentes')::boolean, false);
BEGIN
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Selecione ao menos uma transacao.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.transacao
   WHERE id = ANY(p_ids) AND is_deleted = false
   FOR UPDATE;

  SELECT count(*), count(DISTINCT upper(tipo::text)),
         coalesce(sum(coalesce(nullif("valorLiquido", 0), valor)), 0)
    INTO v_qtd, v_tipos_distintos, v_soma_liquida
    FROM public.transacao
   WHERE id = ANY(p_ids) AND is_deleted = false;

  IF v_qtd <> array_length(p_ids, 1) THEN
    RAISE EXCEPTION 'Alguma transacao selecionada nao existe mais.' USING ERRCODE = 'P0002';
  END IF;

  IF v_tipos_distintos > 1 THEN
    RAISE EXCEPTION 'Um adiantamento nao pode misturar receita e despesa.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.transacao
     WHERE id = ANY(p_ids) AND (pendente = false OR is_deleted = true)
  ) THEN
    RAISE EXCEPTION 'Ha transacao ja baixada ou excluida na selecao.' USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.transacao WHERE id = ANY(p_ids) AND adiantamento_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Ha transacao ja vinculada a outro adiantamento.' USING ERRCODE = '23505';
  END IF;

  SELECT upper(tipo::text) INTO v_tipo
    FROM public.transacao WHERE id = p_ids[1];

  BEGIN
    v_metodo := nullif(btrim(p_adiantamento->>'metodopagamento'), '')::public.metodo_pagamento;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Metodo de pagamento invalido: %.', p_adiantamento->>'metodopagamento'
      USING ERRCODE = '22023';
  END;

  IF v_metodo IS NULL THEN
    RAISE EXCEPTION 'Metodo de pagamento obrigatorio.' USING ERRCODE = '22023';
  END IF;
  IF nullif(p_adiantamento->>'banco_id', '') IS NULL THEN
    RAISE EXCEPTION 'Banco obrigatorio no adiantamento.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.transacao (
    descricao, valor, "valorLiquido", valor_base,
    data, competencia_em, vencimento_em, pago_em,
    tipo, pendente, eh_adiantamento, adiantamento_manteve_pendentes,
    banco_id, metodopagamento, categoria_id,
    plano_de_conta_id, centro_custo_id,
    cliente_id, fornecedor_id,
    nomepagador, cpfcnpjpagador,
    descricao_pagamento, created_by, baixado_por
  ) VALUES (
    coalesce(nullif(btrim(p_adiantamento->>'descricao'), ''),
             'Adiantamento de ' || v_qtd || ' titulo(s)'),
    v_soma_liquida, v_soma_liquida, v_soma_liquida,
    v_pago_em, v_pago_em, v_pago_em, v_pago_em,
    v_tipo::public.tipos_transacao, false, true, v_manter_pendentes,
    (p_adiantamento->>'banco_id')::bigint,
    v_metodo,
    nullif(p_adiantamento->>'categoria_id', '')::integer,
    nullif(p_adiantamento->>'plano_de_conta_id', '')::integer,
    nullif(p_adiantamento->>'centro_custo_id', '')::integer,
    nullif(p_adiantamento->>'cliente_id', '')::integer,
    nullif(p_adiantamento->>'fornecedor_id', '')::integer,
    coalesce(nullif(btrim(p_adiantamento->>'nomepagador'), ''), 'Adiantamento'),
    coalesce(nullif(btrim(p_adiantamento->>'cpfcnpjpagador'), ''), 'NÃO INFORMADO'),
    nullif(btrim(p_adiantamento->>'descricao_pagamento'), ''),
    p_baixado_por, p_baixado_por
  ) RETURNING id INTO v_adiantamento_id;

  IF v_manter_pendentes THEN
    -- Só o vínculo. O título continua em aberto para a cobrança acompanhar, e o
    -- banco fica nulo desde já: quando ele for baixado, o dinheiro não é novo —
    -- a menos que o banco tenha debitado de volta, e aí a baixa diz isso.
    UPDATE public.transacao
       SET adiantamento_id = v_adiantamento_id,
           banco_id = NULL,
           updated_at = now()
     WHERE id = ANY(p_ids);
  ELSE
    UPDATE public.transacao
       SET pendente = false,
           pago_em = v_pago_em,
           baixado_por = p_baixado_por,
           vencimento_em = coalesce(vencimento_em, data),
           banco_id = NULL,
           adiantamento_id = v_adiantamento_id,
           updated_at = now()
     WHERE id = ANY(p_ids);

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento
    )
    SELECT id, vencimento_em, pago_em, baixado_por, NULL, metodopagamento
      FROM public.transacao WHERE id = ANY(p_ids);
  END IF;

  v_taxa := round(coalesce(nullif(p_adiantamento->>'taxa', '')::numeric, 0), 2);

  IF v_taxa < 0 THEN
    RAISE EXCEPTION 'A taxa de antecipacao nao pode ser negativa.' USING ERRCODE = '22023';
  END IF;
  IF v_taxa >= v_soma_liquida THEN
    RAISE EXCEPTION
      'A taxa de antecipacao (%) nao pode alcancar o valor antecipado (%).', v_taxa, v_soma_liquida
      USING ERRCODE = '22023';
  END IF;

  IF v_taxa > 0 THEN
    SELECT id INTO v_tipo_taxa
      FROM public.tipos_ajuste_transacao WHERE codigo_sistema = 'TAXA_ANTECIPACAO';

    INSERT INTO public.transacao_ajuste (
      transacao_id, tipo_id, natureza, modo, valor_informado, valor_calculado, created_by
    ) VALUES (
      v_adiantamento_id, v_tipo_taxa, 'DESCONTO', 'FIXO', v_taxa, v_taxa, p_baixado_por
    );
  END IF;

  RETURN jsonb_build_object(
    'adiantamento_id', v_adiantamento_id,
    'quantidade', v_qtd,
    'valor_bruto', v_soma_liquida,
    'taxa', v_taxa,
    'valor_liquido', v_soma_liquida - v_taxa,
    'tipo', v_tipo,
    'titulos_mantidos_pendentes', v_manter_pendentes
  );
END;
$$;


--
-- Name: baixar_transacao_pendente(bigint, timestamp with time zone, bigint, text, integer, integer, uuid, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.baixar_transacao_pendente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_banco_id bigint, p_metodopagamento text, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_baixado_por uuid DEFAULT NULL::uuid, p_valor numeric DEFAULT NULL::numeric, p_valor_lancado numeric DEFAULT NULL::numeric, p_ajustes jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_transacao public.transacao%ROWTYPE;
  v_metodo public.metodo_pagamento;
  v_antecipada boolean;
  v_atual public.transacao%ROWTYPE;
  v_liquido numeric(14,2);
  v_saldo numeric(14,2);
  v_filha_id bigint;
  v_lancado numeric(14,2);
  v_valor numeric(14,2);
  v_item jsonb;
  v_tipo_id integer;
  v_modo text;
  v_natureza text;
  v_informado numeric;
  v_calculado numeric(14,2);
  v_base numeric(14,2);
BEGIN
  IF p_transacao_id IS NULL OR p_transacao_id <= 0 THEN
    RAISE EXCEPTION 'Transação inválida.' USING ERRCODE = '22023';
  END IF;
  IF p_pago_em IS NULL THEN
    RAISE EXCEPTION 'Data do pagamento obrigatória.' USING ERRCODE = '22023';
  END IF;
  IF p_banco_id IS NULL OR p_banco_id <= 0 THEN
    RAISE EXCEPTION 'Banco obrigatório.' USING ERRCODE = '22023';
  END IF;
  IF nullif(btrim(p_metodopagamento), '') IS NULL THEN
    RAISE EXCEPTION 'Método de pagamento obrigatório.' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_metodo := btrim(p_metodopagamento)::public.metodo_pagamento;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Método de pagamento inválido: %.', btrim(p_metodopagamento)
      USING ERRCODE = '22023';
  END;

  SELECT * INTO v_atual FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_atual.pendente, false) THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  /*
   * Os acrescimos e descontos entram AQUI, e a posicao e a regra.
   *
   * O titulo esta travado pelo FOR UPDATE logo acima e ainda esta pendente —
   * que e exatamente o estado que tg_transacao_ajuste_coerente (20260806140000)
   * exige para aceitar ACRESCIMO, porque acrescimo mexe no bruto e bruto de
   * titulo baixado e imutavel (20260806120000).
   *
   * Era essa ordem — lancar o juros, salvar, so entao baixar — que a tela era
   * obrigada a fazer em dois dialogos e duas idas ao servidor. Agora cabe numa
   * transacao so: recusado o ajuste, a baixa inteira nao aconteceu.
   *
   * Quem faz a conta do percentual e esta funcao, e nao a rota: ela ja detem o
   * FOR UPDATE, e converter no Node abriria uma janela em que a base lida la
   * nao e a base travada aqui.
   */
  IF p_ajustes IS NOT NULL AND jsonb_typeof(p_ajustes) <> 'array' THEN
    RAISE EXCEPTION 'Os ajustes devem vir em uma lista.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_ajustes) > 8 THEN
    RAISE EXCEPTION 'Lance no máximo 8 ajustes por baixa.' USING ERRCODE = '22023';
  END IF;

  IF p_ajustes IS NOT NULL
     AND jsonb_typeof(p_ajustes) = 'array'
     AND jsonb_array_length(p_ajustes) > 0 THEN

    IF v_atual.adiantamento_id IS NOT NULL THEN
      RAISE EXCEPTION 'Titulo antecipado nao aceita acrescimo ou desconto na baixa: a composicao dele responde a antecipacao. Lance o ajuste no titulo antes.'
        USING ERRCODE = '22023';
    END IF;

    -- A base congela antes do laco. Percentual incide sobre valor_base, nunca
    -- sobre o acumulado: duas linhas de 10% somam 20% da base, que e a regra
    -- que recalcular_valores_transacao ja estabeleceu.
    v_base := round(coalesce(v_atual.valor_base, v_atual.valor, 0), 2);

    -- Acréscimos primeiro: a validade do total não depende da ordem da tela.
    FOR v_item IN
      SELECT item.value FROM jsonb_array_elements(p_ajustes) AS item
      LEFT JOIN public.tipos_ajuste_transacao tipo ON tipo.id::text = item.value->>'tipoId'
      ORDER BY CASE WHEN tipo.natureza = 'ACRESCIMO' THEN 0 ELSE 1 END
    LOOP
      v_tipo_id := (v_item->>'tipoId')::integer;
      v_modo := upper(coalesce(v_item->>'modo', 'FIXO'));
      v_informado := (v_item->>'valorInformado')::numeric;

      IF v_informado IS NULL OR v_informado::text IN ('NaN', 'Infinity', '-Infinity')
         OR v_informado <= 0 OR (v_modo = 'PORCENTAGEM' AND v_informado > 100) THEN
        RAISE EXCEPTION 'Valor do ajuste inválido. Informe um valor positivo e percentual de até 100%%.'
          USING ERRCODE = '22023';
      END IF;

      /*
       * A natureza vem do catalogo, nunca do payload.
       *
       * Deixar o cliente informa-la criaria uma segunda verdade sobre o mesmo
       * fato — e tg_transacao_ajuste_coerente existe justamente para recusar
       * divergencia entre a linha e o tipo dela.
       */
      SELECT natureza INTO v_natureza
        FROM public.tipos_ajuste_transacao
       WHERE id = v_tipo_id AND ativo IS TRUE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Tipo de ajuste % inexistente ou inativo.', v_tipo_id
          USING ERRCODE = '22023';
      END IF;

      IF v_modo NOT IN ('FIXO', 'PORCENTAGEM') THEN
        RAISE EXCEPTION 'O modo do ajuste deve ser FIXO ou PORCENTAGEM.'
          USING ERRCODE = '22023';
      END IF;

      v_calculado := CASE
        WHEN v_modo = 'PORCENTAGEM' THEN round(v_base * v_informado / 100, 2)
        ELSE round(v_informado, 2)
      END;

      IF v_calculado <= 0 THEN
        RAISE EXCEPTION 'O ajuste calculado ficou em zero.' USING ERRCODE = '22023';
      END IF;

      INSERT INTO public.transacao_ajuste (
        transacao_id, tipo_id, natureza, modo,
        valor_informado, valor_calculado, observacao, created_by
      ) VALUES (
        p_transacao_id, v_tipo_id, v_natureza, v_modo,
        v_informado, v_calculado,
        left(nullif(btrim(coalesce(v_item->>'observacao', '')), ''), 500),
        p_baixado_por
      );
    END LOOP;

    /*
     * Reler e obrigatorio.
     *
     * transacao_ajuste_recalcular_trg ja regravou valor, valor_acrescimos,
     * valor_descontos e "valorLiquido" do titulo, e v_atual e uma foto de antes.
     * Sem isto, v_liquido e v_saldo logo abaixo seriam os de antes do juros — e
     * quitar o titulo inteiro viraria baixa PARCIAL por acidente, com o banco
     * saindo do titulo e uma filha nascendo sem ninguem ter pedido.
     */
    SELECT * INTO v_atual FROM public.transacao WHERE id = p_transacao_id;
    IF round(v_atual.valor - coalesce(v_atual.valor_descontos, 0) - coalesce(v_atual.valor_baixado, 0), 2) <= 0 THEN
      RAISE EXCEPTION 'Os descontos devem deixar um saldo maior que zero para realizar a baixa.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  v_antecipada := v_atual.adiantamento_id IS NOT NULL;
  v_liquido := round(coalesce(nullif(v_atual."valorLiquido", 0), v_atual.valor, 0), 2);
  v_saldo := round(v_liquido - coalesce(v_atual.valor_baixado, 0), 2);
  v_lancado := round(coalesce(p_valor_lancado, 0), 2);
  v_valor := p_valor;

  /*
   * Quem já foi pago em partes termina em partes.
   *
   * O título com filhas não pode voltar a carregar banco — seria o mesmo dinheiro
   * no título e nas baixas dele. Então quem chama sem dizer o valor (a tela
   * pagando o restante exato, a baixa em lote) está pedindo "termina de receber",
   * e é isso que a função entrega: o saldo, pelo caminho da filha.
   *
   * Antecipado fica de fora: lá a filha é repasse de caixa e não quitação, e o
   * `valor_baixado` dele não é saldo a pagar.
   */
  IF v_valor IS NULL
     AND NOT coalesce(v_antecipada, false)
     AND coalesce(v_atual.valor_baixado, 0) > 0 THEN
    v_valor := v_saldo;
  END IF;

  IF p_valor_lancado IS NOT NULL THEN
    IF NOT coalesce(v_antecipada, false) THEN
      RAISE EXCEPTION
        'Só título antecipado escolhe quanto da baixa entra no caixa: neste o banco já é sempre gravado.'
        USING ERRCODE = '22023';
    END IF;
    IF v_lancado < 0 THEN
      RAISE EXCEPTION 'O valor lançado não pode ser negativo.' USING ERRCODE = '22023';
    END IF;
    IF v_lancado > v_liquido THEN
      RAISE EXCEPTION
        'O valor lançado (%) passa do valor do título (%).', v_lancado, v_liquido
        USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_valor IS NOT NULL THEN
    IF round(v_valor, 2) <= 0 THEN
      RAISE EXCEPTION 'O valor da baixa deve ser maior que zero.' USING ERRCODE = '22023';
    END IF;
    IF round(v_valor, 2) > v_saldo THEN
      RAISE EXCEPTION
        'A baixa de % passa do saldo em aberto do título, que é de %.',
        round(v_valor, 2), v_saldo USING ERRCODE = '22023';
    END IF;
    IF coalesce(v_antecipada, false) THEN
      RAISE EXCEPTION
        'Título antecipado ainda não aceita baixa parcial.' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- --------------------------------------------------------------- parcial
  IF v_valor IS NOT NULL
     AND (round(v_valor, 2) < v_saldo OR coalesce(v_atual.valor_baixado, 0) > 0) THEN

    -- O banco que estava no título era a conta PREVISTA, escolhida no
    -- lançamento. A partir daqui o dinheiro mora nas baixas, e cada uma sabe por
    -- onde entrou de verdade.
    IF v_atual.banco_id IS NOT NULL THEN
      UPDATE public.transacao SET banco_id = NULL, updated_at = now()
       WHERE id = p_transacao_id;
    END IF;

    v_filha_id := public.registrar_baixa_filha(
      v_atual, round(v_valor, 2), p_pago_em, p_banco_id, v_metodo,
      p_plano_de_conta_id, p_centro_custo_id, p_baixado_por, false
    );

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento
    ) VALUES (
      v_atual.id, coalesce(v_atual.vencimento_em, v_atual.data), p_pago_em,
      p_baixado_por, p_banco_id, v_metodo
    );

    SELECT * INTO v_transacao FROM public.transacao WHERE id = p_transacao_id;

    IF upper(v_transacao.tipo::text) = 'RECEITA' AND v_transacao.evento_financeiro_id IS NULL THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_transacao.id,
      'baixa_id', v_filha_id,
      'valor_baixado', v_transacao.valor_baixado,
      'saldo', round(v_liquido - v_transacao.valor_baixado, 2),
      'pendente', v_transacao.pendente,
      'parcial', true
    );
  END IF;

  -- ------------------------------------------------------------- de uma vez
  UPDATE public.transacao
  SET vencimento_em = coalesce(vencimento_em, data),
      data = p_pago_em,
      pago_em = p_pago_em,
      baixado_por = p_baixado_por,
      banco_id = CASE WHEN coalesce(v_antecipada, false) THEN NULL ELSE p_banco_id END,
      metodopagamento = v_metodo,
      plano_de_conta_id = p_plano_de_conta_id,
      centro_custo_id = p_centro_custo_id,
      pendente = false,
      updated_at = now()
  WHERE id = p_transacao_id
    AND pendente = true
    AND is_deleted = false
  RETURNING * INTO v_transacao;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'A transação já foi baixada.' USING ERRCODE = '23505';
  END IF;

  IF coalesce(v_antecipada, false) AND v_lancado > 0 THEN
    v_filha_id := public.registrar_baixa_filha(
      v_atual, v_lancado, p_pago_em, p_banco_id, v_metodo,
      p_plano_de_conta_id, p_centro_custo_id, p_baixado_por, true
    );
  END IF;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento
  ) VALUES (
    v_transacao.id, v_transacao.vencimento_em, v_transacao.pago_em,
    v_transacao.baixado_por,
    CASE WHEN v_filha_id IS NOT NULL THEN p_banco_id ELSE v_transacao.banco_id END,
    v_transacao.metodopagamento
  );

  IF upper(v_transacao.tipo::text) = 'RECEITA' AND v_transacao.evento_financeiro_id IS NULL THEN
    IF v_transacao.ordemservicoid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
    END IF;

    IF v_transacao.vendaid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
    END IF;

    IF v_transacao.pagamento_multiplo_id IS NOT NULL THEN
      PERFORM public.recalcular_documentos_da_transacao(v_transacao.id);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pago_em', v_transacao.pago_em,
    'vencimento_em', v_transacao.vencimento_em,
    'pendente', false,
    'parcial', false,
    'baixa_id', v_filha_id,
    'valor_lancado', coalesce(v_lancado, 0)
  );
END;
$$;


--
-- Name: FUNCTION baixar_transacao_pendente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_banco_id bigint, p_metodopagamento text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_baixado_por uuid, p_valor numeric, p_valor_lancado numeric, p_ajustes jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.baixar_transacao_pendente(p_transacao_id bigint, p_pago_em timestamp with time zone, p_banco_id bigint, p_metodopagamento text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_baixado_por uuid, p_valor numeric, p_valor_lancado numeric, p_ajustes jsonb) IS 'Da baixa num titulo em aberto. p_valor diz quanto esta sendo liquidado; nulo e a baixa de uma vez, salvo em titulo que ja tem baixas parciais, onde significa o restante. p_valor_lancado diz quanto entra na conta, e so titulo antecipado responde. p_ajustes lanca acrescimos e descontos antes da baixa, na unica janela em que o gatilho aceita acrescimo.';


--
-- Name: buscar_ultimo_valor_venda_produto(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.buscar_ultimo_valor_venda_produto(p_produto_id integer) RETURNS TABLE(valor_unitario numeric, origem text, realizado_em timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    candidato.valor_unitario,
    candidato.origem,
    candidato.realizado_em
  FROM (
    SELECT
      round(vp.valor_total / nullif(vp.quantidade, 0), 4) AS valor_unitario,
      'VENDA'::text AS origem,
      coalesce(v.datavenda, v.updatedat, v.createdat) AS realizado_em,
      v.id AS documento_id
    FROM public.vendaproduto vp
    JOIN public.venda v ON v.id = vp.venda_id
    WHERE vp.produtoid = p_produto_id
      AND v.status = 'FINALIZADA'
      AND vp.quantidade > 0

    UNION ALL

    SELECT
      round(op.subtotal / nullif(op.quantidade, 0), 4) AS valor_unitario,
      'OS'::text AS origem,
      coalesce(
        os.pagamento_concluido_em,
        os.datasaida::timestamptz,
        os.updatedat::timestamptz,
        os.createdat::timestamptz
      ) AS realizado_em,
      os.id AS documento_id
    FROM public.osproduto op
    JOIN public.ordemservico os ON os.id = op.ordemservicoid
    WHERE op.produtoid = p_produto_id
      AND os.status = 'CONCLUIDO'
      AND os.is_deleted = false
      AND op.quantidade > 0
  ) candidato
  WHERE candidato.valor_unitario IS NOT NULL
  ORDER BY candidato.realizado_em DESC NULLS LAST, candidato.documento_id DESC
  LIMIT 1;
$$;


--
-- Name: FUNCTION buscar_ultimo_valor_venda_produto(p_produto_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.buscar_ultimo_valor_venda_produto(p_produto_id integer) IS 'Retorna o valor unitário efetivo mais recente entre venda finalizada e OS concluída.';


--
-- Name: cancelar_consumo_produto_os(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_consumo_produto_os(p_evento_id bigint, p_motivo text, p_usuario uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento    public.eventos_financeiros%ROWTYPE;
  v_motivo    text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_status_os text;
BEGIN
  IF v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_evento FROM public.eventos_financeiros WHERE id = p_evento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Consumo nao encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v_evento.origem <> 'CONSUMO' THEN
    RAISE EXCEPTION 'Este evento nao e um consumo de estoque.' USING ERRCODE = 'P0001';
  END IF;
  IF v_evento.status = 'CANCELADO' THEN
    RAISE EXCEPTION 'Este consumo ja foi cancelado.' USING ERRCODE = 'P0001';
  END IF;
  -- Dinheiro real amarrado: desfazer aqui deixaria uma transacao orfa.
  IF v_evento.status = 'CONVERTIDO'
     OR v_evento.transacaoid IS NOT NULL
     OR v_evento.lancamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este consumo ja foi lancado no financeiro. Exclua a transacao vinculada antes de devolver o item ao estoque.'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT o.status::text INTO v_status_os
    FROM public.ordemservico o WHERE o.id = v_evento.ordemservicoid;
  -- Mesma frase que o lancamento de despesas ja usa, para o operador reconhecer
  -- o caminho: reabrir a OS destrava.
  IF v_status_os IN ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO') THEN
    RAISE EXCEPTION 'A OS #% ja foi finalizada. Reabra a OS para desfazer este consumo.',
      v_evento.ordemservicoid USING ERRCODE = 'P0001';
  END IF;

  IF v_evento.consumo_saida_id IS NOT NULL THEN
    PERFORM set_config('app.consumo_os_estorno', 'permitido', true);
    PERFORM public.cancelar_saida_estoque(v_evento.consumo_saida_id, v_motivo, p_usuario);
    PERFORM set_config('app.consumo_os_estorno', '', true);
  ELSIF v_evento.consumo_usoconsumo_saida_id IS NOT NULL THEN
    PERFORM set_config('app.consumo_os_estorno', 'permitido', true);
    PERFORM public.cancelar_saida_usoconsumo(v_evento.consumo_usoconsumo_saida_id, v_motivo, p_usuario);
    PERFORM set_config('app.consumo_os_estorno', '', true);
  ELSE
    RAISE EXCEPTION 'Este consumo nao tem saida de estoque vinculada.' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.eventos_financeiros
     SET status = 'CANCELADO',
         updated_at = now(),
         dados_snapshot = coalesce(dados_snapshot, '{}'::jsonb) || jsonb_build_object(
           'cancelado_em', now(),
           'cancelado_por', p_usuario,
           'motivo_cancelamento', v_motivo
         )
   WHERE id = p_evento_id;

  RETURN jsonb_build_object('evento_id', p_evento_id, 'status', 'CANCELADO');
END;
$$;


--
-- Name: cancelar_entrada_confirmada(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_entrada_confirmada(p_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto(
    'ENTRADA', p_entrada_id, 'Entrada #' || p_entrada_id || ' - cancelada', p_cancelada_by
  );
  RETURN public.cancelar_entrada_confirmada_interna(p_entrada_id, p_motivo, p_cancelada_by);
END;
$$;


--
-- Name: cancelar_entrada_confirmada_interna(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_entrada_confirmada_interna(p_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entrada public.entrada%ROWTYPE;
  v_item record;
  v_estoque integer;
  v_ultimo_custo numeric;
  v_transacao public.transacao%ROWTYPE;
  v_tipo_estorno public.tipos_transacao;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_entrada FROM public.entrada WHERE id = p_entrada_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Entrada não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_entrada.status = 'CANCELADA'::public.enum_status_entrada THEN
    RAISE EXCEPTION 'Esta entrada já está cancelada.' USING ERRCODE = '22023';
  END IF;

  -- Pagamento compartilhado com uma entrada de uso e consumo ainda ativa: a NF-e
  -- mista so pode ser cancelada como um todo, via cancelar_entrada_fiscal_mista.
  IF coalesce(current_setting('app.entrada_mista_cancelamento', true), '') <> 'permitido'
     AND EXISTS(
       SELECT 1 FROM public.transacao t
       JOIN public.usoconsumo_entrada ue ON ue.id = t.usoconsumo_entrada_id
       WHERE t.entrada_id = p_entrada_id
         AND NOT t.is_deleted
         AND t.estorno_transacao_id IS NULL
         AND ue.cancelada_at IS NULL
     ) THEN
    RAISE EXCEPTION 'Esta entrada divide o pagamento da NF-e com uma entrada de uso e consumo ainda ativa. Cancele a nota inteira.'
      USING ERRCODE = '23514';
  END IF;

  FOR v_item IN
    SELECT * FROM public.entradaitens WHERE entrada_id = p_entrada_id ORDER BY id FOR UPDATE
  LOOP
    SELECT estoque INTO v_estoque FROM public.produto WHERE id = v_item.produto_id FOR UPDATE;
    IF coalesce(v_estoque, 0) < v_item.quantidade THEN
      RAISE EXCEPTION 'Não há saldo suficiente do produto % para cancelar a entrada.', v_item.produto_id
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.produto
    SET estoque = estoque - v_item.quantidade::integer, updatedat = now()
    WHERE id = v_item.produto_id;

    INSERT INTO public.estoque_movimento_entrada (
      entrada_id, entrada_item_id, produto_id, tipo, quantidade,
      saldo_anterior, saldo_resultante, valor_unitario_compra
    ) VALUES (
      p_entrada_id, v_item.id, v_item.produto_id, 'CANCELAMENTO', v_item.quantidade::integer,
      v_estoque, v_estoque - v_item.quantidade::integer, v_item.valor_unitario_compra
    );

    SELECT ei.valor_unitario_compra INTO v_ultimo_custo
    FROM public.entradaitens ei
    JOIN public.entrada e ON e.id = ei.entrada_id
    WHERE ei.produto_id = v_item.produto_id
      AND e.id <> p_entrada_id
      AND e.status = 'CONFIRMADA'::public.enum_status_entrada
    ORDER BY e.created_at DESC, e.id DESC, ei.id DESC LIMIT 1;

    UPDATE public.produto
    SET ultimovalordecompra = v_ultimo_custo
    WHERE id = v_item.produto_id;
  END LOOP;

  FOR v_transacao IN
    SELECT * FROM public.transacao
    WHERE entrada_id = p_entrada_id AND NOT is_deleted AND estorno_transacao_id IS NULL
    FOR UPDATE
  LOOP
    IF v_transacao.pendente THEN
      UPDATE public.transacao
      SET pendente = false, is_deleted = true, deleted_at = now(), updated_at = now()
      WHERE id = v_transacao.id;
    ELSE
      v_tipo_estorno := CASE v_transacao.tipo
        WHEN 'DESPESA'::public.tipos_transacao THEN 'RECEITA'::public.tipos_transacao
        WHEN 'RECEITA'::public.tipos_transacao THEN 'DESPESA'::public.tipos_transacao
        WHEN 'DEPOSITO'::public.tipos_transacao THEN 'SAQUE'::public.tipos_transacao
        ELSE 'DEPOSITO'::public.tipos_transacao
      END;
      INSERT INTO public.transacao (
        descricao, valor, "valorLiquido", data, metodopagamento, categoria, categoria_id,
        tipo, cliente_id, banco_id, nomepagador, cpfcnpjpagador, pendente,
        plano_de_conta_id, plano_de_conta, centro_custo_id, centro_custo,
        entrada_id, estorno_transacao_id
      ) VALUES (
        'Estorno: ' || v_transacao.descricao, v_transacao.valor, v_transacao."valorLiquido", now(),
        v_transacao.metodopagamento, v_transacao.categoria, v_transacao.categoria_id,
        v_tipo_estorno, v_transacao.cliente_id, v_transacao.banco_id,
        v_transacao.nomepagador, v_transacao.cpfcnpjpagador, false,
        v_transacao.plano_de_conta_id, v_transacao.plano_de_conta,
        v_transacao.centro_custo_id, v_transacao.centro_custo,
        p_entrada_id, v_transacao.id
      );
    END IF;
  END LOOP;

  UPDATE public.entrada
  SET status = 'CANCELADA'::public.enum_status_entrada,
      cancelada_at = now(),
      cancelada_by = p_cancelada_by,
      motivo_cancelamento = v_motivo
  WHERE id = p_entrada_id;

  RETURN jsonb_build_object('entrada_id', p_entrada_id, 'status', 'CANCELADA');
END;
$$;


--
-- Name: cancelar_entrada_fiscal_mista(bigint, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_entrada_fiscal_mista(p_entrada_id bigint, p_usoconsumo_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto(
    'ENTRADA', p_entrada_id, 'Entrada #' || p_entrada_id || ' - cancelada', p_cancelada_by
  );
  RETURN public.cancelar_entrada_fiscal_mista_interna(
    p_entrada_id, p_usoconsumo_entrada_id, p_motivo, p_cancelada_by
  );
END;
$$;


--
-- Name: cancelar_entrada_fiscal_mista_interna(bigint, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_entrada_fiscal_mista_interna(p_entrada_id bigint, p_usoconsumo_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_doc_produto bigint;
  v_doc_uso bigint;
BEGIN
  SELECT fiscal_dfe_documento_id INTO v_doc_produto FROM public.entrada WHERE id = p_entrada_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada de estoque nao encontrada.' USING ERRCODE = 'P0002'; END IF;
  SELECT documento_fiscal_recebido_id INTO v_doc_uso FROM public.usoconsumo_entrada WHERE id = p_usoconsumo_entrada_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada de uso e consumo nao encontrada.' USING ERRCODE = 'P0002'; END IF;

  IF v_doc_produto IS NULL OR v_doc_uso IS NULL OR v_doc_produto <> v_doc_uso THEN
    RAISE EXCEPTION 'As entradas informadas nao pertencem a mesma NF-e.' USING ERRCODE = '22023';
  END IF;

  -- Libera os guards de cancelamento parcial apenas dentro desta transacao.
  PERFORM set_config('app.entrada_mista_cancelamento', 'permitido', true);

  -- Uso e consumo primeiro: e o lado que remove o pagamento pendente compartilhado,
  -- de modo que o cancelamento do estoque nao tente trata-lo uma segunda vez.
  PERFORM public.cancelar_entrada_usoconsumo(p_usoconsumo_entrada_id, p_motivo, p_cancelada_by);
  PERFORM public.cancelar_entrada_confirmada(p_entrada_id, p_motivo, p_cancelada_by);

  RETURN jsonb_build_object(
    'entrada_id', p_entrada_id,
    'usoconsumo_entrada_id', p_usoconsumo_entrada_id,
    'status', 'CANCELADA'
  );
END $$;


--
-- Name: cancelar_entrada_usoconsumo(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_entrada_usoconsumo(p_entrada_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entrada public.usoconsumo_entrada%ROWTYPE; v_linha record; v_saldo integer; v_ultimo_custo numeric;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_entrada FROM public.usoconsumo_entrada WHERE id=p_entrada_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrada nao encontrada.' USING ERRCODE='P0002'; END IF;
  IF v_entrada.status='CANCELADA' THEN RAISE EXCEPTION 'Entrada ja cancelada.' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM public.transacao WHERE usoconsumo_entrada_id=p_entrada_id AND NOT pendente AND NOT is_deleted AND estorno_transacao_id IS NULL) THEN
    RAISE EXCEPTION 'Existem pagamentos liquidados. Estorne-os antes de cancelar a entrada.' USING ERRCODE='23514';
  END IF;
  -- Pagamento compartilhado com uma entrada de estoque ainda ativa: a NF-e mista
  -- so pode ser cancelada como um todo, via cancelar_entrada_fiscal_mista.
  IF coalesce(current_setting('app.entrada_mista_cancelamento', true), '') <> 'permitido'
     AND EXISTS(
       SELECT 1 FROM public.transacao t
       JOIN public.entrada e ON e.id = t.entrada_id
       WHERE t.usoconsumo_entrada_id = p_entrada_id
         AND NOT t.is_deleted
         AND t.estorno_transacao_id IS NULL
         AND e.cancelada_at IS NULL
     ) THEN
    RAISE EXCEPTION 'Esta entrada divide o pagamento da NF-e com uma entrada de estoque ainda ativa. Cancele a nota inteira.'
      USING ERRCODE = '23514';
  END IF;
  FOR v_linha IN SELECT * FROM public.usoconsumo_entrada_item WHERE entrada_id=p_entrada_id ORDER BY id FOR UPDATE LOOP
    SELECT estoque INTO v_saldo FROM public.usoconsumo_item WHERE id=v_linha.item_id FOR UPDATE;
    IF v_saldo<v_linha.quantidade THEN
      RAISE EXCEPTION 'Saldo insuficiente para cancelar a entrada do item %.',v_linha.item_id USING ERRCODE='23514';
    END IF;
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque-v_linha.quantidade,updated_by=p_cancelada_by WHERE id=v_linha.item_id;
    INSERT INTO public.usoconsumo_movimento_entrada(
      entrada_id,entrada_item_id,item_id,tipo,quantidade,saldo_anterior,saldo_resultante,valor_unitario_compra,created_by
    ) VALUES(p_entrada_id,v_linha.id,v_linha.item_id,'CANCELAMENTO',v_linha.quantidade,v_saldo,
      v_saldo-v_linha.quantidade,v_linha.valor_unitario_compra,p_cancelada_by);
    SELECT ei.valor_unitario_compra INTO v_ultimo_custo
      FROM public.usoconsumo_entrada_item ei JOIN public.usoconsumo_entrada e ON e.id=ei.entrada_id
      WHERE ei.item_id=v_linha.item_id AND e.id<>p_entrada_id AND e.status='CONFIRMADA'
      ORDER BY e.created_at DESC,e.id DESC,ei.id DESC LIMIT 1;
    UPDATE public.usoconsumo_item SET ultimovalordecompra=v_ultimo_custo WHERE id=v_linha.item_id;
  END LOOP;
  UPDATE public.transacao SET is_deleted=true,deleted_at=now(),deleted_by=p_cancelada_by,updated_at=now()
    WHERE usoconsumo_entrada_id=p_entrada_id AND pendente AND NOT is_deleted;
  UPDATE public.fiscal_dfe_item_apropriacao SET cancelada_at=now()
    WHERE usoconsumo_entrada_id=p_entrada_id AND cancelada_at IS NULL;
  UPDATE public.usoconsumo_entrada
    SET status='CANCELADA',cancelada_at=now(),cancelada_by=p_cancelada_by,motivo_cancelamento=v_motivo
    WHERE id=p_entrada_id;
  RETURN jsonb_build_object('entrada_id',p_entrada_id,'status','CANCELADA');
END $$;


--
-- Name: cancelar_eventos_dre_entrada(text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_eventos_dre_entrada(p_source_type text, p_source_id bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_cancelados integer;
BEGIN
  -- Encerra, nao apaga: o livro guarda o que existiu. CONVERTIDO ficaria de fora
  -- pela razao de sempre, mas nem chega a acontecer aqui — estes eventos nascem
  -- com `pode_gerar_transacao = false`, ja que a compra ja esta em contas a pagar.
  UPDATE public.eventos_financeiros
     SET status = 'CANCELADO', updated_at = now()
   WHERE source_type = p_source_type
     AND source_id = p_source_id
     AND origem = 'ENTRADA_FISCAL'
     AND status = 'ATIVO';

  GET DIAGNOSTICS v_cancelados = ROW_COUNT;
  RETURN v_cancelados;
END $$;


--
-- Name: FUNCTION cancelar_eventos_dre_entrada(p_source_type text, p_source_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cancelar_eventos_dre_entrada(p_source_type text, p_source_id bigint) IS 'Encerra os lancamentos de DRE de uma entrada cancelada. Marca CANCELADO em vez de criar evento inverso, para o drill-down nao contar o lancamento duas vezes.';


--
-- Name: cancelar_saida_estoque(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_saida_estoque(p_saida_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_os integer;
  v_aluguel bigint;
BEGIN
  SELECT ordemservicoid, aluguel_id INTO v_os, v_aluguel FROM public.estoque_saida WHERE id = p_saida_id;
  IF v_os IS NOT NULL
     AND coalesce(nullif(current_setting('app.consumo_os_estorno', true), ''), '') <> 'permitido' THEN
    RAISE EXCEPTION 'Esta saida foi gerada pelo consumo registrado na OS #%. Cancele a despesa na ordem de servico para devolver o item ao estoque.',
      v_os USING ERRCODE = 'P0001';
  END IF;
  IF v_aluguel IS NOT NULL
     AND coalesce(nullif(current_setting('app.aluguel_estorno', true), ''), '') <> 'permitido' THEN
    RAISE EXCEPTION 'Esta saida foi gerada pelo Aluguel #%. Encerre, edite ou exclua o aluguel para devolver o item ao estoque.',
      v_aluguel USING ERRCODE = 'P0001';
  END IF;

  PERFORM public.estoque_definir_contexto(
    'SAIDA_MANUAL', p_saida_id, 'Saida #' || p_saida_id || ' - cancelada', p_cancelada_by
  );
  RETURN public.cancelar_saida_estoque_interna(p_saida_id, p_motivo, p_cancelada_by);
END;
$$;


--
-- Name: cancelar_saida_estoque_interna(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_saida_estoque_interna(p_saida_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saida public.estoque_saida%ROWTYPE;
  v_linha record;
  v_estoque integer;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_saida FROM public.estoque_saida WHERE id = p_saida_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Saída não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_saida.status = 'CANCELADA' THEN
    RAISE EXCEPTION 'Esta saída já está cancelada.' USING ERRCODE = '22023';
  END IF;

  -- Cancelar uma saida devolve a quantidade ao estoque.
  FOR v_linha IN
    SELECT * FROM public.estoque_saida_item WHERE saida_id = p_saida_id ORDER BY id FOR UPDATE
  LOOP
    SELECT estoque INTO v_estoque FROM public.produto WHERE id = v_linha.produto_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Produto % não encontrado.', v_linha.produto_id USING ERRCODE = 'P0002';
    END IF;

    UPDATE public.produto
    SET estoque = coalesce(estoque, 0) + v_linha.quantidade,
        updatedat = now()
    WHERE id = v_linha.produto_id;
  END LOOP;

  UPDATE public.estoque_saida
  SET status = 'CANCELADA',
      cancelada_at = now(),
      cancelada_by = p_cancelada_by,
      motivo_cancelamento = v_motivo
  WHERE id = p_saida_id;

  RETURN jsonb_build_object('saida_id', p_saida_id, 'status', 'CANCELADA');
END;
$$;


--
-- Name: cancelar_saida_usoconsumo(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_saida_usoconsumo(p_saida_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saida public.usoconsumo_saida%ROWTYPE; v_linha record;
  v_motivo text := nullif(btrim(p_motivo), '');
BEGIN
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'Informe o motivo do cancelamento.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_saida FROM public.usoconsumo_saida WHERE id=p_saida_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Saida nao encontrada.' USING ERRCODE='P0002'; END IF;
  IF v_saida.status='CANCELADA' THEN RAISE EXCEPTION 'Saida ja cancelada.' USING ERRCODE='22023'; END IF;
  IF v_saida.ordemservicoid IS NOT NULL
     AND coalesce(nullif(current_setting('app.consumo_os_estorno', true), ''), '') <> 'permitido' THEN
    RAISE EXCEPTION 'Esta saida foi gerada pelo consumo registrado na OS #%. Cancele a despesa na ordem de servico para devolver o item ao estoque.',
      v_saida.ordemservicoid USING ERRCODE='P0001';
  END IF;
  IF v_saida.aluguel_id IS NOT NULL
     AND coalesce(nullif(current_setting('app.aluguel_estorno', true), ''), '') <> 'permitido' THEN
    RAISE EXCEPTION 'Esta saida foi gerada pelo Aluguel #%. Encerre, edite ou exclua o aluguel para devolver o item ao estoque.',
      v_saida.aluguel_id USING ERRCODE='P0001';
  END IF;
  FOR v_linha IN SELECT * FROM public.usoconsumo_saida_item WHERE saida_id=p_saida_id ORDER BY id FOR UPDATE LOOP
    PERFORM 1 FROM public.usoconsumo_item WHERE id=v_linha.item_id FOR UPDATE;
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque+v_linha.quantidade,updated_by=p_cancelada_by WHERE id=v_linha.item_id;
  END LOOP;
  UPDATE public.usoconsumo_saida
    SET status='CANCELADA',cancelada_at=now(),cancelada_by=p_cancelada_by,motivo_cancelamento=v_motivo
    WHERE id=p_saida_id;
  RETURN jsonb_build_object('saida_id',p_saida_id,'status','CANCELADA');
END $$;


--
-- Name: cancelar_venda(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_venda(p_venda_id bigint, p_motivo text, p_cancelada_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_motivo text := nullif(btrim(p_motivo), '');
  v_transacoes_excluidas integer := 0;
  v_produtos_devolvidos integer := 0;
BEGIN
  IF v_motivo IS NULL OR char_length(v_motivo) < 3 THEN
    RAISE EXCEPTION 'Informe um motivo com pelo menos 3 caracteres.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_venda FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002'; END IF;
  IF v_venda.status::text IN ('CANCELADA', 'CANCELADO') THEN
    RAISE EXCEPTION 'Esta venda já está cancelada.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.nfe
    WHERE vendaid = p_venda_id AND status::text NOT IN ('RASCUNHO', 'CANCELADA', 'REJEITADA')
  ) THEN
    RAISE EXCEPTION 'Cancele a NF-e autorizada ou em processamento antes de cancelar a venda.' USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::integer INTO v_produtos_devolvidos
  FROM public.vendaproduto_baixa WHERE venda_id = p_venda_id;
  PERFORM public.fn_estornar_estoque_venda(p_venda_id::integer);

  -- Decisão temporária: remove todas as transações por exclusão lógica e não
  -- cria lançamentos inversos. Os registros continuam no banco para auditoria.
  UPDATE public.transacao
  SET pendente = false, is_deleted = true, deleted_at = now(), deleted_by = p_cancelada_by,
      updated_at = now(), updated_by = p_cancelada_by
  WHERE vendaid = p_venda_id AND NOT is_deleted;
  GET DIAGNOSTICS v_transacoes_excluidas = ROW_COUNT;

  UPDATE public.venda
  SET status = 'CANCELADA', motivo_cancelamento = v_motivo, cancelada_at = now(),
      cancelada_by = p_cancelada_by, updated_by = p_cancelada_by, updatedat = now(), status_entrega = NULL
  WHERE id = p_venda_id;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id, 'status', 'CANCELADA',
    'produtosDevolvidos', v_produtos_devolvidos,
    'transacoesExcluidas', v_transacoes_excluidas,
    'estornosCriados', 0
  );
END;
$$;


--
-- Name: cancelar_venda_marketplace_sem_repor_estoque(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancelar_venda_marketplace_sem_repor_estoque(p_venda_id integer, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_venda public.venda%rowtype;
  v_transacoes_excluidas integer := 0;
begin
  if p_motivo is null or char_length(btrim(p_motivo)) < 3 then
    raise exception 'Informe um motivo com pelo menos 3 caracteres.' using errcode = '22023';
  end if;

  select * into v_venda from public.venda where id = p_venda_id for update;
  if not found then
    raise exception 'Venda não encontrada.' using errcode = 'P0002';
  end if;
  if v_venda.status::text in ('CANCELADA', 'CANCELADO') then
    return jsonb_build_object('vendaId', p_venda_id, 'status', 'CANCELADA', 'alreadyCancelled', true);
  end if;
  if exists (
    select 1 from public.nfe
     where vendaid = p_venda_id
       and status::text not in ('RASCUNHO', 'CANCELADA', 'REJEITADA')
  ) then
    raise exception 'Cancele a NF-e autorizada ou em processamento antes de encerrar a venda.' using errcode = '23514';
  end if;

  update public.transacao
     set pendente = false,
         is_deleted = true,
         deleted_at = now(),
         updated_at = now()
   where vendaid = p_venda_id
     and not is_deleted;
  get diagnostics v_transacoes_excluidas = row_count;

  update public.venda
     set status = 'CANCELADA',
         motivo_cancelamento = nullif(btrim(p_motivo), ''),
         cancelada_at = now(),
         updatedat = now(),
         status_entrega = null
   where id = p_venda_id;

  return jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'CANCELADA',
    'estoqueAguardandoConferencia', true,
    'transacoesExcluidas', v_transacoes_excluidas
  );
end;
$$;


--
-- Name: central_emitir_evento_operacional(integer, text, text, text, text, text, text, numeric, numeric, text, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_emitir_evento_operacional(p_tenant_id integer, p_tipo text, p_modulo text, p_entidade_tipo text, p_entidade_id text, p_titulo text, p_descricao text, p_valor numeric, p_quantidade numeric, p_prioridade text, p_metadata jsonb, p_event_key text, p_ocorrido_em timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'realtime', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_criado_em timestamptz;
begin
  if p_tenant_id is null then
    return null;
  end if;

  -- Retencao oportunista: o indice torna a limpeza barata e evita depender de
  -- pg_cron, que nao esta habilitado em todas as instalacoes.
  delete from public.central_evento_operacional
  where tenant_id = p_tenant_id
    and created_at < now() - interval '90 days';

  insert into public.central_evento_operacional (
    tenant_id, tipo, modulo, entidade_tipo, entidade_id, titulo, descricao,
    valor, quantidade, prioridade, metadata, event_key, ocorrido_em
  ) values (
    p_tenant_id,
    p_tipo,
    p_modulo,
    p_entidade_tipo,
    nullif(p_entidade_id, ''),
    p_titulo,
    nullif(p_descricao, ''),
    p_valor,
    p_quantidade,
    coalesce(p_prioridade, 'INFO'),
    coalesce(p_metadata, '{}'::jsonb),
    p_event_key,
    coalesce(p_ocorrido_em, now())
  )
  on conflict (tenant_id, event_key) do nothing
  returning id, created_at into v_id, v_criado_em;

  if v_id is not null then
    perform realtime.send(
      jsonb_build_object(
        'eventId', v_id,
        'createdAt', v_criado_em
      ),
      'operational_changed',
      'operational:tenant:' || p_tenant_id::text,
      true
    );
  end if;

  return v_id;
end;
$$;


--
-- Name: central_evento_nfe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_evento_nfe() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant integer := coalesce(new.empresaid, public.central_operacional_tenant_id());
  v_tipo text;
  v_titulo text;
  v_prioridade text := 'INFO';
  v_numero text := coalesce(nullif(new.numero::text, '0'), new.id::text);
begin
  if new.is_deleted or tg_op <> 'UPDATE' or old.status is not distinct from new.status then
    return new;
  end if;

  if new.status::text in ('ASSINADA', 'ENVIADA', 'PENDENTE_ENVIO') then
    v_tipo := 'NFE_EMISSAO_INICIADA';
    v_titulo := 'NF-e #' || v_numero || ' em emissao';
  elsif new.status::text = 'AUTORIZADA' then
    v_tipo := 'NFE_AUTORIZADA';
    v_titulo := 'NF-e #' || v_numero || ' autorizada';
  elsif new.status::text in ('REJEITADA', 'DENEGADA') then
    v_tipo := 'NFE_REJEITADA';
    v_titulo := 'NF-e #' || v_numero || ' rejeitada';
    v_prioridade := 'CRITICO';
  else
    return new;
  end if;

  perform public.central_emitir_evento_operacional(
    v_tenant,
    v_tipo,
    'FISCAL',
    'NFE',
    new.id::text,
    v_titulo,
    case when v_tipo = 'NFE_REJEITADA' then 'Consulte o documento fiscal' else null end,
    new.total_nfe,
    null,
    v_prioridade,
    jsonb_strip_nulls(jsonb_build_object(
      'numero', new.numero,
      'ordemServicoId', new.ordemservicoid,
      'vendaId', new.vendaid,
      'status', new.status::text
    )),
    v_tipo || ':' || new.id::text || ':' || txid_current()::text,
    coalesce(new.dataautorizacao, new.updatedat, now())
  );
  return new;
exception when others then
  raise warning '[central] evento de NF-e ignorado: %', sqlerrm;
  return new;
end;
$$;


--
-- Name: central_evento_nfse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_evento_nfse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant integer := coalesce(new.empresaid, public.central_operacional_tenant_id());
  v_tipo text;
  v_titulo text;
  v_prioridade text := 'INFO';
  v_status text := upper(coalesce(new.status, ''));
  v_numero text := coalesce(nullif(new.numero, ''), new.id::text);
begin
  if tg_op = 'INSERT' and v_status = 'PROCESSANDO' then
    v_tipo := 'NFSE_EMISSAO_INICIADA';
    v_titulo := 'NFS-e #' || v_numero || ' em emissao';
  elsif tg_op = 'UPDATE' and old.status is distinct from new.status then
    if v_status in ('AUTORIZADA', 'AUTORIZADO', 'EMITIDA', 'EMITIDO') then
      v_tipo := 'NFSE_AUTORIZADA';
      v_titulo := 'NFS-e #' || v_numero || ' autorizada';
    elsif v_status in ('REJEITADA', 'REJEITADO', 'ERRO_AUTORIZACAO') then
      v_tipo := 'NFSE_REJEITADA';
      v_titulo := 'NFS-e #' || v_numero || ' rejeitada';
      v_prioridade := 'CRITICO';
    elsif v_status in ('PROCESSANDO', 'PROCESSANDO_AUTORIZACAO') then
      v_tipo := 'NFSE_EMISSAO_INICIADA';
      v_titulo := 'NFS-e #' || v_numero || ' em emissao';
    else
      return new;
    end if;
  else
    return new;
  end if;

  perform public.central_emitir_evento_operacional(
    v_tenant,
    v_tipo,
    'FISCAL',
    'NFSE',
    new.id::text,
    v_titulo,
    case when v_tipo = 'NFSE_REJEITADA' then 'Consulte o documento fiscal' else null end,
    new.valor_total,
    null,
    v_prioridade,
    jsonb_strip_nulls(jsonb_build_object(
      'numero', new.numero,
      'ordemServicoId', new.ordemservicoid,
      'status', new.status
    )),
    v_tipo || ':' || new.id::text || ':' || txid_current()::text,
    coalesce(new.updatedat, new.dataemissao, now())
  );
  return new;
exception when others then
  raise warning '[central] evento de NFS-e ignorado: %', sqlerrm;
  return new;
end;
$$;


--
-- Name: central_evento_ordemservico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_evento_ordemservico() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant integer := public.central_operacional_tenant_id();
  v_tipo text;
  v_titulo text;
  v_prioridade text := 'INFO';
begin
  if new.is_deleted or new.migracao_referencia is not null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_tipo := 'OS_CRIADA';
    v_titulo := 'OS #' || new.id::text || ' criada';
  elsif old.status is distinct from new.status then
    case new.status::text
      when 'EM_ANDAMENTO' then
        v_tipo := 'OS_INICIO_EXECUCAO';
        v_titulo := 'OS #' || new.id::text || ' iniciou execucao';
      when 'PAGAMENTO' then
        v_tipo := 'OS_AGUARDANDO_PAGAMENTO';
        v_titulo := 'OS #' || new.id::text || ' aguarda pagamento';
      when 'CONCLUIDO' then
        v_tipo := 'OS_FINALIZADA';
        v_titulo := 'OS #' || new.id::text || ' finalizada';
      when 'CANCELADO' then
        v_tipo := 'OS_CANCELADA';
        v_titulo := 'OS #' || new.id::text || ' cancelada';
        v_prioridade := 'ATENCAO';
      else
        return new;
    end case;
  else
    return new;
  end if;

  perform public.central_emitir_evento_operacional(
    v_tenant,
    v_tipo,
    'ORDENS',
    'ORDEM_SERVICO',
    new.id::text,
    v_titulo,
    null,
    null,
    null,
    v_prioridade,
    jsonb_build_object('status', new.status::text),
    case when tg_op = 'INSERT'
      then 'OS_CRIADA:' || new.id::text
      else v_tipo || ':' || new.id::text || ':' || txid_current()::text
    end,
    now()
  );
  return new;
exception when others then
  raise warning '[central] evento de OS ignorado: %', sqlerrm;
  return new;
end;
$$;


--
-- Name: central_evento_produto_estoque(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_evento_produto_estoque() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant integer := public.central_operacional_tenant_id();
  v_diferenca integer := new.estoque - old.estoque;
begin
  if new.is_deleted or new.estoque is not distinct from old.estoque then
    return new;
  end if;

  perform public.central_emitir_evento_operacional(
    v_tenant,
    case when v_diferenca > 0 then 'ESTOQUE_ENTRADA' else 'ESTOQUE_SAIDA' end,
    'ESTOQUE',
    'PRODUTO',
    new.id::text,
    case when v_diferenca > 0 then 'Entrada de estoque · ' else 'Saida de estoque · ' end || new.titulo,
    new.titulo,
    null,
    abs(v_diferenca),
    'INFO',
    jsonb_build_object('estoqueAtual', new.estoque, 'estoqueMinimo', new.estoqueminimo),
    (case when v_diferenca > 0 then 'ESTOQUE_ENTRADA:' else 'ESTOQUE_SAIDA:' end)
      || new.id::text || ':' || txid_current()::text,
    coalesce(new.updatedat, now())
  );

  if new.estoque <= new.estoqueminimo
    and (old.estoque > old.estoqueminimo or new.estoque = 0)
  then
    perform public.central_emitir_evento_operacional(
      v_tenant,
      'ESTOQUE_BAIXO',
      'ESTOQUE',
      'PRODUTO',
      new.id::text,
      case when new.estoque <= 0 then 'Estoque zerado · ' else 'Estoque baixo · ' end || new.titulo,
      new.titulo,
      null,
      new.estoque,
      case when new.estoque <= 0 then 'CRITICO' else 'ATENCAO' end,
      jsonb_build_object('estoqueAtual', new.estoque, 'estoqueMinimo', new.estoqueminimo),
      'ESTOQUE_BAIXO:' || new.id::text || ':' || txid_current()::text,
      coalesce(new.updatedat, now())
    );
  end if;

  return new;
exception when others then
  raise warning '[central] evento de estoque ignorado: %', sqlerrm;
  return new;
end;
$$;


--
-- Name: central_evento_transacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_evento_transacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant integer := public.central_operacional_tenant_id();
  v_tipo text;
  v_modulo text := 'FINANCEIRO';
  v_titulo text;
  v_valor numeric := coalesce(new."valorLiquido", new.valor, 0);
  v_documento text;
begin
  if new.is_deleted then
    return new;
  end if;

  v_documento := case
    when new.ordemservicoid is not null then 'OS #' || new.ordemservicoid::text
    when new.vendaid is not null then 'Venda #' || new.vendaid::text
    else 'Transacao #' || new.id::text
  end;

  if tg_op = 'INSERT' then
    if new.tipo::text = 'DESPESA' and new.pendente then
      v_tipo := 'CONTA_CRIADA';
      v_modulo := 'CONTAS_PAGAR';
      v_titulo := 'Conta a pagar criada · #' || new.id::text;
    elsif new.tipo::text = 'RECEITA' and not new.pendente then
      v_tipo := case when new.metodopagamento::text = 'PIX' then 'PIX_RECEBIDO' else 'PAGAMENTO_RECEBIDO' end;
      v_titulo := case when v_tipo = 'PIX_RECEBIDO' then 'PIX recebido · ' else 'Pagamento recebido · ' end || v_documento;
    elsif new.tipo::text = 'DESPESA' and not new.pendente then
      v_tipo := 'TRANSACAO_PAGA';
      v_titulo := 'Transacao paga · #' || new.id::text;
    else
      v_tipo := 'TRANSACAO_CRIADA';
      v_titulo := 'Movimentacao financeira · #' || new.id::text;
    end if;
  elsif old.pendente is true and new.pendente is false then
    if new.tipo::text = 'DESPESA' then
      v_tipo := 'CONTA_PAGA';
      v_modulo := 'CONTAS_PAGAR';
      v_titulo := 'Conta paga · #' || new.id::text;
    elsif new.tipo::text = 'RECEITA' then
      v_tipo := case when new.metodopagamento::text = 'PIX' then 'PIX_RECEBIDO' else 'PAGAMENTO_RECEBIDO' end;
      v_titulo := case when v_tipo = 'PIX_RECEBIDO' then 'PIX recebido · ' else 'Pagamento recebido · ' end || v_documento;
    else
      v_tipo := 'TRANSACAO_PAGA';
      v_titulo := 'Transacao paga · #' || new.id::text;
    end if;
  else
    return new;
  end if;

  perform public.central_emitir_evento_operacional(
    v_tenant,
    v_tipo,
    v_modulo,
    'TRANSACAO',
    new.id::text,
    v_titulo,
    new.metodopagamento::text,
    v_valor,
    null,
    'INFO',
    jsonb_strip_nulls(jsonb_build_object(
      'ordemServicoId', new.ordemservicoid,
      'vendaId', new.vendaid,
      'tipo', new.tipo::text
    )),
    case when tg_op = 'INSERT'
      then v_tipo || ':' || new.id::text
      else v_tipo || ':' || new.id::text || ':' || txid_current()::text
    end,
    coalesce(new.pago_em, new.updated_at, new.created_at, now())
  );
  return new;
exception when others then
  raise warning '[central] evento de transacao ignorado: %', sqlerrm;
  return new;
end;
$$;


--
-- Name: central_evento_venda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_evento_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_tenant integer := public.central_operacional_tenant_id();
  v_tipo text;
  v_titulo text;
  v_prioridade text := 'INFO';
begin
  if tg_op = 'INSERT' then
    if new.status::text in ('PAGAMENTO', 'PAGO', 'FINALIZADA', 'AUTORIZADO') then
      v_tipo := 'VENDA_CONFIRMADA';
      v_titulo := 'Venda #' || new.id::text || ' confirmada';
    else
      v_tipo := 'VENDA_CRIADA';
      v_titulo := 'Venda #' || new.id::text || ' criada';
    end if;
  elsif old.status is distinct from new.status then
    if new.status::text in ('PAGAMENTO', 'PAGO', 'FINALIZADA', 'AUTORIZADO') then
      v_tipo := 'VENDA_CONFIRMADA';
      v_titulo := 'Venda #' || new.id::text || ' confirmada';
    elsif new.status::text in ('CANCELADA', 'CANCELADO') then
      v_tipo := 'VENDA_CANCELADA';
      v_titulo := 'Venda #' || new.id::text || ' cancelada';
      v_prioridade := 'ATENCAO';
    else
      return new;
    end if;
  else
    return new;
  end if;

  perform public.central_emitir_evento_operacional(
    v_tenant,
    v_tipo,
    'VENDAS',
    'VENDA',
    new.id::text,
    v_titulo,
    null,
    new.valortotal,
    null,
    v_prioridade,
    jsonb_build_object('status', new.status::text),
    case when tg_op = 'INSERT'
      then v_tipo || ':' || new.id::text
      else v_tipo || ':' || new.id::text || ':' || txid_current()::text
    end,
    coalesce(new.updatedat, new.datavenda, new.createdat, now())
  );
  return new;
exception when others then
  raise warning '[central] evento de venda ignorado: %', sqlerrm;
  return new;
end;
$$;


--
-- Name: central_operacional_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_operacional_tenant_id() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select id from public.empresa order by id asc limit 1
$$;


--
-- Name: central_realtime_topic_allowed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_realtime_topic_allowed(p_topic text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.usuario u
    where u.id = auth.uid()
      and u.ativo = true
      and p_topic = 'operational:tenant:' || public.central_operacional_tenant_id()::text
      and (
        coalesce(u.is_root, false)
        or exists (
          select 1
          from public.perfilpermissao pp
          join public.permissao p on p.id = pp.permissaoid
          where pp.perfilid = u.perfilid
            and upper(trim(p.nome)) = upper('acompanhamento:visualizar')
        )
      )
  )
$$;


--
-- Name: chat_audio_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_audio_access(p_usuario_id uuid, p_mensagem_id uuid) RETURNS TABLE(conversa_id uuid, audio_path text, audio_mime text, audio_duracao_ms integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_mensagem public.chat_mensagem%rowtype;
begin
  select * into v_mensagem from public.chat_mensagem where id = p_mensagem_id;
  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_mensagem.conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  if v_mensagem.excluida_para_todos_em is not null
    or v_mensagem.tipo <> 'VOICE'
    or v_mensagem.audio_path is null
    or exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = p_mensagem_id and oculta.usuario_id = p_usuario_id
    )
  then
    raise exception using errcode = '22023', message = 'CHAT_AUDIO_UNAVAILABLE';
  end if;

  return query
  select v_mensagem.conversa_id,
         v_mensagem.audio_path,
         v_mensagem.audio_mime,
         v_mensagem.audio_duracao_ms;
end;
$$;


--
-- Name: chat_broadcast_message_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_broadcast_message_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  perform public.chat_broadcast_para_participantes(
    new.conversa_id,
    jsonb_build_object(
      'kind', 'message',
      'conversationId', new.conversa_id,
      'messageId', new.id,
      'senderId', new.remetente_id,
      'clientMessageId', new.client_message_id,
      'messageType', new.tipo
    )
  );
  return new;
end;
$$;


--
-- Name: chat_broadcast_message_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_broadcast_message_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.conteudo is not distinct from old.conteudo
    and new.editada_em is not distinct from old.editada_em
    and new.excluida_para_todos_em is not distinct from old.excluida_para_todos_em
  then
    return new;
  end if;

  perform public.chat_broadcast_para_participantes(
    new.conversa_id,
    jsonb_build_object(
      'kind', 'message-updated',
      'conversationId', new.conversa_id,
      'messageId', new.id,
      'senderId', new.remetente_id
    )
  );
  return new;
end;
$$;


--
-- Name: chat_broadcast_para_participantes(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_broadcast_para_participantes(p_conversa_id uuid, p_payload jsonb, p_somente_usuario uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_participante uuid;
begin
  for v_participante in
    select usuario_id
    from public.chat_participante
    where conversa_id = p_conversa_id
      and (p_somente_usuario is null or usuario_id = p_somente_usuario)
  loop
    perform realtime.send(
      p_payload,
      'chat_changed',
      'chat:user:' || v_participante::text,
      true
    );
  end loop;
end;
$$;


--
-- Name: chat_broadcast_reaction_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_broadcast_reaction_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_mensagem_id uuid := case when tg_op = 'DELETE' then old.mensagem_id else new.mensagem_id end;
  v_conversa_id uuid;
begin
  select msg.conversa_id into v_conversa_id
  from public.chat_mensagem msg
  where msg.id = v_mensagem_id;

  if found then
    perform public.chat_broadcast_para_participantes(
      v_conversa_id,
      jsonb_build_object(
        'kind', 'reaction',
        'conversationId', v_conversa_id,
        'messageId', v_mensagem_id
      )
    );
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: chat_broadcast_read_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_broadcast_read_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_participante uuid;
begin
  if new.last_read_message_id is not distinct from old.last_read_message_id then
    return new;
  end if;

  for v_participante in
    select usuario_id
    from public.chat_participante
    where conversa_id = new.conversa_id
  loop
    perform realtime.send(
      jsonb_build_object(
        'kind', 'read',
        'conversationId', new.conversa_id,
        'readerId', new.usuario_id,
        'lastReadMessageId', new.last_read_message_id
      ),
      'chat_changed',
      'chat:user:' || v_participante::text,
      true
    );
  end loop;
  return new;
end;
$$;


--
-- Name: chat_clear_reaction(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_clear_reaction(p_usuario_id uuid, p_mensagem_id uuid) RETURNS TABLE(mensagem_id uuid, conversa_id uuid, reacoes jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_conversa_id uuid;
begin
  select msg.conversa_id into v_conversa_id
  from public.chat_mensagem msg
  where msg.id = p_mensagem_id;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  delete from public.chat_reacao
  where chat_reacao.mensagem_id = p_mensagem_id
    and chat_reacao.usuario_id = p_usuario_id;

  return query
  select p_mensagem_id,
         v_conversa_id,
         public.chat_reacoes_da_mensagem(p_mensagem_id, p_usuario_id);
end;
$$;


--
-- Name: chat_delete_message_for_everyone(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_delete_message_for_everyone(p_usuario_id uuid, p_mensagem_id uuid, p_janela_segundos integer DEFAULT 900) RETURNS TABLE(mensagem_id uuid, conversa_id uuid, excluida_para_todos_em timestamp with time zone, audio_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_agora timestamptz := clock_timestamp();
  v_audio_path text;
begin
  select * into v_mensagem
  from public.chat_mensagem
  where id = p_mensagem_id
  for update;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;
  if v_mensagem.remetente_id <> p_usuario_id then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;
  if v_mensagem.excluida_para_todos_em is not null then
    return query
    select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.excluida_para_todos_em, null::text;
    return;
  end if;
  if v_agora > v_mensagem.created_at + make_interval(secs => greatest(0, p_janela_segundos)) then
    raise exception using errcode = '22023', message = 'CHAT_DELETE_WINDOW_EXPIRED';
  end if;

  v_audio_path := v_mensagem.audio_path;

  if v_audio_path is not null then
    insert into public.chat_audio_pendente_remocao(path, conversa_id)
    values (v_audio_path, v_mensagem.conversa_id)
    on conflict (path) do nothing;
  end if;

  -- Exclusao logica: a linha continua para nao quebrar cursor de leitura,
  -- paginacao nem respostas que citem esta mensagem.
  update public.chat_mensagem
  set conteudo = '',
      excluida_para_todos_em = v_agora,
      excluida_para_todos_por = p_usuario_id,
      editada_em = null,
      reply_snapshot_tipo = null,
      reply_snapshot_conteudo = null,
      reply_snapshot_remetente_nome = null,
      audio_path = null,
      audio_mime = null,
      audio_bytes = null,
      audio_duracao_ms = null
  where id = v_mensagem.id
  returning * into v_mensagem;

  -- Decisao: as reacoes de uma mensagem excluida para todos sao removidas.
  delete from public.chat_reacao where chat_reacao.mensagem_id = v_mensagem.id;

  return query
  select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.excluida_para_todos_em, v_audio_path;
end;
$$;


--
-- Name: chat_delete_message_for_me(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_delete_message_for_me(p_usuario_id uuid, p_mensagem_id uuid) RETURNS TABLE(mensagem_id uuid, conversa_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_conversa_id uuid;
begin
  select msg.conversa_id into v_conversa_id
  from public.chat_mensagem msg
  where msg.id = p_mensagem_id;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  insert into public.chat_mensagem_oculta(mensagem_id, usuario_id)
  values (p_mensagem_id, p_usuario_id)
  on conflict do nothing;

  -- Somente as sessoes do proprio usuario precisam saber.
  perform public.chat_broadcast_para_participantes(
    v_conversa_id,
    jsonb_build_object(
      'kind', 'message-updated',
      'conversationId', v_conversa_id,
      'messageId', p_mensagem_id
    ),
    p_usuario_id
  );

  return query select p_mensagem_id, v_conversa_id;
end;
$$;


--
-- Name: chat_direct_key(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_direct_key(p_usuario_a uuid, p_usuario_b uuid) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public'
    AS $$
  select case
    when p_usuario_a::text < p_usuario_b::text
      then p_usuario_a::text || ':' || p_usuario_b::text
    else p_usuario_b::text || ':' || p_usuario_a::text
  end;
$$;


--
-- Name: chat_edit_message(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_edit_message(p_usuario_id uuid, p_mensagem_id uuid, p_conteudo text, p_janela_segundos integer DEFAULT 900) RETURNS TABLE(mensagem_id uuid, conversa_id uuid, conteudo text, editada_em timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_conteudo text := coalesce(btrim(p_conteudo), '');
  v_agora timestamptz := clock_timestamp();
begin
  if length(v_conteudo) = 0 then
    raise exception using errcode = '22023', message = 'CHAT_EMPTY_MESSAGE';
  end if;
  if length(v_conteudo) > 5000 then
    raise exception using errcode = '22001', message = 'CHAT_MESSAGE_TOO_LONG';
  end if;

  select * into v_mensagem
  from public.chat_mensagem
  where id = p_mensagem_id
  for update;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;
  if v_mensagem.remetente_id <> p_usuario_id then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;
  if v_mensagem.tipo <> 'TEXT' then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_EDITABLE';
  end if;
  if v_mensagem.excluida_para_todos_em is not null then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_EDITABLE';
  end if;
  if v_agora > v_mensagem.created_at + make_interval(secs => greatest(0, p_janela_segundos)) then
    raise exception using errcode = '22023', message = 'CHAT_EDIT_WINDOW_EXPIRED';
  end if;

  if v_mensagem.conteudo = v_conteudo then
    return query select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.conteudo, v_mensagem.editada_em;
    return;
  end if;

  insert into public.chat_mensagem_edicao(mensagem_id, conteudo_anterior, editado_por)
  values (v_mensagem.id, v_mensagem.conteudo, p_usuario_id);

  -- created_at nao muda: a edicao nunca reordena a timeline nem move a
  -- conversa para o topo como se fosse mensagem nova.
  update public.chat_mensagem
  set conteudo = v_conteudo,
      editada_em = v_agora
  where id = v_mensagem.id
  returning * into v_mensagem;

  return query select v_mensagem.id, v_mensagem.conversa_id, v_mensagem.conteudo, v_mensagem.editada_em;
end;
$$;


--
-- Name: chat_enforce_direct_participants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_enforce_direct_participants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_conversa_id uuid;
  v_direct_key text;
  v_total integer;
begin
  v_conversa_id := case when tg_op = 'DELETE' then old.conversa_id else new.conversa_id end;
  select c.direct_key into v_direct_key
  from public.chat_conversa c
  where c.id = v_conversa_id;

  -- A conversa ja nao existe durante um cascade de exclusao.
  if not found then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  select count(*)::integer into v_total
  from public.chat_participante p
  where p.conversa_id = v_conversa_id
    and p.usuario_id::text in (
      split_part(v_direct_key, ':', 1),
      split_part(v_direct_key, ':', 2)
    );

  if v_total <> 2 or (
    select count(*) from public.chat_participante p where p.conversa_id = v_conversa_id
  ) <> 2 then
    raise exception using errcode = '23514', message = 'CHAT_DIRECT_REQUIRES_TWO_PARTICIPANTS';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: chat_get_or_create_direct(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_get_or_create_direct(p_usuario_atual uuid, p_destinatario uuid) RETURNS TABLE(conversa_id uuid, criada boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_conversa_id uuid;
  v_criada boolean := false;
  v_direct_key text;
begin
  if p_usuario_atual is null or p_destinatario is null or p_usuario_atual = p_destinatario then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_RECIPIENT';
  end if;

  if not exists (
    select 1 from public.usuario
    where id = p_usuario_atual and ativo = true
  ) then
    raise exception using errcode = '42501', message = 'INACTIVE_USER';
  end if;

  if not exists (
    select 1 from public.usuario
    where id = p_destinatario and ativo = true
  ) then
    raise exception using errcode = '22023', message = 'CHAT_RECIPIENT_UNAVAILABLE';
  end if;

  v_direct_key := public.chat_direct_key(p_usuario_atual, p_destinatario);

  insert into public.chat_conversa(tipo, direct_key)
  values ('DIRECT', v_direct_key)
  on conflict (direct_key) do nothing
  returning id into v_conversa_id;

  if v_conversa_id is null then
    select id into strict v_conversa_id
    from public.chat_conversa
    where direct_key = v_direct_key;
  else
    v_criada := true;
  end if;

  insert into public.chat_participante(conversa_id, usuario_id)
  values
    (v_conversa_id, p_usuario_atual),
    (v_conversa_id, p_destinatario)
  on conflict on constraint chat_participante_pkey do nothing;

  -- O payload e apenas uma invalidacao. Dados do chat continuam restritos as APIs.
  perform realtime.send(
    jsonb_build_object('kind', 'conversation', 'conversationId', v_conversa_id),
    'chat_changed',
    'chat:user:' || p_usuario_atual::text,
    true
  );
  perform realtime.send(
    jsonb_build_object('kind', 'conversation', 'conversationId', v_conversa_id),
    'chat_changed',
    'chat:user:' || p_destinatario::text,
    true
  );

  return query select v_conversa_id, v_criada;
end;
$$;


--
-- Name: chat_list_conversations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_list_conversations(p_usuario_id uuid) RETURNS TABLE(conversa_id uuid, participante_id uuid, participante_nome text, participante_username text, participante_setor_id integer, participante_setor_nome text, ultima_mensagem_id uuid, ultima_mensagem_conteudo text, ultima_mensagem_remetente_id uuid, ultima_mensagem_created_at timestamp with time zone, ultima_mensagem_tipo text, ultima_mensagem_excluida boolean, nao_lidas bigint, last_message_at timestamp with time zone, last_read_message_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not exists (
    select 1 from public.usuario where id = p_usuario_id and ativo = true
  ) then
    raise exception using errcode = '42501', message = 'INACTIVE_USER';
  end if;

  return query
  with minhas as (
    select p.conversa_id, p.last_read_message_id
    from public.chat_participante p
    where p.usuario_id = p_usuario_id
  ),
  visiveis as (
    select msg.*
    from public.chat_mensagem msg
    join minhas m on m.conversa_id = msg.conversa_id
    where not exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = msg.id and oculta.usuario_id = p_usuario_id
    )
  ),
  cursores as (
    select m.conversa_id,
           m.last_read_message_id,
           lida.created_at as lida_created_at,
           lida.id as lida_id
    from minhas m
    left join public.chat_mensagem lida on lida.id = m.last_read_message_id
  ),
  ultimas as (
    select distinct on (v.conversa_id)
      v.conversa_id,
      v.id,
      v.conteudo,
      v.remetente_id,
      v.created_at,
      v.tipo,
      v.excluida_para_todos_em
    from visiveis v
    order by v.conversa_id, v.created_at desc, v.id desc
  ),
  contadores as (
    select v.conversa_id, count(*)::bigint as total
    from visiveis v
    join cursores c on c.conversa_id = v.conversa_id
    where v.remetente_id <> p_usuario_id
      and v.excluida_para_todos_em is null
      and (
        c.lida_id is null
        or (v.created_at, v.id) > (c.lida_created_at, c.lida_id)
      )
    group by v.conversa_id
  )
  select
    c.id,
    outro.usuario_id,
    u.nome::text,
    u.username::text,
    s.id,
    s.nome::text,
    ult.id,
    ult.conteudo,
    ult.remetente_id,
    ult.created_at,
    ult.tipo,
    (ult.excluida_para_todos_em is not null),
    coalesce(cnt.total, 0)::bigint,
    c.last_message_at,
    minhas.last_read_message_id
  from minhas
  join public.chat_conversa c on c.id = minhas.conversa_id and c.tipo = 'DIRECT'
  join public.chat_participante outro
    on outro.conversa_id = c.id and outro.usuario_id <> p_usuario_id
  join public.usuario u on u.id = outro.usuario_id
  left join public.setor s on s.id = u.setorid
  left join ultimas ult on ult.conversa_id = c.id
  left join contadores cnt on cnt.conversa_id = c.id
  order by c.last_message_at desc nulls last, c.created_at desc, c.id desc;
end;
$$;


--
-- Name: chat_list_messages(uuid, uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_list_messages(p_usuario_id uuid, p_conversa_id uuid, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 31) RETURNS TABLE(mensagem_id uuid, remetente_id uuid, tipo text, conteudo text, client_message_id uuid, created_at timestamp with time zone, editada_em timestamp with time zone, excluida_para_todos_em timestamp with time zone, reply_to_message_id uuid, reply_snapshot_tipo text, reply_snapshot_conteudo text, reply_snapshot_remetente_nome text, audio_mime text, audio_bytes integer, audio_duracao_ms integer, reacoes jsonb, nao_lida boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_last_read_id uuid;
  v_last_read_at timestamptz;
begin
  if p_limit < 1 or p_limit > 101 then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_LIMIT';
  end if;
  if (p_before_at is null) <> (p_before_id is null) then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_CURSOR';
  end if;

  select p.last_read_message_id, lida.created_at
  into v_last_read_id, v_last_read_at
  from public.chat_participante p
  left join public.chat_mensagem lida on lida.id = p.last_read_message_id
  where p.conversa_id = p_conversa_id and p.usuario_id = p_usuario_id;

  if not found then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  return query
  select
    msg.id,
    msg.remetente_id,
    msg.tipo,
    msg.conteudo,
    msg.client_message_id,
    msg.created_at,
    msg.editada_em,
    msg.excluida_para_todos_em,
    msg.reply_to_message_id,
    msg.reply_snapshot_tipo,
    msg.reply_snapshot_conteudo,
    msg.reply_snapshot_remetente_nome,
    msg.audio_mime,
    msg.audio_bytes,
    msg.audio_duracao_ms,
    public.chat_reacoes_da_mensagem(msg.id, p_usuario_id),
    (
      msg.remetente_id <> p_usuario_id
      and msg.excluida_para_todos_em is null
      and (
        v_last_read_id is null
        or (msg.created_at, msg.id) > (v_last_read_at, v_last_read_id)
      )
    ) as nao_lida
  from public.chat_mensagem msg
  where msg.conversa_id = p_conversa_id
    and not exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = msg.id and oculta.usuario_id = p_usuario_id
    )
    and (
      p_before_at is null
      or (msg.created_at, msg.id) < (p_before_at, p_before_id)
    )
  order by msg.created_at desc, msg.id desc
  limit p_limit;
end;
$$;


--
-- Name: chat_marcar_foco(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_marcar_foco(p_usuario_id uuid, p_conversa_id uuid, p_segundos integer DEFAULT 60) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.chat_participante
  set foco_ate = case
    when p_segundos <= 0 then null
    else clock_timestamp() + make_interval(secs => least(p_segundos, 300))
  end
  where conversa_id = p_conversa_id and usuario_id = p_usuario_id;

  if not found then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;
end;
$$;


--
-- Name: chat_mark_read(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_mark_read(p_usuario_id uuid, p_conversa_id uuid, p_last_message_id uuid) RETURNS TABLE(last_read_message_id uuid, last_read_at timestamp with time zone, alterada boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_atual_id uuid;
  v_atual_at timestamptz;
  v_alvo_at timestamptz;
  v_read_at timestamptz;
  v_alterada boolean := false;
begin
  select p.last_read_message_id, p.last_read_at, atual.created_at
  into v_atual_id, v_read_at, v_atual_at
  from public.chat_participante p
  left join public.chat_mensagem atual on atual.id = p.last_read_message_id
  where p.conversa_id = p_conversa_id and p.usuario_id = p_usuario_id
  for update of p;

  if not found then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  select msg.created_at into v_alvo_at
  from public.chat_mensagem msg
  where msg.id = p_last_message_id and msg.conversa_id = p_conversa_id;

  if not found then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_READ_MESSAGE';
  end if;

  if v_atual_id is null or (v_alvo_at, p_last_message_id) > (v_atual_at, v_atual_id) then
    v_read_at := clock_timestamp();
    update public.chat_participante participante
    set last_read_message_id = p_last_message_id,
        last_read_at = v_read_at
    where participante.conversa_id = p_conversa_id
      and participante.usuario_id = p_usuario_id;
    v_atual_id := p_last_message_id;
    v_alterada := true;
  end if;

  return query select v_atual_id, v_read_at, v_alterada;
end;
$$;


--
-- Name: chat_push_target(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_push_target(p_mensagem_id uuid) RETURNS TABLE(conversa_id uuid, destinatario_id uuid, remetente_id uuid, remetente_nome text, tipo text, conteudo text, suprimido boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    msg.conversa_id,
    destino.usuario_id,
    msg.remetente_id,
    remetente.nome::text,
    msg.tipo,
    msg.conteudo,
    coalesce(destino.foco_ate > clock_timestamp(), false)
  from public.chat_mensagem msg
  join public.chat_participante destino
    on destino.conversa_id = msg.conversa_id
   and destino.usuario_id <> msg.remetente_id
  join public.usuario remetente on remetente.id = msg.remetente_id
  join public.usuario alvo on alvo.id = destino.usuario_id and alvo.ativo = true
  where msg.id = p_mensagem_id
    and msg.excluida_para_todos_em is null
    and not exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = msg.id and oculta.usuario_id = destino.usuario_id
    );
$$;


--
-- Name: chat_reacoes_da_mensagem(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_reacoes_da_mensagem(p_mensagem_id uuid, p_usuario_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object('reacao', t.reacao, 'total', t.total, 'own', t.own)
      order by t.primeira asc, t.reacao asc
    ),
    '[]'::jsonb
  )
  from (
    select r.reacao,
           count(*)::int as total,
           bool_or(r.usuario_id = p_usuario_id) as own,
           min(r.created_at) as primeira
    from public.chat_reacao r
    where r.mensagem_id = p_mensagem_id
    group by r.reacao
  ) t;
$$;


--
-- Name: chat_realtime_topic_allowed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_realtime_topic_allowed(p_topic text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.usuario u
    where u.id = auth.uid()
      and u.ativo = true
      and (
        p_topic = 'chat:presence'
        or p_topic = 'chat:user:' || u.id::text
        or (
          p_topic like 'chat:conversation:%'
          and exists (
            select 1
            from public.chat_participante p
            where p.usuario_id = u.id
              and p.conversa_id::text = substring(p_topic from 19)
          )
        )
      )
  );
$$;


--
-- Name: chat_send_message(uuid, uuid, text, uuid, text, uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_send_message(p_conversa_id uuid, p_remetente_id uuid, p_conteudo text, p_client_message_id uuid, p_tipo text DEFAULT 'TEXT'::text, p_reply_to_message_id uuid DEFAULT NULL::uuid, p_audio_path text DEFAULT NULL::text, p_audio_mime text DEFAULT NULL::text, p_audio_bytes integer DEFAULT NULL::integer, p_audio_duracao_ms integer DEFAULT NULL::integer) RETURNS TABLE(mensagem_id uuid, conversa_id uuid, remetente_id uuid, tipo text, conteudo text, client_message_id uuid, created_at timestamp with time zone, editada_em timestamp with time zone, excluida_para_todos_em timestamp with time zone, reply_to_message_id uuid, reply_snapshot_tipo text, reply_snapshot_conteudo text, reply_snapshot_remetente_nome text, audio_mime text, audio_bytes integer, audio_duracao_ms integer, criada boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_criada boolean := false;
  v_tipo text := coalesce(nullif(btrim(p_tipo), ''), 'TEXT');
  v_conteudo text := coalesce(btrim(p_conteudo), '');
  v_reply public.chat_mensagem%rowtype;
  v_reply_tipo text;
  v_reply_conteudo text;
  v_reply_nome text;
begin
  if v_tipo not in ('TEXT', 'VOICE') then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_MESSAGE_TYPE';
  end if;
  if p_client_message_id is null then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_CLIENT_MESSAGE_ID';
  end if;

  if v_tipo = 'TEXT' then
    if length(v_conteudo) = 0 then
      raise exception using errcode = '22023', message = 'CHAT_EMPTY_MESSAGE';
    end if;
    if length(v_conteudo) > 5000 then
      raise exception using errcode = '22001', message = 'CHAT_MESSAGE_TOO_LONG';
    end if;
  else
    v_conteudo := '';
    if p_audio_path is null or btrim(p_audio_path) = '' or p_audio_mime is null then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_AUDIO';
    end if;
    if p_audio_bytes is null or p_audio_bytes < 1 or p_audio_bytes > 10485760 then
      raise exception using errcode = '22023', message = 'CHAT_AUDIO_TOO_LARGE';
    end if;
    if p_audio_duracao_ms is null or p_audio_duracao_ms < 1 or p_audio_duracao_ms > 300000 then
      raise exception using errcode = '22023', message = 'CHAT_AUDIO_TOO_LONG';
    end if;
  end if;

  if not exists (
    select 1 from public.usuario where id = p_remetente_id and ativo = true
  ) then
    raise exception using errcode = '42501', message = 'INACTIVE_USER';
  end if;

  if not exists (
    select 1 from public.chat_participante participante
    where participante.conversa_id = p_conversa_id
      and participante.usuario_id = p_remetente_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  -- A citacao so pode apontar para uma mensagem viva da mesma conversa e
  -- visivel para quem responde. O recorte historico e montado aqui, no
  -- servidor: o navegador nunca informa autor nem conteudo citado.
  if p_reply_to_message_id is not null then
    select * into v_reply
    from public.chat_mensagem
    where id = p_reply_to_message_id;

    if not found or v_reply.conversa_id <> p_conversa_id then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_REPLY_TARGET';
    end if;
    if v_reply.excluida_para_todos_em is not null then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_REPLY_TARGET';
    end if;
    if exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = v_reply.id and oculta.usuario_id = p_remetente_id
    ) then
      raise exception using errcode = '22023', message = 'CHAT_INVALID_REPLY_TARGET';
    end if;

    select u.nome::text into v_reply_nome
    from public.usuario u
    where u.id = v_reply.remetente_id;

    v_reply_tipo := v_reply.tipo;
    v_reply_conteudo := case
      when v_reply.tipo = 'VOICE' then ''
      else left(regexp_replace(v_reply.conteudo, '\s+', ' ', 'g'), 160)
    end;
  end if;

  insert into public.chat_mensagem(
    conversa_id,
    remetente_id,
    tipo,
    conteudo,
    client_message_id,
    reply_to_message_id,
    reply_snapshot_tipo,
    reply_snapshot_conteudo,
    reply_snapshot_remetente_nome,
    audio_path,
    audio_mime,
    audio_bytes,
    audio_duracao_ms
  ) values (
    p_conversa_id,
    p_remetente_id,
    v_tipo,
    v_conteudo,
    p_client_message_id,
    p_reply_to_message_id,
    v_reply_tipo,
    v_reply_conteudo,
    v_reply_nome,
    case when v_tipo = 'VOICE' then btrim(p_audio_path) end,
    case when v_tipo = 'VOICE' then p_audio_mime end,
    case when v_tipo = 'VOICE' then p_audio_bytes end,
    case when v_tipo = 'VOICE' then p_audio_duracao_ms end
  )
  on conflict on constraint chat_mensagem_idempotencia_key do nothing
  returning * into v_mensagem;

  if v_mensagem.id is null then
    select * into strict v_mensagem
    from public.chat_mensagem
    where chat_mensagem.conversa_id = p_conversa_id
      and chat_mensagem.remetente_id = p_remetente_id
      and chat_mensagem.client_message_id = p_client_message_id;
  else
    v_criada := true;
    update public.chat_conversa
    set last_message_at = v_mensagem.created_at,
        updated_at = v_mensagem.created_at
    where id = p_conversa_id;
  end if;

  return query
  select
    v_mensagem.id,
    v_mensagem.conversa_id,
    v_mensagem.remetente_id,
    v_mensagem.tipo,
    v_mensagem.conteudo,
    v_mensagem.client_message_id,
    v_mensagem.created_at,
    v_mensagem.editada_em,
    v_mensagem.excluida_para_todos_em,
    v_mensagem.reply_to_message_id,
    v_mensagem.reply_snapshot_tipo,
    v_mensagem.reply_snapshot_conteudo,
    v_mensagem.reply_snapshot_remetente_nome,
    v_mensagem.audio_mime,
    v_mensagem.audio_bytes,
    v_mensagem.audio_duracao_ms,
    v_criada;
end;
$$;


--
-- Name: chat_set_reaction(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_set_reaction(p_usuario_id uuid, p_mensagem_id uuid, p_reacao text) RETURNS TABLE(mensagem_id uuid, conversa_id uuid, reacoes jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_mensagem public.chat_mensagem%rowtype;
  v_reacao text := upper(coalesce(btrim(p_reacao), ''));
begin
  if v_reacao not in ('CORACAO', 'LEGAL', 'FELIZ', 'TRISTE') then
    raise exception using errcode = '22023', message = 'CHAT_INVALID_REACTION';
  end if;

  select * into v_mensagem from public.chat_mensagem where id = p_mensagem_id;
  if not found then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_NOT_FOUND';
  end if;

  if not exists (
    select 1 from public.chat_participante p
    where p.conversa_id = v_mensagem.conversa_id and p.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '42501', message = 'CHAT_FORBIDDEN';
  end if;

  if v_mensagem.excluida_para_todos_em is not null then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_UNAVAILABLE';
  end if;

  if exists (
    select 1 from public.chat_mensagem_oculta oculta
    where oculta.mensagem_id = p_mensagem_id and oculta.usuario_id = p_usuario_id
  ) then
    raise exception using errcode = '22023', message = 'CHAT_MESSAGE_UNAVAILABLE';
  end if;

  insert into public.chat_reacao(mensagem_id, usuario_id, reacao)
  values (p_mensagem_id, p_usuario_id, v_reacao)
  on conflict on constraint chat_reacao_unica_key do update
  set reacao = excluded.reacao,
      updated_at = clock_timestamp();

  return query
  select p_mensagem_id,
         v_mensagem.conversa_id,
         public.chat_reacoes_da_mensagem(p_mensagem_id, p_usuario_id);
end;
$$;


--
-- Name: chat_unread_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_unread_count(p_usuario_id uuid) RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with cursores as (
    select p.conversa_id,
           p.last_read_message_id,
           lida.created_at as lida_created_at,
           lida.id as lida_id
    from public.chat_participante p
    left join public.chat_mensagem lida on lida.id = p.last_read_message_id
    where p.usuario_id = p_usuario_id
  )
  select count(*)::bigint
  from public.chat_mensagem msg
  join cursores c on c.conversa_id = msg.conversa_id
  where msg.remetente_id <> p_usuario_id
    and msg.excluida_para_todos_em is null
    and not exists (
      select 1 from public.chat_mensagem_oculta oculta
      where oculta.mensagem_id = msg.id and oculta.usuario_id = p_usuario_id
    )
    and (
      c.lida_id is null
      or (msg.created_at, msg.id) > (c.lida_created_at, c.lida_id)
    );
$$;


--
-- Name: clientes_divida(integer[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clientes_divida(p_cliente_ids integer[] DEFAULT NULL::integer[], p_somente_devedores boolean DEFAULT false) RETURNS TABLE(cliente_id integer, total_em_aberto numeric, total_vencido numeric, quantidade_em_aberto integer, quantidade_vencida integer, tem_migrado boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH aberto AS (
    SELECT
      tc.cliente_id,
      GREATEST(
        GREATEST(
          round(tc.valor - GREATEST(COALESCE(tc.valor_acrescimos, 0), 0), 2),
          0
        ) - GREATEST(COALESCE(tc.valor_baixado, 0), 0),
        0
      ) AS em_aberto,
      (COALESCE(tc.vencimento_em, tc.data) AT TIME ZONE 'America/Fortaleza')::date
        < (now() AT TIME ZONE 'America/Fortaleza')::date AS vencido,
      tc.origem = 'ORIGEM_MIGRACAO' AS migrado
    FROM public.transacao_cliente tc
    WHERE tc.cliente_id IS NOT NULL
      AND tc.pendente
      AND (p_cliente_ids IS NULL OR tc.cliente_id = ANY (p_cliente_ids))
  )
  SELECT
    aberto.cliente_id,
    round(COALESCE(sum(aberto.em_aberto), 0), 2),
    round(COALESCE(sum(aberto.em_aberto) FILTER (WHERE aberto.vencido), 0), 2),
    count(*)::int,
    (count(*) FILTER (WHERE aberto.vencido))::int,
    bool_or(aberto.migrado)
  FROM aberto
  GROUP BY aberto.cliente_id
  HAVING NOT p_somente_devedores
      OR count(*) FILTER (WHERE aberto.vencido) > 0;
$$;


--
-- Name: conciliar_financeiro_stone_os(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conciliar_financeiro_stone_os(p_pagamento_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pagamento public.pagamento;
  v_os public.ordemservico;
  v_cliente public.cliente;
  v_tx public.transacao;
  v_banco bigint; v_transacao bigint; v_os_id integer;
  v_metodo text; v_valor numeric(14,2); v_erro text;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(87009, 1);
  SELECT ordemservicoid INTO v_os_id FROM public.pagamento WHERE id=p_pagamento_id;
  IF v_os_id IS NULL THEN RAISE EXCEPTION 'Pagamento de OS não encontrado.' USING ERRCODE='P0002'; END IF;
  -- Mesma ordem de locks usada no encaminhamento da OS: OS antes de pagamento.
  PERFORM pg_advisory_xact_lock(87001,v_os_id);
  SELECT * INTO v_os FROM public.ordemservico WHERE id=v_os_id FOR UPDATE;
  SELECT * INTO v_pagamento FROM public.pagamento WHERE id=p_pagamento_id FOR UPDATE;
  IF NOT v_pagamento.financeiro_pendente THEN RETURN; END IF;

  BEGIN
    -- Impede a reentrada do mesmo pagamento quando a conciliação muda o status
    -- da OS. Uma falha reverte esta marca junto de todos os efeitos financeiros.
    UPDATE public.pagamento SET financeiro_pendente=false,financeiro_erro=NULL WHERE id=p_pagamento_id;
    IF v_pagamento.status='ESTORNADO' THEN
      SELECT * INTO v_tx FROM public.transacao WHERE id=v_pagamento.transacao_os_id FOR UPDATE;
      IF FOUND AND NOT v_tx.is_deleted THEN
        IF v_tx.ordemservicoid IS DISTINCT FROM v_os_id OR v_tx.tipo::text <> 'RECEITA' THEN
          RAISE EXCEPTION 'O vínculo financeiro da Stone foi alterado. Confira o recebimento antes de estornar.';
        END IF;
        -- Usa o estorno normal para manter o histórico de baixa. O título
        -- gerado pela cobrança devolvida também é cancelado, liberando cobertura.
        IF NOT coalesce(v_tx.pendente,false) THEN
          PERFORM public.estornar_baixa_transacao(v_tx.id,NULL);
        END IF;
        UPDATE public.transacao SET is_deleted=true,updated_at=now() WHERE id=v_tx.id;
        INSERT INTO public.pagamento_evento(pagamentoid,tipo,payload)
          VALUES(p_pagamento_id,'TRANSACAO_RECEITA_ESTORNADA',jsonb_build_object('transacao_id',v_tx.id));
        PERFORM public.recalcular_status_financeiro_os(v_os_id);
      END IF;
    ELSIF v_pagamento.status='PAGO' AND v_pagamento.transacao_os_id IS NULL THEN
      PERFORM public.validar_novo_recebimento_os(v_os_id);
      SELECT * INTO v_cliente FROM public.cliente WHERE id=v_os.clienteid;
      SELECT id INTO v_banco FROM public.bancoconta WHERE ativo ORDER BY id LIMIT 1;
      IF v_cliente.id IS NULL OR v_banco IS NULL THEN
        RAISE EXCEPTION 'Defina cliente e conta bancária ativa para registrar o recebimento Stone.';
      END IF;
      v_metodo := upper(v_pagamento.metodo);
      v_metodo := CASE WHEN v_metodo LIKE '%PIX%' THEN 'PIX'
        WHEN v_metodo LIKE '%DEBITO%' THEN 'DEBITO' WHEN v_metodo LIKE '%CREDITO%' THEN 'CREDITO'
        WHEN v_metodo LIKE '%BOLETO%' THEN 'BOLETO' WHEN v_metodo LIKE '%TRANSF%' THEN 'TRANSFERENCIA'
        WHEN v_metodo LIKE '%DINHEIRO%' OR v_metodo LIKE '%CASH%' THEN 'DINHEIRO' ELSE v_metodo END;
      v_valor := round(v_pagamento.valor/100,2);
      IF v_valor IS NULL OR v_valor<=0 THEN RAISE EXCEPTION 'Valor Stone inválido.'; END IF;
      INSERT INTO public.transacao(descricao,valor,"valorLiquido",data,metodopagamento,categoria,tipo,
        cliente_id,banco_id,nomepagador,cpfcnpjpagador,ordemservicoid,pendente)
      VALUES('Recebimento OS #'||v_os.id||' - Maquineta Stone',v_valor,v_valor,
        coalesce(v_pagamento.confirmado_em,now()),v_metodo::public.metodo_pagamento,'ORDEM DE SERVIÇO','RECEITA',
        v_cliente.id,v_banco,coalesce(v_cliente.nomerazaosocial,'Cliente OS'),coalesce(v_cliente.cpfcnpj,'00000000000'),v_os.id,false)
      RETURNING id INTO v_transacao;
      UPDATE public.pagamento SET transacao_os_id=v_transacao WHERE id=p_pagamento_id;
      INSERT INTO public.pagamento_evento(pagamentoid,tipo,payload)
        VALUES(p_pagamento_id,'TRANSACAO_RECEITA_CRIADA',jsonb_build_object('transacao_id',v_transacao,'ordemservicoid',v_os_id));
      PERFORM public.recalcular_status_financeiro_os(v_os_id);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- O recebimento externo continua confirmado. O lançamento inteiro é
    -- revertido e a pendência fica visível e disponível para nova conciliação.
    GET STACKED DIAGNOSTICS v_erro=MESSAGE_TEXT;
    UPDATE public.pagamento SET financeiro_pendente=true,financeiro_erro=v_erro WHERE id=p_pagamento_id;
    IF v_pagamento.financeiro_erro IS DISTINCT FROM v_erro THEN
      INSERT INTO public.pagamento_evento(pagamentoid,tipo,payload)
        VALUES(p_pagamento_id,'FINANCEIRO_PENDENTE',jsonb_build_object('motivo',v_erro));
    END IF;
  END;
END;
$$;


--
-- Name: conciliar_movimento_ofx(bigint, text, bigint, numeric, text, integer, integer, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conciliar_movimento_ofx(p_movimento_id bigint, p_acao text, p_transacao_id bigint DEFAULT NULL::bigint, p_valor numeric DEFAULT NULL::numeric, p_metodopagamento text DEFAULT NULL::text, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_nova jsonb DEFAULT NULL::jsonb, p_usuario uuid DEFAULT NULL::uuid, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.conciliar_movimentos_ofx(
    ARRAY[p_movimento_id],
    p_acao,
    p_transacao_id,
    p_valor,
    p_metodopagamento,
    p_plano_de_conta_id,
    p_centro_custo_id,
    p_nova,
    p_usuario,
    p_observacao
  );
$$;


--
-- Name: FUNCTION conciliar_movimento_ofx(p_movimento_id bigint, p_acao text, p_transacao_id bigint, p_valor numeric, p_metodopagamento text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_nova jsonb, p_usuario uuid, p_observacao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conciliar_movimento_ofx(p_movimento_id bigint, p_acao text, p_transacao_id bigint, p_valor numeric, p_metodopagamento text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_nova jsonb, p_usuario uuid, p_observacao text) IS 'Conciliação de um movimento do extrato. Fachada de conciliar_movimentos_ofx com um elemento.';


--
-- Name: conciliar_movimentos_ofx(bigint[], text, bigint, numeric, text, integer, integer, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conciliar_movimentos_ofx(p_movimento_ids bigint[], p_acao text, p_transacao_id bigint DEFAULT NULL::bigint, p_valor numeric DEFAULT NULL::numeric, p_metodopagamento text DEFAULT NULL::text, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_nova jsonb DEFAULT NULL::jsonb, p_usuario uuid DEFAULT NULL::uuid, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_ids bigint[];
  v_qtd integer;
  v_primeiro public.ofx_movimento%ROWTYPE;
  v_imp public.ofx_importacao%ROWTYPE;
  v_tx public.transacao%ROWTYPE;
  v_acao text;
  v_dia date;
  v_data timestamptz;
  v_entrada boolean;
  v_soma_centavos bigint;
  v_alvo_centavos bigint;
  v_liquido_centavos bigint;
  v_saldo numeric(14,2);
  v_baixa numeric(14,2);
  v_resultado jsonb;
  v_transacao_id bigint;
  v_titulo_id bigint;
  v_tipo public.tipos_transacao;
  v_metodo public.metodo_pagamento;
  v_descricao text;
  v_acao_gravada text;
BEGIN
  v_acao := upper(btrim(coalesce(p_acao, '')));
  IF v_acao NOT IN ('VINCULAR', 'LIQUIDAR', 'CRIAR', 'IGNORAR') THEN
    RAISE EXCEPTION 'Ação de conciliação inválida: %.', p_acao USING ERRCODE = '22023';
  END IF;

  -- Sem nulo e sem repetição: o mesmo movimento mandado duas vezes dobraria a
  -- soma e faria a conferência de valor aprovar o que não deveria.
  SELECT array_agg(DISTINCT item ORDER BY item)
    INTO v_ids
    FROM unnest(coalesce(p_movimento_ids, '{}'::bigint[])) AS item
   WHERE item IS NOT NULL;

  IF v_ids IS NULL OR array_length(v_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'Informe ao menos um movimento do extrato.' USING ERRCODE = '22023';
  END IF;

  -- Trava na ordem do id: duas conciliações concorrentes que compartilhem
  -- movimentos pegam os bloqueios na mesma ordem e não se enroscam.
  PERFORM 1 FROM public.ofx_movimento
   WHERE id = ANY(v_ids)
   ORDER BY id
     FOR UPDATE;

  SELECT count(*) INTO v_qtd FROM public.ofx_movimento WHERE id = ANY(v_ids);
  IF v_qtd <> array_length(v_ids, 1) THEN
    RAISE EXCEPTION 'Movimento do extrato não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.ofx_movimento WHERE id = ANY(v_ids) AND status <> 'PENDENTE'
  ) THEN
    RAISE EXCEPTION 'Este movimento do extrato já foi resolvido.' USING ERRCODE = '23505';
  END IF;

  -- Um ato de conciliação pertence a um extrato. Sem isto, um id de importação
  -- qualquer viraria porta para conciliar linha de outra conta bancária.
  IF (SELECT count(DISTINCT importacao_id) FROM public.ofx_movimento WHERE id = ANY(v_ids)) > 1 THEN
    RAISE EXCEPTION
      'Os movimentos conciliados juntos precisam ser do mesmo extrato.' USING ERRCODE = '22023';
  END IF;

  /*
   * Entradas e saídas não se somam numa conciliação.
   *
   * Um crédito de R$ 100 com um débito de R$ 40 "dá" R$ 60, mas são dois fatos
   * de sentidos opostos e o extrato precisa mostrar os dois. Compensar um com o
   * outro esconderia dinheiro que entrou e dinheiro que saiu no mesmo número.
   */
  IF (
    SELECT count(DISTINCT (valor_centavos > 0))
      FROM public.ofx_movimento WHERE id = ANY(v_ids)
  ) > 1 THEN
    RAISE EXCEPTION
      'Não é possível conciliar entradas e saídas na mesma operação: escolha movimentos do mesmo sentido.'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_primeiro
    FROM public.ofx_movimento
   WHERE id = ANY(v_ids)
   ORDER BY sequencia, id
   LIMIT 1;

  SELECT sum(valor_centavos), max(data_postagem)
    INTO v_soma_centavos, v_dia
    FROM public.ofx_movimento
   WHERE id = ANY(v_ids);

  SELECT * INTO v_imp FROM public.ofx_importacao WHERE id = v_primeiro.importacao_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Importação não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  /*
   * A data do ato é a do ÚLTIMO movimento do grupo.
   *
   * Com uma linha só é a data dela, como sempre foi. Com duas, é o dia em que o
   * dinheiro terminou de sair da conta — datar pela primeira registraria a baixa
   * antes de o valor todo ter passado.
   *
   * Meio-dia no fuso da oficina, igual ao que a rota de baixa já faz: ancorar na
   * meia-noite deixaria o movimento sujeito a cair no dia anterior.
   */
  v_data := (v_dia::text || ' 12:00:00-03')::timestamptz;
  v_entrada := v_soma_centavos > 0;
  v_alvo_centavos := abs(v_soma_centavos);

  -- ------------------------------------------------------------- ignorar
  IF v_acao = 'IGNORAR' THEN
    UPDATE public.ofx_movimento
       SET status = 'IGNORADO',
           acao_conciliacao = 'IGNORAR',
           observacao = coalesce(nullif(btrim(coalesce(p_observacao, '')), ''), observacao),
           conciliado_em = now(),
           conciliado_por = p_usuario
     WHERE id = ANY(v_ids);

    RETURN jsonb_build_object(
      'movimento_id', v_ids[1],
      'movimento_ids', to_jsonb(v_ids),
      'status', 'IGNORADO'
    );
  END IF;

  -- ------------------------------------------------------------- vincular
  IF v_acao = 'VINCULAR' THEN
    IF p_transacao_id IS NULL THEN
      RAISE EXCEPTION 'Informe a transação a vincular.' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_tx FROM public.transacao
     WHERE id = p_transacao_id AND is_deleted = false FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
    END IF;

    /*
     * Aqui mora a proteção que era do índice único.
     *
     * Sob o `FOR UPDATE` acima, duas conciliações da mesma transação viram fila:
     * a segunda enxerga a marcação da primeira e é recusada. Os movimentos deste
     * mesmo ato ficam de fora da conferência — eles são o ato.
     */
    IF EXISTS (
      SELECT 1 FROM public.ofx_movimento
       WHERE transacao_id = p_transacao_id AND NOT (id = ANY(v_ids))
    ) THEN
      RAISE EXCEPTION
        'Esta transação já responde por outro movimento do extrato.' USING ERRCODE = '23505';
    END IF;

    IF coalesce(v_tx.pendente, false) THEN
      RAISE EXCEPTION
        'Este título ainda está em aberto. Use a baixa para liquidá-lo com o movimento do extrato.'
        USING ERRCODE = '22023';
    END IF;
    IF coalesce(v_tx.banco_id, 0) <> v_imp.banco_id THEN
      RAISE EXCEPTION
        'A transação não está na conta bancária deste extrato.' USING ERRCODE = '22023';
    END IF;
    IF (upper(v_tx.tipo::text) IN ('RECEITA', 'DEPOSITO')) <> v_entrada THEN
      RAISE EXCEPTION
        'O sentido não confere: o extrato mostra uma %, e a transação é %.',
        CASE WHEN v_entrada THEN 'entrada' ELSE 'saída' END, v_tx.tipo
        USING ERRCODE = '22023';
    END IF;

    /*
     * A soma do grupo tem que ser o dinheiro da transação.
     *
     * Com uma linha só é a conferência de sempre. Com duas, é ela que impede a
     * conciliação em grupo de virar um jeito de fechar o extrato com o valor
     * errado: R$ 743,16 + R$ 161,01 só valem pela transação de R$ 904,17.
     */
    v_liquido_centavos := round(public.transacao_valor_liquido_efetivo(v_tx) * 100)::bigint;
    IF v_liquido_centavos <> v_alvo_centavos THEN
      IF array_length(v_ids, 1) > 1 THEN
        RAISE EXCEPTION
          'A soma dos % movimentos é %, e a transação movimenta %.',
          array_length(v_ids, 1),
          round(v_alvo_centavos / 100.0, 2), round(v_liquido_centavos / 100.0, 2)
          USING ERRCODE = '22023';
      END IF;
      RAISE EXCEPTION
        'O valor não confere: o extrato mostra % e a transação movimenta %.',
        round(v_alvo_centavos / 100.0, 2), round(v_liquido_centavos / 100.0, 2)
        USING ERRCODE = '22023';
    END IF;

    v_transacao_id := v_tx.id;
    v_titulo_id := NULL;
    v_acao_gravada := 'VINCULAR';
  END IF;

  -- ------------------------------------------------------------- liquidar
  IF v_acao = 'LIQUIDAR' THEN
    IF p_transacao_id IS NULL THEN
      RAISE EXCEPTION 'Informe o título a liquidar.' USING ERRCODE = '22023';
    END IF;
    IF nullif(btrim(coalesce(p_metodopagamento, '')), '') IS NULL THEN
      RAISE EXCEPTION 'Informe a forma de pagamento da baixa.' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_tx FROM public.transacao
     WHERE id = p_transacao_id AND is_deleted = false;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Título não encontrado.' USING ERRCODE = 'P0002';
    END IF;
    IF NOT coalesce(v_tx.pendente, false) THEN
      RAISE EXCEPTION 'Este título já foi baixado.' USING ERRCODE = '23505';
    END IF;
    IF (upper(v_tx.tipo::text) IN ('RECEITA', 'DEPOSITO')) <> v_entrada THEN
      RAISE EXCEPTION
        'O sentido não confere: o extrato mostra uma %, e o título é %.',
        CASE WHEN v_entrada THEN 'entrada' ELSE 'saída' END, v_tx.tipo
        USING ERRCODE = '22023';
    END IF;

    v_saldo := round(
      public.transacao_valor_liquido_efetivo(v_tx) - coalesce(v_tx.valor_baixado, 0), 2);
    v_baixa := round(coalesce(p_valor, v_saldo), 2);

    /*
     * O dinheiro da baixa tem que ser exatamente o dinheiro do extrato.
     *
     * Sem esta conferência a conciliação aceitaria baixar R$ 5.000 com um
     * movimento de R$ 2.000 e marcar a linha como resolvida — o extrato
     * "fecharia" com R$ 3.000 que nunca passaram pela conta. Em grupo, o
     * dinheiro do extrato é a soma das linhas: N movimentos produzem UMA baixa
     * do total, não uma baixa cada.
     */
    IF round(v_baixa * 100)::bigint <> v_alvo_centavos THEN
      RAISE EXCEPTION
        'A baixa de % não corresponde ao movimento do extrato, que é de %.',
        v_baixa, round(v_alvo_centavos / 100.0, 2) USING ERRCODE = '22023';
    END IF;

    -- A baixa parcial, o saldo restante e a recusa por valor acima do saldo são
    -- todos da RPC de baixa. Aqui só se diz quanto foi pago.
    v_resultado := public.baixar_transacao_pendente(
      p_transacao_id := v_tx.id,
      p_pago_em := v_data,
      p_banco_id := v_imp.banco_id,
      p_metodopagamento := btrim(p_metodopagamento),
      p_plano_de_conta_id := p_plano_de_conta_id,
      p_centro_custo_id := p_centro_custo_id,
      p_baixado_por := p_usuario,
      p_valor := CASE WHEN v_baixa < v_saldo THEN v_baixa ELSE NULL END,
      p_valor_lancado := NULL
    );

    /*
     * Qual linha é o dinheiro?
     *
     * Na baixa de uma vez o próprio título vira o movimento de caixa: recebe
     * banco, data do pagamento e sai de pendente. Na parcial o título continua
     * aberto e quem carrega o dinheiro é a transação filha — é ela que aparece
     * no Fluxo, e é ela que o extrato representa.
     */
    IF coalesce((v_resultado->>'parcial')::boolean, false) THEN
      v_transacao_id := (v_resultado->>'baixa_id')::bigint;
      v_acao_gravada := 'BAIXA_PARCIAL';
    ELSE
      v_transacao_id := (v_resultado->>'id')::bigint;
      v_acao_gravada := 'LIQUIDAR';
    END IF;
    v_titulo_id := v_tx.id;

    IF v_transacao_id IS NULL THEN
      RAISE EXCEPTION
        'A baixa não devolveu o movimento de caixa correspondente.' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- ------------------------------------------------------------- criar
  IF v_acao = 'CRIAR' THEN
    v_descricao := nullif(btrim(coalesce(p_nova->>'descricao', '')), '');
    v_descricao := coalesce(
      v_descricao,
      nullif(btrim(coalesce(v_primeiro.memo, '')), ''),
      nullif(btrim(coalesce(v_primeiro.nome, '')), ''),
      'Movimento bancário importado'
    );

    /*
     * O sentido do extrato manda; o usuário só escolhe entre os dois tipos
     * daquele sentido. Deixar o tipo livre permitiria transformar um débito em
     * receita, o que inverteria o resultado da empresa a partir de um extrato.
     */
    v_tipo := CASE
      WHEN v_entrada AND upper(coalesce(p_nova->>'tipo', '')) = 'DEPOSITO' THEN 'DEPOSITO'
      WHEN v_entrada THEN 'RECEITA'
      WHEN upper(coalesce(p_nova->>'tipo', '')) = 'SAQUE' THEN 'SAQUE'
      ELSE 'DESPESA'
    END::public.tipos_transacao;

    IF nullif(btrim(coalesce(p_metodopagamento, '')), '') IS NOT NULL THEN
      BEGIN
        v_metodo := btrim(p_metodopagamento)::public.metodo_pagamento;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'Forma de pagamento inválida: %.', btrim(p_metodopagamento)
          USING ERRCODE = '22023';
      END;
    ELSE
      v_metodo := NULL;
    END IF;

    INSERT INTO public.transacao (
      descricao, valor, valor_base, "valorLiquido",
      valor_acrescimos, valor_descontos,
      data, competencia_em, vencimento_em, pago_em,
      tipo, pendente, banco_id, metodopagamento,
      categoria, categoria_id, plano_de_conta_id, centro_custo_id,
      cliente_id, fornecedor_id, nomepagador, cpfcnpjpagador,
      created_by, baixado_por
    ) VALUES (
      v_descricao,
      round(v_alvo_centavos / 100.0, 2),
      round(v_alvo_centavos / 100.0, 2),
      round(v_alvo_centavos / 100.0, 2),
      0, 0,
      v_data,
      coalesce(nullif(p_nova->>'competencia_em', '')::timestamptz, v_data),
      v_data, v_data,
      v_tipo, false, v_imp.banco_id, v_metodo,
      coalesce(nullif(btrim(coalesce(p_nova->>'categoria', '')), ''), 'NÃO RELACIONADO'),
      nullif(p_nova->>'categoria_id', '')::integer,
      nullif(p_nova->>'plano_de_conta_id', '')::integer,
      nullif(p_nova->>'centro_custo_id', '')::integer,
      nullif(p_nova->>'cliente_id', '')::integer,
      nullif(p_nova->>'fornecedor_id', '')::integer,
      -- Colunas NOT NULL herdadas do desenho antigo da tabela. Tarifa bancária
      -- não tem pagador, e inventar um cadastro para ela seria pior.
      coalesce(nullif(btrim(coalesce(p_nova->>'nomepagador', '')), ''),
               nullif(btrim(coalesce(v_primeiro.nome, '')), ''),
               'Extrato bancário'),
      coalesce(nullif(btrim(coalesce(p_nova->>'cpfcnpjpagador', '')), ''), ''),
      p_usuario, p_usuario
    ) RETURNING id INTO v_transacao_id;

    v_titulo_id := NULL;
    v_acao_gravada := 'CRIAR';
  END IF;

  -- A marcação fecha a operação, e vale para todas as linhas do ato de uma vez.
  UPDATE public.ofx_movimento
     SET status = 'CONCILIADO',
         acao_conciliacao = v_acao_gravada,
         transacao_id = v_transacao_id,
         titulo_origem_id = v_titulo_id,
         observacao = coalesce(nullif(btrim(coalesce(p_observacao, '')), ''), observacao),
         conciliado_em = now(),
         conciliado_por = p_usuario
   WHERE id = ANY(v_ids);

  RETURN jsonb_build_object(
    'movimento_id', v_ids[1],
    'movimento_ids', to_jsonb(v_ids),
    'status', 'CONCILIADO',
    'acao', v_acao_gravada,
    'transacao_id', v_transacao_id,
    'titulo_origem_id', v_titulo_id,
    'baixa', v_resultado
  );
END;
$_$;


--
-- Name: FUNCTION conciliar_movimentos_ofx(p_movimento_ids bigint[], p_acao text, p_transacao_id bigint, p_valor numeric, p_metodopagamento text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_nova jsonb, p_usuario uuid, p_observacao text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.conciliar_movimentos_ofx(p_movimento_ids bigint[], p_acao text, p_transacao_id bigint, p_valor numeric, p_metodopagamento text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_nova jsonb, p_usuario uuid, p_observacao text) IS 'Aplica uma decisão de conciliação a um conjunto de movimentos do extrato. Com mais de um, a soma das linhas — que precisam ser do mesmo extrato e do mesmo sentido — é o valor conferido contra a transação, e todas passam a apontar para o mesmo lançamento.';


--
-- Name: conciliar_stone_ao_desativar_fluxo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conciliar_stone_ao_desativar_fluxo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id bigint;
BEGIN
  IF OLD.habilitar_faturamento_os AND NOT NEW.habilitar_faturamento_os THEN
    FOR v_id IN SELECT p.id FROM public.pagamento p JOIN public.ordemservico o ON o.id=p.ordemservicoid
      WHERE p.financeiro_pendente AND NOT o.is_deleted AND o.status='PAGAMENTO' ORDER BY o.id,p.id LOOP
      PERFORM public.conciliar_financeiro_stone_os(v_id);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: conciliar_stone_ao_liberar_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conciliar_stone_ao_liberar_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id bigint;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  IF NEW.status='FATURAMENTO' OR (NEW.status='PAGAMENTO' AND NOT public.faturamento_os_habilitado()) THEN
    FOR v_id IN SELECT id FROM public.pagamento WHERE ordemservicoid=NEW.id AND financeiro_pendente ORDER BY id LOOP
      PERFORM public.conciliar_financeiro_stone_os(v_id);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: confirmar_pagamento_stone_os(bigint, text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirmar_pagamento_stone_os(p_pagamento_id bigint, p_status text, p_evento text, p_payload jsonb, p_registrar_receita boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_pagamento public.pagamento; v_os_id integer; v_ativo boolean; v_conciliar boolean;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(87009,1);
  SELECT ordemservicoid INTO v_os_id FROM public.pagamento WHERE id=p_pagamento_id;
  IF v_os_id IS NULL THEN RAISE EXCEPTION 'Pagamento de OS não encontrado.' USING ERRCODE='P0002'; END IF;
  IF p_status IS NULL OR p_status NOT IN ('PAGO','ESTORNADO','RECUSADO') THEN
    RAISE EXCEPTION 'Status de pagamento inválido.' USING ERRCODE='P0001';
  END IF;
  PERFORM pg_advisory_xact_lock(87001,v_os_id);
  PERFORM 1 FROM public.ordemservico WHERE id=v_os_id FOR UPDATE;
  SELECT * INTO v_pagamento FROM public.pagamento WHERE id=p_pagamento_id FOR UPDATE;
  -- Entregas atrasadas/repetidas não ressuscitam uma cobrança estornada.
  IF v_pagamento.status='ESTORNADO' AND p_status<>'ESTORNADO' THEN RETURN; END IF;
  IF v_pagamento.status='PAGO' AND p_status='RECUSADO' THEN RETURN; END IF;
  v_ativo := public.faturamento_os_habilitado();
  v_conciliar := v_pagamento.financeiro_pendente
    OR (p_status='ESTORNADO' AND v_pagamento.transacao_os_id IS NOT NULL)
    OR (p_status='PAGO' AND v_pagamento.status IS DISTINCT FROM 'PAGO' AND (v_ativo OR p_registrar_receita));
  UPDATE public.pagamento SET status=p_status,atualizado_em=now(),financeiro_pendente=v_conciliar,
    confirmado_em=CASE WHEN p_status='PAGO' THEN coalesce(confirmado_em,now()) ELSE confirmado_em END,
    nsu=coalesce(p_payload#>>'{data,transaction_id}',p_payload#>>'{data,id}',nsu),
    autorizacao=coalesce(p_payload#>>'{data,authorization_code}',autorizacao),
    bandeira=coalesce(p_payload#>>'{data,card,brand}',bandeira)
    WHERE id=p_pagamento_id;
  IF v_pagamento.status IS DISTINCT FROM p_status THEN
    INSERT INTO public.pagamento_evento(pagamentoid,tipo,payload)
      VALUES(p_pagamento_id,p_evento,coalesce(p_payload,'{}'));
  END IF;
  IF v_conciliar THEN
    PERFORM public.conciliar_financeiro_stone_os(p_pagamento_id);
  ELSIF p_status='PAGO' AND NOT v_ativo AND v_pagamento.status IS DISTINCT FROM 'PAGO' THEN
    -- Compatibilidade do webhook legado que apenas confirma a OS.
    UPDATE public.ordemservico SET status='CONCLUIDO' WHERE id=v_os_id AND status<>'CONCLUIDO';
  END IF;
END;
$$;


--
-- Name: consumir_estoque_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consumir_estoque_os(p_os_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto('ORDEM_SERVICO', p_os_id::bigint, 'OS #' || p_os_id);
  PERFORM public.consumir_estoque_os_interna(p_os_id);
END;
$$;


--
-- Name: consumir_estoque_os_interna(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consumir_estoque_os_interna(p_os_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  r record;
  q_baixada int;
  delta int;
begin
  for r in
    select p.produtoid, coalesce(p.quantidade, 0)::int as quantidade
      from public.osproduto p
     where p.ordemservicoid = p_os_id
  loop
    select b.quantidade
      into q_baixada
      from public.osproduto_baixa b
     where b.ordemservicoid = p_os_id
       and b.produtoid = r.produtoid;

    if q_baixada is null then
      delta := r.quantidade;
    else
      delta := r.quantidade - q_baixada;
    end if;

    if delta > 0 then
      update public.produto
         set estoque = estoque - delta
       where id = r.produtoid
         and estoque >= delta;

      if not found then
        raise exception 'Estoque insuficiente para o produto % (necessario: %, OS %)', r.produtoid, delta, p_os_id
          using errcode = 'P0001';
      end if;

      insert into public.osproduto_baixa (ordemservicoid, produtoid, quantidade)
      values (p_os_id, r.produtoid, r.quantidade)
      on conflict (ordemservicoid, produtoid) do update
        set quantidade = excluded.quantidade;
    elsif delta < 0 then
      update public.produto
         set estoque = estoque + (-delta)
       where id = r.produtoid;

      insert into public.osproduto_baixa (ordemservicoid, produtoid, quantidade)
      values (p_os_id, r.produtoid, r.quantidade)
      on conflict (ordemservicoid, produtoid) do update
        set quantidade = excluded.quantidade;
    end if;
  end loop;

  for r in
    select b.produtoid, b.quantidade
      from public.osproduto_baixa b
     where b.ordemservicoid = p_os_id
       and not exists (
         select 1
           from public.osproduto p
          where p.ordemservicoid = p_os_id
            and p.produtoid = b.produtoid
       )
  loop
    update public.produto
       set estoque = estoque + r.quantidade
     where id = r.produtoid;

    delete from public.osproduto_baixa
     where ordemservicoid = p_os_id
       and produtoid = r.produtoid;
  end loop;
end;
$$;


--
-- Name: converter_evento_financeiro_em_transacao(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.converter_evento_financeiro_em_transacao(p_eventoid bigint, p_usuarioid uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento public.eventos_financeiros%rowtype;
  v_transacaoid bigint;
BEGIN
  SELECT * INTO v_evento FROM public.eventos_financeiros WHERE id = p_eventoid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evento financeiro nao encontrado.'; END IF;
  IF NOT v_evento.pode_gerar_transacao THEN
    RAISE EXCEPTION 'Este evento nao pode gerar uma transacao.';
  END IF;
  IF v_evento.status <> 'ATIVO' OR v_evento.transacaoid IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento ja foi convertido ou cancelado.';
  END IF;

  INSERT INTO public.transacao
    (descricao, valor, "valorLiquido", data, tipo, ordemservicoid, pendente,
     categoria, nomepagador, cpfcnpjpagador, created_by, evento_financeiro_id)
  VALUES
    (v_evento.descricao, v_evento.valor, v_evento.valor, now(),
     v_evento.natureza::public.tipos_transacao, v_evento.ordemservicoid, true,
     'NAO RELACIONADO', 'Evento financeiro OS #' || v_evento.ordemservicoid, '',
     p_usuarioid, v_evento.id)
  RETURNING id INTO v_transacaoid;

  UPDATE public.eventos_financeiros
     SET status = 'CONVERTIDO', transacaoid = v_transacaoid, updated_at = now()
   WHERE id = v_evento.id;
  RETURN v_transacaoid;
END;
$$;


--
-- Name: criar_convite_assinatura_checklist(uuid, uuid, text, text, text, text, jsonb, timestamp with time zone, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.criar_convite_assinatura_checklist(p_documento_public_id uuid, p_convite_public_id uuid, p_cpf_hmac text, p_cpf_cifrado text, p_senha_hash text, p_senha_salt text, p_senha_parametros jsonb, p_expira_em timestamp with time zone, p_criado_por uuid, p_request_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS TABLE(convite_id bigint, convite_public_id uuid, documento_id bigint, criado_em timestamp with time zone, expira_em timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  doc public.checklist_documento%rowtype;
  novo public.checklist_documento_convite_assinatura%rowtype;
begin
  select * into doc
  from public.checklist_documento
  where public_id = p_documento_public_id
  for update;

  if not found then
    raise exception 'Versao do checklist nao encontrada.' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.checklist_documento posterior
    where posterior.ordemservico_id = doc.ordemservico_id
      and posterior.tipo = doc.tipo
      and posterior.versao > doc.versao
  ) then
    raise exception 'Somente a versao mais recente pode receber convite.' using errcode = '55000';
  end if;
  if exists (
    select 1 from public.checklist_documento_assinatura assinatura
    where assinatura.documento_id = doc.id
  ) then
    raise exception 'Esta versao ja foi assinada.' using errcode = '55000';
  end if;
  if p_expira_em <= now() then
    raise exception 'A validade do convite deve estar no futuro.' using errcode = '22023';
  end if;

  update public.checklist_documento_convite_assinatura convite
     set revogado_em = now(),
         revogado_por = p_criado_por,
         motivo_revogacao = 'REEMITIDO'
   where convite.documento_id = doc.id
     and convite.revogado_em is null
     and convite.consumido_em is null;

  insert into public.checklist_documento_convite_assinatura (
    public_id,
    documento_id,
    cpf_hmac,
    cpf_cifrado,
    senha_hash,
    senha_salt,
    senha_parametros,
    expira_em,
    criado_por
  ) values (
    p_convite_public_id,
    doc.id,
    p_cpf_hmac,
    p_cpf_cifrado,
    p_senha_hash,
    p_senha_salt,
    p_senha_parametros,
    p_expira_em,
    p_criado_por
  ) returning * into novo;

  insert into public.checklist_documento_evento (
    documento_id, tipo, usuario_id, request_ip, user_agent, metadados
  ) values (
    doc.id,
    'CONVITE_ASSINATURA_CRIADO',
    p_criado_por,
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    jsonb_build_object(
      'convitePublicId', novo.public_id,
      'expiraEm', novo.expira_em
    )
  );

  convite_id := novo.id;
  convite_public_id := novo.public_id;
  documento_id := novo.documento_id;
  criado_em := novo.criado_em;
  expira_em := novo.expira_em;
  return next;
end;
$$;


--
-- Name: criar_despesa_frete_venda(bigint, bigint, text, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.criar_despesa_frete_venda(p_venda_id bigint, p_receita_id bigint, p_descricao text, p_detalhe text, p_valor numeric, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_receita public.eventos_financeiros%ROWTYPE;
  v_evento public.eventos_financeiros%ROWTYPE;
BEGIN
  IF p_venda_id IS NULL OR p_venda_id <= 0 OR p_receita_id IS NULL OR p_receita_id <= 0
     OR nullif(btrim(p_descricao), '') IS NULL OR p_valor IS NULL
     OR p_valor::text IN ('NaN', 'Infinity', '-Infinity') OR round(p_valor, 2) <= 0 THEN
    RAISE EXCEPTION 'Informe a receita de frete, o título e um valor positivo para a despesa.' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_venda FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.venda_reconhece_receita(v_venda.status::text) THEN
    RAISE EXCEPTION 'Esta venda não aceita despesas de frete no status atual.' USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_receita FROM public.eventos_financeiros
   WHERE id = p_receita_id AND source_type = 'VENDA' AND source_id = p_venda_id
     AND ordemservicoid IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A receita não foi encontrada nesta venda.' USING ERRCODE = 'P0002';
  END IF;
  IF v_receita.origem <> 'FRETE' OR v_receita.natureza <> 'RECEITA' THEN
    RAISE EXCEPTION 'Somente receitas de frete podem receber esta despesa.' USING ERRCODE = '22023';
  END IF;
  IF v_receita.status <> 'ATIVO' THEN
    RAISE EXCEPTION 'A receita de frete não está ativa.' USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO public.eventos_financeiros
    (source_type, source_id, source_item_id, origem, natureza, natureza_dre,
     chave_origem, descricao, detalhe, valor, competencia_em, is_manual,
     pode_gerar_transacao, dados_snapshot, created_by)
  VALUES ('VENDA', p_venda_id, v_receita.id, 'FRETE', 'DESPESA',
    public.natureza_dre_de_evento('FRETE', 'DESPESA'), 'MANUAL:' || gen_random_uuid(),
    btrim(p_descricao), coalesce(nullif(btrim(p_detalhe), ''), 'Vinculada a ' || v_receita.descricao),
    round(p_valor, 2), v_receita.competencia_em, true, true,
    jsonb_build_object('despesa_frete_manual', true, 'receita_frete_valor', v_receita.valor,
      'dre_linha_codigo', '4.6', 'evento_receita_origem_id', v_receita.id, 'criado_em', now()), p_usuario)
  RETURNING * INTO v_evento;
  RETURN to_jsonb(v_evento);
END;
$$;


--
-- Name: criar_evento_financeiro_manual_venda(bigint, text, text, text, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.criar_evento_financeiro_manual_venda(p_venda_id bigint, p_natureza text, p_tipo text, p_descricao text, p_detalhe text, p_valor numeric, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_evento public.eventos_financeiros%ROWTYPE;
BEGIN
  IF p_natureza IS NULL OR p_natureza NOT IN ('RECEITA','DESPESA')
     OR p_tipo IS NULL OR p_tipo NOT IN ('PRODUTO','SERVICO','CONSUMO')
     OR (p_tipo = 'CONSUMO' AND p_natureza <> 'DESPESA')
     OR nullif(btrim(p_descricao),'') IS NULL OR p_valor IS NULL
     OR p_valor::text IN ('NaN','Infinity','-Infinity') OR round(p_valor,2) <= 0
     OR p_usuario IS NULL THEN
    RAISE EXCEPTION 'Informe natureza, tipo, título e valor positivo válidos.' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_venda FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002'; END IF;
  PERFORM set_config('app.audit_user_id', p_usuario::text, true);
  INSERT INTO public.eventos_financeiros
    (ordemservicoid,source_type,source_id,origem,natureza,natureza_dre,
     chave_origem,descricao,detalhe,valor,competencia_em,is_manual,
     pode_gerar_transacao,created_by,status,dados_snapshot)
  VALUES (NULL,'VENDA',p_venda_id,p_tipo,p_natureza,
    public.natureza_dre_de_evento(p_tipo,p_natureza),'MANUAL:' || gen_random_uuid(),
    btrim(p_descricao),nullif(btrim(p_detalhe),''),round(p_valor,2),
    coalesce(v_venda.datavenda,v_venda.createdat,now()),true,true,p_usuario,'ATIVO',
    jsonb_build_object('lancamento_avulso_manual',true,'tipo_informado',p_tipo,
      'consumo_de_estoque',false,'criado_em',now())) RETURNING * INTO v_evento;
  RETURN to_jsonb(v_evento);
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: usoconsumo_item; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.usoconsumo_item (
    id integer NOT NULL,
    titulo text NOT NULL,
    descricao text,
    referencia text,
    fabricante text,
    grupo_id integer,
    unidade public.unidade_medida DEFAULT 'UN'::public.unidade_medida NOT NULL,
    conservacao text DEFAULT 'NOVO'::text NOT NULL,
    codigobarras text,
    etiqueta text,
    local text,
    estoque integer DEFAULT 0 NOT NULL,
    estoqueminimo integer DEFAULT 0 NOT NULL,
    status_estoque text DEFAULT 'SEM_ESTOQUE'::text NOT NULL,
    precocompra numeric(14,4) DEFAULT 0 NOT NULL,
    ultimovalordecompra numeric(14,4),
    img_url text,
    ncm text,
    cest text,
    cfop_entrada text,
    origem_mercadoria text,
    csosn text,
    cst text,
    aliquotaicms numeric(8,4),
    cst_pis text,
    aliquota_pis numeric(8,4),
    modo_pis text,
    aliquota_por_unidade_pis numeric(14,4),
    cst_cofins text,
    aliquota_cofins numeric(8,4),
    modo_cofins text,
    aliquota_por_unidade_cofins numeric(14,4),
    cst_ibscbs text,
    cclass_trib text,
    aliquota_ibs_uf numeric(8,4),
    aliquota_ibs_municipio numeric(8,4),
    aliquota_cbs numeric(8,4),
    ativo boolean DEFAULT true NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    escopo text DEFAULT 'USOCONSUMO'::text NOT NULL,
    CONSTRAINT usoconsumo_item_aliquotas_check CHECK ((((aliquotaicms IS NULL) OR ((aliquotaicms >= (0)::numeric) AND (aliquotaicms <= (100)::numeric))) AND ((aliquota_pis IS NULL) OR ((aliquota_pis >= (0)::numeric) AND (aliquota_pis <= (100)::numeric))) AND ((aliquota_cofins IS NULL) OR ((aliquota_cofins >= (0)::numeric) AND (aliquota_cofins <= (100)::numeric))) AND ((aliquota_ibs_uf IS NULL) OR ((aliquota_ibs_uf >= (0)::numeric) AND (aliquota_ibs_uf <= (100)::numeric))) AND ((aliquota_ibs_municipio IS NULL) OR ((aliquota_ibs_municipio >= (0)::numeric) AND (aliquota_ibs_municipio <= (100)::numeric))) AND ((aliquota_cbs IS NULL) OR ((aliquota_cbs >= (0)::numeric) AND (aliquota_cbs <= (100)::numeric))))),
    CONSTRAINT usoconsumo_item_conservacao_check CHECK ((conservacao = ANY (ARRAY['NOVO'::text, 'USADO'::text, 'RECONDICIONADO'::text]))),
    CONSTRAINT usoconsumo_item_custos_check CHECK (((precocompra >= (0)::numeric) AND ((ultimovalordecompra IS NULL) OR (ultimovalordecompra >= (0)::numeric)))),
    CONSTRAINT usoconsumo_item_escopo_check CHECK ((escopo = ANY (ARRAY['USOCONSUMO'::text, 'GERAL'::text]))),
    CONSTRAINT usoconsumo_item_saldos_check CHECK (((estoque >= 0) AND (estoqueminimo >= 0))),
    CONSTRAINT usoconsumo_item_status_check CHECK ((status_estoque = ANY (ARRAY['OK'::text, 'BAIXO'::text, 'CRITICO'::text, 'SEM_ESTOQUE'::text]))),
    CONSTRAINT usoconsumo_item_titulo_check CHECK ((NULLIF(btrim(titulo), ''::text) IS NOT NULL))
);


--
-- Name: COLUMN usoconsumo_item.escopo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.usoconsumo_item.escopo IS 'A qual estoque simples o item pertence: USOCONSUMO ou GERAL (Geral/Avulso). Saldos sao independentes.';


--
-- Name: criar_item_usoconsumo(jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.criar_item_usoconsumo(p_item jsonb, p_estoque_inicial integer DEFAULT 0, p_created_by uuid DEFAULT NULL::uuid) RETURNS public.usoconsumo_item
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item public.usoconsumo_item%ROWTYPE;
  v_entrada_id bigint;
  v_entrada_item_id bigint;
  v_escopo text := upper(btrim(coalesce(p_item->>'escopo','USOCONSUMO')));
BEGIN
  IF nullif(btrim(p_item->>'titulo'),'') IS NULL THEN
    RAISE EXCEPTION 'Informe o titulo.' USING ERRCODE='22023';
  END IF;
  IF v_escopo NOT IN ('USOCONSUMO','GERAL') THEN
    RAISE EXCEPTION 'Escopo de estoque invalido: %.', v_escopo USING ERRCODE='22023';
  END IF;
  IF p_estoque_inicial IS NULL OR p_estoque_inicial < 0 THEN
    RAISE EXCEPTION 'Estoque inicial invalido.' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.usoconsumo_item (
    escopo,titulo,descricao,referencia,fabricante,grupo_id,unidade,conservacao,codigobarras,etiqueta,local,
    estoque,estoqueminimo,precocompra,ultimovalordecompra,ncm,cest,cfop_entrada,origem_mercadoria,
    csosn,cst,aliquotaicms,cst_pis,aliquota_pis,modo_pis,aliquota_por_unidade_pis,cst_cofins,
    aliquota_cofins,modo_cofins,aliquota_por_unidade_cofins,cst_ibscbs,cclass_trib,aliquota_ibs_uf,
    aliquota_ibs_municipio,aliquota_cbs,created_by,updated_by
  ) VALUES (
    v_escopo,
    btrim(p_item->>'titulo'),nullif(btrim(p_item->>'descricao'),''),nullif(btrim(p_item->>'referencia'),''),
    nullif(btrim(p_item->>'fabricante'),''),nullif(p_item->>'grupo_id','')::integer,
    coalesce(nullif(p_item->>'unidade','')::public.unidade_medida,'UN'),coalesce(nullif(p_item->>'conservacao',''),'NOVO'),
    nullif(btrim(p_item->>'codigobarras'),''),nullif(btrim(p_item->>'etiqueta'),''),nullif(btrim(p_item->>'local'),''),
    p_estoque_inicial,coalesce(nullif(p_item->>'estoqueminimo','')::integer,0),
    coalesce(nullif(p_item->>'precocompra','')::numeric,0),
    CASE WHEN p_estoque_inicial>0 THEN coalesce(nullif(p_item->>'precocompra','')::numeric,0) ELSE NULL END,
    nullif(btrim(p_item->>'ncm'),''),nullif(btrim(p_item->>'cest'),''),nullif(btrim(p_item->>'cfop_entrada'),''),
    nullif(btrim(p_item->>'origem_mercadoria'),''),nullif(btrim(p_item->>'csosn'),''),nullif(btrim(p_item->>'cst'),''),
    nullif(p_item->>'aliquotaicms','')::numeric,nullif(btrim(p_item->>'cst_pis'),''),nullif(p_item->>'aliquota_pis','')::numeric,
    nullif(btrim(p_item->>'modo_pis'),''),nullif(p_item->>'aliquota_por_unidade_pis','')::numeric,
    nullif(btrim(p_item->>'cst_cofins'),''),nullif(p_item->>'aliquota_cofins','')::numeric,
    nullif(btrim(p_item->>'modo_cofins'),''),nullif(p_item->>'aliquota_por_unidade_cofins','')::numeric,
    nullif(btrim(p_item->>'cst_ibscbs'),''),nullif(btrim(p_item->>'cclass_trib'),''),
    nullif(p_item->>'aliquota_ibs_uf','')::numeric,nullif(p_item->>'aliquota_ibs_municipio','')::numeric,
    nullif(p_item->>'aliquota_cbs','')::numeric,p_created_by,p_created_by
  ) RETURNING * INTO v_item;
  IF p_estoque_inicial>0 THEN
    INSERT INTO public.usoconsumo_entrada(escopo,tipo,origem,valor_total,created_by)
      VALUES(v_escopo,'SALDO_INICIAL','AJUSTE_RAPIDO',round(p_estoque_inicial*v_item.precocompra,2),p_created_by)
      RETURNING id INTO v_entrada_id;
    INSERT INTO public.usoconsumo_entrada_item(
      entrada_id,item_id,quantidade,unidade,valor_unitario_compra,valor_total,saldo_anterior,saldo_resultante,titulo
    ) VALUES(v_entrada_id,v_item.id,p_estoque_inicial,v_item.unidade,v_item.precocompra,
      round(p_estoque_inicial*v_item.precocompra,2),0,p_estoque_inicial,v_item.titulo)
    RETURNING id INTO v_entrada_item_id;
    INSERT INTO public.usoconsumo_movimento_entrada(
      entrada_id,entrada_item_id,item_id,tipo,quantidade,saldo_anterior,saldo_resultante,valor_unitario_compra,created_by
    ) VALUES(v_entrada_id,v_entrada_item_id,v_item.id,'ENTRADA',p_estoque_inicial,0,p_estoque_inicial,v_item.precocompra,p_created_by);
  END IF;
  RETURN v_item;
END $$;


--
-- Name: criar_nfe_de_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.criar_nfe_de_os(p_ordemservicoid integer) RETURNS bigint
    LANGUAGE plpgsql
    AS $$DECLARE
  v_nfe_id      bigint;
  v_numero      int;
  v_serie       int;
  v_modelo      public.enum_modelo_nfe;
  v_ambiente    public.enum_ambiente_nfe;
  v_chave       char(44);
  v_dataemissao timestamptz := now();
  v_cod_uf      text;
  v_cnpj_emit   text;
  v_ano         text;
  v_mes         text;
  v_mod         text;
  v_serie_str   text;
  v_numero_str  text;
  v_tp_emis     text;
  v_cod_nf      text;
  v_cdv         text;

  -- por enquanto fixo; depois você pode amarrar a empresa da OS
  v_empresaid   bigint := 1;

  v_cfg         nfe_config%ROWTYPE;
  v_emp         empresa%ROWTYPE;
BEGIN
  --------------------------------------------------------------------
  -- 1) Validar se a OS existe
  --------------------------------------------------------------------
  IF NOT EXISTS (SELECT 1 FROM ordemservico WHERE id = p_ordemservicoid) THEN
    RAISE EXCEPTION 'OS % não encontrada', p_ordemservicoid;
  END IF;

  --------------------------------------------------------------------
  -- 2) Carregar EMPRESA e NFE_CONFIG da empresa
  --------------------------------------------------------------------
  SELECT *
    INTO v_emp
  FROM empresa
  WHERE id = v_empresaid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Empresa % não encontrada na tabela EMPRESA', v_empresaid;
  END IF;

  SELECT *
    INTO v_cfg
  FROM nfe_config
  WHERE empresaid = v_empresaid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Configuração de NF-e (nfe_config) não encontrada para empresa %', v_empresaid;
  END IF;

  --------------------------------------------------------------------
  -- 3) Puxar parâmetros da config
  --------------------------------------------------------------------
  v_modelo   := v_cfg.modelo;
  v_serie    := v_cfg.serie;
  v_ambiente := v_cfg.ambiente;
  v_tp_emis  := v_cfg.tp_emis::text;   -- tp_emis é smallint na config

  -- cUF = 2 primeiros dígitos do código do município
  v_cod_uf := substring(coalesce(v_emp.codigomunicipio, '') FROM 1 FOR 2);

  IF v_cod_uf IS NULL OR length(v_cod_uf) <> 2 THEN
    RAISE EXCEPTION 'Código de município inválido para empresa % (codigomunicipio=%)',
      v_empresaid, v_emp.codigomunicipio;
  END IF;

  -- CNPJ somente números
  v_cnpj_emit := regexp_replace(coalesce(v_emp.cnpj, ''), '\D', '', 'g');

  IF length(v_cnpj_emit) <> 14 THEN
    RAISE EXCEPTION 'CNPJ da empresa % inválido (%). Deve ter 14 dígitos numéricos.',
      v_empresaid, v_emp.cnpj;
  END IF;

  v_ano := to_char(v_dataemissao, 'YY');
  v_mes := to_char(v_dataemissao, 'MM');
  v_mod := '55';  -- NF-e

  --------------------------------------------------------------------
  -- 4) Descobrir próximo número da NF-e a partir do nfe_config
  --    (ultimo_numero + 1)
  --------------------------------------------------------------------
  v_numero := v_cfg.ultimo_numero + 1;

  v_serie_str  := lpad(v_serie::text, 3, '0');
  v_numero_str := lpad(v_numero::text, 9, '0');

  --------------------------------------------------------------------
  -- 5) Gerar cNF (8 dígitos) aleatório
  --------------------------------------------------------------------
  v_cod_nf := lpad((floor(random() * 99999999))::int::text, 8, '0');

  --------------------------------------------------------------------
  -- 6) Montar chave de acesso SEM o DV
  --    cUF(2) + AAMM(4) + CNPJ(14) + mod(2) + série(3)
  --    + nNF(9) + tpEmis(1) + cNF(8)
  --------------------------------------------------------------------
  v_chave :=
    (v_cod_uf || v_ano || v_mes || v_cnpj_emit || v_mod ||
     v_serie_str || v_numero_str || v_tp_emis || v_cod_nf);

  --------------------------------------------------------------------
  -- 7) Calcular dígito verificador (módulo 11)
  --------------------------------------------------------------------
  DECLARE
    soma int := 0;
    peso int := 2;
    i    int;
    dig  int;
    ch_sem_dv text := v_chave;
  BEGIN
    FOR i IN REVERSE length(ch_sem_dv)..1 LOOP
      soma := soma + (substr(ch_sem_dv, i, 1)::int * peso);
      peso := peso + 1;
      IF peso > 9 THEN
        peso := 2;
      END IF;
    END LOOP;

    dig := 11 - (soma % 11);

    -- mantém a mesma regra que você já estava usando
    IF dig = 0 OR dig = 1 THEN
      dig := 0;
    END IF;

    v_cdv := dig::text;
  END;

  v_chave := v_chave || v_cdv;

  --------------------------------------------------------------------
  -- 8) Inserir na tabela NFE (RASCUNHO)
  --------------------------------------------------------------------
  INSERT INTO nfe (
    modelo,
    serie,
    numero,
    chave_acesso,
    ambiente,
    status,
    ordemservicoid,
    vendaid,
    clienteid,
    empresaid,
    dataemissao,
    total_produtos,
    total_servicos,
    total_nfe,
    xml_assinado,
    xml_autorizado
  )
  SELECT
    v_modelo,
    v_serie,
    v_numero,
    v_chave,
    v_ambiente,
    'RASCUNHO',
    os.id,
    NULL,
    os.clienteid,
    v_empresaid,          -- antes era 3 fixo
    v_dataemissao,
    0,
    0,
    0,
    NULL,
    NULL
  FROM ordemservico os
  WHERE os.id = p_ordemservicoid
  RETURNING id INTO v_nfe_id;

  --------------------------------------------------------------------
  -- 9) Atualizar nfe_config.ultimo_numero
  --------------------------------------------------------------------
  UPDATE nfe_config
     SET ultimo_numero = v_numero,
         updatedat     = now()
   WHERE id = v_cfg.id;

  RETURN v_nfe_id;
END;$$;


--
-- Name: criar_nfe_de_venda(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.criar_nfe_de_venda(p_vendaid integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$declare
  v_nfe_id      bigint;
  v_numero      int;
  v_serie       int;
  v_modelo      public.enum_modelo_nfe;
  v_ambiente    public.enum_ambiente_nfe;
  v_chave       char(44);
  v_dataemissao timestamptz := now();
  v_cod_uf      text;
  v_cnpj_emit   text;
  v_ano         text;
  v_mes         text;
  v_mod         text;
  v_serie_str   text;
  v_numero_str  text;
  v_tp_emis     text;
  v_cod_nf      text;
  v_cdv         text;

  -- por enquanto fixo; você pode amarrar depois
  v_empresaid   bigint := 1;

  v_cfg         public.nfe_config%rowtype;
  v_emp         public.empresa%rowtype;
  v_venda       public.venda%rowtype;
begin
  -- 1) Validar se a VENDA existe
  select * into v_venda
  from public.venda
  where id = p_vendaid;

  if not found then
    raise exception 'Venda % não encontrada', p_vendaid;
  end if;

  -- 2) Carregar EMPRESA e NFE_CONFIG
  select * into v_emp
  from public.empresa
  where id = v_empresaid;

  if not found then
    raise exception 'Empresa % não encontrada na tabela EMPRESA', v_empresaid;
  end if;

  select * into v_cfg
  from public.nfe_config
  where empresaid = v_empresaid;

  if not found then
    raise exception 'Configuração de NF-e (nfe_config) não encontrada para empresa %', v_empresaid;
  end if;

  -- 3) Puxar parâmetros da config
  v_modelo   := v_cfg.modelo;
  v_serie    := v_cfg.serie;
  v_ambiente := v_cfg.ambiente;
  v_tp_emis  := v_cfg.tp_emis::text;

  -- cUF = 2 primeiros dígitos do código do município
  v_cod_uf := substring(coalesce(v_emp.codigomunicipio, '') from 1 for 2);

  if v_cod_uf is null or length(v_cod_uf) <> 2 then
    raise exception 'Código de município inválido para empresa % (codigomunicipio=%)',
      v_empresaid, v_emp.codigomunicipio;
  end if;

  -- CNPJ somente números
  v_cnpj_emit := regexp_replace(coalesce(v_emp.cnpj, ''), '\D', '', 'g');

  if length(v_cnpj_emit) <> 14 then
    raise exception 'CNPJ da empresa % inválido (%). Deve ter 14 dígitos numéricos.',
      v_empresaid, v_emp.cnpj;
  end if;

  v_ano := to_char(v_dataemissao, 'YY');
  v_mes := to_char(v_dataemissao, 'MM');
  v_mod := '55';

  -- 4) Próximo número (ultimo_numero + 1)
  v_numero := v_cfg.ultimo_numero + 1;

  v_serie_str  := lpad(v_serie::text, 3, '0');
  v_numero_str := lpad(v_numero::text, 9, '0');

  -- 5) cNF (8 dígitos)
  v_cod_nf := lpad((floor(random() * 99999999))::int::text, 8, '0');

  -- 6) chave sem DV
  v_chave :=
    (v_cod_uf || v_ano || v_mes || v_cnpj_emit || v_mod ||
     v_serie_str || v_numero_str || v_tp_emis || v_cod_nf);

  -- 7) DV (módulo 11)
  declare
    soma int := 0;
    peso int := 2;
    i    int;
    dig  int;
    ch_sem_dv text := v_chave;
  begin
    for i in reverse length(ch_sem_dv)..1 loop
      soma := soma + (substr(ch_sem_dv, i, 1)::int * peso);
      peso := peso + 1;
      if peso > 9 then
        peso := 2;
      end if;
    end loop;

    dig := 11 - (soma % 11);

    if dig = 0 or dig = 1 then
      dig := 0;
    end if;

    v_cdv := dig::text;
  end;

  v_chave := v_chave || v_cdv;

  -- 8) Inserir NFE (RASCUNHO) vinculada à VENDA
  insert into public.nfe (
    modelo,
    serie,
    numero,
    chave_acesso,
    ambiente,
    status,
    ordemservicoid,
    vendaid,
    clienteid,
    empresaid,
    dataemissao,
    total_produtos,
    total_servicos,
    total_nfe,
    xml_assinado,
    xml_autorizado
  )
  values (
    v_modelo,
    v_serie,
    v_numero,
    v_chave,
    v_ambiente,
    'RASCUNHO',
    null,
    v_venda.id,
    v_venda.clienteid,
    v_empresaid,
    v_dataemissao,
    0,
    0,
    0,
    null,
    null
  )
  returning id into v_nfe_id;

  -- 9) Atualizar nfe_config.ultimo_numero
  update public.nfe_config
     set ultimo_numero = v_numero,
         updatedat     = now()
   where id = v_cfg.id;

  return v_nfe_id;
end;$$;


--
-- Name: dashboard_estoque_resumo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_estoque_resumo() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with base as (
    select
      p.id,
      coalesce(nullif(p.titulo, ''), 'Produto #' || p.id) as titulo,
      nullif(p.referencia, '') as referencia,
      p.estoque::numeric as estoque,
      greatest(0, p.estoqueminimo)::numeric as minimo,
      case
        when coalesce(p.ultimovalordecompra, 0) <> 0 then p.ultimovalordecompra
        else coalesce(p.precocompra, 0)
      end as custo
    from public.produto p
    where p.is_deleted = false
  ),
  calculado as (
    select
      b.*,
      greatest(0, b.estoque) * b.custo as valor,
      greatest(0, b.minimo - b.estoque) as reposicao_sugerida
    from base b
  ),
  reposicao as (
    select *
    from calculado
    where estoque <= minimo
    order by (estoque <= 0) desc, reposicao_sugerida desc, estoque asc, id asc
    limit 10
  ),
  maior_valor as (
    select *
    from calculado
    where valor > 0
    order by valor desc, id asc
    limit 8
  )
  select jsonb_build_object(
    'totais', (
      select jsonb_build_object(
        'produtos', count(*),
        'unidades', coalesce(sum(greatest(0, estoque)), 0),
        'valorEstoque', coalesce(sum(valor), 0),
        'zerados', count(*) filter (where estoque <= 0),
        'abaixoMinimo', count(*) filter (where estoque > 0 and estoque <= minimo),
        'adequados', count(*) filter (where estoque > 0 and estoque > minimo),
        'semCusto', count(*) filter (where custo <= 0)
      )
      from calculado
    ),
    'reposicao', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', r.id, 'titulo', r.titulo, 'referencia', r.referencia,
          'estoque', r.estoque, 'minimo', r.minimo, 'custo', r.custo,
          'valor', r.valor, 'reposicaoSugerida', r.reposicao_sugerida
        )
        order by (r.estoque <= 0) desc, r.reposicao_sugerida desc, r.estoque asc, r.id asc
      )
      from reposicao r
    ), '[]'::jsonb),
    'maiorValor', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', m.id, 'titulo', m.titulo, 'referencia', m.referencia,
          'estoque', m.estoque, 'minimo', m.minimo, 'custo', m.custo,
          'valor', m.valor, 'reposicaoSugerida', m.reposicao_sugerida
        )
        order by m.valor desc, m.id asc
      )
      from maior_valor m
    ), '[]'::jsonb)
  );
$$;


--
-- Name: desfazer_adiantamento(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.desfazer_adiantamento(p_id bigint, p_deleted_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_adiantamento public.transacao%ROWTYPE;
  v_titulos bigint[];
  v_documentos jsonb;
  v_titulo record;
  v_com_lancamento bigint[];
BEGIN
  SELECT * INTO v_adiantamento
    FROM public.transacao
   WHERE id = p_id AND is_deleted = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lançamento #% não encontrado.', p_id USING ERRCODE = 'P0002';
  END IF;
  IF NOT coalesce(v_adiantamento.eh_adiantamento, false) THEN
    RAISE EXCEPTION 'O lançamento #% não é uma antecipação.', p_id USING ERRCODE = 'P0001';
  END IF;

  SELECT array_agg(id) INTO v_titulos
    FROM public.transacao
   WHERE adiantamento_id = p_id AND is_deleted = false;

  -- O repasse mora numa transação própria. Reabrir o título em bloco a deixaria
  -- órfã no extrato, com dinheiro sem origem.
  SELECT array_agg(DISTINCT t.id) INTO v_com_lancamento
    FROM public.transacao t
    JOIN public.transacao f ON f.baixa_de_transacao_id = t.id AND f.is_deleted = false
   WHERE t.adiantamento_id = p_id AND t.is_deleted = false;

  IF v_com_lancamento IS NOT NULL THEN
    RAISE EXCEPTION
      'O título #% teve dinheiro lançado na conta pela baixa dele. Estorne essa baixa antes de desfazer a antecipação.',
      v_com_lancamento[1] USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object(
           'tipo', CASE WHEN t.ordemservicoid IS NOT NULL THEN 'OS' ELSE 'VENDA' END,
           'id', coalesce(t.ordemservicoid, t.vendaid))), '[]'::jsonb)
    INTO v_documentos
    FROM public.transacao t
   WHERE t.id = ANY (coalesce(v_titulos, ARRAY[]::bigint[]))
     AND coalesce(t.ordemservicoid, t.vendaid) IS NOT NULL;

  IF v_titulos IS NOT NULL THEN
    UPDATE public.transacao
       SET pendente = true,
           pago_em = NULL,
           baixado_por = NULL,
           adiantamento_id = NULL,
           updated_at = now()
     WHERE id = ANY (v_titulos);
  END IF;

  UPDATE public.transacao
     SET is_deleted = true,
         deleted_at = now(),
         deleted_by = p_deleted_by,
         updated_at = now()
   WHERE id = p_id;

  FOR v_titulo IN
    SELECT DISTINCT t.ordemservicoid, t.vendaid
      FROM public.transacao t
     WHERE t.id = ANY (coalesce(v_titulos, ARRAY[]::bigint[]))
  LOOP
    IF v_titulo.ordemservicoid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_os(v_titulo.ordemservicoid);
    ELSIF v_titulo.vendaid IS NOT NULL THEN
      PERFORM public.recalcular_status_financeiro_venda(v_titulo.vendaid);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'id', p_id,
    'titulos_revertidos', coalesce(array_length(v_titulos, 1), 0),
    'titulos', coalesce(to_jsonb(v_titulos), '[]'::jsonb),
    'documentos', v_documentos,
    'tipo', v_adiantamento.tipo::text
  );
END;
$$;


--
-- Name: FUNCTION desfazer_adiantamento(p_id bigint, p_deleted_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.desfazer_adiantamento(p_id bigint, p_deleted_by uuid) IS 'Exclui a transação de antecipação e devolve os títulos que ela liquidou para em aberto, numa operação só. Recusa quando algum título já foi baixado com lançamento próprio.';


--
-- Name: devolver_os_ao_desativar_faturamento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.devolver_os_ao_desativar_faturamento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.habilitar_faturamento_os AND NOT NEW.habilitar_faturamento_os THEN
    -- Desligar a etapa é uma decisão administrativa, não um acontecimento de
    -- cada OS: avisar a equipe uma vez por OS devolvida seria só ruído. A
    -- auditoria continua registrando tudo; apenas a notificação é silenciada.
    PERFORM set_config('app.devolucao_faturamento_em_massa', 'on', true);
    UPDATE public.ordemservico SET status = 'PAGAMENTO', updatedat = now()
    WHERE status = 'FATURAMENTO' AND NOT coalesce(is_deleted, false);
    PERFORM set_config('app.devolucao_faturamento_em_massa', 'off', true);
  END IF;
  -- A auditoria de configuração e de cada OS é feita pelos triggers existentes,
  -- na mesma transação, preservando o contexto do autor da requisição.
  RETURN NEW;
END;
$$;


--
-- Name: dre_classificacao_do_cadastro(integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_classificacao_do_cadastro(p_conta_id integer, p_grupo_id integer, p_competencia date) RETURNS TABLE(classificacao_id integer, origem text, regra_id integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH grupo AS (
    SELECT coalesce(p_grupo_id, (SELECT c.grupo_id FROM public.planosdeconta c WHERE c.id = p_conta_id)) AS id
  ),
  candidatos AS (
    SELECT 1 AS ordem, r.classificacao_id, 'CONTA'::text AS origem, r.id AS regra_id
      FROM public.plano_contas_classificacao_regra r
     WHERE p_conta_id IS NOT NULL
       AND r.conta_id = p_conta_id
       AND p_competencia >= r.vigencia_inicio
       AND (r.vigencia_fim IS NULL OR p_competencia < r.vigencia_fim)
    UNION ALL
    SELECT 2, c.classificacao_especifica_id, 'CONTA', NULL
      FROM public.planosdeconta c
     WHERE c.id = p_conta_id
       AND c.classificacao_especifica_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.plano_contas_classificacao_regra r WHERE r.conta_id = c.id)
    UNION ALL
    SELECT 3, r.classificacao_id, 'GRUPO', r.id
      FROM public.plano_contas_classificacao_regra r, grupo g
     WHERE g.id IS NOT NULL
       AND r.grupo_id = g.id
       AND p_competencia >= r.vigencia_inicio
       AND (r.vigencia_fim IS NULL OR p_competencia < r.vigencia_fim)
    UNION ALL
    SELECT 4, gr.classificacao_padrao_id, 'GRUPO', NULL
      FROM public.planosdecontagrupos gr, grupo g
     WHERE gr.id = g.id
       AND gr.classificacao_padrao_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.plano_contas_classificacao_regra r WHERE r.grupo_id = gr.id)
  )
  -- Qualificado: numa funcao SQL, um nome que serve a coluna e a parametro de
  -- saida ao mesmo tempo e ambiguo e o Postgres recusa.
  SELECT c.classificacao_id, c.origem, c.regra_id
    FROM candidatos c
   ORDER BY c.ordem
   LIMIT 1;
$$;


--
-- Name: FUNCTION dre_classificacao_do_cadastro(p_conta_id integer, p_grupo_id integer, p_competencia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_classificacao_do_cadastro(p_conta_id integer, p_grupo_id integer, p_competencia date) IS 'Classificacao efetiva de conta/grupo numa competencia: conta antes do grupo; regra com vigencia decide, e o campo do cadastro so vale quando o cadastro nao tem regra nenhuma.';


--
-- Name: dre_congelar_classificacao_legado(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_congelar_classificacao_legado(p_template_id integer, p_lote integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_congelados integer := 0;
  v_versao integer;
BEGIN
  IF p_lote IS NULL OR p_lote < 1 OR p_lote > 5000 THEN
    RAISE EXCEPTION 'Tamanho de lote invalido: %.', p_lote USING ERRCODE = '22023';
  END IF;

  SELECT max(versao_catalogo) INTO v_versao FROM public.classificacoes_resultado;

  WITH alvo AS (
    SELECT e.id AS evento_id,
           coalesce(
             e.dre_linha_id,
             (SELECT mp.linha_id
                FROM public.dre_mapeamento mp
               WHERE mp.template_id = p_template_id
                 AND mp.ativo
                 AND mp.origem_tipo = 'EVENTO_ORIGEM'
                 AND mp.origem_valor = e.origem || ':' || e.natureza
                 AND (mp.vigencia_inicio IS NULL OR e.competencia_em >= mp.vigencia_inicio)
                 AND (mp.vigencia_fim IS NULL OR e.competencia_em <= mp.vigencia_fim)
               LIMIT 1)
           ) AS linha_id
      FROM public.eventos_financeiros e
     WHERE e.status IN ('ATIVO', 'CONVERTIDO')
       AND NOT EXISTS (
         SELECT 1 FROM public.eventos_financeiros_classificacao ec
          WHERE ec.evento_id = e.id AND ec.vigente)
     ORDER BY e.id
     LIMIT p_lote
  )
  INSERT INTO public.eventos_financeiros_classificacao
    (evento_id, template_id, linha_id, resultado, motivo, versao_catalogo, origem_resolucao)
  SELECT a.evento_id, p_template_id, a.linha_id,
         CASE WHEN a.linha_id IS NULL THEN 'PENDENTE' ELSE 'CLASSIFICADO' END,
         CASE WHEN a.linha_id IS NULL
              THEN 'Congelado do legado sem destino: o lancamento ja nao entrava em nenhum total.'
         END,
         coalesce(v_versao, 1), 'LEGADO'
    FROM alvo a;

  GET DIAGNOSTICS v_congelados = ROW_COUNT;
  RETURN v_congelados;
END;
$$;


--
-- Name: FUNCTION dre_congelar_classificacao_legado(p_template_id integer, p_lote integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_congelar_classificacao_legado(p_template_id integer, p_lote integer) IS 'Congela em dado a resolucao que a DRE ja usa, em lotes retomaveis. Nao altera valor, competencia nem dre_linha_id. Evento sem destino e congelado como PENDENTE, preservando sua situacao original.';


--
-- Name: dre_destino_da_classificacao(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_destino_da_classificacao(p_template_id integer, p_classificacao_id integer) RETURNS TABLE(linha_id integer, exclui boolean, motivo text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total integer;
BEGIN
  SELECT count(*) INTO v_total
    FROM public.dre_mapeamento m
   WHERE m.template_id = p_template_id
     AND m.origem_tipo = 'CLASSIFICACAO_RESULTADO'
     AND m.classificacao_resultado_id = p_classificacao_id
     AND m.ativo;

  IF v_total > 1 THEN
    RAISE EXCEPTION
      'Classificacao % tem % destinos ativos no template %.',
      p_classificacao_id, v_total, p_template_id
      USING ERRCODE = '23514';
  END IF;

  RETURN QUERY
  SELECT m.linha_id, m.exclui_do_resultado,
         CASE WHEN m.exclui_do_resultado THEN m.observacao ELSE NULL END
    FROM public.dre_mapeamento m
   WHERE m.template_id = p_template_id
     AND m.origem_tipo = 'CLASSIFICACAO_RESULTADO'
     AND m.classificacao_resultado_id = p_classificacao_id
     AND m.ativo;
END;
$$;


--
-- Name: dre_destino_do_cadastro(integer, integer, date, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_destino_do_cadastro(p_conta_id integer, p_grupo_id integer, p_competencia date, p_natureza text DEFAULT NULL::text, p_template_id integer DEFAULT NULL::integer) RETURNS TABLE(situacao text, linha_id integer, classificacao_id integer, origem text, regra_id integer, motivo text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_grupo     integer := p_grupo_id;
  v_template  integer;
  v_class     integer;
  v_origem    text;
  v_regra     integer;
  v_naturezas text[];
  v_nome      text;
  v_linha     integer;
  v_exclui    boolean;
  v_motivo    text;
BEGIN
  IF p_conta_id IS NULL AND p_grupo_id IS NULL THEN
    RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer, NULL::text, NULL::integer,
      'Lancamento sem conta do plano de contas.'::text;
    RETURN;
  END IF;

  IF p_conta_id IS NOT NULL THEN
    SELECT c.grupo_id INTO v_grupo FROM public.planosdeconta c WHERE c.id = p_conta_id;
    IF NOT FOUND THEN
      RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer, NULL::text, NULL::integer,
        'Conta inexistente.'::text;
      RETURN;
    END IF;
  END IF;

  SELECT r.classificacao_id, r.origem, r.regra_id
    INTO v_class, v_origem, v_regra
    FROM public.dre_classificacao_do_cadastro(p_conta_id, v_grupo, coalesce(p_competencia, current_date)) r;

  IF v_class IS NULL THEN
    -- Ultimo degrau: o mapeamento do grupo, lido do mesmo jeito que a
    -- sincronizacao sempre leu. E o que mantem a DRE identica enquanto ninguem
    -- classificar nada.
    SELECT mp.linha_id, coalesce(mp.exclui_do_resultado, false)
      INTO v_linha, v_exclui
      FROM public.dre_mapeamento mp
     WHERE mp.origem_tipo = 'PLANO_GRUPO' AND mp.origem_id = v_grupo AND mp.ativo
     LIMIT 1;

    IF NOT FOUND THEN
      RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer, NULL::text, NULL::integer,
        'Nem a conta nem o grupo tem linha da DRE definida.'::text;
    ELSIF v_exclui THEN
      RETURN QUERY SELECT 'EXCLUIDO'::text, NULL::integer, NULL::integer, 'MAPEAMENTO_GRUPO'::text,
        NULL::integer, 'Grupo marcado como fora do resultado.'::text;
    ELSIF v_linha IS NULL THEN
      RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer, 'MAPEAMENTO_GRUPO'::text,
        NULL::integer, 'O mapeamento do grupo nao aponta linha.'::text;
    ELSE
      RETURN QUERY SELECT 'CLASSIFICADO'::text, v_linha, NULL::integer, 'MAPEAMENTO_GRUPO'::text,
        NULL::integer, NULL::text;
    END IF;
    RETURN;
  END IF;

  SELECT c.naturezas, c.nome INTO v_naturezas, v_nome
    FROM public.classificacoes_resultado c
   WHERE c.id = v_class AND c.ativo;

  IF v_naturezas IS NULL THEN
    RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, v_class, v_origem, v_regra,
      'Classificacao inativa ou inexistente.'::text;
    RETURN;
  END IF;

  IF p_natureza IS NOT NULL AND NOT (p_natureza = ANY (v_naturezas)) THEN
    RETURN QUERY SELECT 'INCOMPATIVEL'::text, NULL::integer, v_class, v_origem, v_regra,
      format('%s nao aceita lancamento de %s.', v_nome, lower(p_natureza));
    RETURN;
  END IF;

  v_template := coalesce(
    p_template_id,
    (SELECT t.id FROM public.dre_template t WHERE t.ativo ORDER BY t.versao DESC LIMIT 1));

  SELECT d.linha_id, d.exclui, d.motivo
    INTO v_linha, v_exclui, v_motivo
    FROM public.dre_destino_da_classificacao(v_template, v_class) d;

  IF v_exclui IS NULL THEN
    RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, v_class, v_origem, v_regra,
      format('%s nao tem linha no template ativo.', v_nome);
  ELSIF v_exclui THEN
    RETURN QUERY SELECT 'EXCLUIDO'::text, NULL::integer, v_class, v_origem, v_regra,
      coalesce(v_motivo, 'Nao compoe o resultado.');
  ELSE
    RETURN QUERY SELECT 'CLASSIFICADO'::text, v_linha, v_class, v_origem, v_regra, NULL::text;
  END IF;
END;
$$;


--
-- Name: FUNCTION dre_destino_do_cadastro(p_conta_id integer, p_grupo_id integer, p_competencia date, p_natureza text, p_template_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_destino_do_cadastro(p_conta_id integer, p_grupo_id integer, p_competencia date, p_natureza text, p_template_id integer) IS 'Destino de conta/grupo numa competencia: classificacao da conta, do grupo e, sem nenhuma, o mapeamento antigo do grupo. Regra unica da sincronizacao, da exclusao do resultado, da tela, da previa e da fila.';


--
-- Name: dre_gravar_classificacao_evento(bigint, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_gravar_classificacao_evento(p_evento_id bigint, p_template_id integer, p_usuario uuid DEFAULT NULL::uuid, p_origem_forcada text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_resolucao record;
  v_anterior  bigint;
  v_versao    integer;
  v_novo      bigint;
BEGIN
  -- Um evento por vez, na mesma ordem em todo lugar: evita que duas gravacoes
  -- simultaneas troquem a revisao vigente uma por cima da outra.
  PERFORM 1 FROM public.eventos_financeiros WHERE id = p_evento_id FOR UPDATE;

  SELECT * INTO v_resolucao
    FROM public.dre_resolver_evento(p_evento_id, p_template_id);

  SELECT max(versao_catalogo) INTO v_versao FROM public.classificacoes_resultado;

  SELECT id INTO v_anterior
    FROM public.eventos_financeiros_classificacao
   WHERE evento_id = p_evento_id AND vigente;

  UPDATE public.eventos_financeiros_classificacao
     SET vigente = false
   WHERE evento_id = p_evento_id AND vigente;

  INSERT INTO public.eventos_financeiros_classificacao
    (evento_id, classificacao_id, regra_id, conta_id, grupo_id, template_id, linha_id,
     resultado, motivo, versao_catalogo, classificado_por, origem_resolucao,
     reclassificacao_de_id)
  VALUES
    (p_evento_id, v_resolucao.classificacao_id, v_resolucao.regra_id,
     v_resolucao.conta_id, v_resolucao.grupo_id, p_template_id, v_resolucao.linha_id,
     v_resolucao.resultado, v_resolucao.motivo, coalesce(v_versao, 1), p_usuario,
     coalesce(p_origem_forcada, v_resolucao.origem_resolucao), v_anterior)
  RETURNING id INTO v_novo;

  UPDATE public.eventos_financeiros
     SET dre_linha_id = v_resolucao.linha_id,
         updated_at = now()
   WHERE id = p_evento_id
     AND dre_linha_id IS DISTINCT FROM v_resolucao.linha_id;

  RETURN v_novo;
END;
$$;


--
-- Name: dre_lancamentos_por_linha(integer, integer[], timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_lancamentos_por_linha(p_template_id integer, p_linha_ids integer[], p_de timestamp with time zone, p_ate timestamp with time zone) RETURNS TABLE(id bigint, linha_id integer, competencia_em timestamp with time zone, origem text, natureza text, natureza_dre text, descricao text, detalhe text, valor numeric, source_type text, source_id bigint, ordemservicoid integer, transacaoid bigint, is_manual boolean, estorno_de_id bigint, sem_custo boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_modo record;
BEGIN
  SELECT * INTO v_modo FROM public.dre_modo_apuracao();

  RETURN QUERY
  SELECT l.id, l.linha_id, l.competencia_em, l.origem, l.natureza, l.natureza_dre,
         l.descricao, l.detalhe, l.valor, l.source_type, l.source_id,
         l.ordemservicoid, l.transacaoid, l.is_manual, l.estorno_de_id,
         coalesce((l.dados_snapshot ->> 'custo_nao_informado')::boolean, false) AS sem_custo
    FROM (
      SELECT e.*,
             public.dre_linha_do_evento(
               e.id, p_template_id, v_modo.estado, v_modo.vigencia_inicio) AS linha_id
        FROM public.eventos_financeiros e
       WHERE e.status IN ('ATIVO', 'CONVERTIDO')
         AND e.competencia_em IS NOT NULL
         AND e.competencia_em >= p_de
         AND e.competencia_em <= p_ate
    ) l
   WHERE l.linha_id = ANY (p_linha_ids)
   ORDER BY l.competencia_em DESC, l.id DESC;
END;
$$;


--
-- Name: FUNCTION dre_lancamentos_por_linha(p_template_id integer, p_linha_ids integer[], p_de timestamp with time zone, p_ate timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_lancamentos_por_linha(p_template_id integer, p_linha_ids integer[], p_de timestamp with time zone, p_ate timestamp with time zone) IS 'Lancamentos de uma linha no periodo. Resolve a linha por dre_linha_do_evento, a mesma da soma: o detalhamento nao pode divergir do total.';


--
-- Name: dre_linha_da_transacao(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_linha_da_transacao(p_transacaoid bigint) RETURNS TABLE(papel text, documento_tipo text, documento_id bigint, linha_id integer, codigo text, nome text, natureza_dre text, valor numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_modo record;
  v_template integer;
BEGIN
  SELECT * INTO v_modo FROM public.dre_modo_apuracao();
  SELECT t.id INTO v_template
    FROM public.dre_template t WHERE t.ativo ORDER BY t.versao DESC, t.id DESC LIMIT 1;

  RETURN QUERY
  WITH tx AS (
    SELECT * FROM public.transacao WHERE id = p_transacaoid
  ),
  -- Documentos que esta transacao LIQUIDA. Pagamento multiplo cobre varios (o
  -- rateio diz quais); pagamento comum cobre um; avulso nao cobre nenhum.
  --
  -- `evento_financeiro_id IS NULL` e o que separa liquidar de materializar.
  -- Uma despesa da OS — servico terceirizado, comissao — vira transacao com
  -- `ordemservicoid` preenchido, mas ela nao paga a OS: ela E aquela despesa, e
  -- aponta para o evento que virou. Sem este filtro, abrir os R$ 200 de um
  -- terceirizado mostraria tambem a receita inteira da OS, como se aquele
  -- pagamento a tivesse quitado. O papel dela e DIRETO, so.
  documentos AS (
    SELECT 'OS'::text AS tipo, t.ordemservicoid::bigint AS id
      FROM tx t WHERE t.ordemservicoid IS NOT NULL AND t.evento_financeiro_id IS NULL
    UNION
    SELECT 'VENDA'::text, t.vendaid::bigint
      FROM tx t WHERE t.vendaid IS NOT NULL AND t.evento_financeiro_id IS NULL
    UNION
    SELECT r.tipo_documento::text, r.documento_id::bigint
      FROM public.pagamento_multiplo_rateio r
     WHERE r.transacao_id = p_transacaoid
  ),
  eventos AS (
    SELECT 'DIRETO'::text AS papel, NULL::text AS doc_tipo, NULL::bigint AS doc_id,
           e.id AS evento_id, e.valor
      FROM public.eventos_financeiros e
     WHERE e.status IN ('ATIVO', 'CONVERTIDO')
       AND ((e.source_type = 'TRANSACAO' AND e.source_id = p_transacaoid)
            OR e.transacaoid = p_transacaoid)
    UNION ALL
    SELECT 'DOCUMENTO'::text, d.tipo, d.id, e.id, e.valor
      FROM documentos d
      JOIN public.eventos_financeiros e
        -- OS tem DOIS vinculos possiveis. `ordemservicoid` e a coluna original,
        -- de quando o livro so servia a OS; `source_type`/`source_id` vieram na
        -- 20260802160000, que generalizou a tabela mas nao fez backfill das
        -- linhas antigas. No Demir isso e a maioria: 225 dos 377 eventos de OS
        -- tem `source_type` nulo. Casar so pelo par novo perderia todos eles —
        -- e a OS apareceria como se nao tivesse lancamento nenhum.
        -- Venda nasceu depois da generalizacao e nao tem esse legado.
        ON (d.tipo = 'OS'    AND (e.ordemservicoid = d.id
                                  OR (e.source_type = 'ORDEM_SERVICO' AND e.source_id = d.id)))
        OR (d.tipo = 'VENDA' AND e.source_type = 'VENDA' AND e.source_id = d.id)
     WHERE e.status IN ('ATIVO', 'CONVERTIDO')
       -- Ja contado como DIRETO: e a despesa que esta propria transacao pagou.
       AND e.transacaoid IS DISTINCT FROM p_transacaoid
  ),
  resolvidos AS (
    SELECT ev.papel, ev.doc_tipo, ev.doc_id, ev.valor,
           public.dre_linha_do_evento(
             ev.evento_id, v_template, v_modo.estado, v_modo.vigencia_inicio) AS linha_id
      FROM eventos ev
  )
  SELECT r.papel, r.doc_tipo, r.doc_id, dl.id, dl.codigo, dl.nome, dl.natureza_dre,
         round(sum(r.valor), 2) AS valor
    FROM resolvidos r
    JOIN public.dre_linha dl ON dl.id = r.linha_id
   GROUP BY r.papel, r.doc_tipo, r.doc_id, dl.id, dl.codigo, dl.nome, dl.natureza_dre
   ORDER BY r.doc_id NULLS FIRST, dl.codigo;
END;
$_$;


--
-- Name: FUNCTION dre_linha_da_transacao(p_transacaoid bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_linha_da_transacao(p_transacaoid bigint) IS 'Como uma transacao aparece na DRE. papel=DIRETO: ela e o fato, e o valor dela e o valor na linha. papel=DOCUMENTO: ela apenas liquida OS/venda, e o que entra na DRE sao os lancamentos do documento, com o valor deles. Mesma resolucao de linha que dre_somar_por_linha.';


--
-- Name: dre_linha_do_evento(bigint, integer, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_linha_do_evento(p_evento_id bigint, p_template_id integer, p_estado text, p_vigencia date) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
           WHEN p_estado = 'ATIVO'
                AND p_vigencia IS NOT NULL
                AND e.competencia_em >= p_vigencia
           THEN (SELECT ec.linha_id
                   FROM public.eventos_financeiros_classificacao ec
                  WHERE ec.evento_id = e.id AND ec.vigente)
           ELSE coalesce(
             e.dre_linha_id,
             (SELECT mp.linha_id
                FROM public.dre_mapeamento mp
               WHERE mp.template_id = p_template_id
                 AND mp.ativo
                 AND mp.origem_tipo = 'EVENTO_ORIGEM'
                 AND mp.origem_valor = e.origem || ':' || e.natureza
                 AND (mp.vigencia_inicio IS NULL OR e.competencia_em >= mp.vigencia_inicio)
                 AND (mp.vigencia_fim IS NULL OR e.competencia_em <= mp.vigencia_fim)
               LIMIT 1))
         END
    FROM public.eventos_financeiros e
   WHERE e.id = p_evento_id;
$$;


--
-- Name: FUNCTION dre_linha_do_evento(p_evento_id bigint, p_template_id integer, p_estado text, p_vigencia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_linha_do_evento(p_evento_id bigint, p_template_id integer, p_estado text, p_vigencia date) IS 'Linha da DRE de um evento, unica para soma, detalhamento e badge. Em LEGADO usa dre_linha_id e o mapeamento da origem; em ATIVO usa a revisao vigente a partir da data de vigencia.';


--
-- Name: dre_modo_apuracao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_modo_apuracao() RETURNS TABLE(estado text, vigencia_inicio date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY SELECT i.estado, i.vigencia_inicio FROM public.dre_implantacao i LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'Implantacao da DRE nao configurada neste banco: nao e possivel decidir o modo de apuracao.'
      USING ERRCODE = 'P0002';
  END IF;
END;
$$;


--
-- Name: dre_pendencias(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_pendencias(p_de timestamp with time zone, p_ate timestamp with time zone) RETURNS TABLE(motivo text, descricao text, escopo text, quantidade bigint, valor numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_template integer;
  v_modo record;
BEGIN
  SELECT * INTO v_modo FROM public.dre_modo_apuracao();
  SELECT id INTO v_template FROM public.dre_template WHERE ativo ORDER BY versao DESC LIMIT 1;

  RETURN QUERY
  -- Cadastro: nao depende do periodo. Um grupo sem destino e um problema hoje,
  -- mesmo que ninguem tenha lancado nele ainda.
  SELECT 'GRUPO_SEM_DESTINO'::text,
         'Grupo ativo sem linha da DRE: as contas dele sem excecao nao tem para onde ir.'::text,
         'CADASTRO'::text,
         count(*)::bigint,
         NULL::numeric
    FROM public.planosdecontagrupos g
   WHERE g.ativo
     AND (SELECT d.situacao FROM public.dre_destino_do_cadastro(NULL, g.id, current_date) d) = 'PENDENTE'
  HAVING count(*) > 0;

  RETURN QUERY
  SELECT 'CONTA_SEM_REGRA'::text,
         'Conta ativa sem linha da DRE: nem a conta nem o grupo definem destino.'::text,
         'CADASTRO'::text,
         count(*)::bigint,
         NULL::numeric
    FROM public.planosdeconta c
    JOIN public.planosdecontagrupos g ON g.id = c.grupo_id
   WHERE c.ativo AND g.ativo
     AND (SELECT d.situacao FROM public.dre_destino_do_cadastro(c.id, g.id, current_date) d) = 'PENDENTE'
  HAVING count(*) > 0;

  RETURN QUERY
  -- Periodo: o que existe e nao entra em total nenhum.
  SELECT 'EVENTO_SEM_LINHA'::text,
         'Lancamento no periodo que nao entra em nenhuma linha da DRE.'::text,
         'PERIODO'::text,
         count(*)::bigint,
         round(coalesce(sum(e.valor), 0), 2)
    FROM public.eventos_financeiros e
   WHERE e.status IN ('ATIVO', 'CONVERTIDO')
     AND e.competencia_em BETWEEN p_de AND p_ate
     AND public.dre_linha_do_evento(e.id, v_template, v_modo.estado, v_modo.vigencia_inicio) IS NULL
  HAVING count(*) > 0;

  RETURN QUERY
  -- Item vendido sem custo. Ja existia como contagem avulsa na rota da DRE, e
  -- por isso era o unico aviso sem lista: a tela dizia "6 itens" e nao sabia
  -- dizer quais. Como motivo da fila, ganha o mesmo drill-down dos outros e
  -- deixa de ser um caminho a parte.
  SELECT 'ITEM_SEM_CUSTO'::text,
         'Item vendido sem custo cadastrado: a margem esta superestimada.'::text,
         'PERIODO'::text,
         count(*)::bigint,
         round(coalesce(sum(e.valor), 0), 2)
    FROM public.eventos_financeiros e
   WHERE e.status IN ('ATIVO', 'CONVERTIDO')
     AND e.natureza_dre = 'CUSTO'
     AND e.dados_snapshot @> '{"custo_nao_informado": true}'::jsonb
     AND e.competencia_em BETWEEN p_de AND p_ate
  HAVING count(*) > 0;

  RETURN QUERY
  -- OS ainda em execucao: competencia nula aqui e estado legitimo, porque o
  -- carimbo so vem no encerramento. Fica na fila como informacao — a receita ja
  -- foi reconhecida e ainda nao pertence a mes nenhum —, nao como defeito.
  SELECT 'EVENTO_OS_EM_ABERTO'::text,
         'Lancamento de OS ainda em execucao: a competencia so e carimbada no encerramento.'::text,
         'GERAL'::text,
         count(*)::bigint,
         round(coalesce(sum(e.valor), 0), 2)
    FROM public.eventos_financeiros e
    JOIN public.ordemservico o
      ON o.id = public.os_do_evento(e.ordemservicoid, e.source_type, e.source_id)
   WHERE e.status IN ('ATIVO', 'CONVERTIDO')
     AND e.competencia_em IS NULL
     AND o.execucao_fim_em IS NULL
  HAVING count(*) > 0;

  RETURN QUERY
  -- Sem fonte nao ha de onde herdar competencia: nenhuma acao no documento
  -- original conserta, porque nao ha documento original.
  SELECT 'EVENTO_SEM_FONTE'::text,
         'Lancamento sem fonte e sem competencia: nao ha de onde herdar o periodo.'::text,
         'GERAL'::text,
         count(*)::bigint,
         round(coalesce(sum(e.valor), 0), 2)
    FROM public.eventos_financeiros e
   WHERE e.status IN ('ATIVO', 'CONVERTIDO')
     AND e.competencia_em IS NULL
     AND e.source_id IS NULL
     AND e.ordemservicoid IS NULL
  HAVING count(*) > 0;

  RETURN QUERY
  -- O que sobra: tem fonte, a fonte ja encerrou (ou nao e OS) e mesmo assim o
  -- lancamento ficou sem periodo. Anomalia de verdade.
  SELECT 'EVENTO_SEM_COMPETENCIA'::text,
         'Lancamento sem competencia: nao pertence a nenhum periodo.'::text,
         'GERAL'::text,
         count(*)::bigint,
         round(coalesce(sum(e.valor), 0), 2)
    FROM public.eventos_financeiros e
   WHERE e.status IN ('ATIVO', 'CONVERTIDO')
     AND e.competencia_em IS NULL
     AND (e.source_id IS NOT NULL OR e.ordemservicoid IS NOT NULL)
     AND NOT EXISTS (
       SELECT 1 FROM public.ordemservico o
        WHERE o.id = public.os_do_evento(e.ordemservicoid, e.source_type, e.source_id)
          AND o.execucao_fim_em IS NULL)
  HAVING count(*) > 0;

  RETURN QUERY
  -- Natureza incompativel produz uma DRE que parece valida: uma despesa somando
  -- em receita de servicos nao viola nada, so mente.
  SELECT 'NATUREZA_INCOMPATIVEL'::text,
         'Lancamento numa linha de natureza contraria a dele.'::text,
         'PERIODO'::text,
         count(*)::bigint,
         round(coalesce(sum(e.valor), 0), 2)
    FROM public.eventos_financeiros e
    JOIN public.dre_linha l
      ON l.id = public.dre_linha_do_evento(e.id, v_template, v_modo.estado, v_modo.vigencia_inicio)
   WHERE e.status IN ('ATIVO', 'CONVERTIDO')
     AND e.competencia_em BETWEEN p_de AND p_ate
     AND l.natureza_dre IS NOT NULL
     AND ((l.natureza_dre = 'RECEITA' AND e.natureza <> 'RECEITA')
       OR (l.natureza_dre IN ('CUSTO', 'DESPESA') AND e.natureza <> 'DESPESA'))
  HAVING count(*) > 0;

  RETURN QUERY
  -- Ausencia de evento nao dispensa controle: a transacao existe, e nada dela
  -- chega ao resultado. So conta quando a transacao DEVERIA ter gerado evento —
  -- acusar o que o sistema decidiu manter fora do resultado ensina a ignorar a
  -- fila.
  SELECT 'TRANSACAO_SEM_EVENTO'::text,
         'Transacao de resultado no periodo que nao gerou lancamento na DRE.'::text,
         'PERIODO'::text,
         count(*)::bigint,
         round(coalesce(sum(t.valor), 0), 2)
    FROM public.transacao t
   WHERE t.competencia_em BETWEEN p_de AND p_ate
     AND upper(t.tipo::text) IN ('RECEITA', 'DESPESA')
     AND public.transacao_gera_evento_de_resultado(t.id)
     AND NOT EXISTS (
       SELECT 1 FROM public.eventos_financeiros e
        WHERE e.source_type = 'TRANSACAO' AND e.source_id = t.id
          AND e.status IN ('ATIVO', 'CONVERTIDO'))
  HAVING count(*) > 0;

  RETURN QUERY
  -- Exclusao que ninguem revisou: o mapeamento inicial foi sugerido por palavra
  -- no nome do grupo, e nem a conta nem o grupo ganharam classificacao desde
  -- entao. Classificar qualquer um dos dois ja e a revisao.
  SELECT 'EXCLUSAO_NAO_REVISADA'::text,
         'Valor fora da DRE por sugestao automatica de migracao, ainda sem revisao.'::text,
         'PERIODO'::text,
         count(t.id)::bigint,
         round(coalesce(sum(t.valor), 0), 2)
    FROM public.dre_mapeamento m
    JOIN public.planosdecontagrupos g ON g.id = m.origem_id
    JOIN public.planosdeconta c ON c.grupo_id = g.id
    JOIN public.transacao t
      ON t.plano_de_conta_id = c.id
     AND t.competencia_em BETWEEN p_de AND p_ate
   WHERE m.ativo AND m.origem_tipo = 'PLANO_GRUPO' AND m.exclui_do_resultado
     AND m.observacao ILIKE '%sugestao automatica%'
     AND g.classificacao_padrao_id IS NULL
     AND c.classificacao_especifica_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.plano_contas_classificacao_regra r
                      WHERE r.grupo_id = g.id OR r.conta_id = c.id)
  HAVING count(t.id) > 0;
END;
$$;


--
-- Name: FUNCTION dre_pendencias(p_de timestamp with time zone, p_ate timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_pendencias(p_de timestamp with time zone, p_ate timestamp with time zone) IS 'Fila de integridade da DRE, com quantidade e valor por motivo. Escopo CADASTRO nao depende do periodo; PERIODO e GERAL dependem. Destino de cadastro e exclusao vem de dre_destino_do_cadastro e transacao_gera_evento_de_resultado, as mesmas regras da sincronizacao.';


--
-- Name: dre_pendencias_itens(text, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_pendencias_itens(p_motivo text, p_de timestamp with time zone, p_ate timestamp with time zone, p_limite integer DEFAULT 100, p_deslocamento integer DEFAULT 0) RETURNS TABLE(referencia_tipo text, referencia_id bigint, descricao text, grupo_nome text, conta_nome text, competencia date, valor numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_template integer;
  v_modo record;
  v_limite integer := least(greatest(coalesce(p_limite, 100), 1), 500);
BEGIN
  SELECT * INTO v_modo FROM public.dre_modo_apuracao();
  SELECT id INTO v_template FROM public.dre_template WHERE ativo ORDER BY versao DESC LIMIT 1;

  IF p_motivo = 'GRUPO_SEM_DESTINO' THEN
    RETURN QUERY
    SELECT 'GRUPO'::text, g.id::bigint, g.nome, g.nome, NULL::text, NULL::date, NULL::numeric
      FROM public.planosdecontagrupos g
     WHERE g.ativo
       AND (SELECT d.situacao FROM public.dre_destino_do_cadastro(NULL, g.id, current_date) d) = 'PENDENTE'
     ORDER BY g.codigo
     LIMIT v_limite OFFSET coalesce(p_deslocamento, 0);

  ELSIF p_motivo = 'CONTA_SEM_REGRA' THEN
    RETURN QUERY
    SELECT 'CONTA'::text, c.id::bigint, c.nome, g.nome, c.nome, NULL::date,
           (SELECT round(coalesce(sum(t.valor), 0), 2) FROM public.transacao t
             WHERE t.plano_de_conta_id = c.id
               AND t.competencia_em BETWEEN p_de AND p_ate)
      FROM public.planosdeconta c
      JOIN public.planosdecontagrupos g ON g.id = c.grupo_id
     WHERE c.ativo AND g.ativo
       AND (SELECT d.situacao FROM public.dre_destino_do_cadastro(c.id, g.id, current_date) d) = 'PENDENTE'
     ORDER BY g.codigo, c.codigo
     LIMIT v_limite OFFSET coalesce(p_deslocamento, 0);

  ELSIF p_motivo IN ('EVENTO_SEM_LINHA', 'NATUREZA_INCOMPATIVEL', 'EVENTO_SEM_COMPETENCIA',
                     'EVENTO_OS_EM_ABERTO', 'EVENTO_SEM_FONTE', 'ITEM_SEM_CUSTO') THEN
    RETURN QUERY
    SELECT 'EVENTO'::text, e.id::bigint, e.descricao, g.nome, c.nome,
           e.competencia_em::date, round(e.valor, 2)
      FROM public.eventos_financeiros e
      LEFT JOIN public.transacao t ON t.id = e.source_id AND e.source_type = 'TRANSACAO'
      LEFT JOIN public.planosdeconta c ON c.id = t.plano_de_conta_id
      LEFT JOIN public.planosdecontagrupos g ON g.id = c.grupo_id
      LEFT JOIN public.dre_linha l
        ON l.id = public.dre_linha_do_evento(e.id, v_template, v_modo.estado, v_modo.vigencia_inicio)
     WHERE e.status IN ('ATIVO', 'CONVERTIDO')
       AND CASE p_motivo
             WHEN 'EVENTO_OS_EM_ABERTO' THEN
               e.competencia_em IS NULL
               AND EXISTS (SELECT 1 FROM public.ordemservico o
                            WHERE o.id = public.os_do_evento(e.ordemservicoid, e.source_type, e.source_id)
                              AND o.execucao_fim_em IS NULL)
             WHEN 'EVENTO_SEM_FONTE' THEN
               e.competencia_em IS NULL AND e.source_id IS NULL AND e.ordemservicoid IS NULL
             WHEN 'EVENTO_SEM_COMPETENCIA' THEN
               e.competencia_em IS NULL
               AND (e.source_id IS NOT NULL OR e.ordemservicoid IS NOT NULL)
               AND NOT EXISTS (
                 SELECT 1 FROM public.ordemservico o
                  WHERE o.id = public.os_do_evento(e.ordemservicoid, e.source_type, e.source_id)
                    AND o.execucao_fim_em IS NULL)
             WHEN 'ITEM_SEM_CUSTO' THEN
               e.natureza_dre = 'CUSTO'
               AND e.dados_snapshot @> '{"custo_nao_informado": true}'::jsonb
               AND e.competencia_em BETWEEN p_de AND p_ate
             WHEN 'EVENTO_SEM_LINHA' THEN
               e.competencia_em BETWEEN p_de AND p_ate AND l.id IS NULL
             ELSE
               e.competencia_em BETWEEN p_de AND p_ate
               AND l.natureza_dre IS NOT NULL
               AND ((l.natureza_dre = 'RECEITA' AND e.natureza <> 'RECEITA')
                 OR (l.natureza_dre IN ('CUSTO', 'DESPESA') AND e.natureza <> 'DESPESA'))
           END
     ORDER BY e.valor DESC NULLS LAST
     LIMIT v_limite OFFSET coalesce(p_deslocamento, 0);

  ELSIF p_motivo = 'TRANSACAO_SEM_EVENTO' THEN
    RETURN QUERY
    SELECT 'TRANSACAO'::text, t.id::bigint, t.descricao, g.nome, c.nome,
           t.competencia_em::date, round(t.valor, 2)
      FROM public.transacao t
      LEFT JOIN public.planosdeconta c ON c.id = t.plano_de_conta_id
      LEFT JOIN public.planosdecontagrupos g ON g.id = c.grupo_id
     WHERE t.competencia_em BETWEEN p_de AND p_ate
       AND upper(t.tipo::text) IN ('RECEITA', 'DESPESA')
       AND public.transacao_gera_evento_de_resultado(t.id)
       AND NOT EXISTS (SELECT 1 FROM public.eventos_financeiros e
                        WHERE e.source_type = 'TRANSACAO' AND e.source_id = t.id
                          AND e.status IN ('ATIVO', 'CONVERTIDO'))
     ORDER BY t.valor DESC NULLS LAST
     LIMIT v_limite OFFSET coalesce(p_deslocamento, 0);

  ELSIF p_motivo = 'EXCLUSAO_NAO_REVISADA' THEN
    RETURN QUERY
    SELECT 'TRANSACAO'::text, t.id::bigint, t.descricao, g.nome, c.nome,
           t.competencia_em::date, round(t.valor, 2)
      FROM public.dre_mapeamento m
      JOIN public.planosdecontagrupos g ON g.id = m.origem_id
      JOIN public.planosdeconta c ON c.grupo_id = g.id
      JOIN public.transacao t ON t.plano_de_conta_id = c.id
       AND t.competencia_em BETWEEN p_de AND p_ate
     WHERE m.ativo AND m.origem_tipo = 'PLANO_GRUPO' AND m.exclui_do_resultado
       AND m.observacao ILIKE '%sugestao automatica%'
       AND g.classificacao_padrao_id IS NULL
       AND c.classificacao_especifica_id IS NULL
       AND NOT EXISTS (SELECT 1 FROM public.plano_contas_classificacao_regra r
                        WHERE r.grupo_id = g.id OR r.conta_id = c.id)
     ORDER BY t.valor DESC NULLS LAST
     LIMIT v_limite OFFSET coalesce(p_deslocamento, 0);

  ELSE
    RAISE EXCEPTION 'Motivo de pendencia desconhecido: %.', p_motivo USING ERRCODE = '22023';
  END IF;
END;
$$;


--
-- Name: dre_previa_da_conta(integer, text, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_previa_da_conta(p_conta_id integer, p_natureza text, p_competencia date DEFAULT CURRENT_DATE, p_template_id integer DEFAULT NULL::integer) RETURNS TABLE(resultado text, classificacao text, classificacao_nome text, linha_codigo text, linha_nome text, origem text, motivo text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_natureza IS NULL OR p_natureza NOT IN ('RECEITA', 'DESPESA') THEN
    RAISE EXCEPTION 'Natureza invalida: %.', p_natureza USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT d.situacao, c.codigo, c.nome, l.codigo, l.nome, coalesce(d.origem, 'RESOLVEDOR'), d.motivo
    FROM public.dre_destino_do_cadastro(
           p_conta_id, NULL, coalesce(p_competencia, current_date), p_natureza, p_template_id) d
    LEFT JOIN public.classificacoes_resultado c ON c.id = d.classificacao_id
    LEFT JOIN public.dre_linha l ON l.id = d.linha_id;
END;
$$;


--
-- Name: FUNCTION dre_previa_da_conta(p_conta_id integer, p_natureza text, p_competencia date, p_template_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_previa_da_conta(p_conta_id integer, p_natureza text, p_competencia date, p_template_id integer) IS 'Explica, sem gravar, para onde um lancamento nesta conta vai: linha da DRE, exclusao com motivo, incompatibilidade de natureza ou pendencia. Leitura de dre_destino_do_cadastro, a mesma regra da sincronizacao.';


--
-- Name: dre_resolver_evento(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_resolver_evento(p_evento_id bigint, p_template_id integer) RETURNS TABLE(resultado text, classificacao_id integer, linha_id integer, motivo text, origem_resolucao text, regra_id integer, conta_id integer, grupo_id integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento       record;
  v_conta        integer;
  v_grupo        integer;
  v_competencia  date;
  v_class        integer;
  v_origem       text;
  v_regra        integer;
  v_naturezas    text[];
  v_tratamento   text;
  v_codigo       text;
  v_linha        integer;
  v_exclui       boolean;
  v_motivo       text;
BEGIN
  SELECT e.id, e.origem, e.natureza, e.competencia_em, e.source_type, e.source_id
    INTO v_evento
    FROM public.eventos_financeiros e
   WHERE e.id = p_evento_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Evento financeiro % nao encontrado.', p_evento_id
      USING ERRCODE = 'P0002';
  END IF;

  IF v_evento.competencia_em IS NULL THEN
    RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer,
      'Evento sem competencia: nao ha periodo para resolver.'::text,
      'RESOLVEDOR'::text, NULL::integer, NULL::integer, NULL::integer;
    RETURN;
  END IF;

  v_competencia := v_evento.competencia_em::date;

  -- Passo 1: origem automatica. Receber uma parcela nao cria receita nova; o
  -- significado ja veio do documento quando o evento nasceu.
  SELECT m.classificacao_resultado_id INTO v_class
    FROM public.dre_mapeamento m
   WHERE m.template_id = p_template_id
     AND m.ativo
     AND m.origem_tipo = 'EVENTO_ORIGEM'
     AND m.origem_valor = v_evento.origem || ':' || v_evento.natureza
     AND (m.vigencia_inicio IS NULL OR v_evento.competencia_em >= m.vigencia_inicio)
     AND (m.vigencia_fim IS NULL OR v_evento.competencia_em <= m.vigencia_fim)
   LIMIT 1;

  IF v_class IS NOT NULL THEN
    v_origem := 'ORIGEM_EVENTO';
  ELSE
    -- Passos 2 e 3: cadastro da transacao que originou o evento.
    IF v_evento.source_type = 'TRANSACAO' THEN
      SELECT t.plano_de_conta_id INTO v_conta
        FROM public.transacao t WHERE t.id = v_evento.source_id;
    END IF;

    IF v_conta IS NOT NULL THEN
      SELECT c.grupo_id INTO v_grupo FROM public.planosdeconta c WHERE c.id = v_conta;
    END IF;

    IF v_conta IS NULL AND v_grupo IS NULL THEN
      RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer,
        'Lancamento sem conta do plano: nao ha regra a aplicar.'::text,
        'RESOLVEDOR'::text, NULL::integer, NULL::integer, NULL::integer;
      RETURN;
    END IF;

    SELECT r.classificacao_id, r.origem, r.regra_id
      INTO v_class, v_origem, v_regra
      FROM public.dre_classificacao_do_cadastro(v_conta, v_grupo, v_competencia) r;
  END IF;

  IF v_class IS NULL THEN
    RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer,
      'Conta e grupo sem classificacao vigente nesta competencia.'::text,
      'RESOLVEDOR'::text, NULL::integer, v_conta, v_grupo;
    RETURN;
  END IF;

  SELECT c.naturezas, c.tratamento, c.codigo
    INTO v_naturezas, v_tratamento, v_codigo
    FROM public.classificacoes_resultado c
   WHERE c.id = v_class AND c.ativo;

  IF v_naturezas IS NULL THEN
    RETURN QUERY SELECT 'PENDENTE'::text, NULL::integer, NULL::integer,
      'Classificacao inativa ou inexistente para este cadastro.'::text,
      coalesce(v_origem, 'RESOLVEDOR'), v_regra, v_conta, v_grupo;
    RETURN;
  END IF;

  IF NOT (v_evento.natureza = ANY (v_naturezas)) THEN
    RETURN QUERY SELECT 'PENDENTE'::text, v_class, NULL::integer,
      format('Natureza %s incompativel com a classificacao %s.', v_evento.natureza, v_codigo),
      coalesce(v_origem, 'RESOLVEDOR'), v_regra, v_conta, v_grupo;
    RETURN;
  END IF;

  SELECT d.linha_id, d.exclui, d.motivo
    INTO v_linha, v_exclui, v_motivo
    FROM public.dre_destino_da_classificacao(p_template_id, v_class) d;

  IF v_exclui IS NULL THEN
    RETURN QUERY SELECT 'PENDENTE'::text, v_class, NULL::integer,
      format('Classificacao %s sem destino no template %s.', v_codigo, p_template_id),
      coalesce(v_origem, 'RESOLVEDOR'), v_regra, v_conta, v_grupo;
    RETURN;
  END IF;

  IF v_exclui THEN
    RETURN QUERY SELECT 'EXCLUIDO'::text, v_class, NULL::integer,
      coalesce(v_motivo, 'Nao compoe resultado.'),
      coalesce(v_origem, 'RESOLVEDOR'), v_regra, v_conta, v_grupo;
    RETURN;
  END IF;

  RETURN QUERY SELECT 'CLASSIFICADO'::text, v_class, v_linha, NULL::text,
    coalesce(v_origem, 'RESOLVEDOR'), v_regra, v_conta, v_grupo;
END;
$$;


--
-- Name: FUNCTION dre_resolver_evento(p_evento_id bigint, p_template_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_resolver_evento(p_evento_id bigint, p_template_id integer) IS 'Resolucao canonica de um evento: origem automatica, regra da conta, regra do grupo, senao PENDENTE com motivo. Natureza incompativel nunca vira linha. Usada por gravacao, soma, detalhamento e previa.';


--
-- Name: dre_somar_por_linha(integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_somar_por_linha(p_template_id integer, p_de timestamp with time zone, p_ate timestamp with time zone) RETURNS TABLE(linha_id integer, valor numeric, lancamentos bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_modo record;
BEGIN
  SELECT * INTO v_modo FROM public.dre_modo_apuracao();

  RETURN QUERY
  SELECT l.linha_id,
         round(sum(l.valor), 2) AS valor,
         count(*)::bigint       AS lancamentos
    FROM (
      SELECT public.dre_linha_do_evento(
               e.id, p_template_id, v_modo.estado, v_modo.vigencia_inicio) AS linha_id,
             e.valor
        FROM public.eventos_financeiros e
       WHERE e.status IN ('ATIVO', 'CONVERTIDO')
         AND e.competencia_em IS NOT NULL
         AND e.competencia_em >= p_de
         AND e.competencia_em <= p_ate
    ) l
   WHERE l.linha_id IS NOT NULL
   GROUP BY l.linha_id;
END;
$$;


--
-- Name: FUNCTION dre_somar_por_linha(p_template_id integer, p_de timestamp with time zone, p_ate timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_somar_por_linha(p_template_id integer, p_de timestamp with time zone, p_ate timestamp with time zone) IS 'Soma os lancamentos por linha no periodo. Inclui CONVERTIDO: virar transacao define como a despesa sera paga, nao desfaz o fato economico. Resolve a linha por dre_linha_do_evento, a mesma do drill-down e do badge.';


--
-- Name: editar_evento_financeiro_venda(bigint, bigint, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.editar_evento_financeiro_venda(p_venda_id bigint, p_evento_id bigint, p_payload jsonb, p_usuario uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento public.eventos_financeiros%ROWTYPE;
  v_manual boolean;
  v_comissao boolean;
  v_valor numeric;
  v_descricao text;
  v_detalhe text;
  v_snapshot jsonb;
BEGIN
  IF p_usuario IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Informe os dados do evento financeiro e o autor.' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Venda nao encontrada.' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_evento FROM public.eventos_financeiros
    WHERE id = p_evento_id AND source_type = 'VENDA' AND source_id = p_venda_id
      AND ordemservicoid IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evento financeiro nao encontrado nesta venda.' USING ERRCODE = 'P0002'; END IF;
  IF v_evento.status = 'CONVERTIDO' OR v_evento.transacaoid IS NOT NULL OR v_evento.lancamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Exclua primeiro a transacao ou o lancamento financeiro vinculado.' USING ERRCODE = 'P0001';
  END IF;
  IF v_evento.status <> 'ATIVO' THEN
    RAISE EXCEPTION 'Somente eventos ativos podem ser alterados.' USING ERRCODE = 'P0001';
  END IF;
  v_manual := coalesce(v_evento.is_manual,false) AND coalesce(v_evento.chave_origem,'') LIKE 'MANUAL:%';
  v_comissao := coalesce(v_evento.origem = 'COMISSAO' AND v_evento.natureza = 'DESPESA' AND v_evento.chave_origem = 'COMISSAO_VENDA',false);
  IF v_evento.consumo_saida_id IS NOT NULL OR v_evento.consumo_usoconsumo_saida_id IS NOT NULL
    OR NOT (v_manual AND v_evento.origem <> 'COMISSAO' AND NOT (v_evento.origem = 'FRETE' AND v_evento.natureza = 'RECEITA')
      OR v_evento.natureza = 'RECEITA' AND v_evento.origem = 'PRODUTO'
      OR v_evento.natureza = 'RECEITA' AND v_evento.origem = 'FRETE' AND v_evento.chave_origem = 'FRETE'
      OR v_comissao) THEN
    RAISE EXCEPTION 'Este evento deve ser corrigido na origem que o criou.' USING ERRCODE = 'P0001';
  END IF;
  IF v_comissao THEN
    PERFORM 1 FROM public.venda_comissao WHERE vendaid = p_venda_id AND integrada
      AND usuarioid IS NOT DISTINCT FROM v_evento.usuarioid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Comissao integrada nao encontrada para este beneficiario.' USING ERRCODE = 'P0001'; END IF;
  END IF;
  v_valor := (p_payload->>'valor')::numeric;
  v_descricao := CASE WHEN v_manual AND NOT v_comissao THEN btrim(coalesce(p_payload->>'descricao',v_evento.descricao)) ELSE v_evento.descricao END;
  v_detalhe := CASE WHEN v_manual AND NOT v_comissao AND p_payload ? 'detalhe'
    THEN nullif(btrim(p_payload->>'detalhe'),'') ELSE v_evento.detalhe END;
  IF v_valor IS NULL OR v_valor::text IN ('NaN','Infinity','-Infinity') OR v_valor < 0
    OR nullif(v_descricao,'') IS NULL THEN
    RAISE EXCEPTION 'Informe titulo e valor valido, igual ou maior que zero.' USING ERRCODE = '22023';
  END IF;
  PERFORM set_config('app.audit_user_id',p_usuario::text,true);
  v_snapshot := coalesce(v_evento.dados_snapshot,'{}'::jsonb)
    || jsonb_build_object('ajuste_manual',true,'ajustado_em',clock_timestamp(),'ajustado_por',p_usuario);
  IF v_comissao THEN
    v_snapshot := v_snapshot || jsonb_build_object('comissao_ajustada_a_mao',true,
      'valor_automatico',coalesce(v_evento.dados_snapshot->'valor_automatico',to_jsonb(v_evento.valor)),
      'valor_comissao',round(v_valor,2));
  END IF;
  UPDATE public.eventos_financeiros SET descricao = v_descricao, detalhe = v_detalhe,
    valor = round(v_valor,2), is_manual = v_evento.is_manual OR v_comissao,
    pode_gerar_transacao = CASE WHEN v_comissao THEN round(v_valor,2) > 0 AND usuarioid IS NOT NULL ELSE pode_gerar_transacao END,
    updated_at = now(), dados_snapshot = v_snapshot WHERE id = v_evento.id RETURNING * INTO v_evento;
  RETURN to_jsonb(v_evento);
END;
$$;


--
-- Name: editar_movimento_saldo_cliente(integer, bigint, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.editar_movimento_saldo_cliente(p_cliente_id integer, p_movimento_id bigint, p_sentido text, p_valor numeric, p_motivo text DEFAULT NULL::text, p_usuario uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_movimento public.cliente_saldo_movimento%ROWTYPE;
  v_sentido text;
  v_valor numeric(14,2);
  v_motivo text;
  v_saldo numeric(14,2);
BEGIN
  v_sentido := upper(btrim(coalesce(p_sentido, '')));
  IF v_sentido NOT IN ('CREDITO', 'DEBITO') THEN
    RAISE EXCEPTION 'Informe se o lançamento adiciona (CREDITO) ou remove (DEBITO) saldo.'
      USING ERRCODE = '22023';
  END IF;

  v_valor := round(coalesce(p_valor, 0), 2);
  IF v_valor <= 0 THEN
    RAISE EXCEPTION 'O valor do lançamento deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;

  v_motivo := nullif(btrim(coalesce(p_motivo, '')), '');

  -- Mesma trava do ajuste: duas mexidas simultâneas no mesmo cliente não
  -- podem reconstruir o razão cada uma por cima da outra.
  PERFORM 1 FROM public.cliente c
   WHERE c.id = p_cliente_id AND c.is_deleted = false
     FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_movimento
    FROM public.cliente_saldo_movimento m
   WHERE m.id = p_movimento_id AND m.cliente_id = p_cliente_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lançamento não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF v_movimento.origem <> 'MANUAL' OR v_movimento.acao <> 'REGISTRO' THEN
    RAISE EXCEPTION
      'Este lançamento veio de uma baixa e não pode ser editado. Para desfazê-lo, estorne a baixa no financeiro.'
      USING ERRCODE = '22023';
  END IF;

  IF (v_movimento.sentido, v_movimento.valor, v_movimento.motivo)
     IS NOT DISTINCT FROM (v_sentido, v_valor, v_motivo) THEN
    SELECT c.saldo_credito INTO v_saldo FROM public.cliente c WHERE c.id = p_cliente_id;
    RETURN jsonb_build_object('movimento_id', v_movimento.id, 'alterado', false, 'saldo', v_saldo);
  END IF;

  PERFORM set_config('app.audit_user_id', coalesce(p_usuario::text, ''), true);
  PERFORM set_config('app.razao_credito_reescrita', 'on', true);

  UPDATE public.cliente_saldo_movimento
     SET sentido = v_sentido,
         valor = v_valor,
         motivo = v_motivo,
         updated_at = now(),
         updated_by = p_usuario
   WHERE id = v_movimento.id;

  v_saldo := public.reconstruir_razao_credito_cliente(p_cliente_id);

  PERFORM set_config('app.razao_credito_reescrita', 'off', true);

  RETURN jsonb_build_object('movimento_id', v_movimento.id, 'alterado', true, 'saldo', v_saldo);
END;
$$;


--
-- Name: FUNCTION editar_movimento_saldo_cliente(p_cliente_id integer, p_movimento_id bigint, p_sentido text, p_valor numeric, p_motivo text, p_usuario uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.editar_movimento_saldo_cliente(p_cliente_id integer, p_movimento_id bigint, p_sentido text, p_valor numeric, p_motivo text, p_usuario uuid) IS 'Corrige sentido, valor e motivo de um ajuste MANUAL do crédito do cliente e recalcula o razão. Recusa se o saldo ficaria negativo em algum ponto.';


--
-- Name: entrada_fiscal_personalizada_completar_auditoria(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entrada_fiscal_personalizada_completar_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item record;
BEGIN
  NEW.modalidade := coalesce(nullif(NEW.modalidade, ''), 'INTEGRAL');

  IF NEW.destino = 'ESTOQUE' AND NEW.entrada_id IS NOT NULL
     AND (NEW.produto_id IS NULL OR NEW.quantidade_personalizada IS NULL
          OR NEW.custo_unitario IS NULL OR NEW.item_destino_snapshot IS NULL) THEN
    SELECT ei.produto_id, ei.quantidade, ei.valor_unitario_compra, ei.titulo,
           ei.referencia, ei.unidade, e.valor_total
      INTO v_item
      FROM public.entradaitens ei
      JOIN public.entrada e ON e.id = ei.entrada_id
     WHERE ei.entrada_id = NEW.entrada_id
     ORDER BY ei.id
     LIMIT 1;
    IF FOUND THEN
      NEW.produto_id := coalesce(NEW.produto_id, v_item.produto_id);
      NEW.quantidade_personalizada := coalesce(NEW.quantidade_personalizada, v_item.quantidade);
      NEW.custo_unitario := coalesce(NEW.custo_unitario, v_item.valor_unitario_compra);
      NEW.valor_fiscal_documento := coalesce(NEW.valor_fiscal_documento, v_item.valor_total);
      NEW.item_destino_snapshot := coalesce(
        NEW.item_destino_snapshot,
        jsonb_build_object(
          'id', v_item.produto_id,
          'titulo', v_item.titulo,
          'referencia', v_item.referencia,
          'unidade', v_item.unidade
        )
      );
    END IF;
  ELSIF NEW.destino IN ('USOCONSUMO', 'GERAL') AND NEW.usoconsumo_entrada_id IS NOT NULL
     AND (NEW.usoconsumo_item_id IS NULL OR NEW.quantidade_personalizada IS NULL
          OR NEW.custo_unitario IS NULL OR NEW.item_destino_snapshot IS NULL) THEN
    SELECT ui.item_id, ui.quantidade, ui.valor_unitario_compra, ui.titulo,
           ui.referencia, ui.unidade, ue.valor_total
      INTO v_item
      FROM public.usoconsumo_entrada_item ui
      JOIN public.usoconsumo_entrada ue ON ue.id = ui.entrada_id
     WHERE ui.entrada_id = NEW.usoconsumo_entrada_id
     ORDER BY ui.id
     LIMIT 1;
    IF FOUND THEN
      NEW.usoconsumo_item_id := coalesce(NEW.usoconsumo_item_id, v_item.item_id);
      NEW.quantidade_personalizada := coalesce(NEW.quantidade_personalizada, v_item.quantidade);
      NEW.custo_unitario := coalesce(NEW.custo_unitario, v_item.valor_unitario_compra);
      NEW.valor_fiscal_documento := coalesce(NEW.valor_fiscal_documento, v_item.valor_total);
      NEW.item_destino_snapshot := coalesce(
        NEW.item_destino_snapshot,
        jsonb_build_object(
          'id', v_item.item_id,
          'titulo', v_item.titulo,
          'referencia', v_item.referencia,
          'unidade', v_item.unidade
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: estoque_definir_contexto(text, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estoque_definir_contexto(p_origem text, p_documento_id bigint DEFAULT NULL::bigint, p_documento_label text DEFAULT NULL::text, p_usuario uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM set_config('app.estoque_origem', COALESCE(p_origem, ''), true);
  PERFORM set_config('app.estoque_documento_id', COALESCE(p_documento_id::text, ''), true);
  PERFORM set_config('app.estoque_documento_label', COALESCE(p_documento_label, ''), true);
  PERFORM set_config('app.estoque_usuario', COALESCE(p_usuario::text, ''), true);
END;
$$;


--
-- Name: estoque_saida_item_fiscal_validar_origem(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estoque_saida_item_fiscal_validar_origem() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saida_produto integer;
  v_saida_quantidade numeric;
  v_entrada_produto integer;
  v_entrada_quantidade numeric;
  v_ja_vinculada numeric;
  v_exige_referencia boolean;
BEGIN
  SELECT produto_id, quantidade
    INTO v_saida_produto, v_saida_quantidade
    FROM public.estoque_saida_item
   WHERE id = NEW.saida_item_id
     AND saida_id = NEW.saida_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'O item fiscal não pertence à saída informada.' USING ERRCODE = '23514';
  END IF;

  SELECT documento_referenciado_obrigatorio OR finalidade = 'DEVOLUCAO'
    INTO v_exige_referencia
    FROM public.estoque_saida_fiscal
   WHERE saida_id = NEW.saida_id;

  IF v_exige_referencia AND (
    NEW.entrada_item_origem_id IS NULL OR NEW.numero_item_referenciado IS NULL
  ) THEN
    RAISE EXCEPTION 'A operação fiscal exige a entrada e o número do item de origem.'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.entrada_item_origem_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT produto_id, quantidade
    INTO v_entrada_produto, v_entrada_quantidade
    FROM public.entradaitens
   WHERE id = NEW.entrada_item_origem_id
   FOR UPDATE;

  IF NOT FOUND OR v_entrada_produto <> v_saida_produto THEN
    RAISE EXCEPTION 'O item da entrada de origem pertence a outro produto.' USING ERRCODE = '23514';
  END IF;

  SELECT coalesce(sum(saida_item.quantidade), 0)
    INTO v_ja_vinculada
    FROM public.estoque_saida_item_fiscal vinculo
    JOIN public.estoque_saida_item saida_item ON saida_item.id = vinculo.saida_item_id
   WHERE vinculo.entrada_item_origem_id = NEW.entrada_item_origem_id
     AND vinculo.id <> coalesce(NEW.id, -1);

  IF v_ja_vinculada + v_saida_quantidade > v_entrada_quantidade THEN
    RAISE EXCEPTION 'A quantidade total vinculada supera a quantidade recebida no item de origem.'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: estornar_baixa_estoque_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estornar_baixa_estoque_os(p_os_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto('ORDEM_SERVICO', p_os_id::bigint, 'OS #' || p_os_id || ' - estorno');
  PERFORM public.estornar_baixa_estoque_os_interna(p_os_id);
END;
$$;


--
-- Name: estornar_baixa_estoque_os_interna(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estornar_baixa_estoque_os_interna(p_os_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  -- devolve tudo que foi baixado
  update public.produto p
     set estoque = p.estoque + b.quantidade
    from public.osproduto_baixa b
   where b.ordemservicoid = p_os_id
     and p.id = b.produtoid;

  delete from public.osproduto_baixa
   where ordemservicoid = p_os_id;
end
$$;


--
-- Name: estornar_baixa_transacao(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estornar_baixa_transacao(p_transacao_id bigint, p_estornado_por uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_transacao public.transacao%ROWTYPE;
  v_acrescimos_removidos numeric(14,2) := 0;
  v_valor_reaberto numeric(14,2);
  v_baixa_do_titulo boolean := false;
  v_titulo bigint;
  v_movimento public.cliente_saldo_movimento%ROWTYPE;
  v_sentido_estorno text;
  v_saldo_anterior numeric(14,2);
  v_saldo_resultante numeric(14,2);
BEGIN
  SELECT * INTO v_transacao
    FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false
     FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transação não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF v_transacao.baixa_de_transacao_id IS NOT NULL THEN
    v_titulo := v_transacao.baixa_de_transacao_id;

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
    ) VALUES (
      v_titulo, coalesce(v_transacao.vencimento_em, v_transacao.data),
      coalesce(v_transacao.pago_em, v_transacao.data),
      p_estornado_por, v_transacao.banco_id, v_transacao.metodopagamento, 'ESTORNO'
    );

    DELETE FROM public.transacao WHERE id = p_transacao_id;

    SELECT * INTO v_transacao FROM public.transacao WHERE id = v_titulo;

    IF upper(v_transacao.tipo::text) = 'RECEITA' THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_titulo,
      'baixa_estornada', p_transacao_id,
      'valor_baixado', v_transacao.valor_baixado,
      'pendente', v_transacao.pendente,
      'parcial', true
    );
  END IF;

  IF coalesce(v_transacao.pendente, false) THEN
    RAISE EXCEPTION 'Esta transação não está liquidada: não há baixa a estornar.'
      USING ERRCODE = '22023';
  END IF;

  IF coalesce(v_transacao.abonado, false) THEN
    UPDATE public.transacao
       SET pendente = true,
           data = coalesce(vencimento_em, data),
           pago_em = NULL,
           abonado = false,
           abonado_por = NULL,
           abonado_em = NULL,
           abono_motivo = NULL,
           updated_at = now()
     WHERE id = p_transacao_id;

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
    ) VALUES (
      v_transacao.id, coalesce(v_transacao.vencimento_em, v_transacao.data),
      coalesce(v_transacao.pago_em, v_transacao.data),
      p_estornado_por, NULL, NULL, 'ESTORNO'
    );

    IF upper(v_transacao.tipo::text) = 'RECEITA' THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_transacao.id,
      'pendente', true,
      'abono_desfeito', true
    );
  END IF;

  -- ------------------------------------------------- baixa por crédito
  --
  -- A última linha do razão daquela transação diz se ainda há o que desfazer:
  -- REGISTRO é baixa em pé, ESTORNO é ciclo já fechado.
  SELECT * INTO v_movimento
    FROM public.cliente_saldo_movimento m
   WHERE m.transacao_id = p_transacao_id
     AND m.origem = 'TRANSACAO'
   ORDER BY m.id DESC
   LIMIT 1;

  IF FOUND AND v_movimento.acao = 'REGISTRO' THEN
    v_sentido_estorno := CASE WHEN v_movimento.sentido = 'DEBITO' THEN 'CREDITO' ELSE 'DEBITO' END;

    SELECT c.saldo_credito INTO v_saldo_anterior
      FROM public.cliente c
     WHERE c.id = v_movimento.cliente_id
       FOR UPDATE;

    v_saldo_anterior := coalesce(v_saldo_anterior, 0);
    v_saldo_resultante := CASE
      WHEN v_sentido_estorno = 'CREDITO' THEN v_saldo_anterior + v_movimento.valor
      ELSE v_saldo_anterior - v_movimento.valor
    END;

    -- Só acontece no título a pagar: o crédito que ele gerou já foi gasto em
    -- outra cobrança, e tirá-lo agora deixaria a carteira negativa.
    IF v_saldo_resultante < 0 THEN
      RAISE EXCEPTION
        'O crédito gerado por esta baixa já foi usado: o cliente tem R$ % e o estorno retiraria R$ %.',
        to_char(v_saldo_anterior, 'FM999999990.00'),
        to_char(v_movimento.valor, 'FM999999990.00')
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.transacao
       SET pendente = true,
           data = coalesce(vencimento_em, data),
           pago_em = NULL,
           baixado_por = NULL,
           updated_at = now()
     WHERE id = p_transacao_id;

    INSERT INTO public.cliente_saldo_movimento (
      cliente_id, sentido, origem, acao, valor,
      saldo_anterior, saldo_resultante, transacao_id, motivo, created_by
    ) VALUES (
      v_movimento.cliente_id, v_sentido_estorno, 'TRANSACAO', 'ESTORNO', v_movimento.valor,
      v_saldo_anterior, round(v_saldo_resultante, 2), p_transacao_id,
      'Estorno da baixa do título #' || p_transacao_id, p_estornado_por
    );

    INSERT INTO public.transacao_baixa_historico (
      transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
    ) VALUES (
      v_transacao.id, coalesce(v_transacao.vencimento_em, v_transacao.data),
      coalesce(v_transacao.pago_em, v_transacao.data),
      p_estornado_por, NULL, v_transacao.metodopagamento, 'ESTORNO'
    );

    IF upper(v_transacao.tipo::text) = 'RECEITA' THEN
      IF v_transacao.ordemservicoid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_os(v_transacao.ordemservicoid);
      END IF;
      IF v_transacao.vendaid IS NOT NULL THEN
        PERFORM public.recalcular_status_financeiro_venda(v_transacao.vendaid);
      END IF;
    END IF;

    RETURN jsonb_build_object(
      'id', v_transacao.id,
      'pendente', true,
      'credito_devolvido', v_movimento.valor,
      'saldo', round(v_saldo_resultante, 2)
    );
  END IF;

  IF v_transacao.adiantamento_id IS NOT NULL THEN
    SELECT coalesce(a.adiantamento_manteve_pendentes, false) INTO v_baixa_do_titulo
      FROM public.transacao a WHERE a.id = v_transacao.adiantamento_id;

    IF NOT coalesce(v_baixa_do_titulo, false) THEN
      RAISE EXCEPTION
        'Este título foi liquidado pela antecipação #%. Desfaça a antecipação: ela devolve este título e os irmãos para em aberto de uma vez.',
        v_transacao.adiantamento_id USING ERRCODE = '22023';
    END IF;
  END IF;

  IF coalesce(v_transacao.eh_adiantamento, false) THEN
    RAISE EXCEPTION
      'Esta é uma antecipação, não a baixa de um título. Excluí-la é que devolve os títulos para em aberto.'
      USING ERRCODE = '22023';
  END IF;

  IF v_transacao.pagamento_multiplo_id IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta baixa é uma perna do pagamento múltiplo #%. Desfaça o pagamento inteiro.',
      v_transacao.pagamento_multiplo_id USING ERRCODE = '22023';
  END IF;

  /*
   * Título comum pago em partes: cada pagamento tem data, banco e valor próprios
   * e sai do extrato sozinho, então o estorno é de cada um.
   *
   * O antecipado é o contrário: a baixa foi UMA — ela quitou o título e criou o
   * repasse no mesmo ato —, e desfazê-la desfaz as duas coisas.
   */
  IF v_transacao.adiantamento_id IS NULL AND EXISTS (
    SELECT 1 FROM public.transacao f
     WHERE f.baixa_de_transacao_id = p_transacao_id AND f.is_deleted = false
  ) THEN
    RAISE EXCEPTION
      'Este título foi pago em partes. Estorne os pagamentos dele, um a um.'
      USING ERRCODE = '22023';
  END IF;

  IF v_transacao.adiantamento_id IS NOT NULL THEN
    DELETE FROM public.transacao WHERE baixa_de_transacao_id = p_transacao_id;
  END IF;

  UPDATE public.transacao
     SET pendente = true,
         data = coalesce(vencimento_em, data),
         pago_em = NULL,
         baixado_por = NULL,
         banco_id = CASE WHEN v_transacao.adiantamento_id IS NOT NULL THEN NULL ELSE banco_id END,
         updated_at = now()
   WHERE id = p_transacao_id;

  WITH removidos AS (
    DELETE FROM public.transacao_ajuste
     WHERE transacao_id = p_transacao_id
       AND natureza = 'ACRESCIMO'
    RETURNING valor_calculado
  )
  SELECT coalesce(sum(valor_calculado), 0) INTO v_acrescimos_removidos FROM removidos;

  v_valor_reaberto := round(coalesce(v_transacao.valor_base, v_transacao.valor), 2);

  UPDATE public.transacao
     SET valor = v_valor_reaberto,
         valor_acrescimos = 0,
         "valorLiquido" = round(v_valor_reaberto - coalesce(valor_descontos, 0), 2),
         updated_at = now()
   WHERE id = p_transacao_id;

  INSERT INTO public.transacao_baixa_historico (
    transacao_id, vencimento_em, pago_em, baixado_por, banco_id, metodopagamento, operacao
  ) VALUES (
    v_transacao.id,
    coalesce(v_transacao.vencimento_em, v_transacao.data),
    coalesce(v_transacao.pago_em, v_transacao.data),
    p_estornado_por,
    v_transacao.banco_id,
    v_transacao.metodopagamento,
    'ESTORNO'
  );

  RETURN jsonb_build_object(
    'id', v_transacao.id,
    'pendente', true,
    'valor', v_valor_reaberto,
    'acrescimos_removidos', v_acrescimos_removidos,
    'vencimento_em', coalesce(v_transacao.vencimento_em, v_transacao.data)
  );
END;
$_$;


--
-- Name: FUNCTION estornar_baixa_transacao(p_transacao_id bigint, p_estornado_por uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.estornar_baixa_transacao(p_transacao_id bigint, p_estornado_por uuid) IS 'Tira a transação do fluxo de caixa: desfaz a baixa, remove os acréscimos do pagamento e devolve o título para a pagar ou a receber. Em título antecipado só alcança a baixa feita pelo próprio título, no modo que manteve os títulos em aberto.';


--
-- Name: estornar_consumos_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.estornar_consumos_os(p_os_id integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linha  record;
  v_total  integer := 0;
  v_motivo text := 'Estorno automatico: OS #' || p_os_id || ' cancelada ou orcamento recusado';
BEGIN
  FOR v_linha IN
    SELECT s.id AS saida_id, 'PRODUTO'::text AS tipo, e.id AS evento_id
      FROM public.estoque_saida s
      LEFT JOIN public.eventos_financeiros e ON e.consumo_saida_id = s.id
     WHERE s.ordemservicoid = p_os_id
       AND s.motivo = 'CONSUMO_EM_OS'
       AND s.status = 'CONFIRMADA'
       AND (e.id IS NULL OR (e.status <> 'CONVERTIDO'
            AND e.transacaoid IS NULL AND e.lancamento_id IS NULL))
    UNION ALL
    SELECT s.id, 'USOCONSUMO'::text, e.id
      FROM public.usoconsumo_saida s
      LEFT JOIN public.eventos_financeiros e ON e.consumo_usoconsumo_saida_id = s.id
     WHERE s.ordemservicoid = p_os_id
       AND s.motivo = 'CONSUMO_EM_OS'
       AND s.status = 'CONFIRMADA'
       AND (e.id IS NULL OR (e.status <> 'CONVERTIDO'
            AND e.transacaoid IS NULL AND e.lancamento_id IS NULL))
  LOOP
    PERFORM set_config('app.consumo_os_estorno', 'permitido', true);
    IF v_linha.tipo = 'PRODUTO' THEN
      PERFORM public.cancelar_saida_estoque(v_linha.saida_id, v_motivo, NULL);
    ELSE
      PERFORM public.cancelar_saida_usoconsumo(v_linha.saida_id, v_motivo, NULL);
    END IF;
    PERFORM set_config('app.consumo_os_estorno', '', true);

    -- Em CANCELADO o gatilho BEFORE ja fechou o evento; em ORCAMENTO_RECUSADO,
    -- nao -- aquele caminho nao mexe em evento nenhum.
    IF v_linha.evento_id IS NOT NULL THEN
      UPDATE public.eventos_financeiros
         SET status = 'CANCELADO',
             updated_at = now(),
             dados_snapshot = coalesce(dados_snapshot, '{}'::jsonb) || jsonb_build_object(
               'estorno_automatico', true,
               'motivo_cancelamento', v_motivo
             )
       WHERE id = v_linha.evento_id AND status <> 'CANCELADO';
    END IF;

    v_total := v_total + 1;
  END LOOP;

  RETURN v_total;
END;
$$;


--
-- Name: excluir_checklist_documento(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_checklist_documento(p_public_id uuid, p_permitir_assinado boolean DEFAULT false) RETURNS TABLE(documento_id bigint, codigo text, versao integer, tipo text, ordemservico_id bigint, assinado boolean, arquivo_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  doc public.checklist_documento%rowtype;
  v_assinado boolean;
  v_arquivo text;
begin
  select * into doc
  from public.checklist_documento
  where public_id = p_public_id;

  if not found then
    raise exception 'Versao de checklist nao encontrada.' using errcode = 'P0002';
  end if;

  select exists (
    select 1 from public.checklist_documento_assinatura a where a.documento_id = doc.id
  ) into v_assinado;

  if v_assinado and not coalesce(p_permitir_assinado, false) then
    raise exception 'Documento assinado nao pode ser excluido.' using errcode = '55000';
  end if;

  select f.storage_path into v_arquivo
  from public.checklist_documento_arquivo f
  where f.documento_id = doc.id;

  -- Quem apontava para esta versao passa a apontar para a anterior dela: o
  -- historico continua encadeado sem o elo removido.
  update public.checklist_documento
     set versao_anterior_id = doc.versao_anterior_id
   where versao_anterior_id = doc.id;

  if v_assinado then
    perform set_config('app.checklist_exclusao_assinada', 'on', true);
  end if;

  delete from public.checklist_documento where id = doc.id;

  perform set_config('app.checklist_exclusao_assinada', 'off', true);

  documento_id := doc.id;
  codigo := doc.codigo;
  versao := doc.versao;
  tipo := doc.tipo;
  ordemservico_id := doc.ordemservico_id;
  assinado := v_assinado;
  arquivo_path := v_arquivo;
  return next;
end;
$$;


--
-- Name: excluir_evento_financeiro_manual_os(integer, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_evento_financeiro_manual_os(p_ordemservico_id integer, p_evento_id bigint, p_motivo text DEFAULT NULL::text, p_usuario uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento public.eventos_financeiros%ROWTYPE;
  v_status_os text;
  v_os_excluida boolean;
  v_manual_de_origem boolean;
  v_consumo_com_estoque boolean;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  IF p_ordemservico_id IS NULL OR p_ordemservico_id <= 0
     OR p_evento_id IS NULL OR p_evento_id <= 0 THEN
    RAISE EXCEPTION 'Identificador invalido.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_evento
    FROM public.eventos_financeiros
   WHERE id = p_evento_id
     AND ordemservicoid = p_ordemservico_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Evento financeiro nao encontrado nesta OS.' USING ERRCODE = 'P0002';
  END IF;

  v_consumo_com_estoque :=
    v_evento.origem = 'CONSUMO'
    AND v_evento.natureza = 'DESPESA'
    AND (v_evento.consumo_saida_id IS NOT NULL OR v_evento.consumo_usoconsumo_saida_id IS NOT NULL);
  v_manual_de_origem :=
    coalesce(v_evento.is_manual, false)
    AND (
      coalesce(v_evento.chave_origem, '') LIKE 'MANUAL:%'
      OR v_consumo_com_estoque
    );

  -- Uma comissao corrigida recebe is_manual para congelar seu calculo, mas
  -- continua sendo automatica. Frete/receita pertence ao orcamento.
  IF NOT v_manual_de_origem
     OR v_evento.origem = 'COMISSAO'
     OR (v_evento.origem = 'FRETE' AND v_evento.natureza = 'RECEITA') THEN
    RAISE EXCEPTION 'Este evento foi gerado automaticamente e deve ser corrigido na origem que o criou.'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_evento.status = 'CONVERTIDO'
     OR v_evento.transacaoid IS NOT NULL
     OR v_evento.lancamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento ja foi lancado no Financeiro. Exclua primeiro a transacao ou o lancamento vinculado.'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_evento.status <> 'ATIVO' THEN
    RAISE EXCEPTION 'Somente eventos financeiros ativos podem ser excluidos.' USING ERRCODE = 'P0001';
  END IF;

  SELECT o.status::text, coalesce(o.is_deleted, false)
    INTO v_status_os, v_os_excluida
    FROM public.ordemservico o
   WHERE o.id = p_ordemservico_id
   FOR UPDATE;
  IF NOT FOUND OR v_os_excluida THEN
    RAISE EXCEPTION 'OS nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_status_os = 'CANCELADO' THEN
    RAISE EXCEPTION 'Esta OS esta cancelada e seus eventos financeiros nao podem mais ser alterados.'
      USING ERRCODE = 'P0001';
  END IF;
  IF v_consumo_com_estoque AND v_status_os IN ('CONCLUIDO', 'SEM_COBRANCA') THEN
    RAISE EXCEPTION 'A OS #% ja foi finalizada. Reabra a OS para excluir este consumo e devolver o item ao estoque.',
      p_ordemservico_id USING ERRCODE = 'P0001';
  END IF;
  IF v_consumo_com_estoque AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'Informe o motivo para devolver o item ao estoque.' USING ERRCODE = '22023';
  END IF;

  -- Faz o gatilho generico de auditoria atribuir UPDATE/DELETE ao operador que
  -- chamou a API, mesmo a RPC sendo executada pelo service_role.
  PERFORM set_config('app.audit_user_id', coalesce(p_usuario::text, ''), true);

  IF v_consumo_com_estoque THEN
    -- A funcao existente cancela a saida e devolve o saldo. Como esta chamada e
    -- interna a mesma RPC, qualquer falha no DELETE tambem desfaz o estorno.
    PERFORM public.cancelar_consumo_produto_os(p_evento_id, v_motivo, p_usuario);
  END IF;

  DELETE FROM public.eventos_financeiros
   WHERE id = p_evento_id
     AND ordemservicoid = p_ordemservico_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'O evento mudou durante a exclusao. Recarregue a OS e tente novamente.'
      USING ERRCODE = '40001';
  END IF;

  RETURN jsonb_build_object(
    'evento_id', p_evento_id,
    'excluido', true,
    'estoque_devolvido', v_consumo_com_estoque,
    'saida_id', coalesce(v_evento.consumo_saida_id, v_evento.consumo_usoconsumo_saida_id)
  );
END;
$$;


--
-- Name: FUNCTION excluir_evento_financeiro_manual_os(p_ordemservico_id integer, p_evento_id bigint, p_motivo text, p_usuario uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.excluir_evento_financeiro_manual_os(p_ordemservico_id integer, p_evento_id bigint, p_motivo text, p_usuario uuid) IS 'Exclui evento manual da OS; quando for consumo, cancela a saida e devolve o estoque atomicamente.';


--
-- Name: excluir_lancamento_de_eventos(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_lancamento_de_eventos(p_id bigint, p_deleted_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_grupo public.lancamento_de_eventos%ROWTYPE;
  v_os_finalizadas text;
  v_os_ids integer[];
  v_baixadas integer;
  v_parcelas integer;
  v_despesas integer;
BEGIN
  SELECT * INTO v_grupo FROM public.lancamento_de_eventos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lancamento #% nao encontrado.', p_id USING ERRCODE = 'P0002';
  END IF;

  -- Guarda 1: dinheiro que ja saiu. A exclusao apaga o titulo, nao a baixa: o
  -- saldo do banco subiria sozinho, sem que nada tenha acontecido no mundo.
  -- Mesma razao da trava individual do DELETE de transacao, mas valendo para o
  -- grupo — com uma parcela paga, nem as pendentes saem.
  SELECT count(*) INTO v_baixadas
    FROM public.transacao t
   WHERE t.lancamento_id = p_id AND t.is_deleted = false AND t.pendente = false;

  IF v_baixadas > 0 THEN
    RAISE EXCEPTION
      'Este lancamento tem % parcela(s) ja paga(s). Tire a baixa do fluxo de caixa antes de excluir.',
      v_baixadas USING ERRCODE = 'P0001';
  END IF;

  -- As ordens saem dos eventos, e nao do carimbo do grupo: num lancamento
  -- multi-OS ele e nulo, e ler dali passaria batido por todas elas. Precisa vir
  -- antes do UPDATE que solta o vinculo, senao nao ha mais o que ler.
  SELECT array_agg(DISTINCT e.ordemservicoid)
    INTO v_os_ids
    FROM public.eventos_financeiros e
   WHERE e.lancamento_id = p_id AND e.ordemservicoid IS NOT NULL;

  -- Guarda 2: OS finalizada. Mesmo conjunto de status que
  -- tg_reconciliar_eventos_ao_finalizar_os trata como fim de linha.
  SELECT string_agg(o.id::text, ', ' ORDER BY o.id) INTO v_os_finalizadas
    FROM public.ordemservico o
   WHERE o.id = ANY (coalesce(v_os_ids, ARRAY[]::integer[]))
     AND o.status::text IN ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO');

  IF v_os_finalizadas IS NOT NULL THEN
    RAISE EXCEPTION
      'A(s) OS #% ja foi(ram) finalizada(s). Reabra a OS para desfazer este lancamento.',
      v_os_finalizadas USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*) INTO v_parcelas
    FROM public.transacao t WHERE t.lancamento_id = p_id;

  -- As despesas voltam a prevista ANTES de o grupo sumir. A FK e ON DELETE SET
  -- NULL, entao o vinculo cairia sozinho — mas o status nao, e uma despesa
  -- CONVERTIDO sem vinculo nenhum seria uma despesa presa para sempre.
  UPDATE public.eventos_financeiros
     SET status = 'ATIVO', lancamento_id = NULL, updated_at = now()
   WHERE lancamento_id = p_id;

  GET DIAGNOSTICS v_despesas = ROW_COUNT;

  -- As parcelas caem por CASCADE.
  DELETE FROM public.lancamento_de_eventos WHERE id = p_id;

  RETURN jsonb_build_object(
    'id', p_id,
    'ordemservicoid', v_grupo.ordemservicoid,
    'ordemservicoids', to_jsonb(coalesce(v_os_ids, ARRAY[]::integer[])),
    'parcelas_removidas', v_parcelas,
    'despesas_revertidas', v_despesas
  );
END;
$$;


--
-- Name: excluir_movimento_saldo_cliente(integer, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_movimento_saldo_cliente(p_cliente_id integer, p_movimento_id bigint, p_usuario uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_movimento public.cliente_saldo_movimento%ROWTYPE;
  v_saldo numeric(14,2);
BEGIN
  PERFORM 1 FROM public.cliente c
   WHERE c.id = p_cliente_id AND c.is_deleted = false
     FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_movimento
    FROM public.cliente_saldo_movimento m
   WHERE m.id = p_movimento_id AND m.cliente_id = p_cliente_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lançamento não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF v_movimento.origem <> 'MANUAL' OR v_movimento.acao <> 'REGISTRO' THEN
    RAISE EXCEPTION
      'Este lançamento veio de uma baixa e não pode ser excluído. Para desfazê-lo, estorne a baixa no financeiro.'
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('app.audit_user_id', coalesce(p_usuario::text, ''), true);
  PERFORM set_config('app.razao_credito_reescrita', 'on', true);

  DELETE FROM public.cliente_saldo_movimento WHERE id = v_movimento.id;

  v_saldo := public.reconstruir_razao_credito_cliente(p_cliente_id);

  PERFORM set_config('app.razao_credito_reescrita', 'off', true);

  RETURN jsonb_build_object('movimento_id', v_movimento.id, 'excluido', true, 'saldo', v_saldo);
END;
$$;


--
-- Name: FUNCTION excluir_movimento_saldo_cliente(p_cliente_id integer, p_movimento_id bigint, p_usuario uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.excluir_movimento_saldo_cliente(p_cliente_id integer, p_movimento_id bigint, p_usuario uuid) IS 'Exclui um ajuste MANUAL do crédito do cliente e recalcula o razão. Recusa se o saldo ficaria negativo em algum ponto.';


--
-- Name: excluir_pagamento_multiplo(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.excluir_pagamento_multiplo(p_id bigint, p_deleted_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_grupo public.pagamento_multiplo%ROWTYPE;
  v_baixadas integer;
  v_documentos jsonb;
  v_doc record;
  v_removidas integer;
BEGIN
  SELECT * INTO v_grupo FROM public.pagamento_multiplo WHERE id = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pagamento múltiplo #% não encontrado.', p_id USING ERRCODE = 'P0002';
  END IF;

  IF v_grupo.modo = 'PARCELADO' THEN
    SELECT count(*) INTO v_baixadas
      FROM public.transacao t
     WHERE t.pagamento_multiplo_id = p_id
       AND t.is_deleted = false
       AND t.pendente = false;

    IF v_baixadas > 0 THEN
      RAISE EXCEPTION
        'Este pagamento tem % parcela(s) já baixada(s). Estorne essas baixas antes de excluir o pagamento.',
        v_baixadas USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Os documentos agora vivem no rateio, e não no `ordemservicoid` das linhas.
  SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('tipo', tipo_documento, 'id', documento_id)), '[]'::jsonb)
    INTO v_documentos
    FROM public.pagamento_multiplo_rateio
   WHERE pagamento_multiplo_id = p_id;

  UPDATE public.transacao
     SET is_deleted = true,
         deleted_at = now(),
         deleted_by = p_deleted_by,
         updated_at = now()
   WHERE pagamento_multiplo_id = p_id
     AND is_deleted = false;

  GET DIAGNOSTICS v_removidas = ROW_COUNT;

  FOR v_doc IN
    SELECT DISTINCT tipo_documento, documento_id
      FROM public.pagamento_multiplo_rateio
     WHERE pagamento_multiplo_id = p_id
  LOOP
    IF v_doc.tipo_documento = 'OS' THEN
      PERFORM public.recalcular_status_financeiro_os(v_doc.documento_id);
    ELSE
      PERFORM public.recalcular_status_financeiro_venda(v_doc.documento_id);
    END IF;
  END LOOP;

  -- O grupo NÃO é apagado. A versão anterior tentava, e não podia: as transações
  -- são excluídas por `is_deleted` e continuam referenciando o grupo, cuja FK é
  -- ON DELETE RESTRICT — ou seja, excluir um pagamento múltiplo sempre falhou com
  -- erro de chave estrangeira. Manter a linha também preserva o histórico de que
  -- aquele recebimento existiu e foi desfeito; o rateio segue junto, e some das
  -- contas porque `recebimento_por_documento` só olha transação não excluída.

  RETURN jsonb_build_object(
    'id', p_id,
    'transacoes_removidas', v_removidas,
    'documentos', v_documentos
  );
END;
$$;


--
-- Name: faturamento_os_habilitado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.faturamento_os_habilitado() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN coalesce((SELECT habilitar_faturamento_os FROM public.config_geral ORDER BY id DESC LIMIT 1), false);
END;
$$;


--
-- Name: fiscal_ativar_contexto_dfe(integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_ativar_contexto_dfe(p_empresa_id integer, p_cnpj text, p_ambiente text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cnpj text := public.fiscal_cnpj_normalizar(p_cnpj);
  v_ambiente text := upper(btrim(coalesce(p_ambiente, '')));
  v_contexto public.fiscal_dfe_contexto%ROWTYPE;
  v_restaurado boolean := false;
BEGIN
  IF NOT public.fiscal_cnpj_valido(v_cnpj) THEN
    RAISE EXCEPTION 'CNPJ invalido para ativacao do contexto DF-e.' USING ERRCODE = '22023';
  END IF;

  IF v_ambiente NOT IN ('HOMOLOGACAO', 'PRODUCAO') THEN
    RAISE EXCEPTION 'Ambiente fiscal invalido para ativacao do contexto DF-e.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.fiscal_dfe_controle (empresa_id, updatedat)
  VALUES (p_empresa_id, now())
  ON CONFLICT (empresa_id) DO NOTHING;

  PERFORM 1
    FROM public.fiscal_dfe_controle
   WHERE empresa_id = p_empresa_id
   FOR UPDATE;

  SELECT * INTO v_contexto
    FROM public.fiscal_dfe_contexto
   WHERE empresa_id = p_empresa_id
     AND cnpj = v_cnpj
     AND ambiente = v_ambiente;
  v_restaurado := FOUND;

  DELETE FROM public.fiscal_dfe_documento
   WHERE empresa_id = p_empresa_id;

  UPDATE public.fiscal_dfe_controle
     SET cnpj_consultado = v_cnpj,
         ambiente_consultado = v_ambiente,
         ult_nsu = CASE WHEN v_restaurado THEN v_contexto.ult_nsu ELSE '000000000000000' END,
         max_nsu = CASE WHEN v_restaurado THEN v_contexto.max_nsu ELSE '000000000000000' END,
         last_sync_at = CASE WHEN v_restaurado THEN v_contexto.last_sync_at ELSE NULL END,
         last_cstat = CASE WHEN v_restaurado THEN v_contexto.last_cstat ELSE NULL END,
         last_xmotivo = CASE WHEN v_restaurado THEN v_contexto.last_xmotivo ELSE NULL END,
         next_sync_after = CASE WHEN v_restaurado THEN v_contexto.next_sync_after ELSE NULL END,
         consumo_indevido_until = CASE WHEN v_restaurado THEN v_contexto.consumo_indevido_until ELSE NULL END,
         sync_lock_until = NULL,
         sync_started_at = CASE WHEN v_restaurado THEN v_contexto.sync_started_at ELSE NULL END,
         consulta_chave_window_started_at = CASE
           WHEN v_restaurado THEN v_contexto.consulta_chave_window_started_at ELSE NULL
         END,
         consulta_chave_count = CASE WHEN v_restaurado THEN v_contexto.consulta_chave_count ELSE 0 END,
         updatedat = now()
   WHERE empresa_id = p_empresa_id;

  RETURN jsonb_build_object(
    'restaurado', v_restaurado,
    'cnpj', v_cnpj,
    'ambiente', v_ambiente,
    'ultNSU', CASE WHEN v_restaurado THEN v_contexto.ult_nsu ELSE '000000000000000' END,
    'maxNSU', CASE WHEN v_restaurado THEN v_contexto.max_nsu ELSE '000000000000000' END
  );
END;
$$;


--
-- Name: fiscal_cnpj_normalizar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_cnpj_normalizar(p_valor text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN p_valor IS NULL THEN NULL
    ELSE upper(regexp_replace(btrim(p_valor), '[./[:space:]-]', '', 'g'))
  END
$$;


--
-- Name: FUNCTION fiscal_cnpj_normalizar(p_valor text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fiscal_cnpj_normalizar(p_valor text) IS 'Normaliza CNPJ numérico ou alfanumérico para 14 caracteres uppercase, removendo somente pontuação e espaços conhecidos.';


--
-- Name: fiscal_cnpj_valido(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_cnpj_valido(p_valor text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $_$
DECLARE
  v_cnpj text := public.fiscal_cnpj_normalizar(p_valor);
  v_pesos_primeiro integer[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
  v_pesos_segundo integer[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
  v_soma integer := 0;
  v_resto integer;
  v_dv1 integer;
  v_dv2 integer;
  v_indice integer;
BEGIN
  IF v_cnpj IS NULL OR v_cnpj !~ '^[A-Z0-9]{12}[0-9]{2}$' THEN
    RETURN false;
  END IF;

  -- Rejeita bases triviais repetidas, inclusive a forma numérica
  -- 00000000000000, em paridade com o validador TypeScript.
  IF substr(v_cnpj, 1, 12) = repeat(substr(v_cnpj, 1, 1), 12) THEN
    RETURN false;
  END IF;

  FOR v_indice IN 1..12 LOOP
    v_soma := v_soma
      + (ascii(substr(v_cnpj, v_indice, 1)) - 48) * v_pesos_primeiro[v_indice];
  END LOOP;
  v_resto := mod(v_soma, 11);
  v_dv1 := CASE WHEN v_resto < 2 THEN 0 ELSE 11 - v_resto END;

  v_soma := 0;
  FOR v_indice IN 1..12 LOOP
    v_soma := v_soma
      + (ascii(substr(v_cnpj, v_indice, 1)) - 48) * v_pesos_segundo[v_indice];
  END LOOP;
  v_soma := v_soma + v_dv1 * v_pesos_segundo[13];
  v_resto := mod(v_soma, 11);
  v_dv2 := CASE WHEN v_resto < 2 THEN 0 ELSE 11 - v_resto END;

  RETURN substr(v_cnpj, 13, 1)::integer = v_dv1
     AND substr(v_cnpj, 14, 1)::integer = v_dv2;
END;
$_$;


--
-- Name: FUNCTION fiscal_cnpj_valido(p_valor text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fiscal_cnpj_valido(p_valor text) IS 'Valida CNPJ numérico ou alfanumérico pelo módulo 11 oficial (valor ASCII menos 48).';


--
-- Name: fiscal_dfe_cancelar_apropriacao_comercial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_dfe_cancelar_apropriacao_comercial() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status::text='CANCELADA' AND OLD.status::text<>'CANCELADA' THEN
    UPDATE public.fiscal_dfe_item_apropriacao SET cancelada_at=now()
    WHERE entrada_id=NEW.id AND cancelada_at IS NULL;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fiscal_difal_regra_touch_atualizado_em(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_difal_regra_touch_atualizado_em() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.atualizado_em := now();
  RETURN NEW;
END;
$$;


--
-- Name: fiscal_guardar_contexto_dfe_ativo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_guardar_contexto_dfe_ativo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cnpj text := public.fiscal_cnpj_normalizar(NEW.cnpj_consultado);
  v_ambiente text := upper(btrim(coalesce(NEW.ambiente_consultado, '')));
BEGIN
  IF NOT public.fiscal_cnpj_valido(v_cnpj)
     OR v_ambiente NOT IN ('HOMOLOGACAO', 'PRODUCAO') THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.fiscal_dfe_contexto (
    empresa_id, cnpj, ambiente, ult_nsu, max_nsu, last_sync_at,
    last_cstat, last_xmotivo, next_sync_after, consumo_indevido_until,
    sync_started_at, consulta_chave_window_started_at,
    consulta_chave_count, updatedat
  ) VALUES (
    NEW.empresa_id, v_cnpj, v_ambiente,
    coalesce(NEW.ult_nsu, '000000000000000'),
    coalesce(NEW.max_nsu, '000000000000000'),
    NEW.last_sync_at, NEW.last_cstat, NEW.last_xmotivo,
    NEW.next_sync_after, NEW.consumo_indevido_until, NEW.sync_started_at,
    NEW.consulta_chave_window_started_at,
    coalesce(NEW.consulta_chave_count, 0), now()
  )
  ON CONFLICT (empresa_id, cnpj, ambiente)
  DO UPDATE SET
    ult_nsu = EXCLUDED.ult_nsu,
    max_nsu = EXCLUDED.max_nsu,
    last_sync_at = EXCLUDED.last_sync_at,
    last_cstat = EXCLUDED.last_cstat,
    last_xmotivo = EXCLUDED.last_xmotivo,
    next_sync_after = EXCLUDED.next_sync_after,
    consumo_indevido_until = EXCLUDED.consumo_indevido_until,
    sync_started_at = EXCLUDED.sync_started_at,
    consulta_chave_window_started_at = EXCLUDED.consulta_chave_window_started_at,
    consulta_chave_count = EXCLUDED.consulta_chave_count,
    updatedat = now();

  RETURN NEW;
END;
$$;


--
-- Name: fiscal_registrar_cancelamento_nfe(bigint, integer, text, text, text, text, text, date, text, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_registrar_cancelamento_nfe(p_nfe_id bigint, p_empresa_id integer, p_chave_acesso text, p_justificativa text, p_status_evento text, p_protocolo_evento text, p_data_evento_original text, p_data_evento_civil date, p_data_evento_offset text, p_data_evento_instante_utc timestamp with time zone, p_xml_evento text, p_resposta_sefaz text, p_xml_sha256 text, p_resposta_sha256 text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento public.fiscal_documento_evento%ROWTYPE;
BEGIN
  PERFORM 1
    FROM public.nfe
   WHERE id = p_nfe_id
     AND empresaid = p_empresa_id
     AND chave_acesso = p_chave_acesso
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'NF-e do cancelamento não encontrada ou contexto divergente.'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_evento
    FROM public.fiscal_documento_evento
   WHERE nfe_id = p_nfe_id
     AND tipo_evento = '110111'
     AND sequencia = 1;

  IF FOUND THEN
    IF v_evento.protocolo_evento IS DISTINCT FROM p_protocolo_evento
       OR v_evento.xml_sha256 IS DISTINCT FROM p_xml_sha256
       OR v_evento.resposta_sha256 IS DISTINCT FROM p_resposta_sha256 THEN
      RAISE EXCEPTION 'Cancelamento já preservado com conteúdo divergente.'
        USING ERRCODE = '23505';
    END IF;
  ELSE
    INSERT INTO public.fiscal_documento_evento(
      empresa_id, nfe_id, chave_acesso, tipo_evento, sequencia,
      status_evento, protocolo_evento, data_evento_original,
      data_evento_civil, data_evento_offset, data_evento_instante_utc,
      xml_evento, resposta_sefaz, xml_sha256, resposta_sha256, origem
    ) VALUES (
      p_empresa_id, p_nfe_id, p_chave_acesso, '110111', 1,
      p_status_evento, p_protocolo_evento, p_data_evento_original,
      p_data_evento_civil, p_data_evento_offset, p_data_evento_instante_utc,
      p_xml_evento, p_resposta_sefaz, p_xml_sha256, p_resposta_sha256, 'SEFAZ'
    );
  END IF;

  UPDATE public.nfe
     SET status = 'CANCELADA',
         updatedat = now(),
         justificativacancelamento = p_justificativa
   WHERE id = p_nfe_id;
END;
$$;


--
-- Name: fiscal_reset_dfe_por_troca_cnpj(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_reset_dfe_por_troca_cnpj(p_empresa_id integer, p_cnpj text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cnpj text := regexp_replace(coalesce(p_cnpj, ''), '\D', '', 'g');
BEGIN
  IF length(v_cnpj) <> 14 THEN
    RAISE EXCEPTION 'CNPJ inválido para reinicialização do DF-e.';
  END IF;

  DELETE FROM public.fiscal_dfe_documento
  WHERE empresa_id = p_empresa_id;

  INSERT INTO public.fiscal_dfe_controle (
    empresa_id,
    cnpj_consultado,
    ult_nsu,
    max_nsu,
    last_sync_at,
    last_cstat,
    last_xmotivo,
    next_sync_after,
    consumo_indevido_until,
    sync_lock_until,
    sync_started_at,
    updatedat
  )
  VALUES (
    p_empresa_id,
    v_cnpj,
    '000000000000000',
    '000000000000000',
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    now()
  )
  ON CONFLICT (empresa_id)
  DO UPDATE SET
    cnpj_consultado = EXCLUDED.cnpj_consultado,
    ult_nsu = EXCLUDED.ult_nsu,
    max_nsu = EXCLUDED.max_nsu,
    last_sync_at = NULL,
    last_cstat = NULL,
    last_xmotivo = NULL,
    next_sync_after = NULL,
    consumo_indevido_until = NULL,
    sync_lock_until = NULL,
    sync_started_at = NULL,
    updatedat = now();
END;
$$;


--
-- Name: fiscal_salvar_dfe_consulta_pontual(integer, jsonb, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_salvar_dfe_consulta_pontual(p_empresa_id integer, p_docs jsonb, p_cstat text, p_xmotivo text, p_consumo_indevido_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_controle public.fiscal_dfe_controle%ROWTYPE;
  v_inseridos integer := 0;
BEGIN
  SELECT * INTO v_controle
  FROM public.fiscal_dfe_controle
  WHERE empresa_id = p_empresa_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Controle DF-e nao encontrado para a empresa %.', p_empresa_id;
  END IF;

  v_inseridos := public.fiscal_salvar_dfe_lote(
    p_empresa_id,
    p_docs,
    v_controle.ult_nsu,
    v_controle.max_nsu,
    p_cstat,
    p_xmotivo,
    v_controle.next_sync_after,
    CASE
      WHEN p_cstat = '656' THEN p_consumo_indevido_until
      ELSE v_controle.consumo_indevido_until
    END
  );

  -- A consulta consChNFe nao faz parte da sequencia distNSU. Preserva o
  -- cursor, o horario da distribuicao e seu cooldown. Somente um novo 656
  -- pode atualizar o bloqueio global do CNPJ.
  UPDATE public.fiscal_dfe_controle
  SET
    ult_nsu = v_controle.ult_nsu,
    max_nsu = v_controle.max_nsu,
    last_sync_at = v_controle.last_sync_at,
    last_cstat = CASE WHEN p_cstat = '656' THEN p_cstat ELSE v_controle.last_cstat END,
    last_xmotivo = CASE WHEN p_cstat = '656' THEN p_xmotivo ELSE v_controle.last_xmotivo END,
    next_sync_after = v_controle.next_sync_after,
    consumo_indevido_until = CASE
      WHEN p_cstat = '656' THEN p_consumo_indevido_until
      ELSE v_controle.consumo_indevido_until
    END,
    updatedat = now()
  WHERE empresa_id = p_empresa_id;

  RETURN v_inseridos;
END;
$$;


--
-- Name: fiscal_salvar_dfe_lote(integer, jsonb, text, text, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_salvar_dfe_lote(p_empresa_id integer, p_docs jsonb, p_ult_nsu text, p_max_nsu text, p_cstat text, p_xmotivo text, p_next_sync_after timestamp with time zone DEFAULT NULL::timestamp with time zone, p_consumo_indevido_until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_doc jsonb;
  v_existing_id bigint;
  v_existing_schema text;
  v_inserted integer := 0;
  v_chave text;
  v_schema text;
  v_nsu text;
  v_is_nfe boolean;
  v_should_keep_proc boolean;
BEGIN
  FOR v_doc IN SELECT * FROM jsonb_array_elements(coalesce(p_docs, '[]'::jsonb))
  LOOP
    v_nsu := nullif(v_doc->>'nsu', '');
    v_schema := nullif(v_doc->>'schema', '');
    v_chave := nullif(v_doc->>'chave_acesso', '');
    v_existing_id := NULL;
    v_existing_schema := NULL;
    v_is_nfe := v_schema LIKE 'resNFe%' OR v_schema LIKE 'procNFe%';

    IF v_nsu IS NULL OR v_schema IS NULL THEN
      CONTINUE;
    END IF;

    IF v_is_nfe AND v_chave IS NOT NULL THEN
      SELECT id, schema INTO v_existing_id, v_existing_schema
      FROM public.fiscal_dfe_documento
      WHERE empresa_id = p_empresa_id
        AND chave_acesso = v_chave
        AND (schema LIKE 'resNFe%' OR schema LIKE 'procNFe%')
      ORDER BY createdat ASC NULLS LAST, id ASC
      LIMIT 1;
    END IF;

    IF v_existing_id IS NULL THEN
      SELECT id, schema INTO v_existing_id, v_existing_schema
      FROM public.fiscal_dfe_documento
      WHERE empresa_id = p_empresa_id
        AND nsu = v_nsu
      LIMIT 1;
    END IF;

    IF v_existing_id IS NULL AND v_chave IS NOT NULL THEN
      SELECT id, schema INTO v_existing_id, v_existing_schema
      FROM public.fiscal_dfe_documento
      WHERE empresa_id = p_empresa_id
        AND chave_acesso = v_chave
        AND schema = v_schema
      LIMIT 1;
    END IF;

    IF v_existing_id IS NULL THEN
      INSERT INTO public.fiscal_dfe_documento (
        empresa_id,
        nsu,
        schema,
        tipo_documento,
        chave_acesso,
        data_emissao,
        emitente_nome,
        emitente_cnpj,
        valor_total,
        status,
        status_manifestacao,
        xml,
        resumo,
        updatedat
      )
      VALUES (
        p_empresa_id,
        v_nsu,
        v_schema,
        coalesce(v_doc->>'tipo_documento', 'OUTRO'),
        v_chave,
        nullif(v_doc->>'data_emissao', '')::timestamp with time zone,
        nullif(v_doc->>'emitente_nome', ''),
        nullif(v_doc->>'emitente_cnpj', ''),
        nullif(v_doc->>'valor_total', '')::numeric,
        nullif(v_doc->>'status', ''),
        nullif(v_doc->>'status_manifestacao', ''),
        coalesce(v_doc->>'xml', ''),
        jsonb_strip_nulls(
          coalesce(v_doc->'resumo', '{}'::jsonb) ||
          CASE
            WHEN v_is_nfe THEN jsonb_build_object(
              'nsuResumo', CASE WHEN v_schema LIKE 'resNFe%' THEN v_nsu ELSE NULL END,
              'nsuProcNFe', CASE WHEN v_schema LIKE 'procNFe%' THEN v_nsu ELSE NULL END
            )
            ELSE '{}'::jsonb
          END
        ),
        now()
      );
      v_inserted := v_inserted + 1;
    ELSE
      IF v_is_nfe AND v_chave IS NOT NULL THEN
        DELETE FROM public.fiscal_dfe_documento
        WHERE empresa_id = p_empresa_id
          AND chave_acesso = v_chave
          AND id <> v_existing_id
          AND (schema LIKE 'resNFe%' OR schema LIKE 'procNFe%');
      END IF;

      v_should_keep_proc := v_is_nfe
        AND v_existing_schema LIKE 'procNFe%'
        AND v_schema LIKE 'resNFe%';

      UPDATE public.fiscal_dfe_documento
      SET
        schema = CASE WHEN v_should_keep_proc THEN schema ELSE v_schema END,
        tipo_documento = CASE
          WHEN v_should_keep_proc THEN tipo_documento
          ELSE coalesce(v_doc->>'tipo_documento', tipo_documento)
        END,
        chave_acesso = coalesce(v_chave, chave_acesso),
        data_emissao = coalesce(nullif(v_doc->>'data_emissao', '')::timestamp with time zone, data_emissao),
        emitente_nome = coalesce(nullif(v_doc->>'emitente_nome', ''), emitente_nome),
        emitente_cnpj = coalesce(nullif(v_doc->>'emitente_cnpj', ''), emitente_cnpj),
        valor_total = coalesce(nullif(v_doc->>'valor_total', '')::numeric, valor_total),
        status = coalesce(nullif(v_doc->>'status', ''), status),
        status_manifestacao = coalesce(status_manifestacao, nullif(v_doc->>'status_manifestacao', '')),
        xml = CASE
          WHEN v_should_keep_proc THEN xml
          ELSE coalesce(nullif(v_doc->>'xml', ''), xml)
        END,
        resumo = CASE
          WHEN v_is_nfe THEN jsonb_strip_nulls(
            coalesce(resumo, '{}'::jsonb) ||
            CASE WHEN v_should_keep_proc THEN '{}'::jsonb ELSE coalesce(v_doc->'resumo', '{}'::jsonb) END ||
            jsonb_build_object(
              'nsuResumo', CASE
                WHEN v_schema LIKE 'resNFe%' THEN coalesce(resumo->>'nsuResumo', v_nsu)
                ELSE resumo->>'nsuResumo'
              END,
              'nsuProcNFe', CASE
                WHEN v_schema LIKE 'procNFe%' THEN v_nsu
                ELSE resumo->>'nsuProcNFe'
              END,
              'xmlCompletoConsulta', CASE
                WHEN v_schema LIKE 'procNFe%' THEN jsonb_build_object('disponivel', true, 'consultadoEm', now())
                ELSE resumo->'xmlCompletoConsulta'
              END
            )
          )
          ELSE coalesce(v_doc->'resumo', resumo)
        END,
        updatedat = now()
      WHERE id = v_existing_id;
    END IF;
  END LOOP;

  INSERT INTO public.fiscal_dfe_controle (
    empresa_id,
    ult_nsu,
    max_nsu,
    last_cstat,
    last_xmotivo,
    last_sync_at,
    next_sync_after,
    consumo_indevido_until,
    updatedat
  )
  VALUES (
    p_empresa_id,
    p_ult_nsu,
    p_max_nsu,
    p_cstat,
    p_xmotivo,
    now(),
    p_next_sync_after,
    p_consumo_indevido_until,
    now()
  )
  ON CONFLICT (empresa_id)
  DO UPDATE SET
    ult_nsu = EXCLUDED.ult_nsu,
    max_nsu = EXCLUDED.max_nsu,
    last_cstat = EXCLUDED.last_cstat,
    last_xmotivo = EXCLUDED.last_xmotivo,
    last_sync_at = now(),
    next_sync_after = EXCLUDED.next_sync_after,
    consumo_indevido_until = EXCLUDED.consumo_indevido_until,
    updatedat = now();

  RETURN v_inserted;
END;
$$;


--
-- Name: fiscal_sped_abrir_versao(bigint, text, text, text, text, text, timestamp with time zone, text, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_abrir_versao(p_competencia_id bigint, p_finalidade text, p_leiaute text, p_guia_pratico text, p_motor_versao text, p_git_commit text, p_source_cutoff_at timestamp with time zone, p_context_hash text, p_usuario_id uuid, p_versao_anterior_id bigint DEFAULT NULL::bigint, p_motivo_abertura text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_competencia public.fiscal_sped_competencia%ROWTYPE;
  v_numero integer;
  v_id bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(2147480000, (p_competencia_id % 2147483647)::integer);
  SELECT * INTO v_competencia
    FROM public.fiscal_sped_competencia
   WHERE id = p_competencia_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Competencia SPED inexistente.' USING ERRCODE = 'P0002';
  END IF;
  IF v_competencia.status = 'FECHADA' THEN
    RAISE EXCEPTION 'Reabra a competencia antes de criar nova versao.' USING ERRCODE = '55000';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.fiscal_sped_versao
     WHERE competencia_id = p_competencia_id
       AND status IN ('RASCUNHO', 'VALIDADA')
  ) THEN
    RAISE EXCEPTION 'A competencia ja possui versao editavel.' USING ERRCODE = '23505';
  END IF;
  IF p_versao_anterior_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.fiscal_sped_versao
     WHERE id = p_versao_anterior_id
       AND competencia_id = p_competencia_id
       AND status = 'FECHADA'
  ) THEN
    RAISE EXCEPTION 'Versao anterior invalida para a competencia.' USING ERRCODE = '23503';
  END IF;

  SELECT coalesce(max(numero), 0) + 1 INTO v_numero
    FROM public.fiscal_sped_versao
   WHERE competencia_id = p_competencia_id;

  INSERT INTO public.fiscal_sped_versao(
    competencia_id, numero, finalidade, versao_anterior_id, leiaute,
    guia_pratico, motor_versao, git_commit, source_cutoff_at,
    context_hash, motivo_abertura, created_by
  ) VALUES (
    p_competencia_id, v_numero, p_finalidade, p_versao_anterior_id,
    p_leiaute, p_guia_pratico, p_motor_versao, lower(p_git_commit),
    p_source_cutoff_at, lower(p_context_hash), p_motivo_abertura, p_usuario_id
  ) RETURNING id INTO v_id;

  UPDATE public.fiscal_sped_competencia
     SET versao_atual_id = v_id,
         status = 'ABERTA',
         updated_by = p_usuario_id,
         lock_version = lock_version + 1,
         fechada_at = NULL,
         fechada_by = NULL
   WHERE id = p_competencia_id;

  RETURN v_id;
END;
$$;


--
-- Name: fiscal_sped_bloquear_registro_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_bloquear_registro_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'Registro fiscal imutavel: %.%', tg_table_schema, tg_table_name
    USING ERRCODE = '55000';
END;
$$;


--
-- Name: fiscal_sped_concluir_validacao(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_concluir_validacao(p_execucao_id bigint, p_usuario_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_execucao public.fiscal_sped_validacao_execucao%ROWTYPE;
  v_bloqueios integer;
  v_erros integer;
  v_avisos integer;
  v_informacoes integer;
  v_apta boolean;
BEGIN
  SELECT * INTO v_execucao
    FROM public.fiscal_sped_validacao_execucao
   WHERE id = p_execucao_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Execucao de validacao inexistente.' USING ERRCODE = 'P0002';
  END IF;
  IF v_execucao.status <> 'PROCESSANDO' OR v_execucao.versao_id IS NULL THEN
    RAISE EXCEPTION 'Execucao de validacao nao esta processando uma versao.' USING ERRCODE = '55000';
  END IF;
  PERFORM pg_advisory_xact_lock(2147480000, (v_execucao.competencia_id % 2147483647)::integer);

  SELECT
    count(*) FILTER (WHERE severidade = 'BLOQUEIO'),
    count(*) FILTER (WHERE severidade = 'ERRO'),
    count(*) FILTER (WHERE severidade = 'AVISO' AND status = 'ABERTA'),
    count(*) FILTER (WHERE severidade = 'INFORMACAO' AND status = 'ABERTA')
  INTO v_bloqueios, v_erros, v_avisos, v_informacoes
  FROM public.fiscal_sped_inconsistencia
  WHERE execucao_id = p_execucao_id;

  v_apta := v_bloqueios = 0 AND v_erros = 0;

  UPDATE public.fiscal_sped_validacao_execucao
     SET status = 'CONCLUIDA', concluido_at = now(),
         quantidade_bloqueios = v_bloqueios,
         quantidade_erros = v_erros,
         quantidade_avisos = v_avisos,
         quantidade_informacoes = v_informacoes
   WHERE id = p_execucao_id;

  IF v_apta THEN
    UPDATE public.fiscal_sped_versao
       SET status = 'VALIDADA', validated_at = now(), validated_by = p_usuario_id
     WHERE id = v_execucao.versao_id AND status = 'RASCUNHO';
  END IF;

  UPDATE public.fiscal_sped_competencia
     SET status = CASE WHEN v_apta THEN 'APTA' ELSE 'COM_ERROS' END,
         updated_by = p_usuario_id,
         lock_version = lock_version + 1
   WHERE id = v_execucao.competencia_id;

  RETURN jsonb_build_object(
    'apta', v_apta,
    'bloqueios', v_bloqueios,
    'erros', v_erros,
    'avisos', v_avisos,
    'informacoes', v_informacoes
  );
END;
$$;


--
-- Name: fiscal_sped_configurar_item_competencia(bigint, integer, text, text, bigint, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_configurar_item_competencia(p_competencia_id bigint, p_produto_id integer, p_codigo_item text, p_tipo_item text, p_documento_id bigint, p_numero_item integer, p_tratamento_credito text, p_evidencia text, p_usuario_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_competencia public.fiscal_sped_competencia%ROWTYPE;
  v_config public.fiscal_sped_item_config%ROWTYPE;
  v_decisao public.fiscal_sped_item_credito_decisao%ROWTYPE;
  v_config_id bigint;
  v_decisao_id bigint;
BEGIN
  IF nullif(btrim(p_evidencia), '') IS NULL THEN
    RAISE EXCEPTION 'A evidencia da decisao fiscal e obrigatoria.' USING ERRCODE = '22023';
  END IF;
  IF p_produto_id IS NULL AND p_documento_id IS NULL THEN
    RAISE EXCEPTION 'Informe a configuracao do produto ou a decisao de credito.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_competencia
    FROM public.fiscal_sped_competencia
   WHERE id = p_competencia_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Competencia SPED inexistente.' USING ERRCODE = 'P0002';
  END IF;
  IF v_competencia.status = 'FECHADA' THEN
    RAISE EXCEPTION 'Competencia fechada nao aceita decisoes fiscais.' USING ERRCODE = '55000';
  END IF;

  IF p_produto_id IS NOT NULL THEN
    IF nullif(btrim(p_codigo_item), '') IS NULL OR p_tipo_item IS NULL OR p_tipo_item !~ '^[0-9]{2}$' THEN
      RAISE EXCEPTION 'Codigo canonico e tipo de item valido sao obrigatorios.' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_config
      FROM public.fiscal_sped_item_config
     WHERE empresa_id = v_competencia.empresa_id
       AND produto_id = p_produto_id
       AND vigencia_inicio <= v_competencia.competencia
       AND (vigencia_fim IS NULL OR vigencia_fim >= v_competencia.competencia)
     ORDER BY vigencia_inicio DESC
     LIMIT 1
     FOR UPDATE;

    IF FOUND AND v_config.vigencia_inicio = v_competencia.competencia THEN
      UPDATE public.fiscal_sped_item_config
         SET codigo_item = btrim(p_codigo_item), tipo_item = p_tipo_item,
             fonte = 'CONFIGURACAO_MANUAL', evidencia = btrim(p_evidencia),
             updated_by = p_usuario_id
       WHERE id = v_config.id
      RETURNING id INTO v_config_id;
    ELSE
      IF FOUND THEN
        UPDATE public.fiscal_sped_item_config
           SET vigencia_fim = v_competencia.competencia - 1, updated_by = p_usuario_id
         WHERE id = v_config.id;
      END IF;
      INSERT INTO public.fiscal_sped_item_config(
        empresa_id, produto_id, codigo_item, tipo_item, vigencia_inicio,
        fonte, evidencia, created_by, updated_by
      ) VALUES (
        v_competencia.empresa_id, p_produto_id, btrim(p_codigo_item), p_tipo_item,
        v_competencia.competencia, 'CONFIGURACAO_MANUAL', btrim(p_evidencia),
        p_usuario_id, p_usuario_id
      ) RETURNING id INTO v_config_id;
    END IF;
  END IF;

  IF p_documento_id IS NOT NULL THEN
    IF p_numero_item IS NULL OR p_numero_item <= 0
       OR p_tratamento_credito IS NULL
       OR p_tratamento_credito NOT IN ('CREDITAVEL', 'SEM_CREDITO', 'USO_CONSUMO', 'ATIVO_IMOBILIZADO') THEN
      RAISE EXCEPTION 'Decisao de credito invalida.' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.fiscal_dfe_documento
       WHERE id = p_documento_id AND empresa_id = v_competencia.empresa_id
    ) THEN
      RAISE EXCEPTION 'DFe nao pertence ao estabelecimento da competencia.' USING ERRCODE = '23503';
    END IF;
    SELECT * INTO v_decisao
      FROM public.fiscal_sped_item_credito_decisao
     WHERE documento_id = p_documento_id
       AND numero_item = p_numero_item
       AND vigencia_inicio <= v_competencia.competencia
       AND (vigencia_fim IS NULL OR vigencia_fim >= v_competencia.competencia)
     ORDER BY vigencia_inicio DESC
     LIMIT 1
     FOR UPDATE;

    IF FOUND AND v_decisao.vigencia_inicio = v_competencia.competencia THEN
      UPDATE public.fiscal_sped_item_credito_decisao
         SET tratamento_credito = p_tratamento_credito,
             evidencia = btrim(p_evidencia), updated_by = p_usuario_id
       WHERE id = v_decisao.id
      RETURNING id INTO v_decisao_id;
    ELSE
      IF FOUND THEN
        UPDATE public.fiscal_sped_item_credito_decisao
           SET vigencia_fim = v_competencia.competencia - 1, updated_by = p_usuario_id
         WHERE id = v_decisao.id;
      END IF;
      INSERT INTO public.fiscal_sped_item_credito_decisao(
        empresa_id, documento_id, numero_item, tratamento_credito, evidencia,
        vigencia_inicio, created_by, updated_by
      ) VALUES (
        v_competencia.empresa_id, p_documento_id, p_numero_item,
        p_tratamento_credito, btrim(p_evidencia), v_competencia.competencia,
        p_usuario_id, p_usuario_id
      ) RETURNING id INTO v_decisao_id;
    END IF;
  END IF;

  RETURN jsonb_build_object('itemConfigId', v_config_id, 'creditDecisionId', v_decisao_id);
END;
$_$;


--
-- Name: fiscal_sped_criar_competencia(integer, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_criar_competencia(p_empresa_id integer, p_competencia date, p_usuario_id uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
  v_lock_key integer;
BEGIN
  IF p_competencia IS NULL
     OR p_competencia <> date_trunc('month', p_competencia)::date THEN
    RAISE EXCEPTION 'Competencia deve ser o primeiro dia do mes.' USING ERRCODE = '22023';
  END IF;

  v_lock_key := extract(year FROM p_competencia)::integer * 100
    + extract(month FROM p_competencia)::integer;
  PERFORM pg_advisory_xact_lock(p_empresa_id, v_lock_key);

  INSERT INTO public.fiscal_sped_competencia(
    empresa_id, competencia, created_by, updated_by
  ) VALUES (
    p_empresa_id, p_competencia, p_usuario_id, p_usuario_id
  )
  ON CONFLICT (empresa_id, competencia) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
      FROM public.fiscal_sped_competencia
     WHERE empresa_id = p_empresa_id
       AND competencia = p_competencia;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: fiscal_sped_fechar_versao(bigint, bigint, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_fechar_versao(p_competencia_id bigint, p_versao_id bigint, p_expected_lock_version integer, p_context_hash text, p_usuario_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_competencia public.fiscal_sped_competencia%ROWTYPE;
  v_versao public.fiscal_sped_versao%ROWTYPE;
  v_config public.fiscal_sped_config%ROWTYPE;
  v_novo_lock integer;
BEGIN
  PERFORM pg_advisory_xact_lock(2147480000, (p_competencia_id % 2147483647)::integer);
  SELECT * INTO v_competencia
    FROM public.fiscal_sped_competencia
   WHERE id = p_competencia_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Competencia SPED inexistente.' USING ERRCODE = 'P0002';
  END IF;
  IF v_competencia.lock_version <> p_expected_lock_version THEN
    RAISE EXCEPTION 'Competencia alterada por outro processo.' USING ERRCODE = '40001';
  END IF;
  IF v_competencia.status <> 'APTA' OR v_competencia.versao_atual_id <> p_versao_id THEN
    RAISE EXCEPTION 'Competencia nao esta apta com a versao informada.' USING ERRCODE = '55000';
  END IF;

  SELECT * INTO v_versao
    FROM public.fiscal_sped_versao
   WHERE id = p_versao_id AND competencia_id = p_competencia_id
   FOR UPDATE;
  IF NOT FOUND OR v_versao.status <> 'VALIDADA' THEN
    RAISE EXCEPTION 'Versao SPED nao esta validada.' USING ERRCODE = '55000';
  END IF;
  IF lower(p_context_hash) <> v_versao.context_hash THEN
    RAISE EXCEPTION 'Hash de contexto divergente.' USING ERRCODE = '40001';
  END IF;

  SELECT * INTO v_config
    FROM public.fiscal_sped_config
   WHERE empresa_id = v_competencia.empresa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Configuracao SPED ausente.' USING ERRCODE = '23514';
  END IF;
  IF v_config.timezone_status <> 'CONFIRMADO'
     OR v_config.perfil_efd_status <> 'CONFIRMADO'
     OR v_config.indicador_atividade_status <> 'CONFIRMADO'
     OR v_config.bloco_k_status = 'PENDENTE'
     OR v_config.registro_1400_status = 'PENDENTE'
     OR v_config.c176_c179_status = 'PENDENTE'
     OR v_config.registro_1601_status = 'PENDENTE'
     OR v_config.inventario_status = 'PENDENTE'
     OR v_config.contribuinte_ipi_status = 'PENDENTE'
     OR v_config.entrega_efd_contribuicoes_status = 'PENDENTE' THEN
    RAISE EXCEPTION 'Existem gates fiscais pendentes na configuracao SPED.' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.fiscal_sped_validacao_execucao execucao
     WHERE execucao.versao_id = p_versao_id
       AND execucao.status = 'CONCLUIDA'
       AND execucao.context_hash = v_versao.context_hash
       AND execucao.quantidade_bloqueios = 0
       AND execucao.quantidade_erros = 0
  ) THEN
    RAISE EXCEPTION 'Versao sem validacao concluida e livre de erros.' USING ERRCODE = '23514';
  END IF;

  IF v_versao.versao_anterior_id IS NOT NULL THEN
    UPDATE public.fiscal_sped_versao
       SET status = 'SUBSTITUIDA', substituted_at = now()
     WHERE id = v_versao.versao_anterior_id
       AND status = 'FECHADA';
  END IF;

  UPDATE public.fiscal_sped_versao
     SET status = 'FECHADA', closed_at = now(), closed_by = p_usuario_id
   WHERE id = p_versao_id;

  UPDATE public.fiscal_sped_competencia
     SET status = 'FECHADA', fechada_at = now(), fechada_by = p_usuario_id,
         updated_by = p_usuario_id, lock_version = lock_version + 1
   WHERE id = p_competencia_id
  RETURNING lock_version INTO v_novo_lock;

  RETURN v_novo_lock;
END;
$$;


--
-- Name: fiscal_sped_guardar_estado_competencia(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_guardar_estado_competencia() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'Competencias SPED nao podem ser excluidas.' USING ERRCODE = '55000';
  END IF;

  IF OLD.status IS DISTINCT FROM NEW.status AND NOT (
    (OLD.status = 'ABERTA' AND NEW.status = 'EM_VALIDACAO')
    OR (OLD.status = 'EM_VALIDACAO' AND NEW.status IN ('ABERTA', 'COM_ERROS', 'APTA'))
    OR (OLD.status = 'COM_ERROS' AND NEW.status IN ('ABERTA', 'EM_VALIDACAO'))
    OR (OLD.status = 'APTA' AND NEW.status IN ('ABERTA', 'EM_VALIDACAO', 'FECHADA'))
    OR (OLD.status = 'FECHADA' AND NEW.status = 'ABERTA')
  ) THEN
    RAISE EXCEPTION 'Transicao de competencia SPED invalida: % -> %', OLD.status, NEW.status
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fiscal_sped_guardar_inventario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_guardar_inventario() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linha jsonb;
  v_status text;
BEGIN
  v_linha := CASE WHEN tg_op = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  SELECT status INTO v_status
    FROM public.fiscal_inventario_fechamento
   WHERE id = (v_linha ->> 'inventario_id')::bigint;

  IF v_status IN ('APROVADO', 'CANCELADO') THEN
    RAISE EXCEPTION 'Itens de inventario aprovado/cancelado sao imutaveis.'
      USING ERRCODE = '55000';
  END IF;

  IF tg_op = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fiscal_sped_guardar_mutacao_competencia_aberta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_guardar_mutacao_competencia_aberta() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linha jsonb;
  v_competencia_id bigint;
  v_status text;
BEGIN
  v_linha := CASE WHEN tg_op = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;

  IF tg_table_name = 'fiscal_sped_1601_linha' THEN
    SELECT importacao.competencia_id
      INTO v_competencia_id
      FROM public.fiscal_sped_1601_importacao importacao
     WHERE importacao.id = (v_linha ->> 'importacao_id')::bigint;
  ELSE
    v_competencia_id := (v_linha ->> 'competencia_id')::bigint;
  END IF;

  SELECT status INTO v_status
    FROM public.fiscal_sped_competencia
   WHERE id = v_competencia_id;

  IF v_status = 'FECHADA' THEN
    RAISE EXCEPTION 'A competencia SPED fechada nao aceita alteracao de dados de entrada.'
      USING ERRCODE = '55000';
  END IF;

  IF tg_op = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fiscal_sped_guardar_snapshot_rascunho(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_guardar_snapshot_rascunho() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_linha jsonb;
  v_versao_id bigint;
  v_status text;
BEGIN
  v_linha := CASE WHEN tg_op = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;

  IF tg_table_name = 'fiscal_sped_item_snapshot' THEN
    SELECT documento.versao_id
      INTO v_versao_id
      FROM public.fiscal_sped_documento_snapshot documento
     WHERE documento.id = (v_linha ->> 'documento_snapshot_id')::bigint;
  ELSE
    v_versao_id := (v_linha ->> 'versao_id')::bigint;
  END IF;

  SELECT status INTO v_status
    FROM public.fiscal_sped_versao
   WHERE id = v_versao_id;

  IF v_status IS DISTINCT FROM 'RASCUNHO' THEN
    RAISE EXCEPTION 'Snapshots somente podem ser alterados em versao RASCUNHO.'
      USING ERRCODE = '55000';
  END IF;

  IF tg_op = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: fiscal_sped_guardar_versao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_guardar_versao() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'Versoes SPED nao podem ser excluidas.' USING ERRCODE = '55000';
  END IF;

  IF OLD.status = 'SUBSTITUIDA' THEN
    RAISE EXCEPTION 'Versao SPED substituida e imutavel.' USING ERRCODE = '55000';
  END IF;

  IF OLD.status = 'FECHADA' THEN
    IF NEW.status <> 'SUBSTITUIDA'
       OR (to_jsonb(NEW) - ARRAY['status', 'substituted_at']::text[])
          IS DISTINCT FROM
          (to_jsonb(OLD) - ARRAY['status', 'substituted_at']::text[]) THEN
      RAISE EXCEPTION 'Versao SPED fechada somente pode ser marcada como SUBSTITUIDA.'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'RASCUNHO' AND NEW.status = 'VALIDADA')
    OR (OLD.status = 'VALIDADA' AND NEW.status IN ('RASCUNHO', 'FECHADA'))
  ) THEN
    RAISE EXCEPTION 'Transicao de versao SPED invalida: % -> %', OLD.status, NEW.status
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fiscal_sped_importar_1601(bigint, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_importar_1601(p_competencia_id bigint, p_nome_arquivo text, p_storage_path text, p_arquivo_sha256 text, p_linhas jsonb, p_usuario_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_competencia public.fiscal_sped_competencia%ROWTYPE;
  v_id bigint;
BEGIN
  SELECT * INTO v_competencia
    FROM public.fiscal_sped_competencia
   WHERE id = p_competencia_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Competencia SPED nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_competencia.status = 'FECHADA' THEN
    RAISE EXCEPTION 'Competencia SPED fechada nao aceita importacao.' USING ERRCODE = '55000';
  END IF;
  IF jsonb_typeof(p_linhas) <> 'array' OR jsonb_array_length(p_linhas) = 0 THEN
    RAISE EXCEPTION 'Importacao 1601 exige ao menos uma linha.' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_id
    FROM public.fiscal_sped_1601_importacao
   WHERE competencia_id = p_competencia_id
     AND arquivo_sha256 = p_arquivo_sha256;
  IF FOUND THEN RETURN v_id; END IF;

  UPDATE public.fiscal_sped_1601_importacao
     SET status = 'REJEITADA'
   WHERE competencia_id = p_competencia_id
     AND status = 'VALIDADA';

  INSERT INTO public.fiscal_sped_1601_importacao(
    competencia_id, nome_arquivo, storage_path, arquivo_sha256,
    status, quantidade_linhas, imported_by
  ) VALUES (
    p_competencia_id, p_nome_arquivo, p_storage_path, p_arquivo_sha256,
    'VALIDADA', jsonb_array_length(p_linhas), p_usuario_id
  ) RETURNING id INTO v_id;

  INSERT INTO public.fiscal_sped_1601_linha(
    importacao_id, numero_linha, instituicao_cnpj, instituicao_nome,
    instituicao_codigo_participante, intermediario_cnpj, intermediario_nome,
    intermediario_codigo_participante, total_operacoes, total_icms,
    total_iss, total_outros, dados_origem
  )
  SELECT
    v_id, linha.numero_linha, linha.instituicao_cnpj,
    linha.instituicao_nome, linha.instituicao_codigo_participante,
    linha.intermediario_cnpj, linha.intermediario_nome,
    linha.intermediario_codigo_participante, linha.total_operacoes,
    0, linha.total_iss, linha.total_outros, linha.dados_origem
  FROM jsonb_to_recordset(p_linhas) AS linha(
    numero_linha integer,
    instituicao_cnpj text,
    instituicao_nome text,
    instituicao_codigo_participante text,
    intermediario_cnpj text,
    intermediario_nome text,
    intermediario_codigo_participante text,
    total_operacoes numeric,
    total_iss numeric,
    total_outros numeric,
    dados_origem jsonb
  );

  RETURN v_id;
END;
$$;


--
-- Name: fiscal_sped_importar_efd_anterior(bigint, date, text, text, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_importar_efd_anterior(p_competencia_id bigint, p_competencia_arquivo date, p_nome_arquivo text, p_storage_path text, p_arquivo_sha256 text, p_cabecalho jsonb, p_saldos_apuracao jsonb, p_usuario_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_competencia public.fiscal_sped_competencia%ROWTYPE;
  v_id bigint;
BEGIN
  SELECT * INTO v_competencia
    FROM public.fiscal_sped_competencia
   WHERE id = p_competencia_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Competencia SPED nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_competencia.status = 'FECHADA' THEN
    RAISE EXCEPTION 'Competencia SPED fechada nao aceita importacao.' USING ERRCODE = '55000';
  END IF;
  IF p_competencia_arquivo <> (v_competencia.competencia - interval '1 month')::date THEN
    RAISE EXCEPTION 'A EFD importada deve ser da competencia imediatamente anterior.' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_id
    FROM public.fiscal_sped_efd_anterior_importacao
   WHERE competencia_id = p_competencia_id
     AND arquivo_sha256 = p_arquivo_sha256;
  IF FOUND THEN RETURN v_id; END IF;

  UPDATE public.fiscal_sped_efd_anterior_importacao
     SET status = 'REJEITADA'
   WHERE competencia_id = p_competencia_id
     AND status = 'VALIDADA';

  INSERT INTO public.fiscal_sped_efd_anterior_importacao(
    competencia_id, competencia_arquivo, nome_arquivo, storage_path,
    arquivo_sha256, status, cabecalho, saldos_apuracao, imported_by
  ) VALUES (
    p_competencia_id, p_competencia_arquivo, p_nome_arquivo, p_storage_path,
    p_arquivo_sha256, 'VALIDADA', coalesce(p_cabecalho, '{}'::jsonb),
    coalesce(p_saldos_apuracao, '{}'::jsonb), p_usuario_id
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


--
-- Name: fiscal_sped_iniciar_validacao(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_iniciar_validacao(p_versao_id bigint, p_context_hash text, p_usuario_id uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_versao public.fiscal_sped_versao%ROWTYPE;
  v_execucao_id bigint;
BEGIN
  SELECT * INTO v_versao
    FROM public.fiscal_sped_versao
   WHERE id = p_versao_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Versao SPED inexistente.' USING ERRCODE = 'P0002';
  END IF;
  PERFORM pg_advisory_xact_lock(2147480000, (v_versao.competencia_id % 2147483647)::integer);
  SELECT * INTO v_versao
    FROM public.fiscal_sped_versao
   WHERE id = p_versao_id
   FOR UPDATE;
  IF v_versao.status NOT IN ('RASCUNHO', 'VALIDADA') THEN
    RAISE EXCEPTION 'Somente versao editavel pode ser validada.' USING ERRCODE = '55000';
  END IF;
  IF lower(p_context_hash) <> v_versao.context_hash THEN
    RAISE EXCEPTION 'Hash de contexto divergente.' USING ERRCODE = '40001';
  END IF;

  IF v_versao.status = 'VALIDADA' THEN
    UPDATE public.fiscal_sped_versao
       SET status = 'RASCUNHO', validated_at = NULL, validated_by = NULL
     WHERE id = p_versao_id;
  END IF;

  INSERT INTO public.fiscal_sped_validacao_execucao(
    competencia_id, versao_id, context_hash, iniciado_by
  ) VALUES (
    v_versao.competencia_id, p_versao_id, lower(p_context_hash), p_usuario_id
  ) RETURNING id INTO v_execucao_id;

  UPDATE public.fiscal_sped_competencia
     SET status = 'EM_VALIDACAO', updated_by = p_usuario_id,
         lock_version = lock_version + 1
   WHERE id = v_versao.competencia_id;

  RETURN v_execucao_id;
END;
$$;


--
-- Name: fiscal_sped_reabrir_competencia(bigint, integer, uuid, text, text, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_reabrir_competencia(p_competencia_id bigint, p_expected_lock_version integer, p_usuario_id uuid, p_motivo text, p_leiaute text, p_guia_pratico text, p_motor_versao text, p_git_commit text, p_source_cutoff_at timestamp with time zone, p_context_hash text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_competencia public.fiscal_sped_competencia%ROWTYPE;
  v_numero integer;
  v_nova_versao_id bigint;
BEGIN
  IF nullif(btrim(p_motivo), '') IS NULL THEN
    RAISE EXCEPTION 'Motivo da reabertura e obrigatorio.' USING ERRCODE = '22023';
  END IF;
  PERFORM pg_advisory_xact_lock(2147480000, (p_competencia_id % 2147483647)::integer);
  SELECT * INTO v_competencia
    FROM public.fiscal_sped_competencia
   WHERE id = p_competencia_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Competencia SPED inexistente.' USING ERRCODE = 'P0002';
  END IF;
  IF v_competencia.status <> 'FECHADA' OR v_competencia.versao_atual_id IS NULL THEN
    RAISE EXCEPTION 'Somente competencia fechada pode ser reaberta.' USING ERRCODE = '55000';
  END IF;
  IF v_competencia.lock_version <> p_expected_lock_version THEN
    RAISE EXCEPTION 'Competencia alterada por outro processo.' USING ERRCODE = '40001';
  END IF;

  SELECT coalesce(max(numero), 0) + 1 INTO v_numero
    FROM public.fiscal_sped_versao
   WHERE competencia_id = p_competencia_id;

  INSERT INTO public.fiscal_sped_versao(
    competencia_id, numero, finalidade, versao_anterior_id, leiaute,
    guia_pratico, motor_versao, git_commit, source_cutoff_at,
    context_hash, motivo_abertura, created_by
  ) VALUES (
    p_competencia_id, v_numero, 'RETIFICADORA', v_competencia.versao_atual_id,
    p_leiaute, p_guia_pratico, p_motor_versao, lower(p_git_commit),
    p_source_cutoff_at, lower(p_context_hash), btrim(p_motivo), p_usuario_id
  ) RETURNING id INTO v_nova_versao_id;

  UPDATE public.fiscal_sped_competencia
     SET status = 'ABERTA', versao_atual_id = v_nova_versao_id,
         fechada_at = NULL, fechada_by = NULL,
         updated_by = p_usuario_id, lock_version = lock_version + 1
   WHERE id = p_competencia_id;

  RETURN v_nova_versao_id;
END;
$$;


--
-- Name: fiscal_sped_registrar_arquivo(bigint, text, text, text, text, text, bigint, integer, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_registrar_arquivo(p_versao_id bigint, p_tipo text, p_finalidade text, p_storage_bucket text, p_storage_path text, p_arquivo_sha256 text, p_tamanho_bytes bigint, p_quantidade_registros integer, p_contadores_registro jsonb, p_generated_by uuid) RETURNS TABLE(id bigint, versao_id bigint, sequencia integer, tipo text, finalidade text, storage_bucket text, storage_path text, arquivo_sha256 text, tamanho_bytes bigint, quantidade_registros integer, contadores_registro jsonb, generated_by uuid, generated_at timestamp with time zone, is_new boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_existing public.fiscal_sped_arquivo%ROWTYPE;
  v_next_seq integer;
  v_inserted public.fiscal_sped_arquivo%ROWTYPE;
  v_lock_key bigint;
BEGIN
  -- Serializa registros de arquivos para a mesma versao usando advisory lock transacional
  v_lock_key := ('x' || substr(md5('sped_arquivo_lock:' || p_versao_id::text), 1, 15))::bit(64)::bigint;
  PERFORM pg_advisory_xact_lock(v_lock_key);

  -- 1. Verifica se arquivo do mesmo tipo e hash já existe para esta versão (idempotência estrita)
  SELECT * INTO v_existing
    FROM public.fiscal_sped_arquivo a
   WHERE a.versao_id = p_versao_id
     AND a.tipo = p_tipo
     AND a.arquivo_sha256 = p_arquivo_sha256
   LIMIT 1;

  IF FOUND THEN
    RETURN QUERY SELECT
      v_existing.id,
      v_existing.versao_id,
      v_existing.sequencia,
      v_existing.tipo,
      v_existing.finalidade,
      v_existing.storage_bucket,
      v_existing.storage_path,
      v_existing.arquivo_sha256,
      v_existing.tamanho_bytes,
      v_existing.quantidade_registros,
      v_existing.contadores_registro,
      v_existing.generated_by,
      v_existing.generated_at,
      false AS is_new;
    RETURN;
  END IF;

  -- 2. Aloca a próxima sequência de forma atômica protegida pelo lock
  SELECT COALESCE(MAX(a.sequencia), 0) + 1 INTO v_next_seq
    FROM public.fiscal_sped_arquivo a
   WHERE a.versao_id = p_versao_id;

  -- 3. Insere o novo registro
  INSERT INTO public.fiscal_sped_arquivo (
    versao_id,
    sequencia,
    tipo,
    finalidade,
    storage_bucket,
    storage_path,
    arquivo_sha256,
    tamanho_bytes,
    quantidade_registros,
    contadores_registro,
    generated_by
  ) VALUES (
    p_versao_id,
    v_next_seq,
    p_tipo,
    p_finalidade,
    p_storage_bucket,
    p_storage_path,
    p_arquivo_sha256,
    p_tamanho_bytes,
    p_quantidade_registros,
    p_contadores_registro,
    p_generated_by
  )
  RETURNING * INTO v_inserted;

  RETURN QUERY SELECT
    v_inserted.id,
    v_inserted.versao_id,
    v_inserted.sequencia,
    v_inserted.tipo,
    v_inserted.finalidade,
    v_inserted.storage_bucket,
    v_inserted.storage_path,
    v_inserted.arquivo_sha256,
    v_inserted.tamanho_bytes,
    v_inserted.quantidade_registros,
    v_inserted.contadores_registro,
    v_inserted.generated_by,
    v_inserted.generated_at,
    true AS is_new;
END;
$$;


--
-- Name: FUNCTION fiscal_sped_registrar_arquivo(p_versao_id bigint, p_tipo text, p_finalidade text, p_storage_bucket text, p_storage_path text, p_arquivo_sha256 text, p_tamanho_bytes bigint, p_quantidade_registros integer, p_contadores_registro jsonb, p_generated_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fiscal_sped_registrar_arquivo(p_versao_id bigint, p_tipo text, p_finalidade text, p_storage_bucket text, p_storage_path text, p_arquivo_sha256 text, p_tamanho_bytes bigint, p_quantidade_registros integer, p_contadores_registro jsonb, p_generated_by uuid) IS 'Aloca sequencia e registra arquivo SPED Fiscal de forma atomica com protecao contra concorrencia e garantia de idempotencia.';


--
-- Name: fiscal_sped_substituir_snapshots_documentais(bigint, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_substituir_snapshots_documentais(p_versao_id bigint, p_documentos jsonb, p_cadastros jsonb, p_apuracoes jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_documento jsonb;
  v_item jsonb;
  v_cadastro jsonb;
  v_apuracao jsonb;
  v_documento_snapshot_id bigint;
BEGIN
  IF jsonb_typeof(p_documentos) <> 'array'
     OR jsonb_typeof(p_cadastros) <> 'array'
     OR jsonb_typeof(p_apuracoes) <> 'array' THEN
    RAISE EXCEPTION 'Snapshots documentais devem ser arrays JSON.' USING ERRCODE = '22023';
  END IF;

  SELECT status INTO v_status
    FROM public.fiscal_sped_versao
   WHERE id = p_versao_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Versao SPED inexistente.' USING ERRCODE = 'P0002';
  END IF;
  IF v_status <> 'RASCUNHO' THEN
    RAISE EXCEPTION 'Snapshots somente podem ser substituidos em versao RASCUNHO.'
      USING ERRCODE = '55000';
  END IF;

  DELETE FROM public.fiscal_sped_item_snapshot item
   USING public.fiscal_sped_documento_snapshot documento
   WHERE item.documento_snapshot_id = documento.id
     AND documento.versao_id = p_versao_id;
  DELETE FROM public.fiscal_sped_documento_snapshot WHERE versao_id = p_versao_id;
  DELETE FROM public.fiscal_sped_cadastro_snapshot
   WHERE versao_id = p_versao_id AND tipo <> 'CONFIG';
  DELETE FROM public.fiscal_sped_apuracao_snapshot WHERE versao_id = p_versao_id;

  FOR v_documento IN SELECT value FROM jsonb_array_elements(p_documentos)
  LOOP
    INSERT INTO public.fiscal_sped_documento_snapshot(
      versao_id, fonte_tipo, fonte_tabela, fonte_id, operacao, chave_acesso,
      modelo, codigo_situacao, data_emissao_civil, data_emissao_original,
      data_emissao_offset, data_emissao_instante_utc, data_escrituracao_civil,
      participante_codigo, participante_documento_tipo,
      participante_documento_canonico, participante_documento_original,
      xml_sha256, payload, source_refs
    ) VALUES (
      p_versao_id,
      v_documento->>'fonte_tipo',
      v_documento->>'fonte_tabela',
      v_documento->>'fonte_id',
      v_documento->>'operacao',
      v_documento->>'chave_acesso',
      v_documento->>'modelo',
      v_documento->>'codigo_situacao',
      (v_documento->>'data_emissao_civil')::date,
      nullif(v_documento->>'data_emissao_original', ''),
      nullif(v_documento->>'data_emissao_offset', ''),
      nullif(v_documento->>'data_emissao_instante_utc', '')::timestamptz,
      nullif(v_documento->>'data_escrituracao_civil', '')::date,
      nullif(v_documento->>'participante_codigo', ''),
      coalesce(nullif(v_documento->>'participante_documento_tipo', ''), 'SEM_DOCUMENTO'),
      nullif(v_documento->>'participante_documento_canonico', ''),
      nullif(v_documento->>'participante_documento_original', ''),
      v_documento->>'xml_sha256',
      coalesce(v_documento->'payload', '{}'::jsonb),
      coalesce(v_documento->'source_refs', '[]'::jsonb)
    ) RETURNING id INTO v_documento_snapshot_id;

    FOR v_item IN SELECT value FROM jsonb_array_elements(coalesce(v_documento->'itens', '[]'::jsonb))
    LOOP
      INSERT INTO public.fiscal_sped_item_snapshot(
        documento_snapshot_id, numero_item, produto_id, item_config_id,
        codigo_item, unidade_documento, unidade_inventario,
        tratamento_credito, payload, source_refs
      ) VALUES (
        v_documento_snapshot_id,
        (v_item->>'numero_item')::integer,
        nullif(v_item->>'produto_id', '')::integer,
        nullif(v_item->>'item_config_id', '')::bigint,
        v_item->>'codigo_item',
        v_item->>'unidade_documento',
        nullif(v_item->>'unidade_inventario', ''),
        v_item->>'tratamento_credito',
        coalesce(v_item->'payload', '{}'::jsonb),
        coalesce(v_item->'source_refs', '[]'::jsonb)
      );
    END LOOP;
  END LOOP;

  FOR v_cadastro IN SELECT value FROM jsonb_array_elements(p_cadastros)
  LOOP
    INSERT INTO public.fiscal_sped_cadastro_snapshot(
      versao_id, tipo, codigo, documento_tipo, documento_canonico,
      documento_original, payload, source_refs, payload_sha256
    ) VALUES (
      p_versao_id,
      v_cadastro->>'tipo',
      v_cadastro->>'codigo',
      coalesce(nullif(v_cadastro->>'documento_tipo', ''), 'SEM_DOCUMENTO'),
      nullif(v_cadastro->>'documento_canonico', ''),
      nullif(v_cadastro->>'documento_original', ''),
      coalesce(v_cadastro->'payload', '{}'::jsonb),
      coalesce(v_cadastro->'source_refs', '[]'::jsonb),
      v_cadastro->>'payload_sha256'
    );
  END LOOP;

  FOR v_apuracao IN SELECT value FROM jsonb_array_elements(p_apuracoes)
  LOOP
    INSERT INTO public.fiscal_sped_apuracao_snapshot(
      versao_id, tipo, uf, periodo_inicio, periodo_fim, payload, payload_sha256
    ) VALUES (
      p_versao_id,
      v_apuracao->>'tipo',
      nullif(v_apuracao->>'uf', ''),
      (v_apuracao->>'periodo_inicio')::date,
      (v_apuracao->>'periodo_fim')::date,
      coalesce(v_apuracao->'payload', '{}'::jsonb),
      v_apuracao->>'payload_sha256'
    );
  END LOOP;
END;
$$;


--
-- Name: fiscal_sped_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_sped_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: fiscal_try_lock_dfe(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fiscal_try_lock_dfe(p_empresa_id integer, p_lock_until timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id bigint;
BEGIN
  INSERT INTO public.fiscal_dfe_controle (
    empresa_id,
    sync_lock_until,
    sync_started_at,
    updatedat
  )
  VALUES (
    p_empresa_id,
    p_lock_until,
    now(),
    now()
  )
  ON CONFLICT (empresa_id)
  DO UPDATE SET
    sync_lock_until = EXCLUDED.sync_lock_until,
    sync_started_at = now(),
    updatedat = now()
  WHERE public.fiscal_dfe_controle.sync_lock_until IS NULL
     OR public.fiscal_dfe_controle.sync_lock_until < now()
  RETURNING id INTO v_id;

  RETURN v_id IS NOT NULL;
END;
$$;


--
-- Name: fn_agendar_resumo_financeiro_telegram(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_agendar_resumo_financeiro_telegram() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  SELECT financeiro_endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF v_endpoint_url IS NULL OR v_bearer_token IS NULL THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := v_endpoint_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_bearer_token
    ),
    body := jsonb_build_object('origem', 'PG_CRON'),
    timeout_milliseconds := 5000
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Falha ao agendar resumo financeiro Telegram: %', SQLERRM;
END;
$$;


--
-- Name: fn_aplicar_preco_mercadolivre_no_erp(bigint, numeric, text, bigint, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_aplicar_preco_mercadolivre_no_erp(p_product_link_id bigint, p_price numeric, p_source text DEFAULT 'WEBHOOK'::text, p_notification_id bigint DEFAULT NULL::bigint, p_ml_price_before numeric DEFAULT NULL::numeric) RETURNS TABLE(changed boolean, log_id bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link public.mercadolivre_product_link%ROWTYPE;
  v_old_price numeric;
  v_changed boolean;
  v_log_id bigint;
BEGIN
  IF p_price IS NULL OR p_price <= 0 THEN
    RAISE EXCEPTION 'Preço inválido recebido do Mercado Livre.';
  END IF;

  SELECT *
    INTO v_link
    FROM public.mercadolivre_product_link
   WHERE id = p_product_link_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo Mercado Livre % não encontrado.', p_product_link_id;
  END IF;

  SELECT precovenda
    INTO v_old_price
    FROM public.produto
   WHERE id = v_link.produto_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto % não encontrado.', v_link.produto_id;
  END IF;

  v_changed := v_old_price IS DISTINCT FROM p_price;

  IF v_changed THEN
    UPDATE public.produto
       SET precovenda = p_price,
           updatedat = now()
     WHERE id = v_link.produto_id;
  END IF;

  -- O UPDATE do produto pode acionar o trigger ERP -> ML. Como esta alteração
  -- veio do próprio Mercado Livre, neutralizamos a fila dentro da transação.
  UPDATE public.mercadolivre_stock_sync_queue
     SET status = 'PROCESSADA',
         locked_at = NULL,
         next_retry_at = NULL,
         last_error = NULL,
         processed_at = now(),
         updated_at = now()
   WHERE product_link_id = v_link.id;

  INSERT INTO public.mercadolivre_price_sync_log (
    empresa_id,
    product_link_id,
    produto_id,
    notification_id,
    ml_item_id,
    direction,
    source,
    status,
    erp_price_before,
    erp_price_after,
    ml_price_before,
    ml_price_after,
    message,
    completed_at
  )
  VALUES (
    v_link.empresa_id,
    v_link.id,
    v_link.produto_id,
    p_notification_id,
    v_link.ml_item_id,
    'ML_PARA_ERP',
    COALESCE(NULLIF(btrim(p_source), ''), 'WEBHOOK'),
    CASE WHEN v_changed THEN 'SUCESSO' ELSE 'SEM_ALTERACAO' END,
    v_old_price,
    p_price,
    p_ml_price_before,
    p_price,
    CASE
      WHEN v_changed THEN 'Preço do ERP atualizado a partir do Mercado Livre.'
      ELSE 'ERP e Mercado Livre já possuíam o mesmo preço.'
    END,
    now()
  )
  RETURNING id INTO v_log_id;

  RETURN QUERY SELECT v_changed, v_log_id;
END;
$$;


--
-- Name: fn_aprovar_orcamento_venda(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_aprovar_orcamento_venda(p_venda_id integer, p_forma_pagamento text DEFAULT NULL::text) RETURNS void
