--
-- Name: fn_baixa_estoque_produto(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_baixa_estoque_produto(p_produto_id integer, p_quantidade integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_estoque integer;
begin
  -- quantidade inválida: não faz nada
  if p_quantidade is null or p_quantidade <= 0 then
    return;
  end if;

  -- trava a linha para evitar corrida de concorrência
  select estoque
    into v_estoque
  from produto
  where id = p_produto_id
  for update;

  if v_estoque is null then
    raise exception 'Produto % não encontrado para baixa de estoque.', p_produto_id
      using errcode = 'P0001';
  end if;

  if v_estoque < p_quantidade then
    raise exception 'Estoque insuficiente para produto %, em estoque: %, necessário: %',
      p_produto_id, v_estoque, p_quantidade
      using errcode = 'P0001';
  end if;

  update produto
    set estoque = estoque - p_quantidade,
        updatedat = now()
  where id = p_produto_id;
end;
$$;


--
-- Name: fn_baixar_estoque_venda(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_baixar_estoque_venda(p_venda_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto('VENDA', p_venda_id::bigint, 'Venda #' || p_venda_id);
  RETURN public.fn_baixar_estoque_venda_interna(p_venda_id);
END;
$$;


--
-- Name: fn_baixar_estoque_venda_interna(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_baixar_estoque_venda_interna(p_venda_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
  q_baixada int;
  delta int;
begin
  -- trava a venda para evitar concorrência
  perform 1 from public.venda where id = p_venda_id for update;

  for r in
    select vp.produtoid, vp.quantidade
      from public.vendaproduto vp
     where vp.venda_id = p_venda_id
  loop
    select b.quantidade into q_baixada
      from public.vendaproduto_baixa b
     where b.venda_id = p_venda_id
       and b.produtoid = r.produtoid;

    if q_baixada is null then
      delta := r.quantidade;
    else
      delta := r.quantidade - q_baixada;
    end if;

    if delta > 0 then
      update public.produto
         set estoque = estoque - delta,
             updatedat = now()
       where id = r.produtoid
         and estoque >= delta;

      if not found then
        raise exception 'Estoque insuficiente para o produto % (necessário: %, venda %)',
          r.produtoid, delta, p_venda_id
          using errcode = 'P0001';
      end if;

    elsif delta < 0 then
      update public.produto
         set estoque = estoque + (-delta),
             updatedat = now()
       where id = r.produtoid;
    end if;

    insert into public.vendaproduto_baixa (venda_id, produtoid, quantidade, updated_at)
    values (p_venda_id, r.produtoid, r.quantidade, now())
    on conflict (venda_id, produtoid) do update
      set quantidade = excluded.quantidade,
          updated_at = now();
  end loop;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: fn_concluir_sincronizacao_site(bigint, bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_concluir_sincronizacao_site(p_queue_id bigint, p_desired_version bigint, p_success boolean, p_error text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_queue public.site_catalog_sync_queue%rowtype;
  v_changed boolean;
  v_delay_minutes integer;
begin
  select * into v_queue
    from public.site_catalog_sync_queue
   where id = p_queue_id
   for update;

  if not found then
    return 'NAO_ENCONTRADA';
  end if;

  v_changed := v_queue.desired_version <> p_desired_version;

  if p_success and not v_changed then
    update public.site_catalog_sync_queue
       set status = 'PROCESSADA',
           locked_at = null,
           next_retry_at = null,
           last_error = null,
           processed_at = now(),
           updated_at = now()
     where id = p_queue_id;

    update public.site_product_link
       set sync_status = 'SINCRONIZADO',
           last_synced_at = now(),
           last_sync_error = null,
           updated_at = now()
     where id = v_queue.product_link_id
       and sync_version = p_desired_version;

    return 'PROCESSADA';
  end if;

  if p_success and v_changed then
    update public.site_catalog_sync_queue
       set status = 'PENDENTE',
           locked_at = null,
           next_retry_at = null,
           last_error = null,
           processed_at = null,
           updated_at = now()
     where id = p_queue_id;
    return 'REATIVADA';
  end if;

  if not p_success and v_changed then
    update public.site_catalog_sync_queue
       set status = 'PENDENTE',
           locked_at = null,
           next_retry_at = null,
           last_error = null,
           processed_at = null,
           updated_at = now()
     where id = p_queue_id;
    return 'REATIVADA';
  end if;

  v_delay_minutes := least(5 * power(2, greatest(v_queue.attempts - 1, 0))::integer, 360);

  update public.site_catalog_sync_queue
     set status = 'ERRO',
         locked_at = null,
         next_retry_at = now() + make_interval(mins => v_delay_minutes),
         last_error = left(coalesce(p_error, 'Falha ao sincronizar com a loja.'), 2000),
         processed_at = null,
         updated_at = now()
   where id = p_queue_id;

  update public.site_product_link
     set sync_status = 'ERRO',
         last_sync_error = left(coalesce(p_error, 'Falha ao sincronizar com a loja.'), 2000),
         updated_at = now()
   where id = v_queue.product_link_id;

  return 'ERRO';
end;
$$;


--
-- Name: fn_criar_pedido_site(integer, jsonb, jsonb, numeric, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_criar_pedido_site(p_cliente_id integer, p_endereco_snapshot jsonb, p_itens jsonb, p_subtotal numeric, p_total numeric, p_canal text DEFAULT 'ONLINE'::text, p_forma_pagamento text DEFAULT 'Pagar.me'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_venda_id integer;
    v_item jsonb;
    v_produtoid integer;
    v_quantidade integer;
    v_sub_total numeric;
    v_valor_total numeric;
    v_canal public.enum_canal_venda;
    v_now timestamptz := now();
BEGIN
    IF p_cliente_id IS NULL OR p_cliente_id <= 0 THEN
        RAISE EXCEPTION 'Cliente inválido para criação de pedido.';
    END IF;

    IF p_itens IS NULL OR jsonb_array_length(p_itens) = 0 THEN
        RAISE EXCEPTION 'Pedido deve conter pelo menos um item.';
    END IF;

    -- Converte canal com fallback seguro para ONLINE
    BEGIN
        v_canal := COALESCE(p_canal, 'ONLINE')::public.enum_canal_venda;
    EXCEPTION WHEN OTHERS THEN
        v_canal := 'ONLINE'::public.enum_canal_venda;
    END;

    -- 1. Cria a venda com status PENDENTE (transação única)
    INSERT INTO public.venda (
        clienteid,
        status,
        valortotal,
        sub_total,
        datavenda,
        createdat,
        updatedat,
        forma_pagamento,
        endereco_entrega_snapshot,
        canal
    ) VALUES (
        p_cliente_id,
        'PENDENTE'::public.enum_status_venda,
        p_total,
        p_subtotal,
        v_now,
        v_now,
        v_now,
        p_forma_pagamento,
        p_endereco_snapshot,
        v_canal
    )
    RETURNING id INTO v_venda_id;

    -- 2. Insere todos os itens. Se qualquer item falhar, rollback total automático do plpgsql
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
    LOOP
        v_produtoid := (v_item->>'produtoid')::integer;
        v_quantidade := (v_item->>'quantidade')::integer;
        v_sub_total := (v_item->>'sub_total')::numeric;
        v_valor_total := (v_item->>'valor_total')::numeric;

        IF v_produtoid IS NULL OR v_quantidade IS NULL OR v_quantidade <= 0 THEN
            RAISE EXCEPTION 'Item com produto ou quantidade inválida no pedido: produto % quantidade %', v_produtoid, v_quantidade;
        END IF;

        INSERT INTO public.vendaproduto (
            venda_id,
            produtoid,
            quantidade,
            sub_total,
            valor_total,
            valor_frete,
            created_at,
            updated_at
        ) VALUES (
            v_venda_id,
            v_produtoid,
            v_quantidade,
            v_sub_total,
            v_valor_total,
            0,
            v_now,
            v_now
        );
    END LOOP;

    RETURN v_venda_id;
END;
$$;


--
-- Name: fn_criar_venda_com_itens(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_criar_venda_com_itens(p_venda jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cliente_id integer := (p_venda->>'clienteId')::integer;
  v_created_by uuid := (p_venda->>'created_by')::uuid;
  v_status public.enum_status_venda := (p_venda->>'status')::public.enum_status_venda;
  v_baixar_estoque boolean := coalesce((p_venda->>'baixarEstoque')::boolean, true);
  v_valor_frete numeric(14,2) := round(coalesce(nullif(p_venda->>'valorFrete', '')::numeric, 0), 2);
  v_venda_id integer;
  v_item jsonb;
  v_produto_id integer;
  v_quantidade integer;
  v_item_sub_total numeric(14,2);
  v_item_valor_total numeric(14,2);
  v_item_valor_desconto numeric(14,2);
  v_item_tipo_desconto public.enum_tipo_desconto_venda;
  v_item_desconto_aplicado numeric(14,2);
  v_item_valor_frete numeric(14,2);
  v_comissao numeric;
BEGIN
  IF v_cliente_id IS NULL OR v_created_by IS NULL OR v_status IS NULL
     OR p_venda->>'subTotal' IS NULL OR p_venda->>'valorTotal' IS NULL THEN
    RAISE EXCEPTION 'Campos obrigatórios ausentes em p_venda.' USING ERRCODE = 'P0001';
  END IF;
  IF v_valor_frete < 0 THEN
    RAISE EXCEPTION 'O valor do frete não pode ser negativo.' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_venda->'itens') <> 'array' OR jsonb_array_length(p_venda->'itens') = 0 THEN
    RAISE EXCEPTION 'p_venda.itens deve possuir ao menos um item.' USING ERRCODE = 'P0001';
  END IF;

  SELECT coalesce(comissao_venda_percent, 0)
    INTO v_comissao
    FROM public.usuario
   WHERE id = v_created_by;

  INSERT INTO public.venda (
    clienteid, created_by, vendedor, status, statusaprovacao,
    forma_pagamento, pagamentos_previstos, parcelas_pagamento,
    descricao, observacoes, descricao_financeiro, observacoes_fiscais, garantia,
    sub_total, valortotal, desconto_tipo, desconto_valor, valor_frete, datavenda,
    comissao_venda_percent_aplicada, categoriavendaid
  ) VALUES (
    v_cliente_id,
    v_created_by,
    coalesce(nullif(p_venda->>'vendedor', '')::uuid, v_created_by),
    v_status,
    NULL,
    nullif(p_venda->>'formaPagamento', ''),
    nullif(p_venda->'pagamentosPrevistos', 'null'::jsonb),
    nullif(p_venda->>'parcelasPagamento', '')::integer,
    nullif(btrim(p_venda->>'descricao'), ''),
    nullif(btrim(p_venda->>'observacoes'), ''),
    nullif(btrim(p_venda->>'descricaoFinanceiro'), ''),
    nullif(btrim(p_venda->>'observacoesFiscais'), ''),
    nullif(btrim(p_venda->>'garantia'), ''),
    (p_venda->>'subTotal')::numeric,
    (p_venda->>'valorTotal')::numeric,
    nullif(p_venda->>'descontoTipo', '')::public.enum_tipo_desconto_venda,
    nullif(p_venda->>'descontoValor', '')::numeric,
    v_valor_frete,
    coalesce(nullif(p_venda->>'dataVenda', '')::timestamp, now()),
    v_comissao,
    nullif(p_venda->>'categoriaVendaId', '')::integer
  ) RETURNING id INTO v_venda_id;

  IF v_baixar_estoque THEN
    PERFORM public.estoque_definir_contexto(
      'VENDA', v_venda_id::bigint, 'Venda #' || v_venda_id, v_created_by
    );
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_venda->'itens') LOOP
    v_produto_id := (v_item->>'produtoId')::integer;
    v_quantidade := (v_item->>'quantidade')::integer;
    v_item_sub_total := round((v_item->>'subTotal')::numeric, 2);
    v_item_valor_total := round((v_item->>'valorTotal')::numeric, 2);
    v_item_valor_desconto := round(coalesce(nullif(v_item->>'valorDesconto', '')::numeric, 0), 2);
    v_item_tipo_desconto := nullif(v_item->>'tipoDesconto', '')::public.enum_tipo_desconto_venda;
    v_item_valor_frete := round(coalesce(nullif(v_item->>'valorFrete', '')::numeric, 0), 2);
    v_item_desconto_aplicado := CASE
      WHEN v_item_tipo_desconto::text = 'PORCENTAGEM'
        THEN round(v_item_sub_total * least(v_item_valor_desconto, 100) / 100, 2)
      WHEN v_item_tipo_desconto::text = 'FIXO'
        THEN least(v_item_sub_total, v_item_valor_desconto)
      ELSE 0
    END;

    IF v_produto_id IS NULL OR v_quantidade IS NULL OR v_quantidade <= 0
       OR v_item_sub_total < 0 OR v_item_valor_total < 0
       OR v_item_valor_desconto < 0 OR v_item_valor_frete < 0
       OR (v_item_tipo_desconto::text = 'PORCENTAGEM' AND v_item_valor_desconto > 100)
       OR v_item_valor_total <> round(v_item_sub_total - v_item_desconto_aplicado + v_item_valor_frete, 2) THEN
      RAISE EXCEPTION 'Dados inválidos em um dos itens da venda.' USING ERRCODE = 'P0001';
    END IF;

    IF v_baixar_estoque THEN
      PERFORM public.fn_baixa_estoque_produto(v_produto_id, v_quantidade);
    END IF;

    INSERT INTO public.vendaproduto (
      venda_id, produtoid, quantidade, sub_total, valor_total,
      valor_desconto, tipo_desconto, valor_frete
    ) VALUES (
      v_venda_id, v_produto_id, v_quantidade, v_item_sub_total, v_item_valor_total,
      v_item_valor_desconto, v_item_tipo_desconto, v_item_valor_frete
    );

    IF v_baixar_estoque THEN
      INSERT INTO public.vendaproduto_baixa (venda_id, produtoid, quantidade, updated_at)
      VALUES (v_venda_id, v_produto_id, v_quantidade, now())
      ON CONFLICT (venda_id, produtoid) DO UPDATE
        SET quantidade = excluded.quantidade, updated_at = now();
    END IF;
  END LOOP;

  RETURN v_venda_id;
END;
$$;


--
-- Name: fn_criar_venda_marketplace_com_itens(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_criar_venda_marketplace_com_itens(p_venda jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_cliente_id integer := COALESCE((p_venda->>'clienteId')::integer, (p_venda->>'clienteid')::integer);
  v_status public.enum_status_venda := COALESCE(NULLIF(p_venda->>'status', '')::public.enum_status_venda, 'ABERTA'::public.enum_status_venda);
  v_canal public.enum_canal_venda := COALESCE(NULLIF(p_venda->>'canal', '')::public.enum_canal_venda, 'MERCADO_LIVRE'::public.enum_canal_venda);
  v_status_entrega public.enum_status_entrega := NULLIF(p_venda->>'statusEntrega', '')::public.enum_status_entrega;
  v_desconto_tipo public.enum_tipo_desconto_venda := NULLIF(COALESCE(p_venda->>'descontoTipo', p_venda->>'desconto_tipo'), '')::public.enum_tipo_desconto_venda;
  v_desconto_valor numeric := NULLIF(COALESCE(p_venda->>'descontoValor', p_venda->>'desconto_valor'), '')::numeric;
  v_sub_total numeric := COALESCE(NULLIF(COALESCE(p_venda->>'subTotal', p_venda->>'sub_total'), '')::numeric, 0);
  v_valor_total numeric := COALESCE(NULLIF(COALESCE(p_venda->>'valorTotal', p_venda->>'valortotal'), '')::numeric, 0);
  v_data_venda timestamptz := COALESCE(NULLIF(p_venda->>'dataVenda', '')::timestamptz, now());
  v_forma_pagamento text := NULLIF(COALESCE(p_venda->>'formaPagamento', p_venda->>'forma_pagamento'), '');
  v_observacoes text := NULLIF(p_venda->>'observacoes', '');
  v_itens jsonb := p_venda->'itens';
  v_item jsonb;
  v_produto_id integer;
  v_quantidade integer;
  v_sub_total_item numeric;
  v_valor_total_item numeric;
  v_baixar_estoque boolean;
  v_venda_id integer;
BEGIN
  IF v_cliente_id IS NULL OR v_sub_total <= 0 OR v_valor_total <= 0 THEN
    RAISE EXCEPTION 'Campos obrigatórios ausentes em p_venda (clienteId, subTotal, valorTotal).';
  END IF;

  IF v_itens IS NULL OR jsonb_typeof(v_itens) <> 'array' OR jsonb_array_length(v_itens) = 0 THEN
    RAISE EXCEPTION 'p_venda.itens deve ser um array não vazio.';
  END IF;

  INSERT INTO public.venda (
    clienteid,
    status,
    canal,
    status_entrega,
    valortotal,
    sub_total,
    desconto_tipo,
    desconto_valor,
    forma_pagamento,
    datavenda,
    createdat,
    updatedat,
    observacoes
  )
  VALUES (
    v_cliente_id,
    v_status,
    v_canal,
    v_status_entrega,
    v_valor_total,
    v_sub_total,
    v_desconto_tipo,
    v_desconto_valor,
    v_forma_pagamento,
    v_data_venda,
    now(),
    now(),
    v_observacoes
  )
  RETURNING id INTO v_venda_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_itens)
  LOOP
    v_produto_id := COALESCE((v_item->>'produtoId')::integer, (v_item->>'produtoid')::integer);
    v_quantidade := COALESCE((v_item->>'quantidade')::integer, 1);
    v_sub_total_item := COALESCE(NULLIF(COALESCE(v_item->>'subTotal', v_item->>'sub_total'), '')::numeric, 0);
    v_valor_total_item := COALESCE(NULLIF(COALESCE(v_item->>'valorTotal', v_item->>'valor_total'), '')::numeric, v_sub_total_item);
    v_baixar_estoque := COALESCE((v_item->>'baixarEstoque')::boolean, true);

    IF v_produto_id IS NULL OR v_quantidade <= 0 THEN
      RAISE EXCEPTION 'Cada item deve possuir produtoId e quantidade > 0.';
    END IF;

    IF v_baixar_estoque THEN
      PERFORM public.fn_baixa_estoque_produto(v_produto_id, v_quantidade);

      INSERT INTO public.vendaproduto_baixa (venda_id, produtoid, quantidade, created_at, updated_at)
      VALUES (v_venda_id, v_produto_id, v_quantidade, now(), now())
      ON CONFLICT (venda_id, produtoid) DO UPDATE
      SET quantidade = EXCLUDED.quantidade,
          updated_at = now();
    END IF;

    INSERT INTO public.vendaproduto (
      venda_id,
      produtoid,
      quantidade,
      sub_total,
      valor_total,
      valor_desconto,
      tipo_desconto
    )
    VALUES (
      v_venda_id,
      v_produto_id,
      v_quantidade,
      v_sub_total_item,
      v_valor_total_item,
      NULL,
      NULL
    );
  END LOOP;

  RETURN v_venda_id;
END;
$$;


--
-- Name: fn_criar_venda_mercadolivre_reservada(bigint, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_criar_venda_mercadolivre_reservada(p_ml_order_id bigint, p_empresa_id integer, p_venda jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda_id integer;
  v_import_status text;
BEGIN
  SELECT venda_id, import_status
    INTO v_venda_id, v_import_status
    FROM public.mercadolivre_order
   WHERE ml_order_id = p_ml_order_id
     AND empresa_id = p_empresa_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pedido Mercado Livre % não encontrado.', p_ml_order_id;
  END IF;

  IF v_venda_id IS NOT NULL THEN
    RETURN v_venda_id;
  END IF;

  IF v_import_status <> 'PROCESSANDO' THEN
    RAISE EXCEPTION 'Pedido Mercado Livre % não está reservado para importação.', p_ml_order_id;
  END IF;

  v_venda_id := public.fn_criar_venda_marketplace_com_itens(p_venda);

  UPDATE public.mercadolivre_order
     SET venda_id = v_venda_id,
         import_status = 'IMPORTADA',
         import_locked_at = NULL,
         import_error = NULL,
         updated_at = now()
   WHERE ml_order_id = p_ml_order_id
     AND empresa_id = p_empresa_id;

  RETURN v_venda_id;
END;
$$;


--
-- Name: fn_criar_venda_shopee_reservada(text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_criar_venda_shopee_reservada(p_order_sn text, p_empresa_id integer, p_venda jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_venda_id integer;
  v_import_status text;
begin
  select venda_id, import_status
    into v_venda_id, v_import_status
    from public.shopee_order
   where order_sn = p_order_sn and empresa_id = p_empresa_id
   for update;

  if not found then raise exception 'Pedido Shopee % não encontrado.', p_order_sn; end if;
  if v_venda_id is not null then return v_venda_id; end if;
  if v_import_status <> 'PROCESSANDO' then raise exception 'Pedido Shopee % não está reservado para importação.', p_order_sn; end if;

  v_venda_id := public.fn_criar_venda_marketplace_com_itens(p_venda);
  update public.shopee_order
     set venda_id = v_venda_id,
         import_status = 'IMPORTADA',
         import_locked_at = null,
         import_error = null,
         updated_at = now()
   where order_sn = p_order_sn and empresa_id = p_empresa_id;
  return v_venda_id;
end;
$$;


--
-- Name: fn_desconciliar_transacao_excluida(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_desconciliar_transacao_excluida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.ofx_movimento
     set status = 'PENDENTE',
         acao_conciliacao = null,
         transacao_id = null,
         titulo_origem_id = null,
         conciliado_em = null,
         conciliado_por = null
   where transacao_id = old.id
     and status = 'CONCILIADO';

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION fn_desconciliar_transacao_excluida(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_desconciliar_transacao_excluida() IS 'Devolve para PENDENTE os movimentos do extrato conciliados com a transação que está sendo excluída (física ou logicamente).';


--
-- Name: fn_disparar_processamento_notificacao_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_disparar_processamento_notificacao_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  SELECT endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_endpoint_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_bearer_token
      ),
      body := jsonb_build_object('evento_id', NEW.id),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- A OS e o evento permanecem salvos; o processador recorrente pode recuperar a fila.
    RAISE WARNING 'Falha ao agendar processamento Telegram para evento %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: fn_editar_venda_com_itens(integer, jsonb, numeric, numeric, text, numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_editar_venda_com_itens(p_venda_id integer, p_itens jsonb, p_sub_total numeric, p_valor_total numeric, p_desconto_tipo text DEFAULT NULL::text, p_desconto_valor numeric DEFAULT 0, p_valor_frete numeric DEFAULT 0, p_updated_by uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_tinha_baixa boolean;
  v_item jsonb;
  v_produto_id integer;
  v_quantidade integer;
  v_sub_total numeric(14,2);
  v_valor_total numeric(14,2);
  v_valor_desconto numeric(14,2);
  v_tipo_desconto public.enum_tipo_desconto_venda;
  v_desconto_aplicado numeric(14,2);
  v_valor_frete_item numeric(14,2);
  v_ids_solicitados integer;
  v_ids_encontrados integer;
  v_soma_itens numeric(14,2);
BEGIN
  SELECT status::text
    INTO v_status
    FROM public.venda
   WHERE id = p_venda_id
   FOR UPDATE;

  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_status IN ('PAGO', 'FINALIZADA', 'CANCELADA', 'CANCELADO') THEN
    RAISE EXCEPTION 'Os itens não podem ser alterados em uma venda paga, finalizada ou cancelada.'
      USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.nfe WHERE vendaid = p_venda_id) THEN
    RAISE EXCEPTION 'Exclua a NF-e em rascunho antes de alterar os itens da venda.'
      USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'A venda deve possuir ao menos um item.' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(DISTINCT (value->>'produtoId')::integer)
    INTO v_ids_solicitados
    FROM jsonb_array_elements(p_itens);
  SELECT count(*)
    INTO v_ids_encontrados
    FROM public.produto
   WHERE id IN (
     SELECT DISTINCT (value->>'produtoId')::integer FROM jsonb_array_elements(p_itens)
   );
  IF v_ids_solicitados <> v_ids_encontrados THEN
    RAISE EXCEPTION 'Um ou mais produtos não existem.' USING ERRCODE = 'P0001';
  END IF;

  PERFORM 1
    FROM public.produto
   WHERE id IN (
     SELECT DISTINCT (value->>'produtoId')::integer FROM jsonb_array_elements(p_itens)
   )
   ORDER BY id
   FOR UPDATE;

  SELECT round(coalesce(sum((value->>'subTotal')::numeric), 0), 2)
    INTO v_soma_itens
    FROM jsonb_array_elements(p_itens);
  IF v_soma_itens <> round(coalesce(p_sub_total, 0), 2) THEN
    RAISE EXCEPTION 'O subtotal da venda não corresponde à soma dos itens.' USING ERRCODE = 'P0001';
  END IF;
  IF coalesce(p_sub_total, 0) < 0 OR coalesce(p_valor_total, 0) < 0
     OR coalesce(p_desconto_valor, 0) < 0 OR coalesce(p_valor_frete, 0) < 0 THEN
    RAISE EXCEPTION 'Os valores financeiros da venda não podem ser negativos.' USING ERRCODE = 'P0001';
  END IF;

  v_tinha_baixa := EXISTS (
    SELECT 1 FROM public.vendaproduto_baixa WHERE venda_id = p_venda_id
  );
  IF v_tinha_baixa THEN
    PERFORM public.fn_estornar_estoque_venda(p_venda_id);
  END IF;

  DELETE FROM public.vendaproduto WHERE venda_id = p_venda_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    v_produto_id := (v_item->>'produtoId')::integer;
    v_quantidade := (v_item->>'quantidade')::integer;
    v_sub_total := round((v_item->>'subTotal')::numeric, 2);
    v_valor_total := round((v_item->>'valorTotal')::numeric, 2);
    v_valor_desconto := round(coalesce(nullif(v_item->>'valorDesconto', '')::numeric, 0), 2);
    v_tipo_desconto := nullif(v_item->>'tipoDesconto', '')::public.enum_tipo_desconto_venda;
    v_valor_frete_item := round(coalesce(nullif(v_item->>'valorFrete', '')::numeric, 0), 2);
    v_desconto_aplicado := CASE
      WHEN v_tipo_desconto::text = 'PORCENTAGEM'
        THEN round(v_sub_total * least(v_valor_desconto, 100) / 100, 2)
      WHEN v_tipo_desconto::text = 'FIXO'
        THEN least(v_sub_total, v_valor_desconto)
      ELSE 0
    END;

    IF v_produto_id IS NULL OR v_quantidade IS NULL OR v_quantidade <= 0
       OR v_sub_total < 0 OR v_valor_total < 0 OR v_valor_desconto < 0
       OR v_valor_frete_item < 0
       OR (v_tipo_desconto::text = 'PORCENTAGEM' AND v_valor_desconto > 100)
       OR v_valor_total <> round(v_sub_total - v_desconto_aplicado + v_valor_frete_item, 2) THEN
      RAISE EXCEPTION 'Dados inválidos em um dos itens da venda.' USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO public.vendaproduto (
      venda_id, produtoid, quantidade, sub_total, valor_total,
      valor_desconto, tipo_desconto, valor_frete
    ) VALUES (
      p_venda_id, v_produto_id, v_quantidade, v_sub_total, v_valor_total,
      v_valor_desconto, v_tipo_desconto, v_valor_frete_item
    );
  END LOOP;

  UPDATE public.venda
     SET sub_total = round(p_sub_total, 2),
         valortotal = round(p_valor_total, 2),
         desconto_tipo = nullif(p_desconto_tipo, '')::public.enum_tipo_desconto_venda,
         desconto_valor = round(coalesce(p_desconto_valor, 0), 2),
         valor_frete = round(coalesce(p_valor_frete, 0), 2),
         updated_by = coalesce(p_updated_by, updated_by),
         updatedat = now()
   WHERE id = p_venda_id;

  IF v_tinha_baixa THEN
    PERFORM public.fn_baixar_estoque_venda(p_venda_id);
  END IF;
END;
$$;


--
-- Name: fn_enfileirar_estoque_mercadolivre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_enfileirar_estoque_mercadolivre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.mercadolivre_stock_sync_queue (
    empresa_id,
    product_link_id,
    produto_id,
    desired_quantity,
    status,
    attempts,
    next_retry_at,
    locked_at,
    last_error,
    processed_at,
    updated_at
  )
  SELECT
    link.empresa_id,
    link.id,
    NEW.id,
    GREATEST(COALESCE(NEW.estoque, 0), 0),
    'PENDENTE',
    0,
    NULL,
    NULL,
    NULL,
    NULL,
    now()
  FROM public.mercadolivre_product_link link
  WHERE link.produto_id = NEW.id
  ON CONFLICT (product_link_id) DO UPDATE
    SET desired_quantity = EXCLUDED.desired_quantity,
        status = 'PENDENTE',
        attempts = 0,
        next_retry_at = NULL,
        locked_at = NULL,
        last_error = NULL,
        processed_at = NULL,
        updated_at = now();

  RETURN NEW;
END;
$$;


--
-- Name: fn_enfileirar_notificacao_estoque(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_enfileirar_notificacao_estoque() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento_tipo text;
  v_quantidade_entregas integer := 0;
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  v_evento_tipo := public.fn_tipo_evento_notificacao_estoque(
    NEW.origem,
    NEW.acao,
    NEW.sentido
  );

  IF v_evento_tipo IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.telegram_estoque_entrega (
    movimento_id,
    usuario_id,
    chat_id,
    evento_tipo
  )
  SELECT
    NEW.id,
    preferencia.usuario_id,
    preferencia.chat_id,
    v_evento_tipo
  FROM public.telegram_usuario_preferencia preferencia
  JOIN public.usuario usuario
    ON usuario.id = preferencia.usuario_id
   AND usuario.ativo = true
  WHERE preferencia.ativo = true
    AND preferencia.chat_id IS NOT NULL
    AND v_evento_tipo = ANY(preferencia.estoque_eventos_selecionados)
    AND EXISTS (
      SELECT 1
      FROM public.perfilpermissao perfil_permissao
      JOIN public.permissao permissao
        ON permissao.id = perfil_permissao.permissaoid
      WHERE perfil_permissao.perfilid = usuario.perfilid
        AND upper(btrim(permissao.nome)) = 'ESTOQUE:VISUALIZAR'
    )
  ON CONFLICT (movimento_id, usuario_id) DO NOTHING;

  GET DIAGNOSTICS v_quantidade_entregas = ROW_COUNT;
  IF v_quantidade_entregas = 0 THEN
    RETURN NEW;
  END IF;

  SELECT endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF v_endpoint_url IS NULL OR v_bearer_token IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_endpoint_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_bearer_token
      ),
      body := jsonb_build_object(
        'origem', 'ESTOQUE',
        'movimento_id', NEW.id
      ),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- A entrega continua pendente e pode ser recuperada pelo cron ou pelo botao
    -- de processamento manual.
    RAISE WARNING 'Falha ao agendar notificacao Telegram do movimento de estoque %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: fn_enfileirar_notificacao_fiscal(text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_enfileirar_notificacao_fiscal(p_documento_tipo text, p_documento_id bigint, p_evento_tipo text, p_dedupe_chave text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quantidade_entregas integer := 0;
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  INSERT INTO public.telegram_fiscal_entrega (
    documento_tipo,
    documento_id,
    evento_tipo,
    dedupe_chave,
    usuario_id,
    chat_id
  )
  SELECT
    p_documento_tipo,
    p_documento_id,
    p_evento_tipo,
    p_dedupe_chave,
    preferencia.usuario_id,
    preferencia.chat_id
  FROM public.telegram_usuario_preferencia preferencia
  JOIN public.usuario usuario
    ON usuario.id = preferencia.usuario_id
   AND usuario.ativo = true
  WHERE preferencia.ativo = true
    AND preferencia.chat_id IS NOT NULL
    AND p_evento_tipo = ANY(preferencia.fiscal_eventos_selecionados)
    AND EXISTS (
      SELECT 1
      FROM public.perfilpermissao perfil_permissao
      JOIN public.permissao permissao
        ON permissao.id = perfil_permissao.permissaoid
      WHERE perfil_permissao.perfilid = usuario.perfilid
        AND upper(btrim(permissao.nome)) = 'FINANCEIRO:NOTAS_FISCAIS'
    )
  ON CONFLICT (usuario_id, evento_tipo, dedupe_chave) DO NOTHING;

  GET DIAGNOSTICS v_quantidade_entregas = ROW_COUNT;
  IF v_quantidade_entregas = 0 THEN
    RETURN;
  END IF;

  SELECT endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF v_endpoint_url IS NULL OR v_bearer_token IS NULL THEN
    RETURN;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_endpoint_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_bearer_token
      ),
      body := jsonb_build_object(
        'origem', 'FISCAL',
        'documento_tipo', p_documento_tipo,
        'documento_id', p_documento_id
      ),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- A entrega continua pendente e e recuperada pelo cron ou pelo botao de
    -- processamento manual. Emissao fiscal nunca falha por causa do aviso.
    RAISE WARNING 'Falha ao agendar notificacao Telegram do documento fiscal % %: %',
      p_documento_tipo, p_documento_id, SQLERRM;
  END;
END;
$$;


--
-- Name: fn_enfileirar_novo_vinculo_mercadolivre(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_enfileirar_novo_vinculo_mercadolivre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estoque integer;
BEGIN
  SELECT GREATEST(COALESCE(estoque, 0), 0)
    INTO v_estoque
    FROM public.produto
   WHERE id = NEW.produto_id;

  INSERT INTO public.mercadolivre_stock_sync_queue (
    empresa_id,
    product_link_id,
    produto_id,
    desired_quantity,
    status,
    updated_at
  )
  VALUES (
    NEW.empresa_id,
    NEW.id,
    NEW.produto_id,
    COALESCE(v_estoque, 0),
    'PENDENTE',
    now()
  )
  ON CONFLICT (product_link_id) DO UPDATE
    SET desired_quantity = EXCLUDED.desired_quantity,
        status = 'PENDENTE',
        attempts = 0,
        next_retry_at = NULL,
        locked_at = NULL,
        last_error = NULL,
        processed_at = NULL,
        updated_at = now();

  RETURN NEW;
END;
$$;


--
-- Name: fn_enfileirar_site_product_link(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_enfileirar_site_product_link(p_product_link_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_link public.site_product_link%rowtype;
begin
  update public.site_product_link
     set sync_version = sync_version + 1,
         sync_status = 'PENDENTE',
         last_sync_error = null,
         updated_at = now()
   where id = p_product_link_id
   returning * into v_link;

  if not found then
    return;
  end if;

  insert into public.site_catalog_sync_queue (
    empresa_id,
    product_link_id,
    produto_id,
    event_id,
    desired_version,
    status,
    attempts,
    locked_at,
    next_retry_at,
    last_error,
    processed_at,
    updated_at
  ) values (
    v_link.empresa_id,
    v_link.id,
    v_link.produto_id,
    gen_random_uuid(),
    v_link.sync_version,
    'PENDENTE',
    0,
    null,
    null,
    null,
    null,
    now()
  )
  on conflict (product_link_id) do update
     set event_id = excluded.event_id,
         desired_version = excluded.desired_version,
         status = case
           when site_catalog_sync_queue.status = 'PROCESSANDO'
             then 'PROCESSANDO'
           else 'PENDENTE'
         end,
         attempts = case
           when site_catalog_sync_queue.status = 'PROCESSANDO'
             then site_catalog_sync_queue.attempts
           else 0
         end,
         locked_at = case
           when site_catalog_sync_queue.status = 'PROCESSANDO'
             then site_catalog_sync_queue.locked_at
           else null
         end,
         next_retry_at = null,
         last_error = null,
         processed_at = null,
         updated_at = now();
end;
$$;


--
-- Name: fn_estornar_estoque_venda(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_estornar_estoque_venda(p_venda_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto('VENDA', p_venda_id::bigint, 'Venda #' || p_venda_id || ' - estorno');
  RETURN public.fn_estornar_estoque_venda_interna(p_venda_id);
END;
$$;


--
-- Name: fn_estornar_estoque_venda_interna(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_estornar_estoque_venda_interna(p_venda_id integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
begin
  perform 1 from public.venda where id = p_venda_id for update;

  for r in
    select produtoid, quantidade
      from public.vendaproduto_baixa
     where venda_id = p_venda_id
  loop
    update public.produto
       set estoque = estoque + r.quantidade,
           updatedat = now()
     where id = r.produtoid;
  end loop;

  delete from public.vendaproduto_baixa
   where venda_id = p_venda_id;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: fn_fill_titulo_marketplace(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_fill_titulo_marketplace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin
  if new."tituloMarketplace" is null
     or btrim(new."tituloMarketplace") = '' then
    new."tituloMarketplace" := new.titulo;
  end if;

  return new;
end;$$;


--
-- Name: fn_importar_pedido_site(integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_importar_pedido_site(p_empresa_id integer, p_pedido jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_site_order_id bigint := (p_pedido->>'id')::bigint;
  v_site_customer_id bigint := nullif(p_pedido->'customer'->>'id', '')::bigint;
  v_status text := upper(coalesce(p_pedido->>'status', ''));
  v_documento text := regexp_replace(coalesce(p_pedido->'customer'->>'document', ''), '\D', '', 'g');
  v_nome text := nullif(btrim(p_pedido->'customer'->>'name'), '');
  v_email text := nullif(lower(btrim(p_pedido->'customer'->>'email')), '');
  v_telefone text := nullif(regexp_replace(coalesce(p_pedido->'customer'->>'phone', ''), '\D', '', 'g'), '');
  v_endereco jsonb := coalesce(p_pedido->'shippingAddress', '{}'::jsonb);
  v_cliente_id integer;
  v_venda_id integer;
  v_itens jsonb := coalesce(p_pedido->'items', '[]'::jsonb);
begin
  if v_site_order_id is null or v_site_order_id <= 0 then
    raise exception 'Pedido do site sem identificador valido.';
  end if;
  if v_status <> 'PAGO' then
    raise exception 'Somente pedidos pagos podem ser importados. Pedido %, status %.', v_site_order_id, v_status;
  end if;
  if length(v_documento) not in (11, 14) or v_nome is null or v_email is null then
    raise exception 'Cliente do pedido % possui cadastro incompleto.', v_site_order_id;
  end if;
  if jsonb_typeof(v_itens) <> 'array' or jsonb_array_length(v_itens) = 0 then
    raise exception 'Pedido % nao possui itens.', v_site_order_id;
  end if;

  insert into public.site_order_link (
    empresa_id, site_order_id, site_customer_id, site_status,
    payment_provider, gateway_payment_id, total_amount, order_created_at,
    import_status, import_locked_at, raw_order, last_synced_at
  ) values (
    p_empresa_id, v_site_order_id, v_site_customer_id, v_status,
    nullif(p_pedido->>'paymentProvider', ''), nullif(p_pedido->>'gatewayPaymentId', ''),
    coalesce((p_pedido->>'total')::numeric, 0), nullif(p_pedido->>'createdAt', '')::timestamptz,
    'PROCESSANDO', now(), p_pedido, now()
  )
  on conflict (empresa_id, site_order_id) do update set
    site_status = excluded.site_status,
    payment_provider = excluded.payment_provider,
    gateway_payment_id = excluded.gateway_payment_id,
    total_amount = excluded.total_amount,
    raw_order = excluded.raw_order,
    last_synced_at = now(),
    updated_at = now();

  select venda_id into v_venda_id
    from public.site_order_link
   where empresa_id = p_empresa_id and site_order_id = v_site_order_id
   for update;

  if v_venda_id is not null then
    return v_venda_id;
  end if;

  select id into v_cliente_id
    from public.cliente
   where regexp_replace(coalesce(cpfcnpj, ''), '\D', '', 'g') = v_documento
     and is_deleted = false
   order by id
   limit 1;

  if v_cliente_id is null then
    begin
      insert into public.cliente (
        tipopessoa, cpfcnpj, nomerazaosocial, email, telefone,
        endereco, endereconumero, enderecocomplemento, bairro,
        cidade, estado, cep, status
      ) values (
        case when length(v_documento) = 14 then 'JURIDICA' else 'FISICA' end::public.enum_tipopessoa,
        v_documento, v_nome, v_email, coalesce(v_telefone, 'SITE' || v_site_customer_id::text),
        nullif(v_endereco->>'logradouro', ''), nullif(v_endereco->>'numero', ''),
        nullif(v_endereco->>'complemento', ''), nullif(v_endereco->>'bairro', ''),
        coalesce(nullif(v_endereco->>'cidade', ''), 'Nao informado'),
        coalesce(nullif(v_endereco->>'estado', ''), 'NI'),
        nullif(regexp_replace(coalesce(v_endereco->>'cep', ''), '\D', '', 'g'), ''),
        'ATIVO'
      ) returning id into v_cliente_id;
    exception when unique_violation then
      select id into v_cliente_id
        from public.cliente
       where regexp_replace(coalesce(cpfcnpj, ''), '\D', '', 'g') = v_documento
       order by id
       limit 1;
      if v_cliente_id is null then
        raise;
      end if;
    end;
  end if;

  v_venda_id := public.fn_criar_venda_marketplace_com_itens(
    jsonb_build_object(
      'clienteId', v_cliente_id,
      'status', 'FINALIZADA',
      'canal', 'ONLINE',
      'statusEntrega', 'SEPARACAO',
      'subTotal', (p_pedido->>'subtotal')::numeric,
      'valorTotal', (p_pedido->>'total')::numeric,
      'formaPagamento', coalesce(nullif(p_pedido->>'paymentMethod', ''), 'ASAAS'),
      'dataVenda', coalesce(nullif(p_pedido->>'createdAt', ''), now()::text),
      'observacoes', 'Pedido do Site #' || v_site_order_id,
      'itens', v_itens
    )
  );

  update public.site_order_link
     set venda_id = v_venda_id,
         import_status = 'IMPORTADA',
         import_locked_at = null,
         import_error = null,
         updated_at = now()
   where empresa_id = p_empresa_id and site_order_id = v_site_order_id;

  return v_venda_id;
exception when others then
  update public.site_order_link
     set import_status = 'ERRO', import_locked_at = null,
         import_error = sqlerrm, updated_at = now()
   where empresa_id = p_empresa_id and site_order_id = v_site_order_id;
  raise;
end;
$$;


--
-- Name: fn_notificar_telegram_dfe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_notificar_telegram_dfe() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_chave text;
BEGIN
  -- Evento e manifestacao entram no mesmo razao; so NF-e de terceiro vira aviso.
  IF upper(btrim(coalesce(NEW.tipo_documento, ''))) NOT IN ('RESUMO_NFE', 'PROC_NFE') THEN
    RETURN NEW;
  END IF;

  v_chave := coalesce(nullif(btrim(coalesce(NEW.chave_acesso, '')), ''), 'NSU-' || NEW.nsu);

  IF TG_OP = 'INSERT' THEN
    -- A distribuicao devolve ate 90 dias de documentos na primeira sincronizacao
    -- da empresa. Avisar sobre todos eles seria uma enxurrada de mensagens sobre
    -- notas antigas: so entra o que foi emitido nos ultimos dias, que e o caso em
    -- que alguem ainda precisa manifestar ou dar entrada.
    IF NEW.data_emissao IS NOT NULL AND NEW.data_emissao < now() - interval '3 days' THEN
      RETURN NEW;
    END IF;

    PERFORM public.fn_enfileirar_notificacao_fiscal(
      'DFE', NEW.id::bigint, 'DFE_RECEBIDA', 'DFE:' || v_chave
    );
    RETURN NEW;
  END IF;

  -- 101 cancelada, 110 denegada: a nota deixou de valer depois de ja ter sido
  -- reconhecida aqui, e quem deu entrada nela precisa saber.
  IF NEW.status IS DISTINCT FROM OLD.status
     AND btrim(coalesce(NEW.status, '')) IN ('101', '110') THEN
    PERFORM public.fn_enfileirar_notificacao_fiscal(
      'DFE', NEW.id::bigint, 'DFE_CANCELADA', 'DFE-CANC:' || v_chave
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_notificar_telegram_nfe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_notificar_telegram_nfe() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF coalesce(NEW.is_deleted, false) THEN
    RETURN NEW;
  END IF;
  -- Homologacao e teste: nota de teste nao vira aviso. Rascunho antigo sem
  -- ambiente gravado conta como producao para nao engolir aviso legitimo.
  IF coalesce(NEW.ambiente::text, 'PRODUCAO') <> 'PRODUCAO' THEN
    RETURN NEW;
  END IF;

  v_evento := CASE upper(btrim(coalesce(NEW.status::text, '')))
    WHEN 'AUTORIZADA' THEN 'NFE_AUTORIZADA'
    WHEN 'REJEITADA' THEN 'NFE_REJEITADA'
    WHEN 'DENEGADA' THEN 'NFE_DENEGADA'
    WHEN 'CANCELADA' THEN 'NFE_CANCELADA'
    WHEN 'RESULTADO_INCERTO' THEN 'NFE_RESULTADO_INCERTO'
    ELSE NULL
  END;

  IF v_evento IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM public.fn_enfileirar_notificacao_fiscal(
    'NFE', NEW.id::bigint, v_evento, 'NFE:' || NEW.id::text
  );
  RETURN NEW;
END;
$$;


--
-- Name: fn_notificar_telegram_nfse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_notificar_telegram_nfse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  -- Denegacao de NFS-e volta com o motivo no mesmo lugar da rejeicao e exige a
  -- mesma correcao: um evento so.
  v_evento := CASE upper(btrim(coalesce(NEW.status::text, '')))
    WHEN 'AUTORIZADA' THEN 'NFSE_AUTORIZADA'
    WHEN 'REJEITADA' THEN 'NFSE_REJEITADA'
    WHEN 'DENEGADA' THEN 'NFSE_REJEITADA'
    WHEN 'CANCELADA' THEN 'NFSE_CANCELADA'
    ELSE NULL
  END;

  IF v_evento IS NULL THEN
    RETURN NEW;
  END IF;

  -- Uma mensagem por tentativa, nao por nota: o reenvio acontece na propria
  -- linha rejeitada, e a referencia e o que distingue um envio do outro.
  PERFORM public.fn_enfileirar_notificacao_fiscal(
    'NFSE',
    NEW.id::bigint,
    v_evento,
    'NFSE:' || NEW.id::text || ':' || coalesce(NEW.referencia::text, '')
  );
  RETURN NEW;
END;
$$;


--
-- Name: fn_notificar_telegram_transacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_notificar_telegram_transacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_evento text;
  v_origem text;
  v_valor numeric(14,2);
  v_dedupe text;
  v_ator uuid;
  v_quantidade_entregas integer := 0;
  v_endpoint_url text;
  v_bearer_token text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF coalesce(NEW.is_deleted, false) THEN
      RETURN NEW;
    END IF;
    IF NEW.transferencia_id IS NOT NULL THEN
      v_evento := 'TRANSFERENCIA_ENTRE_CONTAS';
    ELSIF coalesce(NEW.pendente, false) THEN
      v_evento := CASE WHEN upper(coalesce(NEW.tipo::text, '')) = 'RECEITA'
                       THEN 'CONTA_RECEBER_CRIADA' ELSE 'CONTA_PAGAR_CRIADA' END;
    ELSE
      v_evento := 'MOVIMENTO_CAIXA_CRIADO';
    END IF;
  ELSE
    -- Exclusao vem antes da baixa: a linha sai do fluxo, e o que aconteceu com
    -- `pendente` no mesmo update deixa de importar.
    IF coalesce(NEW.is_deleted, false) AND NOT coalesce(OLD.is_deleted, false) THEN
      v_evento := 'LANCAMENTO_EXCLUIDO';
    ELSIF coalesce(NEW.is_deleted, false) THEN
      RETURN NEW;
    ELSIF coalesce(OLD.pendente, false) AND NOT coalesce(NEW.pendente, false) THEN
      v_evento := CASE WHEN upper(coalesce(NEW.tipo::text, '')) = 'RECEITA'
                       THEN 'CONTA_RECEBER_LIQUIDADA' ELSE 'CONTA_PAGAR_LIQUIDADA' END;
    ELSIF NOT coalesce(OLD.pendente, false) AND coalesce(NEW.pendente, false) THEN
      v_evento := 'BAIXA_ESTORNADA';
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  v_origem := CASE
    WHEN NEW.ordemservicoid IS NOT NULL THEN 'ORDEM_SERVICO'
    WHEN NEW.vendaid IS NOT NULL THEN 'VENDA'
    WHEN NEW.entrada_id IS NOT NULL OR NEW.usoconsumo_entrada_id IS NOT NULL THEN 'ENTRADA'
    ELSE 'AVULSO'
  END;
  v_valor := abs(coalesce(NEW.valor, 0));
  v_ator := public.auditoria_usuario_requisicao();

  v_dedupe := CASE
    WHEN NEW.transferencia_id IS NOT NULL THEN 'TRANSF:' || NEW.transferencia_id::text
    ELSE 'TX:' || NEW.id::text || ':' || v_evento || ':'
         || to_char(coalesce(NEW.updated_at, now()), 'YYYYMMDDHH24MISSUS')
  END;

  INSERT INTO public.telegram_financeiro_entrega (
    transacao_id, evento_tipo, dedupe_chave, ator_usuario_id, usuario_id, chat_id
  )
  SELECT NEW.id, v_evento, v_dedupe, v_ator, preferencia.usuario_id, preferencia.chat_id
  FROM public.telegram_usuario_preferencia preferencia
  JOIN public.usuario usuario
    ON usuario.id = preferencia.usuario_id
   AND usuario.ativo = true
  WHERE preferencia.ativo = true
    AND preferencia.chat_id IS NOT NULL
    AND v_evento = ANY(preferencia.financeiro_eventos_selecionados)
    AND v_valor >= coalesce(preferencia.financeiro_valor_minimo, 0)
    -- Transferencia passa direto pelo filtro de origem: ela ja tem evento proprio,
    -- e some-la a lista faria quem escolhe origens perde-la sem perceber.
    AND (
      NEW.transferencia_id IS NOT NULL
      OR coalesce(array_length(preferencia.financeiro_origens_selecionadas, 1), 0) = 0
      OR v_origem = ANY(preferencia.financeiro_origens_selecionadas)
    )
    -- Titulo ainda sem banco definido nunca e excluido pelo filtro de contas:
    -- conta a pagar costuma nascer assim, e o banco so aparece na baixa.
    AND (
      coalesce(array_length(preferencia.financeiro_bancos_selecionados, 1), 0) = 0
      OR NEW.banco_id IS NULL
      OR NEW.banco_id = ANY(preferencia.financeiro_bancos_selecionados)
    )
    AND EXISTS (
      SELECT 1
      FROM public.perfilpermissao perfil_permissao
      JOIN public.permissao permissao
        ON permissao.id = perfil_permissao.permissaoid
      WHERE perfil_permissao.perfilid = usuario.perfilid
        AND upper(btrim(permissao.nome)) = 'FINANCEIRO:VISUALIZAR'
    )
  ON CONFLICT (usuario_id, evento_tipo, dedupe_chave) DO NOTHING;

  GET DIAGNOSTICS v_quantidade_entregas = ROW_COUNT;
  IF v_quantidade_entregas = 0 THEN
    RETURN NEW;
  END IF;

  SELECT endpoint_url, bearer_token
    INTO v_endpoint_url, v_bearer_token
    FROM public.telegram_dispatch_configuracao
   WHERE id = 1 AND ativo = true;

  IF v_endpoint_url IS NULL OR v_bearer_token IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_endpoint_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_bearer_token
      ),
      body := jsonb_build_object('origem', 'FINANCEIRO', 'transacao_id', NEW.id),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- Lancamento e baixa nunca falham por causa do aviso: a entrega fica
    -- pendente e o cron ou o botao de processar recuperam.
    RAISE WARNING 'Falha ao agendar notificacao Telegram da transacao %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: fn_os_execucao_set_times(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_os_execucao_set_times() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Quando entra em EM_ANDAMENTO, marca início (só se ainda não tiver)
  if (new.status::text = 'EM_ANDAMENTO' and old.status is distinct from new.status) then
    new.execucao_inicio_em := coalesce(old.execucao_inicio_em, now());
    new.execucao_fim_em := null; -- se voltar para andamento, reabre a execução
  end if;

  -- Quando entra em PAGAMENTO, marca fim (só se tiver início e ainda não tiver fim)
  if (new.status::text = 'PAGAMENTO' and old.status is distinct from new.status) then
    if (old.execucao_inicio_em is not null) then
      new.execucao_inicio_em := old.execucao_inicio_em;
      new.execucao_fim_em := coalesce(old.execucao_fim_em, now());
    end if;
  end if;

  -- Cancelar desfaz a conclusão: o carimbo é o que define OS concluída no
  -- sistema inteiro, e trabalho cancelado não é produção.
  if (new.status::text = 'CANCELADO') then
    new.execucao_fim_em := null;
  end if;

  -- Reiniciar também: OS de volta ao orçamento não terminou trabalho nenhum.
  if (new.status::text in (
        'AGUARDANDO_CHECKLIST', 'ORCAMENTO', 'APROVACAO_ORCAMENTO',
        'ORCAMENTO_APROVADO', 'ORCAMENTO_RECUSADO')) then
    new.execucao_fim_em := null;
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION fn_os_execucao_set_times(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_os_execucao_set_times() IS 'Mantém execucao_inicio_em e execucao_fim_em conforme o status: abre em EM_ANDAMENTO, fecha em PAGAMENTO e desfaz a conclusão em CANCELADO e nos status anteriores à execução. O carimbo de fim é o que define "OS concluída" em todo o sistema, então quem muda status é quem responde por ele.';


--
-- Name: fn_osproduto_snapshot_ultimo_custo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_osproduto_snapshot_ultimo_custo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new.custo_unitario_aplicado IS NULL THEN
    UPDATE public.osproduto op
       SET custo_unitario_aplicado = coalesce(nullif(p.ultimovalordecompra, 0), nullif(p.precocompra, 0))
      FROM public.produto p
     WHERE op.ordemservicoid = new.ordemservicoid
       AND op.produtoid = new.produtoid
       AND p.id = new.produtoid;
  END IF;
  RETURN new;
END;
$$;


--
-- Name: fn_preservar_vinculo_pedido_site(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_preservar_vinculo_pedido_site() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.venda_id is not null and (tg_op = 'DELETE' or new.venda_id is distinct from old.venda_id) then
    raise exception 'O vinculo de uma venda do site nao pode ser removido.';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: fn_proteger_cancelamento_site_enviado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proteger_cancelamento_site_enviado() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists(select 1 from public.site_order_link where venda_id = old.id) then
    if old.status_entrega::text in ('ENVIO', 'ENVIADO', 'ENTREGUE') then
      if new.status_entrega is distinct from old.status_entrega
         and coalesce(new.status_entrega::text, '') not in ('ENVIO', 'ENVIADO', 'ENTREGUE') then
        raise exception 'Pedido do site enviado nao pode retornar para uma etapa anterior.';
      end if;
      if new.status is distinct from old.status and new.status::text in ('CANCELADA', 'CANCELADO') and not exists(select 1 from public.site_order_link where venda_id=old.id and return_received_at is not null and refund_status='REFUNDED') then
        raise exception 'Pedido enviado exige devolucao fisica conferida antes de devolver estoque.';
      end if;
    end if;
    if new.status_entrega is distinct from old.status_entrega
       and new.status_entrega::text in ('ENVIO', 'ENVIADO', 'ENTREGUE')
       and exists(select 1 from public.site_order_link where venda_id = old.id
         and (refund_requested_at is not null or refund_status = 'REFUNDED')) then
      raise exception 'Pedido com estorno solicitado nao pode ser enviado ou entregue.';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: fn_proteger_itens_venda_site(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proteger_itens_venda_site() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_sale_id bigint;
begin
  if tg_table_name = 'transacao' then v_sale_id := old.vendaid;
  else v_sale_id := old.venda_id;
  end if;
  if exists(select 1 from public.site_order_link where venda_id = v_sale_id) then
    if tg_op = 'UPDATE' and tg_table_name = 'transacao' and exists (
      select 1 from public.site_order_link where venda_id = v_sale_id and refund_status = 'REFUNDED'
    ) then return new; end if;
    raise exception 'Nao e permitido alterar ou excluir itens ou lancamentos de uma venda do site.';
  end if;
  if tg_op = 'UPDATE' then return new; end if;
  return old;
end;
$$;


--
-- Name: fn_proteger_venda_site(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_proteger_venda_site() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (select 1 from public.site_order_link where venda_id = old.id) then
    if tg_op = 'DELETE' then
      raise exception 'Vendas do site nao podem ser excluidas. Preserve o historico do pedido.';
    end if;
    if to_jsonb(new)->'is_deleted' is distinct from to_jsonb(old)->'is_deleted' and coalesce((to_jsonb(new)->>'is_deleted')::boolean, false) then
      raise exception 'Vendas do site nao podem ser excluidas.';
    end if;
    if (to_jsonb(new)->'valortotal', to_jsonb(new)->'sub_total', to_jsonb(new)->'clienteid', to_jsonb(new)->'canal')
      is distinct from (to_jsonb(old)->'valortotal', to_jsonb(old)->'sub_total', to_jsonb(old)->'clienteid', to_jsonb(old)->'canal') then
      raise exception 'Valores, cliente e canal da venda do site nao podem ser alterados.';
    end if;
    if new.status is distinct from old.status then
      if new.status::text not in ('CANCELADA', 'CANCELADO') or not exists (
        select 1 from public.site_order_link where venda_id = old.id and refund_status = 'REFUNDED'
      ) then
        raise exception 'A alteracao de status da venda do site exige estorno confirmado no Asaas.';
      end if;
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: fn_publicar_produto_novo_no_site(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_publicar_produto_novo_no_site() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_empresas integer;
  v_empresa_id integer;
BEGIN
  SELECT count(*), min(id)
    INTO v_empresas, v_empresa_id
    FROM (SELECT id FROM public.empresa ORDER BY id LIMIT 2) empresas;

  IF v_empresas <> 1 THEN
    RETURN NEW;
  END IF;

  BEGIN
    -- O trigger de site_product_link enfileira a sincronizacao com a loja.
    INSERT INTO public.site_product_link (empresa_id, produto_id, status)
    VALUES (v_empresa_id, NEW.id, 'PUBLICADO')
    ON CONFLICT (empresa_id, produto_id) DO NOTHING;
  EXCEPTION WHEN others THEN
    RAISE WARNING 'Produto % cadastrado sem publicacao no site: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION fn_publicar_produto_novo_no_site(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fn_publicar_produto_novo_no_site() IS 'Cria site_product_link PUBLICADO para produto novo visivel no PDV. Ocultar do site e escolha explicita na aba Marketplace.';


--
-- Name: fn_registrar_evento_notificacao_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_registrar_evento_notificacao_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo text;
  v_status_anterior text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_tipo := 'CRIADA';
    v_status_anterior := NULL;
  ELSIF OLD.status IS DISTINCT FROM NEW.status THEN
    -- Devolução em massa por desativação da etapa não notifica: ver
    -- devolver_os_ao_desativar_faturamento.
    IF coalesce(current_setting('app.devolucao_faturamento_em_massa', true), 'off') = 'on' THEN
      RETURN NEW;
    END IF;
    v_tipo := 'STATUS_ALTERADO';
    v_status_anterior := OLD.status::text;
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.os_notificacao_evento (
    ordemservico_id, tipo, status_anterior, status_novo,
    ator_usuario_id, snapshot, disponivel_em
  ) VALUES (
    NEW.id, v_tipo, v_status_anterior, NEW.status::text,
    public.auditoria_usuario_requisicao(),
    jsonb_build_object(
      'cliente_id', NEW.clienteid,
      'veiculo_id', NEW.veiculoid,
      'peca_id', NEW.pecaid,
      'alvo_tipo', NEW.alvo_tipo,
      'equipamento_nome', NEW.equipamento_nome,
      'setor_id', NEW.setorid,
      'usuario_criador_id', NEW.usuariocriadorid,
      'prioridade', NEW.prioridade
    ),
    now()
  );

  RETURN NEW;
END;
$$;


