    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT telegram_estoque_entrega_evento_tipo_check CHECK ((evento_tipo = ANY (ARRAY['ENTRADA_REGISTRO'::text, 'ENTRADA_ESTORNO'::text, 'SAIDA_MANUAL_REGISTRO'::text, 'SAIDA_MANUAL_ESTORNO'::text, 'VENDA_REGISTRO'::text, 'VENDA_ESTORNO'::text, 'ORDEM_SERVICO_REGISTRO'::text, 'ORDEM_SERVICO_ESTORNO'::text]))),
    CONSTRAINT telegram_estoque_entrega_status_check CHECK ((status = ANY (ARRAY['PENDENTE'::text, 'ENVIANDO'::text, 'ENVIADO'::text, 'ERRO'::text, 'DESCARTADO'::text]))),
    CONSTRAINT telegram_estoque_entrega_tentativas_check CHECK ((tentativas >= 0))
