--
-- Name: fn_reservar_eventos_notificacao_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_eventos_notificacao_os(p_limit integer DEFAULT 30) RETURNS SETOF public.os_notificacao_evento
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH selecionados AS (
    SELECT evento.id
    FROM public.os_notificacao_evento evento
    WHERE (
      evento.status_processamento IN ('PENDENTE', 'ERRO')
      OR (
        evento.status_processamento = 'PROCESSANDO'
        AND evento.locked_at < now() - interval '10 minutes'
      )
    )
      AND evento.disponivel_em <= now()
      AND evento.tentativas < 5
    ORDER BY evento.id
    FOR UPDATE SKIP LOCKED
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 30), 1), 100)
  )
  UPDATE public.os_notificacao_evento evento
  SET status_processamento = 'PROCESSANDO',
      tentativas = evento.tentativas + 1,
      locked_at = now(),
      ultimo_erro = NULL
  FROM selecionados
  WHERE evento.id = selecionados.id
  RETURNING evento.*;
END;
$$;


--
-- Name: fn_reservar_importacao_mercadolivre(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_importacao_mercadolivre(p_ml_order_id bigint, p_empresa_id integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rows integer := 0;
BEGIN
  UPDATE public.mercadolivre_order
     SET import_status = 'PROCESSANDO',
         import_locked_at = now(),
         import_error = NULL,
         updated_at = now()
   WHERE ml_order_id = p_ml_order_id
     AND empresa_id = p_empresa_id
     AND venda_id IS NULL
     AND (
       import_status IN ('PENDENTE', 'ERRO')
       OR (
         import_status = 'PROCESSANDO'
         AND (import_locked_at IS NULL OR import_locked_at < now() - interval '10 minutes')
       )
     );

  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows > 0;
END;
$$;


--
-- Name: fn_reservar_importacao_shopee(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_importacao_shopee(p_order_sn text, p_empresa_id integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rows integer := 0;
begin
  update public.shopee_order
     set import_status = 'PROCESSANDO',
         import_locked_at = now(),
         import_error = null,
         updated_at = now()
   where order_sn = p_order_sn
     and empresa_id = p_empresa_id
     and venda_id is null
     and (
       import_status in ('PENDENTE', 'ERRO')
       or (import_status = 'PROCESSANDO' and (import_locked_at is null or import_locked_at < now() - interval '10 minutes'))
     );
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$$;


--
-- Name: fn_reservar_notificacoes_marketplace_telegram(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_notificacoes_marketplace_telegram(p_limit integer DEFAULT 50, p_source_event_id text DEFAULT NULL::text) RETURNS TABLE(notification_id bigint, usuario_id uuid, chat_id bigint, title text, message text, href text, source_event_id text, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with candidates as (
    select notification.id, preference.chat_id
      from public.system_notification notification
      join public.telegram_usuario_preferencia preference
        on preference.usuario_id = notification.usuario_id
     where notification.category = 'MARKETPLACE'
       and notification.source in ('MERCADOLIVRE_WEBHOOK', 'SITE_ORDER')
       and notification.telegram_sent_at is null
       and notification.telegram_attempts < 5
       and (notification.telegram_next_retry_at is null or notification.telegram_next_retry_at <= now())
       and (notification.telegram_locked_at is null or notification.telegram_locked_at < now() - interval '15 minutes')
       and (p_source_event_id is null or notification.source_event_id = p_source_event_id)
       and preference.ativo = true
       and ((notification.source = 'MERCADOLIVRE_WEBHOOK' and preference.notificar_marketplace = true)
         or (notification.source = 'SITE_ORDER' and preference.notificar_site = true))
       and preference.chat_id is not null
       -- Sem escolha explícita o usuário continua recebendo tudo o que vê na
       -- central; um aviso sem evento no metadata nunca é engolido pelo filtro.
       and (
         notification.source = 'SITE_ORDER'
         or preference.marketplace_topicos_selecionados is null
         or notification.metadata->>'event' is null
         or notification.metadata->>'event' = any (preference.marketplace_topicos_selecionados)
       )
     order by notification.created_at, notification.id
     for update of notification skip locked
     limit least(greatest(coalesce(p_limit, 50), 1), 100)
  )
  update public.system_notification notification
     set telegram_attempts = notification.telegram_attempts + 1,
         telegram_locked_at = now()
    from candidates
   where notification.id = candidates.id
  returning notification.id,
            notification.usuario_id,
            candidates.chat_id,
            notification.title,
            notification.message,
            notification.href,
            notification.source_event_id,
            notification.telegram_attempts;
end;
$$;


--
-- Name: fn_reservar_notificacoes_mercadolivre(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_notificacoes_mercadolivre(p_limit integer DEFAULT 30) RETURNS TABLE(notification_id bigint, processing_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH selected AS (
    SELECT notification.id
      FROM public.mercadolivre_notification notification
     WHERE (
       (
         notification.status IN ('RECEBIDA', 'ERRO')
         AND (notification.next_retry_at IS NULL OR notification.next_retry_at <= now())
       )
       OR (
         notification.status = 'PROCESSANDO'
         AND (notification.locked_at IS NULL OR notification.locked_at < now() - interval '10 minutes')
       )
     )
     ORDER BY notification.created_at ASC
     FOR UPDATE SKIP LOCKED
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 30), 1), 100)
  )
  UPDATE public.mercadolivre_notification notification
     SET status = 'PROCESSANDO',
         processing_attempts = notification.processing_attempts + 1,
         locked_at = now(),
         error = NULL
    FROM selected
   WHERE notification.id = selected.id
  RETURNING notification.id, notification.processing_attempts;
END;
$$;


--
-- Name: telegram_resumo_financeiro_envio; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.telegram_resumo_financeiro_envio (
    id bigint NOT NULL,
    usuario_id uuid NOT NULL,
    referencia_data date NOT NULL,
    status text DEFAULT 'PENDENTE'::text NOT NULL,
    tentativas integer DEFAULT 0 NOT NULL,
    proxima_tentativa_em timestamp with time zone,
    locked_at timestamp with time zone,
    mensagens jsonb,
    proxima_mensagem integer DEFAULT 0 NOT NULL,
    quantidade_atrasadas integer DEFAULT 0 NOT NULL,
    quantidade_hoje integer DEFAULT 0 NOT NULL,
    total_atrasado numeric(14,2) DEFAULT 0 NOT NULL,
    total_hoje numeric(14,2) DEFAULT 0 NOT NULL,
    telegram_message_ids bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    erro text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tipo text DEFAULT 'A_PAGAR'::text NOT NULL,
    CONSTRAINT telegram_resumo_financeiro_envio_proxima_mensagem_check CHECK ((proxima_mensagem >= 0)),
    CONSTRAINT telegram_resumo_financeiro_envio_status_check CHECK ((status = ANY (ARRAY['PENDENTE'::text, 'PROCESSANDO'::text, 'ENVIADO'::text, 'SEM_MOVIMENTO'::text, 'ERRO'::text]))),
    CONSTRAINT telegram_resumo_financeiro_envio_tentativas_check CHECK ((tentativas >= 0)),
    CONSTRAINT telegram_resumo_financeiro_envio_tipo_check CHECK ((tipo = ANY (ARRAY['A_PAGAR'::text, 'A_RECEBER'::text])))
);


--
-- Name: TABLE telegram_resumo_financeiro_envio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.telegram_resumo_financeiro_envio IS 'Controle idempotente do resumo diario de contas a pagar enviado pelo Telegram.';


--
-- Name: COLUMN telegram_resumo_financeiro_envio.tipo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.telegram_resumo_financeiro_envio.tipo IS 'Qual resumo diario esta linha controla: A_PAGAR ou A_RECEBER.';


--
-- Name: fn_reservar_resumos_financeiros_telegram(date, time without time zone, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_resumos_financeiros_telegram(p_referencia_data date, p_horario_local time without time zone, p_limit integer DEFAULT 20, p_tipo text DEFAULT 'A_PAGAR'::text) RETURNS SETOF public.telegram_resumo_financeiro_envio
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_tipo NOT IN ('A_PAGAR', 'A_RECEBER') THEN
    RAISE EXCEPTION 'Tipo de resumo invalido: %', p_tipo USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.telegram_resumo_financeiro_envio (usuario_id, referencia_data, tipo)
  SELECT preferencia.usuario_id, p_referencia_data, p_tipo
    FROM public.telegram_usuario_preferencia preferencia
    JOIN public.usuario usuario ON usuario.id = preferencia.usuario_id AND usuario.ativo = true
   WHERE preferencia.ativo = true
     AND preferencia.chat_id IS NOT NULL
     AND CASE WHEN p_tipo = 'A_RECEBER'
              THEN preferencia.notificar_receber_diario
              ELSE preferencia.notificar_financeiro_diario
         END = true
     AND CASE WHEN p_tipo = 'A_RECEBER'
              THEN preferencia.horario_resumo_receber
              ELSE preferencia.horario_resumo_financeiro
         END <= p_horario_local
     AND EXISTS (
       SELECT 1
         FROM public.perfilpermissao perfil_permissao
         JOIN public.permissao permissao ON permissao.id = perfil_permissao.permissaoid
        WHERE perfil_permissao.perfilid = usuario.perfilid
          AND upper(btrim(permissao.nome)) = 'FINANCEIRO:VISUALIZAR'
     )
  ON CONFLICT (usuario_id, referencia_data, tipo) DO NOTHING;

  RETURN QUERY
  WITH selecionados AS (
    SELECT envio.id
      FROM public.telegram_resumo_financeiro_envio envio
      JOIN public.telegram_usuario_preferencia preferencia
        ON preferencia.usuario_id = envio.usuario_id
       AND preferencia.ativo = true
       AND preferencia.chat_id IS NOT NULL
       AND CASE WHEN p_tipo = 'A_RECEBER'
                THEN preferencia.notificar_receber_diario
                ELSE preferencia.notificar_financeiro_diario
           END = true
      JOIN public.usuario usuario ON usuario.id = envio.usuario_id AND usuario.ativo = true
     WHERE envio.referencia_data = p_referencia_data
       AND envio.tipo = p_tipo
       AND (
         envio.status = 'PENDENTE'
         OR (envio.status = 'ERRO' AND coalesce(envio.proxima_tentativa_em, now()) <= now())
         OR (envio.status = 'PROCESSANDO' AND envio.locked_at < now() - interval '10 minutes')
       )
       AND envio.tentativas < 5
       AND EXISTS (
         SELECT 1
           FROM public.perfilpermissao perfil_permissao
           JOIN public.permissao permissao ON permissao.id = perfil_permissao.permissaoid
          WHERE perfil_permissao.perfilid = usuario.perfilid
            AND upper(btrim(permissao.nome)) = 'FINANCEIRO:VISUALIZAR'
       )
     ORDER BY envio.id
     FOR UPDATE OF envio SKIP LOCKED
     LIMIT LEAST(GREATEST(coalesce(p_limit, 20), 1), 100)
  )
  UPDATE public.telegram_resumo_financeiro_envio envio
     SET status = 'PROCESSANDO',
         tentativas = envio.tentativas + 1,
         locked_at = now(),
         erro = NULL,
         updated_at = now()
    FROM selecionados
   WHERE envio.id = selecionados.id
  RETURNING envio.*;
END;
$$;


--
-- Name: fn_reservar_sincronizacao_estoque_ml(integer, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_sincronizacao_estoque_ml(p_limit integer DEFAULT 30, p_product_ids integer[] DEFAULT NULL::integer[]) RETURNS TABLE(queue_id bigint, empresa_id integer, product_link_id bigint, produto_id integer, desired_quantity integer, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH selected AS (
    SELECT queue.id
      FROM public.mercadolivre_stock_sync_queue queue
     WHERE (
       queue.status IN ('PENDENTE', 'ERRO')
       OR (
         queue.status = 'PROCESSANDO'
         AND (queue.locked_at IS NULL OR queue.locked_at < now() - interval '10 minutes')
       )
     )
       AND (queue.next_retry_at IS NULL OR queue.next_retry_at <= now())
       AND (p_product_ids IS NULL OR queue.produto_id = ANY(p_product_ids))
     ORDER BY queue.updated_at ASC
     FOR UPDATE SKIP LOCKED
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 30), 1), 100)
  )
  UPDATE public.mercadolivre_stock_sync_queue queue
     SET status = 'PROCESSANDO',
         attempts = queue.attempts + 1,
         locked_at = now(),
         last_error = NULL,
         updated_at = now()
    FROM selected
   WHERE queue.id = selected.id
  RETURNING
    queue.id,
    queue.empresa_id,
    queue.product_link_id,
    queue.produto_id,
    queue.desired_quantity,
    queue.attempts;
END;
$$;


--
-- Name: fn_reservar_sincronizacao_site(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reservar_sincronizacao_site(p_limit integer DEFAULT 50, p_empresa_id integer DEFAULT NULL::integer) RETURNS TABLE(queue_id bigint, event_id uuid, empresa_id integer, product_link_id bigint, produto_id integer, desired_version bigint, attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with candidates as (
    select q.id
      from public.site_catalog_sync_queue q
     where (
         q.status in ('PENDENTE', 'ERRO')
         or (q.status = 'PROCESSANDO' and q.locked_at < now() - interval '15 minutes')
       )
       and (q.next_retry_at is null or q.next_retry_at <= now())
       and (p_empresa_id is null or q.empresa_id = p_empresa_id)
     order by q.created_at, q.id
     for update skip locked
     limit least(greatest(coalesce(p_limit, 50), 1), 100)
  ), reserved as (
    update public.site_catalog_sync_queue q
       set status = 'PROCESSANDO',
           attempts = q.attempts + 1,
           locked_at = now(),
           updated_at = now()
      from candidates c
     where q.id = c.id
     returning q.*
  )
  select
    r.id,
    r.event_id,
    r.empresa_id,
    r.product_link_id,
    r.produto_id,
    r.desired_version,
    r.attempts
  from reserved r
  order by r.created_at, r.id;
end;
$$;


--
-- Name: fn_set_status_estoque(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_set_status_estoque() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin
  new.status_estoque :=
    case
      when new.estoque <= 0 then 'SEM_ESTOQUE'
      when new.estoque <= (new.estoqueminimo / 2) then 'CRITICO'
      when new.estoque <= new.estoqueminimo then 'BAIXO'
      else 'OK'
    end;
  return new;
end;$$;


--
-- Name: fn_set_titulo_marketplace_product(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_set_titulo_marketplace_product() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin
  new.tituloMarketplace :=
    case
      when new.tituloMarketplace = '' then new.titulo
    end;
  return new;
end;$$;


--
-- Name: fn_sincronizar_baixa_estoque_marketplace(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sincronizar_baixa_estoque_marketplace(p_venda_id integer, p_produto_id integer, p_quantidade_alvo integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto('VENDA', p_venda_id::bigint, 'Venda #' || p_venda_id || ' (marketplace)');
  PERFORM public.fn_sincronizar_baixa_estoque_marketplace_interna(p_venda_id, p_produto_id, p_quantidade_alvo);
END;
$$;


--
-- Name: fn_sincronizar_baixa_estoque_marketplace_interna(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sincronizar_baixa_estoque_marketplace_interna(p_venda_id integer, p_produto_id integer, p_quantidade_alvo integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estoque integer;
  v_quantidade_atual integer := 0;
  v_delta integer;
BEGIN
  IF p_venda_id IS NULL OR p_venda_id <= 0 OR p_produto_id IS NULL OR p_produto_id <= 0 THEN
    RAISE EXCEPTION 'Venda e produto são obrigatórios.';
  END IF;
  IF p_quantidade_alvo IS NULL OR p_quantidade_alvo < 0 THEN
    RAISE EXCEPTION 'Quantidade alvo inválida.';
  END IF;

  SELECT estoque
    INTO v_estoque
    FROM public.produto
   WHERE id = p_produto_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto % não encontrado.', p_produto_id;
  END IF;

  SELECT quantidade
    INTO v_quantidade_atual
    FROM public.vendaproduto_baixa
   WHERE venda_id = p_venda_id
     AND produtoid = p_produto_id
   FOR UPDATE;

  v_quantidade_atual := COALESCE(v_quantidade_atual, 0);
  v_delta := p_quantidade_alvo - v_quantidade_atual;

  IF v_delta > 0 THEN
    IF v_estoque < v_delta THEN
      RAISE EXCEPTION 'Estoque insuficiente para produto %, em estoque: %, necessário: %',
        p_produto_id, v_estoque, v_delta;
    END IF;

    UPDATE public.produto
       SET estoque = estoque - v_delta,
           updatedat = now()
     WHERE id = p_produto_id;
  ELSIF v_delta < 0 THEN
    UPDATE public.produto
       SET estoque = estoque + abs(v_delta),
           updatedat = now()
     WHERE id = p_produto_id;
  END IF;

  IF p_quantidade_alvo = 0 THEN
    DELETE FROM public.vendaproduto_baixa
     WHERE venda_id = p_venda_id
       AND produtoid = p_produto_id;
  ELSE
    INSERT INTO public.vendaproduto_baixa (venda_id, produtoid, quantidade, created_at, updated_at)
    VALUES (p_venda_id, p_produto_id, p_quantidade_alvo, now(), now())
    ON CONFLICT (venda_id, produtoid) DO UPDATE
      SET quantidade = EXCLUDED.quantidade,
          updated_at = now();
  END IF;
END;
$$;


--
-- Name: fn_site_product_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_site_product_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_link_id bigint;
begin
  for v_link_id in
    select id
      from public.site_product_link
     where produto_id = new.id
       and status <> 'RASCUNHO'
  loop
    perform public.fn_enfileirar_site_product_link(v_link_id);
  end loop;
  return new;
end;
$$;


