    perform public.fn_enfileirar_site_product_link(v_link_id);
  end loop;
  return new;
end;
$$;


--
-- Name: fn_site_product_image_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_site_product_image_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_produto_id integer := coalesce(new.produto_id, old.produto_id);
  v_link_id bigint;
begin
  for v_link_id in
    select id
      from public.site_product_link
     where produto_id = v_produto_id
       and status <> 'RASCUNHO'
  loop
    perform public.fn_enfileirar_site_product_link(v_link_id);
  end loop;
  return coalesce(new, old);
end;
$$;


