--
-- Name: fn_sync_site_order_delivery_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sync_site_order_delivery_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_endereco jsonb;
begin
  if new.venda_id is null then
    return new;
  end if;

  v_endereco := coalesce(new.raw_order->'shippingAddress', '{}'::jsonb);
  if jsonb_typeof(v_endereco) = 'object' and v_endereco <> '{}'::jsonb then
    update public.venda
       set endereco_entrega_snapshot = v_endereco,
           updatedat = now()
     where id = new.venda_id
       and endereco_entrega_snapshot is distinct from v_endereco;
  end if;

  return new;
end;
$$;


--
-- Name: fn_tipo_evento_notificacao_estoque(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_tipo_evento_notificacao_estoque(p_origem text, p_acao text, p_sentido text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_origem = 'ENTRADA' AND p_acao = 'REGISTRO' AND p_sentido = 'ENTRADA'
      THEN 'ENTRADA_REGISTRO'
    WHEN p_origem = 'ENTRADA' AND p_acao = 'ESTORNO' AND p_sentido = 'SAIDA'
      THEN 'ENTRADA_ESTORNO'
    WHEN p_origem = 'SAIDA_MANUAL' AND p_acao = 'REGISTRO' AND p_sentido = 'SAIDA'
      THEN 'SAIDA_MANUAL_REGISTRO'
    WHEN p_origem = 'SAIDA_MANUAL' AND p_acao = 'ESTORNO' AND p_sentido = 'ENTRADA'
      THEN 'SAIDA_MANUAL_ESTORNO'
    WHEN p_origem = 'VENDA' AND p_acao = 'REGISTRO' AND p_sentido = 'SAIDA'
      THEN 'VENDA_REGISTRO'
    WHEN p_origem = 'VENDA' AND p_acao = 'ESTORNO' AND p_sentido = 'ENTRADA'
      THEN 'VENDA_ESTORNO'
    WHEN p_origem = 'ORDEM_SERVICO' AND p_acao = 'REGISTRO' AND p_sentido = 'SAIDA'
      THEN 'ORDEM_SERVICO_REGISTRO'
    WHEN p_origem = 'ORDEM_SERVICO' AND p_acao = 'ESTORNO' AND p_sentido = 'ENTRADA'
      THEN 'ORDEM_SERVICO_ESTORNO'
    ELSE NULL
  END;
$$;


--
-- Name: fn_vendaproduto_snapshot_ultimo_custo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_vendaproduto_snapshot_ultimo_custo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.custo_unitario_aplicado is null then
    select p.ultimovalordecompra
      into new.custo_unitario_aplicado
      from public.produto p
     where p.id = new.produtoid;
  end if;
  return new;
end;
$$;


--
-- Name: formatar_percentual_comissao(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.formatar_percentual_comissao(p_percentual numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT replace(
           rtrim(rtrim(to_char(coalesce(p_percentual, 0), 'FM999999990.00'), '0'), '.'),
           '.', ','
         );
$$;


--
-- Name: FUNCTION formatar_percentual_comissao(p_percentual numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.formatar_percentual_comissao(p_percentual numeric) IS 'Percentual em texto para o detalhe do evento de comissao: 10.00 -> "10", 7.50 -> "7,5".';


--
-- Name: habilitar_auditoria_tabela(regclass); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.habilitar_auditoria_tabela(nome_tabela regclass) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  schema_nome text;
  tabela_nome text;
begin
  select n.nspname, c.relname
    into schema_nome, tabela_nome
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where c.oid = nome_tabela;

  if schema_nome <> 'public' or tabela_nome = 'auditoria_evento' then
    raise exception 'A auditoria so pode ser habilitada em tabelas de negocio do schema public';
  end if;

  execute format('drop trigger if exists auditoria_linha on %I.%I', schema_nome, tabela_nome);
  execute format(
    'create trigger auditoria_linha after insert or update or delete on %I.%I for each row execute function public.registrar_auditoria()',
    schema_nome,
    tabela_nome
  );
end;
$$;


--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  ator uuid := public.auditoria_try_uuid(new.raw_user_meta_data ->> 'created_by');
begin
  insert into public.usuario (
    id, email, nome, perfilid, setorid, createdat, updatedat, created_by, updated_by
  ) values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'nome', new.email),
    nullif(new.raw_user_meta_data ->> 'perfilid', '')::int,
    nullif(new.raw_user_meta_data ->> 'setorid', '')::int,
    now(),
    now(),
    ator,
    ator
  )
  on conflict (id) do update
    set email = excluded.email,
        nome = coalesce(excluded.nome, public.usuario.nome),
        perfilid = coalesce(excluded.perfilid, public.usuario.perfilid),
        setorid = coalesce(excluded.setorid, public.usuario.setorid),
        created_by = coalesce(public.usuario.created_by, excluded.created_by),
        updated_by = coalesce(excluded.updated_by, public.usuario.updated_by),
        updatedat = now();
  return new;
end;
$$;


--
-- Name: handle_update_auth_user_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_update_auth_user_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.email is distinct from old.email then
    update public.usuario
       set email = new.email,
           updatedat = now()
     where id = new.id;
  end if;
  return new;
end;
$$;


--
-- Name: impedir_financeiro_em_os_historica_migrada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.impedir_financeiro_em_os_historica_migrada() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.ordemservicoid is not null
     and exists (
       select 1
         from public.ordemservico os
        where os.id = new.ordemservicoid
          and os.migracao_referencia is not null
     ) then
    raise exception 'A OS % e historica e nao aceita lancamentos financeiros.', new.ordemservicoid
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: invalidar_aprovacoes_venda(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidar_aprovacoes_venda(p_venda_id integer, p_motivo text DEFAULT 'ORCAMENTO_ALTERADO'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_quantidade integer;
BEGIN
  UPDATE public.vendaaprovacao
     SET invalidado_em = now(),
         motivo_invalidacao = nullif(btrim(p_motivo), '')
   WHERE vendaid = p_venda_id
     AND usado_em IS NULL
     AND invalidado_em IS NULL;

  GET DIAGNOSTICS v_quantidade = ROW_COUNT;
  RETURN v_quantidade;
END;
$$;


--
-- Name: invalidar_convites_checklist_por_assinatura_presencial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidar_convites_checklist_por_assinatura_presencial() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.metodo <> 'PRESENCIAL_DESENHADA' then return new; end if;
  with revogados as (
    update public.checklist_documento_convite_assinatura convite
       set revogado_em = now(),
           motivo_revogacao = 'ASSINADO_PRESENCIALMENTE'
     where convite.documento_id = new.documento_id
       and convite.revogado_em is null
       and convite.consumido_em is null
    returning convite.id
  )
  insert into public.checklist_documento_evento (documento_id, tipo, metadados)
  select new.documento_id, 'CONVITE_ASSINATURA_REVOGADO', jsonb_build_object(
    'conviteId', id,
    'motivo', 'ASSINADO_PRESENCIALMENTE'
  ) from revogados;
  return new;
end;
$$;


--
-- Name: invalidar_convites_checklist_por_nova_versao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidar_convites_checklist_por_nova_versao() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  with revogados as (
    update public.checklist_documento_convite_assinatura convite
       set revogado_em = now(),
           motivo_revogacao = 'SUPERADO'
      from public.checklist_documento anterior
     where convite.documento_id = anterior.id
       and anterior.ordemservico_id = new.ordemservico_id
       and anterior.tipo = new.tipo
       and anterior.versao < new.versao
       and convite.revogado_em is null
       and convite.consumido_em is null
    returning convite.documento_id, convite.id
  )
  insert into public.checklist_documento_evento (documento_id, tipo, metadados)
  select documento_id, 'CONVITE_ASSINATURA_SUPERADO', jsonb_build_object(
    'conviteId', id,
    'novaVersao', new.versao,
    'novaVersaoPublicId', new.public_id
  ) from revogados;
  return new;
end;
$$;


--
-- Name: is_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_staff() RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (
    select 1 from public.usuario u
    where u.id = (select auth.uid())
      and u.ativo = true
  );
$$;


--
-- Name: listar_metodos_pagamento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listar_metodos_pagamento() RETURNS TABLE(value text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select enum_value.enumlabel::text
  from pg_catalog.pg_type enum_type
  join pg_catalog.pg_namespace enum_namespace
    on enum_namespace.oid = enum_type.typnamespace
  join pg_catalog.pg_enum enum_value
    on enum_value.enumtypid = enum_type.oid
  where enum_namespace.nspname = 'public'
    and enum_type.typname = 'metodo_pagamento'
  order by enum_value.enumsortorder;
$$;


--
-- Name: marketplace_search_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_search_normalize(p_text text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public'
    AS $$
  select translate(lower(coalesce(p_text, '')),
    'áàâãäåéèêëíìîïóòôõöúùûüçñ', 'aaaaaaeeeeiiiiooooouuuucn');
$$;


--
-- Name: marketplace_search_products(bigint, jsonb, integer, integer, bigint, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketplace_search_products(p_empresa_id bigint, p_tokens jsonb DEFAULT '[]'::jsonb, p_page integer DEFAULT 1, p_limit integer DEFAULT 20, p_product_id bigint DEFAULT NULL::bigint, p_linked boolean DEFAULT false, p_unlinked boolean DEFAULT false, p_include_zero boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  if p_empresa_id is null or p_empresa_id <= 0 or p_page is null or p_page < 1
    or p_page > 100000 or p_limit is null or p_limit < 1 or p_limit > 1000
    or p_tokens is null or jsonb_typeof(p_tokens) <> 'array' then
    raise exception 'Parâmetros de busca inválidos';
  end if;
  if jsonb_array_length(p_tokens) > 20 then raise exception 'Busca muito longa'; end if;

  with candidates as (
    select p.id, to_jsonb(p) as doc
    from public.produto p
    where p.is_deleted = false
      and (p_product_id is null or p.id = p_product_id)
      and (p_product_id is not null or (
        (not p_linked and not p_unlinked and (p_include_zero or p.estoque > 0))
        or (p_unlinked and not exists (select 1 from public.mercadolivre_product_link l
          where l.empresa_id = p_empresa_id and l.produto_id = p.id and l.ml_item_id is not null))
        or (p_linked and not p_unlinked and exists (select 1 from public.mercadolivre_product_link l
          where l.empresa_id = p_empresa_id and l.produto_id = p.id and l.ml_item_id is not null))
      ))
  ), matched as materialized (
    select c.id from candidates c
    where not exists (
      select 1 from jsonb_array_elements(p_tokens) token
      where not (
        (not coalesce((token->>'structured')::boolean, false) and c.id::text = token->>'value')
        or exists (
          select 1 from jsonb_each_text(c.doc) field
          where field.key = any(case when coalesce((token->>'structured')::boolean, false)
            then array['referencia','codigobarras','etiqueta','ncm','cest']
            else array['titulo','descricao','referencia','fabricante','codigobarras','etiqueta',
              'local','ncm','cest','status_estoque','conservacao','tituloMarketplace','descricaoMarketplace'] end)
            and strpos(public.marketplace_search_normalize(field.value), token->>'value') > 0
        )
      )
    )
  ), page_rows as (
    select p.* from public.produto p join (
      select id from matched order by id desc limit p_limit offset ((p_page - 1)::bigint * p_limit)
    ) ids on ids.id = p.id
  )
  select jsonb_build_object('total', (select count(*) from matched),
    'data', coalesce((select jsonb_agg(jsonb_build_object(
      'id', p.id, 'titulo', p.titulo, 'descricao', p.descricao, 'referencia', p.referencia,
      'precovenda', p.precovenda, 'estoque', p.estoque,
      'status_estoque', p.status_estoque, 'tituloMarketplace', p."tituloMarketplace",
      'descricaoMarketplace', p."descricaoMarketplace", 'imgUrl', p."imgUrl",
      'fabricante', p.fabricante, 'codigobarras', p.codigobarras, 'conservacao', p.conservacao,
      'etiqueta', p.etiqueta, 'local', p.local, 'ncm', p.ncm, 'cest', p.cest
    ) order by p.id desc) from page_rows p), '[]'::jsonb)) into result;
  return result;
end;
$$;


--
-- Name: mercadolivre_sync_run; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mercadolivre_sync_run (
    id bigint NOT NULL,
    job_name text DEFAULT 'FULL_SYNC'::text NOT NULL,
    trigger_source text DEFAULT 'CRON'::text NOT NULL,
    status text DEFAULT 'PROCESSANDO'::text NOT NULL,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    error text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    duration_ms integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT mercadolivre_sync_run_status_check CHECK ((status = ANY (ARRAY['PROCESSANDO'::text, 'CONCLUIDO'::text, 'PARCIAL'::text, 'ERRO'::text])))
);


--
-- Name: mercadolivre_latest_sync_runs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mercadolivre_latest_sync_runs() RETURNS SETOF public.mercadolivre_sync_run
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select latest.*
  from unnest(array['NOTIFICATIONS','ORDERS','ITEMS','SHIPMENTS','STOCK','INVOICES','METRICS']) as jobs(name)
  cross join lateral (
    select r.* from public.mercadolivre_sync_run r
    where r.job_name = jobs.name
    order by r.started_at desc, r.id desc
    limit 1
  ) latest
  order by latest.started_at desc, latest.id desc;
$$;


--
-- Name: natureza_dre_de_evento(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.natureza_dre_de_evento(p_origem text, p_natureza text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    (SELECT dl.natureza_dre
       FROM public.dre_mapeamento mp
       JOIN public.dre_linha dl ON dl.id = mp.linha_id
      WHERE mp.ativo
        AND mp.origem_tipo = 'EVENTO_ORIGEM'
        AND mp.origem_valor = p_origem || ':' || p_natureza
      ORDER BY mp.template_id DESC, mp.id
      LIMIT 1),
    CASE WHEN p_natureza = 'RECEITA' THEN 'RECEITA' ELSE 'DESPESA' END
  );
$$;


--
-- Name: FUNCTION natureza_dre_de_evento(p_origem text, p_natureza text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.natureza_dre_de_evento(p_origem text, p_natureza text) IS 'Classificacao de resultado (RECEITA/DEDUCAO/CUSTO/DESPESA) da origem de um evento, lida da linha mapeada no template da DRE. Mantem o evento e o template com uma fonte de verdade so.';


--
-- Name: nfe_alocar_numero(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_alocar_numero(p_config_id bigint) RETURNS TABLE(numero integer, serie integer, empresaid bigint, modelo public.enum_modelo_nfe, ambiente public.enum_ambiente_nfe)
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_config public.nfe_config%ROWTYPE;
  v_reaproveitado integer;
BEGIN
  SELECT *
    INTO v_config
    FROM public.nfe_config
   WHERE id = p_config_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Configuração de NF-e % não encontrada.', p_config_id;
  END IF;

  -- O lock na config acima serializa as alocações concorrentes.
  DELETE FROM public.nfe_numero_liberado l
   WHERE l.id = (
     SELECT candidato.id
       FROM public.nfe_numero_liberado candidato
      WHERE candidato.config_id = p_config_id
        AND candidato.serie = v_config.serie
      ORDER BY candidato.numero
      LIMIT 1
   )
  RETURNING l.numero INTO v_reaproveitado;

  IF v_reaproveitado IS NOT NULL THEN
    numero := v_reaproveitado;
    serie := v_config.serie;
    empresaid := v_config.empresaid;
    modelo := v_config.modelo;
    ambiente := v_config.ambiente;
    RETURN NEXT;
    RETURN;
  END IF;

  UPDATE public.nfe_config
     SET ultimo_numero = COALESCE(ultimo_numero, 0) + 1,
         updatedat = now()
   WHERE id = p_config_id
   RETURNING ultimo_numero, nfe_config.serie, nfe_config.empresaid, nfe_config.modelo, nfe_config.ambiente
    INTO numero, serie, empresaid, modelo, ambiente;

  RETURN NEXT;
END;
$$;


--
-- Name: nfe_ciencia_aviso_somente_inclusao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_ciencia_aviso_somente_inclusao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'nfe_ciencia_aviso é trilha de auditoria: não se apaga ciência registrada (id %).', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  IF (to_jsonb(NEW) - 'nfe_id') IS DISTINCT FROM (to_jsonb(OLD) - 'nfe_id') THEN
    RAISE EXCEPTION 'nfe_ciencia_aviso é trilha de auditoria: só nfe_id pode mudar (id %).', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  -- Ligar a uma NF-e (NULL -> id) ou desligar pelo descarte (id -> NULL).
  -- Mover a ciência de uma nota para outra não é permitido.
  IF OLD.nfe_id IS NOT NULL AND NEW.nfe_id IS NOT NULL AND NEW.nfe_id <> OLD.nfe_id THEN
    RAISE EXCEPTION 'ciência % já pertence à NF-e %; não pode ser movida para a %.', OLD.id, OLD.nfe_id, NEW.nfe_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: nfe_impedir_origem_transmitida_duplicada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_impedir_origem_transmitida_duplicada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status_ocupa boolean;
  v_status_anterior_ocupava boolean := false;
BEGIN
  v_status_ocupa := NOT coalesce(NEW.is_deleted, false)
    AND NEW.status IN (
      'ASSINADA', 'ENVIADA', 'PENDENTE_ENVIO',
      'CONTINGENCIA', 'RESULTADO_INCERTO'
    );

  IF NOT v_status_ocupa THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    v_status_anterior_ocupava := NOT coalesce(OLD.is_deleted, false)
      AND OLD.status IN (
        'ASSINADA', 'ENVIADA', 'PENDENTE_ENVIO',
        'CONTINGENCIA', 'RESULTADO_INCERTO'
      );

    IF v_status_anterior_ocupava
       AND NEW.vendaid IS NOT DISTINCT FROM OLD.vendaid
       AND NEW.ordemservicoid IS NOT DISTINCT FROM OLD.ordemservicoid
       AND NEW.modelo IS NOT DISTINCT FROM OLD.modelo THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.vendaid IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(format('nfe:venda:%s:modelo:%s', NEW.vendaid, NEW.modelo), 0)
    );

    IF EXISTS (
      SELECT 1
        FROM public.nfe existente
       WHERE existente.id <> coalesce(NEW.id, -1)
         AND existente.vendaid = NEW.vendaid
         AND existente.modelo = NEW.modelo
         AND existente.is_deleted = false
         AND existente.status IN (
           'ASSINADA', 'ENVIADA', 'PENDENTE_ENVIO',
           'CONTINGENCIA', 'RESULTADO_INCERTO'
         )
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23505',
        MESSAGE = format(
          'A venda %s já possui uma nota em transmissão do modelo %s.',
          NEW.vendaid,
          NEW.modelo
        ),
        CONSTRAINT = 'nfe_origem_venda_modelo_transmitida_idx';
    END IF;
  END IF;

  IF NEW.ordemservicoid IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended(format('nfe:os:%s:modelo:%s', NEW.ordemservicoid, NEW.modelo), 0)
    );

    IF EXISTS (
      SELECT 1
        FROM public.nfe existente
       WHERE existente.id <> coalesce(NEW.id, -1)
         AND existente.ordemservicoid = NEW.ordemservicoid
         AND existente.modelo = NEW.modelo
         AND existente.is_deleted = false
         AND existente.status IN (
           'ASSINADA', 'ENVIADA', 'PENDENTE_ENVIO',
           'CONTINGENCIA', 'RESULTADO_INCERTO'
         )
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23505',
        MESSAGE = format(
          'A OS %s já possui uma nota em transmissão do modelo %s.',
          NEW.ordemservicoid,
          NEW.modelo
        ),
        CONSTRAINT = 'nfe_origem_os_modelo_transmitida_idx';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: nfe_impedir_saida_transmitida_duplicada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_impedir_saida_transmitida_duplicada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.saidaid IS NULL
     OR coalesce(NEW.is_deleted, false)
     OR NEW.status NOT IN (
       'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
       'CONTINGENCIA', 'RESULTADO_INCERTO'
     ) THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.saidaid IS NOT DISTINCT FROM OLD.saidaid
     AND NEW.modelo IS NOT DISTINCT FROM OLD.modelo
     AND NOT coalesce(OLD.is_deleted, false)
     AND OLD.status IN (
       'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
       'CONTINGENCIA', 'RESULTADO_INCERTO'
     ) THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(format('nfe:saida:%s:modelo:%s', NEW.saidaid, NEW.modelo), 0)
  );

  IF EXISTS (
    SELECT 1
      FROM public.nfe existente
     WHERE existente.id <> coalesce(NEW.id, -1)
       AND existente.saidaid = NEW.saidaid
       AND existente.modelo = NEW.modelo
       AND existente.is_deleted = false
       AND existente.status IN (
         'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
         'CONTINGENCIA', 'RESULTADO_INCERTO'
       )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505',
      MESSAGE = format(
        'A saída %s já possui uma nota transmitida do modelo %s.',
        NEW.saidaid,
        NEW.modelo
      ),
      CONSTRAINT = 'nfe_origem_saida_modelo_ativa_idx';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: nfe_liberar_numero(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_liberar_numero(p_nfe_id bigint, p_motivo text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_nfe public.nfe%ROWTYPE;
  v_config public.nfe_config%ROWTYPE;
BEGIN
  SELECT * INTO v_nfe FROM public.nfe WHERE id = p_nfe_id FOR UPDATE;
  IF NOT FOUND OR NOT v_nfe.numero_definitivo OR v_nfe.numero IS NULL THEN
    RETURN false;
  END IF;

  IF v_nfe.status IN (
    'AUTORIZADA', 'DENEGADA', 'CANCELADA', 'ENVIADA', 'ASSINADA',
    'PENDENTE_ENVIO', 'CONTINGENCIA', 'RESULTADO_INCERTO'
  ) THEN
    RETURN false;
  END IF;

  SELECT * INTO v_config
    FROM public.nfe_config
   WHERE empresaid = v_nfe.empresaid
     AND modelo = v_nfe.modelo
   ORDER BY id
   LIMIT 1
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  UPDATE public.nfe
     SET numero_definitivo = false,
         updatedat = now()
   WHERE id = p_nfe_id;

  INSERT INTO public.nfe_numero_liberado (config_id, serie, numero, motivo)
  VALUES (v_config.id, v_nfe.serie, v_nfe.numero, p_motivo)
  ON CONFLICT ON CONSTRAINT nfe_numero_liberado_unico DO NOTHING;

  RETURN true;
END;
$$;


--
-- Name: FUNCTION nfe_liberar_numero(p_nfe_id bigint, p_motivo text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.nfe_liberar_numero(p_nfe_id bigint, p_motivo text) IS 'Devolve para a fila do proprio modelo o numero de uma nota que nunca chegou a SEFAZ.';


--
-- Name: nfe_origem_vinculo_sincronizar_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_origem_vinculo_sincronizar_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.nfe_origem_vinculo
     SET ativo = public.nfe_status_ocupa_origem(NEW.status::text, NEW.is_deleted),
         updated_at = now()
   WHERE nfe_id = NEW.id;
  RETURN NEW;
END;
$$;


--
-- Name: nfe_origem_vinculo_validar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_origem_vinculo_validar() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_modelo text;
  v_status text;
  v_excluida boolean;
  v_nfe_cliente integer;
  v_nfe_os integer;
  v_nfe_venda integer;
  v_origem_cliente integer;
  v_origem_existe boolean;
  v_ancora_esperada boolean;
BEGIN
  SELECT modelo::text, status::text, coalesce(is_deleted, false), clienteid, ordemservicoid, vendaid
    INTO v_modelo, v_status, v_excluida, v_nfe_cliente, v_nfe_os, v_nfe_venda
    FROM public.nfe
   WHERE id = NEW.nfe_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'O vinculo de origem exige uma NF-e existente.' USING ERRCODE = '23514';
  END IF;

  IF NEW.modelo <> v_modelo THEN
    RAISE EXCEPTION 'O modelo do vinculo difere do modelo da NF-e.' USING ERRCODE = '23514';
  END IF;

  -- Só modelo 55. A NFC-e admite um destinatário diferente do cliente da venda
  -- (o consumidor que se identifica no caixa), então a validação de cliente
  -- abaixo recusaria emissões legítimas.
  IF v_modelo <> 'NFE' THEN
    RAISE EXCEPTION 'Somente NF-e modelo 55 usa vinculo de origem.' USING ERRCODE = '23514';
  END IF;

  IF NEW.tipo = 'OS' THEN
    SELECT clienteid INTO v_origem_cliente
      FROM public.ordemservico WHERE id = NEW.ordemservico_id;
    v_origem_existe := FOUND;
    v_ancora_esperada := v_nfe_os IS NOT DISTINCT FROM NEW.ordemservico_id;
  ELSE
    SELECT clienteid INTO v_origem_cliente
      FROM public.venda WHERE id = NEW.venda_id;
    v_origem_existe := FOUND;
    v_ancora_esperada := v_nfe_venda IS NOT DISTINCT FROM NEW.venda_id;
  END IF;

  IF NOT v_origem_existe THEN
    RAISE EXCEPTION 'A origem informada no vinculo nao existe.' USING ERRCODE = '23514';
  END IF;

  -- A invariante do destinatário único, no banco: uma NF-e só documenta
  -- origens do mesmo cliente que consta na própria nota.
  IF NEW.cliente_id <> v_nfe_cliente THEN
    RAISE EXCEPTION 'O vinculo aponta para um cliente diferente do destinatario da NF-e.'
      USING ERRCODE = '23514';
  END IF;

  IF v_origem_cliente IS DISTINCT FROM v_nfe_cliente THEN
    RAISE EXCEPTION
      'A origem % pertence ao cliente % e a NF-e foi emitida para o cliente %. Uma NF-e tem um unico destinatario.',
      NEW.origem_id, v_origem_cliente, v_nfe_cliente
      USING ERRCODE = '23514';
  END IF;

  -- `ancora` não é escolha de quem grava: é um fato derivado de qual origem
  -- está na coluna escalar da nota.
  NEW.ancora := v_ancora_esperada;
  NEW.ativo := public.nfe_status_ocupa_origem(v_status, v_excluida);
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: nfe_saida_item_vinculo_sincronizar_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_saida_item_vinculo_sincronizar_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.nfe_saida_item_vinculo
     SET ativo = NOT coalesce(NEW.is_deleted, false) AND NEW.status::text IN (
           'RASCUNHO', 'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
           'CONTINGENCIA', 'RESULTADO_INCERTO'
         ),
         updated_at = now()
   WHERE nfe_id = NEW.id;
  RETURN NEW;
END;
$$;


--
-- Name: nfe_saida_item_vinculo_validar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_saida_item_vinculo_validar() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_modelo text;
  v_status text;
  v_excluida boolean;
  v_saida_id bigint;
  v_produto_id integer;
  v_quantidade numeric;
  v_entrada_produto_id integer;
BEGIN
  SELECT modelo::text, status::text, coalesce(is_deleted, false)
    INTO v_modelo, v_status, v_excluida
    FROM public.nfe
   WHERE id = NEW.nfe_id;

  IF NOT FOUND OR v_modelo <> 'NFE' THEN
    RAISE EXCEPTION 'O vínculo de saída exige uma NF-e existente.' USING ERRCODE = '23514';
  END IF;

  SELECT saida_id, produto_id, quantidade
    INTO v_saida_id, v_produto_id, v_quantidade
    FROM public.estoque_saida_item
   WHERE id = NEW.saida_item_id;

  IF NOT FOUND OR v_saida_id <> NEW.saida_id THEN
    RAISE EXCEPTION 'O item não pertence à saída informada.' USING ERRCODE = '23514';
  END IF;

  IF round(NEW.quantidade, 4) <> round(v_quantidade, 4) THEN
    RAISE EXCEPTION 'A quantidade fiscal deve corresponder à baixa da saída.' USING ERRCODE = '23514';
  END IF;

  IF NEW.entrada_item_origem_id IS NOT NULL THEN
    SELECT produto_id
      INTO v_entrada_produto_id
      FROM public.entradaitens
     WHERE id = NEW.entrada_item_origem_id;
    IF NOT FOUND OR v_entrada_produto_id <> v_produto_id THEN
      RAISE EXCEPTION 'A entrada fiscal vinculada pertence a outro produto.' USING ERRCODE = '23514';
    END IF;
  END IF;

  NEW.ativo := NOT v_excluida AND v_status IN (
    'RASCUNHO', 'ASSINADA', 'ENVIADA', 'AUTORIZADA', 'PENDENTE_ENVIO',
    'CONTINGENCIA', 'RESULTADO_INCERTO'
  );
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: nfe_status_ocupa_origem(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfe_status_ocupa_origem(p_status text, p_is_deleted boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT NOT coalesce(p_is_deleted, false)
     AND p_status IN (
       'RASCUNHO', 'ASSINADA', 'ENVIADA', 'PENDENTE_ENVIO',
       'CONTINGENCIA', 'RESULTADO_INCERTO'
     );
$$;


--
-- Name: nfse_os_servico_vinculo_sincronizar_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfse_os_servico_vinculo_sincronizar_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.nfse_os_servico_vinculo
     SET ativo = public.nfse_status_ocupa_servico(NEW.status),
         updated_at = now()
   WHERE nfse_id = NEW.id;
  RETURN NEW;
END;
$$;


--
-- Name: nfse_os_servico_vinculo_validar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfse_os_servico_vinculo_validar() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_nfse_cliente integer;
  v_nfse_os integer;
  v_os_cliente integer;
BEGIN
  SELECT status, clienteid, ordemservicoid
    INTO v_status, v_nfse_cliente, v_nfse_os
    FROM public.nfse
   WHERE id = NEW.nfse_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'O vinculo exige uma NFS-e existente.' USING ERRCODE = '23514';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.osservico
     WHERE ordemservicoid = NEW.ordemservico_id
       AND servicoid = NEW.servico_id
  ) THEN
    RAISE EXCEPTION 'O servico % nao pertence a OS %.', NEW.servico_id, NEW.ordemservico_id
      USING ERRCODE = '23514';
  END IF;

  SELECT clienteid INTO v_os_cliente
    FROM public.ordemservico WHERE id = NEW.ordemservico_id;

  -- Uma NFS-e tem um unico tomador: as OS agrupadas precisam ser do mesmo
  -- cliente da nota.
  IF v_os_cliente IS DISTINCT FROM v_nfse_cliente OR NEW.cliente_id <> v_nfse_cliente THEN
    RAISE EXCEPTION
      'A OS % pertence ao cliente % e a NFS-e foi emitida para o cliente %. Uma NFS-e tem um unico tomador.',
      NEW.ordemservico_id, v_os_cliente, v_nfse_cliente
      USING ERRCODE = '23514';
  END IF;

  NEW.ancora := v_nfse_os IS NOT DISTINCT FROM NEW.ordemservico_id;
  NEW.ativo := public.nfse_status_ocupa_servico(v_status);
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


--
-- Name: nfse_status_ocupa_servico(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.nfse_status_ocupa_servico(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT upper(coalesce(p_status, '')) IN ('PROCESSANDO', 'AUTORIZADA', 'DENEGADA');
$$;


--
-- Name: normalize_placa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_placa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.placa := upper(regexp_replace(new.placa, '[^A-Za-z0-9]', '', 'g'));
  return new;
end;
$$;


--
-- Name: ordens_contagem_por_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ordens_contagem_por_status() RETURNS TABLE(status_os text, total bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.status::text, count(*)::bigint
    FROM public.ordemservico o
   GROUP BY o.status;
$$;


--
-- Name: ordens_realtime_emit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ordens_realtime_emit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_tenant integer;
begin
  select id into v_tenant from public.empresa order by id limit 1;
  if v_tenant is not null then
    perform realtime.send(jsonb_build_object('table', tg_table_name),
      'ordens_changed', 'ordens:tenant:' || v_tenant::text, true);
  end if;
  return null;
exception when others then
  -- Uma indisponibilidade do socket não pode impedir o trabalho na oficina.
  raise warning '[ordens] realtime indisponivel: %', sqlerrm;
  return null;
end;
$$;


--
-- Name: ordens_realtime_topic_allowed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ordens_realtime_topic_allowed(p_topic text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.usuario u
    where u.id = auth.uid() and u.ativo
      and p_topic = 'ordens:tenant:' || (select id from public.empresa order by id limit 1)::text
      and (coalesce(u.is_root, false) or exists (
        select 1 from public.perfilpermissao pp
        join public.permissao p on p.id = pp.permissaoid
        where pp.perfilid = u.perfilid and lower(trim(p.nome)) in
          ('ordens:visualizar', 'execucao_os:visualizar', 'acompanhamento:visualizar', 'financeiro:acompanhamento')
      ))
  );
$$;


--
-- Name: os_do_evento(integer, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.os_do_evento(p_ordemservicoid integer, p_source_type text, p_source_id bigint) RETURNS bigint
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT coalesce(
    p_ordemservicoid::bigint,
    CASE WHEN p_source_type = 'ORDEM_SERVICO' THEN p_source_id END);
$$;


--
-- Name: FUNCTION os_do_evento(p_ordemservicoid integer, p_source_type text, p_source_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.os_do_evento(p_ordemservicoid integer, p_source_type text, p_source_id bigint) IS 'Id da OS que originou o evento, seja pela coluna antiga (ordemservicoid) ou pelo par source_type/source_id. Sem acesso a tabela: e barata o suficiente para entrar em WHERE.';


--
-- Name: produtogrupo; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.produtogrupo (
    id integer NOT NULL,
    nome text NOT NULL,
    descricao text,
    ativo boolean DEFAULT true NOT NULL,
    createdat timestamp without time zone DEFAULT now() NOT NULL,
    updatedat timestamp without time zone DEFAULT now() NOT NULL,
    "exibirPdv" boolean DEFAULT true NOT NULL,
    "exibirSite" boolean DEFAULT true NOT NULL
);


--
-- Name: COLUMN produtogrupo."exibirPdv"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produtogrupo."exibirPdv" IS 'Quando false, oculta todos os produtos do grupo no PDV, independentemente de produto.exibirPdv. Quando true, respeita a flag individual do produto.';


--
-- Name: COLUMN produtogrupo."exibirSite"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produtogrupo."exibirSite" IS 'Quando false, oculta a categoria e todos os produtos do grupo no site, independentemente de site_product_link.status. Quando true, respeita a publicacao individual do produto.';


--
-- Name: pdv_group_search_text(public.produtogrupo); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pdv_group_search_text(g public.produtogrupo) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select public.marketplace_search_normalize(
    g.id::text || ' ' || coalesce(g.nome, '') || ' ' || coalesce(g.descricao, '') || ' ' ||
    g.ativo::text || ' ' || g."exibirPdv"::text
  );
$$;


--
-- Name: produto; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.produto (
    id integer NOT NULL,
    descricao text,
    precovenda numeric NOT NULL,
    estoque integer DEFAULT 0 NOT NULL,
    estoqueminimo integer DEFAULT 0 NOT NULL,
    ncm text,
    unidade public.unidade_medida DEFAULT 'UN'::public.unidade_medida NOT NULL,
    cest text,
    csosn text,
    codigobarras text,
    createdat timestamp with time zone DEFAULT now(),
    updatedat timestamp with time zone DEFAULT now(),
    referencia text,
    titulo text NOT NULL,
    status_estoque public.estoque_status DEFAULT 'OK'::public.estoque_status NOT NULL,
    fabricante text,
    grupo public.grupo_produto DEFAULT 'OUTROS'::public.grupo_produto,
    "exibirPdv" boolean DEFAULT true NOT NULL,
    "tituloMarketplace" text DEFAULT ''::text NOT NULL,
    "descricaoMarketplace" text DEFAULT ''::text NOT NULL,
    "cClassTrib" text,
    "cstIbs" text,
    "cstCbs" text,
    cst text,
    aliquotaicms numeric,
    cfop text,
    cst_pis text,
    aliquota_pis numeric(5,2),
    cst_cofins text,
    aliquota_cofins numeric(5,2),
    "imgUrl" text,
    updated_by uuid,
    created_by uuid,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    grupo_produto_id integer DEFAULT 1 NOT NULL,
    tipo_unidade_id integer DEFAULT 1 NOT NULL,
    precocompra numeric,
    conservacao public.enum_produto_conservacao,
    destaque boolean DEFAULT false,
    etiqueta text,
    local text,
    origem_mercadoria text,
    modo_pis text,
    aliquota_por_unidade_pis numeric,
    modo_cofins text,
    aliquota_por_unidade_cofins numeric,
    rtc_habilitado boolean DEFAULT false NOT NULL,
    cst_ibscbs text,
    cclass_trib text,
    aliquota_ibs_uf numeric,
    aliquota_ibs_municipio numeric,
    aliquota_cbs numeric,
    ultimovalordecompra numeric(14,2),
    em_estoque boolean GENERATED ALWAYS AS ((estoque > 0)) STORED,
    CONSTRAINT produto_cclass_trib_check CHECK (((cclass_trib IS NULL) OR (cclass_trib ~ '^\d{6}$'::text))),
    CONSTRAINT produto_cst_ibscbs_check CHECK (((cst_ibscbs IS NULL) OR (cst_ibscbs ~ '^\d{3}$'::text))),
    CONSTRAINT produto_fiscal_rates_nonnegative_check CHECK (((COALESCE(aliquota_por_unidade_pis, (0)::numeric) >= (0)::numeric) AND (COALESCE(aliquota_por_unidade_cofins, (0)::numeric) >= (0)::numeric) AND (COALESCE(aliquota_ibs_uf, (0)::numeric) >= (0)::numeric) AND (COALESCE(aliquota_ibs_municipio, (0)::numeric) >= (0)::numeric) AND (COALESCE(aliquota_cbs, (0)::numeric) >= (0)::numeric))),
    CONSTRAINT produto_modo_cofins_check CHECK (((modo_cofins IS NULL) OR (modo_cofins = ANY (ARRAY['PERCENTUAL'::text, 'QUANTIDADE'::text, 'NAO_TRIBUTADO'::text])))),
    CONSTRAINT produto_modo_pis_check CHECK (((modo_pis IS NULL) OR (modo_pis = ANY (ARRAY['PERCENTUAL'::text, 'QUANTIDADE'::text, 'NAO_TRIBUTADO'::text])))),
    CONSTRAINT produto_origem_mercadoria_check CHECK (((origem_mercadoria IS NULL) OR (origem_mercadoria ~ '^[0-8]$'::text)))
);


--
-- Name: COLUMN produto."exibirPdv"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produto."exibirPdv" IS 'true: o produto aparece na busca do PDV. Padrao true; false e escolha explicita (ocultado no cadastro, excluido logicamente ou placeholder de integracao).';


--
-- Name: COLUMN produto.origem_mercadoria; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produto.origem_mercadoria IS 'Origem fiscal explícita da mercadoria, código oficial 0 a 8; não inferir pelo fornecedor.';


--
-- Name: COLUMN produto.modo_pis; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produto.modo_pis IS 'Modo padrão de cálculo do PIS para novos itens de NF-e; pode ser sobrescrito no rascunho.';


--
-- Name: COLUMN produto.modo_cofins; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produto.modo_cofins IS 'Modo padrão de cálculo da COFINS para novos itens de NF-e; pode ser sobrescrito no rascunho.';


--
-- Name: COLUMN produto.cclass_trib; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produto.cclass_trib IS 'Classificação IBS/CBS padrão do produto; deve ser revalidada na tabela oficial vigente na emissão.';


--
-- Name: COLUMN produto.ultimovalordecompra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.produto.ultimovalordecompra IS 'Valor unitario da compra mais recente; futuramente atualizado ao confirmar entrada fiscal.';


--
-- Name: pdv_product_search_text(public.produto); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pdv_product_search_text(p public.produto) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO ''
    AS $$
  select public.marketplace_search_normalize(
    coalesce(p.titulo, '') || ' ' || coalesce(p.descricao, '') || ' ' ||
    coalesce(p.referencia, '') || ' ' || coalesce(p.fabricante, '') || ' ' ||
    coalesce(p.codigobarras, '') || ' ' || coalesce(p.etiqueta, '') || ' ' ||
    coalesce(p.local, '') || ' ' || coalesce(p.unidade::text, '') || ' ' ||
    coalesce(p.ncm, '') || ' ' || coalesce(p.cfop, '') || ' ' ||
    coalesce(p.origem_mercadoria::text, '') || ' ' || coalesce(p.csosn, '') || ' ' ||
    coalesce(p.cst, '') || ' ' || coalesce(p.cest, '') || ' ' ||
    coalesce(p.cst_pis, '') || ' ' || coalesce(p.modo_pis::text, '') || ' ' ||
    coalesce(p.cst_cofins, '') || ' ' || coalesce(p.modo_cofins::text, '') || ' ' ||
    coalesce(p.cst_ibscbs, '') || ' ' || coalesce(p.cclass_trib, '') || ' ' ||
    coalesce(p.status_estoque::text, '') || ' ' || coalesce(p.conservacao::text, '') || ' ' ||
    coalesce(p."tituloMarketplace", '') || ' ' || coalesce(p."descricaoMarketplace", '')
  );
$$;


--
-- Name: pdv_product_structured_text(public.produto); Type: FUNCTION; Schema: public; Owner: -
