  select public.marketplace_search_normalize(
    coalesce(p.etiqueta, '') || ' ' || coalesce(p.referencia, '') || ' ' ||
    coalesce(p.codigobarras, '') || ' ' || coalesce(p.ncm, '') || ' ' ||
    coalesce(p.cest, '')
  );
$$;


--
-- Name: pdv_search_products(jsonb, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pdv_search_products(p_tokens jsonb DEFAULT '[]'::jsonb, p_page integer DEFAULT 1, p_limit integer DEFAULT 48, p_group_id integer DEFAULT NULL::integer, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_where text := 'p.is_deleted = false and p."exibirPdv" = true and g."exibirPdv" = true';
  v_token jsonb;
  v_value text;
  v_pattern text;
  v_result jsonb;
begin
  if p_tokens is null or jsonb_typeof(p_tokens) <> 'array'
     or jsonb_array_length(p_tokens) > 20 or p_page is null or p_page < 1
     or p_limit is null or p_limit < 1 or p_limit > 100
     or (p_status is not null and p_status not in ('OK','CRITICO','BAIXO','SEM_ESTOQUE')) then
    raise exception 'Parâmetros de busca inválidos';
  end if;

  if p_group_id is not null then
    v_where := v_where || format(' and p.grupo_produto_id = %L', p_group_id);
  end if;
  if p_status is not null then
    v_where := v_where || format(' and p.status_estoque = %L::public.estoque_status', p_status);
  end if;

  for v_token in select value from jsonb_array_elements(p_tokens) loop
    v_value := public.marketplace_search_normalize(v_token->>'value');
    if v_value is null or length(v_value) > 100 or v_value = '' then
      raise exception 'Termo de busca inválido';
    end if;
    v_pattern := '%' || replace(replace(replace(v_value, '!', '!!'), '%', '!%'), '_', '!_') || '%';
    if coalesce((v_token->>'structured')::boolean, false) then
      v_where := v_where || format(
        ' and public.pdv_product_structured_text(p) like %L escape ''!''', v_pattern
      );
    else
      v_where := v_where || format(
        ' and (p.id::text = %L or public.pdv_product_search_text(p) like %L escape ''!'' or p.grupo_produto_id in (select sg.id from public.produtogrupo sg where sg."exibirPdv" = true and public.pdv_group_search_text(sg) like %L escape ''!''))',
        v_value, v_pattern, v_pattern
      );
    end if;
  end loop;

  execute format($query$
    with matched as materialized (
      select p.id from public.produto p
      join public.produtogrupo g on g.id = p.grupo_produto_id
      where %s
    ), page_rows as (
      select p.id, p.titulo, p.descricao, p.precovenda, p.estoque,
        p.estoqueminimo, p.unidade, p.referencia, p.codigobarras,
        p.ncm, p.cfop, p.fabricante, p.grupo_produto_id,
        jsonb_build_object('id', g.id, 'nome', g.nome, 'descricao', g.descricao,
          'ativo', g.ativo, 'exibirPdv', g."exibirPdv") as grupo,
        p.status_estoque, p."exibirPdv", p."tituloMarketplace",
        p."descricaoMarketplace", p."imgUrl"
      from matched m
      join public.produto p on p.id = m.id
      join public.produtogrupo g on g.id = p.grupo_produto_id
      order by m.id desc
      limit %s offset %s
    )
    select jsonb_build_object(
      'total', (select count(*) from matched),
      'data', coalesce((select jsonb_agg(to_jsonb(r) order by r.id desc) from page_rows r), '[]'::jsonb)
    )
  $query$, v_where, p_limit, (p_page::bigint - 1) * p_limit) into v_result;
  return v_result;
end;
$_$;


--
-- Name: plano_contas_aplicar_lote(integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_aplicar_lote(p_lote_id integer, p_usuario uuid DEFAULT NULL::uuid, p_limite integer DEFAULT 500) RETURNS TABLE(aplicados integer, conflitos integer, erros integer, restantes integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_lote   public.plano_contas_lote%rowtype;
  v_item   record;
  v_versao integer;
  v_atual  integer;
  v_aplicados integer := 0;
  v_conflitos integer := 0;
  v_erros integer := 0;
  v_restantes integer;
BEGIN
  SELECT * INTO v_lote FROM public.plano_contas_lote WHERE id = p_lote_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lote % nao encontrado.', p_lote_id USING ERRCODE = 'P0002';
  END IF;
  IF v_lote.estado = 'CANCELADO' THEN
    RAISE EXCEPTION 'Lote % esta cancelado.', p_lote_id USING ERRCODE = 'PT422';
  END IF;

  FOR v_item IN
    SELECT * FROM public.plano_contas_lote_item
     WHERE lote_id = p_lote_id AND estado = 'PENDENTE'
     ORDER BY id
     LIMIT greatest(coalesce(p_limite, 500), 1)
  LOOP
    IF v_item.entidade = 'GRUPO' THEN
      SELECT versao_registro, classificacao_padrao_id INTO v_versao, v_atual
        FROM public.planosdecontagrupos WHERE id = v_item.entidade_id;
    ELSE
      SELECT versao_registro, classificacao_especifica_id INTO v_versao, v_atual
        FROM public.planosdeconta WHERE id = v_item.entidade_id;
    END IF;

    IF v_versao IS NULL THEN
      UPDATE public.plano_contas_lote_item
         SET estado = 'CONFLITO', motivo = 'Cadastro nao existe mais.'
       WHERE id = v_item.id;
      v_conflitos := v_conflitos + 1;
      CONTINUE;
    END IF;

    IF v_versao <> v_item.versao_esperada THEN
      UPDATE public.plano_contas_lote_item
         SET estado = 'CONFLITO',
             motivo = format('Cadastro alterado depois da simulacao (versao %s, esperada %s).',
                             v_versao, v_item.versao_esperada)
       WHERE id = v_item.id;
      v_conflitos := v_conflitos + 1;
      CONTINUE;
    END IF;

    BEGIN
      IF v_item.entidade = 'GRUPO' THEN
        PERFORM public.plano_contas_salvar_grupo(
          v_item.entidade_id,
          (SELECT codigo FROM public.planosdecontagrupos WHERE id = v_item.entidade_id),
          (SELECT nome FROM public.planosdecontagrupos WHERE id = v_item.entidade_id),
          (SELECT descricao FROM public.planosdecontagrupos WHERE id = v_item.entidade_id),
          NULL, v_item.classificacao_id, v_item.versao_esperada,
          v_lote.vigencia_inicio, p_usuario, v_item.justificativa, 'MIGRACAO');
      ELSE
        PERFORM public.plano_contas_salvar_conta(
          v_item.entidade_id,
          (SELECT codigo FROM public.planosdeconta WHERE id = v_item.entidade_id),
          (SELECT nome FROM public.planosdeconta WHERE id = v_item.entidade_id),
          (SELECT descricao FROM public.planosdeconta WHERE id = v_item.entidade_id),
          NULL,
          (SELECT grupo_id FROM public.planosdeconta WHERE id = v_item.entidade_id),
          v_item.classificacao_id, v_item.versao_esperada,
          v_lote.vigencia_inicio, p_usuario, v_item.justificativa, 'MIGRACAO');
      END IF;

      UPDATE public.plano_contas_lote_item
         SET estado = 'APLICADO',
             classificacao_anterior_id = v_atual,
             aplicado_em = now(),
             motivo = NULL
       WHERE id = v_item.id;
      v_aplicados := v_aplicados + 1;

    EXCEPTION WHEN OTHERS THEN
      -- Uma unidade que falha nao derruba o lote: ela fica marcada com o erro e
      -- as outras seguem. Sem isso, um cadastro estranho impediria a migracao
      -- inteira e ninguem saberia qual era.
      UPDATE public.plano_contas_lote_item
         SET estado = 'ERRO', motivo = left(SQLERRM, 500)
       WHERE id = v_item.id;
      v_erros := v_erros + 1;
    END;
  END LOOP;

  SELECT count(*) INTO v_restantes
    FROM public.plano_contas_lote_item WHERE lote_id = p_lote_id AND estado = 'PENDENTE';

  IF v_restantes = 0 THEN
    UPDATE public.plano_contas_lote
       SET estado = 'APLICADO', aplicado_em = now(), aplicado_por = p_usuario
     WHERE id = p_lote_id;
  END IF;

  RETURN QUERY SELECT v_aplicados, v_conflitos, v_erros, v_restantes;
END;
$$;


--
-- Name: FUNCTION plano_contas_aplicar_lote(p_lote_id integer, p_usuario uuid, p_limite integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.plano_contas_aplicar_lote(p_lote_id integer, p_usuario uuid, p_limite integer) IS 'Aplica o lote por unidades, idempotente e retomavel. Cadastro alterado desde a simulacao vira CONFLITO e nao e sobrescrito. O lote so fica APLICADO quando nao sobra unidade pendente.';


--
-- Name: plano_contas_excecao_compativel(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_excecao_compativel(p_grupo_id integer, p_classificacao_id integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT true;
$$;


--
-- Name: plano_contas_grupos_visao(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_grupos_visao(p_competencia date DEFAULT CURRENT_DATE) RETURNS TABLE(grupo_id integer, codigo text, nome text, descricao text, ativo boolean, origem text, codigo_sistema text, versao integer, classificacao text, classificacao_nome text, familia text, tratamento text, naturezas text[], linha_codigo text, linha_nome text, motivo text, situacao text, contas bigint, contas_ativas bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT g.id, g.codigo, g.nome, g.descricao, g.ativo, g.origem_cadastro, g.codigo_sistema,
         g.versao_registro,
         efetiva.codigo, efetiva.nome, efetiva.familia, efetiva.tratamento, efetiva.naturezas,
         l.codigo, l.nome,
         CASE WHEN d.situacao <> 'CLASSIFICADO' THEN d.motivo END,
         d.situacao,
         (SELECT count(*) FROM public.planosdeconta c WHERE c.grupo_id = g.id),
         (SELECT count(*) FROM public.planosdeconta c WHERE c.grupo_id = g.id AND c.ativo)
    FROM public.planosdecontagrupos g
    LEFT JOIN LATERAL public.dre_destino_do_cadastro(
      NULL, g.id, coalesce(p_competencia, current_date)) d ON true
    LEFT JOIN public.classificacoes_resultado efetiva ON efetiva.id = d.classificacao_id
    LEFT JOIN public.dre_linha l ON l.id = d.linha_id
   ORDER BY g.codigo, g.nome;
$$;


--
-- Name: FUNCTION plano_contas_grupos_visao(p_competencia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.plano_contas_grupos_visao(p_competencia date) IS 'Grupos com classificacao padrao e destino — inclusive o destino pelo mapeamento antigo — e os que ainda nao tem conta nenhuma.';


--
-- Name: plano_contas_inicio_do_historico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_inicio_do_historico() RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT DATE '1900-01-01';
$$;


--
-- Name: plano_contas_instalar_padrao(jsonb, date, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_instalar_padrao(p_definicao jsonb, p_vigencia_inicio date DEFAULT NULL::date, p_apenas_base boolean DEFAULT true, p_usuario uuid DEFAULT NULL::uuid) RETURNS TABLE(entidade text, codigo_sistema text, acao text, detalhe text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_grupo jsonb;
  v_conta jsonb;
  v_classificacao integer;
  v_id integer;
  v_codigo text;
  v_sufixo integer;
  v_vigencia date := coalesce(p_vigencia_inicio, current_date);
BEGIN
  FOR v_grupo IN SELECT * FROM jsonb_array_elements(p_definicao -> 'grupos')
  LOOP
    SELECT g.id INTO v_id FROM public.planosdecontagrupos g
     WHERE g.codigo_sistema = v_grupo ->> 'codigo';

    IF v_id IS NOT NULL THEN
      RETURN QUERY SELECT 'GRUPO'::text, v_grupo ->> 'codigo', 'JA_INSTALADO'::text, NULL::text;
      CONTINUE;
    END IF;

    IF EXISTS (SELECT 1 FROM public.planosdecontagrupos g
                WHERE upper(btrim(g.nome)) = upper(btrim(v_grupo ->> 'nome'))) THEN
      RETURN QUERY SELECT 'GRUPO'::text, v_grupo ->> 'codigo', 'COLISAO_NOME'::text,
        format('Ja existe um grupo chamado "%s". Vincular por nome nao e seguro: revise a mao.',
               v_grupo ->> 'nome');
      CONTINUE;
    END IF;

    SELECT cr.id INTO v_classificacao FROM public.classificacoes_resultado cr
     WHERE cr.codigo = v_grupo ->> 'classificacao';

    -- Codigo visual livre: o sugerido e preferencia, nao exigencia.
    v_codigo := v_grupo ->> 'codigo_sugerido';
    v_sufixo := 0;
    WHILE EXISTS (SELECT 1 FROM public.planosdecontagrupos g
                   WHERE upper(btrim(g.codigo)) = upper(btrim(v_codigo))) LOOP
      v_sufixo := v_sufixo + 1;
      v_codigo := (v_grupo ->> 'codigo_sugerido') || '-' || v_sufixo;
    END LOOP;

    INSERT INTO public.planosdecontagrupos
      (codigo, nome, descricao, ativo, classificacao_padrao_id, origem_cadastro,
       codigo_sistema, createdat, updatedat)
    VALUES (v_codigo, v_grupo ->> 'nome', NULL, true, v_classificacao, 'SISTEMA',
            v_grupo ->> 'codigo', now(), now())
    RETURNING id INTO v_id;

    PERFORM public.plano_contas_registrar_regra(
      v_id, NULL, v_classificacao, v_vigencia, 'SISTEMA', p_usuario,
      'Grupo padrao instalado pelo catalogo.');

    RETURN QUERY SELECT 'GRUPO'::text, v_grupo ->> 'codigo', 'CRIADO'::text, v_codigo;
  END LOOP;

  FOR v_conta IN SELECT * FROM jsonb_array_elements(p_definicao -> 'contas')
  LOOP
    CONTINUE WHEN p_apenas_base AND (v_conta ->> 'instalacao') <> 'BASE';

    IF EXISTS (SELECT 1 FROM public.planosdeconta c WHERE c.codigo_sistema = v_conta ->> 'codigo') THEN
      RETURN QUERY SELECT 'CONTA'::text, v_conta ->> 'codigo', 'JA_INSTALADA'::text, NULL::text;
      CONTINUE;
    END IF;

    SELECT g.id INTO v_id FROM public.planosdecontagrupos g
     WHERE g.codigo_sistema = v_conta ->> 'grupo';
    IF v_id IS NULL THEN
      RETURN QUERY SELECT 'CONTA'::text, v_conta ->> 'codigo', 'SEM_GRUPO'::text,
        format('O grupo padrao %s nao foi instalado.', v_conta ->> 'grupo');
      CONTINUE;
    END IF;

    IF EXISTS (SELECT 1 FROM public.planosdeconta c
                WHERE c.grupo_id = v_id
                  AND upper(btrim(c.nome)) = upper(btrim(v_conta ->> 'nome'))) THEN
      RETURN QUERY SELECT 'CONTA'::text, v_conta ->> 'codigo', 'COLISAO_NOME'::text,
        format('Ja existe "%s" neste grupo.', v_conta ->> 'nome');
      CONTINUE;
    END IF;

    SELECT cr.id INTO v_classificacao FROM public.classificacoes_resultado cr
     WHERE cr.codigo = v_conta ->> 'classificacao';

    v_codigo := (SELECT g.codigo FROM public.planosdecontagrupos g WHERE g.id = v_id);
    v_sufixo := 0;
    LOOP
      v_sufixo := v_sufixo + 1;
      EXIT WHEN NOT EXISTS (
        SELECT 1 FROM public.planosdeconta c
         WHERE upper(btrim(c.codigo)) = upper(btrim(v_codigo || '.' || v_sufixo)));
    END LOOP;

    INSERT INTO public.planosdeconta
      (codigo, nome, descricao, ativo, grupo_id, classificacao_especifica_id,
       origem_cadastro, codigo_sistema, createdat, updatedat)
    VALUES (v_codigo || '.' || v_sufixo, v_conta ->> 'nome', NULL, true, v_id,
            v_classificacao, 'SISTEMA', v_conta ->> 'codigo', now(), now());

    RETURN QUERY SELECT 'CONTA'::text, v_conta ->> 'codigo', 'CRIADA'::text,
      v_codigo || '.' || v_sufixo;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION plano_contas_instalar_padrao(p_definicao jsonb, p_vigencia_inicio date, p_apenas_base boolean, p_usuario uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.plano_contas_instalar_padrao(p_definicao jsonb, p_vigencia_inicio date, p_apenas_base boolean, p_usuario uuid) IS 'Instala grupos e contas do catalogo. Idempotente por codigo_sistema. Nunca vincula por nome: colisao vira aviso para revisao humana.';


--
-- Name: plano_contas_refazer_lancamentos(integer, integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_refazer_lancamentos(p_conta_id integer, p_grupo_id integer, p_desde date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id    bigint;
  v_total integer := 0;
BEGIN
  IF p_conta_id IS NULL AND p_grupo_id IS NULL THEN
    RAISE EXCEPTION 'Informe a conta ou o grupo cujos lancamentos serao refeitos.' USING ERRCODE = '22023';
  END IF;

  FOR v_id IN
    SELECT t.id
      FROM public.transacao t
      JOIN public.planosdeconta c ON c.id = t.plano_de_conta_id
     WHERE (p_conta_id IS NULL OR c.id = p_conta_id)
       AND (p_grupo_id IS NULL OR c.grupo_id = p_grupo_id)
       AND (p_desde IS NULL OR coalesce(t.competencia_em, t.data)::date >= p_desde)
     ORDER BY t.id
  LOOP
    PERFORM public.sincronizar_eventos_financeiros_transacao(v_id);
    v_total := v_total + 1;
  END LOOP;

  RETURN v_total;
END;
$$;


--
-- Name: plano_contas_registrar_regra(integer, integer, integer, date, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_registrar_regra(p_grupo_id integer, p_conta_id integer, p_classificacao_id integer, p_vigencia_inicio date, p_origem text, p_usuario uuid, p_justificativa text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_versao   integer;
  v_id       integer;
  v_conflito date;
  v_inicio   date;
BEGIN
  IF num_nonnulls(p_grupo_id, p_conta_id) <> 1 THEN
    RAISE EXCEPTION 'A regra e de um grupo OU de uma conta.' USING ERRCODE = '22023';
  END IF;

  IF p_vigencia_inicio IS NULL THEN
    DELETE FROM public.plano_contas_classificacao_regra
     WHERE grupo_id IS NOT DISTINCT FROM p_grupo_id
       AND conta_id IS NOT DISTINCT FROM p_conta_id;
    v_inicio := public.plano_contas_inicio_do_historico();
  ELSE
    v_inicio := p_vigencia_inicio;

    SELECT max(vigencia_inicio) INTO v_conflito
      FROM public.plano_contas_classificacao_regra r
     WHERE r.grupo_id IS NOT DISTINCT FROM p_grupo_id
       AND r.conta_id IS NOT DISTINCT FROM p_conta_id
       AND r.vigencia_inicio > v_inicio;

    IF v_conflito IS NOT NULL THEN
      RAISE EXCEPTION
        'Ja existe regra a partir de % para este cadastro: uma vigencia nova nao pode comecar antes dela. Para corrigir o passado, grave sem data (todo o historico).',
        v_conflito
        USING ERRCODE = 'PT422';
    END IF;

    UPDATE public.plano_contas_classificacao_regra
       SET vigencia_fim = v_inicio
     WHERE grupo_id IS NOT DISTINCT FROM p_grupo_id
       AND conta_id IS NOT DISTINCT FROM p_conta_id
       AND vigencia_fim IS NULL
       AND vigencia_inicio < v_inicio;

    -- Regra que comecaria no mesmo dia da anterior substitui a anterior: duas
    -- regras iniciando na mesma data nao tem ordem definida.
    DELETE FROM public.plano_contas_classificacao_regra
     WHERE grupo_id IS NOT DISTINCT FROM p_grupo_id
       AND conta_id IS NOT DISTINCT FROM p_conta_id
       AND vigencia_inicio = v_inicio;
  END IF;

  IF p_classificacao_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT max(versao_catalogo) INTO v_versao FROM public.classificacoes_resultado;

  INSERT INTO public.plano_contas_classificacao_regra
    (grupo_id, conta_id, classificacao_id, origem_regra, vigencia_inicio,
     versao_catalogo, justificativa, created_by)
  VALUES (p_grupo_id, p_conta_id, p_classificacao_id, coalesce(p_origem, 'MANUAL'),
          v_inicio, coalesce(v_versao, 1), p_justificativa, p_usuario)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: plano_contas_salvar_conta(integer, text, text, text, boolean, integer, integer, integer, date, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_salvar_conta(p_id integer, p_codigo text, p_nome text, p_descricao text, p_ativo boolean, p_grupo_id integer, p_classificacao_id integer, p_versao_esperada integer DEFAULT NULL::integer, p_vigencia_inicio date DEFAULT NULL::date, p_usuario uuid DEFAULT NULL::uuid, p_justificativa text DEFAULT NULL::text, p_origem_regra text DEFAULT 'MANUAL'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_atual       public.planosdeconta%rowtype;
  v_id          integer;
  v_grupo_ativo boolean;
BEGIN
  IF nullif(btrim(coalesce(p_nome, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Nome da conta e obrigatorio.' USING ERRCODE = '22023';
  END IF;

  SELECT ativo INTO v_grupo_ativo FROM public.planosdecontagrupos WHERE id = p_grupo_id;
  IF v_grupo_ativo IS NULL THEN
    RAISE EXCEPTION 'Grupo de plano de conta nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.planosdeconta
      (codigo, nome, descricao, ativo, grupo_id, classificacao_especifica_id,
       origem_cadastro, createdat, updatedat)
    VALUES (nullif(btrim(coalesce(p_codigo, '')), ''), btrim(p_nome),
            nullif(btrim(coalesce(p_descricao, '')), ''), coalesce(p_ativo, true),
            p_grupo_id, p_classificacao_id, 'PERSONALIZADO', now(), now())
    RETURNING id INTO v_id;

    IF p_classificacao_id IS NOT NULL THEN
      PERFORM public.plano_contas_registrar_regra(
        NULL, v_id, p_classificacao_id, p_vigencia_inicio, p_origem_regra, p_usuario, p_justificativa);
    END IF;

    RETURN to_jsonb((SELECT c FROM public.planosdeconta c WHERE c.id = v_id));
  END IF;

  SELECT * INTO v_atual FROM public.planosdeconta WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conta nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF p_versao_esperada IS NOT NULL AND v_atual.versao_registro <> p_versao_esperada THEN
    RAISE EXCEPTION
      'A conta foi alterada por outra pessoa (versao % em vez de %). Recarregue antes de salvar.',
      v_atual.versao_registro, p_versao_esperada
      USING ERRCODE = 'PT409';
  END IF;

  -- Conta do sistema mantem a chave e a finalidade; nome e codigo continuam
  -- editaveis, porque sao apresentacao.
  IF v_atual.origem_cadastro = 'SISTEMA'
     AND (p_grupo_id IS DISTINCT FROM v_atual.grupo_id
          OR p_classificacao_id IS DISTINCT FROM v_atual.classificacao_especifica_id) THEN
    RAISE EXCEPTION
      'Conta padrao do sistema nao muda de grupo nem de classificacao.'
      USING ERRCODE = 'PT422';
  END IF;

  UPDATE public.planosdeconta
     SET codigo = nullif(btrim(coalesce(p_codigo, '')), ''),
         nome = btrim(p_nome),
         descricao = nullif(btrim(coalesce(p_descricao, '')), ''),
         ativo = coalesce(p_ativo, ativo),
         grupo_id = p_grupo_id,
         classificacao_especifica_id = p_classificacao_id,
         versao_registro = versao_registro + 1,
         updatedat = now()
   WHERE id = p_id;

  -- Editar nome ou codigo nao reclassifica nada: so a mudanca de classificacao
  -- ou de grupo abre regra nova e refaz os lancamentos.
  IF p_classificacao_id IS DISTINCT FROM v_atual.classificacao_especifica_id
     OR p_grupo_id IS DISTINCT FROM v_atual.grupo_id THEN
    PERFORM public.plano_contas_registrar_regra(
      NULL, p_id, p_classificacao_id, p_vigencia_inicio, p_origem_regra, p_usuario, p_justificativa);
    PERFORM public.plano_contas_refazer_lancamentos(p_id, NULL, p_vigencia_inicio);
  END IF;

  RETURN to_jsonb((SELECT c FROM public.planosdeconta c WHERE c.id = p_id));
END;
$$;


--
-- Name: FUNCTION plano_contas_salvar_conta(p_id integer, p_codigo text, p_nome text, p_descricao text, p_ativo boolean, p_grupo_id integer, p_classificacao_id integer, p_versao_esperada integer, p_vigencia_inicio date, p_usuario uuid, p_justificativa text, p_origem_regra text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.plano_contas_salvar_conta(p_id integer, p_codigo text, p_nome text, p_descricao text, p_ativo boolean, p_grupo_id integer, p_classificacao_id integer, p_versao_esperada integer, p_vigencia_inicio date, p_usuario uuid, p_justificativa text, p_origem_regra text) IS 'Salva conta, classificacao e regra de vigencia numa transacao, e refaz os lancamentos da conta. Vigencia em branco = historico inteiro. Editar nome ou codigo nao abre regra nova.';


--
-- Name: plano_contas_salvar_grupo(integer, text, text, text, boolean, integer, integer, date, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_salvar_grupo(p_id integer, p_codigo text, p_nome text, p_descricao text, p_ativo boolean, p_classificacao_id integer, p_versao_esperada integer DEFAULT NULL::integer, p_vigencia_inicio date DEFAULT NULL::date, p_usuario uuid DEFAULT NULL::uuid, p_justificativa text DEFAULT NULL::text, p_origem_regra text DEFAULT 'MANUAL'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_atual   public.planosdecontagrupos%rowtype;
  v_id      integer;
  v_ativas  integer;
BEGIN
  IF nullif(btrim(coalesce(p_codigo, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Codigo do grupo e obrigatorio.' USING ERRCODE = '22023';
  END IF;
  IF nullif(btrim(coalesce(p_nome, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Nome do grupo e obrigatorio.' USING ERRCODE = '22023';
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO public.planosdecontagrupos
      (codigo, nome, descricao, ativo, classificacao_padrao_id, origem_cadastro, createdat, updatedat)
    VALUES (btrim(p_codigo), btrim(p_nome), nullif(btrim(coalesce(p_descricao, '')), ''),
            coalesce(p_ativo, true), p_classificacao_id, 'PERSONALIZADO', now(), now())
    RETURNING id INTO v_id;

    PERFORM public.plano_contas_registrar_regra(
      v_id, NULL, p_classificacao_id, p_vigencia_inicio, p_origem_regra, p_usuario, p_justificativa);

    RETURN to_jsonb((SELECT g FROM public.planosdecontagrupos g WHERE g.id = v_id));
  END IF;

  SELECT * INTO v_atual FROM public.planosdecontagrupos WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Grupo nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF p_versao_esperada IS NOT NULL AND v_atual.versao_registro <> p_versao_esperada THEN
    RAISE EXCEPTION
      'O grupo foi alterado por outra pessoa (versao % em vez de %). Recarregue antes de salvar.',
      v_atual.versao_registro, p_versao_esperada
      USING ERRCODE = 'PT409';
  END IF;

  -- Grupo do sistema tem significado protegido: nome local e apresentacao, a
  -- finalidade nao muda sem uma versao nova do catalogo.
  IF v_atual.origem_cadastro = 'SISTEMA'
     AND p_classificacao_id IS DISTINCT FROM v_atual.classificacao_padrao_id THEN
    RAISE EXCEPTION
      'Grupo padrao do sistema nao muda de finalidade. Crie um grupo proprio para outra classificacao.'
      USING ERRCODE = 'PT422';
  END IF;

  -- Inativar grupo com conta ativa deixaria as contas sem destino sem que
  -- ninguem tivesse decidido nada sobre elas.
  IF coalesce(p_ativo, v_atual.ativo) = false AND v_atual.ativo THEN
    SELECT count(*) INTO v_ativas
      FROM public.planosdeconta c WHERE c.grupo_id = p_id AND c.ativo;
    IF v_ativas > 0 THEN
      RAISE EXCEPTION
        'O grupo tem % conta(s) ativa(s). Inative ou mova as contas antes de inativar o grupo.', v_ativas
        USING ERRCODE = 'PT422';
    END IF;
  END IF;

  UPDATE public.planosdecontagrupos
     SET codigo = btrim(p_codigo),
         nome = btrim(p_nome),
         descricao = nullif(btrim(coalesce(p_descricao, '')), ''),
         ativo = coalesce(p_ativo, ativo),
         classificacao_padrao_id = p_classificacao_id,
         versao_registro = versao_registro + 1,
         updatedat = now()
   WHERE id = p_id;

  IF p_classificacao_id IS DISTINCT FROM v_atual.classificacao_padrao_id THEN
    PERFORM public.plano_contas_registrar_regra(
      p_id, NULL, p_classificacao_id, p_vigencia_inicio, p_origem_regra, p_usuario, p_justificativa);
    PERFORM public.plano_contas_refazer_lancamentos(NULL, p_id, p_vigencia_inicio);
  END IF;

  RETURN to_jsonb((SELECT g FROM public.planosdecontagrupos g WHERE g.id = p_id));
END;
$$;


--
-- Name: FUNCTION plano_contas_salvar_grupo(p_id integer, p_codigo text, p_nome text, p_descricao text, p_ativo boolean, p_classificacao_id integer, p_versao_esperada integer, p_vigencia_inicio date, p_usuario uuid, p_justificativa text, p_origem_regra text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.plano_contas_salvar_grupo(p_id integer, p_codigo text, p_nome text, p_descricao text, p_ativo boolean, p_classificacao_id integer, p_versao_esperada integer, p_vigencia_inicio date, p_usuario uuid, p_justificativa text, p_origem_regra text) IS 'Salva grupo, classificacao padrao e regra de vigencia numa transacao, e refaz os lancamentos das contas do grupo. Vigencia em branco = historico inteiro. Concorrencia otimista por versao_registro (PT409).';


--
-- Name: plano_contas_uso_da_conta(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_uso_da_conta(p_conta_id integer) RETURNS TABLE(transacoes bigint, eventos bigint, primeira date, ultima date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)::bigint,
         count(*) FILTER (WHERE EXISTS (
           SELECT 1 FROM public.eventos_financeiros e
            WHERE e.source_type = 'TRANSACAO' AND e.source_id = t.id
              AND e.status IN ('ATIVO', 'CONVERTIDO')))::bigint,
         min(t.competencia_em)::date,
         max(t.competencia_em)::date
    FROM public.transacao t
   WHERE t.plano_de_conta_id = p_conta_id;
$$;


--
-- Name: plano_contas_visao(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plano_contas_visao(p_competencia date DEFAULT CURRENT_DATE) RETURNS TABLE(conta_id integer, conta_codigo text, conta_nome text, conta_descricao text, conta_ativo boolean, conta_origem text, conta_codigo_sistema text, conta_versao integer, grupo_id integer, grupo_codigo text, grupo_nome text, grupo_ativo boolean, grupo_origem text, grupo_codigo_sistema text, grupo_versao integer, classificacao_especifica text, classificacao text, classificacao_nome text, classificacao_origem text, familia text, tratamento text, naturezas text[], linha_codigo text, linha_nome text, motivo text, situacao text, transacoes bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT c.id, c.codigo, c.nome, c.descricao, c.ativo, c.origem_cadastro, c.codigo_sistema,
         c.versao_registro,
         g.id, g.codigo, g.nome, g.ativo, g.origem_cadastro, g.codigo_sistema, g.versao_registro,
         excecao.codigo, efetiva.codigo, efetiva.nome, d.origem, efetiva.familia, efetiva.tratamento,
         efetiva.naturezas,
         l.codigo, l.nome,
         CASE WHEN d.situacao <> 'CLASSIFICADO' THEN d.motivo END,
         d.situacao,
         (SELECT count(*) FROM public.transacao tr WHERE tr.plano_de_conta_id = c.id)
    FROM public.planosdeconta c
    JOIN public.planosdecontagrupos g ON g.id = c.grupo_id
    LEFT JOIN public.classificacoes_resultado excecao ON excecao.id = c.classificacao_especifica_id
    LEFT JOIN LATERAL public.dre_destino_do_cadastro(
      c.id, g.id, coalesce(p_competencia, current_date)) d ON true
    LEFT JOIN public.classificacoes_resultado efetiva ON efetiva.id = d.classificacao_id
    LEFT JOIN public.dre_linha l ON l.id = d.linha_id
   ORDER BY g.codigo, c.codigo NULLS LAST, c.nome;
$$;


--
-- Name: FUNCTION plano_contas_visao(p_competencia date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.plano_contas_visao(p_competencia date) IS 'Contas com origem, classificacao herdada ou de excecao, destino na DRE e motivo, resolvidos por dre_destino_do_cadastro — a mesma regra da sincronizacao.';


--
-- Name: preencher_itens_nfe_de_os(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preencher_itens_nfe_de_os(p_nfe_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_nfe record;
begin
  --------------------------------------------------------------------
  -- 1) Verifica se a NF-e existe e está vinculada a uma OS
  --------------------------------------------------------------------
  select *
    into v_nfe
  from nfe
  where id = p_nfe_id;

  if not found then
    raise exception 'NF-e % não encontrada na tabela nfe', p_nfe_id;
  end if;

  if v_nfe.ordemservicoid is null then
    raise exception
      'NF-e % não está vinculada a uma ordem de serviço (ordemservicoid nulo).',
      p_nfe_id;
  end if;

  --------------------------------------------------------------------
  -- 2) Remove itens anteriores da NF-e (se houver) para recriar do zero
  --------------------------------------------------------------------
  delete from nfe_item
  where nfe_id = p_nfe_id;

  --------------------------------------------------------------------
  -- 3) Insere itens da OS (osproduto) na nfe_item,
  --    herdando ICMS, PIS e COFINS do produto.
  --------------------------------------------------------------------
  insert into nfe_item (
    nfe_id,
    n_item,
    produtoid,
    descricao,
    ncm,
    cfop,
    csosn,
    cest,
    unidade,
    quantidade,
    valor_unitario,
    valor_total,
    valor_desconto,
    aliquotaicms,
    valor_bc_icms,
    valor_icms,
    cst_pis,
    aliquota_pis,
    valor_pis,
    cst_cofins,
    aliquota_cofins,
    valor_cofins,
    cst
  )
  select
    n.id as nfe_id,
    row_number() over (order by op.produtoid) as n_item,

    -- identificação do produto
    p.id as produtoid,
    coalesce(p.titulo, p.descricao) as descricao,
    p.ncm,
    coalesce(p.cfop, '5102') as cfop,
    p.csosn,
    p.cest,
    p.unidade,

    -- quantidade e valores
    op.quantidade::numeric(14,4)      as quantidade,
    op.precounitario::numeric(14,10)  as valor_unitario,
    op.subtotal::numeric(14,2)        as valor_total,
    0::numeric(14,2)                  as valor_desconto,

    -- ICMS
    p.aliquotaicms,
    op.subtotal::numeric(14,2) as valor_bc_icms,
    (
      op.subtotal
      * coalesce(p.aliquotaicms, 0) / 100
    )::numeric(14,2) as valor_icms,

    -- PIS (herdado do produto; default para 07/0,00 se não preenchido)
    coalesce(p.cst_pis, '07')                       as cst_pis,
    coalesce(p.aliquota_pis, 0)::numeric(5,2)       as aliquota_pis,
    0::numeric(14,2)                                as valor_pis,   -- se quiser, pode calcular depois

    -- COFINS (herdado do produto; default para 07/0,00 se não preenchido)
    coalesce(p.cst_cofins, '07')                    as cst_cofins,
    coalesce(p.aliquota_cofins, 0)::numeric(5,2)    as aliquota_cofins,
    0::numeric(14,2)                                as valor_cofins, -- idem

    -- CST genérico de ICMS (espelho do produto)
    p.cst
  from nfe n
  join ordemservico os on os.id = n.ordemservicoid
  join osproduto op on op.ordemservicoid = os.id
  join produto p on p.id = op.produtoid
  where n.id = p_nfe_id;

  --------------------------------------------------------------------
  -- 4) Opcional: se quiser garantir pelo menos 1 item, pode validar aqui
  --------------------------------------------------------------------
  if not exists (select 1 from nfe_item where nfe_id = p_nfe_id) then
    raise exception
      'Nenhum item foi gerado em nfe_item para a NF-e % (ordemservicoid=%).',
      p_nfe_id, v_nfe.ordemservicoid;
  end if;

end;
$$;


--
-- Name: preencher_itens_nfe_de_venda(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preencher_itens_nfe_de_venda(p_nfe_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_nfe record;
begin
  -- 1) Verifica NFE e vínculo com venda
  select * into v_nfe
  from public.nfe
  where id = p_nfe_id;

  if not found then
    raise exception 'NF-e % não encontrada na tabela nfe', p_nfe_id;
  end if;

  if v_nfe.vendaid is null then
    raise exception 'NF-e % não está vinculada a uma venda (vendaid nulo).', p_nfe_id;
  end if;

  -- 2) Remove itens anteriores
  delete from public.nfe_item
  where nfe_id = p_nfe_id;

  -- 3) Insere itens da VENDA (vendaproduto) na nfe_item
  insert into public.nfe_item (
    nfe_id,
    n_item,
    produtoid,
    descricao,
    ncm,
    cfop,
    csosn,
    cest,
    unidade,
    quantidade,
    valor_unitario,
    valor_total,
    valor_desconto,
    aliquotaicms,
    valor_bc_icms,
    valor_icms,
    cst_pis,
    aliquota_pis,
    valor_pis,
    cst_cofins,
    aliquota_cofins,
    valor_cofins,
    cst
  )
  select
    n.id as nfe_id,
    row_number() over (order by vp.id) as n_item,

    p.id as produtoid,
    coalesce(p.titulo, p.descricao) as descricao,
    p.ncm,
    coalesce(p.cfop, '5102') as cfop,
    p.csosn,
    p.cest,
    p.unidade,

    vp.quantidade::numeric(14,4) as quantidade,

    case
      when vp.quantidade::numeric > 0 then
        (vp.valor_total::numeric / vp.quantidade::numeric)::numeric(14,10)
      else
        vp.valor_total::numeric::numeric(14,10)
    end as valor_unitario,

    vp.valor_total::numeric(14,2) as valor_total,
    coalesce(vp.valor_desconto, 0)::numeric(14,2) as valor_desconto,

    -- ICMS
    p.aliquotaicms,
    vp.valor_total::numeric(14,2) as valor_bc_icms,
    (
      vp.valor_total::numeric
      * coalesce(p.aliquotaicms, 0) / 100
    )::numeric(14,2) as valor_icms,

    -- PIS
    coalesce(p.cst_pis, '07') as cst_pis,
    coalesce(p.aliquota_pis, 0)::numeric(5,2) as aliquota_pis,
    0::numeric(14,2) as valor_pis,

    -- COFINS
    coalesce(p.cst_cofins, '07') as cst_cofins,
    coalesce(p.aliquota_cofins, 0)::numeric(5,2) as aliquota_cofins,
    0::numeric(14,2) as valor_cofins,

    -- CST genérico
    p.cst
  from public.nfe n
  join public.venda v on v.id = n.vendaid
  join public.vendaproduto vp on vp.venda_id = v.id
  join public.produto p on p.id = vp.produtoid
  where n.id = p_nfe_id;

  if not exists (select 1 from public.nfe_item where nfe_id = p_nfe_id) then
    raise exception 'Nenhum item foi gerado em nfe_item para a NF-e % (vendaid=%).',
      p_nfe_id, v_nfe.vendaid;
  end if;
end;
$$;


--
-- Name: preparar_venda_para_aprovacao(integer, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preparar_venda_para_aprovacao(p_venda_id integer, p_novo_token uuid, p_expira_em timestamp with time zone, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_aprovacao public.vendaaprovacao%ROWTYPE;
  v_documento text;
  v_reutilizado boolean := false;
BEGIN
  SELECT * INTO v_venda
    FROM public.venda
   WHERE id = p_venda_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_venda.status::text NOT IN ('ORCAMENTO', 'APROVACAO_ORCAMENTO', 'ORCAMENTO_RECUSADO') THEN
    RAISE EXCEPTION 'Esta venda não pode ser enviada para aprovação no status atual.'
      USING ERRCODE = '22023';
  END IF;

  SELECT regexp_replace(coalesce(c.cpfcnpj, ''), '\D', '', 'g')
    INTO v_documento
    FROM public.cliente c
   WHERE c.id = v_venda.clienteid;
  IF coalesce(v_documento, '') = '' THEN
    RAISE EXCEPTION 'O cliente precisa possuir CPF/CNPJ para receber o link de aprovação.'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_aprovacao
    FROM public.vendaaprovacao
   WHERE vendaid = p_venda_id
     AND usado_em IS NULL
     AND invalidado_em IS NULL
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND
     AND v_venda.status::text = 'APROVACAO_ORCAMENTO'
     AND v_venda.statusaprovacao::text = 'PENDENTE'
     AND v_aprovacao.expira_em > now() THEN
    v_reutilizado := true;
  ELSE
    IF v_aprovacao.id IS NOT NULL THEN
      UPDATE public.vendaaprovacao
         SET invalidado_em = now(),
             motivo_invalidacao = CASE
               WHEN v_aprovacao.expira_em <= now() THEN 'EXPIRADO'
               ELSE 'NOVO_ENVIO'
             END
       WHERE id = v_aprovacao.id;
    END IF;

    UPDATE public.venda
       SET status = 'APROVACAO_ORCAMENTO',
           statusaprovacao = 'PENDENTE',
           updated_by = coalesce(p_usuario_id, updated_by),
           updatedat = now()
     WHERE id = p_venda_id;

    INSERT INTO public.vendaaprovacao (
      vendaid, token, expira_em, created_by
    ) VALUES (
      p_venda_id, p_novo_token, p_expira_em, p_usuario_id
    )
    RETURNING * INTO v_aprovacao;
  END IF;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'APROVACAO_ORCAMENTO',
    'statusaprovacao', 'PENDENTE',
    'token', v_aprovacao.token,
    'expiraEm', v_aprovacao.expira_em,
    'reutilizado', v_reutilizado
  );
END;
$$;


--
-- Name: processar_devolucao_mercadolivre_estoque(integer, uuid, text, integer, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.processar_devolucao_mercadolivre_estoque(p_empresa_id integer, p_request_key uuid, p_ml_claim_id text, p_produto_id integer, p_disposition text, p_quantity integer, p_note text DEFAULT NULL::text, p_processed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_claim public.mercadolivre_claim%rowtype;
  v_order public.mercadolivre_order%rowtype;
  v_existing public.mercadolivre_return_inventory%rowtype;
  v_sold_quantity integer;
  v_processed_quantity integer := 0;
  v_deducted_quantity integer := 0;
  v_restored_quantity integer := 0;
  v_stock_before integer;
  v_stock_after integer;
  v_disposition text := upper(btrim(coalesce(p_disposition, '')));
begin
  if p_empresa_id is null or p_request_key is null or p_ml_claim_id is null or btrim(p_ml_claim_id) = '' or p_produto_id is null then
    raise exception 'Empresa, operação, reclamação e produto são obrigatórios.' using errcode = '22023';
  end if;
  if v_disposition not in ('RESTOCK', 'DAMAGED', 'NOT_RETURNED') then
    raise exception 'Destinação da devolução inválida.' using errcode = '22023';
  end if;
  if v_disposition in ('DAMAGED', 'NOT_RETURNED') and nullif(btrim(coalesce(p_note, '')), '') is null then
    raise exception 'Informe uma observação para itens avariados ou não retornados.' using errcode = '22023';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'A quantidade conferida deve ser maior que zero.' using errcode = '22023';
  end if;

  select * into v_claim
    from public.mercadolivre_claim
   where empresa_id = p_empresa_id
     and ml_claim_id = btrim(p_ml_claim_id)
   for update;
  if not found then
    raise exception 'Devolução do Mercado Livre não encontrada.' using errcode = 'P0002';
  end if;
  if v_claim.return_id is null then
    raise exception 'A reclamação ainda não possui uma devolução identificada pelo Mercado Livre.' using errcode = '22023';
  end if;

  select * into v_order
    from public.mercadolivre_order
   where id = v_claim.order_id
     and empresa_id = p_empresa_id;
  if not found or v_order.venda_id is null then
    raise exception 'A devolução não possui uma venda vinculada no ERP.' using errcode = 'P0002';
  end if;

  select * into v_existing
    from public.mercadolivre_return_inventory
   where request_key = p_request_key;
  if found then
    return jsonb_build_object(
      'id', v_existing.id,
      'alreadyProcessed', true,
      'disposition', v_existing.disposition,
      'quantity', v_existing.quantity,
      'restoredQuantity', v_existing.restored_quantity,
      'stockBefore', v_existing.stock_before,
      'stockAfter', v_existing.stock_after,
      'processedAt', v_existing.processed_at
    );
  end if;

  select coalesce(sum(quantidade), 0)::integer into v_sold_quantity
    from public.vendaproduto
   where venda_id = v_order.venda_id
     and produtoid = p_produto_id;
  if v_sold_quantity <= 0 then
    raise exception 'O produto informado não pertence à venda desta devolução.' using errcode = '22023';
  end if;
  if p_quantity > v_sold_quantity then
    raise exception 'A quantidade devolvida não pode superar a quantidade vendida (%).', v_sold_quantity using errcode = '22023';
  end if;

  select coalesce(sum(quantity), 0)::integer into v_processed_quantity
    from public.mercadolivre_return_inventory
   where claim_id = v_claim.id
     and produto_id = p_produto_id;
  if p_quantity > v_sold_quantity - v_processed_quantity then
    raise exception 'A quantidade informada supera o saldo pendente de conferência (%).', greatest(v_sold_quantity - v_processed_quantity, 0)
      using errcode = '22023';
  end if;

  select estoque into v_stock_before
    from public.produto
   where id = p_produto_id
   for update;
  if not found then
    raise exception 'Produto não encontrado no estoque.' using errcode = 'P0002';
  end if;

  select coalesce(quantidade, 0)::integer into v_deducted_quantity
    from public.vendaproduto_baixa
   where venda_id = v_order.venda_id
     and produtoid = p_produto_id;
  v_deducted_quantity := coalesce(v_deducted_quantity, 0);

  if v_disposition = 'RESTOCK' then
    v_restored_quantity := least(p_quantity, v_deducted_quantity);
    if v_restored_quantity > 0 then
      perform public.fn_sincronizar_baixa_estoque_marketplace(
        v_order.venda_id,
        p_produto_id,
        v_deducted_quantity - v_restored_quantity
      );
    end if;
  end if;

  select estoque into v_stock_after from public.produto where id = p_produto_id;

  insert into public.mercadolivre_return_inventory (
    empresa_id, request_key, claim_id, order_id, venda_id, produto_id, disposition,
    quantity, restored_quantity, stock_before, stock_after, note, processed_by
  ) values (
    p_empresa_id, p_request_key, v_claim.id, v_order.id, v_order.venda_id, p_produto_id, v_disposition,
    p_quantity, v_restored_quantity, v_stock_before, v_stock_after,
    nullif(btrim(coalesce(p_note, '')), ''), p_processed_by
  ) returning * into v_existing;

  return jsonb_build_object(
    'id', v_existing.id,
    'alreadyProcessed', false,
    'disposition', v_existing.disposition,
    'quantity', v_existing.quantity,
    'restoredQuantity', v_existing.restored_quantity,
    'stockBefore', v_existing.stock_before,
    'stockAfter', v_existing.stock_after,
    'processedAt', v_existing.processed_at
  );
end;
$$;


--
-- Name: propagar_codigo_grupo_plano_de_conta(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propagar_codigo_grupo_plano_de_conta() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.codigo IS DISTINCT FROM OLD.codigo THEN
    UPDATE public.planosdeconta
    SET codigo = btrim(NEW.codigo) || substring(codigo FROM char_length(btrim(OLD.codigo)) + 1),
        updatedat = now()
    WHERE grupo_id = NEW.id
      AND codigo LIKE btrim(OLD.codigo) || '.%';
  END IF;
  RETURN NEW;
END;
$$;


