--
-- Name: proteger_categoria_transacao_sistema(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proteger_categoria_transacao_sistema() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.codigo_sistema IS NOT NULL THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'Categorias de sistema não podem ser excluídas.';
    END IF;

    IF NEW.codigo_sistema IS DISTINCT FROM OLD.codigo_sistema THEN
      RAISE EXCEPTION 'O código de uma categoria de sistema não pode ser alterado.';
    END IF;

    IF NEW.ativo IS NOT TRUE THEN
      RAISE EXCEPTION 'Categorias de sistema não podem ser desativadas.';
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: proteger_checklist_documento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proteger_checklist_documento() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    -- Unico campo mutavel: o elo com a versao anterior. Comparar o resto como
    -- jsonb mantem a trava valida quando novas colunas forem adicionadas.
    if to_jsonb(new) - 'versao_anterior_id' is distinct from to_jsonb(old) - 'versao_anterior_id' then
      raise exception 'Versoes de checklist sao imutaveis.' using errcode = '55000';
    end if;
    return new;
  end if;

  -- Segunda barreira para o documento assinado: mesmo chamando a funcao de
  -- exclusao, ela precisa ter declarado a intencao na mesma transacao.
  if exists (
    select 1 from public.checklist_documento_assinatura a where a.documento_id = old.id
  ) and coalesce(current_setting('app.checklist_exclusao_assinada', true), 'off') <> 'on' then
    raise exception 'Documento assinado nao pode ser excluido.' using errcode = '55000';
  end if;

  return old;
end;
$$;


