--
-- Name: proteger_credenciais_convite_checklist(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proteger_credenciais_convite_checklist() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.public_id is distinct from old.public_id
    or new.documento_id is distinct from old.documento_id
    or new.cpf_hmac is distinct from old.cpf_hmac
    or new.cpf_cifrado is distinct from old.cpf_cifrado
    or new.senha_hash is distinct from old.senha_hash
    or new.senha_salt is distinct from old.senha_salt
    or new.senha_parametros is distinct from old.senha_parametros
    or new.expira_em is distinct from old.expira_em
    or new.criado_por is distinct from old.criado_por
    or new.criado_em is distinct from old.criado_em then
    raise exception 'As credenciais do convite de assinatura sao imutaveis.' using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: proteger_os_historica_migrada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.proteger_os_historica_migrada() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.migracao_referencia is not null
     and coalesce(current_setting('app.permitir_alterar_os_migrada', true), '') <> 'on' then
    raise exception 'A OS % e historica e somente leitura.', old.id
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


