--
-- Name: reaplicar_baixa_estoque_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reaplicar_baixa_estoque_os(p_os_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.estoque_definir_contexto('ORDEM_SERVICO', p_os_id::bigint, 'OS #' || p_os_id);
  PERFORM public.reaplicar_baixa_estoque_os_interna(p_os_id);
END;
$$;


--
-- Name: reaplicar_baixa_estoque_os_interna(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reaplicar_baixa_estoque_os_interna(p_os_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  r record;
  q_baixada int;
  delta int;
begin
  -- Para cada item ATUAL do orçamento
  for r in
    select p.produtoid, p.quantidade
      from public.osproduto p
     where p.ordemservicoid = p_os_id
  loop
    select b.quantidade into q_baixada
      from public.osproduto_baixa b
     where b.ordemservicoid = p_os_id
       and b.produtoid = r.produtoid;

    if q_baixada is null then
      delta := r.quantidade; -- primeira baixa
    else
      delta := r.quantidade - q_baixada; -- diferença desde a última aplicação
    end if;

    if delta > 0 then
      -- precisa baixar mais (consumir estoque)
      update public.produto
         set estoque = estoque - delta
       where id = r.produtoid
         and estoque >= delta;
      if not found then
        raise exception 'Estoque insuficiente para o produto % (necessário: %, OS %)', r.produtoid, delta, p_os_id
          using errcode = 'P0001';
      end if;

      insert into public.osproduto_baixa (ordemservicoid, produtoid, quantidade)
      values (p_os_id, r.produtoid, r.quantidade)
      on conflict (ordemservicoid, produtoid) do update
        set quantidade = excluded.quantidade;

    elsif delta < 0 then
      -- precisa devolver parte (reduziu quantidade no orçamento)
      update public.produto
         set estoque = estoque + (-delta)
       where id = r.produtoid;

      insert into public.osproduto_baixa (ordemservicoid, produtoid, quantidade)
      values (p_os_id, r.produtoid, r.quantidade)
      on conflict (ordemservicoid, produtoid) do update
        set quantidade = excluded.quantidade;
    end if;
  end loop;

  -- Itens que foram REMOVIDOS do orçamento: estorna tudo e apaga controle
  for r in
    select b.produtoid, b.quantidade
      from public.osproduto_baixa b
     where b.ordemservicoid = p_os_id
       and not exists (
         select 1 from public.osproduto p
          where p.ordemservicoid = p_os_id
            and p.produtoid = b.produtoid
       )
  loop
    update public.produto
       set estoque = estoque + r.quantidade
     where id = r.produtoid;

    delete from public.osproduto_baixa
     where ordemservicoid = p_os_id
       and produtoid      = r.produtoid;
  end loop;
end
$$;


--
-- Name: recalcular_baixas_transacao(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_baixas_transacao(p_transacao_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_baixado numeric(14,2);
  v_quantas int;
  v_liquido numeric(14,2);
  v_ultimo_pago timestamptz;
  v_antecipado boolean;
  v_fechou boolean;
BEGIN
  SELECT coalesce(sum(coalesce(nullif(f."valorLiquido", 0), f.valor)), 0),
         count(*), max(f.pago_em)
    INTO v_baixado, v_quantas, v_ultimo_pago
    FROM public.transacao f
   WHERE f.baixa_de_transacao_id = p_transacao_id
     AND f.is_deleted = false;

  SELECT coalesce(nullif(t."valorLiquido", 0), t.valor), t.adiantamento_id IS NOT NULL
    INTO v_liquido, v_antecipado
    FROM public.transacao t WHERE t.id = p_transacao_id;
  IF NOT FOUND THEN RETURN; END IF;

  IF round(v_baixado, 2) > round(coalesce(v_liquido, 0), 2) THEN
    RAISE EXCEPTION
      'As baixas do título #% somam % e passam do valor dele (%).',
      p_transacao_id, v_baixado, v_liquido USING ERRCODE = '22023';
  END IF;

  IF v_quantas = 0 THEN
    UPDATE public.transacao SET valor_baixado = 0, updated_at = now()
     WHERE id = p_transacao_id AND valor_baixado <> 0;
    RETURN;
  END IF;

  /*
   * Em título antecipado a filha é REPASSE DE CAIXA, não quitação.
   *
   * A antecipação já respondeu pelo principal; o que entra agora é só a parte
   * que o banco não reteve. Quem fecha o título é a baixa, que sabe que o boleto
   * foi pago por inteiro — e ela já gravou a data informada.
   */
  IF coalesce(v_antecipado, false) THEN
    UPDATE public.transacao
       SET valor_baixado = round(v_baixado, 2), updated_at = now()
     WHERE id = p_transacao_id;
    RETURN;
  END IF;

  v_fechou := round(v_baixado, 2) >= round(coalesce(v_liquido, 0), 2);

  UPDATE public.transacao
     SET valor_baixado = round(v_baixado, 2),
         pendente = NOT v_fechou,
         pago_em = CASE WHEN v_fechou THEN v_ultimo_pago ELSE NULL END,
         -- `data` é a data de liquidação, e é por ela que as listas recortam o
         -- período. Fechado, o título vale pelo dia do último pagamento; reaberto
         -- por estorno, volta a valer pelo vencimento — a mesma ida e volta que a
         -- baixa comum e o estorno dela já fazem.
         data = CASE
           WHEN v_fechou THEN coalesce(v_ultimo_pago, data)
           ELSE coalesce(vencimento_em, data)
         END,
         updated_at = now()
   WHERE id = p_transacao_id;
END;
$$;


--
-- Name: FUNCTION recalcular_baixas_transacao(p_transacao_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recalcular_baixas_transacao(p_transacao_id bigint) IS 'Refaz valor_baixado do título a partir das baixas parciais dele, e decide se está aberto. Fechado, leva `data` para o dia do último pagamento; reaberto, devolve ao vencimento. Em título antecipado só atualiza o valor: lá quem fecha é a baixa, porque a filha é repasse de caixa e não quitação.';


--
-- Name: recalcular_comissao_criacao_os(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_comissao_criacao_os(p_ordemservicoid integer, p_forcar boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_criador uuid;
  v_pct_servicos numeric := 0;
  v_pct_produtos numeric := 0;
  v_somente boolean := false;
  v_execucao_encerrada boolean := false;
  v_total_os_sem_frete numeric := 0;
  v_total_itens numeric := 0;
  v_fator numeric := 1;
  v_existe boolean;
BEGIN
  SELECT o.usuariocriadorid, o.execucao_fim_em IS NOT NULL
    INTO v_criador, v_execucao_encerrada
    FROM public.ordemservico o
   WHERE o.id = p_ordemservicoid;

  IF v_criador IS NULL THEN
    DELETE FROM public.os_comissao_criacao WHERE ordemservicoid = p_ordemservicoid;
    RETURN;
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.os_comissao_criacao WHERE ordemservicoid = p_ordemservicoid)
    INTO v_existe;

  -- Execucao encerrada e nunca apurada: fica assim, a menos que alguem tenha
  -- pedido nomeando a OS. Ver 20260904140000.
  IF NOT v_existe AND v_execucao_encerrada AND NOT p_forcar THEN
    RETURN;
  END IF;

  IF p_forcar THEN
    v_execucao_encerrada := false;
  END IF;

  -- Execucao encerrada: os percentuais viraram historico e saem das proprias
  -- linhas. Ainda em execucao: releem o cadastro.
  IF v_existe AND v_execucao_encerrada THEN
    SELECT max(CASE WHEN c.tipo = 'SERVICO' THEN c.pct END),
           max(CASE WHEN c.tipo <> 'SERVICO' THEN c.pct END)
      INTO v_pct_servicos, v_pct_produtos
      FROM public.os_comissao_criacao c
     WHERE c.ordemservicoid = p_ordemservicoid;
    -- A flag nao viaja nas linhas: o que ela decidiu ja esta expresso em quais
    -- servicos existem como linha. Reler o cadastro aqui reabriria a base.
    SELECT coalesce(u.comissao_criacao_somente_comissionaveis, false) INTO v_somente
      FROM public.usuario u WHERE u.id = v_criador;
  ELSE
    SELECT coalesce(u.comissao_criacao_servico_percent, 0),
           coalesce(u.comissao_criacao_produto_percent, 0),
           coalesce(u.comissao_criacao_somente_comissionaveis, false)
      INTO v_pct_servicos, v_pct_produtos, v_somente
      FROM public.usuario u
     WHERE u.id = v_criador;
  END IF;

  v_pct_servicos := coalesce(v_pct_servicos, 0);
  v_pct_produtos := coalesce(v_pct_produtos, 0);

  IF v_pct_servicos = 0 AND v_pct_produtos = 0 THEN
    DELETE FROM public.os_comissao_criacao WHERE ordemservicoid = p_ordemservicoid;
    RETURN;
  END IF;

  -- Expressao identica a de `recalcular_comissao_osservico`. Mudar uma sem a
  -- outra faz as duas comissoes da mesma OS discordarem sobre o desconto.
  SELECT greatest(coalesce(o.orcamentototal, 0) - coalesce(o.valor_frete, 0), 0),
         coalesce((SELECT sum(coalesce(op.subtotal, 0)) FROM public.osproduto op WHERE op.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(opa.subtotal, 0)) FROM public.osproduto_avulso opa WHERE opa.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(os.subtotal, 0)) FROM public.osservico os WHERE os.ordemservicoid = o.id), 0)
    INTO v_total_os_sem_frete, v_total_itens
    FROM public.ordemservico o WHERE o.id = p_ordemservicoid;

  IF v_total_itens > 0 THEN v_fator := v_total_os_sem_frete / v_total_itens; END IF;

  -- Uma linha por item. O DELETE do que sobrou remove item retirado da OS.
  WITH desejadas AS (
    SELECT 'SERVICO'::text AS tipo, os.servicoid AS item_id,
           round(coalesce(os.subtotal, 0) * v_fator, 2) AS base, v_pct_servicos AS pct
      FROM public.osservico os
      JOIN public.servico s ON s.id = os.servicoid
     WHERE os.ordemservicoid = p_ordemservicoid
       AND v_pct_servicos > 0
       AND (NOT v_somente OR coalesce(s.gera_comissao, true))
    UNION ALL
    SELECT 'PRODUTO', op.produtoid,
           round(coalesce(op.subtotal, 0) * v_fator, 2), v_pct_produtos
      FROM public.osproduto op
     WHERE op.ordemservicoid = p_ordemservicoid AND v_pct_produtos > 0
    UNION ALL
    SELECT 'PRODUTO_AVULSO', opa.id,
           round(coalesce(opa.subtotal, 0) * v_fator, 2), v_pct_produtos
      FROM public.osproduto_avulso opa
     WHERE opa.ordemservicoid = p_ordemservicoid AND v_pct_produtos > 0
  ),
  gravadas AS (
    INSERT INTO public.os_comissao_criacao AS c
      (ordemservicoid, tipo, item_id, usuarioid, base, pct, valor_comissao, updated_at)
    SELECT p_ordemservicoid, d.tipo, d.item_id, v_criador, d.base, d.pct,
           round(d.base * d.pct / 100.0, 2), now()
      FROM desejadas d
    ON CONFLICT (ordemservicoid, tipo, item_id) DO UPDATE SET
      -- `usuarioid` de proposito NAO entra: o criador e carimbado na primeira
      -- apuracao e nao acompanha troca de titularidade.
      base = excluded.base,
      pct = excluded.pct,
      -- O ajuste feito no financeiro prevalece sobre o calculo.
      valor_comissao = coalesce(c.valor_comissao_manual, excluded.valor_comissao),
      updated_at = now()
    RETURNING c.tipo, c.item_id
  )
  DELETE FROM public.os_comissao_criacao c
   WHERE c.ordemservicoid = p_ordemservicoid
     AND NOT EXISTS (
       SELECT 1 FROM gravadas g WHERE g.tipo = c.tipo AND g.item_id = c.item_id
     );
END;
$$;


--
-- Name: FUNCTION recalcular_comissao_criacao_os(p_ordemservicoid integer, p_forcar boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recalcular_comissao_criacao_os(p_ordemservicoid integer, p_forcar boolean) IS 'Recalcula a comissao de criacao da OS, uma linha por item, sobre a base liquida. Criador sem percentual: apaga as linhas. Execucao encerrada: usa os percentuais congelados, e nao apura o que nunca foi apurado — salvo com p_forcar.';


--
-- Name: recalcular_comissao_osservico(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_comissao_osservico(p_ordemservicoid integer, p_servicoid integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_subtotal numeric;
  v_qtd int;
  v_gera_comissao boolean;
  v_total_itens numeric := 0;
  v_total_os_sem_frete numeric := 0;
  v_fator numeric := 1;
  v_base_liquida numeric;
  v_percent_maior numeric := 0;
  v_execucao_encerrada boolean := true;
BEGIN
  SELECT coalesce(s.subtotal, 0) INTO v_subtotal
    FROM public.osservico s
   WHERE s.ordemservicoid = p_ordemservicoid AND s.servicoid = p_servicoid;
  SELECT coalesce(sv.gera_comissao, true) INTO v_gera_comissao
    FROM public.servico sv WHERE sv.id = p_servicoid;
  SELECT count(*) INTO v_qtd FROM public.osservico_realizador r
   WHERE r.ordemservicoid = p_ordemservicoid AND r.servicoid = p_servicoid;
  IF v_qtd <= 0 THEN RETURN; END IF;

  SELECT greatest(coalesce(o.orcamentototal, 0) - coalesce(o.valor_frete, 0), 0),
         coalesce((SELECT sum(coalesce(op.subtotal, 0)) FROM public.osproduto op WHERE op.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(opa.subtotal, 0)) FROM public.osproduto_avulso opa WHERE opa.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(os.subtotal, 0)) FROM public.osservico os WHERE os.ordemservicoid = o.id), 0),
         o.execucao_fim_em IS NOT NULL
    INTO v_total_os_sem_frete, v_total_itens, v_execucao_encerrada
    FROM public.ordemservico o WHERE o.id = p_ordemservicoid;

  -- Enquanto o servico nao foi entregue, quem manda e o cadastro de hoje: a
  -- taxa que vale e a do dia da entrega, nao a do dia da atribuicao.
  IF NOT v_execucao_encerrada THEN
    PERFORM public.recarimbar_comissao_osservico(p_ordemservicoid, p_servicoid);
  END IF;

  IF v_total_itens > 0 THEN v_fator := v_total_os_sem_frete / v_total_itens; END IF;
  v_base_liquida := round(v_subtotal * v_fator / v_qtd, 2);

  -- O maior percentual entre quem executou. Com um realizador so, e a taxa dele
  -- e nada muda em relacao ao comportamento anterior.
  SELECT coalesce(max(coalesce(r.comissao_percent_aplicada, 0)), 0)
    INTO v_percent_maior
    FROM public.osservico_realizador r
   WHERE r.ordemservicoid = p_ordemservicoid AND r.servicoid = p_servicoid;

  -- Servico que nao comissiona zera a taxa efetiva, e nao so o valor: assim a
  -- linha zerada no relatorio se explica sozinha.
  IF NOT coalesce(v_gera_comissao, true) THEN
    v_percent_maior := 0;
  END IF;

  -- O ajuste feito no financeiro prevalece; base e percentual seguem dizendo
  -- o que a regra calcularia.
  UPDATE public.osservico_realizador r
     SET valor_base = v_base_liquida,
         comissao_percent_efetiva = v_percent_maior,
         valor_comissao = coalesce(r.valor_comissao_manual, round(v_base_liquida * v_percent_maior / 100.0, 2)),
         updated_at = now()
   WHERE r.ordemservicoid = p_ordemservicoid AND r.servicoid = p_servicoid;
END;
$$;


--
-- Name: recalcular_documentos_da_transacao(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_documentos_da_transacao(p_transacao_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT DISTINCT tipo_documento, documento_id
      FROM public.pagamento_multiplo_rateio
     WHERE transacao_id = p_transacao_id
  LOOP
    IF r.tipo_documento = 'OS' THEN
      PERFORM public.recalcular_status_financeiro_os(r.documento_id);
    ELSE
      PERFORM public.recalcular_status_financeiro_venda(r.documento_id);
    END IF;
  END LOOP;
END;
$$;


--
-- Name: recalcular_saldo_credito_cliente(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_saldo_credito_cliente(p_cliente_id integer) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo numeric(14,2);
BEGIN
  SELECT coalesce(
           sum(CASE WHEN m.sentido = 'CREDITO' THEN m.valor ELSE -m.valor END),
           0
         )
    INTO v_saldo
    FROM public.cliente_saldo_movimento m
   WHERE m.cliente_id = p_cliente_id;

  UPDATE public.cliente
     SET saldo_credito = round(v_saldo, 2),
         updatedat = now()
   WHERE id = p_cliente_id;

  RETURN round(v_saldo, 2);
END;
$$;


--
-- Name: recalcular_status_financeiro_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_status_financeiro_os(p_ordemservicoid integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_pagamento_concluido_em timestamptz;
  v_total_devido numeric(14,2);
  v_valor_comprometido numeric(14,2);
  v_quitada boolean;
  v_novo_status text;
  v_novo_pagamento_concluido_em timestamptz;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(87009, 1);
  SELECT o.status::text, o.pagamento_concluido_em
    INTO v_status, v_pagamento_concluido_em
  FROM public.ordemservico o
  WHERE o.id = p_ordemservicoid
    AND coalesce(o.is_deleted, false) = false
    AND o.migracao_referencia IS NULL FOR UPDATE;

  IF NOT FOUND THEN RETURN; END IF;

  SELECT r.total_devido, r.valor_comprometido, r.quitada
    INTO v_total_devido, v_valor_comprometido, v_quitada
  FROM public.resumo_financeiro_os(p_ordemservicoid) r;

  v_novo_status := v_status;
  IF v_status IN ('PAGAMENTO', 'FATURAMENTO') AND v_quitada THEN
    v_novo_status := 'CONCLUIDO';
  ELSIF v_status = 'CONCLUIDO'
        AND v_total_devido > 0
        AND v_valor_comprometido < v_total_devido THEN
    v_novo_status := CASE WHEN public.faturamento_os_habilitado() THEN 'FATURAMENTO' ELSE 'PAGAMENTO' END;
  END IF;

  v_novo_pagamento_concluido_em := CASE
    WHEN v_quitada THEN coalesce(v_pagamento_concluido_em, now())
    ELSE NULL
  END;

  UPDATE public.ordemservico
  SET status = v_novo_status::public.enum_status_os,
      pagamento_concluido_em = v_novo_pagamento_concluido_em,
      updatedat = now()
  WHERE id = p_ordemservicoid
    AND (
      status::text IS DISTINCT FROM v_novo_status OR
      pagamento_concluido_em IS DISTINCT FROM v_novo_pagamento_concluido_em
    );
END;
$$;


--
-- Name: recalcular_status_financeiro_venda(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_status_financeiro_venda(p_venda_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_devido numeric(14,2);
  v_comprometido numeric(14,2);
  v_status text;
  v_novo text;
BEGIN
  SELECT v.status::text,
         round(
           greatest(coalesce(v.valortotal, 0), 0) +
           CASE
             WHEN v.acrescimo_financeiro_tipo = 'PORCENTAGEM' THEN
               greatest(coalesce(v.valortotal, 0), 0) *
               least(greatest(coalesce(v.acrescimo_financeiro_valor, 0), 0), 100) / 100
             WHEN v.acrescimo_financeiro_tipo = 'FIXO' THEN
               greatest(coalesce(v.acrescimo_financeiro_valor, 0), 0)
             ELSE 0
           END,
           2
         )
    INTO v_status, v_total_devido
  FROM public.venda v
  WHERE v.id = p_venda_id;

  IF NOT FOUND THEN RETURN; END IF;
  IF v_status = 'CANCELADA' THEN RETURN; END IF;

  -- Pendente conta: título em aberto é compromisso assumido, igual à OS. Quem
  -- recebe de fato é a baixa, que é trabalho do financeiro e não do vendedor.
  SELECT coalesce(round(sum(r.valor), 2), 0)
    INTO v_comprometido
  FROM public.recebimento_por_documento r
  WHERE r.tipo_documento = 'VENDA'
    AND r.documento_id = p_venda_id;

  v_novo := CASE WHEN v_total_devido > 0 AND v_comprometido >= v_total_devido
                 THEN 'FINALIZADA' ELSE 'PAGAMENTO' END;

  UPDATE public.venda
  SET status = v_novo::public.enum_status_venda,
      updatedat = now()
  WHERE id = p_venda_id
    AND status::text IS DISTINCT FROM v_novo;
END;
$$;


--
-- Name: FUNCTION recalcular_status_financeiro_venda(p_venda_id integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recalcular_status_financeiro_venda(p_venda_id integer) IS 'Status financeiro da venda. Título pendente conta como comprometido e já finaliza a venda, mesma regra da ordem de serviço.';


--
-- Name: recalcular_valores_transacao(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalcular_valores_transacao(p_transacao_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acrescimos numeric(14,2);
  v_descontos numeric(14,2);
  v_base numeric(14,2);
  v_valor numeric(14,2);
BEGIN
  SELECT coalesce(valor_base, valor, 0) INTO v_base
    FROM public.transacao WHERE id = p_transacao_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT
    coalesce(sum(valor_calculado) FILTER (WHERE natureza = 'ACRESCIMO'), 0),
    coalesce(sum(valor_calculado) FILTER (WHERE natureza = 'DESCONTO'), 0)
    INTO v_acrescimos, v_descontos
    FROM public.transacao_ajuste
   WHERE transacao_id = p_transacao_id;

  v_valor := round(v_base + v_acrescimos, 2);

  IF v_descontos > v_valor THEN
    RAISE EXCEPTION
      'A soma dos descontos (%) nao pode passar do valor bruto (%).', v_descontos, v_valor
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.transacao
     SET valor_acrescimos = v_acrescimos,
         valor_descontos = v_descontos,
         valor = v_valor,
         "valorLiquido" = round(v_valor - v_descontos, 2),
         updated_at = now()
   WHERE id = p_transacao_id;
END;
$$;


--
-- Name: recarimbar_comissao_criacao_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recarimbar_comissao_criacao_os(p_ordemservicoid integer) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE public.os_comissao_criacao c
     SET pct = CASE c.tipo
                 WHEN 'SERVICO' THEN coalesce(u.comissao_criacao_servico_percent, 0)
                 ELSE coalesce(u.comissao_criacao_produto_percent, 0)
               END,
         updated_at = now()
    FROM public.usuario u
   WHERE c.ordemservicoid = p_ordemservicoid
     AND u.id = c.usuarioid;
$$;


--
-- Name: FUNCTION recarimbar_comissao_criacao_os(p_ordemservicoid integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recarimbar_comissao_criacao_os(p_ordemservicoid integer) IS 'Traz os percentuais de comissao de criacao do cadastro do usuario para as linhas da OS, cada uma pelo percentual do seu tipo.';


--
-- Name: recarimbar_comissao_osservico(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recarimbar_comissao_osservico(p_ordemservicoid integer, p_servicoid integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE public.osservico_realizador r
     SET comissao_percent_aplicada =
           CASE
             WHEN coalesce((SELECT s.gera_comissao FROM public.servico s WHERE s.id = r.servicoid), true)
               THEN coalesce((SELECT u.comissao_percent FROM public.usuario u WHERE u.id = r.usuarioid), 0)
             ELSE 0
           END,
         updated_at = now()
   WHERE r.ordemservicoid = p_ordemservicoid
     AND (p_servicoid IS NULL OR r.servicoid = p_servicoid);
$$;


--
-- Name: FUNCTION recarimbar_comissao_osservico(p_ordemservicoid integer, p_servicoid integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.recarimbar_comissao_osservico(p_ordemservicoid integer, p_servicoid integer) IS 'Traz comissao_percent_aplicada do cadastro do usuario para os vinculos da OS (ou de um servico dela). Servico sem comissao carimba zero.';


--
-- Name: reconciliar_comissao_venda(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconciliar_comissao_venda(p_vendaid bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_snapshot public.venda_comissao%ROWTYPE;
  v_evento public.eventos_financeiros%ROWTYPE;
  v_usuario uuid; v_pct numeric; v_base numeric; v_valor numeric;
  v_manual numeric; v_calculado numeric; v_frete_itens numeric;
  v_reconhecida boolean; v_nome text;
BEGIN
  SELECT * INTO v_venda FROM public.venda WHERE id = p_vendaid FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT * INTO v_snapshot FROM public.venda_comissao WHERE vendaid = p_vendaid FOR UPDATE;
  IF FOUND AND NOT v_snapshot.integrada THEN RETURN; END IF;
  v_reconhecida := public.venda_reconhece_receita(v_venda.status::text);
  v_usuario := coalesce(v_venda.vendedor,v_venda.created_by);
  IF v_reconhecida AND v_snapshot.congelada_em IS NOT NULL AND v_usuario IS NOT DISTINCT FROM v_snapshot.usuarioid THEN
    v_pct := v_snapshot.percentual;
  ELSE
    SELECT coalesce(comissao_venda_percent,0) INTO v_pct FROM public.usuario WHERE id = v_usuario;
  END IF;
  v_pct := coalesce(v_pct,0);
  SELECT coalesce(sum(valor_frete),0) INTO v_frete_itens FROM public.vendaproduto WHERE venda_id = p_vendaid;
  v_base := round(greatest(coalesce(v_venda.valortotal,0)-coalesce(v_venda.valor_frete,0)-v_frete_itens,0),2);
  v_calculado := round(v_base*v_pct/100,2);
  SELECT * INTO v_evento FROM public.eventos_financeiros
    WHERE source_type = 'VENDA' AND source_id = p_vendaid AND origem = 'COMISSAO' AND chave_origem = 'COMISSAO_VENDA' FOR UPDATE;
  -- Ajustes anteriores sao reconhecidos quando a venda for recalculada, sem
  -- backfill nem reescrita de historico durante a aplicacao desta migration.
  v_manual := CASE WHEN v_usuario IS NOT DISTINCT FROM v_snapshot.usuarioid THEN
    coalesce(v_snapshot.valor_comissao_manual,CASE WHEN v_evento.is_manual AND v_evento.usuarioid IS NOT DISTINCT FROM v_usuario THEN v_evento.valor END) END;
  v_valor := coalesce(v_manual,v_calculado);
  PERFORM 1 FROM public.eventos_financeiros WHERE source_type = 'VENDA' AND source_id = p_vendaid AND origem = 'COMISSAO' FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.eventos_financeiros e
    WHERE e.source_type = 'VENDA' AND e.source_id = p_vendaid AND e.origem = 'COMISSAO'
      AND (e.status = 'CONVERTIDO' OR e.transacaoid IS NOT NULL OR e.lancamento_id IS NOT NULL)
      AND (NOT v_reconhecida OR e.valor IS DISTINCT FROM v_valor OR e.usuarioid IS DISTINCT FROM v_usuario)) THEN
    RAISE EXCEPTION 'Desfaca o lancamento financeiro da comissao antes de alterar ou cancelar esta venda.' USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO public.venda_comissao(vendaid,usuarioid,base,percentual,valor_comissao,valor_comissao_manual,congelada_em)
    VALUES(p_vendaid,v_usuario,v_base,v_pct,v_valor,v_manual,
      CASE WHEN v_reconhecida THEN coalesce(v_snapshot.congelada_em,v_venda.pagamento_em,now()) END)
    ON CONFLICT(vendaid) DO UPDATE SET usuarioid = excluded.usuarioid,base = excluded.base,
      percentual = excluded.percentual,valor_comissao = excluded.valor_comissao,
      valor_comissao_manual = excluded.valor_comissao_manual,congelada_em = excluded.congelada_em,updated_at = now();
  IF NOT v_reconhecida THEN
    UPDATE public.eventos_financeiros SET status = 'CANCELADO',updated_at = now()
      WHERE source_type = 'VENDA' AND source_id = p_vendaid AND origem = 'COMISSAO' AND status = 'ATIVO';
    RETURN;
  END IF;
  SELECT coalesce(nullif(nome,''),'Vendedor') INTO v_nome FROM public.usuario WHERE id = v_usuario;
  INSERT INTO public.eventos_financeiros
    (source_type,source_id,origem,natureza,natureza_dre,chave_origem,descricao,detalhe,valor,usuarioid,
     valor_base_snapshot,percentual_snapshot,competencia_em,dados_snapshot,pode_gerar_transacao,is_manual)
    VALUES('VENDA',p_vendaid,'COMISSAO','DESPESA',public.natureza_dre_de_evento('COMISSAO','DESPESA'),
      'COMISSAO_VENDA','Comissão da venda #'||p_vendaid||' - '||coalesce(v_nome,'Sem vendedor'),
      'Base líquida sem frete: R$ '||v_base||' × '||v_pct||'%',v_valor,v_usuario,v_base,v_pct,
      coalesce(v_venda.datavenda,v_venda.createdat,now()),
      jsonb_build_object('vendaid',p_vendaid,'usuarioid',v_usuario,'base',v_base,'percentual',v_pct,'valor_comissao',v_valor)
        || CASE WHEN v_manual IS NOT NULL THEN jsonb_build_object('comissao_ajustada_a_mao',true,'valor_calculado',v_calculado) ELSE '{}'::jsonb END,
      v_valor > 0 AND v_usuario IS NOT NULL,v_manual IS NOT NULL)
    ON CONFLICT(source_type,source_id,origem,chave_origem,natureza) WHERE ordemservicoid IS NULL
    DO UPDATE SET valor = excluded.valor,usuarioid = excluded.usuarioid,descricao = excluded.descricao,
      detalhe = excluded.detalhe,valor_base_snapshot = excluded.valor_base_snapshot,
      percentual_snapshot = excluded.percentual_snapshot,competencia_em = excluded.competencia_em,
      dados_snapshot = CASE WHEN excluded.is_manual THEN coalesce(eventos_financeiros.dados_snapshot,'{}'::jsonb) || excluded.dados_snapshot ELSE excluded.dados_snapshot END,
      pode_gerar_transacao = excluded.pode_gerar_transacao,is_manual = excluded.is_manual,status = 'ATIVO',updated_at = now()
    WHERE eventos_financeiros.status <> 'CONVERTIDO' AND eventos_financeiros.transacaoid IS NULL AND eventos_financeiros.lancamento_id IS NULL;
END;
$_$;


--
-- Name: FUNCTION reconciliar_comissao_venda(p_vendaid bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconciliar_comissao_venda(p_vendaid bigint) IS 'Apura a comissao da venda. A taxa congela com a venda, mas trocar o vendedor transfere a comissao e reapura pela taxa de quem entrou. Comissao ja lancada no financeiro recusa a alteracao.';


--
-- Name: reconciliar_eventos_financeiros_os(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconciliar_eventos_financeiros_os(p_ordemservicoid integer, p_incluir_comissoes boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_total_os numeric := 0;
  v_bruto numeric := 0;
  v_frete numeric := 0;
  v_deducao numeric := 0;
BEGIN
  SELECT coalesce(o.orcamentototal, 0),
         round(coalesce(o.valor_frete, 0), 2),
         coalesce((SELECT sum(coalesce(op.precounitario, 0) * coalesce(op.quantidade, 0))
                     FROM public.osproduto op WHERE op.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(opa.precounitario, 0) * coalesce(opa.quantidade, 0))
                         FROM public.osproduto_avulso opa WHERE opa.ordemservicoid = o.id), 0)
           + coalesce((SELECT sum(coalesce(os.precounitario, 0) * coalesce(os.quantidade, 0))
                         FROM public.osservico os WHERE os.ordemservicoid = o.id), 0)
    INTO v_total_os, v_frete, v_bruto
  FROM public.ordemservico o
  WHERE o.id = p_ordemservicoid;

  IF NOT FOUND THEN RAISE EXCEPTION 'OS nao encontrada.'; END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.eventos_os_desejados (
    origem text NOT NULL,
    natureza text NOT NULL,
    chave_origem text NOT NULL,
    descricao text NOT NULL,
    detalhe text,
    valor numeric(14,2) NOT NULL,
    produtoid integer,
    servicoid integer,
    usuarioid uuid,
    quantidade_snapshot numeric(14,4),
    valor_unitario_snapshot numeric(14,4),
    percentual_snapshot numeric(8,4),
    valor_base_snapshot numeric(14,2),
    dados_snapshot jsonb NOT NULL,
    pode_gerar_transacao boolean NOT NULL,
    natureza_dre text,
    PRIMARY KEY (origem, natureza, chave_origem)
  ) ON COMMIT DROP;
  TRUNCATE pg_temp.eventos_os_desejados;

  INSERT INTO pg_temp.eventos_os_desejados
    (origem, natureza, chave_origem, descricao, detalhe, valor, produtoid, servicoid,
     usuarioid, quantidade_snapshot, valor_unitario_snapshot, percentual_snapshot,
     valor_base_snapshot, dados_snapshot, pode_gerar_transacao, natureza_dre)
  SELECT 'PRODUTO', 'RECEITA', op.produtoid::text,
         'Venda - ' || coalesce(nullif(p.titulo, ''), nullif(p.descricao, ''), 'Produto #' || op.produtoid),
         op.quantidade || ' unidade(s)',
         round(coalesce(op.precounitario, 0) * coalesce(op.quantidade, 0), 2),
         op.produtoid, null, null, op.quantidade, op.precounitario, null, null,
         jsonb_build_object('subtotal', op.subtotal, 'bruto', round(coalesce(op.precounitario, 0) * coalesce(op.quantidade, 0), 2)), false,
         public.natureza_dre_de_evento('PRODUTO', 'RECEITA')
  FROM public.osproduto op
  JOIN public.produto p ON p.id = op.produtoid
  WHERE op.ordemservicoid = p_ordemservicoid;

  INSERT INTO pg_temp.eventos_os_desejados
    (origem, natureza, chave_origem, descricao, detalhe, valor, produtoid, servicoid,
     usuarioid, quantidade_snapshot, valor_unitario_snapshot, percentual_snapshot,
     valor_base_snapshot, dados_snapshot, pode_gerar_transacao, natureza_dre)
  SELECT 'PRODUTO', 'RECEITA', 'AVULSO:' || opa.id,
         'Venda - ' || coalesce(nullif(opa.titulo, ''), 'Produto avulso #' || opa.id),
         opa.quantidade || ' unidade(s) (produto avulso)',
         round(coalesce(opa.precounitario, 0) * coalesce(opa.quantidade, 0), 2),
         null, null, null, opa.quantidade, opa.precounitario, null, null,
         jsonb_build_object(
           'produto_avulso', true,
           'produto_avulso_id', opa.id,
           'subtotal', opa.subtotal,
           'bruto', round(coalesce(opa.precounitario, 0) * coalesce(opa.quantidade, 0), 2)
         ), false,
         public.natureza_dre_de_evento('PRODUTO', 'RECEITA')
  FROM public.osproduto_avulso opa
  WHERE opa.ordemservicoid = p_ordemservicoid;

  INSERT INTO pg_temp.eventos_os_desejados
    (origem, natureza, chave_origem, descricao, detalhe, valor, produtoid, servicoid,
     usuarioid, quantidade_snapshot, valor_unitario_snapshot, percentual_snapshot,
     valor_base_snapshot, dados_snapshot, pode_gerar_transacao, natureza_dre)
  SELECT 'PRODUTO', 'DESPESA', op.produtoid::text,
         'Custo - ' || coalesce(nullif(p.titulo, ''), nullif(p.descricao, ''), 'Produto #' || op.produtoid),
         CASE
           WHEN coalesce(op.custo_unitario_aplicado, 0) > 0 THEN 'Custo registrado na OS'
           WHEN coalesce(p.ultimovalordecompra, 0) > 0 THEN 'Ultimo valor de compra do produto'
           WHEN coalesce(p.precocompra, 0) > 0 THEN 'Preco medio de compra do produto'
           ELSE 'Produto sem custo cadastrado'
         END,
         round(coalesce(nullif(op.custo_unitario_aplicado, 0), nullif(p.ultimovalordecompra, 0), nullif(p.precocompra, 0), 0)
               * coalesce(op.quantidade, 0), 2),
         op.produtoid, null, null, op.quantidade,
         coalesce(nullif(op.custo_unitario_aplicado, 0), nullif(p.ultimovalordecompra, 0), nullif(p.precocompra, 0), 0), null, null,
         jsonb_build_object(
           'custo_nao_informado',
             coalesce(nullif(op.custo_unitario_aplicado, 0), nullif(p.ultimovalordecompra, 0), nullif(p.precocompra, 0), 0) = 0,
           'custo_origem', CASE
             WHEN coalesce(op.custo_unitario_aplicado, 0) > 0 THEN 'OS'
             WHEN coalesce(p.ultimovalordecompra, 0) > 0 THEN 'ULTIMA_COMPRA'
             WHEN coalesce(p.precocompra, 0) > 0 THEN 'PRECO_MEDIO'
             ELSE 'SEM_CUSTO'
           END), false,
         public.natureza_dre_de_evento('PRODUTO', 'DESPESA')
  FROM public.osproduto op
  JOIN public.produto p ON p.id = op.produtoid
  WHERE op.ordemservicoid = p_ordemservicoid;

  INSERT INTO pg_temp.eventos_os_desejados
    (origem, natureza, chave_origem, descricao, detalhe, valor, produtoid, servicoid,
     usuarioid, quantidade_snapshot, valor_unitario_snapshot, percentual_snapshot,
     valor_base_snapshot, dados_snapshot, pode_gerar_transacao, natureza_dre)
  SELECT 'SERVICO', 'RECEITA', os.servicoid::text,
         'Servico - ' || public.titulo_servico_os(s.descricao, os.descricao, os.servicoid),
         os.quantidade || ' unidade(s)',
         round(coalesce(os.precounitario, 0) * coalesce(os.quantidade, 0), 2),
         null, os.servicoid, null, os.quantidade, os.precounitario, null, null,
         jsonb_build_object('subtotal', os.subtotal, 'bruto', round(coalesce(os.precounitario, 0) * coalesce(os.quantidade, 0), 2)), false,
         public.natureza_dre_de_evento('SERVICO', 'RECEITA')
  FROM public.osservico os
  JOIN public.servico s ON s.id = os.servicoid
  WHERE os.ordemservicoid = p_ordemservicoid;

  IF v_frete > 0 THEN
    INSERT INTO pg_temp.eventos_os_desejados
      (origem, natureza, chave_origem, descricao, detalhe, valor, dados_snapshot,
       pode_gerar_transacao, natureza_dre)
    VALUES ('FRETE', 'RECEITA', 'FRETE',
            'Frete - OS #' || p_ordemservicoid, 'Receita de frete da ordem de servico',
            v_frete, jsonb_build_object('valor_frete', v_frete), false,
            public.natureza_dre_de_evento('FRETE', 'RECEITA'));
  END IF;

  v_deducao := round(greatest(v_bruto + v_frete - v_total_os, 0), 2);

  IF v_deducao > 0 THEN
    INSERT INTO pg_temp.eventos_os_desejados
      (origem, natureza, chave_origem, descricao, detalhe, valor, dados_snapshot,
       pode_gerar_transacao, natureza_dre)
    VALUES ('DESCONTO', 'DESPESA', 'DESCONTO',
            'Desconto concedido - OS #' || p_ordemservicoid, 'Deducao da receita bruta',
            v_deducao, jsonb_build_object('bruto', v_bruto, 'frete', v_frete, 'total_os', v_total_os),
            false, public.natureza_dre_de_evento('DESCONTO', 'DESPESA'));
  END IF;

  IF p_incluir_comissoes THEN
    WITH comissoes AS (
      SELECT r.servicoid,
             r.usuarioid,
             coalesce(r.valor_comissao, 0) AS valor_comissao,
             r.valor_base,
             coalesce(r.comissao_percent_aplicada, 0) AS pct_proprio,
             -- Quem pagou a linha. A coluna efetiva e nula em vinculo anterior
             -- a regra do maior percentual; la a taxa individual era a que valia.
             coalesce(r.comissao_percent_efetiva, r.comissao_percent_aplicada, 0) AS pct_aplicado,
             count(*) OVER (PARTITION BY r.servicoid) AS realizadores,
             public.titulo_servico_os(s.descricao, os.descricao, r.servicoid) AS titulo,
             coalesce(os.subtotal, 0) AS subtotal_servico,
             coalesce(u.nome, 'Realizador') AS realizador_nome,
             coalesce(s.gera_comissao, true) AS comissiona
        FROM public.osservico_realizador r
        JOIN public.osservico os ON os.ordemservicoid = r.ordemservicoid AND os.servicoid = r.servicoid
        JOIN public.servico s ON s.id = r.servicoid
        LEFT JOIN public.usuario u ON u.id = r.usuarioid
       WHERE r.ordemservicoid = p_ordemservicoid
    )
    INSERT INTO pg_temp.eventos_os_desejados
      (origem, natureza, chave_origem, descricao, detalhe, valor, produtoid, servicoid,
       usuarioid, quantidade_snapshot, valor_unitario_snapshot, percentual_snapshot,
       valor_base_snapshot, dados_snapshot, pode_gerar_transacao, natureza_dre)
    SELECT 'COMISSAO', 'DESPESA', c.servicoid || ':' || c.usuarioid,
           'Comissão - ' || c.titulo,
           CASE WHEN NOT c.comissiona THEN
             c.realizador_nome || ' · serviço não gera comissão'
             || CASE WHEN c.realizadores > 1
                     THEN ' · executado por ' || c.realizadores || ' realizadores'
                     ELSE '' END
           ELSE
           c.realizador_nome
             || ' · ' || public.formatar_percentual_comissao(c.pct_aplicado) || '%'
             || CASE WHEN c.realizadores > 1
                     THEN ' (maior entre ' || c.realizadores || ' realizadores) sobre 1/'
                          || c.realizadores || ' do serviço'
                     ELSE ' do serviço' END
             -- A comissao sai do liquido: o desconto da OS e rateado entre os
             -- itens antes do calculo. Sem dizer isso, R$ 88,30 de 5% sobre um
             -- servico de R$ 1.800 parece erro de conta.
             --
             -- A tolerancia e de um centavo por realizador: a base e arredondada
             -- por pessoa, entao 333,33 x 3 fica um centavo abaixo de 1.000 sem
             -- que exista desconto nenhum.
             || CASE WHEN c.subtotal_servico - coalesce(c.valor_base, 0) * c.realizadores
                          > 0.01 * c.realizadores
                     THEN ', já com o desconto da OS'
                     ELSE '' END
             || CASE WHEN c.pct_proprio <> c.pct_aplicado
                     THEN ' · taxa própria ' || public.formatar_percentual_comissao(c.pct_proprio) || '%'
                     ELSE '' END
           END,
           -- Servico sem comissao ja tem valor_comissao zerado pelo recalculo; o
           -- greatest e cinto de seguranca para vinculo que nunca foi recalculado
           -- depois de a flag mudar, para nao publicar despesa que nao existe.
           CASE WHEN c.comissiona THEN c.valor_comissao ELSE 0 END,
           null, c.servicoid, c.usuarioid, null, null,
           CASE WHEN c.comissiona THEN c.pct_aplicado ELSE 0 END, c.valor_base,
           jsonb_build_object(
             'realizador_nome', c.realizador_nome,
             'percentual_aplicado', CASE WHEN c.comissiona THEN c.pct_aplicado ELSE 0 END,
             'percentual_proprio', c.pct_proprio,
             'realizadores_no_servico', c.realizadores,
             'valor_servico', c.subtotal_servico,
             'gera_comissao', c.comissiona
           ),
           -- Zero nao vira transacao: nao ha o que pagar.
           c.comissiona,
           public.natureza_dre_de_evento('COMISSAO', 'DESPESA')
      FROM comissoes c;


    -- A comissao de criacao: uma linha por item da OS, do criador. Mesma
    -- granularidade da comissao de realizacao, que sempre foi um evento por
    -- (servico, realizador).
    --
    -- `produtoid`/`servicoid` saem preenchidos, e e o que permite separar
    -- comissao de produto da de servico lendo a coluna, sem interpretar chave
    -- nem snapshot. Produto avulso nao tem produtoid: o vinculo dele mora na
    -- chave de origem e em dados_snapshot.
    INSERT INTO pg_temp.eventos_os_desejados
      (origem, natureza, chave_origem, descricao, detalhe, valor, produtoid, servicoid,
       usuarioid, quantidade_snapshot, valor_unitario_snapshot, percentual_snapshot,
       valor_base_snapshot, dados_snapshot, pode_gerar_transacao, natureza_dre)
    SELECT 'COMISSAO', 'DESPESA',
           'CRIACAO:' || c.usuarioid || ':'
             || CASE c.tipo WHEN 'SERVICO' THEN 'S' WHEN 'PRODUTO' THEN 'P' ELSE 'A' END
             || c.item_id,
           'Comissão de criação - ' || coalesce(
             CASE c.tipo
               WHEN 'SERVICO' THEN
                 public.titulo_servico_os(s.descricao, os.descricao, c.item_id)
               WHEN 'PRODUTO' THEN
                 coalesce(nullif(p.titulo, ''), nullif(p.descricao, ''), 'Produto #' || c.item_id)
               ELSE coalesce(nullif(opa.titulo, ''), 'Produto avulso #' || c.item_id)
             END, 'Item #' || c.item_id),
           coalesce(u.nome, 'Criador') || ' · '
             || public.formatar_percentual_comissao(c.pct) || '%'
             || CASE c.tipo WHEN 'SERVICO' THEN ' do serviço' ELSE ' do produto' END
             || ', por ter criado a OS'
             -- Mesma frase da comissao de realizacao, pelo mesmo motivo: a base
             -- e liquida, e sem dizer isso o valor parece erro de conta.
             || CASE WHEN coalesce(
                            CASE c.tipo
                              WHEN 'SERVICO' THEN os.subtotal
                              WHEN 'PRODUTO' THEN op.subtotal
                              ELSE opa.subtotal
                            END, 0) - c.base > 0.01
                     THEN ', já com o desconto da OS'
                     ELSE '' END,
           c.valor_comissao,
           CASE WHEN c.tipo = 'PRODUTO' THEN c.item_id ELSE NULL END,
           CASE WHEN c.tipo = 'SERVICO' THEN c.item_id ELSE NULL END,
           c.usuarioid, null, null,
           c.pct, c.base,
           jsonb_build_object(
             'comissao_de_criacao', true,
             'criador_nome', coalesce(u.nome, 'Criador'),
             'tipo_item', c.tipo,
             'item_id', c.item_id,
             'base', c.base,
             'percentual', c.pct
           ),
           -- Zero nao vira transacao: nao ha o que pagar.
           c.valor_comissao > 0,
           public.natureza_dre_de_evento('COMISSAO', 'DESPESA')
      FROM public.os_comissao_criacao c
      LEFT JOIN public.usuario u ON u.id = c.usuarioid
      LEFT JOIN public.osservico os
        ON c.tipo = 'SERVICO' AND os.ordemservicoid = c.ordemservicoid AND os.servicoid = c.item_id
      LEFT JOIN public.servico s ON c.tipo = 'SERVICO' AND s.id = c.item_id
      LEFT JOIN public.osproduto op
        ON c.tipo = 'PRODUTO' AND op.ordemservicoid = c.ordemservicoid AND op.produtoid = c.item_id
      LEFT JOIN public.produto p ON c.tipo = 'PRODUTO' AND p.id = c.item_id
      LEFT JOIN public.osproduto_avulso opa
        ON c.tipo = 'PRODUTO_AVULSO' AND opa.id = c.item_id
     WHERE c.ordemservicoid = p_ordemservicoid;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.eventos_financeiros e
    LEFT JOIN pg_temp.eventos_os_desejados d
      ON d.origem = e.origem AND d.natureza = e.natureza AND d.chave_origem = e.chave_origem
    WHERE e.ordemservicoid = p_ordemservicoid
      AND e.origem <> 'AVULSO'
      AND NOT coalesce(e.is_manual, false)
      AND e.status = 'CONVERTIDO'
      AND (d.chave_origem IS NULL OR e.valor <> d.valor)
  ) THEN
    RAISE EXCEPTION 'Existem eventos convertidos divergentes. Exclua as transacoes vinculadas antes de alterar o orcamento.';
  END IF;

  INSERT INTO public.eventos_financeiros (
    ordemservicoid, origem, natureza, chave_origem, descricao, detalhe, valor,
    produtoid, servicoid, usuarioid, quantidade_snapshot, valor_unitario_snapshot,
    percentual_snapshot, valor_base_snapshot, dados_snapshot, pode_gerar_transacao,
    natureza_dre, status, updated_at
  )
  SELECT p_ordemservicoid, d.origem, d.natureza, d.chave_origem, d.descricao, d.detalhe, d.valor,
         d.produtoid, d.servicoid, d.usuarioid, d.quantidade_snapshot, d.valor_unitario_snapshot,
         d.percentual_snapshot, d.valor_base_snapshot, d.dados_snapshot, d.pode_gerar_transacao,
         d.natureza_dre, 'ATIVO', now()
  FROM pg_temp.eventos_os_desejados d
  ON CONFLICT (ordemservicoid, origem, chave_origem, natureza) DO UPDATE SET
    descricao = excluded.descricao,
    detalhe = excluded.detalhe,
    valor = excluded.valor,
    produtoid = excluded.produtoid,
    servicoid = excluded.servicoid,
    usuarioid = excluded.usuarioid,
    quantidade_snapshot = excluded.quantidade_snapshot,
    valor_unitario_snapshot = excluded.valor_unitario_snapshot,
    percentual_snapshot = excluded.percentual_snapshot,
    valor_base_snapshot = excluded.valor_base_snapshot,
    dados_snapshot = excluded.dados_snapshot,
    pode_gerar_transacao = excluded.pode_gerar_transacao,
    -- Vem da linha mapeada no template; o coalesce so protege o valor ja gravado
    -- caso uma origem fique sem mapeamento algum.
    natureza_dre = coalesce(excluded.natureza_dre, eventos_financeiros.natureza_dre),
    status = 'ATIVO',
    updated_at = now()
  WHERE eventos_financeiros.status <> 'CONVERTIDO'
    AND NOT coalesce(eventos_financeiros.is_manual, false);

  UPDATE public.eventos_financeiros e
     SET status = 'CANCELADO', updated_at = now()
   WHERE e.ordemservicoid = p_ordemservicoid
     AND e.origem <> 'AVULSO'
     AND NOT coalesce(e.is_manual, false)
     AND e.status <> 'CONVERTIDO'
     AND NOT EXISTS (
       SELECT 1
       FROM pg_temp.eventos_os_desejados d
       WHERE d.origem = e.origem
         AND d.natureza = e.natureza
         AND d.chave_origem = e.chave_origem
     );
END;
$_$;


--
-- Name: reconstruir_razao_credito_cliente(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconstruir_razao_credito_cliente(p_cliente_id integer) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_linha record;
  v_saldo numeric(14,2) := 0;
  v_depois numeric(14,2);
BEGIN
  FOR v_linha IN
    SELECT m.id, m.sentido, m.valor, m.origem, m.transacao_id,
           m.saldo_anterior, m.saldo_resultante
      FROM public.cliente_saldo_movimento m
     WHERE m.cliente_id = p_cliente_id
     ORDER BY m.id
  LOOP
    v_depois := round(
      CASE WHEN v_linha.sentido = 'CREDITO' THEN v_saldo + v_linha.valor ELSE v_saldo - v_linha.valor END,
      2
    );

    IF v_depois < 0 THEN
      IF v_linha.origem = 'TRANSACAO' AND v_linha.transacao_id IS NOT NULL THEN
        RAISE EXCEPTION
          'Este crédito já foi usado no título #%: com a alteração o cliente ficaria com R$ % negativos ali.',
          v_linha.transacao_id, to_char(-v_depois, 'FM999999990.00')
          USING ERRCODE = '22023';
      END IF;
      RAISE EXCEPTION
        'Com a alteração o saldo do cliente ficaria negativo (R$ %) no lançamento #%.',
        to_char(v_depois, 'FM999999990.00'), v_linha.id
        USING ERRCODE = '22023';
    END IF;

    IF (v_linha.saldo_anterior, v_linha.saldo_resultante) IS DISTINCT FROM (v_saldo, v_depois) THEN
      UPDATE public.cliente_saldo_movimento
         SET saldo_anterior = v_saldo,
             saldo_resultante = v_depois
       WHERE id = v_linha.id;
    END IF;

    v_saldo := v_depois;
  END LOOP;

  RETURN public.recalcular_saldo_credito_cliente(p_cliente_id);
END;
$_$;


--
-- Name: registrar_auditoria(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_auditoria() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  anterior jsonb := CASE WHEN tg_op IN ('UPDATE', 'DELETE') THEN to_jsonb(old) ELSE NULL END;
  novo jsonb := CASE WHEN tg_op IN ('INSERT', 'UPDATE') THEN to_jsonb(new) ELSE NULL END;
  anterior_alterado jsonb;
  novo_alterado jsonb;
  campos text[] := '{}'::text[];
  linha_referencia jsonb;
  ator uuid;
  contexto_externo jsonb;
  id_registro text;
BEGIN
  IF tg_op = 'UPDATE' AND anterior = novo THEN
    RETURN new;
  END IF;

  linha_referencia := coalesce(novo, anterior);

  IF tg_op = 'UPDATE' THEN
    SELECT
      coalesce(jsonb_object_agg(chave, anterior -> chave), '{}'::jsonb),
      coalesce(jsonb_object_agg(chave, novo -> chave), '{}'::jsonb),
      coalesce(array_agg(chave ORDER BY chave), '{}'::text[])
    INTO anterior_alterado, novo_alterado, campos
    FROM (
      SELECT chave
      FROM jsonb_object_keys(anterior || novo) AS chaves(chave)
      WHERE (anterior -> chave) IS DISTINCT FROM (novo -> chave)
    ) alteracoes;
  ELSIF tg_op = 'INSERT' THEN
    novo_alterado := novo;
    SELECT coalesce(array_agg(chave ORDER BY chave), '{}'::text[])
      INTO campos
    FROM jsonb_object_keys(novo) AS chaves(chave);
  ELSE
    anterior_alterado := anterior;
    SELECT coalesce(array_agg(chave ORDER BY chave), '{}'::text[])
      INTO campos
    FROM jsonb_object_keys(anterior) AS chaves(chave);
  END IF;

  ator := coalesce(
    public.auditoria_try_uuid(current_setting('app.audit_user_id', true)),
    auth.uid(),
    public.auditoria_usuario_requisicao()
  );
  contexto_externo := CASE
    WHEN ator IS NULL THEN public.auditoria_contexto_externo_requisicao()
    ELSE NULL
  END;

  IF ator IS NULL AND tg_op = 'INSERT' THEN
    ator := coalesce(
      public.auditoria_try_uuid(novo ->> 'created_by'),
      public.auditoria_try_uuid(novo ->> 'createdby'),
      public.auditoria_try_uuid(novo ->> 'usuariocriadorid')
    );
  ELSIF ator IS NULL AND tg_op = 'UPDATE' THEN
    ator := coalesce(
      public.auditoria_try_uuid(novo ->> 'updated_by'),
      public.auditoria_try_uuid(novo ->> 'updatedby'),
      public.auditoria_try_uuid(novo ->> 'usuarioalteracaoid')
    );
  ELSIF ator IS NULL AND tg_op = 'DELETE' THEN
    ator := coalesce(
      public.auditoria_try_uuid(anterior ->> 'deleted_by'),
      public.auditoria_try_uuid(anterior ->> 'updated_by'),
      public.auditoria_try_uuid(anterior ->> 'updatedby'),
      public.auditoria_try_uuid(anterior ->> 'usuarioalteracaoid')
    );
  END IF;

  IF ator IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.usuario WHERE id = ator) THEN
    ator := NULL;
  END IF;

  id_registro := coalesce(
    linha_referencia ->> 'id',
    linha_referencia ->> 'uuid',
    linha_referencia ->> 'ordemservicoid',
    linha_referencia ->> 'vendaid',
    linha_referencia ->> 'produtoid',
    linha_referencia ->> 'clienteid',
    nullif(concat_ws(':', linha_referencia ->> 'perfilid', linha_referencia ->> 'permissaoid'), '')
  );

  INSERT INTO public.auditoria_evento (
    operacao,
    modulo,
    tabela,
    registro_id,
    usuario_id,
    ator_nome,
    dados_anteriores,
    dados_novos,
    campos_alterados,
    origem
  ) VALUES (
    tg_op,
    public.auditoria_modulo_tabela(tg_table_name),
    tg_table_name,
    id_registro,
    ator,
    contexto_externo ->> 'nome',
    public.auditoria_json_seguro(anterior_alterado),
    public.auditoria_json_seguro(novo_alterado),
    campos,
    CASE
      WHEN ator IS NOT NULL THEN 'usuario'
      WHEN contexto_externo ->> 'origem' = 'cliente' THEN 'cliente'
      ELSE 'sistema'
    END
  );

  IF tg_op = 'DELETE' THEN
    RETURN old;
  END IF;
  RETURN new;
EXCEPTION WHEN others THEN
  RAISE WARNING 'Falha ao auditar %.%: %', tg_table_schema, tg_table_name, sqlerrm;
  IF tg_op = 'DELETE' THEN
    RETURN old;
  END IF;
  RETURN new;
END;
$$;


--
-- Name: transacao; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transacao (
    id bigint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    descricao text NOT NULL,
    valor numeric(14,2) NOT NULL,
    data timestamp with time zone NOT NULL,
    metodopagamento public.metodo_pagamento,
    categoria text DEFAULT 'NÃO RELACIONADO'::text NOT NULL,
    tipo public.tipos_transacao NOT NULL,
    cliente_id integer,
    banco_id bigint,
    nomepagador text NOT NULL,
    cpfcnpjpagador text NOT NULL,
    ordemservicoid integer,
    "valorLiquido" numeric,
    vendaid integer,
    pendente boolean DEFAULT false NOT NULL,
    created_by uuid,
    updated_by uuid,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    categoria_id integer,
    plano_de_conta_id integer,
    plano_de_conta text,
    centro_custo_id integer,
    centro_custo text,
    entrada_id bigint,
    estorno_transacao_id bigint,
    evento_financeiro_id bigint,
    vencimento_em timestamp with time zone,
    pago_em timestamp with time zone,
    baixado_por uuid,
    usoconsumo_entrada_id bigint,
    origem text,
    fornecedor_id integer,
    parcelas integer DEFAULT 1 NOT NULL,
    competencia_em timestamp with time zone,
    descricao_pagamento text,
    valor_base numeric(14,2) DEFAULT 0,
    valor_acrescimos numeric(14,2) DEFAULT 0 NOT NULL,
    valor_descontos numeric(14,2) DEFAULT 0 NOT NULL,
    adiantamento_id bigint,
    eh_adiantamento boolean DEFAULT false NOT NULL,
    documento_tipo_id integer,
    documento_numero text,
    documento_serie text,
    documento_chave text,
    documento_emitido_em date,
    documento_valor numeric(14,2),
    documento_observacao text,
    pagamento_multiplo_id bigint,
    parcelamento_id bigint,
    adiantamento_manteve_pendentes boolean,
    bandeira_id integer,
    bandeira_parcelas smallint,
    bandeira_taxa_percentual numeric(6,4),
    bandeira_taxa_ajustada boolean DEFAULT false NOT NULL,
    baixa_de_transacao_id bigint,
    valor_baixado numeric(14,2) DEFAULT 0 NOT NULL,
    transferencia_id bigint,
    lancamento_id bigint,
    data_dia date GENERATED ALWAYS AS (((data AT TIME ZONE '-03:00:00'::interval))::date) STORED,
    movimento_registrado_em timestamp with time zone DEFAULT now() NOT NULL,
    abonado boolean DEFAULT false NOT NULL,
    abonado_por uuid,
    abonado_em timestamp with time zone,
    abono_motivo text,
    CONSTRAINT transacao_adiantamento_nao_circular_check CHECK (((adiantamento_id IS NULL) OR (adiantamento_id <> id))),
    CONSTRAINT transacao_adiantamento_um_nivel_check CHECK ((NOT (eh_adiantamento AND (adiantamento_id IS NOT NULL)))),
    CONSTRAINT transacao_ajustes_nao_negativos_check CHECK (((valor_acrescimos >= (0)::numeric) AND (valor_descontos >= (0)::numeric))),
    CONSTRAINT transacao_bandeira_coerente CHECK (((bandeira_id IS NOT NULL) OR ((bandeira_parcelas IS NULL) AND (bandeira_taxa_percentual IS NULL) AND (bandeira_taxa_ajustada = false)))),
    CONSTRAINT transacao_documento_tipo_obrigatorio CHECK (((documento_tipo_id IS NOT NULL) OR ((documento_numero IS NULL) AND (documento_serie IS NULL) AND (documento_chave IS NULL) AND (documento_emitido_em IS NULL) AND (documento_valor IS NULL) AND (documento_observacao IS NULL)))),
    CONSTRAINT transacao_documento_valor_nao_negativo CHECK (((documento_valor IS NULL) OR (documento_valor >= (0)::numeric))),
    CONSTRAINT transacao_parcelas_check CHECK ((parcelas >= 1))
);


--
-- Name: COLUMN transacao.fornecedor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.fornecedor_id IS 'Fornecedor vinculado ao lancamento. Mutuamente exclusivo com cliente_id: ambos alimentam nomepagador/cpfcnpjpagador.';


--
-- Name: COLUMN transacao.competencia_em; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.competencia_em IS 'Data de competencia (regime economico). Define o periodo na DRE, ao contrario de `data`/`pago_em`, que sao de caixa. Backfill inicial copiou `data`.';


--
-- Name: COLUMN transacao.descricao_pagamento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.descricao_pagamento IS 'Texto livre sobre o pagamento em si, informado por quem registrou a transacao. Preservado integralmente em cada parcela.';


--
-- Name: COLUMN transacao.valor_base; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.valor_base IS 'Valor de face, antes dos acrescimos. valor = valor_base + valor_acrescimos.';


--
-- Name: COLUMN transacao.valor_acrescimos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.valor_acrescimos IS 'Soma das linhas de acrescimo em transacao_ajuste. Mantida por gatilho.';


--
-- Name: COLUMN transacao.valor_descontos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.valor_descontos IS 'Soma das linhas de desconto em transacao_ajuste. Mantida por gatilho.';


--
-- Name: COLUMN transacao.adiantamento_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.adiantamento_id IS 'Nas parcelas liquidadas por antecipacao, aponta para a transacao de adiantamento que trouxe o dinheiro.';


--
-- Name: COLUMN transacao.eh_adiantamento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.eh_adiantamento IS 'true na transacao que representa o movimento unico de dinheiro da antecipacao.';


--
-- Name: COLUMN transacao.documento_numero; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.documento_numero IS 'Numero do documento (nota, recibo, boleto). Livre: cada emissor formata do seu jeito.';


--
-- Name: COLUMN transacao.documento_chave; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.documento_chave IS 'Chave de acesso da NF-e/NFS-e ou codigo de verificacao. Nao e validado nem conferido na SEFAZ.';


--
-- Name: COLUMN transacao.pagamento_multiplo_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.pagamento_multiplo_id IS 'Grupo do pagamento múltiplo a que esta linha pertence. Nulo em lançamento avulso.';


--
-- Name: COLUMN transacao.parcelamento_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.parcelamento_id IS 'Parcelamento avulso a que esta linha pertence. Nulo em lancamento a vista e em parcela de OS, venda ou pagamento multiplo.';


--
-- Name: COLUMN transacao.adiantamento_manteve_pendentes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.adiantamento_manteve_pendentes IS 'Só na antecipação (eh_adiantamento): true quando os títulos ficaram em aberto para a cobrança acompanhar, false quando foram liquidados no ato. É o que decide se a baixa de um título antecipado é dele sozinho (estornável) ou do conjunto (só desfazendo a antecipação).';


--
-- Name: COLUMN transacao.bandeira_parcelas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.bandeira_parcelas IS 'Em quantas vezes o cliente passou no cartao. Nem sempre igual ao numero de parcelas da transacao: no recebimento a vista o dinheiro entra de uma vez e este campo guarda o parcelamento que o cliente fez na maquineta.';


--
-- Name: COLUMN transacao.bandeira_taxa_percentual; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.bandeira_taxa_percentual IS 'Percentual usado no lancamento, congelado. Mudar a tabela da bandeira nao reescreve o que ja foi registrado.';


--
-- Name: COLUMN transacao.bandeira_taxa_ajustada; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.bandeira_taxa_ajustada IS 'O usuario destravou o liquido calculado e digitou outro valor por cima da tabela da bandeira.';


--
-- Name: COLUMN transacao.baixa_de_transacao_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.baixa_de_transacao_id IS 'Esta linha é o dinheiro que entrou ou saiu numa baixa parcial daquele título. Nula em lançamento comum. O título apontado carrega o saldo em valor_baixado.';


--
-- Name: COLUMN transacao.valor_baixado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.valor_baixado IS 'Quanto das baixas parciais já cobriu este título. O saldo em aberto é valorLiquido - valor_baixado. Mantida pelo gatilho transacao_baixa_parcial_trg; não escrever à mão.';


--
-- Name: COLUMN transacao.transferencia_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.transferencia_id IS 'Transferencia entre contas de que esta linha e uma das pernas. Nula em lancamento comum. Escrita somente por registrar_transferencia_entre_contas; nao preencher a mao.';


--
-- Name: COLUMN transacao.lancamento_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.lancamento_id IS 'Lancamento de despesas de OS a que esta parcela pertence. Nulo em tudo o mais. CASCADE de proposito: some o grupo, somem as parcelas — a reversao e tudo-ou-nada. Quando preenchido, evento_financeiro_id fica nulo: quem liga a despesa e o grupo.';


--
-- Name: COLUMN transacao.data_dia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.data_dia IS 'O dia local (-03:00) de `data`. Existe porque `data` carrega horas que variam conforme o caminho que criou a linha (meia-noite, meio-dia ou now()), e ordenar por ela misturava a ordem dentro do dia. Gerada: não se escreve.';


--
-- Name: COLUMN transacao.movimento_registrado_em; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.movimento_registrado_em IS 'Quando o movimento foi registrado no sistema, em relógio de verdade — diferente de `pago_em`, que é o dia informado pelo operador, e de `updated_at`, que qualquer edição posterior move. É o que ordena as linhas dentro de um mesmo dia no Fluxo.';


--
-- Name: COLUMN transacao.abonado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.abonado IS 'Título a receber perdoado sem passar pelo banco. pendente=false e banco_id=NULL, igual ao título quitado por antecipação — a diferença é que aqui nenhum dinheiro entrou em lugar nenhum.';


--
-- Name: COLUMN transacao.abonado_por; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.abonado_por IS 'Quem abonou a cobrança.';


--
-- Name: COLUMN transacao.abonado_em; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.abonado_em IS 'Quando a cobrança foi abonada.';


--
-- Name: COLUMN transacao.abono_motivo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.transacao.abono_motivo IS 'Motivo do abono, texto livre e opcional.';


--
-- Name: registrar_baixa_filha(public.transacao, numeric, timestamp with time zone, bigint, public.metodo_pagamento, integer, integer, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_baixa_filha(p_titulo public.transacao, p_valor numeric, p_pago_em timestamp with time zone, p_banco_id bigint, p_metodo public.metodo_pagamento, p_plano_de_conta_id integer, p_centro_custo_id integer, p_baixado_por uuid, p_repasse boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
BEGIN
  INSERT INTO public.transacao (
    descricao, valor, valor_base, "valorLiquido",
    valor_acrescimos, valor_descontos,
    data, competencia_em, vencimento_em, pago_em,
    tipo, pendente, banco_id, metodopagamento,
    categoria, categoria_id,
    plano_de_conta_id, centro_custo_id,
    cliente_id, fornecedor_id, nomepagador, cpfcnpjpagador,
    baixa_de_transacao_id, created_by, baixado_por
  ) VALUES (
    CASE WHEN p_repasse THEN 'Repasse do título #' ELSE 'Pagamento do título #' END
      || p_titulo.id || ' — '
      || coalesce(nullif(btrim(p_titulo.descricao), ''), 'sem descrição'),
    round(p_valor, 2), round(p_valor, 2), round(p_valor, 2),
    0, 0,
    p_pago_em, coalesce(p_titulo.competencia_em, p_pago_em),
    coalesce(p_titulo.vencimento_em, p_titulo.data), p_pago_em,
    p_titulo.tipo, false, p_banco_id, p_metodo,
    p_titulo.categoria, p_titulo.categoria_id,
    coalesce(p_plano_de_conta_id, p_titulo.plano_de_conta_id),
    coalesce(p_centro_custo_id, p_titulo.centro_custo_id),
    p_titulo.cliente_id, p_titulo.fornecedor_id,
    p_titulo.nomepagador, p_titulo.cpfcnpjpagador,
    -- Sem `ordemservicoid`/`vendaid` e sem `adiantamento_id`: a filha é
    -- movimento de caixa, e carregar o vínculo do documento a faria contar como
    -- recebimento dele, em cima do título que já conta.
    p_titulo.id, p_baixado_por, p_baixado_por
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: registrar_consulta_placa_empresa(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_consulta_placa_empresa(p_empresa_id integer DEFAULT NULL::integer) RETURNS TABLE(permitido boolean, empresa_id integer, limite integer, usadas integer, mes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_empresa_id integer;
  v_mes text := to_char(timezone('America/Sao_Paulo', now()), 'YYYY-MM');
begin
  select e.id
    into v_empresa_id
    from public.empresa e
   where p_empresa_id is null or e.id = p_empresa_id
   order by e.id
   limit 1
   for update;

  if v_empresa_id is null then
    return;
  end if;

  update public.empresa e
     set placa_consulta_qtd_mes = case
           when e.placa_consulta_mes <> v_mes then 0
           else e.placa_consulta_qtd_mes
         end,
         placa_consulta_mes = v_mes
   where e.id = v_empresa_id;

  return query
  update public.empresa e
     set placa_consulta_qtd_mes = e.placa_consulta_qtd_mes + 1,
         updatedat = now()
   where e.id = v_empresa_id
     and e.placa_consulta_qtd_mes < e.placa_consulta_limite_mensal
   returning
     true,
     e.id,
     e.placa_consulta_limite_mensal,
     e.placa_consulta_qtd_mes,
     e.placa_consulta_mes;

  if not found then
    return query
    select
      false,
      e.id,
      e.placa_consulta_limite_mensal,
      e.placa_consulta_qtd_mes,
      e.placa_consulta_mes
    from public.empresa e
    where e.id = v_empresa_id;
  end if;
end;
$$;


--
-- Name: registrar_consumo_produto_os(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_consumo_produto_os(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_os_id       integer := nullif(p_payload->>'ordemservicoid', '')::integer;
  v_escopo      text    := upper(btrim(coalesce(p_payload->>'escopo', '')));
  v_item_id     integer := nullif(p_payload->>'item_id', '')::integer;
  v_quantidade  integer := nullif(p_payload->>'quantidade', '')::integer;
  v_observacao  text    := nullif(btrim(coalesce(p_payload->>'observacao', '')), '');
  v_descricao   text    := nullif(btrim(coalesce(p_payload->>'descricao', '')), '');
  v_detalhe     text    := nullif(btrim(coalesce(p_payload->>'detalhe', '')), '');
  v_valor       numeric(14,2) := nullif(p_payload->>'valor', '')::numeric;
  v_pode_gerar  boolean := coalesce((p_payload->>'pode_gerar_transacao')::boolean, false);
  v_user        uuid    := nullif(p_payload->>'created_by', '')::uuid;
  v_status_os   text;
  v_saida       jsonb;
  v_saida_id    bigint;
  v_custo       numeric(14,4);
  v_saldo       integer;
  v_titulo      text;
  v_unidade     text;
  v_valor_base  numeric(14,2);
  v_editado     boolean := false;
  v_evento_id   bigint;
BEGIN
  IF v_os_id IS NULL OR v_os_id <= 0 THEN
    RAISE EXCEPTION 'Informe a ordem de servico.' USING ERRCODE = '22023';
  END IF;
  IF v_escopo NOT IN ('PRODUTO', 'USOCONSUMO', 'GERAL') THEN
    RAISE EXCEPTION 'Estoque invalido: %.', v_escopo USING ERRCODE = '22023';
  END IF;
  IF v_item_id IS NULL OR v_item_id <= 0 THEN
    RAISE EXCEPTION 'Selecione o item consumido.' USING ERRCODE = '22023';
  END IF;
  IF v_quantidade IS NULL OR v_quantidade <= 0 THEN
    RAISE EXCEPTION 'A quantidade deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;
  IF v_valor IS NOT NULL AND v_valor < 0 THEN
    RAISE EXCEPTION 'O valor da despesa nao pode ser negativo.' USING ERRCODE = '22023';
  END IF;

  SELECT o.status::text INTO v_status_os
    FROM public.ordemservico o
   WHERE o.id = v_os_id AND coalesce(o.is_deleted, false) = false;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OS nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  -- Os tres primeiros sao a mesma regra do POST de eventos financeiros. O quarto
  -- entra porque ORCAMENTO_RECUSADO e um estado em que o estoque esta voltando.
  IF v_status_os IN ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO', 'ORCAMENTO_RECUSADO') THEN
    RAISE EXCEPTION 'Nao e possivel registrar consumo numa OS com status %.',
      replace(v_status_os, '_', ' ') USING ERRCODE = 'P0001';
  END IF;

  IF v_escopo = 'PRODUTO' THEN
    SELECT p.titulo, p.unidade::text INTO v_titulo, v_unidade
      FROM public.produto p
     WHERE p.id = v_item_id AND coalesce(p.is_deleted, false) = false;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Produto nao encontrado.' USING ERRCODE = 'P0002';
    END IF;

    -- A RPC inteira, e nao um recorte dela: e ela que trava a linha, confere o
    -- saldo e carimba a origem no razao.
    v_saida := public.registrar_saida_estoque(
      v_item_id, v_quantidade, 'CONSUMO_EM_OS', v_observacao, v_user
    );
    v_saida_id := (v_saida->>'saida_id')::bigint;
    v_saldo    := (v_saida->>'saldo_resultante')::integer;

    UPDATE public.estoque_saida SET ordemservicoid = v_os_id WHERE id = v_saida_id;

    SELECT i.valor_custo_aplicado INTO v_custo
      FROM public.estoque_saida_item i
     WHERE i.saida_id = v_saida_id AND i.produto_id = v_item_id;
  ELSE
    SELECT i.titulo, i.unidade::text INTO v_titulo, v_unidade
      FROM public.usoconsumo_item i
     WHERE i.id = v_item_id AND i.ativo AND i.escopo = v_escopo;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item nao encontrado neste estoque.' USING ERRCODE = 'P0002';
    END IF;

    v_saida := public.registrar_saida_usoconsumo(
      jsonb_build_object(
        'escopo', v_escopo, 'motivo', 'CONSUMO_EM_OS',
        'observacao', v_observacao, 'created_by', v_user
      ),
      jsonb_build_array(jsonb_build_object('item_id', v_item_id, 'quantidade', v_quantidade))
    );
    v_saida_id := (v_saida->>'saida_id')::bigint;

    UPDATE public.usoconsumo_saida SET ordemservicoid = v_os_id WHERE id = v_saida_id;

    SELECT i.valor_custo_aplicado, i.saldo_resultante INTO v_custo, v_saldo
      FROM public.usoconsumo_saida_item i
     WHERE i.saida_id = v_saida_id AND i.item_id = v_item_id;
  END IF;

  -- O custo do cadastro e a base; o valor informado a mao e o escape, e ele
  -- marca a linha para a correcao nao passar despercebida.
  v_valor_base := round(coalesce(v_custo, 0) * v_quantidade, 2);
  IF v_valor IS NULL THEN
    v_valor := v_valor_base;
  ELSE
    v_valor := round(v_valor, 2);
    v_editado := v_valor IS DISTINCT FROM v_valor_base;
  END IF;

  v_titulo := coalesce(nullif(btrim(coalesce(v_titulo, '')), ''), 'Item #' || v_item_id);

  INSERT INTO public.eventos_financeiros (
    ordemservicoid, source_type, source_id, source_item_id,
    origem, natureza, natureza_dre, chave_origem,
    descricao, detalhe, valor,
    produtoid, quantidade_snapshot, valor_unitario_snapshot,
    is_manual, pode_gerar_transacao,
    consumo_saida_id, consumo_usoconsumo_saida_id,
    dados_snapshot, created_by
  ) VALUES (
    v_os_id, 'ORDEM_SERVICO', v_os_id, v_item_id,
    'CONSUMO', 'DESPESA', 'CUSTO', 'CONSUMO:' || v_saida_id,
    coalesce(v_descricao, 'Consumo - ' || v_titulo),
    coalesce(
      v_detalhe,
      v_quantidade || ' ' || coalesce(v_unidade, 'UN')
        || ' - ' || CASE v_escopo
                      WHEN 'PRODUTO'    THEN 'Estoque de produtos'
                      WHEN 'USOCONSUMO' THEN 'Uso e consumo'
                      ELSE 'Geral/Avulso'
                    END
    ),
    v_valor,
    CASE WHEN v_escopo = 'PRODUTO' THEN v_item_id END,
    v_quantidade, coalesce(v_custo, 0),
    true, v_pode_gerar,
    CASE WHEN v_escopo = 'PRODUTO' THEN v_saida_id END,
    CASE WHEN v_escopo <> 'PRODUTO' THEN v_saida_id END,
    jsonb_build_object(
      'consumo_de_estoque', true,
      'escopo', v_escopo,
      'item_id', v_item_id,
      'item_titulo', v_titulo,
      'unidade', coalesce(v_unidade, 'UN'),
      'saida_id', v_saida_id,
      'custo_unitario', coalesce(v_custo, 0),
      'valor_base', v_valor_base,
      'valor_editado', v_editado,
      'observacao', v_observacao
    ),
    v_user
  ) RETURNING id INTO v_evento_id;

  RETURN jsonb_build_object(
    'evento_id', v_evento_id,
    'saida_id', v_saida_id,
    'escopo', v_escopo,
    'valor', v_valor,
    'saldo_resultante', v_saldo
  );
END;
$$;


--
-- Name: registrar_entrada_comercial_apropriada(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_comercial_apropriada(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_item jsonb;
  v_documento_id bigint:=nullif(p_entrada->>'fiscal_dfe_documento_id','')::bigint;
  v_numero_item integer;
  v_user uuid:=nullif(p_entrada->>'created_by','')::uuid;
BEGIN
  SELECT public.registrar_entrada_confirmada(p_entrada,p_itens,p_transacoes) INTO v_result;
  IF v_documento_id IS NOT NULL THEN
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
      v_numero_item:=nullif(v_item->>'numero_item_fiscal','')::integer;
      IF v_numero_item IS NULL THEN
        RAISE EXCEPTION 'Informe o numero fiscal de todos os itens apropriados.' USING ERRCODE='22023';
      END IF;
      INSERT INTO public.fiscal_dfe_item_apropriacao(
        documento_id,numero_item,destino,entrada_id,quantidade,created_by
      ) VALUES(
        v_documento_id,v_numero_item,'PRODUTO',(v_result->>'entrada_id')::bigint,
        (v_item->>'quantidade')::numeric,v_user
      );
    END LOOP;
  END IF;
  RETURN v_result;
END $$;


--
-- Name: registrar_entrada_confirmada(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_confirmada(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_entrada_id bigint;
  v_item record;
  v_entrada_item_id bigint;
  v_numero_item integer;
  v_competencia timestamptz;
BEGIN
  SELECT public.registrar_entrada_confirmada_sem_numero_item(
    p_entrada,
    p_itens,
    p_transacoes
  ) INTO v_result;
  v_entrada_id := (v_result->>'entrada_id')::bigint;

  FOR v_item IN
    SELECT value, ordinality
      FROM jsonb_array_elements(p_itens) WITH ORDINALITY
  LOOP
    v_numero_item := nullif(v_item.value->>'numero_item_fiscal', '')::integer;
    IF v_numero_item IS NOT NULL AND (v_numero_item < 1 OR v_numero_item > 990) THEN
      RAISE EXCEPTION 'O número fiscal do item deve ficar entre 1 e 990.' USING ERRCODE = '22023';
    END IF;

    SELECT id
      INTO v_entrada_item_id
      FROM public.entradaitens
     WHERE entrada_id = v_entrada_id
     ORDER BY id
     OFFSET (v_item.ordinality - 1)
     LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Não foi possível reconciliar os itens da entrada fiscal.' USING ERRCODE = '23514';
    END IF;

    UPDATE public.entradaitens
       SET numero_item_fiscal = v_numero_item
     WHERE id = v_entrada_item_id;
  END LOOP;

  IF p_entrada ? 'tributos' THEN
    SELECT coalesce(data_emissao, created_at) INTO v_competencia
      FROM public.entrada WHERE id = v_entrada_id;
    PERFORM public.registrar_eventos_dre_entrada(
      'ENTRADA', v_entrada_id, v_competencia, p_entrada->'tributos',
      nullif(p_entrada->>'created_by', '')::uuid
    );
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: registrar_entrada_confirmada_sem_numero_item(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_confirmada_sem_numero_item(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entrada_id bigint;
  v_item jsonb;
  v_item_id bigint;
  v_produto public.produto%ROWTYPE;
  v_produto_id integer;
  v_quantidade integer;
  v_custo numeric(14,4);
  v_desconto numeric(14,2);
  v_frete numeric(14,2);
  v_outras numeric(14,2);
  v_total_item numeric(14,2);
  v_total numeric(14,2) := 0;
  v_total_documento numeric(14,2) := nullif(p_entrada->>'valor_total_documento', '')::numeric;
  v_total_financeiro numeric(14,2) := 0;
  v_transacao jsonb;
  v_chave text := nullif(regexp_replace(coalesce(p_entrada->>'notachave', ''), '\D', '', 'g'), '');
  v_fiscal boolean := coalesce((p_entrada->>'fiscal')::boolean, false);
  v_origem text := coalesce(nullif(p_entrada->>'origem', ''), 'MANUAL');
  v_created_by uuid := nullif(p_entrada->>'created_by', '')::uuid;
BEGIN
  IF jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Informe ao menos um item para a entrada.' USING ERRCODE = '22023';
  END IF;

  IF v_origem NOT IN ('AJUSTE_RAPIDO', 'MANUAL', 'NFE_TERCEIRO') THEN
    RAISE EXCEPTION 'Origem da entrada inválida.' USING ERRCODE = '22023';
  END IF;
  IF v_total_documento IS NOT NULL AND v_total_documento < 0 THEN
    RAISE EXCEPTION 'O total do documento fiscal não pode ser negativo.' USING ERRCODE = '22023';
  END IF;

  IF v_fiscal AND (v_chave IS NULL OR length(v_chave) <> 44) THEN
    RAISE EXCEPTION 'A entrada fiscal exige uma chave de acesso com 44 dígitos.' USING ERRCODE = '22023';
  END IF;
  IF v_fiscal AND nullif(p_entrada->>'fornecedorid', '') IS NULL THEN
    RAISE EXCEPTION 'A entrada fiscal exige um fornecedor vinculado.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.entrada (
    fornecedorid, fiscal, notachave, tipo, status, origem,
    numero_nota, serie_nota, data_emissao, fiscal_dfe_documento_id, valor_total,
    created_by, observacao
  ) VALUES (
    nullif(p_entrada->>'fornecedorid', '')::integer,
    v_fiscal,
    v_chave,
    coalesce(nullif(p_entrada->>'tipo', ''), 'COMPRA_FORNECEDOR'),
    'CONFIRMADA'::public.enum_status_entrada,
    v_origem,
    nullif(p_entrada->>'numero_nota', ''),
    nullif(p_entrada->>'serie_nota', ''),
    nullif(p_entrada->>'data_emissao', '')::timestamp with time zone,
    nullif(p_entrada->>'fiscal_dfe_documento_id', '')::bigint,
    0,
    v_created_by,
    nullif(btrim(coalesce(p_entrada->>'observacao', '')), '')
  ) RETURNING id INTO v_entrada_id;

  PERFORM public.estoque_definir_contexto(
    'ENTRADA', v_entrada_id, 'Entrada #' || v_entrada_id, v_created_by
  );

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens)
  LOOP
    v_produto_id := nullif(v_item->>'produto_id', '')::integer;
    v_quantidade := nullif(v_item->>'quantidade', '')::integer;
    v_custo := nullif(v_item->>'valor_unitario_compra', '')::numeric;
    v_desconto := coalesce(nullif(v_item->>'valor_desconto', '')::numeric, 0);
    v_frete := coalesce(nullif(v_item->>'valor_frete', '')::numeric, 0);
    v_outras := coalesce(nullif(v_item->>'outras_despesas', '')::numeric, 0);

    IF v_produto_id IS NULL OR v_quantidade IS NULL OR v_quantidade <= 0 THEN
      RAISE EXCEPTION 'Produto e quantidade inteira positiva são obrigatórios.' USING ERRCODE = '22023';
    END IF;
    IF v_custo IS NULL OR v_custo < 0 OR v_desconto < 0 OR v_frete < 0 OR v_outras < 0 THEN
      RAISE EXCEPTION 'Os valores de compra do item são inválidos.' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_produto FROM public.produto WHERE id = v_produto_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Produto % não encontrado.', v_produto_id USING ERRCODE = 'P0002';
    END IF;

    v_total_item := round((v_quantidade * v_custo) - v_desconto + v_frete + v_outras, 2);
    IF v_total_item < 0 THEN
      RAISE EXCEPTION 'O total do item não pode ser negativo.' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.entradaitens (
      entrada_id, produto_id, quantidade, precovenda, unidade,
      valor_unitario_compra, valor_desconto, valor_frete, outras_despesas, valor_total,
      ncm, cest, csosn, referencia, titulo, "cClassTrib", "cstIbs", "cstCbs",
      cst, aliquotaicms, cfop, cst_pis, aliquota_pis, cst_cofins, aliquota_cofins
    ) VALUES (
      v_entrada_id, v_produto_id, v_quantidade, coalesce(v_produto.precovenda, 0),
      coalesce(nullif(v_item->>'unidade', '')::public.unidade_medida, v_produto.unidade, 'UN'),
      v_custo, v_desconto, v_frete, v_outras, v_total_item,
      coalesce(nullif(v_item->>'ncm', ''), v_produto.ncm),
      coalesce(nullif(v_item->>'cest', ''), v_produto.cest),
      coalesce(nullif(v_item->>'csosn', ''), v_produto.csosn),
      coalesce(nullif(v_item->>'referencia', ''), v_produto.referencia),
      coalesce(nullif(v_item->>'titulo', ''), v_produto.titulo),
      coalesce(nullif(v_item->>'cClassTrib', ''), v_produto."cClassTrib"),
      coalesce(nullif(v_item->>'cstIbs', ''), v_produto."cstIbs"),
      coalesce(nullif(v_item->>'cstCbs', ''), v_produto."cstCbs"),
      coalesce(nullif(v_item->>'cst', ''), v_produto.cst),
      coalesce(nullif(v_item->>'aliquotaicms', '')::numeric, v_produto.aliquotaicms),
      coalesce(nullif(v_item->>'cfop', ''), v_produto.cfop),
      coalesce(nullif(v_item->>'cst_pis', ''), v_produto.cst_pis),
      coalesce(nullif(v_item->>'aliquota_pis', '')::numeric, v_produto.aliquota_pis),
      coalesce(nullif(v_item->>'cst_cofins', ''), v_produto.cst_cofins),
      coalesce(nullif(v_item->>'aliquota_cofins', '')::numeric, v_produto.aliquota_cofins)
    ) RETURNING id INTO v_item_id;

    UPDATE public.produto
    SET estoque = coalesce(estoque, 0) + v_quantidade,
        ultimovalordecompra = v_custo,
        updatedat = now()
    WHERE id = v_produto_id;

    INSERT INTO public.estoque_movimento_entrada (
      entrada_id, entrada_item_id, produto_id, tipo, quantidade,
      saldo_anterior, saldo_resultante, valor_unitario_compra
    ) VALUES (
      v_entrada_id, v_item_id, v_produto_id, 'ENTRADA', v_quantidade,
      coalesce(v_produto.estoque, 0), coalesce(v_produto.estoque, 0) + v_quantidade, v_custo
    );

    v_total := v_total + v_total_item;
  END LOOP;

  UPDATE public.entrada
  SET valor_total = round(coalesce(v_total_documento, v_total), 2)
  WHERE id = v_entrada_id;

  IF p_transacoes IS NOT NULL AND jsonb_typeof(p_transacoes) = 'array'
     AND jsonb_array_length(p_transacoes) > 0 THEN
    SELECT round(coalesce(sum((value->>'valor')::numeric), 0), 2)
      INTO v_total_financeiro
    FROM jsonb_array_elements(p_transacoes);
    IF v_total_financeiro <> round(coalesce(v_total_documento, v_total), 2) THEN
      RAISE EXCEPTION 'A soma dos lançamentos financeiros (%) difere do total da entrada (%).',
        v_total_financeiro, round(coalesce(v_total_documento, v_total), 2) USING ERRCODE = '22023';
    END IF;

    FOR v_transacao IN SELECT value FROM jsonb_array_elements(p_transacoes)
    LOOP
      IF coalesce((v_transacao->>'valor')::numeric, 0) <= 0 THEN
        RAISE EXCEPTION 'O valor do lançamento financeiro deve ser positivo.' USING ERRCODE = '22023';
      END IF;
      INSERT INTO public.transacao (
        descricao, valor, "valorLiquido", data, metodopagamento, categoria, categoria_id,
        tipo, cliente_id, banco_id, nomepagador, cpfcnpjpagador, pendente,
        plano_de_conta_id, plano_de_conta, centro_custo_id, centro_custo, entrada_id
      ) VALUES (
        coalesce(nullif(v_transacao->>'descricao', ''), 'Compra de mercadorias'),
        (v_transacao->>'valor')::numeric,
        (v_transacao->>'valor')::numeric,
        coalesce(nullif(v_transacao->>'data', '')::timestamp with time zone, now()),
        nullif(v_transacao->>'metodopagamento', '')::public.metodo_pagamento,
        coalesce(nullif(v_transacao->>'categoria', ''), 'NÃO RELACIONADO'),
        nullif(v_transacao->>'categoria_id', '')::integer,
        'DESPESA'::public.tipos_transacao,
        NULL,
        nullif(v_transacao->>'banco_id', '')::bigint,
        coalesce(nullif(v_transacao->>'nomepagador', ''), 'Fornecedor'),
        coalesce(nullif(regexp_replace(v_transacao->>'cpfcnpjpagador', '\D', '', 'g'), ''), 'NÃO INFORMADO'),
        coalesce((v_transacao->>'pendente')::boolean, false),
        nullif(v_transacao->>'plano_de_conta_id', '')::integer,
        nullif(v_transacao->>'plano_de_conta', ''),
        nullif(v_transacao->>'centro_custo_id', '')::integer,
        nullif(v_transacao->>'centro_custo', ''),
        v_entrada_id
      );
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'entrada_id', v_entrada_id,
    'valor_total', round(coalesce(v_total_documento, v_total), 2)
  );
END;
$$;


--
-- Name: registrar_entrada_fiscal_hibrida(jsonb, jsonb, jsonb, jsonb, jsonb, jsonb, numeric, numeric, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_fiscal_hibrida(p_entrada_produto jsonb, p_itens_produto jsonb, p_entrada_usoconsumo jsonb, p_itens_usoconsumo jsonb, p_apropriacoes jsonb, p_auditoria jsonb, p_custo_total numeric, p_custo_personalizado numeric, p_total_documento numeric, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tem_produto boolean := jsonb_typeof(p_itens_produto) = 'array'
    AND jsonb_array_length(p_itens_produto) > 0;
  v_tem_uso boolean := jsonb_typeof(p_itens_usoconsumo) = 'array'
    AND jsonb_array_length(p_itens_usoconsumo) > 0;
  v_documento_produto bigint := nullif(p_entrada_produto->>'fiscal_dfe_documento_id', '')::bigint;
  v_documento_uso bigint := nullif(p_entrada_usoconsumo->>'documento_fiscal_recebido_id', '')::bigint;
  v_documento_id bigint;
  v_destino_personalizado text := upper(btrim(coalesce(p_auditoria->>'destino', '')));
  v_created_by uuid := coalesce(
    nullif(p_entrada_produto->>'created_by', '')::uuid,
    nullif(p_entrada_usoconsumo->>'created_by', '')::uuid
  );
  v_resultado_produto jsonb;
  v_resultado_uso jsonb;
  v_entrada_id bigint;
  v_usoconsumo_entrada_id bigint;
  v_apropriacao jsonb;
  v_numero_item integer;
  v_quantidade numeric(14,4);
  v_destino_apropriacao text;
  v_numeros integer[] := ARRAY[]::integer[];
  v_ocorrencias integer;
  v_total_fisico numeric(14,2);
  v_total_custom_auditoria numeric(14,2);
  v_total_custom_item numeric(14,2);
  v_total_financeiro numeric(14,2);
  v_transacao jsonb;
BEGIN
  IF jsonb_typeof(p_itens_produto) <> 'array'
     OR jsonb_typeof(p_itens_usoconsumo) <> 'array' THEN
    RAISE EXCEPTION 'As listas fisicas da entrada hibrida sao invalidas.' USING ERRCODE = '22023';
  END IF;
  IF NOT v_tem_produto AND NOT v_tem_uso THEN
    RAISE EXCEPTION 'A entrada hibrida exige ao menos um item fisico.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_apropriacoes) <> 'array' OR jsonb_array_length(p_apropriacoes) < 2 THEN
    RAISE EXCEPTION 'A entrada hibrida exige todas as linhas fiscais da NF-e.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_auditoria) <> 'object'
     OR jsonb_typeof(p_auditoria->'itens_originais') <> 'array'
     OR jsonb_array_length(p_auditoria->'itens_originais') = 0 THEN
    RAISE EXCEPTION 'Informe as linhas consolidadas da entrada personalizada.' USING ERRCODE = '22023';
  END IF;
  IF v_destino_personalizado NOT IN ('ESTOQUE', 'USOCONSUMO', 'GERAL') THEN
    RAISE EXCEPTION 'Destino personalizado invalido.' USING ERRCODE = '22023';
  END IF;
  IF (v_destino_personalizado = 'ESTOQUE' AND NOT v_tem_produto)
     OR (v_destino_personalizado IN ('USOCONSUMO', 'GERAL') AND NOT v_tem_uso) THEN
    RAISE EXCEPTION 'O item personalizado nao pertence ao cabecalho informado.' USING ERRCODE = '22023';
  END IF;
  IF p_custo_total IS NULL OR p_custo_total < 0
     OR p_custo_personalizado IS NULL OR p_custo_personalizado < 0
     OR p_total_documento IS NULL OR p_total_documento < 0 THEN
    RAISE EXCEPTION 'Os totais da entrada hibrida sao invalidos.' USING ERRCODE = '22023';
  END IF;

  v_documento_id := coalesce(v_documento_produto, v_documento_uso);
  IF v_documento_id IS NULL
     OR (v_documento_produto IS NOT NULL AND v_documento_uso IS NOT NULL
         AND v_documento_produto <> v_documento_uso) THEN
    RAISE EXCEPTION 'Os cabecalhos nao apontam para a mesma NF-e.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.fiscal_dfe_documento
   WHERE id = v_documento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Documento fiscal recebido nao encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.fiscal_dfe_item_apropriacao
     WHERE documento_id = v_documento_id AND cancelada_at IS NULL
  ) THEN
    RAISE EXCEPTION 'A entrada hibrida exige uma NF-e ainda nao apropriada.' USING ERRCODE = '23505';
  END IF;

  -- Cada nItem precisa aparecer uma vez nas apropriacoes e uma vez na origem:
  -- como item fisico normal ou como linha do snapshot personalizado.
  FOR v_apropriacao IN SELECT value FROM jsonb_array_elements(p_apropriacoes)
  LOOP
    v_numero_item := nullif(v_apropriacao->>'numero_item', '')::integer;
    v_quantidade := nullif(v_apropriacao->>'quantidade', '')::numeric;
    v_destino_apropriacao := upper(btrim(coalesce(v_apropriacao->>'destino', '')));
    IF v_numero_item IS NULL OR v_numero_item < 1 OR v_numero_item > 990
       OR v_quantidade IS NULL OR v_quantidade <= 0
       OR v_destino_apropriacao NOT IN ('PRODUTO', 'USOCONSUMO') THEN
      RAISE EXCEPTION 'As apropriacoes fiscais da entrada hibrida sao invalidas.' USING ERRCODE = '22023';
    END IF;
    IF v_numero_item = ANY(v_numeros) THEN
      RAISE EXCEPTION 'O item fiscal % foi apropriado mais de uma vez.', v_numero_item
        USING ERRCODE = '22023';
    END IF;
    IF (v_destino_apropriacao = 'PRODUTO' AND NOT v_tem_produto)
       OR (v_destino_apropriacao = 'USOCONSUMO' AND NOT v_tem_uso) THEN
      RAISE EXCEPTION 'A apropriacao do item % nao possui cabecalho fisico.', v_numero_item
        USING ERRCODE = '22023';
    END IF;

    SELECT count(*) INTO v_ocorrencias FROM (
      SELECT nullif(value->>'numero_item_fiscal', '')::integer AS numero
        FROM jsonb_array_elements(p_itens_produto)
      UNION ALL
      SELECT nullif(value->>'numero_item_fiscal', '')::integer
        FROM jsonb_array_elements(p_itens_usoconsumo)
      UNION ALL
      SELECT nullif(value->>'numero_item', '')::integer
        FROM jsonb_array_elements(p_auditoria->'itens_originais')
    ) origens WHERE numero = v_numero_item;
    IF v_ocorrencias <> 1 THEN
      RAISE EXCEPTION 'O item fiscal % deve possuir exatamente uma origem.', v_numero_item
        USING ERRCODE = '22023';
    END IF;
    v_numeros := array_append(v_numeros, v_numero_item);
  END LOOP;

  SELECT count(*) INTO v_ocorrencias FROM (
    SELECT nullif(value->>'numero_item_fiscal', '')::integer AS numero
      FROM jsonb_array_elements(p_itens_produto)
    UNION ALL
    SELECT nullif(value->>'numero_item_fiscal', '')::integer
      FROM jsonb_array_elements(p_itens_usoconsumo)
    UNION ALL
    SELECT nullif(value->>'numero_item', '')::integer
      FROM jsonb_array_elements(p_auditoria->'itens_originais')
  ) origens WHERE numero IS NOT NULL;
  IF v_ocorrencias <> jsonb_array_length(p_apropriacoes) THEN
    RAISE EXCEPTION 'A entrada hibrida nao cobre todas as linhas fiscais uma unica vez.'
      USING ERRCODE = '22023';
  END IF;

  SELECT round(coalesce(sum((value->>'custo_estoque')::numeric), 0), 2)
    INTO v_total_custom_auditoria
    FROM jsonb_array_elements(p_auditoria->'itens_originais');
  IF v_total_custom_auditoria <> round(p_custo_personalizado, 2) THEN
    RAISE EXCEPTION 'O custo personalizado (%) difere da soma das linhas consolidadas (%).',
      round(p_custo_personalizado, 2), v_total_custom_auditoria USING ERRCODE = '23514';
  END IF;

  IF v_destino_personalizado = 'ESTOQUE' THEN
    SELECT round(
      (value->>'quantidade')::numeric * (value->>'valor_unitario_compra')::numeric
      - coalesce(nullif(value->>'valor_desconto', '')::numeric, 0)
      + coalesce(nullif(value->>'valor_frete', '')::numeric, 0)
      + coalesce(nullif(value->>'outras_despesas', '')::numeric, 0), 2
    ) INTO v_total_custom_item
      FROM jsonb_array_elements(p_itens_produto)
     WHERE nullif(value->>'numero_item_fiscal', '') IS NULL
       AND nullif(value->>'produto_id', '')::integer = nullif(p_auditoria->>'produto_id', '')::integer;
  ELSE
    SELECT round(
      (value->>'quantidade')::numeric * (value->>'valor_unitario_compra')::numeric
      - coalesce(nullif(value->>'valor_desconto', '')::numeric, 0)
      + coalesce(nullif(value->>'valor_frete', '')::numeric, 0)
      + coalesce(nullif(value->>'outras_despesas', '')::numeric, 0), 2
    ) INTO v_total_custom_item
      FROM jsonb_array_elements(p_itens_usoconsumo)
     WHERE nullif(value->>'numero_item_fiscal', '') IS NULL
       AND nullif(value->>'item_id', '')::integer = nullif(p_auditoria->>'usoconsumo_item_id', '')::integer;
  END IF;
  IF v_total_custom_item IS NULL OR v_total_custom_item <> round(p_custo_personalizado, 2) THEN
    RAISE EXCEPTION 'O item personalizado nao reproduz o custo consolidado.' USING ERRCODE = '23514';
  END IF;

  IF v_tem_produto THEN
    SELECT public.registrar_entrada_confirmada(
      p_entrada_produto - 'valor_total_documento',
      p_itens_produto,
      '[]'::jsonb
    ) INTO v_resultado_produto;
    v_entrada_id := (v_resultado_produto->>'entrada_id')::bigint;
  END IF;

  IF v_tem_uso THEN
    SELECT public.registrar_entrada_usoconsumo(
      (p_entrada_usoconsumo - 'documento_fiscal_recebido_id') - 'valor_total_documento',
      p_itens_usoconsumo,
      '[]'::jsonb
    ) INTO v_resultado_uso;
    v_usoconsumo_entrada_id := (v_resultado_uso->>'entrada_id')::bigint;
    UPDATE public.usoconsumo_entrada
       SET documento_fiscal_recebido_id = v_documento_id
     WHERE id = v_usoconsumo_entrada_id;
  END IF;

  v_total_fisico := round(
    coalesce((v_resultado_produto->>'valor_total')::numeric, 0)
    + coalesce((v_resultado_uso->>'valor_total')::numeric, 0), 2
  );
  IF v_total_fisico <> round(p_custo_total, 2) THEN
    RAISE EXCEPTION 'O custo fisico (%) difere do custo calculado da NF-e (%).',
      v_total_fisico, round(p_custo_total, 2) USING ERRCODE = '23514';
  END IF;

  -- Com um unico cabecalho, a tela historicamente mostra o vNF no cabecalho. Com
  -- dois, cada metade conserva seu custo fisico e o financeiro compartilhado
  -- carrega o total integral, como na entrada fiscal mista atual.
  IF v_tem_produto AND NOT v_tem_uso THEN
    UPDATE public.entrada SET valor_total = round(p_total_documento, 2)
     WHERE id = v_entrada_id;
  ELSIF v_tem_uso AND NOT v_tem_produto THEN
    UPDATE public.usoconsumo_entrada SET valor_total = round(p_total_documento, 2)
     WHERE id = v_usoconsumo_entrada_id;
  END IF;

  FOR v_apropriacao IN SELECT value FROM jsonb_array_elements(p_apropriacoes)
  LOOP
    v_destino_apropriacao := upper(v_apropriacao->>'destino');
    INSERT INTO public.fiscal_dfe_item_apropriacao(
      documento_id, numero_item, destino, entrada_id,
      usoconsumo_entrada_id, quantidade, created_by
    ) VALUES (
      v_documento_id,
      (v_apropriacao->>'numero_item')::integer,
      v_destino_apropriacao,
      CASE WHEN v_destino_apropriacao = 'PRODUTO' THEN v_entrada_id END,
      CASE WHEN v_destino_apropriacao = 'USOCONSUMO' THEN v_usoconsumo_entrada_id END,
      (v_apropriacao->>'quantidade')::numeric,
      v_created_by
    );
  END LOOP;

  INSERT INTO public.entrada_fiscal_personalizada(
    documento_id, destino, entrada_id, usoconsumo_entrada_id,
    itens_originais, custo_total_estoque, created_by, modalidade,
    produto_id, usoconsumo_item_id, quantidade_personalizada, custo_unitario,
    valor_fiscal_documento, item_destino_snapshot
  ) VALUES (
    v_documento_id,
    v_destino_personalizado,
    CASE WHEN v_destino_personalizado = 'ESTOQUE' THEN v_entrada_id END,
    CASE WHEN v_destino_personalizado IN ('USOCONSUMO', 'GERAL') THEN v_usoconsumo_entrada_id END,
    p_auditoria->'itens_originais',
    round(p_custo_personalizado, 2),
    v_created_by,
    'HIBRIDA',
    nullif(p_auditoria->>'produto_id', '')::integer,
    nullif(p_auditoria->>'usoconsumo_item_id', '')::integer,
    nullif(p_auditoria->>'quantidade_personalizada', '')::integer,
    nullif(p_auditoria->>'custo_unitario', '')::numeric,
    round(p_total_documento, 2),
    p_auditoria->'item_destino_snapshot'
  );

  IF jsonb_typeof(p_transacoes) = 'array' AND jsonb_array_length(p_transacoes) > 0 THEN
    SELECT round(coalesce(sum((value->>'valor')::numeric), 0), 2)
      INTO v_total_financeiro FROM jsonb_array_elements(p_transacoes);
    IF v_total_financeiro <> round(p_total_documento, 2) THEN
      RAISE EXCEPTION 'A soma dos lancamentos financeiros (%) difere do vNF (%).',
        v_total_financeiro, round(p_total_documento, 2) USING ERRCODE = '22023';
    END IF;

    FOR v_transacao IN SELECT value FROM jsonb_array_elements(p_transacoes)
    LOOP
      IF coalesce(nullif(v_transacao->>'valor', '')::numeric, 0) <= 0 THEN
        RAISE EXCEPTION 'O valor do lancamento financeiro deve ser positivo.' USING ERRCODE = '22023';
      END IF;
      INSERT INTO public.transacao(
        descricao, valor, "valorLiquido", data, vencimento_em, metodopagamento,
        categoria, categoria_id, tipo, cliente_id, banco_id, nomepagador,
        cpfcnpjpagador, pendente, plano_de_conta_id, plano_de_conta,
        centro_custo_id, centro_custo, entrada_id, usoconsumo_entrada_id,
        origem, created_by
      ) VALUES (
        coalesce(nullif(v_transacao->>'descricao', ''), 'Compra de mercadorias'),
        (v_transacao->>'valor')::numeric,
        (v_transacao->>'valor')::numeric,
        coalesce(nullif(v_transacao->>'data', '')::timestamptz, now()),
        nullif(v_transacao->>'vencimento_em', '')::timestamptz,
        nullif(v_transacao->>'metodopagamento', '')::public.metodo_pagamento,
        coalesce(nullif(v_transacao->>'categoria', ''), 'NAO RELACIONADO'),
        nullif(v_transacao->>'categoria_id', '')::integer,
        'DESPESA'::public.tipos_transacao,
        NULL,
        nullif(v_transacao->>'banco_id', '')::bigint,
        coalesce(nullif(v_transacao->>'nomepagador', ''), 'Fornecedor'),
        coalesce(nullif(regexp_replace(v_transacao->>'cpfcnpjpagador', '\D', '', 'g'), ''), 'NAO INFORMADO'),
        coalesce((v_transacao->>'pendente')::boolean, false),
        nullif(v_transacao->>'plano_de_conta_id', '')::integer,
        nullif(v_transacao->>'plano_de_conta', ''),
        nullif(v_transacao->>'centro_custo_id', '')::integer,
        nullif(v_transacao->>'centro_custo', ''),
        v_entrada_id,
        v_usoconsumo_entrada_id,
        'ENTRADA_FISCAL_MISTA',
        v_created_by
      );
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'entrada_id', v_entrada_id,
    'usoconsumo_entrada_id', v_usoconsumo_entrada_id,
    'valor_total', round(p_total_documento, 2),
    'custo_total_estoque', v_total_fisico,
    'custo_personalizado', round(p_custo_personalizado, 2)
  );
END;
$$;


--
-- Name: registrar_entrada_fiscal_mista(jsonb, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_fiscal_mista(p_entrada_produto jsonb, p_itens_produto jsonb, p_entrada_usoconsumo jsonb, p_itens_usoconsumo jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_res_produto jsonb;
  v_res_uso jsonb;
  v_entrada_id bigint;
  v_uso_entrada_id bigint;
  v_entrada_produto jsonb;
  v_entrada_uso jsonb;
  v_documento_id bigint := nullif(p_entrada_produto->>'fiscal_dfe_documento_id','')::bigint;
  v_total numeric(14,2);
  v_total_itens numeric(14,2);
  v_total_documento numeric(14,2) := nullif(p_entrada_produto->>'valor_total_documento','')::numeric;
  v_total_fin numeric(14,2);
  v_tx jsonb;
  v_user uuid := nullif(p_entrada_produto->>'created_by','')::uuid;
BEGIN
  IF jsonb_typeof(p_itens_produto) <> 'array' OR jsonb_array_length(p_itens_produto) = 0
     OR jsonb_typeof(p_itens_usoconsumo) <> 'array' OR jsonb_array_length(p_itens_usoconsumo) = 0 THEN
    RAISE EXCEPTION 'A entrada mista exige ao menos um item de estoque e um item de uso e consumo.'
      USING ERRCODE = '22023';
  END IF;

  IF v_total_documento IS NOT NULL AND v_total_documento < 0 THEN
    RAISE EXCEPTION 'O total do documento fiscal não pode ser negativo.' USING ERRCODE = '22023';
  END IF;

  -- Sem valor_total_documento a entrada de estoque fecha pelo total dos seus proprios
  -- itens, e nao pelo total da NF-e (que inclui a parte de uso e consumo). O mesmo
  -- vale agora para a metade de uso e consumo, que ganhou a mesma válvula.
  v_entrada_produto := p_entrada_produto - 'valor_total_documento';
  v_entrada_uso := p_entrada_usoconsumo - 'valor_total_documento';

  -- As duas entradas sao gravadas sem transacoes: o pagamento e unico e vem depois.
  IF v_documento_id IS NOT NULL THEN
    SELECT public.registrar_entrada_comercial_apropriada(v_entrada_produto, p_itens_produto, '[]'::jsonb)
      INTO v_res_produto;
  ELSE
    SELECT public.registrar_entrada_confirmada(v_entrada_produto, p_itens_produto, '[]'::jsonb)
      INTO v_res_produto;
  END IF;
  v_entrada_id := (v_res_produto->>'entrada_id')::bigint;

  SELECT public.registrar_entrada_usoconsumo(v_entrada_uso, p_itens_usoconsumo, '[]'::jsonb)
    INTO v_res_uso;
  v_uso_entrada_id := (v_res_uso->>'entrada_id')::bigint;

  v_total_itens := round(
    coalesce((v_res_produto->>'valor_total')::numeric, 0)
    + coalesce((v_res_uso->>'valor_total')::numeric, 0), 2);

  -- O documento manda quando informado: é ele que o fornecedor cobra, e é contra
  -- ele que as duplicatas fecham. Sem ele, vale a soma das duas entradas.
  v_total := round(coalesce(v_total_documento, v_total_itens), 2);

  IF jsonb_typeof(p_transacoes) = 'array' AND jsonb_array_length(p_transacoes) > 0 THEN
    SELECT round(coalesce(sum((value->>'valor')::numeric), 0), 2)
      INTO v_total_fin
      FROM jsonb_array_elements(p_transacoes);
    IF v_total_fin <> v_total THEN
      RAISE EXCEPTION 'A soma dos lancamentos financeiros (%) difere do total da nota (%).',
        v_total_fin, v_total USING ERRCODE = '22023';
    END IF;

    FOR v_tx IN SELECT value FROM jsonb_array_elements(p_transacoes) LOOP
      IF coalesce(nullif(v_tx->>'valor','')::numeric, 0) <= 0 THEN
        RAISE EXCEPTION 'O valor do lancamento financeiro deve ser positivo.' USING ERRCODE = '22023';
      END IF;
      INSERT INTO public.transacao(
        descricao, valor, "valorLiquido", data, vencimento_em, metodopagamento, categoria, categoria_id,
        tipo, cliente_id, banco_id, nomepagador, cpfcnpjpagador, pendente, plano_de_conta_id,
        plano_de_conta, centro_custo_id, centro_custo, entrada_id, usoconsumo_entrada_id, origem, created_by
      ) VALUES (
        coalesce(nullif(v_tx->>'descricao',''), 'Compra de mercadorias'),
        (v_tx->>'valor')::numeric,
        (v_tx->>'valor')::numeric,
        coalesce(nullif(v_tx->>'data','')::timestamptz, now()),
        nullif(v_tx->>'vencimento_em','')::timestamptz,
        nullif(v_tx->>'metodopagamento','')::public.metodo_pagamento,
        coalesce(nullif(v_tx->>'categoria',''), 'NAO RELACIONADO'),
        nullif(v_tx->>'categoria_id','')::integer,
        'DESPESA'::public.tipos_transacao,
        NULL,
        nullif(v_tx->>'banco_id','')::bigint,
        coalesce(nullif(v_tx->>'nomepagador',''), 'Fornecedor'),
        coalesce(nullif(regexp_replace(v_tx->>'cpfcnpjpagador','\D','','g'),''), 'NAO INFORMADO'),
        coalesce((v_tx->>'pendente')::boolean, false),
        nullif(v_tx->>'plano_de_conta_id','')::integer,
        nullif(v_tx->>'plano_de_conta',''),
        nullif(v_tx->>'centro_custo_id','')::integer,
        nullif(v_tx->>'centro_custo',''),
        v_entrada_id,
        v_uso_entrada_id,
        'ENTRADA_FISCAL_MISTA',
        v_user
      );
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'entrada_id', v_entrada_id,
    'usoconsumo_entrada_id', v_uso_entrada_id,
    'valor_total', v_total
  );
END $$;


--
-- Name: registrar_entrada_fiscal_personalizada(text, jsonb, jsonb, jsonb, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_fiscal_personalizada(p_destino text, p_entrada jsonb, p_item jsonb, p_itens_fiscais jsonb, p_custo_total numeric, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_destino text := upper(btrim(coalesce(p_destino, '')));
  v_documento_id bigint;
  v_resultado jsonb;
  v_entrada_id bigint;
  v_usoconsumo_entrada_id bigint;
  v_linha jsonb;
  v_numero_item integer;
  v_quantidade_fiscal numeric(14,4);
  v_numeros integer[] := ARRAY[]::integer[];
  v_created_by uuid := nullif(p_entrada->>'created_by', '')::uuid;
BEGIN
  IF v_destino NOT IN ('ESTOQUE', 'USOCONSUMO', 'GERAL') THEN
    RAISE EXCEPTION 'Destino da entrada personalizada invalido.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_item) <> 'object' THEN
    RAISE EXCEPTION 'Informe o item consolidado da entrada personalizada.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_itens_fiscais) <> 'array' OR jsonb_array_length(p_itens_fiscais) = 0 THEN
    RAISE EXCEPTION 'A entrada personalizada exige os itens originais da NF-e.' USING ERRCODE = '22023';
  END IF;
  IF p_custo_total IS NULL OR p_custo_total < 0 THEN
    RAISE EXCEPTION 'O custo total da entrada personalizada e invalido.' USING ERRCODE = '22023';
  END IF;

  v_documento_id := CASE
    WHEN v_destino = 'ESTOQUE'
      THEN nullif(p_entrada->>'fiscal_dfe_documento_id', '')::bigint
    ELSE nullif(p_entrada->>'documento_fiscal_recebido_id', '')::bigint
  END;
  IF v_documento_id IS NULL THEN
    RAISE EXCEPTION 'Informe o documento fiscal recebido.' USING ERRCODE = '22023';
  END IF;

  -- Serializa entradas personalizadas concorrentes da mesma NF-e. Entradas
  -- normais continuam protegidas pelo indice unico das apropriacoes.
  PERFORM 1 FROM public.fiscal_dfe_documento
    WHERE id = v_documento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Documento fiscal recebido nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.fiscal_dfe_item_apropriacao
     WHERE documento_id = v_documento_id AND cancelada_at IS NULL
  ) THEN
    RAISE EXCEPTION 'A entrada personalizada exige uma NF-e ainda nao apropriada.' USING ERRCODE = '23505';
  END IF;

  -- Valida nItem e quantidade antes de criar qualquer saldo.
  FOR v_linha IN SELECT value FROM jsonb_array_elements(p_itens_fiscais)
  LOOP
    v_numero_item := nullif(v_linha->>'numero_item', '')::integer;
    v_quantidade_fiscal := nullif(v_linha->>'quantidade', '')::numeric;
    IF v_numero_item IS NULL OR v_numero_item < 1 OR v_numero_item > 990
       OR v_quantidade_fiscal IS NULL OR v_quantidade_fiscal <= 0 THEN
      RAISE EXCEPTION 'Os itens originais da NF-e sao invalidos.' USING ERRCODE = '22023';
    END IF;
    IF v_numero_item = ANY(v_numeros) THEN
      RAISE EXCEPTION 'O item fiscal % foi informado mais de uma vez.', v_numero_item
        USING ERRCODE = '22023';
    END IF;
    v_numeros := array_append(v_numeros, v_numero_item);
  END LOOP;

  IF v_destino = 'ESTOQUE' THEN
    SELECT public.registrar_entrada_confirmada(
      p_entrada,
      jsonb_build_array(p_item),
      p_transacoes
    ) INTO v_resultado;
    v_entrada_id := (v_resultado->>'entrada_id')::bigint;
  ELSE
    -- Sem o documento durante a chamada, o motor de uso/consumo nao tenta criar
    -- a apropriacao linha a linha. O vinculo volta logo abaixo, na mesma transacao.
    SELECT public.registrar_entrada_usoconsumo(
      p_entrada - 'documento_fiscal_recebido_id',
      jsonb_build_array(p_item),
      p_transacoes
    ) INTO v_resultado;
    v_usoconsumo_entrada_id := (v_resultado->>'entrada_id')::bigint;

    UPDATE public.usoconsumo_entrada
       SET documento_fiscal_recebido_id = v_documento_id
     WHERE id = v_usoconsumo_entrada_id;
  END IF;

  FOR v_linha IN SELECT value FROM jsonb_array_elements(p_itens_fiscais)
  LOOP
    INSERT INTO public.fiscal_dfe_item_apropriacao(
      documento_id, numero_item, destino, entrada_id,
      usoconsumo_entrada_id, quantidade, created_by
    ) VALUES (
      v_documento_id,
      (v_linha->>'numero_item')::integer,
      CASE WHEN v_destino = 'ESTOQUE' THEN 'PRODUTO' ELSE 'USOCONSUMO' END,
      v_entrada_id,
      v_usoconsumo_entrada_id,
      (v_linha->>'quantidade')::numeric,
      v_created_by
    );
  END LOOP;

  INSERT INTO public.entrada_fiscal_personalizada(
    documento_id, destino, entrada_id, usoconsumo_entrada_id,
    itens_originais, custo_total_estoque, created_by
  ) VALUES (
    v_documento_id, v_destino, v_entrada_id, v_usoconsumo_entrada_id,
    p_itens_fiscais, round(p_custo_total, 2), v_created_by
  );

  RETURN v_resultado || jsonb_build_object(
    'destino', v_destino,
    'entrada_id', v_entrada_id,
    'usoconsumo_entrada_id', v_usoconsumo_entrada_id,
    'custo_total_estoque', round(p_custo_total, 2)
  );
END;
$$;


--
-- Name: registrar_entrada_usoconsumo(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_usoconsumo(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_entrada_id bigint;
  v_competencia timestamptz;
BEGIN
  SELECT public.registrar_entrada_usoconsumo_sem_dre(p_entrada, p_itens, p_transacoes)
    INTO v_result;
  v_entrada_id := (v_result->>'entrada_id')::bigint;

  IF p_entrada ? 'tributos' THEN
    SELECT coalesce(data_emissao, created_at) INTO v_competencia
      FROM public.usoconsumo_entrada WHERE id = v_entrada_id;
    PERFORM public.registrar_eventos_dre_entrada(
      'USOCONSUMO_ENTRADA', v_entrada_id, v_competencia, p_entrada->'tributos',
      nullif(p_entrada->>'created_by', '')::uuid
    );
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: registrar_entrada_usoconsumo_sem_dre(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_entrada_usoconsumo_sem_dre(p_entrada jsonb, p_itens jsonb, p_transacoes jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entrada_id bigint; v_item_json jsonb; v_item public.usoconsumo_item%ROWTYPE;
  v_entrada_item_id bigint; v_item_id integer; v_qtd integer; v_custo numeric(14,4);
  v_desc numeric(14,2); v_frete numeric(14,2); v_outras numeric(14,2); v_total_item numeric(14,2);
  v_total numeric(14,2):=0; v_total_fin numeric(14,2); v_tx jsonb; v_fiscal boolean;
  v_chave text; v_documento_id bigint; v_numero_item integer; v_user uuid;
  v_total_documento numeric(14,2) := nullif(p_entrada->>'valor_total_documento','')::numeric;
  v_total_devido numeric(14,2);
  v_escopo text := upper(btrim(coalesce(p_entrada->>'escopo','USOCONSUMO')));
  v_rotulo text;
BEGIN
  IF jsonb_typeof(p_itens)<>'array' OR jsonb_array_length(p_itens)=0 THEN
    RAISE EXCEPTION 'Informe ao menos um item.' USING ERRCODE='22023';
  END IF;
  IF v_escopo NOT IN ('USOCONSUMO','GERAL','MISTO') THEN
    RAISE EXCEPTION 'Escopo de estoque invalido: %.', v_escopo USING ERRCODE='22023';
  END IF;
  v_rotulo := CASE v_escopo
                WHEN 'GERAL' THEN 'Compra de material do estoque geral'
                WHEN 'MISTO' THEN 'Compra de material de uso e consumo e do estoque geral'
                ELSE 'Compra de material de uso e consumo' END;
  IF v_total_documento IS NOT NULL AND v_total_documento < 0 THEN
    RAISE EXCEPTION 'O total do documento fiscal nao pode ser negativo.' USING ERRCODE='22023';
  END IF;
  v_fiscal:=coalesce((p_entrada->>'fiscal')::boolean,false);
  v_chave:=nullif(regexp_replace(coalesce(p_entrada->>'chave_nfe',''),'\D','','g'),'');
  v_documento_id:=nullif(p_entrada->>'documento_fiscal_recebido_id','')::bigint;
  v_user:=nullif(p_entrada->>'created_by','')::uuid;
  IF v_fiscal AND (v_chave IS NULL OR length(v_chave)<>44 OR nullif(p_entrada->>'fornecedor_id','') IS NULL) THEN
    RAISE EXCEPTION 'A entrada fiscal exige chave valida e fornecedor.' USING ERRCODE='22023';
  END IF;
  INSERT INTO public.usoconsumo_entrada(
    escopo,fornecedor_id,fiscal,chave_nfe,numero_nota,serie_nota,data_emissao,tipo,origem,documento_fiscal_recebido_id,created_by,observacao
  ) VALUES(
    v_escopo,
    nullif(p_entrada->>'fornecedor_id','')::integer,v_fiscal,v_chave,nullif(p_entrada->>'numero_nota',''),
    nullif(p_entrada->>'serie_nota',''),nullif(p_entrada->>'data_emissao','')::timestamptz,
    coalesce(nullif(p_entrada->>'tipo',''),'COMPRA_FORNECEDOR'),coalesce(nullif(p_entrada->>'origem',''),'MANUAL'),
    v_documento_id,v_user,nullif(btrim(coalesce(p_entrada->>'observacao','')),'')
  ) RETURNING id INTO v_entrada_id;

  FOR v_item_json IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    v_item_id:=nullif(v_item_json->>'item_id','')::integer;
    v_qtd:=nullif(v_item_json->>'quantidade','')::integer;
    v_custo:=nullif(v_item_json->>'valor_unitario_compra','')::numeric;
    v_desc:=coalesce(nullif(v_item_json->>'valor_desconto','')::numeric,0);
    v_frete:=coalesce(nullif(v_item_json->>'valor_frete','')::numeric,0);
    v_outras:=coalesce(nullif(v_item_json->>'outras_despesas','')::numeric,0);
    v_numero_item:=nullif(v_item_json->>'numero_item_fiscal','')::integer;
    IF v_item_id IS NULL OR v_qtd IS NULL OR v_qtd<=0 OR v_custo IS NULL OR v_custo<0
       OR v_desc<0 OR v_frete<0 OR v_outras<0 THEN
      RAISE EXCEPTION 'Item, quantidade ou valores invalidos.' USING ERRCODE='22023';
    END IF;
    IF v_fiscal AND v_documento_id IS NOT NULL AND v_numero_item IS NULL THEN
      RAISE EXCEPTION 'Informe o numero do item fiscal.' USING ERRCODE='22023';
    END IF;
    -- MISTO aceita item de qualquer estoque simples; escopo unico exige o proprio.
    SELECT * INTO v_item FROM public.usoconsumo_item
    WHERE id=v_item_id AND ativo
      AND (v_escopo='MISTO' OR escopo=v_escopo)
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item % nao encontrado neste estoque.',v_item_id USING ERRCODE='P0002';
    END IF;
    v_total_item:=round(v_qtd*v_custo-v_desc+v_frete+v_outras,2);
    IF v_total_item<0 THEN RAISE EXCEPTION 'Total do item invalido.' USING ERRCODE='22023'; END IF;
    INSERT INTO public.usoconsumo_entrada_item(
      entrada_id,item_id,numero_item_fiscal,codigo_fornecedor,quantidade,unidade,valor_unitario_compra,
      valor_desconto,valor_frete,outras_despesas,valor_total,saldo_anterior,saldo_resultante,ncm,cest,csosn,
      referencia,titulo,cst,aliquotaicms,cfop,cst_pis,aliquota_pis,cst_cofins,aliquota_cofins,cst_ibscbs,
      cclass_trib,aliquota_ibs_uf,aliquota_ibs_municipio,aliquota_cbs
    ) VALUES(
      v_entrada_id,v_item_id,v_numero_item,nullif(v_item_json->>'codigo_fornecedor',''),v_qtd,
      coalesce(nullif(v_item_json->>'unidade','')::public.unidade_medida,v_item.unidade),v_custo,v_desc,v_frete,v_outras,
      v_total_item,v_item.estoque,v_item.estoque+v_qtd,coalesce(nullif(v_item_json->>'ncm',''),v_item.ncm),
      coalesce(nullif(v_item_json->>'cest',''),v_item.cest),coalesce(nullif(v_item_json->>'csosn',''),v_item.csosn),
      coalesce(nullif(v_item_json->>'referencia',''),v_item.referencia),coalesce(nullif(v_item_json->>'titulo',''),v_item.titulo),
      coalesce(nullif(v_item_json->>'cst',''),v_item.cst),coalesce(nullif(v_item_json->>'aliquotaicms','')::numeric,v_item.aliquotaicms),
      coalesce(nullif(v_item_json->>'cfop',''),v_item.cfop_entrada),coalesce(nullif(v_item_json->>'cst_pis',''),v_item.cst_pis),
      coalesce(nullif(v_item_json->>'aliquota_pis','')::numeric,v_item.aliquota_pis),
      coalesce(nullif(v_item_json->>'cst_cofins',''),v_item.cst_cofins),coalesce(nullif(v_item_json->>'aliquota_cofins','')::numeric,v_item.aliquota_cofins),
      coalesce(nullif(v_item_json->>'cst_ibscbs',''),v_item.cst_ibscbs),coalesce(nullif(v_item_json->>'cclass_trib',''),v_item.cclass_trib),
      coalesce(nullif(v_item_json->>'aliquota_ibs_uf','')::numeric,v_item.aliquota_ibs_uf),
      coalesce(nullif(v_item_json->>'aliquota_ibs_municipio','')::numeric,v_item.aliquota_ibs_municipio),
      coalesce(nullif(v_item_json->>'aliquota_cbs','')::numeric,v_item.aliquota_cbs)
    ) RETURNING id INTO v_entrada_item_id;
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque+v_qtd,ultimovalordecompra=v_custo,updated_by=v_user WHERE id=v_item_id;
    INSERT INTO public.usoconsumo_movimento_entrada(
      entrada_id,entrada_item_id,item_id,tipo,quantidade,saldo_anterior,saldo_resultante,valor_unitario_compra,created_by
    ) VALUES(v_entrada_id,v_entrada_item_id,v_item_id,'ENTRADA',v_qtd,v_item.estoque,v_item.estoque+v_qtd,v_custo,v_user);
    IF nullif(p_entrada->>'fornecedor_id','') IS NOT NULL THEN
      INSERT INTO public.usoconsumo_fornecedor_item(fornecedor_id,item_id,codigo_fornecedor,ultimo_valor_compra)
      VALUES((p_entrada->>'fornecedor_id')::integer,v_item_id,nullif(v_item_json->>'codigo_fornecedor',''),v_custo)
      ON CONFLICT(fornecedor_id,item_id) DO UPDATE SET
        codigo_fornecedor=coalesce(EXCLUDED.codigo_fornecedor,usoconsumo_fornecedor_item.codigo_fornecedor),
        ultimo_valor_compra=EXCLUDED.ultimo_valor_compra,updated_at=now();
    END IF;
    IF v_fiscal AND v_documento_id IS NOT NULL THEN
      INSERT INTO public.fiscal_dfe_item_apropriacao(
        documento_id,numero_item,destino,usoconsumo_entrada_id,quantidade,created_by
      ) VALUES(v_documento_id,v_numero_item,'USOCONSUMO',v_entrada_id,v_qtd,v_user);
    END IF;
    v_total:=v_total+v_total_item;
  END LOOP;

  v_total_devido := round(coalesce(v_total_documento, v_total),2);
  UPDATE public.usoconsumo_entrada SET valor_total=v_total_devido WHERE id=v_entrada_id;

  IF jsonb_typeof(p_transacoes)='array' AND jsonb_array_length(p_transacoes)>0 THEN
    SELECT round(coalesce(sum((value->>'valor')::numeric),0),2) INTO v_total_fin FROM jsonb_array_elements(p_transacoes);
    IF v_total_fin<>v_total_devido THEN
      RAISE EXCEPTION 'A soma dos lancamentos financeiros (%) difere do total da entrada (%).',
        v_total_fin, v_total_devido USING ERRCODE='22023';
    END IF;
    FOR v_tx IN SELECT value FROM jsonb_array_elements(p_transacoes) LOOP
      IF coalesce(nullif(v_tx->>'valor','')::numeric,0)<=0 THEN
        RAISE EXCEPTION 'Valor financeiro invalido.' USING ERRCODE='22023';
      END IF;
      INSERT INTO public.transacao(
        descricao,valor,"valorLiquido",data,vencimento_em,metodopagamento,categoria,categoria_id,tipo,cliente_id,
        banco_id,nomepagador,cpfcnpjpagador,pendente,plano_de_conta_id,plano_de_conta,centro_custo_id,
        centro_custo,usoconsumo_entrada_id,origem,created_by
      ) VALUES(
        coalesce(nullif(v_tx->>'descricao',''),v_rotulo),(v_tx->>'valor')::numeric,
        (v_tx->>'valor')::numeric,coalesce(nullif(v_tx->>'data','')::timestamptz,now()),
        nullif(v_tx->>'vencimento_em','')::timestamptz,nullif(v_tx->>'metodopagamento','')::public.metodo_pagamento,
        coalesce(nullif(v_tx->>'categoria',''),v_rotulo),
        nullif(v_tx->>'categoria_id','')::integer,'DESPESA',NULL,nullif(v_tx->>'banco_id','')::bigint,
        coalesce(nullif(v_tx->>'nomepagador',''),'Fornecedor'),
        coalesce(nullif(regexp_replace(v_tx->>'cpfcnpjpagador','\D','','g'),''),'NAO INFORMADO'),
        coalesce((v_tx->>'pendente')::boolean,false),nullif(v_tx->>'plano_de_conta_id','')::integer,
        nullif(v_tx->>'plano_de_conta',''),nullif(v_tx->>'centro_custo_id','')::integer,
        nullif(v_tx->>'centro_custo',''),v_entrada_id,'USOCONSUMO_ENTRADA',v_user
      );
    END LOOP;
  END IF;
  RETURN jsonb_build_object('entrada_id',v_entrada_id,'valor_total',v_total_devido,'escopo',v_escopo);
END $$;


--
-- Name: registrar_eventos_dre_entrada(text, bigint, timestamp with time zone, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_eventos_dre_entrada(p_source_type text, p_source_id bigint, p_competencia timestamp with time zone, p_tributos jsonb, p_user uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tributo   jsonb;
  v_tipo      text;
  v_natureza  text;
  v_valor     numeric(14,2);
  v_gravados  integer := 0;
BEGIN
  IF p_source_type NOT IN ('ENTRADA', 'USOCONSUMO_ENTRADA') THEN
    RAISE EXCEPTION 'Fonte invalida para lancamento de entrada: %.', p_source_type
      USING ERRCODE = '22023';
  END IF;
  IF p_tributos IS NULL OR jsonb_typeof(p_tributos) <> 'array' THEN
    RETURN 0;
  END IF;

  FOR v_tributo IN SELECT value FROM jsonb_array_elements(p_tributos) LOOP
    v_tipo     := nullif(btrim(v_tributo->>'tipo'), '');
    v_natureza := upper(coalesce(nullif(btrim(v_tributo->>'natureza'), ''), 'DESPESA'));
    v_valor    := round(coalesce((v_tributo->>'valor')::numeric, 0), 2);

    IF v_tipo IS NULL THEN
      RAISE EXCEPTION 'Tributo da entrada sem tipo.' USING ERRCODE = '22023';
    END IF;
    IF v_natureza NOT IN ('RECEITA', 'DESPESA') THEN
      RAISE EXCEPTION 'Natureza invalida no tributo %: %.', v_tipo, v_natureza
        USING ERRCODE = '22023';
    END IF;
    -- Valor negativo nao existe aqui: o sinal mora na linha da DRE. Zero e
    -- ignorado em vez de virar lancamento vazio no relatorio.
    IF v_valor <= 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.eventos_financeiros (
      ordemservicoid, source_type, source_id, source_item_id,
      origem, natureza, natureza_dre, chave_origem,
      descricao, detalhe, valor, competencia_em,
      dados_snapshot, pode_gerar_transacao, status, created_by
    ) VALUES (
      NULL, p_source_type, p_source_id, NULL,
      'ENTRADA_FISCAL', v_natureza,
      public.natureza_dre_de_evento('ENTRADA_FISCAL', v_natureza), v_tipo,
      coalesce(nullif(btrim(v_tributo->>'descricao'), ''), v_tipo || ' na compra'),
      nullif(btrim(v_tributo->>'detalhe'), ''),
      v_valor, p_competencia,
      jsonb_build_object('tipo', v_tipo, 'itens', coalesce(v_tributo->'itens', '[]'::jsonb)),
      false, 'ATIVO', p_user
    )
    ON CONFLICT (source_type, source_id, origem, chave_origem, natureza)
      WHERE ordemservicoid IS NULL
    DO UPDATE SET valor          = excluded.valor,
                  descricao      = excluded.descricao,
                  detalhe        = excluded.detalhe,
                  competencia_em = excluded.competencia_em,
                  dados_snapshot = excluded.dados_snapshot,
                  natureza_dre   = excluded.natureza_dre,
                  status         = 'ATIVO',
                  updated_at     = now()
    WHERE public.eventos_financeiros.status <> 'CONVERTIDO';

    v_gravados := v_gravados + 1;
  END LOOP;

  RETURN v_gravados;
END $$;


--
-- Name: FUNCTION registrar_eventos_dre_entrada(p_source_type text, p_source_id bigint, p_competencia timestamp with time zone, p_tributos jsonb, p_user uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_eventos_dre_entrada(p_source_type text, p_source_id bigint, p_competencia timestamp with time zone, p_tributos jsonb, p_user uuid) IS 'Lanca na DRE o que a nota de entrada cobrou e nao virou custo de estoque. A mercadoria nao passa por aqui: ela espera a baixa e chega como CMV.';


--
-- Name: registrar_finalizacao_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_finalizacao_os() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_novo_final boolean := new.status::text in ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO');
  v_antigo_final boolean := false;
begin
  if tg_op = 'INSERT' then
    new.finalizado_em := case when v_novo_final then coalesce(new.finalizado_em, now()) else null end;
    return new;
  end if;

  v_antigo_final := old.status::text in ('CONCLUIDO', 'SEM_COBRANCA', 'CANCELADO');
  if old.status is distinct from new.status then
    if v_novo_final then
      new.finalizado_em := case when v_antigo_final then now() else coalesce(new.finalizado_em, now()) end;
    elsif v_antigo_final then
      new.finalizado_em := null;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: registrar_importacao_ofx(bigint, text, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_importacao_ofx(p_banco_id bigint, p_arquivo_nome text, p_arquivo_hash text, p_cabecalho jsonb, p_movimentos jsonb, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_importacao_id bigint;
  v_movimento jsonb;
  v_id bigint;
  v_importados integer := 0;
  v_repetidos integer := 0;
  v_total integer;
  v_resultado jsonb := '[]'::jsonb;
  v_existente_id bigint;
BEGIN
  IF p_banco_id IS NULL OR p_banco_id <= 0 THEN
    RAISE EXCEPTION 'Conta bancária obrigatória.' USING ERRCODE = '22023';
  END IF;
  IF nullif(btrim(coalesce(p_arquivo_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Não foi possível identificar o arquivo.' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_movimentos) <> 'array' OR jsonb_array_length(p_movimentos) = 0 THEN
    RAISE EXCEPTION 'O extrato não tem nenhum movimento para importar.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.bancoconta WHERE id = p_banco_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conta bancária não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  SELECT id INTO v_existente_id
    FROM public.ofx_importacao
   WHERE banco_id = p_banco_id AND arquivo_hash = p_arquivo_hash;
  IF FOUND THEN
    RAISE EXCEPTION
      'Este arquivo já foi importado nesta conta (importação #%).', v_existente_id
      USING ERRCODE = '23505';
  END IF;

  v_total := jsonb_array_length(p_movimentos);

  INSERT INTO public.ofx_importacao (
    banco_id, arquivo_nome, arquivo_hash,
    bank_id_ofx, agencia_ofx, conta_ofx, tipo_conta_ofx, moeda,
    periodo_inicio, periodo_fim, saldo_inicial, saldo_final,
    quantidade_movimentos, created_by
  ) VALUES (
    p_banco_id,
    coalesce(nullif(btrim(p_arquivo_nome), ''), 'extrato.ofx'),
    p_arquivo_hash,
    nullif(btrim(p_cabecalho->>'bankId'), ''),
    nullif(btrim(p_cabecalho->>'branchId'), ''),
    nullif(btrim(p_cabecalho->>'acctId'), ''),
    nullif(btrim(p_cabecalho->>'acctType'), ''),
    nullif(btrim(p_cabecalho->>'moeda'), ''),
    nullif(p_cabecalho->>'periodoInicio', '')::date,
    nullif(p_cabecalho->>'periodoFim', '')::date,
    nullif(p_cabecalho->>'saldoInicial', '')::numeric,
    nullif(p_cabecalho->>'saldoFinal', '')::numeric,
    v_total,
    p_created_by
  ) RETURNING id INTO v_importacao_id;

  FOR v_movimento IN SELECT * FROM jsonb_array_elements(p_movimentos) LOOP
    /*
     * A linha que já existe de outra importação NÃO é gravada de novo, e o
     * `ON CONFLICT DO NOTHING` faz isso sem abortar a transação. Contar como
     * repetida é o que permite a tela dizer "8 destes 34 já estavam aqui" em
     * vez de o usuário achar que perdeu movimento.
     */
    INSERT INTO public.ofx_movimento (
      importacao_id, banco_id, sequencia,
      fitid, checknum, refnum, tipo_ofx,
      data_postagem, data_disponivel,
      valor, valor_centavos, nome, memo,
      fingerprint, situacao_analise, score_match, observacao
    ) VALUES (
      v_importacao_id, p_banco_id,
      coalesce((v_movimento->>'sequencia')::integer, 0),
      nullif(btrim(coalesce(v_movimento->>'fitid', '')), ''),
      nullif(btrim(coalesce(v_movimento->>'checknum', '')), ''),
      nullif(btrim(coalesce(v_movimento->>'refnum', '')), ''),
      nullif(btrim(coalesce(v_movimento->>'tipoOfx', '')), ''),
      (v_movimento->>'dataPostagem')::date,
      nullif(v_movimento->>'dataDisponivel', '')::date,
      round((v_movimento->>'valorCentavos')::numeric / 100.0, 2),
      (v_movimento->>'valorCentavos')::bigint,
      nullif(btrim(coalesce(v_movimento->>'nome', '')), ''),
      nullif(btrim(coalesce(v_movimento->>'memo', '')), ''),
      v_movimento->>'fingerprint',
      nullif(v_movimento->>'situacao', ''),
      nullif(v_movimento->>'score', '')::integer,
      nullif(btrim(coalesce(v_movimento->>'observacao', '')), '')
    )
    ON CONFLICT (banco_id, fingerprint) DO NOTHING
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      v_repetidos := v_repetidos + 1;
      SELECT id INTO v_id
        FROM public.ofx_movimento
       WHERE banco_id = p_banco_id AND fingerprint = v_movimento->>'fingerprint';
      v_resultado := v_resultado || jsonb_build_object(
        'fingerprint', v_movimento->>'fingerprint',
        'movimento_id', v_id,
        'repetido', true
      );
    ELSE
      v_importados := v_importados + 1;
      v_resultado := v_resultado || jsonb_build_object(
        'fingerprint', v_movimento->>'fingerprint',
        'movimento_id', v_id,
        'repetido', false
      );
    END IF;

    v_id := NULL;
  END LOOP;

  UPDATE public.ofx_importacao
     SET quantidade_importados = v_importados,
         quantidade_repetidos = v_repetidos
   WHERE id = v_importacao_id;

  RETURN jsonb_build_object(
    'importacao_id', v_importacao_id,
    'quantidade_movimentos', v_total,
    'quantidade_importados', v_importados,
    'quantidade_repetidos', v_repetidos,
    'movimentos', v_resultado
  );
END;
$$;


--
-- Name: FUNCTION registrar_importacao_ofx(p_banco_id bigint, p_arquivo_nome text, p_arquivo_hash text, p_cabecalho jsonb, p_movimentos jsonb, p_created_by uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_importacao_ofx(p_banco_id bigint, p_arquivo_nome text, p_arquivo_hash text, p_cabecalho jsonb, p_movimentos jsonb, p_created_by uuid) IS 'Grava um arquivo OFX e seus movimentos numa conta bancária, de uma vez. Recusa arquivo já importado e ignora movimento cujo fingerprint já existe na conta.';


--
-- Name: registrar_lancamento_de_eventos(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_lancamento_de_eventos(p_payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_os_id integer := nullif(p_payload->>'ordemservicoid', '')::integer;
  v_created_by uuid := nullif(p_payload->>'created_by', '')::uuid;
  v_pendente boolean := coalesce((p_payload->>'pendente')::boolean, true);
  v_data timestamptz := coalesce(nullif(p_payload->>'data', '')::timestamptz, now());
  v_metodo public.metodo_pagamento := nullif(p_payload->>'metodopagamento', '')::public.metodo_pagamento;
  v_categoria text := coalesce(nullif(p_payload->>'categoria', ''), 'NAO RELACIONADO');
  v_categoria_id integer := nullif(p_payload->>'categoria_id', '')::integer;
  v_plano_id integer := nullif(p_payload->>'plano_de_conta_id', '')::integer;
  v_centro_id integer := nullif(p_payload->>'centro_custo_id', '')::integer;
  v_fornecedor_id integer := nullif(p_payload->>'fornecedor_id', '')::integer;
  v_banco_id bigint := nullif(p_payload->>'banco_id', '')::bigint;
  v_nome text := coalesce(nullif(btrim(p_payload->>'nomepagador'), ''), 'Despesa interna');
  v_cpfcnpj text := coalesce(nullif(btrim(p_payload->>'cpfcnpjpagador'), ''), 'NAO INFORMADO');
  v_ids bigint[];
  v_os_ids integer[];
  v_qtd_os integer;
  v_qtd_vendas integer;
  v_os_efetiva integer;
  v_qtd integer;
  v_soma_eventos numeric(14,2);
  v_soma_linhas numeric(14,2);
  v_maus text;
  v_grupo_id bigint;
  v_descricao_grupo text;
  v_descricao text;
  v_total_parcelas integer;
  v_parcela record;
BEGIN
  IF jsonb_typeof(p_payload->'eventos_ids') <> 'array'
     OR jsonb_array_length(p_payload->'eventos_ids') = 0 THEN
    RAISE EXCEPTION 'Selecione ao menos uma despesa para lancar.' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_payload->'linhas') <> 'array'
     OR jsonb_array_length(p_payload->'linhas') = 0 THEN
    RAISE EXCEPTION 'Informe as parcelas do lancamento.' USING ERRCODE = 'P0001';
  END IF;

  SELECT array_agg(DISTINCT item::text::bigint)
    INTO v_ids
    FROM jsonb_array_elements(p_payload->'eventos_ids') AS item;

  -- Trava todas as despesas ate o fim desta transacao: duas telas lancando
  -- grupos que dividem uma despesa serializam aqui, e a segunda encontra o
  -- vinculo ja preenchido.
  PERFORM 1 FROM public.eventos_financeiros WHERE id = ANY (v_ids) FOR UPDATE;

  SELECT count(*), round(coalesce(sum(e.valor), 0), 2)
    INTO v_qtd, v_soma_eventos
    FROM public.eventos_financeiros e WHERE e.id = ANY (v_ids);

  IF v_qtd <> coalesce(array_length(v_ids, 1), 0) THEN
    RAISE EXCEPTION 'Uma ou mais despesas selecionadas nao existem mais.' USING ERRCODE = 'P0002';
  END IF;

  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids)
     AND (e.status <> 'ATIVO' OR e.transacaoid IS NOT NULL OR e.lancamento_id IS NOT NULL);
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Despesa(s) % ja foi(ram) lancada(s) no financeiro ou cancelada(s).', v_maus
      USING ERRCODE = 'P0001';
  END IF;

  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids) AND NOT e.pode_gerar_transacao;
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Despesa(s) % e(sao) lancamento(s) automatico(s) e nao gera(m) transacao.', v_maus
      USING ERRCODE = 'P0001';
  END IF;

  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids) AND e.natureza <> 'DESPESA';
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Lancamento(s) % nao e(sao) despesa.', v_maus USING ERRCODE = 'P0001';
  END IF;

  -- Além de OS, aceita comissão de venda com documento existente.
  -- Entradas e transações avulsas continuam fora deste caminho.
  SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
    FROM public.eventos_financeiros e
   WHERE e.id = ANY (v_ids) AND e.ordemservicoid IS NULL
     AND NOT (e.source_type IS NOT DISTINCT FROM 'VENDA'
              AND (e.origem = 'COMISSAO' OR (e.is_manual AND coalesce(e.chave_origem,'') LIKE 'MANUAL:%'))
              AND EXISTS (SELECT 1 FROM public.venda v WHERE v.id = e.source_id));
  IF v_maus IS NOT NULL THEN
    RAISE EXCEPTION 'Despesa(s) % nao pertence(m) a uma OS, comissao ou despesa manual de venda.', v_maus
      USING ERRCODE = 'P0001';
  END IF;

  -- Quem informa a OS continua preso a ela. E o caminho do painel da propria OS,
  -- que sabe de qual ordem esta falando; afrouxar ali so esconderia um engano.
  IF v_os_id IS NOT NULL THEN
    SELECT string_agg(e.id::text, ', ' ORDER BY e.id) INTO v_maus
      FROM public.eventos_financeiros e
     WHERE e.id = ANY (v_ids) AND e.ordemservicoid IS DISTINCT FROM v_os_id;
    IF v_maus IS NOT NULL THEN
      RAISE EXCEPTION 'Despesa(s) % nao pertence(m) a esta OS.', v_maus USING ERRCODE = 'P0001';
    END IF;
  END IF;

  SELECT array_agg(DISTINCT e.ordemservicoid) FILTER (WHERE e.ordemservicoid IS NOT NULL),
         count(DISTINCT e.source_id) FILTER (WHERE e.source_type = 'VENDA' AND e.ordemservicoid IS NULL)
    INTO v_os_ids, v_qtd_vendas
    FROM public.eventos_financeiros e WHERE e.id = ANY (v_ids);

  v_qtd_os := coalesce(array_length(v_os_ids, 1), 0);
  -- Uma OS so: grupo e parcelas ficam carimbados com ela, como sempre foram.
  -- Varias: nao ha resposta unica, e inventar uma seria pior que a ausencia.
  v_os_efetiva := CASE WHEN v_qtd_os = 1 AND v_qtd_vendas = 0 THEN v_os_ids[1] ELSE NULL END;

  SELECT round(coalesce(sum((item->>'valor')::numeric), 0), 2)
    INTO v_soma_linhas
    FROM jsonb_array_elements(p_payload->'linhas') AS item;

  IF v_soma_linhas <> v_soma_eventos THEN
    RAISE EXCEPTION 'A soma das parcelas (%) difere da soma das despesas selecionadas (%).',
      v_soma_linhas, v_soma_eventos USING ERRCODE = 'P0001';
  END IF;

  v_descricao_grupo := coalesce(
    nullif(btrim(p_payload->>'descricao'), ''),
    CASE WHEN v_os_efetiva IS NOT NULL
      THEN 'Despesas da OS #' || v_os_efetiva
      WHEN v_qtd_os = 0 THEN 'Despesas de ' || v_qtd_vendas || ' venda(s)'
      ELSE 'Despesas de ' || v_qtd_os || ' OS e ' || v_qtd_vendas || ' venda(s)'
    END);

  INSERT INTO public.lancamento_de_eventos (ordemservicoid, descricao, created_by)
  VALUES (v_os_efetiva, v_descricao_grupo, v_created_by)
  RETURNING id INTO v_grupo_id;

  SELECT max((item->>'total_parcelas')::integer) INTO v_total_parcelas
    FROM jsonb_array_elements(p_payload->'linhas') AS item;
  v_total_parcelas := greatest(coalesce(v_total_parcelas, 1), 1);

  FOR v_parcela IN
    SELECT (item->>'parcela')::integer AS numero,
           round((item->>'valor')::numeric, 2) AS valor,
           round(coalesce((item->>'valor_liquido')::numeric,
                          (item->>'valor')::numeric), 2) AS valor_liquido,
           nullif(item->>'vencimento_em', '') AS vencimento
      FROM jsonb_array_elements(p_payload->'linhas') AS item
     ORDER BY 1
  LOOP
    v_descricao := v_descricao_grupo;
    IF v_total_parcelas > 1 THEN
      v_descricao := v_descricao || ' - Parcela ' || v_parcela.numero || '/' || v_total_parcelas;
    END IF;

    INSERT INTO public.transacao (
      descricao, valor, "valorLiquido", data, vencimento_em, metodopagamento,
      categoria, categoria_id, plano_de_conta_id, centro_custo_id, tipo,
      fornecedor_id, banco_id, nomepagador, cpfcnpjpagador, pendente, pago_em,
      ordemservicoid, lancamento_id, created_by, baixado_por
    ) VALUES (
      v_descricao,
      v_parcela.valor,
      v_parcela.valor_liquido,
      coalesce(v_parcela.vencimento::timestamptz, v_data),
      v_parcela.vencimento::timestamptz,
      v_metodo, v_categoria, v_categoria_id, v_plano_id, v_centro_id,
      'DESPESA'::public.tipos_transacao,
      v_fornecedor_id,
      CASE WHEN v_pendente THEN NULL ELSE v_banco_id END,
      v_nome, v_cpfcnpj,
      v_pendente,
      CASE WHEN v_pendente THEN NULL ELSE v_data END,
      v_os_efetiva, v_grupo_id, v_created_by,
      CASE WHEN v_pendente THEN NULL ELSE v_created_by END
    );
  END LOOP;

  UPDATE public.eventos_financeiros
     SET status = 'CONVERTIDO', lancamento_id = v_grupo_id, updated_at = now()
   WHERE id = ANY (v_ids);

  RETURN v_grupo_id;
END;
$$;


--
-- Name: FUNCTION registrar_lancamento_de_eventos(p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_lancamento_de_eventos(p_payload jsonb) IS 'Persiste um lancamento de despesas de OS: o grupo, as P parcelas e a conversao das N despesas, numa transacao so. A OS do payload e opcional — quando vem, todas as despesas precisam ser dela; quando nao vem, as ordens saem dos proprios eventos e o grupo fica sem ordemservicoid se houver mais de uma.';


--
-- Name: registrar_pagamento_multiplo(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_pagamento_multiplo(p_payload jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo_documento text := upper(coalesce(p_payload->>'tipo_documento', ''));
  v_modo text := upper(coalesce(p_payload->>'modo', ''));
  v_valor_total numeric(14,2) := round(coalesce((p_payload->>'valor_total')::numeric, 0), 2);
  v_liquido_total numeric(14,2) := round(coalesce((p_payload->>'valor_liquido')::numeric, 0), 2);
  v_data timestamptz := coalesce(nullif(p_payload->>'data', '')::timestamptz, now());
  v_banco_id bigint := nullif(p_payload->>'banco_id', '')::bigint;
  v_metodo public.metodo_pagamento := nullif(p_payload->>'metodopagamento', '')::public.metodo_pagamento;
  v_created_by uuid := nullif(p_payload->>'created_by', '')::uuid;
  v_categoria text := coalesce(nullif(p_payload->>'categoria', ''), 'NÃO RELACIONADO');
  v_categoria_id integer := nullif(p_payload->>'categoria_id', '')::integer;
  v_plano_id integer := nullif(p_payload->>'plano_de_conta_id', '')::integer;
  v_centro_id integer := nullif(p_payload->>'centro_custo_id', '')::integer;
  v_pendente boolean := (v_modo = 'PARCELADO');
  v_grupo_id bigint;
  v_soma numeric(14,2);
  v_doc_id integer;
  v_documentos integer[] := ARRAY[]::integer[];
  v_cliente_id integer := nullif(p_payload->>'cliente_id', '')::integer;
  v_nome text := nullif(btrim(p_payload->>'nomepagador'), '');
  v_cpfcnpj text := nullif(btrim(p_payload->>'cpfcnpjpagador'), '');
  v_clientes integer[];
  v_descricao_grupo text;
  v_descricao text;
  v_parcela record;
  v_transacao_id bigint;
  v_total_parcelas integer;
  v_comprometido numeric(14,2);
  v_devido numeric(14,2);
  v_liquido numeric(14,2);
  v_liquido_acumulado numeric(14,2) := 0;
  v_indice integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(87009, 1);
  IF v_tipo_documento NOT IN ('OS', 'VENDA') THEN
    RAISE EXCEPTION 'tipo_documento deve ser OS ou VENDA.' USING ERRCODE = 'P0001';
  END IF;
  IF v_modo NOT IN ('AVISTA', 'PARCELADO') THEN
    RAISE EXCEPTION 'modo deve ser AVISTA ou PARCELADO.' USING ERRCODE = 'P0001';
  END IF;
  IF v_valor_total <= 0 THEN
    RAISE EXCEPTION 'O valor do pagamento deve ser maior que zero.' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_payload->'linhas') <> 'array'
     OR jsonb_array_length(p_payload->'linhas') = 0 THEN
    RAISE EXCEPTION 'Informe as linhas do rateio.' USING ERRCODE = 'P0001';
  END IF;

  -- Sem líquido informado, líquido é o próprio valor: não houve taxa.
  IF v_liquido_total <= 0 THEN v_liquido_total := v_valor_total; END IF;

  SELECT round(coalesce(sum((item->>'valor')::numeric), 0), 2) INTO v_soma
    FROM jsonb_array_elements(p_payload->'linhas') AS item;

  IF v_soma <> v_valor_total THEN
    RAISE EXCEPTION 'A soma do rateio (%) difere do valor do pagamento (%).',
      v_soma, v_valor_total USING ERRCODE = 'P0001';
  END IF;

  SELECT array_agg(DISTINCT (item->>'documento_id')::integer ORDER BY (item->>'documento_id')::integer)
    INTO v_documentos
    FROM jsonb_array_elements(p_payload->'linhas') AS item;

  FOREACH v_doc_id IN ARRAY v_documentos LOOP
    PERFORM pg_advisory_xact_lock(87001, v_doc_id);
    IF v_tipo_documento = 'OS' THEN PERFORM public.validar_novo_recebimento_os(v_doc_id); END IF;
  END LOOP;

  IF v_cliente_id IS NULL THEN
    IF v_tipo_documento = 'OS' THEN
      SELECT array_agg(DISTINCT o.clienteid) INTO v_clientes
        FROM public.ordemservico o WHERE o.id = ANY (v_documentos);
    ELSE
      SELECT array_agg(DISTINCT v.clienteid) INTO v_clientes
        FROM public.venda v WHERE v.id = ANY (v_documentos);
    END IF;

    IF array_length(v_clientes, 1) = 1 THEN
      v_cliente_id := v_clientes[1];
    END IF;
  END IF;

  IF v_cliente_id IS NOT NULL AND (v_nome IS NULL OR v_cpfcnpj IS NULL) THEN
    SELECT coalesce(v_nome, c.nomerazaosocial), coalesce(v_cpfcnpj, c.cpfcnpj)
      INTO v_nome, v_cpfcnpj
      FROM public.cliente c WHERE c.id = v_cliente_id;
  END IF;

  v_descricao_grupo := coalesce(
    nullif(btrim(p_payload->>'descricao'), ''),
    'Pagamento múltiplo de ' || array_length(v_documentos, 1) || ' documento(s)');

  INSERT INTO public.pagamento_multiplo (
    descricao, modo, tipo_documento, valor_total, data, banco_id, metodopagamento, created_by
  ) VALUES (
    v_descricao_grupo, v_modo, v_tipo_documento, v_valor_total, v_data,
    v_banco_id, v_metodo, v_created_by
  ) RETURNING id INTO v_grupo_id;

  SELECT max((item->>'total_parcelas')::integer) INTO v_total_parcelas
    FROM jsonb_array_elements(p_payload->'linhas') AS item;
  v_total_parcelas := greatest(coalesce(v_total_parcelas, 1), 1);

  FOR v_parcela IN
    SELECT (item->>'parcela')::integer AS numero,
           round(sum((item->>'valor')::numeric), 2) AS valor,
           min(nullif(item->>'vencimento_em', '')) AS vencimento
      FROM jsonb_array_elements(p_payload->'linhas') AS item
     GROUP BY (item->>'parcela')::integer
     ORDER BY 1
  LOOP
    v_indice := v_indice + 1;

    -- O líquido acompanha a proporção do valor. A última parcela leva a sobra
    -- para a soma dos líquidos fechar exatamente com o informado.
    IF v_indice = v_total_parcelas THEN
      v_liquido := round(v_liquido_total - v_liquido_acumulado, 2);
    ELSE
      v_liquido := round(v_parcela.valor * v_liquido_total / v_valor_total, 2);
      v_liquido_acumulado := v_liquido_acumulado + v_liquido;
    END IF;

    v_descricao := v_descricao_grupo;
    IF v_total_parcelas > 1 THEN
      v_descricao := v_descricao || ' - Parcela ' || v_parcela.numero || '/' || v_total_parcelas;
    END IF;

    INSERT INTO public.transacao (
      descricao, valor, "valorLiquido", data, metodopagamento, categoria, categoria_id,
      plano_de_conta_id, centro_custo_id, tipo, cliente_id, banco_id,
      nomepagador, cpfcnpjpagador, pendente, pago_em,
      ordemservicoid, vendaid, pagamento_multiplo_id, created_by
    ) VALUES (
      v_descricao,
      v_parcela.valor,
      greatest(v_liquido, 0),
      coalesce(v_parcela.vencimento::timestamptz, v_data),
      v_metodo, v_categoria, v_categoria_id, v_plano_id, v_centro_id,
      'RECEITA'::public.tipos_transacao, v_cliente_id,
      CASE WHEN v_pendente THEN NULL ELSE v_banco_id END,
      coalesce(v_nome, 'Diversos'),
      coalesce(v_cpfcnpj, 'NÃO INFORMADO'),
      v_pendente,
      CASE WHEN v_pendente THEN NULL ELSE v_data END,
      NULL, NULL,
      v_grupo_id, v_created_by
    ) RETURNING id INTO v_transacao_id;

    INSERT INTO public.pagamento_multiplo_rateio (
      pagamento_multiplo_id, transacao_id, tipo_documento, documento_id, valor
    )
    SELECT v_grupo_id, v_transacao_id, v_tipo_documento,
           (item->>'documento_id')::integer,
           round((item->>'valor')::numeric, 2)
      FROM jsonb_array_elements(p_payload->'linhas') AS item
     WHERE (item->>'parcela')::integer = v_parcela.numero
       AND round((item->>'valor')::numeric, 2) > 0;
  END LOOP;

  FOREACH v_doc_id IN ARRAY v_documentos LOOP
    IF v_tipo_documento = 'OS' THEN
      SELECT r.total_devido, r.valor_comprometido
        INTO v_devido, v_comprometido
        FROM public.resumo_financeiro_os(v_doc_id) r;
    ELSE
      SELECT round(
               greatest(coalesce(v.valortotal, 0), 0) +
               CASE
                 WHEN v.acrescimo_financeiro_tipo = 'PORCENTAGEM' THEN
                   greatest(coalesce(v.valortotal, 0), 0) *
                   least(greatest(coalesce(v.acrescimo_financeiro_valor, 0), 0), 100) / 100
                 WHEN v.acrescimo_financeiro_tipo = 'FIXO' THEN
                   greatest(coalesce(v.acrescimo_financeiro_valor, 0), 0)
                 ELSE 0
               END, 2)
        INTO v_devido
        FROM public.venda v WHERE v.id = v_doc_id;

      SELECT coalesce(round(sum(r.valor), 2), 0) INTO v_comprometido
        FROM public.recebimento_por_documento r
       WHERE r.tipo_documento = 'VENDA' AND r.documento_id = v_doc_id;
    END IF;

    IF coalesce(v_devido, 0) <= 0 THEN
      RAISE EXCEPTION 'O documento #% não possui valor financeiro disponível para pagamento.',
        v_doc_id USING ERRCODE = '23514';
    END IF;
    IF round(coalesce(v_comprometido, 0), 2) > v_devido THEN
      RAISE EXCEPTION 'O rateio ultrapassa o saldo do documento #%: comprometido % de %.',
        v_doc_id, v_comprometido, v_devido USING ERRCODE = '23514';
    END IF;
  END LOOP;

  RETURN v_grupo_id;
END;
$$;


--
-- Name: registrar_saida_estoque(integer, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_saida_estoque(p_produto_id integer, p_quantidade integer, p_motivo text, p_observacao text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_produto public.produto%ROWTYPE;
  v_saida_id bigint;
  v_motivo text := upper(btrim(coalesce(p_motivo, '')));
  v_observacao text := nullif(btrim(p_observacao), '');
  v_saldo_anterior integer;
  v_saldo_resultante integer;
  v_custo numeric(14,4);
BEGIN
  IF p_produto_id IS NULL OR p_produto_id <= 0 THEN
    RAISE EXCEPTION 'Produto invalido.' USING ERRCODE = '22023';
  END IF;
  IF p_quantidade IS NULL OR p_quantidade <= 0 THEN
    RAISE EXCEPTION 'A quantidade deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tipos_motivo_saida
    WHERE codigo = v_motivo AND ativo AND escopo IN ('PRODUTO', 'AMBOS')
  ) THEN
    RAISE EXCEPTION 'Motivo de saida invalido.' USING ERRCODE = '22023';
  END IF;
  IF v_motivo = 'OUTRO' AND v_observacao IS NULL THEN
    RAISE EXCEPTION 'Informe a observacao para o motivo Outro.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_produto
  FROM public.produto
  WHERE id = p_produto_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  v_saldo_anterior := coalesce(v_produto.estoque, 0)::integer;
  IF v_saldo_anterior < p_quantidade THEN
    RAISE EXCEPTION 'Estoque insuficiente. Disponivel: %, solicitado: %.', v_saldo_anterior, p_quantidade
      USING ERRCODE = '23514';
  END IF;
  v_saldo_resultante := v_saldo_anterior - p_quantidade;
  v_custo := greatest(coalesce(v_produto.ultimovalordecompra, v_produto.precocompra, 0), 0);

  INSERT INTO public.estoque_saida (motivo, observacao, created_by)
  VALUES (v_motivo, v_observacao, p_created_by)
  RETURNING id INTO v_saida_id;

  INSERT INTO public.estoque_saida_item (
    saida_id, produto_id, quantidade, saldo_anterior, saldo_resultante, valor_custo_aplicado
  ) VALUES (
    v_saida_id, p_produto_id, p_quantidade, v_saldo_anterior, v_saldo_resultante, v_custo
  );

  PERFORM public.estoque_definir_contexto(
    'SAIDA_MANUAL', v_saida_id, 'Saida #' || v_saida_id || ' - ' || replace(v_motivo, '_', ' '), p_created_by
  );

  UPDATE public.produto
  SET estoque = v_saldo_resultante,
      updatedat = now()
  WHERE id = p_produto_id;

  RETURN jsonb_build_object(
    'saida_id', v_saida_id,
    'saldo_anterior', v_saldo_anterior,
    'saldo_resultante', v_saldo_resultante
  );
END;
$$;


--
-- Name: registrar_saida_usoconsumo(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_saida_usoconsumo(p_saida jsonb, p_itens jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saida_id bigint; v_json jsonb; v_item public.usoconsumo_item%ROWTYPE;
  v_item_id integer; v_qtd integer; v_user uuid; v_motivo text;
  v_escopo text := upper(btrim(coalesce(p_saida->>'escopo','USOCONSUMO')));
BEGIN
  IF jsonb_typeof(p_itens)<>'array' OR jsonb_array_length(p_itens)=0 THEN
    RAISE EXCEPTION 'Informe ao menos um item.' USING ERRCODE='22023';
  END IF;
  IF v_escopo NOT IN ('USOCONSUMO','GERAL') THEN
    RAISE EXCEPTION 'Escopo de estoque invalido: %.', v_escopo USING ERRCODE='22023';
  END IF;
  v_motivo := upper(btrim(coalesce(p_saida->>'motivo','')));
  IF NOT EXISTS (
    SELECT 1 FROM public.tipos_motivo_saida
    WHERE codigo = v_motivo AND ativo AND escopo IN ('USOCONSUMO', 'AMBOS')
  ) THEN RAISE EXCEPTION 'Motivo invalido.' USING ERRCODE='22023'; END IF;
  IF v_motivo='OUTRO' AND nullif(btrim(p_saida->>'observacao'),'') IS NULL THEN
    RAISE EXCEPTION 'Informe a observacao.' USING ERRCODE='22023';
  END IF;
  v_user:=nullif(p_saida->>'created_by','')::uuid;
  INSERT INTO public.usoconsumo_saida(escopo,motivo,observacao,setor,funcionario,centro_custo_id,created_by)
  VALUES(v_escopo,v_motivo,nullif(btrim(p_saida->>'observacao'),''),nullif(btrim(p_saida->>'setor'),''),
    nullif(btrim(p_saida->>'funcionario'),''),nullif(p_saida->>'centro_custo_id','')::integer,v_user)
  RETURNING id INTO v_saida_id;
  FOR v_json IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    v_item_id:=nullif(v_json->>'item_id','')::integer; v_qtd:=nullif(v_json->>'quantidade','')::integer;
    IF v_item_id IS NULL OR v_qtd IS NULL OR v_qtd<=0 THEN
      RAISE EXCEPTION 'Item ou quantidade invalida.' USING ERRCODE='22023';
    END IF;
    SELECT * INTO v_item FROM public.usoconsumo_item WHERE id=v_item_id AND ativo AND escopo=v_escopo FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item % nao encontrado neste estoque.',v_item_id USING ERRCODE='P0002';
    END IF;
    IF v_item.estoque<v_qtd THEN
      RAISE EXCEPTION 'Estoque insuficiente para o item %.',v_item_id USING ERRCODE='23514';
    END IF;
    INSERT INTO public.usoconsumo_saida_item(saida_id,item_id,quantidade,saldo_anterior,saldo_resultante,valor_custo_aplicado)
      VALUES(v_saida_id,v_item_id,v_qtd,v_item.estoque,v_item.estoque-v_qtd,coalesce(v_item.ultimovalordecompra,v_item.precocompra,0));
    PERFORM set_config('app.usoconsumo_movimento','permitido',true);
    UPDATE public.usoconsumo_item SET estoque=estoque-v_qtd,updated_by=v_user WHERE id=v_item_id;
  END LOOP;
  RETURN jsonb_build_object('saida_id',v_saida_id,'escopo',v_escopo);
END $$;


--
-- Name: registrar_transferencia_entre_contas(numeric, timestamp with time zone, bigint, bigint, text, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.registrar_transferencia_entre_contas(p_valor numeric, p_data timestamp with time zone, p_banco_origem_id bigint, p_banco_destino_id bigint, p_metodopagamento text, p_descricao text DEFAULT NULL::text, p_plano_de_conta_id integer DEFAULT NULL::integer, p_centro_custo_id integer DEFAULT NULL::integer, p_criado_por uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_metodo public.metodo_pagamento;
  v_valor numeric(14,2);
  v_origem text;
  v_destino text;
  v_categoria_id integer;
  v_transferencia_id bigint;
  v_saida_id bigint;
  v_entrada_id bigint;
  v_descricao text;
BEGIN
  IF p_valor IS NULL OR round(p_valor, 2) <= 0 THEN
    RAISE EXCEPTION 'O valor da transferencia deve ser maior que zero.'
      USING ERRCODE = '22023';
  END IF;
  v_valor := round(p_valor, 2);

  IF p_data IS NULL THEN
    RAISE EXCEPTION 'Data da transferencia obrigatoria.' USING ERRCODE = '22023';
  END IF;

  IF p_banco_origem_id IS NULL OR p_banco_destino_id IS NULL THEN
    RAISE EXCEPTION 'Informe a conta de origem e a de destino.' USING ERRCODE = '22023';
  END IF;

  IF p_banco_origem_id = p_banco_destino_id THEN
    RAISE EXCEPTION
      'A conta de origem e a de destino sao a mesma: nao ha transferencia a registrar.'
      USING ERRCODE = '22023';
  END IF;

  IF nullif(btrim(p_metodopagamento), '') IS NULL THEN
    RAISE EXCEPTION 'Metodo de pagamento obrigatorio.' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_metodo := btrim(p_metodopagamento)::public.metodo_pagamento;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Metodo de pagamento invalido: %.', btrim(p_metodopagamento)
      USING ERRCODE = '22023';
  END;

  SELECT titulo INTO v_origem FROM public.bancoconta WHERE id = p_banco_origem_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conta de origem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  SELECT titulo INTO v_destino FROM public.bancoconta WHERE id = p_banco_destino_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conta de destino nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  v_origem := coalesce(nullif(btrim(v_origem), ''), 'conta #' || p_banco_origem_id);
  v_destino := coalesce(nullif(btrim(v_destino), ''), 'conta #' || p_banco_destino_id);
  v_descricao := nullif(btrim(coalesce(p_descricao, '')), '');

  SELECT id INTO v_categoria_id
    FROM public.categoriatransacao WHERE codigo_sistema = 'TRANSFERENCIA' LIMIT 1;

  INSERT INTO public.transacao_transferencia
    (valor, data, banco_origem_id, banco_destino_id, metodopagamento,
     descricao, criado_por)
  VALUES
    (v_valor, p_data, p_banco_origem_id, p_banco_destino_id, v_metodo,
     v_descricao, p_criado_por)
  RETURNING id INTO v_transferencia_id;

  INSERT INTO public.transacao (
    descricao, valor, valor_base, "valorLiquido",
    valor_acrescimos, valor_descontos,
    data, competencia_em, vencimento_em, pago_em,
    tipo, pendente, banco_id, metodopagamento,
    nomepagador, cpfcnpjpagador,
    categoria_id, plano_de_conta_id, centro_custo_id,
    transferencia_id, created_by, baixado_por
  ) VALUES (
    coalesce(v_descricao, 'Transferencia para ' || v_destino),
    v_valor, v_valor, v_valor, 0, 0,
    p_data, p_data, p_data, p_data,
    'SAQUE'::public.tipos_transacao, false, p_banco_origem_id, v_metodo,
    v_destino, 'NAO INFORMADO',
    v_categoria_id, p_plano_de_conta_id, p_centro_custo_id,
    v_transferencia_id, p_criado_por, p_criado_por
  ) RETURNING id INTO v_saida_id;

  INSERT INTO public.transacao (
    descricao, valor, valor_base, "valorLiquido",
    valor_acrescimos, valor_descontos,
    data, competencia_em, vencimento_em, pago_em,
    tipo, pendente, banco_id, metodopagamento,
    nomepagador, cpfcnpjpagador,
    categoria_id, plano_de_conta_id, centro_custo_id,
    transferencia_id, created_by, baixado_por
  ) VALUES (
    coalesce(v_descricao, 'Transferencia de ' || v_origem),
    v_valor, v_valor, v_valor, 0, 0,
    p_data, p_data, p_data, p_data,
    'DEPOSITO'::public.tipos_transacao, false, p_banco_destino_id, v_metodo,
    v_origem, 'NAO INFORMADO',
    v_categoria_id, p_plano_de_conta_id, p_centro_custo_id,
    v_transferencia_id, p_criado_por, p_criado_por
  ) RETURNING id INTO v_entrada_id;

  RETURN jsonb_build_object(
    'transferencia_id', v_transferencia_id,
    'saida_id', v_saida_id,
    'entrada_id', v_entrada_id,
    'valor', v_valor,
    'banco_origem', v_origem,
    'banco_destino', v_destino
  );
END;
$$;


--
-- Name: FUNCTION registrar_transferencia_entre_contas(p_valor numeric, p_data timestamp with time zone, p_banco_origem_id bigint, p_banco_destino_id bigint, p_metodopagamento text, p_descricao text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_criado_por uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.registrar_transferencia_entre_contas(p_valor numeric, p_data timestamp with time zone, p_banco_origem_id bigint, p_banco_destino_id bigint, p_metodopagamento text, p_descricao text, p_plano_de_conta_id integer, p_centro_custo_id integer, p_criado_por uuid) IS 'Move dinheiro entre duas contas proprias: SAQUE na origem e DEPOSITO no destino, ambos liquidados, ligados e fora do resultado. A contraparte de cada perna e o titulo da outra conta.';


--
-- Name: reparcelar_transacao(bigint, jsonb, uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparcelar_transacao(p_transacao_id bigint, p_parcelas jsonb, p_alterado_por uuid DEFAULT NULL::uuid, p_motivo text DEFAULT NULL::text, p_total_anterior numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET lock_timeout TO '5s'
    AS $_$
DECLARE
  v_tx public.transacao%ROWTYPE;
  v_modo text;
  v_grupo_tipo text;
  v_grupo_id bigint;
  v_grupo_ids bigint[];
  v_base text;
  v_novas int;
  v_pendentes int;
  v_alvo bigint;
  v_soma bigint;
  v_template public.transacao%ROWTYPE;
  v_anterior public.transacao%ROWTYPE;
  v_ids_pendentes bigint[];
  v_familia bigint[];
  v_item record;
  v_id bigint;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
  v_total int;
  v_resultado jsonb := '[]'::jsonb;
BEGIN
  -------------------------------------------------------------------------
  -- 1) Formato do payload
  -------------------------------------------------------------------------
  IF p_parcelas IS NULL
     OR jsonb_typeof(p_parcelas) <> 'array'
     OR jsonb_array_length(p_parcelas) = 0 THEN
    RAISE EXCEPTION 'Informe ao menos uma parcela.' USING ERRCODE = '22023';
  END IF;

  v_novas := jsonb_array_length(p_parcelas);

  -- Teto de sanidade: o formulario nao oferece nada perto disso, e sem limite um
  -- payload torto viraria centenas de linhas gravadas.
  IF v_novas > 60 THEN
    RAISE EXCEPTION 'Um parcelamento pode ter no maximo 60 parcelas.' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN
    SELECT indice AS posicao,
           round((parcela->>'valor')::numeric, 2) AS valor,
           (parcela->>'data')::timestamptz AS data
      FROM jsonb_array_elements(p_parcelas) WITH ORDINALITY AS t(parcela, indice)
  LOOP
    IF v_item.valor IS NULL OR v_item.valor <= 0 THEN
      RAISE EXCEPTION 'O valor da parcela % deve ser maior que zero.', v_item.posicao
        USING ERRCODE = '22023';
    END IF;

    -- A data pode ser passada: renegociar um titulo vencido e justamente quando
    -- se reparcela. O que nao pode e nao ter data.
    IF v_item.data IS NULL THEN
      RAISE EXCEPTION 'Informe o vencimento da parcela %.', v_item.posicao
        USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -------------------------------------------------------------------------
  -- 2) O MODO — derivado da linha gravada, nunca recebido
  -------------------------------------------------------------------------
  SELECT * INTO v_tx FROM public.transacao
   WHERE id = p_transacao_id AND is_deleted = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transacao nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  /*
   * A ordem da cascata e a regra: os bloqueios primeiro.
   *
   * Uma linha pode ter dois vinculos ao mesmo tempo — um pagamento multiplo
   * aponta para a OS e para o rateio. Perguntar primeiro pela OS classificaria
   * como reparcelavel algo que so o rateio sabe dividir.
   *
   * `modoDeReparcelamento`, no cliente, repete esta mesma cascata. A de la
   * decide qual botao a tela mostra; esta decide o que pode ser escrito.
   */
  IF v_tx.transferencia_id IS NOT NULL THEN
    RAISE EXCEPTION 'Transferencia entre contas nao e parcelamento: as duas pernas sao o mesmo dinheiro e mudam juntas.'
      USING ERRCODE = '22023';
  ELSIF v_tx.pagamento_multiplo_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este lancamento cobre varios documentos. Quem divide o valor dele e o rateio do pagamento multiplo.'
      USING ERRCODE = '22023';
  ELSIF v_tx.evento_financeiro_id IS NOT NULL THEN
    RAISE EXCEPTION 'Lancamento de evento financeiro e um por evento e nao se divide em parcelas.'
      USING ERRCODE = '22023';
  ELSIF v_tx.adiantamento_id IS NOT NULL OR coalesce(v_tx.eh_adiantamento, false) THEN
    RAISE EXCEPTION 'Titulo antecipado responde ao contrato com o banco e nao pode ser reparcelado aqui.'
      USING ERRCODE = '22023';
  ELSIF v_tx.ordemservicoid IS NOT NULL THEN
    v_modo := 'VINCULADO'; v_grupo_tipo := 'OS';    v_grupo_id := v_tx.ordemservicoid;
  ELSIF v_tx.vendaid IS NOT NULL THEN
    v_modo := 'VINCULADO'; v_grupo_tipo := 'VENDA'; v_grupo_id := v_tx.vendaid;
  ELSIF v_tx.parcelamento_id IS NOT NULL THEN
    v_grupo_tipo := 'PARCELAMENTO'; v_grupo_id := v_tx.parcelamento_id;
    -- Nota de compra: grupo formal, total travado. O total e da nota, dado dela;
    -- a divisao em parcelas e que e livre. Preserva 20260903260000.
    v_modo := CASE WHEN v_tx.entrada_id IS NOT NULL
                     OR v_tx.usoconsumo_entrada_id IS NOT NULL
                   THEN 'VINCULADO' ELSE 'AVULSO' END;
  ELSE
    RAISE EXCEPTION 'Esta transacao nao faz parte de um parcelamento, ou o grupo dela e anterior ao registro de parcelamentos.'
      USING ERRCODE = '22023';
  END IF;

  -------------------------------------------------------------------------
  -- 3) O LOCK, antes de qualquer soma
  -------------------------------------------------------------------------
  /*
   * Sem isto duas telas reparcelam ao mesmo tempo e cada uma fecha a conta
   * contra um estado velho.
   *
   * `ORDER BY id` e a ordem que impede duas chamadas de travarem uma a outra —
   * o deadlock fechado em 20260817120000. E de proposito NAO pego
   * `pg_advisory_xact_lock(87001, os)` aqui: quem o pega e
   * `validar_limite_pagamento_os`, DEPOIS dos locks de linha. Adquiri-lo antes
   * inverteria a ordem em relacao ao resto do sistema.
   */
  BEGIN
    PERFORM 1
       FROM public.transacao
      WHERE is_deleted = false
        AND ((v_grupo_tipo = 'PARCELAMENTO' AND parcelamento_id = v_grupo_id)
          OR (v_grupo_tipo = 'OS' AND ordemservicoid = v_grupo_id
              AND upper(tipo::text) = 'RECEITA' AND evento_financeiro_id IS NULL)
          OR (v_grupo_tipo = 'VENDA' AND vendaid = v_grupo_id
              AND upper(tipo::text) = 'RECEITA' AND evento_financeiro_id IS NULL))
      ORDER BY id
        FOR UPDATE;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'Outra pessoa esta salvando este parcelamento neste momento. Espere alguns segundos e tente de novo.'
      USING ERRCODE = '55P03';
  END;

  -- Sob a trava o conjunto e estavel: materializa uma vez e o resto da funcao
  -- trabalha por id, em vez de repetir o predicado do grupo em toda consulta.
  SELECT array_agg(id ORDER BY id) INTO v_grupo_ids
    FROM public.transacao
   WHERE is_deleted = false
     AND ((v_grupo_tipo = 'PARCELAMENTO' AND parcelamento_id = v_grupo_id)
       OR (v_grupo_tipo = 'OS' AND ordemservicoid = v_grupo_id
           AND upper(tipo::text) = 'RECEITA' AND evento_financeiro_id IS NULL)
       OR (v_grupo_tipo = 'VENDA' AND vendaid = v_grupo_id
           AND upper(tipo::text) = 'RECEITA' AND evento_financeiro_id IS NULL));

  /*
   * Grupo formal que mistura origens nao se conserta escrevendo nele.
   *
   * Um `parcelamento_id` com uma parcela ligada a documento e outra nao e grupo
   * torto: a renumeracao e a soma passariam a valer para linhas que respondem a
   * donos diferentes.
   */
  IF v_grupo_tipo = 'PARCELAMENTO' AND EXISTS (
    SELECT 1 FROM public.transacao
     WHERE id = ANY(v_grupo_ids)
       AND (ordemservicoid IS NOT NULL
         OR vendaid IS NOT NULL
         OR pagamento_multiplo_id IS NOT NULL
         OR evento_financeiro_id IS NOT NULL
         OR adiantamento_id IS NOT NULL
         OR coalesce(eh_adiantamento, false)
         OR transferencia_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Este parcelamento mistura lancamentos de origens diferentes e nao pode ser reparcelado por aqui.'
      USING ERRCODE = '22023';
  END IF;

  -------------------------------------------------------------------------
  -- 4) As pendentes: alvo e ordem de reaproveitamento
  -------------------------------------------------------------------------
  SELECT count(*), coalesce(sum(round(valor * 100)), 0),
         array_agg(id ORDER BY data, id)
    INTO v_pendentes, v_alvo, v_ids_pendentes
    FROM public.transacao
   WHERE id = ANY(v_grupo_ids) AND pendente = true;

  IF v_pendentes = 0 THEN
    RAISE EXCEPTION 'Todas as parcelas deste parcelamento ja foram baixadas. Para corrigir, exclua e lance de novo.'
      USING ERRCODE = '22023';
  END IF;

  /*
   * Titulo com baixa PARCIAL fica pendente, mas nao e folha em branco.
   *
   * Ele tem transacoes filhas apontando para ele por `baixa_de_transacao_id`, e
   * `transacao_baixa_parcial_coerente_trg` guarda a coerencia entre elas.
   * Reparcelar podia baixar o valor dele para menos do que ja entrou, ou
   * soft-deleta-lo deixando as baixas orfas. Com o total livre no modo avulso
   * isso deixou de ser hipotese remota.
   */
  IF EXISTS (
    SELECT 1 FROM public.transacao
     WHERE id = ANY(v_grupo_ids) AND pendente = true
       AND coalesce(valor_baixado, 0) > 0
  ) THEN
    RAISE EXCEPTION 'Ha parcela com baixa parcial neste grupo. Estorne a baixa antes de reparcelar.'
      USING ERRCODE = '22023';
  END IF;

  -------------------------------------------------------------------------
  -- 5) A SOMA — o unico ponto onde os dois modos divergem
  -------------------------------------------------------------------------
  SELECT coalesce(sum(round((parcela->>'valor')::numeric * 100)), 0)
    INTO v_soma
    FROM jsonb_array_elements(p_parcelas) AS parcela;

  IF v_modo = 'VINCULADO' AND v_soma <> v_alvo THEN
    RAISE EXCEPTION
      'A soma das parcelas deve continuar em R$ %; foi informado R$ %.',
      replace(to_char(v_alvo / 100.0, 'FM999999990.00'), '.', ','),
      replace(to_char(v_soma / 100.0, 'FM999999990.00'), '.', ',')
      USING ERRCODE = '22023';
  END IF;

  /*
   * No modo avulso a soma e livre — e com ela some a defesa contra duas telas
   * salvando em cima uma da outra: antes, a segunda errava porque o alvo ja nao
   * era o mesmo. `p_total_anterior` e o total pendente que a tela viu ao abrir.
   * Mesmo desenho do `valorAnterior` de `ajustar_valores_transacao`.
   */
  IF p_total_anterior IS NOT NULL AND round(p_total_anterior * 100) <> v_alvo THEN
    RAISE EXCEPTION 'As parcelas mudaram depois que esta tela foi aberta. Recarregue e refaca o reparcelamento.'
      USING ERRCODE = '40001';
  END IF;

  SELECT * INTO v_template FROM public.transacao WHERE id = v_ids_pendentes[1];

  -- A base da descricao, sem o sufixo de parcela. No grupo formal ela e dado
  -- guardado; no documento e derivada da linha aberta, e e ela que define quais
  -- irmas entram na renumeracao la embaixo.
  IF v_grupo_tipo = 'PARCELAMENTO' THEN
    SELECT descricao INTO v_base FROM public.transacao_parcelamento WHERE id = v_grupo_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Parcelamento nao encontrado.' USING ERRCODE = 'P0002';
    END IF;
  ELSE
    v_base := regexp_replace(v_tx.descricao, ' - Parcela [0-9]+/[0-9]+$', '');
  END IF;

  -------------------------------------------------------------------------
  -- 6) AS ESCRITAS, e a ordem delas
  -------------------------------------------------------------------------
  /*
   * A ordem aqui e obrigatoria, nao estetica.
   *
   * `validar_limite_pagamento_os` roda a cada UPDATE de `valor` e soma as OUTRAS
   * linhas da OS como elas estao NAQUELE INSTANTE — nunca ve o resultado final
   * do lote. Foi exatamente isso que 20260828150000 corrigiu no rateio: uma
   * parcela subindo antes de outra descer estourava o total por R$ 0,33 e a
   * chamada morria num estado que ninguem pediu.
   *
   * Aqui ha um agravante que o rateio nao tem: parcela nova e so aumento. Entao:
   *
   *   a) exclusao logica das excedentes   (descida)
   *   b) UPDATE das reaproveitadas, ORDER BY delta  (descidas, depois subidas)
   *   c) INSERT das novas                 (subida pura, por ultimo)
   *
   * Como no modo vinculado a soma e invariante, nenhuma soma parcial passa do
   * total final. No modo avulso nao ha OS para o gatilho olhar, e a ordem e
   * inofensiva — vale para os dois por simetria.
   *
   * Nao reabre deadlock: as linhas ja estao travadas por id no passo 3.
   * Reordenar UPDATEs nao adquire lock novo.
   */

  -- (a) Sobrou parcela pendente: some por exclusao logica, o mesmo estado de uma
  -- transacao excluida pela tela. Hard delete apagaria a trilha de quem tirou.
  IF v_novas < v_pendentes THEN
    UPDATE public.transacao
       SET is_deleted = true,
           deleted_at = now(),
           deleted_by = p_alterado_por,
           updated_at = now()
     WHERE id = ANY(v_ids_pendentes[(v_novas + 1):v_pendentes]);
  END IF;

  -- (b) As reaproveitadas, da que mais desce para a que mais sobe.
  FOR v_item IN
    SELECT t.indice AS posicao,
           round((t.parcela->>'valor')::numeric, 2) AS valor,
           (t.parcela->>'data')::timestamptz AS data,
           round((t.parcela->>'valor')::numeric, 2)
             - (SELECT valor FROM public.transacao WHERE id = v_ids_pendentes[t.indice])
             AS delta
      FROM jsonb_array_elements(p_parcelas) WITH ORDINALITY AS t(parcela, indice)
     WHERE t.indice <= v_pendentes
     ORDER BY delta, t.indice
  LOOP
    v_id := v_ids_pendentes[v_item.posicao];

    SELECT * INTO v_anterior FROM public.transacao WHERE id = v_id;

    UPDATE public.transacao
       SET valor = v_item.valor,
           -- Havendo desconto lancado, `tg_transacao_valor_coerente` regrava
           -- este campo como `valor - descontos` logo em seguida. E o certo: o
           -- liquido e resultado das linhas de ajuste, nao entrada.
           "valorLiquido" = v_item.valor,
           data = v_item.data,
           -- So acompanha quando ja existia: em parcela pendente o vencimento
           -- mora em `data`, e `vencimento_em` e o retrato tirado na baixa.
           -- Preenche-lo agora criaria um retrato de algo que nao aconteceu.
           vencimento_em = CASE WHEN vencimento_em IS NULL THEN NULL ELSE v_item.data END,
           updated_at = now(),
           updated_by = coalesce(p_alterado_por, updated_by)
     WHERE id = v_id;

    IF round(coalesce(v_anterior.valor, 0) * 100) <> round(v_item.valor * 100) THEN
      INSERT INTO public.transacao_valor_historico (
        transacao_id, valor_anterior, valor_novo,
        valor_liquido_anterior, valor_liquido_novo, alterado_por, motivo
      ) VALUES (
        v_id, v_anterior.valor, v_item.valor,
        v_anterior."valorLiquido", v_item.valor, p_alterado_por,
        coalesce(v_motivo, 'Reparcelamento')
      );
    END IF;

    v_resultado := v_resultado || jsonb_build_object(
      'id', v_id, 'valor', v_item.valor, 'data', v_item.data);
  END LOOP;

  -- (c) As que nascem agora.
  IF v_novas > v_pendentes THEN
    -- Dispensa so o gate de STATUS, e so aqui dentro: ver o bloco 1 no topo
    -- desta migration. O teto de valor da OS continua sendo cobrado a cada
    -- INSERT, por `validar_limite_pagamento_os`.
    PERFORM set_config('app.reparcelamento_em_curso', 'permitido', true);

    FOR v_item IN
      SELECT t.indice AS posicao,
             round((t.parcela->>'valor')::numeric, 2) AS valor,
             (t.parcela->>'data')::timestamptz AS data
        FROM jsonb_array_elements(p_parcelas) WITH ORDINALITY AS t(parcela, indice)
       WHERE t.indice > v_pendentes
       ORDER BY t.indice
    LOOP
      /*
       * Herda o vinculo com o documento, e SO ele.
       *
       * Sem `ordemservicoid`/`vendaid`/`entrada_id` a parcela sai orfa: o
       * documento passaria a ter menos titulos do que vale, a conferencia nao
       * fecharia e a linha viraria receita avulsa na DRE.
       *
       * O que ela nunca herda, e por que:
       *   evento_financeiro_id  indice unico evento<->transacao; um evento nao
       *                         vira dois
       *   banco_id              titulo que nasce pendente nao tem onde o dinheiro
       *                         caiu — quem diz isso e a baixa. A versao anterior
       *                         desta funcao herdava, e com isso arriscava 23514
       *                         em `transacao_baixa_parcial_coerente_trg`
       *   pagamento_multiplo_id nao existiria fatia em `pagamento_multiplo_rateio`
       *   adiantamento_id       grupo ja recusado; explicitar impede vazamento
       *   baixa_de_transacao_id a linha nova nao e baixa de nada
       *   valor_acrescimos      ajuste e da parcela especifica, e mora em tabela
       *   valor_descontos       propria; os gatilhos deixam valor_base = valor
       */
      INSERT INTO public.transacao (
        descricao, descricao_pagamento, valor, "valorLiquido", data,
        metodopagamento, categoria, categoria_id, plano_de_conta, plano_de_conta_id,
        centro_custo, centro_custo_id, tipo, cliente_id, fornecedor_id,
        nomepagador, cpfcnpjpagador, competencia_em, pendente, parcelamento_id,
        ordemservicoid, vendaid, entrada_id, usoconsumo_entrada_id, origem,
        created_by
      ) VALUES (
        v_template.descricao, v_template.descricao_pagamento, v_item.valor, v_item.valor,
        v_item.data, v_template.metodopagamento, v_template.categoria,
        v_template.categoria_id, v_template.plano_de_conta, v_template.plano_de_conta_id,
        v_template.centro_custo, v_template.centro_custo_id, v_template.tipo,
        v_template.cliente_id, v_template.fornecedor_id,
        v_template.nomepagador, v_template.cpfcnpjpagador, v_template.competencia_em,
        true, v_template.parcelamento_id,
        v_template.ordemservicoid, v_template.vendaid,
        v_template.entrada_id, v_template.usoconsumo_entrada_id, v_template.origem,
        coalesce(p_alterado_por, v_template.created_by)
      )
      RETURNING id INTO v_id;

      v_resultado := v_resultado || jsonb_build_object(
        'id', v_id, 'valor', v_item.valor, 'data', v_item.data);
    END LOOP;

    -- Devolve a dispensa. Ela morreria com a transacao de qualquer forma, mas
    -- qualquer escrita posterior no mesmo commit nao tem por que herda-la.
    PERFORM set_config('app.reparcelamento_em_curso', '', true);
  END IF;

  -------------------------------------------------------------------------
  -- 7) Renumeracao: o denominador da descricao
  -------------------------------------------------------------------------
  /*
   * O numero faz parte da descricao, e ir de 3x para 5x muda o denominador de
   * todas: deixar "1/3" ao lado de "4/5" seria mentira na tela e no extrato. As
   * baixadas entram tambem — o gatilho de valor nao se opoe, porque nada aqui
   * toca o valor de linha baixada.
   *
   * No grupo formal a familia e o grupo inteiro. No DOCUMENTO nao e: uma OS pode
   * ter uma entrada a vista mais um parcelamento, e renumerar as duas coisas
   * juntas inventaria uma parcela que a entrada nunca foi. Ali a familia sao as
   * linhas do documento que compartilham a mesma base de descricao.
   */
  IF v_grupo_tipo = 'PARCELAMENTO' THEN
    SELECT array_agg(id) INTO v_familia
      FROM public.transacao
     WHERE parcelamento_id = v_grupo_id AND is_deleted = false;
  ELSE
    SELECT array_agg(id) INTO v_familia
      FROM public.transacao
     WHERE is_deleted = false
       AND ((v_grupo_tipo = 'OS' AND ordemservicoid = v_grupo_id)
         OR (v_grupo_tipo = 'VENDA' AND vendaid = v_grupo_id))
       AND upper(tipo::text) = 'RECEITA'
       AND evento_financeiro_id IS NULL
       AND regexp_replace(descricao, ' - Parcela [0-9]+/[0-9]+$', '') = v_base;
  END IF;

  v_total := coalesce(array_length(v_familia, 1), 0);

  UPDATE public.transacao t
     SET descricao = v_base || ' - Parcela ' || ordenadas.posicao || '/' || v_total,
         updated_at = now()
    FROM (
      SELECT id, row_number() OVER (ORDER BY data, id) AS posicao
        FROM public.transacao
       WHERE id = ANY(v_familia)
    ) AS ordenadas
   WHERE t.id = ordenadas.id
     AND t.descricao IS DISTINCT FROM
         (v_base || ' - Parcela ' || ordenadas.posicao || '/' || v_total);

  -------------------------------------------------------------------------
  -- 8) Status do documento
  -------------------------------------------------------------------------
  /*
   * OS nao precisa: `trg_recalcular_status_financeiro_os` e AFTER INSERT OR
   * UPDATE OF (..., is_deleted, pendente, valor, ...) OR DELETE e ja disparou em
   * cada linha tocada acima.
   *
   * Venda nao tem gatilho equivalente — `recalcular_status_financeiro_venda` so
   * e chamada a mao, pelas funcoes de pagamento multiplo e de exclusao. Sem esta
   * linha, tirar ou acrescentar parcela deixaria o status da venda congelado no
   * que era antes.
   */
  IF v_grupo_tipo = 'VENDA' THEN
    PERFORM public.recalcular_status_financeiro_venda(v_grupo_id::int);
  END IF;

  RETURN jsonb_build_object(
    'modo', v_modo,
    'grupoTipo', v_grupo_tipo,
    'grupoId', v_grupo_id,
    'total', v_total,
    'parcelas', v_resultado
  );
END;
$_$;


--
-- Name: reparcelar_transacao_avulsa(bigint, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reparcelar_transacao_avulsa(p_parcelamento_id bigint, p_parcelas jsonb, p_alterado_por uuid DEFAULT NULL::uuid, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
BEGIN
  -- A mensagem aqui e a de GRUPO, nao a de transacao: e o que a tela antiga e o
  -- teste SQL esperam quando o id nao existe.
  PERFORM 1 FROM public.transacao_parcelamento WHERE id = p_parcelamento_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Parcelamento nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  SELECT id INTO v_id
    FROM public.transacao
   WHERE parcelamento_id = p_parcelamento_id
     AND is_deleted = false
     AND pendente = true
   ORDER BY data, id
   LIMIT 1;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'Todas as parcelas deste parcelamento ja foram baixadas. Para corrigir, exclua e lance de novo.'
      USING ERRCODE = '22023';
  END IF;

  RETURN public.reparcelar_transacao(v_id, p_parcelas, p_alterado_por, p_motivo, NULL);
END;
$$;


--
-- Name: replicar_baixa_estoque_venda(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replicar_baixa_estoque_venda(p_venda_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
      BEGIN
        PERFORM public.estoque_definir_contexto('VENDA', p_venda_id::bigint, 'Venda #' || p_venda_id);
        PERFORM public.replicar_baixa_estoque_venda_interna(p_venda_id);
      END;
      $$;


--
-- Name: replicar_baixa_estoque_venda_interna(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replicar_baixa_estoque_venda_interna(p_venda_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
  q_baixada int;
  delta int;
begin
  -- Para cada item ATUAL da venda
  for r in
    select vp.produtoid, vp.quantidade
      from public.vendaproduto vp
     where vp.venda_id = p_venda_id
  loop
    select b.quantidade into q_baixada
      from public.vendaproduto_baixa b
     where b.venda_id = p_venda_id
       and b.produtoid = r.produtoid;

    if q_baixada is null then
      delta := r.quantidade;
    else
      delta := r.quantidade - q_baixada;
    end if;

    if delta > 0 then
      update public.produto
         set estoque = estoque - delta
       where id = r.produtoid
         and estoque >= delta;

      if not found then
        raise exception 'Estoque insuficiente para o produto % (necessário: %, venda %)', r.produtoid, delta, p_venda_id
          using errcode = 'P0001';
      end if;

    elsif delta < 0 then
      update public.produto
         set estoque = estoque + (-delta)
       where id = r.produtoid;
    end if;

    insert into public.vendaproduto_baixa (venda_id, produtoid, quantidade, updated_at)
    values (p_venda_id, r.produtoid, r.quantidade, now())
    on conflict (venda_id, produtoid) do update
      set quantidade = excluded.quantidade,
          updated_at = now();
  end loop;

  -- Itens removidos da venda: estorna e apaga controle
  for r in
    select b.produtoid, b.quantidade
      from public.vendaproduto_baixa b
     where b.venda_id = p_venda_id
       and not exists (
         select 1
           from public.vendaproduto vp
          where vp.venda_id = p_venda_id
            and vp.produtoid = b.produtoid
       )
  loop
    update public.produto
       set estoque = estoque + r.quantidade
     where id = r.produtoid;

    delete from public.vendaproduto_baixa
     where venda_id = p_venda_id
       and produtoid = r.produtoid;
  end loop;
end;
$$;


--
-- Name: responder_aprovacao_os(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.responder_aprovacao_os(p_token uuid, p_documento text, p_acao text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_token public.osaprovacao%ROWTYPE;
  v_os public.ordemservico%ROWTYPE;
  v_documento_cliente text;
  v_documento text := public.fiscal_cnpj_normalizar(p_documento);
  v_acao text := upper(btrim(coalesce(p_acao, '')));
  v_resultado public.enum_status_aprovacao;
  v_novo_status public.enum_status_os;
BEGIN
  IF v_acao NOT IN ('APROVAR', 'REPROVAR') THEN
    RAISE EXCEPTION 'Acao de aprovacao invalida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_token
    FROM public.osaprovacao
   WHERE token = p_token
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Link de aprovacao invalido.' USING ERRCODE = 'P0002';
  END IF;
  IF v_token.usado_em IS NOT NULL
     OR (v_token.expira_em IS NOT NULL AND v_token.expira_em <= now()) THEN
    RAISE EXCEPTION 'Este link nao esta mais disponivel para resposta.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_os
    FROM public.ordemservico
   WHERE id = v_token.ordemservicoid
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ordem de servico nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_os.status::text <> 'APROVACAO_ORCAMENTO'
     OR v_os.statusaprovacao::text IS DISTINCT FROM 'PENDENTE' THEN
    RAISE EXCEPTION 'Este orcamento nao esta aguardando aprovacao.' USING ERRCODE = '22023';
  END IF;

  SELECT public.fiscal_cnpj_normalizar(c.cpfcnpj)
    INTO v_documento_cliente
    FROM public.cliente c
   WHERE c.id = v_os.clienteid;
  IF coalesce(v_documento, '') = '' OR v_documento IS DISTINCT FROM v_documento_cliente THEN
    RAISE EXCEPTION 'Documento nao confere para este orcamento.' USING ERRCODE = '22023';
  END IF;

  v_resultado := CASE
    WHEN v_acao = 'APROVAR' THEN 'APROVADA'::public.enum_status_aprovacao
    ELSE 'REPROVADA'::public.enum_status_aprovacao
  END;
  v_novo_status := CASE
    WHEN v_acao = 'APROVAR' THEN 'ORCAMENTO_APROVADO'::public.enum_status_os
    ELSE 'ORCAMENTO_RECUSADO'::public.enum_status_os
  END;

  UPDATE public.osaprovacao
     SET usado_em = now(),
         origem = 'LINK',
         resultado = v_resultado::text,
         aprovador_doc = v_documento,
         aprovador_usuario_id = NULL
   WHERE id = v_token.id
     AND usado_em IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Este link ja foi respondido.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.ordemservico
     SET status = v_novo_status,
         statusaprovacao = v_resultado,
         updatedat = now()
   WHERE id = v_os.id;

  RETURN jsonb_build_object(
    'ordemservicoid', v_os.id,
    'status', v_novo_status::text,
    'statusaprovacao', v_resultado::text
  );
END;
$$;


--
-- Name: responder_aprovacao_venda(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.responder_aprovacao_venda(p_token uuid, p_documento text, p_acao text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_token public.vendaaprovacao%ROWTYPE;
  v_venda public.venda%ROWTYPE;
  v_documento_cliente text;
  v_documento text := public.fiscal_cnpj_normalizar(p_documento);
  v_acao text := upper(btrim(coalesce(p_acao, '')));
  v_resultado public.enum_status_aprovacao;
  v_novo_status public.enum_status_venda;
BEGIN
  IF v_acao NOT IN ('APROVAR', 'REPROVAR') THEN
    RAISE EXCEPTION 'Acao de aprovacao invalida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_token
    FROM public.vendaaprovacao
   WHERE token = p_token
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Link de aprovacao invalido.' USING ERRCODE = 'P0002';
  END IF;
  IF v_token.usado_em IS NOT NULL OR v_token.invalidado_em IS NOT NULL OR v_token.expira_em <= now() THEN
    RAISE EXCEPTION 'Este link nao esta mais disponivel para resposta.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_venda
    FROM public.venda
   WHERE id = v_token.vendaid
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_venda.status::text <> 'APROVACAO_ORCAMENTO'
     OR v_venda.statusaprovacao::text IS DISTINCT FROM 'PENDENTE' THEN
    RAISE EXCEPTION 'Este orcamento nao esta aguardando aprovacao.' USING ERRCODE = '22023';
  END IF;

  SELECT public.fiscal_cnpj_normalizar(c.cpfcnpj)
    INTO v_documento_cliente
    FROM public.cliente c
   WHERE c.id = v_venda.clienteid;
  IF coalesce(v_documento, '') = '' OR v_documento IS DISTINCT FROM v_documento_cliente THEN
    RAISE EXCEPTION 'Documento nao confere para este orcamento.' USING ERRCODE = '22023';
  END IF;

  v_resultado := CASE WHEN v_acao = 'APROVAR' THEN 'APROVADA' ELSE 'REPROVADA' END;
  v_novo_status := CASE
    WHEN v_acao = 'APROVAR' THEN 'ORCAMENTO_APROVADO'::public.enum_status_venda
    ELSE 'ORCAMENTO_RECUSADO'::public.enum_status_venda
  END;

  UPDATE public.vendaaprovacao
     SET usado_em = now(),
         origem = 'LINK',
         resultado = v_resultado,
         aprovador_doc = v_documento
   WHERE id = v_token.id
     AND usado_em IS NULL
     AND invalidado_em IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Este link ja foi respondido.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.venda
     SET status = v_novo_status,
         statusaprovacao = v_resultado,
         updatedat = now()
   WHERE id = v_venda.id;

  RETURN jsonb_build_object(
    'vendaId', v_venda.id,
    'status', v_novo_status::text,
    'statusaprovacao', v_resultado
  );
END;
$$;


--
-- Name: resumo_financeiro_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resumo_financeiro_os(p_ordemservicoid integer) RETURNS TABLE(total_devido numeric, valor_recebido numeric, valor_pendente numeric, valor_comprometido numeric, saldo_a_receber numeric, saldo_disponivel_lancamento numeric, quantidade_transacoes bigint, quitada boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH dados_os AS (
    SELECT round(
      greatest(coalesce(o.orcamentototal, 0), 0) +
      CASE
        WHEN o.acrescimo_financeiro_tipo = 'PORCENTAGEM' THEN
          greatest(coalesce(o.orcamentototal, 0), 0) *
          least(greatest(coalesce(o.acrescimo_financeiro_valor, 0), 0), 100) / 100
        WHEN o.acrescimo_financeiro_tipo = 'FIXO' THEN
          greatest(coalesce(o.acrescimo_financeiro_valor, 0), 0)
        ELSE 0
      END,
      2
    )::numeric(14,2) AS total
    FROM public.ordemservico o
    WHERE o.id = p_ordemservicoid
      AND coalesce(o.is_deleted, false) = false
  ),
  pagamentos AS (
    SELECT
      coalesce(round(sum(r.valor) FILTER (WHERE r.pendente = false), 2), 0)::numeric(14,2) AS recebido,
      coalesce(round(sum(r.valor) FILTER (WHERE r.pendente = true), 2), 0)::numeric(14,2) AS pendente,
      count(DISTINCT r.transacao_id)::bigint AS quantidade
    FROM public.recebimento_por_documento r
    WHERE r.tipo_documento = 'OS'
      AND r.documento_id = p_ordemservicoid
  )
  SELECT
    d.total,
    p.recebido,
    p.pendente,
    round(p.recebido + p.pendente, 2)::numeric(14,2),
    greatest(round(d.total - p.recebido, 2), 0)::numeric(14,2),
    greatest(round(d.total - p.recebido - p.pendente, 2), 0)::numeric(14,2),
    p.quantidade,
    (d.total > 0 AND round(p.recebido + p.pendente, 2) >= d.total)
  FROM dados_os d
  CROSS JOIN pagamentos p;
$$;


--
-- Name: reverter_venda_para_orcamento(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverter_venda_para_orcamento(p_venda_id bigint, p_usuario_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda public.venda%ROWTYPE;
  v_produtos_devolvidos integer := 0;
  v_transacoes_excluidas integer := 0;
  v_valor_concluido numeric := 0;
BEGIN
  SELECT * INTO v_venda FROM public.venda WHERE id = p_venda_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF upper(v_venda.status::text) <> 'PAGAMENTO' THEN
    RAISE EXCEPTION 'Somente vendas em PAGAMENTO podem voltar para orçamento (esta está %).', v_venda.status
      USING ERRCODE = '22023';
  END IF;

  -- Mesma trava do cancelamento: nota emitida amarra a venda ao numero fiscal.
  IF EXISTS (
    SELECT 1 FROM public.nfe
    WHERE vendaid = p_venda_id AND status::text NOT IN ('RASCUNHO', 'CANCELADA', 'REJEITADA')
  ) THEN
    RAISE EXCEPTION 'Cancele a NF-e autorizada ou em processamento antes de voltar a venda para orçamento.'
      USING ERRCODE = '23514';
  END IF;

  SELECT count(*)::integer INTO v_produtos_devolvidos
  FROM public.vendaproduto_baixa WHERE venda_id = p_venda_id;
  PERFORM public.fn_estornar_estoque_venda(p_venda_id::integer);

  SELECT count(*)::integer, coalesce(sum(valor) FILTER (WHERE NOT pendente), 0)
    INTO v_transacoes_excluidas, v_valor_concluido
  FROM public.transacao
  WHERE vendaid = p_venda_id AND NOT is_deleted;

  UPDATE public.transacao
  SET pendente = false, is_deleted = true, deleted_at = now(), deleted_by = p_usuario_id,
      updated_at = now(), updated_by = p_usuario_id
  WHERE vendaid = p_venda_id AND NOT is_deleted;

  -- forma_pagamento volta a ser nula porque ela e escolhida na aprovacao: manter
  -- a antiga faria o orcamento exibir um pagamento que ninguem combinou ainda.
  UPDATE public.venda
  SET status = 'ORCAMENTO', forma_pagamento = NULL,
      updated_by = coalesce(p_usuario_id, updated_by), updatedat = now()
  WHERE id = p_venda_id;

  RETURN jsonb_build_object(
    'vendaId', p_venda_id,
    'status', 'ORCAMENTO',
    'produtosDevolvidos', v_produtos_devolvidos,
    'transacoesExcluidas', v_transacoes_excluidas,
    'valorConcluidoRemovido', v_valor_concluido
  );
END;
$$;


--
-- Name: revogar_convite_assinatura_checklist(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revogar_convite_assinatura_checklist(p_documento_public_id uuid, p_revogado_por uuid, p_request_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  doc_id bigint;
  convite_id bigint;
begin
  select id into doc_id
  from public.checklist_documento
  where public_id = p_documento_public_id;
  if not found then
    raise exception 'Versao do checklist nao encontrada.' using errcode = 'P0002';
  end if;

  select id into convite_id
  from public.checklist_documento_convite_assinatura
  where documento_id = doc_id
    and revogado_em is null
    and consumido_em is null
  order by criado_em desc, id desc
  limit 1
  for update;

  if convite_id is null then return false; end if;

  update public.checklist_documento_convite_assinatura
     set revogado_em = now(),
         revogado_por = p_revogado_por,
         motivo_revogacao = 'MANUAL'
   where id = convite_id;

  insert into public.checklist_documento_evento (
    documento_id, tipo, usuario_id, request_ip, user_agent, metadados
  ) values (
    doc_id,
    'CONVITE_ASSINATURA_REVOGADO',
    p_revogado_por,
    case when p_request_ip is null then null else p_request_ip::inet end,
    left(p_user_agent, 1000),
    jsonb_build_object('conviteId', convite_id, 'motivo', 'MANUAL')
  );
  return true;
end;
$$;


--
-- Name: salvar_contexto_fiscal_saida(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_contexto_fiscal_saida(p_contexto jsonb, p_itens jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saida_id bigint := nullif(p_contexto->>'saida_id', '')::bigint;
  v_item jsonb;
BEGIN
  IF v_saida_id IS NULL OR jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Contexto fiscal ou itens da saída inválidos.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.estoque_saida_fiscal (
    saida_id, operacao_fiscal_codigo, natureza_operacao, finalidade,
    documento_referenciado_obrigatorio, entrada_origem_id,
    chave_acesso_referenciada, destinatario_snapshot, observacoes_fiscais,
    created_by, updated_by, updated_at
  ) VALUES (
    v_saida_id,
    p_contexto->>'operacao_fiscal_codigo',
    p_contexto->>'natureza_operacao',
    p_contexto->>'finalidade',
    coalesce((p_contexto->>'documento_referenciado_obrigatorio')::boolean, false),
    nullif(p_contexto->>'entrada_origem_id', '')::bigint,
    nullif(p_contexto->>'chave_acesso_referenciada', ''),
    p_contexto->'destinatario_snapshot',
    nullif(btrim(coalesce(p_contexto->>'observacoes_fiscais', '')), ''),
    nullif(p_contexto->>'user_id', '')::uuid,
    nullif(p_contexto->>'user_id', '')::uuid,
    now()
  )
  ON CONFLICT (saida_id) DO UPDATE SET
    operacao_fiscal_codigo = EXCLUDED.operacao_fiscal_codigo,
    natureza_operacao = EXCLUDED.natureza_operacao,
    finalidade = EXCLUDED.finalidade,
    documento_referenciado_obrigatorio = EXCLUDED.documento_referenciado_obrigatorio,
    entrada_origem_id = EXCLUDED.entrada_origem_id,
    chave_acesso_referenciada = EXCLUDED.chave_acesso_referenciada,
    destinatario_snapshot = EXCLUDED.destinatario_snapshot,
    observacoes_fiscais = EXCLUDED.observacoes_fiscais,
    updated_by = EXCLUDED.updated_by,
    updated_at = now();

  DELETE FROM public.estoque_saida_item_fiscal WHERE saida_id = v_saida_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    INSERT INTO public.estoque_saida_item_fiscal (
      saida_id, saida_item_id, entrada_item_origem_id,
      numero_item_referenciado, percentual_devolucao,
      valor_ipi_devolvido, updated_at
    ) VALUES (
      v_saida_id,
      (v_item->>'saida_item_id')::bigint,
      nullif(v_item->>'entrada_item_origem_id', '')::bigint,
      nullif(v_item->>'numero_item_referenciado', '')::integer,
      nullif(v_item->>'percentual_devolucao', '')::numeric,
      coalesce(nullif(v_item->>'valor_ipi_devolvido', '')::numeric, 0),
      now()
    );
  END LOOP;

  RETURN jsonb_build_object('saida_id', v_saida_id);
END;
$$;


--
-- Name: os_termo_impressao; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.os_termo_impressao (
    id integer NOT NULL,
    titulo text NOT NULL,
    intro text DEFAULT ''::text NOT NULL,
    itens jsonb DEFAULT '[]'::jsonb NOT NULL,
    status public.enum_status_os[] DEFAULT '{}'::public.enum_status_os[] NOT NULL,
    alvos text[] DEFAULT '{}'::text[] NOT NULL,
    ordem integer DEFAULT 0 NOT NULL,
    createdat timestamp with time zone DEFAULT now() NOT NULL,
    updatedat timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT os_termo_impressao_alvos_chk CHECK ((alvos <@ ARRAY['VEICULO'::text, 'PECA'::text, 'EQUIPAMENTO'::text])),
    CONSTRAINT os_termo_impressao_itens_chk CHECK ((jsonb_typeof(itens) = 'array'::text)),
    CONSTRAINT os_termo_impressao_ordem_chk CHECK ((ordem >= 0)),
    CONSTRAINT os_termo_impressao_titulo_chk CHECK ((btrim(titulo) <> ''::text))
);


--
-- Name: TABLE os_termo_impressao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.os_termo_impressao IS 'Blocos de dizeres impressos no rodapé da OS. Vazia = a OS imprime sem termo de aceite.';


--
-- Name: COLUMN os_termo_impressao.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.os_termo_impressao.status IS 'Status da OS em que o bloco imprime. Vazio nunca casa — é o jeito de guardar um texto desligado.';


--
-- Name: COLUMN os_termo_impressao.alvos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.os_termo_impressao.alvos IS 'Alvos em que o bloco imprime: VEICULO, PECA ou EQUIPAMENTO.';


--
-- Name: salvar_os_termos_impressao(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.salvar_os_termos_impressao(p_termos jsonb) RETURNS SETOF public.os_termo_impressao
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_termos IS NULL OR jsonb_typeof(p_termos) <> 'array' THEN
    RAISE EXCEPTION 'Os dizeres devem vir como uma lista.' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.os_termo_impressao WHERE true;

  RETURN QUERY
  WITH inseridos AS (
    INSERT INTO public.os_termo_impressao (titulo, intro, itens, status, alvos, ordem)
    SELECT
      btrim(termo->>'titulo'),
      coalesce(btrim(termo->>'intro'), ''),
      CASE WHEN jsonb_typeof(termo->'itens') = 'array' THEN termo->'itens' ELSE '[]'::jsonb END,
      ARRAY(SELECT jsonb_array_elements_text(termo->'status'))::public.enum_status_os[],
      ARRAY(SELECT jsonb_array_elements_text(termo->'alvos')),
      (posicao - 1) * 10
    FROM jsonb_array_elements(p_termos) WITH ORDINALITY AS entrada(termo, posicao)
    RETURNING *
  )
  SELECT * FROM inseridos ORDER BY ordem, id;
END;
$$;


--
-- Name: separar_conclusao_financeira_da_saida_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.separar_conclusao_financeira_da_saida_os() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.status::text = 'CONCLUIDO'
     and old.status::text is distinct from 'CONCLUIDO' then
    new.pagamento_concluido_em := coalesce(new.pagamento_concluido_em, new.datasaida, now());
  end if;
  if old.status::text = 'CONCLUIDO' and new.status::text IN ('PAGAMENTO', 'FATURAMENTO') then
    new.pagamento_concluido_em := null;
  end if;

  if new.datasaida is distinct from old.datasaida
     and not exists (
       select 1 from public.os_saida s where s.ordemservico_id = old.id
     ) then
    new.datasaida := old.datasaida;
  end if;
  return new;
end;
$$;


