  ELSE
    PERFORM public.cancelar_eventos_dre_entrada('USOCONSUMO_ENTRADA', NEW.id);
  END IF;
  RETURN NEW;
END $$;


--
-- Name: tg_carimbar_competencia_evento_novo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_carimbar_competencia_evento_novo() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.competencia_em is null and new.ordemservicoid is not null then
    select o.execucao_fim_em
      into new.competencia_em
      from public.ordemservico o
     where o.id = new.ordemservicoid;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION tg_carimbar_competencia_evento_novo(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_carimbar_competencia_evento_novo() IS 'Carimba a competencia de evento de OS criado depois do fim da execucao. Sem isso o evento fica fora da DRE, que filtra competencia_em not null.';


--
-- Name: tg_carimbar_competencia_eventos_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_carimbar_competencia_eventos_os() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.execucao_fim_em is distinct from old.execucao_fim_em then
    update public.eventos_financeiros
       set competencia_em = new.execucao_fim_em,
           updated_at = now()
     where ordemservicoid = new.id
       and status <> 'CANCELADO'
       and competencia_em is distinct from new.execucao_fim_em;
  end if;

  return new;
end;
$$;


