-- Name: tg_cliente_saldo_movimento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_cliente_saldo_movimento() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.recalcular_saldo_credito_cliente(new.cliente_id);
  RETURN new;
END;
$$;


--
-- Name: tg_cliente_saldo_movimento_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_cliente_saldo_movimento_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_manual boolean := old.origem = 'MANUAL' AND old.acao = 'REGISTRO';
BEGIN
  IF coalesce(current_setting('app.razao_credito_reescrita', true), '') <> 'on' THEN
    RAISE EXCEPTION 'O razao do credito do cliente so muda pela aba de credito do cliente.'
      USING ERRCODE = '42501';
  END IF;

  IF tg_op = 'DELETE' THEN
    IF NOT v_manual THEN
      RAISE EXCEPTION 'So o lancamento manual de credito pode ser excluido.'
        USING ERRCODE = '42501';
    END IF;
    RETURN old;
  END IF;

  IF v_manual THEN
    IF (new.cliente_id, new.origem, new.acao, new.transacao_id, new.created_by, new.created_at)
       IS DISTINCT FROM
       (old.cliente_id, old.origem, old.acao, old.transacao_id, old.created_by, old.created_at) THEN
      RAISE EXCEPTION 'Na edicao do lancamento manual so mudam sentido, valor e motivo.'
        USING ERRCODE = '42501';
    END IF;
    RETURN new;
  END IF;

  IF (to_jsonb(new) - 'saldo_anterior' - 'saldo_resultante')
     IS DISTINCT FROM
     (to_jsonb(old) - 'saldo_anterior' - 'saldo_resultante') THEN
    RAISE EXCEPTION 'O lancamento gerado por transacao e imutavel: estorne a baixa no financeiro.'
      USING ERRCODE = '42501';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: tg_confirmar_transacao_evento_financeiro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_confirmar_transacao_evento_financeiro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.evento_financeiro_id is not null then
    update public.eventos_financeiros
       set status = 'CONVERTIDO', transacaoid = new.id, updated_at = now()
     where id = new.evento_financeiro_id;
  end if;
  return new;
end;
$$;


--
-- Name: tg_congelar_comissao_ao_encerrar_execucao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_congelar_comissao_ao_encerrar_execucao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF new.execucao_fim_em IS NOT NULL AND old.execucao_fim_em IS NULL THEN
    PERFORM public.recarimbar_comissao_osservico(new.id, NULL);
    PERFORM public.recalcular_comissao_osservico(new.id, s.servicoid)
      FROM public.osservico s WHERE s.ordemservicoid = new.id;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION tg_congelar_comissao_ao_encerrar_execucao(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_congelar_comissao_ao_encerrar_execucao() IS 'No instante em que a execucao encerra, traz a taxa do cadastro uma ultima vez e recalcula. Dali em diante o carimbo nao muda mais sozinho.';


--
-- Name: tg_congelar_comissao_criacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_congelar_comissao_criacao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF new.execucao_fim_em IS NOT NULL AND old.execucao_fim_em IS NULL THEN
    PERFORM public.recarimbar_comissao_criacao_os(new.id);
    PERFORM public.recalcular_comissao_criacao_os(new.id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: tg_dre_implantacao_exige_congelamento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_dre_implantacao_exige_congelamento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_faltando bigint;
BEGIN
  IF new.estado <> 'ATIVO' THEN
    RETURN new;
  END IF;

  SELECT count(*) INTO v_faltando
    FROM public.eventos_financeiros e
   WHERE e.status IN ('ATIVO', 'CONVERTIDO')
     AND e.competencia_em IS NOT NULL
     AND e.competencia_em >= new.vigencia_inicio
     AND NOT EXISTS (
       SELECT 1 FROM public.eventos_financeiros_classificacao ec
        WHERE ec.evento_id = e.id AND ec.vigente);

  IF v_faltando > 0 THEN
    RAISE EXCEPTION
      'Ativacao recusada: % evento(s) a partir de % ainda nao tem classificacao vigente. Rode dre_congelar_classificacao_legado ate zerar.',
      v_faltando, new.vigencia_inicio
      USING ERRCODE = '23514';
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_espelhar_comissao_ajustada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_espelhar_comissao_ajustada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_servicoid integer;
BEGIN
  IF new.chave_origem LIKE 'CRIACAO:%' THEN
    IF new.status = 'CANCELADO' THEN
      UPDATE public.os_comissao_criacao c
         SET valor_comissao_manual = NULL, updated_at = now()
       WHERE c.ordemservicoid = new.ordemservicoid
         AND 'CRIACAO:' || c.usuarioid || ':'
             || CASE c.tipo WHEN 'SERVICO' THEN 'S' WHEN 'PRODUTO' THEN 'P' ELSE 'A' END
             || c.item_id = new.chave_origem
         AND c.valor_comissao_manual IS NOT NULL;
      IF FOUND THEN
        PERFORM public.recalcular_comissao_criacao_os(new.ordemservicoid);
      END IF;
    ELSE
      UPDATE public.os_comissao_criacao c
         SET valor_comissao_manual = new.valor,
             valor_comissao = new.valor,
             updated_at = now()
       WHERE c.ordemservicoid = new.ordemservicoid
         AND 'CRIACAO:' || c.usuarioid || ':'
             || CASE c.tipo WHEN 'SERVICO' THEN 'S' WHEN 'PRODUTO' THEN 'P' ELSE 'A' END
             || c.item_id = new.chave_origem
         AND (c.valor_comissao_manual IS DISTINCT FROM new.valor
              OR c.valor_comissao IS DISTINCT FROM new.valor);
    END IF;
    RETURN NULL;
  END IF;

  IF new.status = 'CANCELADO' THEN
    UPDATE public.osservico_realizador r
       SET valor_comissao_manual = NULL, updated_at = now()
     WHERE r.ordemservicoid = new.ordemservicoid
       AND r.servicoid || ':' || r.usuarioid = new.chave_origem
       AND r.valor_comissao_manual IS NOT NULL
    RETURNING r.servicoid INTO v_servicoid;
    IF v_servicoid IS NOT NULL THEN
      PERFORM public.recalcular_comissao_osservico(new.ordemservicoid, v_servicoid);
    END IF;
  ELSE
    UPDATE public.osservico_realizador r
       SET valor_comissao_manual = new.valor,
           valor_comissao = new.valor,
           updated_at = now()
     WHERE r.ordemservicoid = new.ordemservicoid
       AND r.servicoid || ':' || r.usuarioid = new.chave_origem
       AND (r.valor_comissao_manual IS DISTINCT FROM new.valor
            OR r.valor_comissao IS DISTINCT FROM new.valor);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION tg_espelhar_comissao_ajustada(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_espelhar_comissao_ajustada() IS 'Copia o valor de um evento COMISSAO ajustado a mao (is_manual) para o vinculo de origem (osservico_realizador ou os_comissao_criacao), onde relatorios e Central Pessoal leem. Evento cancelado devolve o vinculo ao calculo.';


--
-- Name: tg_espelhar_comissao_ajustada_venda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_espelhar_comissao_ajustada_venda() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.venda_comissao SET valor_comissao_manual = new.valor,
    valor_comissao = new.valor, updated_at = now()
    WHERE vendaid = new.source_id AND integrada AND usuarioid IS NOT DISTINCT FROM new.usuarioid;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A comissao nao possui apuracao integrada para este beneficiario.' USING ERRCODE = 'P0001';
  END IF;
  RETURN new;
END;
$$;


