    LANGUAGE plpgsql
    AS $$
begin
  perform public.sincronizar_eventos_financeiros_transacao(new.id);
  return new;
end;
$$;


--
-- Name: tg_eventos_financeiros_transacao_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_eventos_financeiros_transacao_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Encerra, nao apaga: o livro guarda o que existiu. CONVERTIDO fica de fora
  -- pela mesma razao de sempre — virou transacao e cabe ao financeiro estornar.
  update public.eventos_financeiros
     set status = 'CANCELADO', updated_at = now()
   where source_type = 'TRANSACAO'
     and source_id = old.id
     and status = 'ATIVO';

  return old;
end;
$$;


--
-- Name: tg_eventos_financeiros_venda(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_eventos_financeiros_venda() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'INSERT' then
    if public.venda_reconhece_receita(new.status::text) then
      perform public.sincronizar_eventos_financeiros_venda(new.id);
    end if;
    return new;
  end if;

  if new.status is distinct from old.status
     or new.valortotal is distinct from old.valortotal
     or new.desconto_valor is distinct from old.desconto_valor
     or new.valor_frete is distinct from old.valor_frete
     or new.datavenda is distinct from old.datavenda then
    perform public.sincronizar_eventos_financeiros_venda(new.id);
  end if;

  return new;
end;
$$;


--
-- Name: tg_eventos_financeiros_venda_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_eventos_financeiros_venda_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.eventos_financeiros
     set status = 'CANCELADO', updated_at = now()
   where source_type = 'VENDA'
     and source_id = old.id
     and status = 'ATIVO';

  return old;
end;
$$;


--
-- Name: tg_eventos_financeiros_vendaproduto(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_eventos_financeiros_vendaproduto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  perform public.sincronizar_eventos_financeiros_venda(coalesce(new.venda_id, old.venda_id));
  return coalesce(new, old);
end;
$$;


--
-- Name: tg_excluir_transacoes_financeiras_os_por_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_excluir_transacoes_financeiras_os_por_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_grupos text;
BEGIN
  IF new.status::text IS NOT DISTINCT FROM old.status::text
     OR new.status::text NOT IN ('ORCAMENTO', 'CANCELADO', 'SEM_COBRANCA') THEN
    RETURN new;
  END IF;

  SELECT string_agg(DISTINCT '#' || g.pagamento_multiplo_id || ' (com ' || g.outros || ')', '; ')
    INTO v_grupos
    FROM (
      SELECT r.pagamento_multiplo_id,
             (SELECT string_agg(DISTINCT o.tipo_documento || ' #' || o.documento_id, ', ')
                FROM public.pagamento_multiplo_rateio o
               WHERE o.pagamento_multiplo_id = r.pagamento_multiplo_id
                 AND NOT (o.tipo_documento = 'OS' AND o.documento_id = new.id)) AS outros
        FROM public.pagamento_multiplo_rateio r
        JOIN public.transacao t ON t.id = r.transacao_id AND t.is_deleted = false
       WHERE r.tipo_documento = 'OS' AND r.documento_id = new.id
    ) g;

  IF v_grupos IS NOT NULL THEN
    RAISE EXCEPTION
      'Esta OS foi paga em pagamento múltiplo %. Exclua o pagamento pelo financeiro antes de reverter o status.',
      v_grupos USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.transacao t
   WHERE t.ordemservicoid = new.id
     AND upper(t.tipo::text) = 'RECEITA'
     AND t.evento_financeiro_id IS NULL
     AND t.is_deleted = false;

  RETURN new;
END;
$$;


--
-- Name: tg_gerar_eventos_financeiros_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_gerar_eventos_financeiros_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'ORCAMENTO_APROVADO' and old.status is distinct from new.status then
    perform public.sincronizar_eventos_financeiros_os(new.id, false);
  elsif new.status = 'EM_ANDAMENTO' and old.status is distinct from new.status then
    if exists (
      select 1 from public.osservico s
      where s.ordemservicoid = new.id
        and not exists (select 1 from public.osservico_realizador r
                        where r.ordemservicoid = s.ordemservicoid and r.servicoid = s.servicoid)
    ) then
      raise exception 'Defina os realizadores de todos os servicos antes de iniciar a OS.';
    end if;
    perform public.sincronizar_eventos_financeiros_os(new.id, true);
  end if;
  return new;
end;
$$;


--
-- Name: tg_invalidar_aprovacao_venda_alterada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_invalidar_aprovacao_venda_alterada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_venda_id integer;
  v_invalidacoes integer := 0;
  v_status text;
  v_eh_troca_status boolean := TG_NAME = 'trg_venda_status_invalidar_aprovacao';
  v_status_mudou_na_edicao boolean := false;
BEGIN
  IF TG_NAME = 'trg_venda_invalidar_aprovacao_alterada' THEN
    v_status_mudou_na_edicao :=
      (to_jsonb(OLD)->>'status') IS DISTINCT FROM (to_jsonb(NEW)->>'status');
  END IF;

  IF TG_TABLE_NAME = 'venda' THEN
    IF TG_OP = 'DELETE' THEN
      v_venda_id := OLD.id;
    ELSE
      v_venda_id := NEW.id;
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_venda_id := OLD.venda_id;
  ELSE
    v_venda_id := NEW.venda_id;
  END IF;

  v_invalidacoes := public.invalidar_aprovacoes_venda(v_venda_id, 'ORCAMENTO_ALTERADO');

  SELECT status::text INTO v_status FROM public.venda WHERE id = v_venda_id;

  IF v_invalidacoes > 0
     OR (
       NOT v_eh_troca_status
       AND NOT v_status_mudou_na_edicao
       AND v_status IN ('APROVACAO_ORCAMENTO', 'ORCAMENTO_APROVADO', 'ORCAMENTO_RECUSADO')
     ) THEN
    UPDATE public.venda
       SET status = CASE
             WHEN v_status IN ('APROVACAO_ORCAMENTO', 'ORCAMENTO_APROVADO', 'ORCAMENTO_RECUSADO')
               THEN 'ORCAMENTO'::public.enum_status_venda
             ELSE status
           END,
           statusaprovacao = NULL,
           updatedat = now()
     WHERE id = v_venda_id;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_recalc_comissao_criacao_os_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalc_comissao_criacao_os_total() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM public.recalcular_comissao_criacao_os(new.id);
  RETURN NULL;
END;
$$;


--
-- Name: tg_recalc_comissao_criacao_por_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalc_comissao_criacao_por_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.recalcular_comissao_criacao_os(old.ordemservicoid);
    RETURN NULL;
  END IF;

  PERFORM public.recalcular_comissao_criacao_os(new.ordemservicoid);

  -- Item movido de OS: a de origem tambem encolheu.
  IF TG_OP = 'UPDATE' AND old.ordemservicoid IS DISTINCT FROM new.ordemservicoid THEN
    PERFORM public.recalcular_comissao_criacao_os(old.ordemservicoid);
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: tg_recalc_comissao_os_total(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalc_comissao_os_total() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF new.orcamentototal IS DISTINCT FROM old.orcamentototal
     OR new.valor_frete IS DISTINCT FROM old.valor_frete THEN
    PERFORM public.recalcular_comissao_osservico(new.id, s.servicoid)
      FROM public.osservico s WHERE s.ordemservicoid = new.id;
  END IF;
  RETURN new;
END;
$$;


--
-- Name: tg_recalc_comissao_osservico_on_subtotal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalc_comissao_osservico_on_subtotal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin
  perform public.recalcular_comissao_osservico(new.ordemservicoid, new.servicoid);
  return new;
end;$$;


--
-- Name: tg_recalc_comissao_osservico_realizador(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalc_comissao_osservico_realizador() RETURNS trigger
    LANGUAGE plpgsql
    AS $$begin
  perform public.recalcular_comissao_osservico(
    coalesce(new.ordemservicoid, old.ordemservicoid),
    coalesce(new.servicoid, old.servicoid)
  );

  return coalesce(new, old);
end;$$;


--
-- Name: tg_recalc_comissao_realizadores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalc_comissao_realizadores() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_os integer;
  v_servico integer;
BEGIN
  IF tg_op = 'DELETE' THEN
    v_os := old.ordemservicoid;
    v_servico := old.servicoid;
  ELSE
    v_os := new.ordemservicoid;
    v_servico := new.servicoid;
  END IF;

  PERFORM public.recalcular_comissao_osservico(v_os, v_servico);
  RETURN NULL;
END;
$$;


--
-- Name: tg_recalcular_documento_do_rateio(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalcular_documento_do_rateio() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo text := CASE WHEN TG_OP = 'DELETE' THEN OLD.tipo_documento ELSE NEW.tipo_documento END;
  v_doc integer := CASE WHEN TG_OP = 'DELETE' THEN OLD.documento_id ELSE NEW.documento_id END;
BEGIN
  IF v_tipo = 'OS' THEN
    PERFORM public.recalcular_status_financeiro_os(v_doc);
  ELSE
    PERFORM public.recalcular_status_financeiro_venda(v_doc);
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_recalcular_status_financeiro_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_recalcular_status_financeiro_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old_os integer;
  v_new_os integer;
BEGIN
  IF TG_OP <> 'INSERT'
     AND OLD.ordemservicoid IS NOT NULL
     AND upper(OLD.tipo::text) = 'RECEITA'
     AND OLD.evento_financeiro_id IS NULL THEN
    v_old_os := OLD.ordemservicoid;
  END IF;

  IF TG_OP <> 'DELETE'
     AND NEW.ordemservicoid IS NOT NULL
     AND upper(NEW.tipo::text) = 'RECEITA'
     AND NEW.evento_financeiro_id IS NULL THEN
    v_new_os := NEW.ordemservicoid;
  END IF;

  IF v_old_os IS NOT NULL THEN
    PERFORM public.recalcular_status_financeiro_os(v_old_os);
  END IF;
  IF v_new_os IS NOT NULL AND v_new_os IS DISTINCT FROM v_old_os THEN
    PERFORM public.recalcular_status_financeiro_os(v_new_os);
  END IF;

  -- Transação de pagamento múltiplo não aponta para documento nenhum: quem sabe
  -- quais ela tocou é o rateio.
  IF TG_OP = 'DELETE' THEN
    IF OLD.pagamento_multiplo_id IS NOT NULL THEN
      PERFORM public.recalcular_documentos_da_transacao(OLD.id);
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.pagamento_multiplo_id IS NOT NULL THEN
    PERFORM public.recalcular_documentos_da_transacao(NEW.id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_reconciliar_eventos_ao_finalizar_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_reconciliar_eventos_ao_finalizar_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.status is not distinct from new.status then
    return new;
  end if;

  if old.status::text in ('PAGAMENTO', 'FATURAMENTO') and new.status::text in ('PAGAMENTO', 'FATURAMENTO') then
    return new;
  end if;

  if new.status::text = 'CANCELADO' then
    -- Cancelar a OS nao remove seus itens, entao reconciliar recriaria os
    -- eventos com valor cheio. O correto e encerra-los.
    update public.eventos_financeiros
       set status = 'CANCELADO', updated_at = now()
     where ordemservicoid = new.id
       and status = 'ATIVO';

  elsif new.status::text = 'SEM_COBRANCA' then
    -- Acerta custo pelo caminho normal...
    perform public.reconciliar_eventos_financeiros_os(new.id, true);
    -- ...e retira receita, deducao e comissao, que nao existem numa OS sem
    -- cobranca. Sobra o custo da peca, que foi consumida de verdade.
    update public.eventos_financeiros
       set status = 'CANCELADO', updated_at = now()
     where ordemservicoid = new.id
       and status = 'ATIVO'
       and (natureza = 'RECEITA' or origem = 'DESCONTO' or origem = 'COMISSAO');

  -- PAGAMENTO junto de CONCLUIDO: nos dois o trabalho terminou e
  -- `execucao_fim_em` ja foi carimbado. Deixar PAGAMENTO de fora fazia a OS
  -- entrar nos relatorios por conclusao sem nunca ter publicado a comissao.
  elsif new.status::text in ('CONCLUIDO', 'PAGAMENTO') then
    perform public.reconciliar_eventos_financeiros_os(new.id, true);
  end if;

  return new;
end;
$$;


--
-- Name: tg_regra_classificacao_sem_sobreposicao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_regra_classificacao_sem_sobreposicao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_conflito integer;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtext('plano_contas_classificacao_regra'),
    coalesce(new.grupo_id, -new.conta_id));

  SELECT r.id INTO v_conflito
    FROM public.plano_contas_classificacao_regra r
   WHERE r.id IS DISTINCT FROM new.id
     AND r.grupo_id IS NOT DISTINCT FROM new.grupo_id
     AND r.conta_id IS NOT DISTINCT FROM new.conta_id
     AND daterange(r.vigencia_inicio, r.vigencia_fim, '[)')
       && daterange(new.vigencia_inicio, new.vigencia_fim, '[)')
   LIMIT 1;

  IF v_conflito IS NOT NULL THEN
    RAISE EXCEPTION
      'Ja existe regra de classificacao vigente no periodo para esta entidade (regra %).', v_conflito
      USING ERRCODE = '23505';
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_restaurar_evento_apos_excluir_transacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_restaurar_evento_apos_excluir_transacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if old.evento_financeiro_id is not null then
    update public.eventos_financeiros
       set status = 'ATIVO', transacaoid = null, updated_at = now()
     where id = old.evento_financeiro_id;
  end if;
  return old;
end;
$$;


--
-- Name: tg_set_comissao_percent_aplicada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_set_comissao_percent_aplicada() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.comissao_percent_aplicada is null then
    if exists (
      select 1 from public.servico s
      where s.id = new.servicoid and s.gera_comissao is false
    ) then
      new.comissao_percent_aplicada := 0;
    else
      select coalesce(u.comissao_percent, 0)
        into new.comissao_percent_aplicada
      from public.usuario u
      where u.id = new.usuarioid;
    end if;
  end if;

  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: tg_transacao_ajuste_coerente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_ajuste_coerente() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_natureza text;
  v_ativo boolean;
  v_pendente boolean;
BEGIN
  SELECT natureza, ativo INTO v_natureza, v_ativo
    FROM public.tipos_ajuste_transacao WHERE id = new.tipo_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tipo de ajuste nao encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v_ativo IS NOT TRUE THEN
    RAISE EXCEPTION 'Tipo de ajuste inativo.' USING ERRCODE = '22023';
  END IF;
  IF new.natureza <> v_natureza THEN
    RAISE EXCEPTION 'A natureza informada nao confere com a do tipo escolhido.'
      USING ERRCODE = '22023';
  END IF;

  -- Acrescimo altera o bruto, e bruto de transacao baixada e imutavel (ver
  -- 20260806120000_travar_valor_apos_baixa). Recusar aqui da mensagem util em
  -- vez de deixar estourar a trava do `valor`, que falaria de outra coisa.
  -- Desconto mexe so no liquido e segue liberado: a taxa da maquineta costuma
  -- ser conhecida depois do pagamento.
  IF new.natureza = 'ACRESCIMO' THEN
    SELECT pendente INTO v_pendente FROM public.transacao WHERE id = new.transacao_id;
    IF coalesce(v_pendente, false) = false THEN
      RAISE EXCEPTION
        'Nao da para lancar acrescimo em transacao ja baixada, porque ele altera o valor bruto.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_ajuste_recalcular(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_ajuste_recalcular() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF tg_op = 'DELETE' THEN
    PERFORM public.recalcular_valores_transacao(old.transacao_id);
    RETURN old;
  END IF;

  PERFORM public.recalcular_valores_transacao(new.transacao_id);
  -- Mover a linha de uma transacao para outra tem que acertar as duas pontas.
  IF tg_op = 'UPDATE' AND old.transacao_id <> new.transacao_id THEN
    PERFORM public.recalcular_valores_transacao(old.transacao_id);
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_antecipado_sem_banco(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_antecipado_sem_banco() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new.adiantamento_id IS NULL OR new.banco_id IS NULL THEN
    RETURN new;
  END IF;

  RAISE EXCEPTION
    'O título #% é antecipado: o dinheiro dele entrou pela antecipação, e o que vier depois é lançado numa transação própria. Dar banco a ele somaria o mesmo valor duas vezes no fluxo de caixa.',
    new.id USING ERRCODE = '23514';
END;
$$;


--
-- Name: FUNCTION tg_transacao_antecipado_sem_banco(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_transacao_antecipado_sem_banco() IS 'Título antecipado nunca carrega banco: o dinheiro veio da antecipação, e o repasse posterior é lançado numa transação filha (baixa_de_transacao_id).';


--
-- Name: tg_transacao_baixa_parcial(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_baixa_parcial() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF old.baixa_de_transacao_id IS NOT NULL THEN
      PERFORM public.recalcular_baixas_transacao(old.baixa_de_transacao_id);
    END IF;
    RETURN old;
  END IF;

  IF new.baixa_de_transacao_id IS NOT NULL THEN
    PERFORM public.recalcular_baixas_transacao(new.baixa_de_transacao_id);
  END IF;

  -- Mover ou apagar logicamente uma filha tem que acertar as duas pontas.
  IF TG_OP = 'UPDATE'
     AND old.baixa_de_transacao_id IS NOT NULL
     AND old.baixa_de_transacao_id IS DISTINCT FROM new.baixa_de_transacao_id THEN
    PERFORM public.recalcular_baixas_transacao(old.baixa_de_transacao_id);
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_baixa_parcial_coerente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_baixa_parcial_coerente() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new.baixa_de_transacao_id IS NOT NULL THEN
    IF new.banco_id IS NULL THEN
      RAISE EXCEPTION
        'A baixa parcial do título #% precisa de banco: ela é o dinheiro que se moveu.',
        new.baixa_de_transacao_id USING ERRCODE = '22023';
    END IF;
    IF coalesce(new.pendente, false) THEN
      RAISE EXCEPTION
        'A baixa parcial do título #% nasce liquidada: ela registra pagamento que já aconteceu.',
        new.baixa_de_transacao_id USING ERRCODE = '22023';
    END IF;
    IF new.baixa_de_transacao_id = new.id THEN
      RAISE EXCEPTION 'Uma transação não pode ser baixa de si mesma.' USING ERRCODE = '22023';
    END IF;

    -- LIQUIDADO e com banco: o dinheiro está no próprio título, e uma baixa
    -- parcial em cima dele contaria o mesmo valor duas vezes. Em aberto o banco é
    -- só a conta prevista, e não impede nada.
    IF EXISTS (
      SELECT 1 FROM public.transacao p
       WHERE p.id = new.baixa_de_transacao_id
         AND p.pendente = false
         AND p.banco_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION
        'O título #% já foi baixado de uma vez e o dinheiro dele está nele: ou ele tem banco, ou tem baixas parciais.',
        new.baixa_de_transacao_id USING ERRCODE = '22023';
    END IF;
    RETURN new;
  END IF;

  -- O outro lado da mesma regra, e aqui NÃO se olha `pendente`.
  --
  -- Tentei afrouxar para "só quando fechar", já que título em aberto não aparece
  -- no extrato. Mas aceitar o banco agora só adia o estouro: quando as parciais
  -- cobrissem o valor, o gatilho do saldo poria `pendente = false` e a trava
  -- dispararia ali — no meio da baixa que o usuário acabou de mandar, com uma
  -- mensagem sobre um banco que ele gravou dias antes. Recusar na hora em que se
  -- tenta gravar é o único lugar em que dá para explicar o motivo.
  IF new.banco_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.transacao f
        WHERE f.baixa_de_transacao_id = new.id AND f.is_deleted = false
     ) THEN
    RAISE EXCEPTION
      'O título #% é pago em partes e o dinheiro dele está nas baixas parciais. Dar banco a ele somaria o mesmo valor duas vezes.',
      new.id USING ERRCODE = '23514';
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_competencia_entrada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_competencia_entrada() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new.competencia_em IS NOT NULL THEN
    RETURN new;
  END IF;

  -- Nota mista preenche as duas colunas; as duas metades são da mesma nota, e
  -- por isso a ordem entre elas não muda a data.
  IF new.entrada_id IS NOT NULL THEN
    SELECT coalesce(e.data_emissao, e.created_at)
      INTO new.competencia_em
      FROM public.entrada e
     WHERE e.id = new.entrada_id;
  ELSIF new.usoconsumo_entrada_id IS NOT NULL THEN
    SELECT coalesce(u.data_emissao, u.created_at)
      INTO new.competencia_em
      FROM public.usoconsumo_entrada u
     WHERE u.id = new.usoconsumo_entrada_id;
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_contraparte_historico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_contraparte_historico() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new.cliente_id IS NOT DISTINCT FROM old.cliente_id
     AND new.fornecedor_id IS NOT DISTINCT FROM old.fornecedor_id
     AND new.nomepagador IS NOT DISTINCT FROM old.nomepagador
     AND new.cpfcnpjpagador IS NOT DISTINCT FROM old.cpfcnpjpagador THEN
    RETURN new;
  END IF;

  INSERT INTO public.transacao_contraparte_historico (
    transacao_id,
    cliente_anterior_id, cliente_novo_id,
    fornecedor_anterior_id, fornecedor_novo_id,
    nome_anterior, nome_novo,
    documento_anterior, documento_novo,
    alterado_por
  ) VALUES (
    new.id,
    old.cliente_id, new.cliente_id,
    old.fornecedor_id, new.fornecedor_id,
    old.nomepagador, new.nomepagador,
    old.cpfcnpjpagador, new.cpfcnpjpagador,
    new.updated_by
  );

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_movimento_registrado(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_movimento_registrado() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (old.pendente IS DISTINCT FROM new.pendente AND new.pendente = false)
     OR (old.data IS DISTINCT FROM new.data) THEN
    new.movimento_registrado_em := now();
  END IF;

  RETURN new;
END;
$$;


--
-- Name: FUNCTION tg_transacao_movimento_registrado(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_transacao_movimento_registrado() IS 'Carimba movimento_registrado_em com now() quando a transação vira movimento ou muda de dia. É o que dá ao Fluxo a ordem de realização dentro do dia.';


--
-- Name: tg_transacao_transferencia_imutavel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_transferencia_imutavel() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.transferencia_id IS NULL AND OLD.transferencia_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.transferencia_id IS DISTINCT FROM OLD.transferencia_id THEN
    RAISE EXCEPTION
      'O vínculo da transferência não se edita: ele nasce com as duas pernas e some com elas.'
      USING ERRCODE = '22023';
  END IF;

  IF NEW.valor IS DISTINCT FROM OLD.valor
     OR NEW."valorLiquido" IS DISTINCT FROM OLD."valorLiquido"
     OR NEW.valor_base IS DISTINCT FROM OLD.valor_base
     OR NEW.tipo IS DISTINCT FROM OLD.tipo
     OR NEW.banco_id IS DISTINCT FROM OLD.banco_id
     OR NEW.pendente IS DISTINCT FROM OLD.pendente THEN
    RAISE EXCEPTION
      'Esta linha é uma das pernas da transferência #% e não muda sozinha — o valor dela é o mesmo da outra conta. Para corrigir, exclua a transferência e refaça.',
      OLD.transferencia_id
      USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: tg_transacao_valida_classificacao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_valida_classificacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_estado text;
  v_previa record;
  v_natureza text;
BEGIN
  IF new.plano_de_conta_id IS NULL THEN
    RETURN new;
  END IF;

  -- `dre_modo_apuracao` aborta quando nao ha configuracao. Ler a tabela direto
  -- devolveria NULL, a guarda concluiria "nao e ATIVO" e deixaria passar — e
  -- falta de configuracao teria virado uma decisao.
  SELECT m.estado INTO v_estado FROM public.dre_modo_apuracao() m;
  IF v_estado IS DISTINCT FROM 'ATIVO' THEN
    RETURN new;
  END IF;

  v_natureza := CASE upper(new.tipo::text)
                  WHEN 'RECEITA' THEN 'RECEITA'
                  WHEN 'DESPESA' THEN 'DESPESA'
                  ELSE NULL
                END;
  IF v_natureza IS NULL THEN
    RETURN new;
  END IF;

  SELECT * INTO v_previa
    FROM public.dre_previa_da_conta(
      new.plano_de_conta_id, v_natureza,
      coalesce(new.competencia_em, new.data, now())::date);

  IF v_previa.resultado = 'INCOMPATIVEL' THEN
    RAISE EXCEPTION '%', v_previa.motivo USING ERRCODE = 'PT422';
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_valor_apos_baixa(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_valor_apos_baixa() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF round(coalesce(new.valor, 0), 2) = round(coalesce(old.valor, 0), 2) THEN
    RETURN new;
  END IF;

  IF coalesce(old.pendente, false) = false THEN
    RAISE EXCEPTION
      'O valor de uma transação já baixada não pode ser alterado. Tire-a do fluxo de caixa primeiro: o título volta a ficar em aberto e o valor volta a ser editável.'
      USING ERRCODE = '22023';
  END IF;

  RETURN new;
END;
$$;


--
-- Name: tg_transacao_valor_base_padrao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_valor_base_padrao() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new.valor_base IS NULL OR new.valor_base = 0 THEN
    new.valor_base := coalesce(new.valor, 0);
  END IF;
  RETURN new;
END;
$$;


--
-- Name: tg_transacao_valor_coerente(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_transacao_valor_coerente() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new.valor IS DISTINCT FROM old.valor THEN
    new.valor_base := round(coalesce(new.valor, 0) - coalesce(new.valor_acrescimos, 0), 2);
  END IF;

  -- Havendo desconto lancado, o liquido e resultado, nao entrada: qualquer valor
  -- que o chamador tenha mandado seria uma segunda verdade sobre o mesmo numero.
  IF coalesce(new.valor_descontos, 0) > 0 THEN
    new."valorLiquido" := round(coalesce(new.valor, 0) - new.valor_descontos, 2);

  -- Sem desconto lancado o liquido segue livre — e assim que os registros
  -- antigos guardam a taxa da maquineta. Livre ate o bruto, nao alem dele:
  -- receber liquido mais do que o valor da transacao nao existe.
  ELSIF coalesce(new."valorLiquido", 0) > coalesce(new.valor, 0) THEN
    new."valorLiquido" := new.valor;
  END IF;

  RETURN new;
END;
$$;


--
-- Name: FUNCTION tg_transacao_valor_coerente(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tg_transacao_valor_coerente() IS 'Mantem valor_base, valor e valorLiquido coerentes entre si em toda escrita na transacao. O liquido nunca passa do bruto.';


--
-- Name: tg_venda_carimbar_marcos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_venda_carimbar_marcos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text := upper(new.status::text);
  v_anterior text := case when tg_op = 'UPDATE' then upper(old.status::text) else null end;
  -- Venda importada ou lançada com data retroativa: o marco acompanha a data
  -- informada, senão o histórico do vendedor migra todo para o dia da carga.
  v_referencia timestamptz := coalesce(new.datavenda, now());
begin
  if tg_op = 'INSERT' then
    if v_status = 'ABERTA' then
      new.orcamento_em := coalesce(new.orcamento_em, v_referencia);
    elsif v_status = 'PAGAMENTO' then
      new.pagamento_em := coalesce(new.pagamento_em, v_referencia);
    elsif v_status = 'FINALIZADA' then
      new.pagamento_em := coalesce(new.pagamento_em, v_referencia);
      new.baixada_em := coalesce(new.baixada_em, v_referencia);
    end if;
    return new;
  end if;

  if v_status is not distinct from v_anterior then
    return new;
  end if;

  -- `coalesce` em vez de atribuição direta: se a venda voltar de FINALIZADA por
  -- estorno e for para pagamento de novo, o marco que vale é o primeiro — é ele
  -- que define o período de comissão do vendedor.
  if v_status = 'PAGAMENTO' then
    new.pagamento_em := coalesce(new.pagamento_em, now());
  end if;

  if v_status = 'FINALIZADA' then
    -- Venda que pula direto para FINALIZADA (quitada no ato) nunca passou por um
    -- UPDATE para PAGAMENTO: sem isto ela ficaria fora do filtro da aba.
    new.pagamento_em := coalesce(new.pagamento_em, now());
    new.baixada_em := coalesce(new.baixada_em, now());
  elsif v_anterior = 'FINALIZADA' and v_status = 'PAGAMENTO' then
    -- Estorno da baixa: sem limpar, a venda ficaria em PAGAMENTO exibindo data
    -- de baixa. Cancelamento não passa por aqui — lá o histórico é preservado.
    new.baixada_em := null;
  elsif v_status = 'ORCAMENTO' then
    -- Voltou a ser proposta: não há pagamento nem baixa a exibir.
    new.pagamento_em := null;
    new.baixada_em := null;
    new.orcamento_em := coalesce(new.orcamento_em, now());
  end if;

  return new;
end;
$$;


--
-- Name: tg_venda_comissao_exclusao(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_venda_comissao_exclusao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM 1 FROM public.eventos_financeiros
   WHERE source_type='VENDA' AND source_id=old.id AND origem='COMISSAO' FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.eventos_financeiros
    WHERE source_type='VENDA' AND source_id=old.id AND origem='COMISSAO'
      AND (status='CONVERTIDO' OR transacaoid IS NOT NULL OR lancamento_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'Desfaça o lançamento financeiro da comissão antes de excluir esta venda.' USING ERRCODE='P0001';
  END IF;
  RETURN old;
END;
$$;


--
-- Name: tg_venda_comissao_percentual(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_venda_comissao_percentual() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  SELECT coalesce(u.comissao_venda_percent,0) INTO new.comissao_venda_percent_aplicada
    FROM public.usuario u WHERE u.id=coalesce(new.vendedor,new.created_by);
  new.comissao_venda_percent_aplicada := coalesce(new.comissao_venda_percent_aplicada,0);
  RETURN new;
END;
$$;


