--
-- Name: tg_venda_resetar_aprovacao_ao_orcamento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_venda_resetar_aprovacao_ao_orcamento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status::text = 'ORCAMENTO' AND OLD.status::text IS DISTINCT FROM 'ORCAMENTO' THEN
    NEW.statusaprovacao := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: tg_vincular_transacao_evento_financeiro(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_vincular_transacao_evento_financeiro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_evento public.eventos_financeiros%ROWTYPE;
BEGIN
  IF new.evento_financeiro_id IS NULL THEN RETURN new; END IF;
  SELECT * INTO v_evento FROM public.eventos_financeiros WHERE id=new.evento_financeiro_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Evento financeiro não encontrado.'; END IF;
  IF v_evento.status <> 'ATIVO' OR v_evento.transacaoid IS NOT NULL OR v_evento.lancamento_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este evento já foi convertido ou cancelado.';
  END IF;
  IF NOT v_evento.pode_gerar_transacao THEN RAISE EXCEPTION 'Este evento não pode gerar uma transação.'; END IF;
  IF v_evento.ordemservicoid IS DISTINCT FROM new.ordemservicoid OR v_evento.natureza <> new.tipo::text THEN
    RAISE EXCEPTION 'A transação não corresponde ao documento ou à natureza do evento financeiro.';
  END IF;
  IF v_evento.source_type = 'VENDA' AND (new.vendaid IS NOT NULL
     OR NOT EXISTS(SELECT 1 FROM public.venda WHERE id=v_evento.source_id)) THEN
    RAISE EXCEPTION 'Use apenas o vínculo do evento para este fato complementar da venda.';
  END IF;
  IF round(v_evento.valor,2) <> round(new.valor,2) THEN
    RAISE EXCEPTION 'O valor da transação deve ser igual ao valor do evento financeiro.';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: titulo_servico_os(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.titulo_servico_os(p_descricao_cadastro text, p_descricao_item text, p_servicoid integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  -- O texto livre que já começa pelo nome do cadastro vale sozinho: no Demir
  -- existe linha digitada como "MAO DE OBRA + SERVIÇO, REVISAO NA BOMBA", e
  -- prefixar o cadastro de novo daria "MAO DE OBRA + SERVIÇO - MAO DE OBRA +
  -- SERVIÇO, REVISAO NA BOMBA". O prefixo cobre também o texto idêntico, que é
  -- o caso comum de quem repete o nome do serviço no campo livre.
  --
  -- A comparação ignora caixa porque o campo é digitado à mão e a oficina
  -- alterna entre maiúsculas e minúsculas no mesmo dia.
  SELECT coalesce(
    CASE
      WHEN t.cadastro IS NOT NULL AND t.item IS NOT NULL THEN
        CASE
          WHEN left(lower(t.item), length(t.cadastro)) = lower(t.cadastro) THEN t.item
          ELSE t.cadastro || ' - ' || t.item
        END
      ELSE coalesce(t.cadastro, t.item)
    END,
    'Servico #' || p_servicoid
  )
  FROM (
    SELECT nullif(btrim(p_descricao_cadastro), '') AS cadastro,
           -- A quebra de linha no texto livre viraria uma linha solta no meio da
           -- descrição do evento.
           nullif(btrim(regexp_replace(coalesce(p_descricao_item, ''), '\s+', ' ', 'g')), '') AS item
  ) t;
$$;


--
-- Name: FUNCTION titulo_servico_os(p_descricao_cadastro text, p_descricao_item text, p_servicoid integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.titulo_servico_os(p_descricao_cadastro text, p_descricao_item text, p_servicoid integer) IS 'Título do serviço numa OS: nome do cadastro + o texto livre da linha, quando os dois existem e diferem.';


--
-- Name: titulos_do_cliente(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.titulos_do_cliente(p_cliente_id integer) RETURNS TABLE(id bigint, valor numeric, valor_acrescimos numeric, valor_baixado numeric, pendente boolean, data timestamp with time zone, vencimento_em timestamp with time zone, pago_em timestamp with time zone, ordemservicoid integer, vendaid integer, metodopagamento text, origem text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT
    tc.transacao_id,
    tc.valor,
    tc.valor_acrescimos,
    tc.valor_baixado,
    tc.pendente,
    tc.data,
    tc.vencimento_em,
    tc.pago_em,
    tc.ordemservicoid,
    tc.vendaid,
    tc.metodopagamento::text,
    tc.origem
  FROM public.transacao_cliente tc
  WHERE tc.cliente_id = p_cliente_id
  ORDER BY tc.data DESC;
$$;


--
-- Name: to_mercosul_equivalente(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.to_mercosul_equivalente(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
  select
    case
      -- placa antiga: ABC1234 -> ABC1C34 (0->A ... 9->J)
      when p ~ '^[A-Z]{3}[0-9]{4}$' then
        substr(p,1,3) ||
        substr(p,4,1) ||
        chr(65 + cast(substr(p,5,1) as int)) ||
        substr(p,6,2)

      -- já no padrão novo (Mercosul): mantém
      when p ~ '^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$' then
        p

      else null
    end;
$_$;


--
-- Name: transacao_gera_evento_de_resultado(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transacao_gera_evento_de_resultado(p_transacao_id bigint) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tx public.transacao%ROWTYPE;
  v_exclui boolean;
BEGIN
  SELECT * INTO v_tx FROM public.transacao WHERE id = p_transacao_id;
  IF NOT FOUND THEN RETURN false; END IF;

  -- Liquidacao de algo ja reconhecido, compra que vira estoque, ou saldo de
  -- abertura trazido de outro sistema: nao e resultado novo.
  --
  -- `baixa_de_transacao_id` e a baixa parcial de um titulo que ja tem evento;
  -- `pagamento_multiplo_id`, a parcela que quita varios documentos de uma vez;
  -- `lancamento_id`, o boleto que quita despesas de OS. Os tres sao a mesma
  -- ideia do `evento_financeiro_id`, em formatos diferentes.
  --
  -- `eh_adiantamento` e `adiantamento_id` sao antecipacao de recebivel: o
  -- dinheiro chega antes, a receita ja foi (ou sera) reconhecida no documento.
  -- Contar os dois e faturar duas vezes.
  --
  -- SAQUE, DEPOSITO e `transferencia_id` sao tesouraria: dinheiro mudando de
  -- lugar entre o caixa e a conta da propria empresa. Nao dependem da conta do
  -- plano — um saque numa conta de despesa continua sendo saque. Quando um
  -- gasto de verdade for lancado como saque, o conserto e trocar o tipo do
  -- lancamento, nao fazer a DRE adivinhar.
  IF v_tx.is_deleted
     OR v_tx.evento_financeiro_id IS NOT NULL
     OR v_tx.lancamento_id IS NOT NULL
     OR v_tx.pagamento_multiplo_id IS NOT NULL
     OR v_tx.baixa_de_transacao_id IS NOT NULL
     OR v_tx.ordemservicoid IS NOT NULL
     OR v_tx.vendaid IS NOT NULL
     OR v_tx.entrada_id IS NOT NULL
     OR v_tx.usoconsumo_entrada_id IS NOT NULL
     OR v_tx.origem = 'ORIGEM_MIGRACAO'
     OR coalesce(v_tx.eh_adiantamento, false)
     OR v_tx.adiantamento_id IS NOT NULL
     OR v_tx.transferencia_id IS NOT NULL
     OR upper(v_tx.tipo::text) IN ('SAQUE', 'DEPOSITO') THEN
    RETURN false;
  END IF;

  -- Conta fora do resultado, pela mesma regra que a tela mostra: classificacao
  -- patrimonial da conta ou do grupo, ou, sem nenhuma, o mapeamento antigo do
  -- grupo marcado para ficar fora.
  SELECT d.situacao = 'EXCLUIDO'
    INTO v_exclui
    FROM public.dre_destino_do_cadastro(
           v_tx.plano_de_conta_id, NULL, coalesce(v_tx.competencia_em, v_tx.data)::date) d;

  RETURN NOT coalesce(v_exclui, false);
END;
$$;


--
-- Name: FUNCTION transacao_gera_evento_de_resultado(p_transacao_id bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transacao_gera_evento_de_resultado(p_transacao_id bigint) IS 'Verdadeiro quando a transacao deve gerar evento financeiro proprio. Regra unica, usada pela sincronizacao e pela fila de pendencias. Ficam de fora: liquidacao de algo ja reconhecido (evento, lancamento de eventos, pagamento multiplo, baixa parcial, OS, venda, entrada, uso e consumo), carga de migracao, antecipacao de recebivel, tesouraria (saque, deposito e transferencia entre contas proprias) e conta cujo destino (dre_destino_do_cadastro) e fora do resultado.';


--
-- Name: transacao_valor_liquido_efetivo(public.transacao); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transacao_valor_liquido_efetivo(p_transacao public.transacao) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN coalesce(p_transacao.valor_descontos, 0) > 0 THEN
      CASE WHEN coalesce(p_transacao."valorLiquido", 0) > 0
        THEN round(p_transacao."valorLiquido", 2)
        ELSE round(coalesce(p_transacao.valor, 0) - p_transacao.valor_descontos, 2)
      END
    -- Só receita e saque têm taxa, e portanto líquido. Despesa e depósito valem
    -- o bruto — registro antigo guarda lixo nessa coluna.
    WHEN upper(p_transacao.tipo::text) NOT IN ('RECEITA', 'SAQUE') THEN
      round(coalesce(p_transacao.valor, 0), 2)
    WHEN coalesce(p_transacao."valorLiquido", 0) > 0 THEN
      round(p_transacao."valorLiquido", 2)
    ELSE round(coalesce(p_transacao.valor, 0), 2)
  END;
$$;


--
-- Name: FUNCTION transacao_valor_liquido_efetivo(p_transacao public.transacao); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.transacao_valor_liquido_efetivo(p_transacao public.transacao) IS 'O dinheiro que a transação de fato movimenta, já descontada a taxa da maquineta. Mesma regra de valorLiquidoEfetivo() no TypeScript.';


--
-- Name: transicionar_faturamento_os(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transicionar_faturamento_os(p_os_id integer, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_os public.ordemservico;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(87009, 1);
  PERFORM pg_advisory_xact_lock(87001, p_os_id);
  SELECT * INTO v_os FROM public.ordemservico WHERE id = p_os_id AND NOT coalesce(is_deleted, false) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OS não encontrada.' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.faturamento_os_habilitado() THEN
    RAISE EXCEPTION 'A etapa de faturamento está desativada. Atualize a tela.' USING ERRCODE = 'P0001';
  END IF;
  IF NOT ((v_os.status = 'PAGAMENTO' AND p_status = 'FATURAMENTO')
      OR (v_os.status = 'FATURAMENTO' AND p_status = 'PAGAMENTO')) THEN
    RAISE EXCEPTION 'O status da OS mudou. Atualize a tela antes de continuar.' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.ordemservico SET status = p_status::public.enum_status_os, updatedat = now() WHERE id = p_os_id;
  IF p_status = 'FATURAMENTO' THEN PERFORM public.recalcular_status_financeiro_os(p_os_id); END IF;
  SELECT * INTO v_os FROM public.ordemservico WHERE id = p_os_id;
  RETURN to_jsonb(v_os);
END;
$$;


--
-- Name: transicionar_faturamento_os(integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transicionar_faturamento_os(p_os_id integer, p_status text, p_condicoes jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_saldo numeric;
  v_total numeric;
  v_resultado jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(87009, 1);
  PERFORM pg_advisory_xact_lock(87001, p_os_id);
  PERFORM 1 FROM public.ordemservico WHERE id = p_os_id FOR UPDATE;
  IF p_status <> 'FATURAMENTO' THEN
    RAISE EXCEPTION 'Condições de pagamento são informadas no envio para faturamento.';
  END IF;
  IF p_condicoes IS NULL OR jsonb_typeof(p_condicoes) <> 'object' THEN
    RAISE EXCEPTION 'Informe as condições de pagamento.';
  END IF;
  SELECT saldo_disponivel_lancamento INTO v_saldo FROM public.resumo_financeiro_os(p_os_id);
  SELECT coalesce(sum((item->>'valor')::numeric), 0) INTO v_total
    FROM jsonb_array_elements(coalesce(nullif(p_condicoes->'pagamentos_previstos', 'null'::jsonb), '[]'::jsonb)) item;
  IF round(v_total, 2) <> round(greatest(coalesce(v_saldo, 0), 0), 2) THEN
    RAISE EXCEPTION 'A soma dos pagamentos previstos precisa fechar o saldo ainda não coberto da OS. Atualize a tela.';
  END IF;

  -- A versão de dois argumentos revalida modo, origem e status sob estes locks.
  PERFORM public.transicionar_faturamento_os(p_os_id, p_status);
  UPDATE public.ordemservico SET
    pagamentos_previstos = nullif(p_condicoes->'pagamentos_previstos', 'null'::jsonb),
    forma_pagamento = nullif(p_condicoes->>'forma_pagamento', '')::public.metodo_pagamento,
    parcelas_pagamento = (p_condicoes->>'parcelas_pagamento')::integer,
    descricao_financeiro = p_condicoes->>'descricao_financeiro',
    garantia = CASE WHEN p_condicoes ? 'garantia' THEN p_condicoes->>'garantia' ELSE garantia END
  WHERE id = p_os_id;
  SELECT to_jsonb(os) INTO v_resultado FROM public.ordemservico os WHERE id = p_os_id;
  RETURN v_resultado;
END;
$$;


--
-- Name: travar_fluxo_faturamento_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.travar_fluxo_faturamento_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'config_geral' THEN
    PERFORM pg_advisory_xact_lock(87009, 1);
  ELSE
    PERFORM pg_advisory_xact_lock_shared(87009, 1);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: trg_os_status_estornar(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_os_status_estornar() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Rejeicao do orcamento e cancelamento definitivo devolvem qualquer baixa existente.
  IF new.status IN ('ORCAMENTO_RECUSADO', 'CANCELADO')
     AND old.status IS DISTINCT FROM new.status THEN
    PERFORM public.estornar_baixa_estoque_os(new.id);
    PERFORM public.estornar_consumos_os(new.id);
  END IF;
  RETURN new;
END;
$$;


--
-- Name: trocar_criador_os(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trocar_criador_os(p_ordemservicoid integer, p_usuarioid uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_os record;
  v_novo record;
  v_nome_anterior text;
  v_comprometidas integer;
  v_comissao_anterior numeric;
  v_comissao_nova numeric;
  v_publica boolean;
BEGIN
  SELECT o.id, o.status::text AS status, o.is_deleted, o.usuariocriadorid
    INTO v_os
    FROM public.ordemservico o
   WHERE o.id = p_ordemservicoid
   FOR UPDATE;

  IF NOT FOUND OR coalesce(v_os.is_deleted, false) THEN
    RAISE EXCEPTION 'OS não encontrada.' USING ERRCODE = 'P0001';
  END IF;
  IF v_os.status = 'CANCELADO' THEN
    RAISE EXCEPTION 'Uma OS cancelada não muda de criador.' USING ERRCODE = 'P0001';
  END IF;

  SELECT u.id, coalesce(nullif(btrim(u.nome), ''), u.email) AS nome, coalesce(u.ativo, false) AS ativo
    INTO v_novo
    FROM public.usuario u
   WHERE u.id = p_usuarioid;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Usuário não encontrado.' USING ERRCODE = 'P0001';
  END IF;
  IF NOT v_novo.ativo THEN
    RAISE EXCEPTION '% está inativo e não pode ser o criador da OS.', v_novo.nome USING ERRCODE = 'P0001';
  END IF;
  IF v_os.usuariocriadorid IS NOT DISTINCT FROM p_usuarioid THEN
    RAISE EXCEPTION 'A OS já foi criada por %.', v_novo.nome USING ERRCODE = 'P0001';
  END IF;

  SELECT coalesce(nullif(btrim(u.nome), ''), u.email)
    INTO v_nome_anterior
    FROM public.usuario u
   WHERE u.id = v_os.usuariocriadorid;

  -- Comissão de quem saiu que já virou dinheiro, ou foi escrita à mão.
  SELECT count(*)
    INTO v_comprometidas
    FROM public.eventos_financeiros e
   WHERE e.ordemservicoid = p_ordemservicoid
     AND e.origem = 'COMISSAO'
     AND e.chave_origem LIKE 'CRIACAO:%'
     AND e.usuarioid IS DISTINCT FROM p_usuarioid
     AND e.status <> 'CANCELADO'
     AND (e.status = 'CONVERTIDO' OR e.transacaoid IS NOT NULL
          OR e.lancamento_id IS NOT NULL OR coalesce(e.is_manual, false));

  IF v_comprometidas > 0 THEN
    RAISE EXCEPTION 'A comissão de criação desta OS já foi lançada no financeiro ou corrigida à mão. Desfaça isso antes de trocar o criador.'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT coalesce(sum(c.valor_comissao), 0)
    INTO v_comissao_anterior
    FROM public.os_comissao_criacao c
   WHERE c.ordemservicoid = p_ordemservicoid;

  UPDATE public.ordemservico
     SET usuariocriadorid = p_usuarioid
   WHERE id = p_ordemservicoid;

  -- O snapshot sai inteiro: sem isso o ON CONFLICT do recálculo manteria o
  -- dono antigo nas linhas que já existiam.
  DELETE FROM public.os_comissao_criacao WHERE ordemservicoid = p_ordemservicoid;

  -- Sem cobrança não comissiona.
  IF v_os.status <> 'SEM_COBRANCA' THEN
    PERFORM public.recalcular_comissao_criacao_os(p_ordemservicoid, true);
  END IF;

  SELECT coalesce(sum(c.valor_comissao), 0)
    INTO v_comissao_nova
    FROM public.os_comissao_criacao c
   WHERE c.ordemservicoid = p_ordemservicoid;

  -- Os status em que a comissão já está no livro, mais a OS que já tem comissão
  -- ativa por outro caminho — a reiniciada mantém os eventos (20260916180000).
  -- A chave `CRIACAO:<uuid>:...` muda junto com o dono: a reconciliação cancela
  -- a de quem saiu e publica a de quem entrou.
  v_publica := v_os.status IN ('EM_ANDAMENTO', 'PAGAMENTO', 'FATURAMENTO', 'CONCLUIDO')
    OR EXISTS (
      SELECT 1 FROM public.eventos_financeiros e
       WHERE e.ordemservicoid = p_ordemservicoid
         AND e.origem = 'COMISSAO'
         AND e.status = 'ATIVO'
    );

  IF v_publica THEN
    PERFORM public.reconciliar_eventos_financeiros_os(p_ordemservicoid, true);
  END IF;

  RETURN jsonb_build_object(
    'criador_anterior', CASE WHEN v_os.usuariocriadorid IS NULL THEN NULL
                             ELSE jsonb_build_object('id', v_os.usuariocriadorid, 'nome', v_nome_anterior) END,
    'criador_novo', jsonb_build_object('id', p_usuarioid, 'nome', v_novo.nome),
    'comissao_anterior', round(v_comissao_anterior, 2),
    'comissao_nova', round(v_comissao_nova, 2),
    'eventos_publicados', v_publica
  );
END;
$$;


--
-- Name: FUNCTION trocar_criador_os(p_ordemservicoid integer, p_usuarioid uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trocar_criador_os(p_ordemservicoid integer, p_usuarioid uuid) IS 'Troca o criador da OS e reapura a comissão de criação pela taxa de quem entrou, republicando os eventos quando a OS já os tem. Recusa OS cancelada e comissão de criação já lançada no financeiro ou corrigida à mão.';


--
-- Name: usoconsumo_atualizar_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usoconsumo_atualizar_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.status_estoque := CASE
    WHEN NEW.estoque = 0 THEN 'SEM_ESTOQUE'
    WHEN NEW.estoqueminimo > 0 AND NEW.estoque <= greatest(floor(NEW.estoqueminimo / 2.0),1) THEN 'CRITICO'
    WHEN NEW.estoque <= NEW.estoqueminimo THEN 'BAIXO'
    ELSE 'OK'
  END;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


--
-- Name: usoconsumo_proteger_saldo(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usoconsumo_proteger_saldo() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.estoque IS DISTINCT FROM OLD.estoque
     AND coalesce(current_setting('app.usoconsumo_movimento', true),'') <> 'permitido' THEN
    RAISE EXCEPTION 'O saldo somente pode ser alterado por uma movimentacao de uso e consumo.' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: usoconsumo_validar_escopo_movimento(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.usoconsumo_validar_escopo_movimento() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_escopo_item text;
  v_escopo_cabecalho text;
BEGIN
  SELECT escopo INTO v_escopo_item
    FROM public.usoconsumo_item WHERE id = NEW.item_id;

  IF TG_ARGV[0] = 'ENTRADA' THEN
    SELECT escopo INTO v_escopo_cabecalho
      FROM public.usoconsumo_entrada WHERE id = NEW.entrada_id;
  ELSE
    SELECT escopo INTO v_escopo_cabecalho
      FROM public.usoconsumo_saida WHERE id = NEW.saida_id;
  END IF;

  IF v_escopo_cabecalho = 'MISTO' THEN
    IF v_escopo_item NOT IN ('USOCONSUMO', 'GERAL') THEN
      RAISE EXCEPTION 'O item % nao pertence a nenhum estoque simples valido.', NEW.item_id
        USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  IF v_escopo_item IS DISTINCT FROM v_escopo_cabecalho THEN
    RAISE EXCEPTION
      'O item % pertence ao estoque % e nao pode entrar em um movimento do estoque %.',
      NEW.item_id, v_escopo_item, v_escopo_cabecalho USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END $$;


--
-- Name: validar_assinatura_ultima_versao_checklist(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_assinatura_ultima_versao_checklist() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  doc public.checklist_documento%rowtype;
begin
  select * into doc
  from public.checklist_documento
  where id = new.documento_id;

  if not found then
    raise exception 'Documento de checklist nao encontrado.' using errcode = '23503';
  end if;

  if exists (
    select 1
    from public.checklist_documento posterior
    where posterior.ordemservico_id = doc.ordemservico_id
      and posterior.tipo = doc.tipo
      and posterior.versao > doc.versao
  ) then
    raise exception 'Somente a versao mais recente do checklist pode ser assinada.' using errcode = '55000';
  end if;

  if new.snapshot_hash is distinct from doc.snapshot_hash then
    raise exception 'A assinatura nao corresponde ao snapshot armazenado.' using errcode = '55000';
  end if;

  return new;
end;
$$;


--
-- Name: validar_etiqueta_inventario_global(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_etiqueta_inventario_global() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_etiqueta text;
BEGIN
  v_etiqueta := nullif(upper(btrim(NEW.etiqueta)), '');
  NEW.etiqueta := v_etiqueta;
  IF v_etiqueta IS NULL THEN
    RETURN NEW;
  END IF;

  -- Serializa tentativas concorrentes para a mesma etiqueta, inclusive entre tabelas.
  PERFORM pg_advisory_xact_lock(hashtextextended('inventario-etiqueta:' || v_etiqueta, 0));

  IF TG_TABLE_NAME = 'produto' THEN
    PERFORM 1 FROM public.usoconsumo_item
    WHERE upper(btrim(etiqueta)) = v_etiqueta
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe um item de uso e consumo com esta etiqueta.' USING ERRCODE = '23505';
    END IF;

    PERFORM 1 FROM public.produto
    WHERE upper(btrim(etiqueta)) = v_etiqueta
      AND id <> coalesce(NEW.id, 0)
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe um produto com esta etiqueta.' USING ERRCODE = '23505';
    END IF;
  ELSE
    PERFORM 1 FROM public.produto
    WHERE upper(btrim(etiqueta)) = v_etiqueta
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe um produto com esta etiqueta.' USING ERRCODE = '23505';
    END IF;

    PERFORM 1 FROM public.usoconsumo_item
    WHERE upper(btrim(etiqueta)) = v_etiqueta
      AND id <> coalesce(NEW.id, 0)
    LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'Já existe outro item de uso e consumo com esta etiqueta.' USING ERRCODE = '23505';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validar_limite_pagamento_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_limite_pagamento_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_status text;
  v_total_devido numeric(14,2);
  v_ja_comprometido numeric(14,2);
  v_novo_valor_face numeric(14,2);
BEGIN
  IF NEW.ordemservicoid IS NULL
     OR upper(NEW.tipo::text) <> 'RECEITA'
     OR NEW.evento_financeiro_id IS NOT NULL
     OR NEW.is_deleted THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock_shared(87009, 1);

  -- O lock vive até o fim da transação que efetivamente insere/edita a linha.
  PERFORM pg_advisory_xact_lock(87001, NEW.ordemservicoid);

  SELECT o.status::text,
         round(
           greatest(coalesce(o.orcamentototal, 0), 0) +
           CASE
             WHEN o.acrescimo_financeiro_tipo = 'PORCENTAGEM' THEN
               greatest(coalesce(o.orcamentototal, 0), 0) *
               least(greatest(coalesce(o.acrescimo_financeiro_valor, 0), 0), 100) / 100
             WHEN o.acrescimo_financeiro_tipo = 'FIXO' THEN
               greatest(coalesce(o.acrescimo_financeiro_valor, 0), 0)
             ELSE 0
           END,
           2
         )
    INTO v_status, v_total_devido
  FROM public.ordemservico o
  WHERE o.id = NEW.ordemservicoid
    AND coalesce(o.is_deleted, false) = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ordem de serviço não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF TG_OP = 'INSERT' OR OLD.ordemservicoid IS DISTINCT FROM NEW.ordemservicoid
     OR OLD.tipo IS DISTINCT FROM NEW.tipo
     OR OLD.evento_financeiro_id IS DISTINCT FROM NEW.evento_financeiro_id
     OR (OLD.is_deleted AND NOT NEW.is_deleted)
     OR (public.faturamento_os_habilitado() AND NEW.valor - coalesce(NEW.valor_acrescimos,0) > OLD.valor - coalesce(OLD.valor_acrescimos,0)) THEN
    PERFORM public.validar_novo_recebimento_os(NEW.ordemservicoid);
  END IF;

  IF v_total_devido <= 0 THEN
    RAISE EXCEPTION 'A OS não possui valor financeiro disponível para pagamento.'
      USING ERRCODE = '23514';
  END IF;

  SELECT coalesce(round(sum(r.valor), 2), 0) INTO v_ja_comprometido
    FROM public.recebimento_por_documento r
   WHERE r.tipo_documento = 'OS' AND r.documento_id = NEW.ordemservicoid
     AND (TG_OP = 'INSERT' OR r.transacao_id <> NEW.id);

  v_novo_valor_face := round(
    greatest(coalesce(NEW.valor, 0) - greatest(coalesce(NEW.valor_acrescimos, 0), 0), 0),
    2
  );

  IF round(v_ja_comprometido + v_novo_valor_face, 2) > v_total_devido THEN
    RAISE EXCEPTION 'A soma de pagamentos e títulos ultrapassa o total financeiro da OS. Saldo disponível: R$ %.',
      to_char(greatest(v_total_devido - v_ja_comprometido, 0), 'FM999G999G990D00')
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: validar_novo_recebimento_os(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_novo_recebimento_os(p_os_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_status text;
BEGIN
  IF coalesce(current_setting('app.reparcelamento_em_curso', true), '') = 'permitido' THEN
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock_shared(87009, 1);
  PERFORM pg_advisory_xact_lock(87001, p_os_id);
  SELECT status::text INTO v_status FROM public.ordemservico
    WHERE id = p_os_id AND NOT coalesce(is_deleted, false) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'OS não encontrada.' USING ERRCODE = 'P0002'; END IF;
  IF v_status NOT IN ('ORCAMENTO_APROVADO', 'EM_ANDAMENTO')
     AND v_status <> (CASE WHEN public.faturamento_os_habilitado() THEN 'FATURAMENTO' ELSE 'PAGAMENTO' END) THEN
    RAISE EXCEPTION 'A OS não está disponível para novos registros financeiros. Verifique o status e a configuração de faturamento.' USING ERRCODE = 'P0001';
  END IF;
END;
$$;


--
-- Name: validar_ositem_historico(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_ositem_historico() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE')
     and coalesce(current_setting('app.permitir_alterar_os_migrada', true), '') <> 'on' then
    raise exception 'Itens de OS historica sao somente leitura.'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if not exists (
    select 1
      from public.ordemservico os
     where os.id = new.ordemservicoid
       and os.migracao_referencia is not null
       and os.status::text = 'CONCLUIDO'
  ) then
    raise exception 'O item historico exige uma OS migrada e concluida.'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


--
-- Name: validar_rateio_faturamento_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_rateio_faturamento_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.tipo_documento = 'OS' AND (TG_OP = 'INSERT'
      OR OLD.documento_id IS DISTINCT FROM NEW.documento_id
      OR OLD.tipo_documento IS DISTINCT FROM NEW.tipo_documento
      OR NEW.valor > OLD.valor) THEN
    PERFORM public.validar_novo_recebimento_os(NEW.documento_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validar_status_faturamento_os(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_status_faturamento_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ativo boolean := public.faturamento_os_habilitado();
  v_quitada boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF NEW.status = 'FATURAMENTO' THEN
    IF NOT v_ativo THEN
      RAISE EXCEPTION 'A etapa de faturamento está desativada. Atualize a tela.' USING ERRCODE = 'P0001';
    END IF;
    IF TG_OP = 'INSERT' OR OLD.status NOT IN ('PAGAMENTO', 'CONCLUIDO') THEN
      RAISE EXCEPTION 'Somente uma OS em Pagamento pode ser enviada para faturamento.' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF v_ativo AND NEW.status = 'CONCLUIDO' AND NEW.migracao_referencia IS NULL THEN
    SELECT quitada INTO v_quitada FROM public.resumo_financeiro_os(NEW.id);
    IF NOT coalesce(v_quitada, false) THEN
      RAISE EXCEPTION 'Registre a cobertura integral da OS em Faturamento antes de concluir.' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validar_tipo_entrada(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validar_tipo_entrada() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_escopo text := TG_ARGV[0];
  v_tipo text := upper(btrim(coalesce(NEW.tipo, '')));
BEGIN
  IF v_tipo = '' THEN
    RAISE EXCEPTION 'Informe o tipo da entrada.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tipos_entrada
    WHERE codigo = v_tipo AND ativo AND escopo IN (v_escopo, 'AMBOS')
  ) THEN
    RAISE EXCEPTION 'Tipo de entrada invalido: %.', v_tipo USING ERRCODE = '22023';
  END IF;
  NEW.tipo := v_tipo;
  RETURN NEW;
END;
$$;


--
-- Name: venda_reconhece_receita(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.venda_reconhece_receita(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT upper(coalesce(p_status, '')) IN ('PAGAMENTO', 'FINALIZADA', 'PAGO', 'AUTORIZADO');
$$;


--
-- Name: FUNCTION venda_reconhece_receita(p_status text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.venda_reconhece_receita(p_status text) IS 'Status de venda que representam operacao concluida. Centraliza a regra para a DRE e qualquer relatorio futuro.';


--
-- Name: vincular_nfe_origens(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vincular_nfe_origens(p_nfe_id bigint, p_origens jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_origem jsonb;
  v_tipo text;
  v_origem_id integer;
  v_nfe_os integer;
  v_nfe_venda integer;
  v_nfe_cliente integer;
  v_nfe_modelo text;
  v_nfe_excluida boolean;
  v_tipos integer;
  v_ancora_presente boolean;
BEGIN
  IF p_nfe_id IS NULL OR jsonb_typeof(p_origens) <> 'array' OR jsonb_array_length(p_origens) = 0 THEN
    RAISE EXCEPTION 'Informe a NF-e e ao menos uma origem.' USING ERRCODE = '22023';
  END IF;

  SELECT ordemservicoid, vendaid, clienteid, modelo::text, coalesce(is_deleted, false)
    INTO v_nfe_os, v_nfe_venda, v_nfe_cliente, v_nfe_modelo, v_nfe_excluida
    FROM public.nfe
   WHERE id = p_nfe_id
   FOR UPDATE;

  IF NOT FOUND OR v_nfe_excluida OR v_nfe_modelo <> 'NFE' THEN
    RAISE EXCEPTION 'NF-e invalida para vinculo com origens.' USING ERRCODE = '22023';
  END IF;

  -- Misturar OS e venda na mesma nota não é suportado: as duas origens têm
  -- naturezas de operação e âncoras distintas.
  SELECT count(DISTINCT origem->>'tipo')
    INTO v_tipos
    FROM jsonb_array_elements(p_origens) origem;

  IF v_tipos <> 1 THEN
    RAISE EXCEPTION 'Uma NF-e agrupada nao pode misturar OS e vendas.' USING ERRCODE = '22023';
  END IF;

  SELECT origem->>'tipo' INTO v_tipo
    FROM jsonb_array_elements(p_origens) origem LIMIT 1;

  IF v_tipo NOT IN ('OS', 'VENDA') THEN
    RAISE EXCEPTION 'Tipo de origem invalido: %.', v_tipo USING ERRCODE = '22023';
  END IF;

  -- A âncora é a origem que abriu a emissão e continua nas colunas escalares.
  -- Ela não pode sair do grupo, senão a nota passaria a apontar para uma
  -- origem que não documenta mais.
  SELECT EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_origens) origem
     WHERE nullif(origem->>'origem_id', '')::integer
           = CASE WHEN v_tipo = 'OS' THEN v_nfe_os ELSE v_nfe_venda END
  ) INTO v_ancora_presente;

  IF NOT v_ancora_presente THEN
    RAISE EXCEPTION 'A origem principal da NF-e precisa permanecer no grupo.' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(format('nfe:origem:%s:%s:%s', v_tipo, ids.origem_id, v_nfe_modelo), 0)
  )
  FROM (
    SELECT DISTINCT nullif(origem->>'origem_id', '')::integer AS origem_id
      FROM jsonb_array_elements(p_origens) origem
     ORDER BY 1
  ) ids;

  DELETE FROM public.nfe_origem_vinculo WHERE nfe_id = p_nfe_id;

  FOR v_origem IN SELECT value FROM jsonb_array_elements(p_origens) LOOP
    v_origem_id := nullif(v_origem->>'origem_id', '')::integer;

    INSERT INTO public.nfe_origem_vinculo (
      nfe_id, tipo, ordemservico_id, venda_id, origem_id, modelo, cliente_id
    ) VALUES (
      p_nfe_id,
      v_tipo,
      CASE WHEN v_tipo = 'OS' THEN v_origem_id END,
      CASE WHEN v_tipo = 'VENDA' THEN v_origem_id END,
      v_origem_id,
      v_nfe_modelo,
      v_nfe_cliente
    );
  END LOOP;

  RETURN jsonb_build_object(
    'nfe_id', p_nfe_id,
    'tipo', v_tipo,
    'origens', (SELECT count(*) FROM public.nfe_origem_vinculo WHERE nfe_id = p_nfe_id)
  );
END;
$$;


--
-- Name: vincular_nfe_saidas(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vincular_nfe_saidas(p_nfe_id bigint, p_itens jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_nfe_saida_id bigint;
  v_nfe_modelo text;
  v_nfe_excluida boolean;
BEGIN
  IF p_nfe_id IS NULL OR jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Informe a NF-e e ao menos um item de saída.' USING ERRCODE = '22023';
  END IF;

  SELECT saidaid, modelo::text, coalesce(is_deleted, false)
    INTO v_nfe_saida_id, v_nfe_modelo, v_nfe_excluida
    FROM public.nfe
   WHERE id = p_nfe_id
   FOR UPDATE;

  IF NOT FOUND OR v_nfe_modelo <> 'NFE' OR v_nfe_excluida THEN
    RAISE EXCEPTION 'NF-e inválida para vínculo com saídas.' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_itens) item
     WHERE nullif(item->>'saida_id', '')::bigint = v_nfe_saida_id
  ) THEN
    RAISE EXCEPTION 'A saída principal da NF-e precisa estar entre os itens.' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(format('nfe:saida-item:%s', ids.saida_item_id), 0)
  )
  FROM (
    SELECT DISTINCT nullif(item->>'saida_item_id', '')::bigint AS saida_item_id
      FROM jsonb_array_elements(p_itens) item
     ORDER BY 1
  ) ids;

  DELETE FROM public.nfe_saida_item_vinculo WHERE nfe_id = p_nfe_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    INSERT INTO public.nfe_saida_item_vinculo (
      nfe_id, saida_id, saida_item_id, entrada_item_origem_id, quantidade
    ) VALUES (
      p_nfe_id,
      nullif(v_item->>'saida_id', '')::bigint,
      nullif(v_item->>'saida_item_id', '')::bigint,
      nullif(v_item->>'entrada_item_origem_id', '')::bigint,
      nullif(v_item->>'quantidade', '')::numeric
    );
  END LOOP;

  RETURN jsonb_build_object(
    'nfe_id', p_nfe_id,
    'saidas', (SELECT count(DISTINCT saida_id) FROM public.nfe_saida_item_vinculo WHERE nfe_id = p_nfe_id),
    'itens', (SELECT count(*) FROM public.nfe_saida_item_vinculo WHERE nfe_id = p_nfe_id)
  );
END;
$$;


--
-- Name: vincular_nfse_os(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vincular_nfse_os(p_nfse_id bigint, p_itens jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_nfse_os integer;
  v_nfse_cliente integer;
BEGIN
  IF p_nfse_id IS NULL OR jsonb_typeof(p_itens) <> 'array' OR jsonb_array_length(p_itens) = 0 THEN
    RAISE EXCEPTION 'Informe a NFS-e e ao menos um servico.' USING ERRCODE = '22023';
  END IF;

  SELECT ordemservicoid, clienteid
    INTO v_nfse_os, v_nfse_cliente
    FROM public.nfse
   WHERE id = p_nfse_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NFS-e invalida para vinculo com servicos.' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_itens) item
     WHERE nullif(item->>'ordemservico_id', '')::integer = v_nfse_os
  ) THEN
    RAISE EXCEPTION 'A OS principal da NFS-e precisa permanecer no grupo.' USING ERRCODE = '22023';
  END IF;

  -- Travas na mesma ordem para duas emissoes concorrentes nao cruzarem.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(format('nfse:os-servico:%s:%s', ids.ordemservico_id, ids.servico_id), 0)
  )
  FROM (
    SELECT DISTINCT
           nullif(item->>'ordemservico_id', '')::integer AS ordemservico_id,
           nullif(item->>'servico_id', '')::integer AS servico_id
      FROM jsonb_array_elements(p_itens) item
     ORDER BY 1, 2
  ) ids;

  DELETE FROM public.nfse_os_servico_vinculo WHERE nfse_id = p_nfse_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
    INSERT INTO public.nfse_os_servico_vinculo (
      nfse_id, ordemservico_id, servico_id, cliente_id
    ) VALUES (
      p_nfse_id,
      nullif(v_item->>'ordemservico_id', '')::integer,
      nullif(v_item->>'servico_id', '')::integer,
      v_nfse_cliente
    );
  END LOOP;

  RETURN jsonb_build_object(
    'nfse_id', p_nfse_id,
    'ordens', (SELECT count(DISTINCT ordemservico_id) FROM public.nfse_os_servico_vinculo WHERE nfse_id = p_nfse_id),
    'servicos', (SELECT count(*) FROM public.nfse_os_servico_vinculo WHERE nfse_id = p_nfse_id)
  );
END;
$$;


--
-- Name: vincular_produto_avulso_os(integer, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vincular_produto_avulso_os(p_ordem_id integer, p_avulso_id bigint, p_produto_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_modo text := 'ORCAMENTO';
  v_quantidade integer;
BEGIN
  PERFORM public.estoque_definir_contexto('ORDEM_SERVICO', p_ordem_id::bigint, 'OS #' || p_ordem_id);
  PERFORM public.vincular_produto_avulso_os_interna(p_ordem_id, p_avulso_id, p_produto_id);

  SELECT status::text
    INTO v_status
  FROM public.ordemservico
  WHERE id = p_ordem_id;

  SELECT COALESCE(modo_baixa_estoque_os::text, 'ORCAMENTO')
    INTO v_modo
  FROM public.config_geral
  ORDER BY id DESC
  LIMIT 1;

  -- PAGAMENTO acompanha EM_ANDAMENTO pela mesma razao que no PUT do orcamento:
  -- a OS ja consumiu material, entao mexer nos itens tem que mexer no saldo.
  IF v_modo = 'EXECUCAO' AND v_status IN ('EM_ANDAMENTO', 'PAGAMENTO', 'FATURAMENTO') THEN
    SELECT quantidade::integer
      INTO v_quantidade
    FROM public.osproduto
    WHERE ordemservicoid = p_ordem_id AND produtoid = p_produto_id;

    IF v_quantidade IS NOT NULL AND v_quantidade > 0 THEN
      PERFORM public.sincronizar_baixa_estoque_os_produto(p_ordem_id, p_produto_id, v_quantidade);
    END IF;
  END IF;

  IF v_status IN ('ORCAMENTO_APROVADO', 'EM_ANDAMENTO', 'PAGAMENTO', 'FATURAMENTO', 'CONCLUIDO') THEN
    PERFORM public.reconciliar_eventos_financeiros_os(
      p_ordem_id,
      v_status IN ('EM_ANDAMENTO', 'PAGAMENTO', 'FATURAMENTO', 'CONCLUIDO')
    );
  END IF;
END;
$$;


--
-- Name: vincular_produto_avulso_os_interna(integer, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.vincular_produto_avulso_os_interna(p_ordem_id integer, p_avulso_id bigint, p_produto_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item public.osproduto_avulso%ROWTYPE;
  v_estoque numeric;
  v_modo text := 'ORCAMENTO';
BEGIN
  SELECT * INTO v_item
  FROM public.osproduto_avulso
  WHERE id = p_avulso_id AND ordemservicoid = p_ordem_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto avulso não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.osproduto
    WHERE ordemservicoid = p_ordem_id AND produtoid = p_produto_id
  ) THEN
    RAISE EXCEPTION 'O produto selecionado já está neste orçamento.' USING ERRCODE = '23505';
  END IF;

  SELECT estoque INTO v_estoque
  FROM public.produto
  WHERE id = p_produto_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Produto não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(modo_baixa_estoque_os::text, 'ORCAMENTO') INTO v_modo
  FROM public.config_geral ORDER BY id DESC LIMIT 1;

  IF v_modo = 'ORCAMENTO' AND v_estoque < v_item.quantidade THEN
    RAISE EXCEPTION 'Estoque insuficiente. Disponível: %, solicitado: %.', v_estoque, v_item.quantidade
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.osproduto (
    ordemservicoid, produtoid, quantidade, precounitario, subtotal,
    desconto_tipo, desconto
  ) VALUES (
    p_ordem_id, p_produto_id, v_item.quantidade, v_item.precounitario,
    v_item.subtotal, v_item.desconto_tipo, v_item.desconto
  );

  IF v_modo = 'ORCAMENTO' THEN
    UPDATE public.produto
    SET estoque = estoque - v_item.quantidade
    WHERE id = p_produto_id;

    INSERT INTO public.osproduto_baixa (ordemservicoid, produtoid, quantidade)
    VALUES (p_ordem_id, p_produto_id, v_item.quantidade)
    ON CONFLICT (ordemservicoid, produtoid)
    DO UPDATE SET quantidade = EXCLUDED.quantidade;
  END IF;

  DELETE FROM public.osproduto_avulso WHERE id = v_item.id;
END;
$$;


--
-- Name: agendamento; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agendamento (
    id integer NOT NULL,
    clienteid integer,
    veiculoid integer,
    usuarioid uuid,
    titulo text NOT NULL,
    descricao text,
    inicio timestamp with time zone NOT NULL,
    fim timestamp with time zone,
    status text DEFAULT 'AGENDADO'::text NOT NULL,
    createdat timestamp with time zone DEFAULT now() NOT NULL,
    updatedat timestamp with time zone DEFAULT now() NOT NULL,
    origem text DEFAULT 'ERP'::text NOT NULL,
    decisorusuarioid uuid,
    solicitante_nome text,
    solicitante_cpfcnpj text,
    solicitante_telefone text,
    solicitante_email text,
    motivorecusa text,
    mensagemnotificacao text,
    canalnotificacao text,
    notificadoat timestamp with time zone,
    decisaoat timestamp with time zone,
    CONSTRAINT agendamento_origem_check CHECK ((origem = ANY (ARRAY['ERP'::text, 'SITE'::text]))),
    CONSTRAINT agendamento_periodo_check CHECK (((fim IS NULL) OR (fim > inicio))),
    CONSTRAINT agendamento_status_check CHECK ((status = ANY (ARRAY['PENDENTE_APROVACAO'::text, 'AGENDADO'::text, 'RECUSADO'::text, 'CANCELADO'::text])))
);


--
-- Name: agendamento_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.agendamento ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.agendamento_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: aluguel; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.aluguel (
    id bigint NOT NULL,
    status text DEFAULT 'ATIVO'::text NOT NULL,
    data_inicio date NOT NULL,
    data_limite date,
    pausado_em timestamp with time zone,
    encerrado_em timestamp with time zone,
    encerrado_por uuid,
    observacao_encerramento text,
    cliente_id integer,
    cliente_nome text,
    cliente_documento text,
    cliente_telefone text,
    cliente_email text,
    observacao text,
    valor_total numeric(14,2) DEFAULT 0 NOT NULL,
    motivo_exclusao text,
    is_deleted boolean DEFAULT false NOT NULL,
    created_by uuid,
    updated_by uuid,
    deleted_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    usuario_id uuid,
    CONSTRAINT aluguel_cliente_check CHECK (((num_nonnulls(cliente_id, usuario_id) <= 1) AND ((cliente_id IS NOT NULL) OR (usuario_id IS NOT NULL) OR (NULLIF(btrim(COALESCE(cliente_nome, ''::text)), ''::text) IS NOT NULL)))),
    CONSTRAINT aluguel_encerramento_check CHECK (((status = 'ENCERRADO'::text) = (encerrado_em IS NOT NULL))),
    CONSTRAINT aluguel_pausa_check CHECK (((status <> 'PAUSADO'::text) OR (pausado_em IS NOT NULL))),
    CONSTRAINT aluguel_periodo_check CHECK ((data_limite >= data_inicio)),
    CONSTRAINT aluguel_status_check CHECK ((status = ANY (ARRAY['ATIVO'::text, 'PAUSADO'::text, 'ENCERRADO'::text]))),
    CONSTRAINT aluguel_valor_total_check CHECK ((valor_total >= (0)::numeric))
);


--
-- Name: TABLE aluguel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.aluguel IS 'Aluguel de bens: produto, item de uso e consumo, item do estoque geral, veiculo ou item avulso. Status ATIVO/PAUSADO/ENCERRADO; agendado e atrasado sao derivados das datas.';


--
-- Name: COLUMN aluguel.data_limite; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.aluguel.data_limite IS 'Ultimo dia combinado. Nulo: prazo indeterminado (sem atraso).';


--
-- Name: COLUMN aluguel.pausado_em; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.aluguel.pausado_em IS 'Momento da pausa. Enquanto pausado, a contagem de dias fica congelada nesta data.';


--
-- Name: COLUMN aluguel.cliente_nome; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.aluguel.cliente_nome IS 'Cliente avulso. Preenchido so quando cliente_id e nulo; nunca vira vinculo com o cadastro.';


--
-- Name: COLUMN aluguel.usuario_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.aluguel.usuario_id IS 'Usuario do sistema que recebeu o aluguel. Exclusivo com cliente_id e com o cliente avulso.';


--
-- Name: aluguel_checklist; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.aluguel_checklist (
    id bigint NOT NULL,
    aluguel_id bigint NOT NULL,
    tipo text NOT NULL,
