--
-- Name: chat_conversa; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.chat_conversa (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo text DEFAULT 'DIRECT'::text NOT NULL,
    direct_key text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    last_message_at timestamp with time zone,
    CONSTRAINT chat_conversa_direct_key_check CHECK (((direct_key ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) AND (split_part(direct_key, ':'::text, 1) < split_part(direct_key, ':'::text, 2)))),
    CONSTRAINT chat_conversa_tipo_check CHECK ((tipo = 'DIRECT'::text))
);


--
-- Name: TABLE chat_conversa; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.chat_conversa IS 'Conversas do chat interno. Na fase 1 somente conversas DIRECT sao permitidas.';


--
-- Name: COLUMN chat_conversa.direct_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.chat_conversa.direct_key IS 'Chave deterministica menorUsuarioId:maiorUsuarioId, calculada no servidor.';


--
-- Name: chat_mensagem; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.chat_mensagem (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversa_id uuid NOT NULL,
    remetente_id uuid NOT NULL,
    conteudo text NOT NULL,
    client_message_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    tipo text DEFAULT 'TEXT'::text NOT NULL,
    reply_to_message_id uuid,
    reply_snapshot_tipo text,
    reply_snapshot_conteudo text,
    reply_snapshot_remetente_nome text,
    editada_em timestamp with time zone,
    excluida_para_todos_em timestamp with time zone,
    excluida_para_todos_por uuid,
    audio_path text,
    audio_mime text,
    audio_bytes integer,
    audio_duracao_ms integer,
    CONSTRAINT chat_mensagem_audio_check CHECK (
CASE
    WHEN ((tipo = 'VOICE'::text) AND (excluida_para_todos_em IS NULL)) THEN ((audio_path IS NOT NULL) AND (btrim(audio_path) <> ''::text) AND (audio_mime IS NOT NULL) AND ((audio_bytes >= 1) AND (audio_bytes <= 10485760)) AND ((audio_duracao_ms >= 1) AND (audio_duracao_ms <= 300000)))
    WHEN (tipo = 'TEXT'::text) THEN ((audio_path IS NULL) AND (audio_mime IS NULL) AND (audio_bytes IS NULL) AND (audio_duracao_ms IS NULL))
    ELSE true
END),
    CONSTRAINT chat_mensagem_conteudo_por_tipo_check CHECK (
CASE
    WHEN (excluida_para_todos_em IS NOT NULL) THEN (length(conteudo) = 0)
    WHEN (tipo = 'TEXT'::text) THEN ((length(btrim(conteudo)) >= 1) AND (length(btrim(conteudo)) <= 5000))
    WHEN (tipo = 'VOICE'::text) THEN (length(conteudo) = 0)
    ELSE false
END),
    CONSTRAINT chat_mensagem_exclusao_check CHECK (((excluida_para_todos_em IS NULL) = (excluida_para_todos_por IS NULL))),
    CONSTRAINT chat_mensagem_reply_snapshot_check CHECK (((reply_snapshot_tipo IS NULL) OR (reply_snapshot_tipo = ANY (ARRAY['TEXT'::text, 'VOICE'::text])))),
    CONSTRAINT chat_mensagem_tipo_check CHECK ((tipo = ANY (ARRAY['TEXT'::text, 'VOICE'::text])))
);


--
-- Name: COLUMN chat_mensagem.client_message_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.chat_mensagem.client_message_id IS 'UUID criado no navegador e preservado nas tentativas para garantir idempotencia.';


--
-- Name: COLUMN chat_mensagem.tipo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.chat_mensagem.tipo IS 'TEXT ou VOICE. Mensagens anteriores a fase 2 recebem TEXT pelo default.';


--
-- Name: COLUMN chat_mensagem.reply_snapshot_conteudo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.chat_mensagem.reply_snapshot_conteudo IS 'Recorte historico do conteudo citado; preserva a resposta apos edicao ou exclusao do original.';


--
-- Name: COLUMN chat_mensagem.audio_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.chat_mensagem.audio_path IS 'Caminho no bucket privado chat_audio. Nunca e devolvido ao navegador.';


--
-- Name: chat_mensagem_edicao; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.chat_mensagem_edicao (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
