    signatario_documento text NOT NULL,
    signatario_qualidade text NOT NULL,
    qualidade_outro text,
    declaracao text NOT NULL,
    declaracao_hash text NOT NULL,
    metodo text DEFAULT 'PRESENCIAL_DESENHADA'::text NOT NULL,
    assinatura_path text NOT NULL,
    assinatura_hash text NOT NULL,
    assinatura_vinculo_hash text NOT NULL,
    snapshot_hash text NOT NULL,
    operador_usuario_id uuid,
    request_ip inet,
    user_agent text,
    assinado_em timestamp with time zone NOT NULL,
    convite_assinatura_id bigint,
    CONSTRAINT checklist_documento_assinatura_assinatura_hash_check CHECK ((assinatura_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT checklist_documento_assinatura_assinatura_vinculo_hash_check CHECK ((assinatura_vinculo_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT checklist_documento_assinatura_convite_metodo_check CHECK ((((metodo = 'PRESENCIAL_DESENHADA'::text) AND (convite_assinatura_id IS NULL)) OR ((metodo = 'REMOTA_DESENHADA'::text) AND (convite_assinatura_id IS NOT NULL)))),
    CONSTRAINT checklist_documento_assinatura_declaracao_hash_check CHECK ((declaracao_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT checklist_documento_assinatura_metodo_check CHECK ((metodo = ANY (ARRAY['PRESENCIAL_DESENHADA'::text, 'REMOTA_DESENHADA'::text]))),
    CONSTRAINT checklist_documento_assinatura_outro_check CHECK (((signatario_qualidade <> 'OUTRO'::text) OR (NULLIF(btrim(qualidade_outro), ''::text) IS NOT NULL))),
    CONSTRAINT checklist_documento_assinatura_signatario_documento_check CHECK ((signatario_documento ~ '^([0-9]{11}|[0-9]{14})$'::text)),
    CONSTRAINT checklist_documento_assinatura_signatario_qualidade_check CHECK ((signatario_qualidade = ANY (ARRAY['CLIENTE'::text, 'PROPRIETARIO'::text, 'RECEBEDOR'::text, 'OUTRO'::text]))),
    CONSTRAINT checklist_documento_assinatura_snapshot_hash_check CHECK ((snapshot_hash ~ '^[0-9a-f]{64}$'::text))
);


