--
-- Name: classificacoes_resultado; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.classificacoes_resultado (
    id integer NOT NULL,
    codigo text NOT NULL,
    nome text NOT NULL,
    descricao text NOT NULL,
    familia text NOT NULL,
    tratamento text NOT NULL,
    naturezas text[] NOT NULL,
    papel_dre text,
    motivo_exclusao text,
    versao_catalogo integer DEFAULT 1 NOT NULL,
    observacao text,
    ativo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT classificacoes_resultado_coerencia_check CHECK ((((tratamento = 'RESULTADO'::text) AND (papel_dre IS NOT NULL) AND (motivo_exclusao IS NULL)) OR ((tratamento = 'PATRIMONIAL'::text) AND (papel_dre IS NULL) AND (motivo_exclusao IS NOT NULL)))),
    CONSTRAINT classificacoes_resultado_familia_check CHECK ((familia = ANY (ARRAY['RECEITA'::text, 'DEDUCAO'::text, 'CUSTO'::text, 'DESPESA'::text, 'FINANCEIRO'::text, 'OUTROS_RESULTADOS'::text, 'TRIBUTO_LUCRO'::text, 'PATRIMONIAL'::text]))),
    CONSTRAINT classificacoes_resultado_natureza_dupla_check CHECK (((array_length(naturezas, 1) = 1) OR (tratamento = 'PATRIMONIAL'::text))),
    CONSTRAINT classificacoes_resultado_naturezas_check CHECK (((array_length(naturezas, 1) > 0) AND (naturezas <@ ARRAY['RECEITA'::text, 'DESPESA'::text]))),
    CONSTRAINT classificacoes_resultado_papel_check CHECK (((papel_dre IS NULL) OR (papel_dre = ANY (ARRAY['RECEITA'::text, 'DEDUCAO'::text, 'CUSTO'::text, 'DESPESA'::text])))),
    CONSTRAINT classificacoes_resultado_tratamento_check CHECK ((tratamento = ANY (ARRAY['RESULTADO'::text, 'PATRIMONIAL'::text])))
);


--
-- Name: TABLE classificacoes_resultado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.classificacoes_resultado IS 'Significado financeiro comum aos bancos. `codigo` e a identidade estavel; nome e id sao locais. Nao guarda formula da DRE: a apresentacao continua em dre_template/dre_linha.';


--
-- Name: COLUMN classificacoes_resultado.naturezas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.classificacoes_resultado.naturezas IS 'Natureza de caixa aceita (RECEITA/DESPESA). Duas naturezas so no tratamento patrimonial.';


--
-- Name: COLUMN classificacoes_resultado.papel_dre; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.classificacoes_resultado.papel_dre IS 'Papel na DRE: RECEITA, DEDUCAO, CUSTO ou DESPESA. Diferente da natureza de caixa.';


--
-- Name: COLUMN classificacoes_resultado.motivo_exclusao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.classificacoes_resultado.motivo_exclusao IS 'Por que o valor nao compoe resultado. Obrigatorio no patrimonial; proibido no resultado.';


