--

CREATE TABLE public.cliente (
    id integer NOT NULL,
    tipopessoa public.enum_tipopessoa NOT NULL,
    cpfcnpj character varying NOT NULL,
    nomerazaosocial character varying NOT NULL,
    email character varying,
    telefone character varying,
    endereco character varying,
    cidade character varying,
    estado character varying,
    cep character varying,
    inscricaoestadual character varying,
    inscricaomunicipal character varying,
    codigomunicipio character varying,
    createdat timestamp without time zone DEFAULT now(),
    updatedat timestamp without time zone DEFAULT now(),
    status public.enum_status_cliente DEFAULT 'ATIVO'::public.enum_status_cliente,
    endereconumero text,
    enderecocomplemento text,
    bairro text,
    created_by uuid,
    updated_by uuid,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    rank public.cliente_rank,
    ranked_by uuid,
    ranked_at timestamp with time zone,
    user_id uuid,
    foto_url text,
    ind_ie_dest smallint,
    saldo_credito numeric(14,2) DEFAULT 0 NOT NULL,
    CONSTRAINT cliente_email_formato_chk CHECK (((email)::text ~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$'::text)),
    CONSTRAINT cliente_ind_ie_dest_check CHECK (((ind_ie_dest IS NULL) OR (ind_ie_dest = ANY (ARRAY[1, 2, 9])))),
    CONSTRAINT cliente_juridica_cidade_required CHECK (((tipopessoa = 'FISICA'::public.enum_tipopessoa) OR (cidade IS NOT NULL))),
    CONSTRAINT cliente_juridica_estado_required CHECK (((tipopessoa = 'FISICA'::public.enum_tipopessoa) OR (estado IS NOT NULL))),
    CONSTRAINT cliente_juridica_telefone_required CHECK (((tipopessoa = 'FISICA'::public.enum_tipopessoa) OR (telefone IS NOT NULL)))
);


--
-- Name: COLUMN cliente.ind_ie_dest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cliente.ind_ie_dest IS 'indIEDest da NF-e: 1 contribuinte do ICMS, 2 contribuinte isento de inscricao, 9 nao contribuinte. NULL = ainda nao classificado.';


--
-- Name: COLUMN cliente.saldo_credito; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.cliente.saldo_credito IS 'Crédito disponível do cliente. Mantida pelo gatilho cliente_saldo_movimento_trg a partir de cliente_saldo_movimento; não escrever à mão.';


