    emissao_nf_vendas_nao_pagas boolean DEFAULT false NOT NULL,
    agendamento_intervalo_minutos integer DEFAULT 60 NOT NULL,
    agendamento_hora_inicio time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    agendamento_hora_fim time without time zone DEFAULT '18:00:00'::time without time zone NOT NULL,
    agendamento_dias_trabalho integer[] DEFAULT ARRAY[1, 2, 3, 4, 5] NOT NULL,
    impressao_cor_primaria text DEFAULT '#2563eb'::text NOT NULL,
    impressao_cor_secundaria text DEFAULT '#0891b2'::text NOT NULL,
    modo_baixa_estoque_os text DEFAULT 'ORCAMENTO'::text NOT NULL,
    produto_preco_medio_compra_obrigatorio boolean DEFAULT false NOT NULL,
    habilitar_edicao_transacoes boolean DEFAULT false NOT NULL,
    permitir_produto_avulso_os boolean DEFAULT false NOT NULL,
    setor_padrao_os_id integer,
    produto_ncm_obrigatorio boolean DEFAULT false NOT NULL,
    impressao_cor_texto text DEFAULT '#ffffff'::text NOT NULL,
    destaque_os_por_status jsonb DEFAULT '{}'::jsonb NOT NULL,
    habilitar_faturamento_os boolean DEFAULT false NOT NULL,
    emissao_nf_status_os public.enum_status_os[] DEFAULT ARRAY['PAGAMENTO'::public.enum_status_os, 'FATURAMENTO'::public.enum_status_os, 'CONCLUIDO'::public.enum_status_os] NOT NULL,
    CONSTRAINT config_geral_agendamento_dias_chk CHECK (((array_length(agendamento_dias_trabalho, 1) >= 1) AND (agendamento_dias_trabalho <@ ARRAY[0, 1, 2, 3, 4, 5, 6]))),
    CONSTRAINT config_geral_agendamento_horario_chk CHECK ((agendamento_hora_fim > agendamento_hora_inicio)),
    CONSTRAINT config_geral_agendamento_intervalo_chk CHECK ((agendamento_intervalo_minutos = ANY (ARRAY[15, 30, 45, 60, 90, 120, 180, 240]))),
    CONSTRAINT config_geral_destaque_os_por_status_obj_chk CHECK ((jsonb_typeof(destaque_os_por_status) = 'object'::text)),
    CONSTRAINT config_geral_emissao_nf_status_os_chk CHECK (((cardinality(emissao_nf_status_os) >= 1) AND (NOT ('CANCELADO'::public.enum_status_os = ANY (emissao_nf_status_os))))),
    CONSTRAINT config_geral_impressao_cor_primaria_chk CHECK ((impressao_cor_primaria ~ '^#[0-9A-Fa-f]{6}$'::text)),
    CONSTRAINT config_geral_impressao_cor_secundaria_chk CHECK ((impressao_cor_secundaria ~ '^#[0-9A-Fa-f]{6}$'::text)),
    CONSTRAINT config_geral_impressao_cor_texto_chk CHECK ((impressao_cor_texto ~ '^#[0-9A-Fa-f]{6}$'::text)),
    CONSTRAINT config_geral_modo_baixa_estoque_os_chk CHECK ((modo_baixa_estoque_os = ANY (ARRAY['ORCAMENTO'::text, 'EXECUCAO'::text])))
);


