    classificacao_resultado_id integer,
    CONSTRAINT dre_mapeamento_classificacao_coerencia_check CHECK ((((origem_tipo = 'CLASSIFICACAO_RESULTADO'::text) AND (classificacao_resultado_id IS NOT NULL) AND (origem_id IS NULL) AND (origem_valor IS NULL)) OR ((origem_tipo = 'EVENTO_ORIGEM'::text) AND (origem_valor IS NOT NULL)) OR ((origem_tipo = ANY (ARRAY['PLANO_CONTA'::text, 'PLANO_GRUPO'::text, 'CATEGORIA_TRANSACAO'::text])) AND (classificacao_resultado_id IS NULL)))),
    CONSTRAINT dre_mapeamento_destino_check CHECK ((((linha_id IS NOT NULL) AND (NOT exclui_do_resultado)) OR ((linha_id IS NULL) AND exclui_do_resultado))),
    CONSTRAINT dre_mapeamento_origem_check CHECK ((origem_tipo = ANY (ARRAY['PLANO_CONTA'::text, 'PLANO_GRUPO'::text, 'CATEGORIA_TRANSACAO'::text, 'EVENTO_ORIGEM'::text, 'CLASSIFICACAO_RESULTADO'::text]))),
    CONSTRAINT dre_mapeamento_percentual_check CHECK (((percentual > (0)::numeric) AND (percentual <= (100)::numeric))),
    CONSTRAINT dre_mapeamento_vigencia_check CHECK (((vigencia_fim IS NULL) OR (vigencia_inicio IS NULL) OR (vigencia_fim >= vigencia_inicio)))
);


