    CONSTRAINT entrada_data_fiscal_sugestao_origem_chk CHECK (((data_entrada_fiscal_sugestao_origem IS NULL) OR (data_entrada_fiscal_sugestao_origem = ANY (ARRAY['XML_EMISSAO'::text, 'CRIACAO_ERP'::text, 'EFD_ANTERIOR'::text, 'MANUAL'::text])))),
