-- Name: entrada_fiscal_personalizada; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.entrada_fiscal_personalizada (
    id bigint NOT NULL,
    documento_id bigint NOT NULL,
    destino text NOT NULL,
    entrada_id bigint,
    usoconsumo_entrada_id bigint,
    itens_originais jsonb NOT NULL,
    custo_total_estoque numeric(14,2) NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    modalidade text DEFAULT 'INTEGRAL'::text NOT NULL,
    produto_id integer,
    usoconsumo_item_id integer,
    quantidade_personalizada integer,
    custo_unitario numeric(14,4),
    valor_fiscal_documento numeric(14,2),
    item_destino_snapshot jsonb,
    CONSTRAINT entrada_fiscal_personalizada_custo_total_estoque_check CHECK ((custo_total_estoque >= (0)::numeric)),
    CONSTRAINT entrada_fiscal_personalizada_destino_check CHECK ((destino = ANY (ARRAY['ESTOQUE'::text, 'USOCONSUMO'::text, 'GERAL'::text]))),
    CONSTRAINT entrada_fiscal_personalizada_destino_item_check CHECK ((((produto_id IS NULL) AND (usoconsumo_item_id IS NULL)) OR ((destino = 'ESTOQUE'::text) AND (produto_id IS NOT NULL) AND (usoconsumo_item_id IS NULL)) OR ((destino = ANY (ARRAY['USOCONSUMO'::text, 'GERAL'::text])) AND (produto_id IS NULL) AND (usoconsumo_item_id IS NOT NULL)))),
    CONSTRAINT entrada_fiscal_personalizada_itens_check CHECK (((jsonb_typeof(itens_originais) = 'array'::text) AND (jsonb_array_length(itens_originais) > 0))),
    CONSTRAINT entrada_fiscal_personalizada_modalidade_check CHECK ((modalidade = ANY (ARRAY['INTEGRAL'::text, 'HIBRIDA'::text]))),
    CONSTRAINT entrada_fiscal_personalizada_quantidade_check CHECK (((quantidade_personalizada IS NULL) OR (quantidade_personalizada > 0))),
    CONSTRAINT entrada_fiscal_personalizada_snapshot_check CHECK (((item_destino_snapshot IS NULL) OR (jsonb_typeof(item_destino_snapshot) = 'object'::text))),
    CONSTRAINT entrada_fiscal_personalizada_vinculo_check CHECK ((((destino = 'ESTOQUE'::text) AND (entrada_id IS NOT NULL) AND (usoconsumo_entrada_id IS NULL)) OR ((destino = ANY (ARRAY['USOCONSUMO'::text, 'GERAL'::text])) AND (entrada_id IS NULL) AND (usoconsumo_entrada_id IS NOT NULL))))
);


--
-- Name: TABLE entrada_fiscal_personalizada; Type: COMMENT; Schema: public; Owner: -
