-- Name: estoque_movimento; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.estoque_movimento (
    id bigint NOT NULL,
    produto_id integer NOT NULL,
    sentido text NOT NULL,
    origem text NOT NULL,
    acao text NOT NULL,
    quantidade integer NOT NULL,
    saldo_anterior integer,
    saldo_resultante integer,
    entrada_id bigint,
    saida_id bigint,
    venda_id integer,
    ordemservicoid integer,
    documento_label text,
    observacao text,
    reconstruido boolean DEFAULT false NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT estoque_movimento_acao_check CHECK ((acao = ANY (ARRAY['REGISTRO'::text, 'ESTORNO'::text]))),
    CONSTRAINT estoque_movimento_origem_check CHECK ((origem = ANY (ARRAY['ENTRADA'::text, 'SAIDA_MANUAL'::text, 'VENDA'::text, 'ORDEM_SERVICO'::text, 'NAO_IDENTIFICADA'::text]))),
    CONSTRAINT estoque_movimento_quantidade_check CHECK ((quantidade > 0)),
    CONSTRAINT estoque_movimento_sentido_check CHECK ((sentido = ANY (ARRAY['ENTRADA'::text, 'SAIDA'::text])))
);


--
-- Name: estoque_conferencia; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.estoque_conferencia AS
 SELECT p.id AS produto_id,
    p.titulo,
    p.estoque AS saldo_atual,
    COALESCE(sum(
        CASE
            WHEN (m.sentido = 'ENTRADA'::text) THEN m.quantidade
            ELSE (- m.quantidade)
        END), (0)::bigint) AS saldo_pelo_razao,
    COALESCE(sum(
        CASE
            WHEN m.reconstruido THEN 0
            WHEN (m.sentido = 'ENTRADA'::text) THEN m.quantidade
            ELSE (- m.quantidade)
        END), (0)::bigint) AS saldo_pelo_razao_ao_vivo,
    count(m.id) FILTER (WHERE m.reconstruido) AS movimentos_reconstruidos,
    count(m.id) FILTER (WHERE (m.origem = 'NAO_IDENTIFICADA'::text)) AS movimentos_sem_origem
   FROM (public.produto p
     LEFT JOIN public.estoque_movimento m ON ((m.produto_id = p.id)))
  WHERE (p.is_deleted = false)
  GROUP BY p.id, p.titulo, p.estoque;


