    setorid integer,
    perfilid integer,
    createdat timestamp without time zone DEFAULT now(),
    updatedat timestamp without time zone DEFAULT now(),
    ativo boolean DEFAULT true NOT NULL,
    salario numeric(12,2),
    comissao_percent numeric(5,2),
    data_admissao date,
    data_demissao date,
    is_root boolean DEFAULT false NOT NULL,
    comissao_venda_percent numeric(5,2),
    created_by uuid,
    updated_by uuid,
    username character varying(30),
    foto_url text,
    foto_path text,
    comissao_criacao_servico_percent numeric(5,2),
    comissao_criacao_produto_percent numeric(5,2),
    comissao_criacao_somente_comissionaveis boolean DEFAULT false NOT NULL,
    CONSTRAINT usuario_username_formato_check CHECK (((username IS NULL) OR (((username)::text = lower(btrim((username)::text))) AND ((username)::text ~ '^[a-z0-9._-]{3,30}$'::text))))
);


