--
-- Name: estoque_movimento_historico; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.estoque_movimento_historico AS
 SELECT m.id,
    m.created_at,
    m.produto_id,
    m.sentido,
    m.origem,
    m.acao,
    m.quantidade,
    m.saldo_anterior,
    m.saldo_resultante,
    m.entrada_id,
    m.saida_id,
    m.venda_id,
    m.ordemservicoid,
    m.documento_label,
    m.observacao,
    m.reconstruido,
    m.created_by,
    p.titulo AS produto_titulo,
    p.referencia AS produto_referencia,
    p.unidade AS produto_unidade,
    e.status AS entrada_status,
    e.origem AS entrada_origem,
    e.fiscal AS entrada_fiscal,
    e.numero_nota AS entrada_numero_nota,
    e.tipo AS entrada_tipo,
    te.nome AS entrada_tipo_nome,
    e.observacao AS entrada_observacao,
    f.nomerazaosocial AS fornecedor_nome,
    s.status AS saida_status,
    s.motivo AS saida_motivo,
    tms.nome AS saida_motivo_nome,
    s.observacao AS saida_observacao,
    s.ordemservicoid AS saida_ordemservicoid,
    u.nome AS criador_nome,
        CASE
            WHEN (m.acao = 'ESTORNO'::text) THEN 'CANCELADA'::text
            WHEN (COALESCE((e.status)::text, s.status) = 'CANCELADA'::text) THEN 'CANCELADA'::text
            ELSE 'CONFIRMADA'::text
        END AS status,
    (COALESCE(e.fiscal, false) OR (NULLIF(btrim(COALESCE(e.numero_nota, ''::text)), ''::text) IS NOT NULL) OR COALESCE((e.origem = ANY (ARRAY['MANUAL_COM_NF'::text, 'XML'::text, 'NFE_TERCEIRO'::text])), false)) AS fiscal,
    lower(concat_ws(' '::text, (m.id)::text, m.documento_label, m.observacao, p.titulo, p.referencia, e.numero_nota, f.nomerazaosocial, replace(COALESCE(e.tipo, ''::text), '_'::text, ' '::text), te.nome, e.observacao, replace(COALESCE(s.motivo, ''::text), '_'::text, ' '::text), tms.nome, s.observacao, (s.ordemservicoid)::text,
        CASE
            WHEN (s.ordemservicoid IS NOT NULL) THEN 'os ordem de servico'::text
            ELSE NULL::text
        END, u.nome, (m.venda_id)::text, (m.ordemservicoid)::text, replace(m.origem, '_'::text, ' '::text),
        CASE
            WHEN (m.acao = 'ESTORNO'::text) THEN 'estorno'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((m.acao = 'ESTORNO'::text) OR (COALESCE((e.status)::text, s.status) = 'CANCELADA'::text)) THEN 'cancelada'::text
            ELSE 'confirmada'::text
        END,
        CASE
            WHEN (COALESCE(e.fiscal, false) OR (e.numero_nota IS NOT NULL)) THEN 'nf-e nota fiscal'::text
            ELSE NULL::text
        END)) AS busca
   FROM (((((((public.estoque_movimento m
     LEFT JOIN public.produto p ON ((p.id = m.produto_id)))
     LEFT JOIN public.entrada e ON ((e.id = m.entrada_id)))
     LEFT JOIN public.tipos_entrada te ON ((te.codigo = e.tipo)))
     LEFT JOIN public.fornecedor f ON ((f.id = e.fornecedorid)))
     LEFT JOIN public.estoque_saida s ON ((s.id = m.saida_id)))
     LEFT JOIN public.tipos_motivo_saida tms ON ((tms.codigo = s.motivo)))
     LEFT JOIN public.usuario u ON ((u.id = m.created_by)));


--
-- Name: VIEW estoque_movimento_historico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.estoque_movimento_historico IS 'Razao de estoque de produtos achatado para a tela de historico: status derivado, marca fiscal, motivo da entrada e da saida, OS que consumiu o item e texto de busca.';


--
-- Name: COLUMN estoque_movimento_historico.saida_ordemservicoid; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.estoque_movimento_historico.saida_ordemservicoid IS 'OS que registrou o consumo. Preenchida, a saida so pode ser cancelada pela ordem de servico.';


--
-- Name: estoque_movimento_financeiro_historico; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.estoque_movimento_financeiro_historico AS
 SELECT id,
    created_at,
    produto_id,
    sentido,
    origem,
    acao,
    quantidade,
    saldo_anterior,
    saldo_resultante,
    entrada_id,
    saida_id,
    venda_id,
    ordemservicoid,
    documento_label,
    observacao,
    reconstruido,
    created_by,
    produto_titulo,
    produto_referencia,
    produto_unidade,
    entrada_status,
    entrada_origem,
    entrada_fiscal,
    entrada_numero_nota,
    entrada_tipo,
    entrada_tipo_nome,
    entrada_observacao,
    fornecedor_nome,
    saida_status,
    saida_motivo,
    saida_motivo_nome,
    saida_observacao,
    saida_ordemservicoid,
    criador_nome,
    status,
    fiscal,
    busca,
        CASE
            WHEN ((origem = 'ENTRADA'::text) AND (acao = 'REGISTRO'::text) AND (entrada_id IS NOT NULL)) THEN (EXISTS ( SELECT 1
               FROM public.transacao transacao
              WHERE ((transacao.entrada_id = historico.entrada_id) AND (transacao.is_deleted = false))))
            ELSE NULL::boolean
        END AS financeiro_lancado
   FROM public.estoque_movimento_historico historico;


--
-- Name: VIEW estoque_movimento_financeiro_historico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.estoque_movimento_financeiro_historico IS 'Historico de produtos acrescido do indicador de lancamento financeiro ativo da entrada.';


