CREATE TABLE public.estoque_saida_fiscal (
    saida_id bigint NOT NULL,
    operacao_fiscal_codigo text NOT NULL,
    natureza_operacao text NOT NULL,
    finalidade text NOT NULL,
    documento_referenciado_obrigatorio boolean DEFAULT false NOT NULL,
