    CONSTRAINT eventos_financeiros_origem_check CHECK ((origem = ANY (ARRAY['PRODUTO'::text, 'SERVICO'::text, 'COMISSAO'::text, 'AVULSO'::text, 'DESCONTO'::text, 'FRETE'::text, 'ENTRADA_FISCAL'::text, 'CONSUMO'::text]))),
    CONSTRAINT eventos_financeiros_source_type_check CHECK (((source_type IS NULL) OR (source_type = ANY (ARRAY['ORDEM_SERVICO'::text, 'VENDA'::text, 'TRANSACAO'::text, 'MANUAL'::text, 'ENTRADA'::text, 'USOCONSUMO_ENTRADA'::text])))),
    CONSTRAINT eventos_financeiros_status_check CHECK ((status = ANY (ARRAY['ATIVO'::text, 'CANCELADO'::text, 'CONVERTIDO'::text]))),
