    deleted_by uuid,
    is_deleted boolean DEFAULT false NOT NULL,
    motivo_cancelamento text,
    motivo_sem_cobranca text,
    observacoes_fiscais text,
    subtotal numeric DEFAULT 0 NOT NULL,
    desconto_tipo public.enum_tipo_desconto_venda,
    desconto numeric DEFAULT 0 NOT NULL,
    acrescimo_financeiro_tipo public.enum_tipo_desconto_venda,
    acrescimo_financeiro_valor numeric(14,2) DEFAULT 0 NOT NULL,
    equipamento_nome text,
    equipamento_patrimonio text,
    equipamento_ano integer,
    equipamento_horimetro numeric(12,1),
    forma_pagamento public.metodo_pagamento,
    garantia text,
    parcelas_pagamento integer,
    descricao_financeiro text,
    pagamentos_previstos jsonb,
    pagamento_concluido_em timestamp with time zone,
    destacada boolean DEFAULT false NOT NULL,
    destaque_motivo character varying(200),
    destacada_por uuid,
    destacada_em timestamp with time zone,
    valor_frete numeric(14,2) DEFAULT 0 NOT NULL,
    orcamentoid bigint,
    destaque_cor character varying(20) DEFAULT 'vermelho'::character varying NOT NULL,
    migracao_referencia text,
    veiculo_snapshot jsonb,
    finalizado_em timestamp with time zone,
    cliente_snapshot jsonb,
    CONSTRAINT ordemservico_acrescimo_financeiro_valor_check CHECK (((acrescimo_financeiro_valor >= (0)::numeric) AND ((acrescimo_financeiro_tipo IS DISTINCT FROM 'PORCENTAGEM'::public.enum_tipo_desconto_venda) OR (acrescimo_financeiro_valor <= (100)::numeric)))),
    CONSTRAINT ordemservico_alvo_consistente CHECK ((((alvo_tipo = 'VEICULO'::public.enum_alvo_reparo) AND (pecaid IS NULL) AND (equipamento_nome IS NULL)) OR ((alvo_tipo = 'PECA'::public.enum_alvo_reparo) AND (pecaid IS NOT NULL) AND (veiculoid IS NULL) AND (equipamento_nome IS NULL)) OR ((alvo_tipo = 'EQUIPAMENTO'::public.enum_alvo_reparo) AND (veiculoid IS NULL) AND (pecaid IS NULL) AND (equipamento_nome IS NOT NULL) AND (btrim(equipamento_nome) <> ''::text)))),
    CONSTRAINT ordemservico_cliente_snapshot_objeto CHECK (((cliente_snapshot IS NULL) OR (jsonb_typeof(cliente_snapshot) = 'object'::text))),
    CONSTRAINT ordemservico_destaque_consistente_chk CHECK ((((destacada = true) AND (destacada_por IS NOT NULL) AND (destacada_em IS NOT NULL)) OR ((destacada = false) AND (destaque_motivo IS NULL) AND (destacada_por IS NULL) AND (destacada_em IS NULL)))),
    CONSTRAINT ordemservico_destaque_cor_chk CHECK (((destaque_cor)::text = ANY ((ARRAY['vermelho'::character varying, 'amarelo'::character varying])::text[]))),
    CONSTRAINT ordemservico_equipamento_ano_valido CHECK (((equipamento_ano IS NULL) OR ((equipamento_ano >= 1900) AND (equipamento_ano <= 3000)))),
    CONSTRAINT ordemservico_equipamento_horimetro_valido CHECK (((equipamento_horimetro IS NULL) OR (equipamento_horimetro >= (0)::numeric))),
    CONSTRAINT ordemservico_equipamento_nome_nao_vazio CHECK (((equipamento_nome IS NULL) OR (btrim(equipamento_nome) <> ''::text))),
    CONSTRAINT ordemservico_garantia_nao_vazia CHECK (((garantia IS NULL) OR (btrim(garantia) <> ''::text))),
    CONSTRAINT ordemservico_migracao_historica_consistente CHECK (((migracao_referencia IS NULL) OR (((status)::text = 'CONCLUIDO'::text) AND ((clienteid IS NOT NULL) OR ((cliente_snapshot IS NOT NULL) AND (jsonb_typeof(cliente_snapshot) = 'object'::text) AND (COALESCE(btrim((cliente_snapshot ->> 'nome'::text)), ''::text) <> ''::text))) AND (veiculo_snapshot IS NOT NULL) AND (jsonb_typeof(veiculo_snapshot) = 'object'::text) AND (COALESCE(btrim((veiculo_snapshot ->> 'placa'::text)), ''::text) <> ''::text) AND (COALESCE(subtotal, (0)::numeric) >= (0)::numeric) AND (COALESCE(orcamentototal, (0)::numeric) >= (0)::numeric) AND (COALESCE(valor_frete, (0)::numeric) = (0)::numeric) AND (COALESCE(acrescimo_financeiro_valor, (0)::numeric) = (0)::numeric) AND (((desconto_tipo IS NULL) AND (COALESCE(desconto, (0)::numeric) = (0)::numeric)) OR (((desconto_tipo)::text = 'FIXO'::text) AND (COALESCE(desconto, (0)::numeric) >= (0)::numeric) AND (COALESCE(desconto, (0)::numeric) <= COALESCE(subtotal, (0)::numeric)))) AND (round(COALESCE(orcamentototal, (0)::numeric), 2) = round((COALESCE(subtotal, (0)::numeric) - COALESCE(desconto, (0)::numeric)), 2)) AND (forma_pagamento IS NULL) AND (parcelas_pagamento IS NULL) AND (pagamentos_previstos IS NULL) AND (dataentrada IS NOT NULL) AND (datasaida IS NOT NULL) AND (pagamento_concluido_em IS NOT NULL) AND (finalizado_em IS NOT NULL) AND (datasaida = dataentrada) AND (pagamento_concluido_em = dataentrada) AND (finalizado_em = dataentrada)))),
    CONSTRAINT ordemservico_migracao_referencia_nao_vazia CHECK (((migracao_referencia IS NULL) OR (btrim(migracao_referencia) <> ''::text))),
    CONSTRAINT ordemservico_pagamentos_previstos_array CHECK (((pagamentos_previstos IS NULL) OR (jsonb_typeof(pagamentos_previstos) = 'array'::text))),
    CONSTRAINT ordemservico_parcelas_compativel_forma CHECK (((parcelas_pagamento IS NULL) OR (forma_pagamento = ANY (ARRAY['CREDITO'::public.metodo_pagamento, 'BOLETO'::public.metodo_pagamento, 'PROMISSORIA'::public.metodo_pagamento])))),
    CONSTRAINT ordemservico_parcelas_pagamento_valida CHECK (((parcelas_pagamento IS NULL) OR ((parcelas_pagamento >= 1) AND (parcelas_pagamento <= 12)))),
    CONSTRAINT ordemservico_status_finalizado_em_consistente CHECK (((((status)::text = ANY (ARRAY['CONCLUIDO'::text, 'SEM_COBRANCA'::text, 'CANCELADO'::text])) AND (finalizado_em IS NOT NULL)) OR ((COALESCE((status)::text, ''::text) <> ALL (ARRAY['CONCLUIDO'::text, 'SEM_COBRANCA'::text, 'CANCELADO'::text])) AND (finalizado_em IS NULL)))),
    CONSTRAINT ordemservico_valor_frete_check CHECK ((valor_frete >= (0)::numeric)),
    CONSTRAINT ordemservico_veiculo_snapshot_objeto CHECK (((veiculo_snapshot IS NULL) OR (jsonb_typeof(veiculo_snapshot) = 'object'::text)))
);


