CREATE TABLE public.venda (
    id integer NOT NULL,
    clienteid integer NOT NULL,
    status public.enum_status_venda NOT NULL,
    valortotal numeric NOT NULL,
    datavenda timestamp with time zone,
    createdat timestamp with time zone,
    updatedat timestamp with time zone,
    created_by uuid,
    desconto_tipo public.enum_tipo_desconto_venda,
    desconto_valor numeric,
    sub_total numeric NOT NULL,
    canal public.enum_canal_venda DEFAULT 'PDV'::public.enum_canal_venda NOT NULL,
    endereco_entrega_snapshot jsonb,
    forma_pagamento text,
    status_entrega public.enum_status_entrega,
    codigo_rastreio text,
    transportadora_rastreio text DEFAULT ''::text,
    ultimo_evento_rastreio text,
    ultimo_evento_rastreio_em timestamp with time zone,
    status_rastreio text,
    eventos_rastreio jsonb,
    rastreio_atualizado_em timestamp with time zone,
    nfe_chave_acesso text,
    danfe_url text,
    observacoes_fiscais text,
    vendedor uuid,
    updated_by uuid,
    comissao_venda_percent_aplicada numeric(5,2),
    observacoes text,
    categoriavendaid integer,
    acrescimo_financeiro_tipo public.enum_tipo_desconto_venda,
    acrescimo_financeiro_valor numeric(14,2) DEFAULT 0 NOT NULL,
    valor_frete numeric(14,2) DEFAULT 0 NOT NULL,
    motivo_cancelamento text,
    cancelada_at timestamp with time zone,
    cancelada_by uuid,
    orcamento_em timestamp with time zone,
    pagamento_em timestamp with time zone,
    baixada_em timestamp with time zone,
    garantia text,
    parcelas_pagamento integer,
    descricao_financeiro text,
    pagamentos_previstos jsonb,
    descricao text,
    statusaprovacao public.enum_status_aprovacao,
    CONSTRAINT venda_acrescimo_financeiro_valor_check CHECK (((acrescimo_financeiro_valor >= (0)::numeric) AND ((acrescimo_financeiro_tipo IS DISTINCT FROM 'PORCENTAGEM'::public.enum_tipo_desconto_venda) OR (acrescimo_financeiro_valor <= (100)::numeric)))),
    CONSTRAINT venda_garantia_nao_vazia CHECK (((garantia IS NULL) OR (btrim(garantia) <> ''::text))),
    CONSTRAINT venda_motivo_cancelamento_check CHECK ((((status)::text <> ALL (ARRAY['CANCELADA'::text, 'CANCELADO'::text])) OR (NULLIF(btrim(motivo_cancelamento), ''::text) IS NOT NULL))),
    CONSTRAINT venda_pagamentos_previstos_array CHECK (((pagamentos_previstos IS NULL) OR (jsonb_typeof(pagamentos_previstos) = 'array'::text))),
    CONSTRAINT venda_parcelas_pagamento_valida CHECK (((parcelas_pagamento IS NULL) OR ((parcelas_pagamento >= 1) AND (parcelas_pagamento <= 12)))),
    CONSTRAINT venda_valor_frete_nonnegative CHECK ((valor_frete >= (0)::numeric))
);


