--
-- Name: eventos_financeiros_fila; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.eventos_financeiros_fila WITH (security_invoker='true') AS
 SELECT e.id,
    e.ordemservicoid,
    e.origem,
    e.natureza,
    e.status,
    e.chave_origem,
    e.descricao,
    e.detalhe,
    e.valor,
    e.data_evento,
    e.produtoid,
    e.servicoid,
    e.usuarioid,
    e.quantidade_snapshot,
    e.valor_unitario_snapshot,
    e.percentual_snapshot,
    e.valor_base_snapshot,
    e.dados_snapshot,
    e.pode_gerar_transacao,
    e.transacaoid,
    e.created_at,
    e.updated_at,
    e.created_by,
    e.source_type,
    e.source_id,
    e.source_item_id,
    e.competencia_em,
    e.natureza_dre,
    e.centro_custo_id,
    e.estorno_de_id,
    e.is_manual,
    e.dre_linha_id,
    e.lancamento_id,
    e.consumo_saida_id,
    e.consumo_usoconsumo_saida_id,
        CASE
            WHEN (o.id IS NOT NULL) THEN 'OS'::text
            ELSE 'VENDA'::text
        END AS documento_tipo,
    COALESCE(o.id, v.id) AS documento_id,
    COALESCE(o.clienteid, v.clienteid) AS cliente_id,
        CASE
            WHEN (o.id IS NOT NULL) THEN jsonb_build_object('id', o.id, 'status', o.status, 'dataentrada', o.dataentrada, 'cliente', jsonb_build_object('id', c.id, 'nomerazaosocial', c.nomerazaosocial))
            ELSE NULL::jsonb
        END AS ordem,
        CASE
            WHEN (v.id IS NOT NULL) THEN jsonb_build_object('id', v.id, 'status', v.status, 'cliente', jsonb_build_object('id', c.id, 'nomerazaosocial', c.nomerazaosocial))
            ELSE NULL::jsonb
        END AS venda
   FROM (((public.eventos_financeiros e
     LEFT JOIN public.ordemservico o ON ((o.id = e.ordemservicoid)))
     LEFT JOIN public.venda v ON (((e.source_type = 'VENDA'::text) AND (e.source_id = v.id) AND ((e.origem = 'COMISSAO'::text) OR (e.is_manual AND (COALESCE(e.chave_origem, ''::text) ~~ 'MANUAL:%'::text))))))
     LEFT JOIN public.cliente c ON ((c.id = COALESCE(o.clienteid, v.clienteid))))
  WHERE (((o.id IS NOT NULL) AND (NOT o.is_deleted)) OR ((e.ordemservicoid IS NULL) AND (v.id IS NOT NULL)));


