--
-- Name: fiscal_difal_regra; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fiscal_difal_regra (
    id bigint NOT NULL,
    uf text NOT NULL,
    tipo_regra text NOT NULL,
    descricao text NOT NULL,
    ncm text,
    ncm_prefixo text,
    cest text,
    aliquota_icms_interna numeric(7,4),
    aliquota_fcp numeric(7,4),
    reducao_base numeric(7,4),
    vigencia_inicio date NOT NULL,
    vigencia_fim date,
    prioridade integer DEFAULT 10 NOT NULL,
    fonte text NOT NULL,
    fonte_url text,
    fundamento_legal text,
    data_fonte date,
    ativo boolean DEFAULT true NOT NULL,
    nota_curadoria text,
    importado_em date,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fiscal_difal_regra_codigos_bem_formados CHECK ((((ncm IS NULL) OR (ncm ~ '^[0-9]{8}$'::text)) AND ((ncm_prefixo IS NULL) OR (ncm_prefixo ~ '^[0-9]{2,8}$'::text)) AND ((cest IS NULL) OR (cest ~ '^[0-9]{7}$'::text)))),
    CONSTRAINT fiscal_difal_regra_determina_algo CHECK (((aliquota_icms_interna IS NOT NULL) OR (aliquota_fcp IS NOT NULL) OR (reducao_base IS NOT NULL))),
    CONSTRAINT fiscal_difal_regra_identificador_coerente CHECK (
CASE tipo_regra
    WHEN 'GERAL'::text THEN ((ncm IS NULL) AND (ncm_prefixo IS NULL) AND (cest IS NULL))
    WHEN 'NCM'::text THEN ((ncm IS NOT NULL) AND (ncm_prefixo IS NULL))
    WHEN 'NCM_PREFIXO'::text THEN ((ncm_prefixo IS NOT NULL) AND (ncm IS NULL))
    WHEN 'CEST'::text THEN ((cest IS NOT NULL) AND (ncm IS NULL))
    WHEN 'NCM_CEST'::text THEN ((ncm IS NOT NULL) AND (cest IS NOT NULL))
    ELSE true
END),
    CONSTRAINT fiscal_difal_regra_percentuais_validos CHECK ((((aliquota_icms_interna IS NULL) OR ((aliquota_icms_interna >= (0)::numeric) AND (aliquota_icms_interna <= (100)::numeric))) AND ((aliquota_fcp IS NULL) OR ((aliquota_fcp >= (0)::numeric) AND (aliquota_fcp <= (100)::numeric))) AND ((reducao_base IS NULL) OR ((reducao_base >= (0)::numeric) AND (reducao_base <= (100)::numeric))))),
    CONSTRAINT fiscal_difal_regra_prioridade_positiva CHECK ((prioridade > 0)),
    CONSTRAINT fiscal_difal_regra_tipo_valido CHECK ((tipo_regra = ANY (ARRAY['GERAL'::text, 'NCM'::text, 'NCM_PREFIXO'::text, 'CEST'::text, 'NCM_CEST'::text, 'BENEFICIO'::text, 'EXCECAO'::text]))),
    CONSTRAINT fiscal_difal_regra_uf_valida CHECK ((uf = ANY (ARRAY['AC'::text, 'AL'::text, 'AM'::text, 'AP'::text, 'BA'::text, 'CE'::text, 'DF'::text, 'ES'::text, 'GO'::text, 'MA'::text, 'MG'::text, 'MS'::text, 'MT'::text, 'PA'::text, 'PB'::text, 'PE'::text, 'PI'::text, 'PR'::text, 'RJ'::text, 'RN'::text, 'RO'::text, 'RR'::text, 'RS'::text, 'SC'::text, 'SE'::text, 'SP'::text, 'TO'::text]))),
    CONSTRAINT fiscal_difal_regra_vigencia_coerente CHECK (((vigencia_fim IS NULL) OR (vigencia_fim >= vigencia_inicio)))
);


--
-- Name: TABLE fiscal_difal_regra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.fiscal_difal_regra IS 'Regras versionadas de DIFAL/FCP por UF de destino. Fonte do grupo ICMSUFDest; ver docs/sefaz/difal-regras.md.';


--
-- Name: COLUMN fiscal_difal_regra.tipo_regra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.tipo_regra IS 'GERAL, NCM, NCM_PREFIXO, CEST, NCM_CEST, BENEFICIO ou EXCECAO. Define a especificidade na disputa entre regras.';


--
-- Name: COLUMN fiscal_difal_regra.aliquota_icms_interna; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.aliquota_icms_interna IS 'pICMSUFDest em percentual. NULL = a fonte não determina a alíquota interna nesta regra.';


--
-- Name: COLUMN fiscal_difal_regra.aliquota_fcp; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.aliquota_fcp IS 'pFCPUFDest em percentual. NULL = não determinado (bloqueia). 0 = a fonte declara que não há FCP.';


--
-- Name: COLUMN fiscal_difal_regra.reducao_base; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.reducao_base IS 'Percentual de redução da base, quando a regra a estabelece. NULL = sem redução determinada pela fonte.';


--
-- Name: COLUMN fiscal_difal_regra.vigencia_inicio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.vigencia_inicio IS 'Primeiro dia em que a regra vale. A emissão usa a regra vigente na data do documento, não a mais recente.';


--
-- Name: COLUMN fiscal_difal_regra.vigencia_fim; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.vigencia_fim IS 'Último dia de vigência, inclusive. NULL = ainda vigente.';


--
-- Name: COLUMN fiscal_difal_regra.prioridade; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.prioridade IS 'Desempate explícito dentro do mesmo tipo_regra. Maior vence; empate com valores diferentes é conflito e bloqueia.';


--
-- Name: COLUMN fiscal_difal_regra.ativo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.ativo IS 'false = carregada para histórico e auditoria, mas fora da resolução automática (fonte ambígua ou divergente).';


--
-- Name: COLUMN fiscal_difal_regra.nota_curadoria; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_difal_regra.nota_curadoria IS 'Por que a regra está como está — em especial por que foi desativada.';


