--

CREATE TABLE public.fiscal_documento_evento (
    id bigint NOT NULL,
    empresa_id integer NOT NULL,
    nfe_id bigint,
    fiscal_dfe_documento_id bigint,
    chave_acesso text NOT NULL,
    tipo_evento text NOT NULL,
    sequencia integer DEFAULT 1 NOT NULL,
    status_evento text,
    protocolo_evento text,
    data_evento_original text,
    data_evento_civil date,
    data_evento_offset text,
    data_evento_instante_utc timestamp with time zone,
    xml_evento text NOT NULL,
    resposta_sefaz text,
    xml_sha256 text NOT NULL,
    resposta_sha256 text,
    origem text DEFAULT 'SEFAZ'::text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fiscal_documento_evento_chave_chk CHECK ((chave_acesso ~ '^[0-9]{44}$'::text)),
    CONSTRAINT fiscal_documento_evento_data_offset_chk CHECK (((data_evento_offset IS NULL) OR (data_evento_offset ~ '^(Z|[+-](0[0-9]|1[0-4]):[0-5][0-9])$'::text))),
    CONSTRAINT fiscal_documento_evento_origem_chk CHECK ((origem = ANY (ARRAY['SEFAZ'::text, 'DISTRIBUICAO_DFE'::text, 'IMPORTACAO_MANUAL'::text]))),
    CONSTRAINT fiscal_documento_evento_origem_documento_chk CHECK ((num_nonnulls(nfe_id, fiscal_dfe_documento_id) = 1)),
    CONSTRAINT fiscal_documento_evento_resposta_hash_chk CHECK (((resposta_sha256 IS NULL) OR (resposta_sha256 ~ '^[a-f0-9]{64}$'::text))),
    CONSTRAINT fiscal_documento_evento_sequencia_chk CHECK ((sequencia > 0)),
    CONSTRAINT fiscal_documento_evento_xml_hash_chk CHECK ((xml_sha256 ~ '^[a-f0-9]{64}$'::text))
);


