--
-- Name: fiscal_ncm; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.fiscal_ncm (
    codigo character(8) NOT NULL,
    descricao text NOT NULL,
    vigencia_inicio date,
    vigencia_fim date,
    ato text,
    fonte text NOT NULL,
    fonte_url text,
    importado_em date,
    criado_em timestamp with time zone DEFAULT now() NOT NULL,
    atualizado_em timestamp with time zone DEFAULT now() NOT NULL,
    caminho text,
    descricao_busca text GENERATED ALWAYS AS (translate(lower(regexp_replace(((descricao || ' '::text) || COALESCE(caminho, ''::text)), '<[^>]*>'::text, ' '::text, 'g'::text)), 'áàâãäéèêëíìîïóòôõöúùûüñçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÑÇ'::text, 'aaaaaeeeeiiiiooooouuuuncAAAAAEEEEIIIIOOOOOUUUUNC'::text)) STORED,
    CONSTRAINT fiscal_ncm_codigo_bem_formado CHECK ((codigo ~ '^[0-9]{8}$'::text)),
    CONSTRAINT fiscal_ncm_vigencia_coerente CHECK (((vigencia_fim IS NULL) OR (vigencia_inicio IS NULL) OR (vigencia_fim >= vigencia_inicio)))
);


--
-- Name: TABLE fiscal_ncm; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.fiscal_ncm IS 'Nomenclatura Comum do Mercosul (8 dígitos), do Portal Único Siscomex. Vazia = validação de existência desligada.';


--
-- Name: COLUMN fiscal_ncm.codigo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_ncm.codigo IS 'NCM com 8 dígitos, sem pontuação.';


--
-- Name: COLUMN fiscal_ncm.vigencia_fim; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_ncm.vigencia_fim IS 'NULL ou 31/12/9999 = ainda vigente.';


--
-- Name: COLUMN fiscal_ncm.ato; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_ncm.ato IS 'Ato que fixou a versão importada (ex.: Resolução Gecex nº 926/2026).';


--
-- Name: COLUMN fiscal_ncm.caminho; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_ncm.caminho IS 'Descrições dos níveis superiores (posição, desdobramentos e item), separadas por " › ". Dá sentido a descrições como "Outros".';


--
-- Name: COLUMN fiscal_ncm.descricao_busca; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.fiscal_ncm.descricao_busca IS 'Descrição e caminho, sem acento, sem HTML e em minúsculas, só para busca. Gerada pelo banco; nunca escrever direto.';


