--
-- Name: nfe; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.nfe (
    id bigint NOT NULL,
    modelo public.enum_modelo_nfe DEFAULT 'NFE'::public.enum_modelo_nfe NOT NULL,
    serie integer NOT NULL,
    numero integer NOT NULL,
    chave_acesso character(44) NOT NULL,
    ambiente public.enum_ambiente_nfe DEFAULT 'HOMOLOGACAO'::public.enum_ambiente_nfe NOT NULL,
    status public.enum_status_nfe DEFAULT 'RASCUNHO'::public.enum_status_nfe NOT NULL,
    ordemservicoid integer,
    vendaid integer,
    clienteid integer,
    dataemissao timestamp with time zone NOT NULL,
    dataautorizacao timestamp with time zone,
    protocolo text,
    total_produtos numeric(14,2) DEFAULT 0 NOT NULL,
    total_servicos numeric(14,2) DEFAULT 0 NOT NULL,
    total_nfe numeric(14,2) DEFAULT 0 NOT NULL,
    xml_assinado text,
    xml_autorizado text,
    justificativacancelamento text,
    createdat timestamp with time zone DEFAULT now() NOT NULL,
    updatedat timestamp with time zone DEFAULT now() NOT NULL,
    empresaid integer NOT NULL,
    icms text,
    cfop text,
    created_by uuid,
    updated_by uuid,
    deleted_by uuid,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    fornecedorid integer,
    entradaid bigint,
    "tpNF" smallint,
    destinatario_snapshot jsonb,
    emitente_snapshot jsonb,
    dados_avulsos jsonb,
    versao_regra_fiscal text,
    decisao_fiscal jsonb DEFAULT '{}'::jsonb NOT NULL,
    valor_frete numeric(14,2) DEFAULT 0 NOT NULL,
    codigo_rejeicao text,
    motivo_rejeicao text,
    rejeitada_em timestamp with time zone,
    valor_desconto numeric(14,2) DEFAULT 0 NOT NULL,
    numero_definitivo boolean DEFAULT false NOT NULL,
    saidaid bigint,
    CONSTRAINT ck_nfe_destinatario CHECK ((((clienteid IS NOT NULL) AND (fornecedorid IS NULL) AND (destinatario_snapshot IS NULL)) OR ((clienteid IS NULL) AND (fornecedorid IS NOT NULL) AND (destinatario_snapshot IS NULL)) OR ((clienteid IS NULL) AND (fornecedorid IS NULL) AND (destinatario_snapshot IS NOT NULL)) OR ((clienteid IS NOT NULL) AND (fornecedorid IS NULL) AND (destinatario_snapshot IS NOT NULL)) OR ((clienteid IS NULL) AND (fornecedorid IS NOT NULL) AND (destinatario_snapshot IS NOT NULL)))),
    CONSTRAINT nfe_valor_desconto_nonnegative CHECK ((valor_desconto >= (0)::numeric)),
    CONSTRAINT nfe_valor_frete_nonnegative CHECK ((valor_frete >= (0)::numeric))
);


--
-- Name: COLUMN nfe.versao_regra_fiscal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe.versao_regra_fiscal IS 'Versao imutavel das regras, NT, IT e schema usados para construir a NF-e.';


--
-- Name: COLUMN nfe.decisao_fiscal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe.decisao_fiscal IS 'Contexto auditavel da decisao fiscal: CRT, vigencia, modelo e classificacoes externas.';


--
-- Name: COLUMN nfe.codigo_rejeicao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe.codigo_rejeicao IS 'cStat devolvido pela SEFAZ na ultima rejeicao (ex.: 694).';


--
-- Name: COLUMN nfe.motivo_rejeicao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe.motivo_rejeicao IS 'xMotivo devolvido pela SEFAZ na ultima rejeicao.';


--
-- Name: COLUMN nfe.rejeitada_em; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe.rejeitada_em IS 'Momento da ultima rejeicao. Limpo quando a nota e autorizada.';


--
