--

COMMENT ON COLUMN public.nfe.numero_definitivo IS 'true quando o numero/serie ja foram alocados para transmissao. Rascunho e nota rejeitada ficam false: o numero exibido e provisorio.';


--
-- Name: nfe_ciencia_aviso; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.nfe_ciencia_aviso (
    id bigint NOT NULL,
    escopo uuid NOT NULL,
    nfe_id bigint,
    origem_tipo text NOT NULL,
    origem_id bigint,
    item_ref text NOT NULL,
    item_numero integer NOT NULL,
    code text NOT NULL,
    fingerprint text NOT NULL,
    versao_regra text NOT NULL,
    mensagem text NOT NULL,
    fontes jsonb DEFAULT '[]'::jsonb NOT NULL,
    dados jsonb DEFAULT '{}'::jsonb NOT NULL,
    usuario_id uuid NOT NULL,
    confirmado_em timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT nfe_ciencia_aviso_campos_preenchidos CHECK (((btrim(item_ref) <> ''::text) AND (btrim(code) <> ''::text) AND (btrim(versao_regra) <> ''::text) AND (btrim(mensagem) <> ''::text) AND (item_numero > 0) AND (fingerprint ~ '^fp[0-9]+\.[0-9a-z]+$'::text) AND (jsonb_typeof(fontes) = 'array'::text) AND (jsonb_typeof(dados) = 'object'::text))),
    CONSTRAINT nfe_ciencia_aviso_origem_tipo_valida CHECK ((origem_tipo = ANY (ARRAY['AVULSA'::text, 'OS'::text, 'VENDA'::text, 'ENTRADA'::text, 'SAIDA'::text])))
);


--
-- Name: TABLE nfe_ciencia_aviso; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.nfe_ciencia_aviso IS 'Ciência de avisos fiscais da NF-e dada pelo usuário e validada pelo servidor. Trilha de auditoria: somente inclusão. Ver docs/modulos/avisos-fiscais-nfe.md.';


--
-- Name: COLUMN nfe_ciencia_aviso.escopo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_ciencia_aviso.escopo IS 'Sessão de emissão gerada pela tela; liga a ciência ao rascunho antes de ele ter id.';


--
-- Name: COLUMN nfe_ciencia_aviso.nfe_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_ciencia_aviso.nfe_id IS 'NF-e cujo aviso esta ciência liberou (o snapshot do item cita o id). NULL se ela nunca foi usada — a situação mudou antes de salvar — ou se o rascunho foi descartado.';


--
-- Name: COLUMN nfe_ciencia_aviso.item_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_ciencia_aviso.item_ref IS 'sourceItemId do item na origem, ou #<índice> na NF-e avulsa.';


--
-- Name: COLUMN nfe_ciencia_aviso.fingerprint; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_ciencia_aviso.fingerprint IS 'Hash estável dos dados que produziram o aviso e da versão da regra (src/lib/nfe/issuesFiscais.ts).';


--
-- Name: COLUMN nfe_ciencia_aviso.versao_regra; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_ciencia_aviso.versao_regra IS 'NFE_FISCAL_RULE_VERSION vigente quando o servidor validou a ciência.';


--
-- Name: COLUMN nfe_ciencia_aviso.mensagem; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_ciencia_aviso.mensagem IS 'Mensagem do aviso como o servidor a calculou, não como a tela a mostrou.';


--
-- Name: COLUMN nfe_ciencia_aviso.dados; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_ciencia_aviso.dados IS 'Os dados que entraram no fingerprint (CFOP, CST, papel da ST, base, componentes, data fiscal...).';


