    descricao text NOT NULL,
    ncm text,
    cfop text NOT NULL,
    csosn text,
    cest text,
    unidade public.unidade_medida NOT NULL,
    quantidade numeric(14,4) NOT NULL,
    valor_unitario numeric(21,10) NOT NULL,
    valor_total numeric(14,2) NOT NULL,
    valor_desconto numeric(14,2) DEFAULT 0 NOT NULL,
    aliquotaicms numeric(5,2),
    valor_bc_icms numeric(14,2),
    valor_icms numeric(14,2),
    cst_pis text,
    aliquota_pis numeric(5,2),
    valor_pis numeric(14,2),
    cst_cofins text,
    aliquota_cofins numeric(5,2),
    valor_cofins numeric(14,2),
    createdat timestamp with time zone DEFAULT now() NOT NULL,
    updatedat timestamp with time zone DEFAULT now() NOT NULL,
    cst text,
    tributacao_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    origem_mercadoria text,
    valor_frete numeric(14,2) DEFAULT 0 NOT NULL,
    grupo_icms_xml text,
    valor_bc_icms_st numeric(14,2),
    valor_icms_st numeric(14,2),
    valor_fcp numeric(14,2),
    valor_fcp_st numeric(14,2),
    valor_bc_st_retido numeric(14,2),
    valor_icms_st_retido numeric(14,2),
    valor_fcp_st_retido numeric(14,2),
    valor_icms_desonerado numeric(14,2),
    valor_icms_diferido numeric(14,2),
    CONSTRAINT nfe_item_origem_mercadoria_check CHECK (((origem_mercadoria IS NULL) OR (origem_mercadoria ~ '^[0-8]$'::text))),
    CONSTRAINT nfe_item_valor_desconto_valido CHECK (((valor_desconto >= (0)::numeric) AND (valor_desconto <= valor_total))),
    CONSTRAINT nfe_item_valor_frete_nonnegative CHECK ((valor_frete >= (0)::numeric))
);


--
