--
-- Name: COLUMN nfe_item.valor_bc_icms_st; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_item.valor_bc_icms_st IS 'vBCST: base do ICMS-ST retido nesta operação.';


--
-- Name: COLUMN nfe_item.valor_icms_st; Type: COMMENT; Schema: public; Owner: -
--

