--
-- Name: COLUMN nfe_item.valor_fcp; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfe_item.valor_fcp IS 'vFCP: FCP sobre o ICMS próprio.';


--
