    ordemservico_id integer,
    venda_id integer,
    origem_id integer NOT NULL,
    modelo text NOT NULL,
    cliente_id integer NOT NULL,
    ancora boolean DEFAULT false NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT nfe_origem_vinculo_origem_coerente CHECK ((((tipo = 'OS'::text) AND (ordemservico_id IS NOT NULL) AND (venda_id IS NULL) AND (origem_id = ordemservico_id)) OR ((tipo = 'VENDA'::text) AND (venda_id IS NOT NULL) AND (ordemservico_id IS NULL) AND (origem_id = venda_id)))),
    CONSTRAINT nfe_origem_vinculo_tipo_check CHECK ((tipo = ANY (ARRAY['OS'::text, 'VENDA'::text])))
);


--
-- Name: TABLE nfe_origem_vinculo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.nfe_origem_vinculo IS 'Elo fiscal entre uma NF-e e cada OS/venda que ela documenta. As colunas escalares de nfe seguem como ancora; esta tabela e aditiva e e quem trava a concorrencia por origem.';


