    CONSTRAINT nfe_saida_item_vinculo_quantidade_check CHECK ((quantidade > (0)::numeric))
);


--
-- Name: nfse; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.nfse (
    id bigint NOT NULL,
    ordemservicoid integer,
    clienteid integer,
    empresaid integer,
    dataemissao timestamp with time zone DEFAULT now(),
    status character varying DEFAULT 'RASCUNHO'::character varying,
    referencia character varying,
    numero character varying,
    codigo_verificacao character varying,
    protocolo character varying,
    valor_total numeric DEFAULT 0,
    qr_code_url text,
    url_xml text,
    url_pdf text,
    erros jsonb,
    createdat timestamp with time zone DEFAULT now(),
    updatedat timestamp with time zone DEFAULT now(),
    modelo_emissao text NOT NULL,
    servico_ids integer[] NOT NULL,
    itens jsonb NOT NULL,
    informacoes_complementares text,
    payload_enviado jsonb,
    url_consulta text,
    retorno_bruto jsonb,
    tentativas jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT nfse_informacoes_complementares_length_check CHECK (((informacoes_complementares IS NULL) OR (char_length(informacoes_complementares) <= 2000))),
    CONSTRAINT nfse_itens_array_check CHECK ((jsonb_typeof(itens) = 'array'::text)),
    CONSTRAINT nfse_modelo_emissao_check CHECK ((modelo_emissao = ANY (ARRAY['MUNICIPAL'::text, 'MUNICIPAL_JOAO_PESSOA'::text, 'MUNICIPAL_CABEDELO'::text, 'NACIONAL'::text])))
);


--
-- Name: COLUMN nfse.modelo_emissao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.modelo_emissao IS 'Estratégia Focus usada na emissão, consulta e cancelamento da NFS-e.';


--
-- Name: COLUMN nfse.servico_ids; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.servico_ids IS 'IDs dos serviços da OS consolidados nesta NFS-e.';


--
-- Name: COLUMN nfse.itens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.itens IS 'Snapshot dos serviços e valores efetivamente informados na emissão.';


--
-- Name: COLUMN nfse.informacoes_complementares; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.informacoes_complementares IS 'Texto livre informado pelo contribuinte durante a emissão.';


--
-- Name: COLUMN nfse.payload_enviado; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.payload_enviado IS 'JSON exato enviado a Focus NFe nesta emissao, incluindo data_emissao. Gravado junto com o retorno, e best-effort: falha ao grava-lo nunca derruba a emissao.';


--
-- Name: COLUMN nfse.url_consulta; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.url_consulta IS 'URL do espelho HTML/portal da NFS-e; o PDF permanece exclusivamente em url_pdf.';


--
-- Name: COLUMN nfse.retorno_bruto; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.retorno_bruto IS 'Ultima resposta da Focus NFe para esta nota: metodo, URL, status HTTP, horario e corpo (JSON quando parseavel, texto cru quando nao; truncado em 20 mil caracteres). Best-effort: falha ao grava-la nunca derruba a emissao.';


--
-- Name: COLUMN nfse.tentativas; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse.tentativas IS 'Tentativas de envio recusadas antes da atual, da mais antiga para a mais recente: referencia, status, erros, payload_enviado e retorno_bruto de cada uma. A tentativa corrente NAO entra aqui -- ela continua nas colunas erros, payload_enviado e retorno_bruto. Limitado as 10 ultimas pelo codigo, porque cada retorno bruto vai ate 20 mil caracteres. Diagnostico puro: nenhuma regra de negocio le esta coluna.';


--
-- Name: nfse_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.nfse_config (
    empresa_id integer NOT NULL,
