    updated_at timestamp with time zone DEFAULT now(),
    padroes_emissao jsonb DEFAULT '{}'::jsonb NOT NULL,
    incluir_garantia_os boolean DEFAULT false NOT NULL,
    CONSTRAINT nfse_config_padroes_emissao_object_check CHECK ((jsonb_typeof(padroes_emissao) = 'object'::text))
);


--
-- Name: COLUMN nfse_config.padroes_emissao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse_config.padroes_emissao IS 'Códigos fiscais padrão por modelo de emissão (chaves: MUNICIPAL_JOAO_PESSOA, MUNICIPAL_CABEDELO, NACIONAL), usados para pré-preencher o formulário de emissão da NFS-e.';


--
-- Name: COLUMN nfse_config.incluir_garantia_os; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.nfse_config.incluir_garantia_os IS 'Preenche as informacoes complementares da NFS-e com a garantia da ordem de servico.';


