--
-- Name: ofx_importacao; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ofx_importacao (
    id bigint NOT NULL,
    banco_id bigint NOT NULL,
    arquivo_nome text NOT NULL,
    arquivo_hash text NOT NULL,
    bank_id_ofx text,
    agencia_ofx text,
    conta_ofx text,
    tipo_conta_ofx text,
    moeda text,
    periodo_inicio date,
    periodo_fim date,
    saldo_inicial numeric(14,2),
    saldo_final numeric(14,2),
    quantidade_movimentos integer DEFAULT 0 NOT NULL,
    quantidade_importados integer DEFAULT 0 NOT NULL,
    quantidade_repetidos integer DEFAULT 0 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE ofx_importacao; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ofx_importacao IS 'Um arquivo OFX importado para uma conta bancária. Guarda o cabeçalho do extrato e as contagens do que entrou; os movimentos ficam em ofx_movimento.';


--
-- Name: COLUMN ofx_importacao.arquivo_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_importacao.arquivo_hash IS 'SHA-256 do arquivo. Responde "este arquivo já foi importado?" — pergunta diferente de "este movimento já foi importado?", que é o fingerprint do movimento.';


--
-- Name: COLUMN ofx_importacao.saldo_inicial; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_importacao.saldo_inicial IS 'Deduzido do saldo final menos a soma dos movimentos: o OFX 1.x quase nunca envia saldo de abertura.';


--
-- Name: COLUMN ofx_importacao.quantidade_movimentos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_importacao.quantidade_movimentos IS 'Linhas lidas do arquivo.';


--
-- Name: COLUMN ofx_importacao.quantidade_importados; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_importacao.quantidade_importados IS 'Linhas gravadas por esta importação. Menor que o total quando o período se sobrepõe a uma importação anterior.';


--
-- Name: COLUMN ofx_importacao.quantidade_repetidos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_importacao.quantidade_repetidos IS 'Linhas que já existiam de outra importação da mesma conta e por isso não foram gravadas de novo.';


--
-- Name: ofx_importacao_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.ofx_importacao ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.ofx_importacao_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: ofx_movimento; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ofx_movimento (
    id bigint NOT NULL,
    importacao_id bigint NOT NULL,
    banco_id bigint NOT NULL,
    sequencia integer NOT NULL,
    fitid text,
    checknum text,
    refnum text,
    tipo_ofx text,
    data_postagem date NOT NULL,
    data_disponivel date,
    valor numeric(14,2) NOT NULL,
    valor_centavos bigint NOT NULL,
    nome text,
    memo text,
    fingerprint text NOT NULL,
    status text DEFAULT 'PENDENTE'::text NOT NULL,
    situacao_analise text,
    score_match integer,
    acao_conciliacao text,
    observacao text,
    transacao_id bigint,
    titulo_origem_id bigint,
    conciliado_em timestamp with time zone,
    conciliado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ofx_movimento_acao_check CHECK (((acao_conciliacao IS NULL) OR (acao_conciliacao = ANY (ARRAY['VINCULAR'::text, 'LIQUIDAR'::text, 'BAIXA_PARCIAL'::text, 'CRIAR'::text, 'IGNORAR'::text])))),
    CONSTRAINT ofx_movimento_conciliado_tem_transacao_check CHECK (((status <> 'CONCILIADO'::text) OR (transacao_id IS NOT NULL))),
    CONSTRAINT ofx_movimento_situacao_check CHECK (((situacao_analise IS NULL) OR (situacao_analise = ANY (ARRAY['MATCH_EXATO'::text, 'MATCH_PROVAVEL'::text, 'AMBIGUO'::text, 'SEM_CORRESPONDENCIA'::text, 'REVISAO_MANUAL'::text])))),
    CONSTRAINT ofx_movimento_status_check CHECK ((status = ANY (ARRAY['PENDENTE'::text, 'CONCILIADO'::text, 'IGNORADO'::text])))
);


--
-- Name: TABLE ofx_movimento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ofx_movimento IS 'Uma linha do extrato bancário importado. É o registro do que o banco informou, e o vínculo com a transação do ERP que representa aquele mesmo dinheiro.';


--
-- Name: COLUMN ofx_movimento.valor_centavos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_movimento.valor_centavos IS 'O valor em centavos inteiros, com sinal: positivo entra na conta, negativo sai. Toda comparação financeira usa esta coluna, nunca a numérica.';


--
-- Name: COLUMN ofx_movimento.fingerprint; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_movimento.fingerprint IS 'Identidade determinística da linha: conta, data, valor com sinal, tipo, CHECKNUM, REFNUM, NAME, MEMO e a ocorrência dentro do arquivo. Sem FITID — há banco que o repete em movimentos diferentes e banco que o regenera a cada exportação (C6).';


--
-- Name: COLUMN ofx_movimento.situacao_analise; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_movimento.situacao_analise IS 'Como a análise classificou a linha no momento da importação. É histórico: a decisão que valeu está em acao_conciliacao.';


--
-- Name: COLUMN ofx_movimento.transacao_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_movimento.transacao_id IS 'A transação do ERP que representa este dinheiro. Numa baixa parcial é a transação FILHA (o movimento de caixa), não o título.';


--
-- Name: COLUMN ofx_movimento.titulo_origem_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ofx_movimento.titulo_origem_id IS 'O título que foi liquidado por este movimento, quando houve baixa. Na baixa de uma vez é a mesma linha de transacao_id; na parcial, o título que continua em aberto.';


--
-- Name: ofx_movimento_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.ofx_movimento ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.ofx_movimento_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: orcamento; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orcamento (
    id bigint NOT NULL,
    clienteid integer,
    veiculoid integer,
    usuariocriadorid uuid,
    status text DEFAULT 'ABERTO'::text NOT NULL,
    descricao text,
    observacoes text,
    subtotal numeric DEFAULT 0 NOT NULL,
    desconto_tipo public.enum_tipo_desconto_venda,
    desconto numeric DEFAULT 0 NOT NULL,
    valor_frete numeric DEFAULT 0 NOT NULL,
    total numeric DEFAULT 0 NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    alvo_tipo text DEFAULT 'VEICULO'::text NOT NULL,
    peca_titulo text,
    peca_descricao text,
    peca_lacre text,
    equipamento_nome text,
    equipamento_patrimonio text,
    equipamento_ano integer,
    equipamento_horimetro numeric,
    CONSTRAINT orcamento_alvo_coerente_check CHECK (
CASE alvo_tipo
    WHEN 'VEICULO'::text THEN ((peca_titulo IS NULL) AND (equipamento_nome IS NULL))
    WHEN 'PECA'::text THEN ((veiculoid IS NULL) AND (equipamento_nome IS NULL))
    ELSE ((veiculoid IS NULL) AND (peca_titulo IS NULL))
END),
    CONSTRAINT orcamento_alvo_tipo_check CHECK ((alvo_tipo = ANY (ARRAY['VEICULO'::text, 'PECA'::text, 'EQUIPAMENTO'::text]))),
    CONSTRAINT orcamento_desconto_check CHECK ((desconto >= (0)::numeric)),
    CONSTRAINT orcamento_equipamento_ano_check CHECK (((equipamento_ano IS NULL) OR ((equipamento_ano >= 1900) AND (equipamento_ano <= 3000)))),
    CONSTRAINT orcamento_equipamento_horimetro_check CHECK (((equipamento_horimetro IS NULL) OR (equipamento_horimetro >= (0)::numeric))),
    CONSTRAINT orcamento_status_check CHECK ((status = ANY (ARRAY['ABERTO'::text, 'CONVERTIDO'::text]))),
    CONSTRAINT orcamento_subtotal_check CHECK ((subtotal >= (0)::numeric)),
    CONSTRAINT orcamento_total_check CHECK ((total >= (0)::numeric)),
    CONSTRAINT orcamento_valor_frete_check CHECK ((valor_frete >= (0)::numeric))
);


--
-- Name: COLUMN orcamento.alvo_tipo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orcamento.alvo_tipo IS 'O que sera atendido: VEICULO, PECA ou EQUIPAMENTO. Espelha ordemservico.alvo_tipo.';


--
-- Name: COLUMN orcamento.peca_titulo; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orcamento.peca_titulo IS 'Peca cotada, ainda sem linha em public.peca — ela so e criada quando o orcamento vira OS.';


--
-- Name: COLUMN orcamento.equipamento_nome; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.orcamento.equipamento_nome IS 'Maquina/equipamento cotado, no mesmo formato inline de ordemservico.';


--
-- Name: orcamento_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.orcamento ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.orcamento_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: orcamento_produto; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orcamento_produto (
    orcamentoid bigint NOT NULL,
    produtoid integer NOT NULL,
    quantidade numeric NOT NULL,
    precounitario numeric NOT NULL,
    desconto_tipo public.enum_tipo_desconto_venda,
    desconto numeric DEFAULT 0 NOT NULL,
    subtotal numeric DEFAULT 0 NOT NULL,
    CONSTRAINT orcamento_produto_desconto_check CHECK ((desconto >= (0)::numeric)),
    CONSTRAINT orcamento_produto_precounitario_check CHECK ((precounitario >= (0)::numeric)),
    CONSTRAINT orcamento_produto_quantidade_check CHECK ((quantidade > (0)::numeric)),
    CONSTRAINT orcamento_produto_subtotal_check CHECK ((subtotal >= (0)::numeric))
);


--
-- Name: orcamento_produto_avulso; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orcamento_produto_avulso (
    id bigint NOT NULL,
    orcamentoid bigint NOT NULL,
    titulo text NOT NULL,
    quantidade integer NOT NULL,
    precounitario numeric NOT NULL,
    desconto_tipo public.enum_tipo_desconto_venda,
    desconto numeric DEFAULT 0 NOT NULL,
    subtotal numeric DEFAULT 0 NOT NULL,
    desconto_informativo_tipo public.enum_tipo_desconto_venda,
    desconto_informativo numeric(15,2) DEFAULT 0 NOT NULL,
    CONSTRAINT orcamento_produto_avulso_desconto_check CHECK ((desconto >= (0)::numeric)),
    CONSTRAINT orcamento_produto_avulso_desconto_informativo_check CHECK (((desconto_informativo >= (0)::numeric) AND (desconto_informativo < 'Infinity'::numeric) AND ((desconto_informativo_tipo IS NOT NULL) OR (desconto_informativo = (0)::numeric)) AND ((desconto_informativo_tipo IS DISTINCT FROM 'PORCENTAGEM'::public.enum_tipo_desconto_venda) OR (desconto_informativo <= (100)::numeric)))),
