--
-- Name: radio_station; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.radio_station (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    frequency text,
    city text,
    state text,
    country text DEFAULT 'Brasil'::text NOT NULL,
    neighborhood text,
    description text,
    genres text[] DEFAULT '{}'::text[] NOT NULL,
    logo_url text,
    website_url text,
    source_page text,
    stream_url text,
    playlist_url text,
    playlist_format text,
    stream_type text,
    codec text,
    bitrate integer,
    stream_status text DEFAULT 'UNKNOWN'::text NOT NULL,
    last_checked_at timestamp with time zone,
    last_online_at timestamp with time zone,
    active boolean DEFAULT true NOT NULL,
    system_default boolean DEFAULT false NOT NULL,
    company_id integer,
    created_by_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    channel_type text DEFAULT 'RADIO'::text NOT NULL,
    CONSTRAINT radio_station_bitrate_check CHECK (((bitrate IS NULL) OR (bitrate > 0))),
    CONSTRAINT radio_station_channel_type_check CHECK ((channel_type = ANY (ARRAY['RADIO'::text, 'THEMATIC'::text]))),
    CONSTRAINT radio_station_name_check CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT radio_station_playlist_format_check CHECK (((playlist_format IS NULL) OR (playlist_format = ANY (ARRAY['M3U'::text, 'M3U8'::text, 'PLS'::text])))),
    CONSTRAINT radio_station_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text)),
    CONSTRAINT radio_station_source_check CHECK (((NOT active) OR (channel_type = 'THEMATIC'::text) OR (stream_url IS NOT NULL) OR (playlist_url IS NOT NULL))),
    CONSTRAINT radio_station_stream_status_check CHECK ((stream_status = ANY (ARRAY['ONLINE'::text, 'OFFLINE'::text, 'UNKNOWN'::text, 'INVALID'::text, 'PLAYLIST_FOUND'::text, 'RESOLVING'::text]))),
    CONSTRAINT radio_station_stream_type_check CHECK (((stream_type IS NULL) OR (stream_type = ANY (ARRAY['DIRECT_STREAM'::text, 'HLS'::text])))),
    CONSTRAINT radio_station_system_scope_check CHECK (((NOT system_default) OR (company_id IS NULL)))
);


--
-- Name: TABLE radio_station; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.radio_station IS 'Catalogo global (company_id null) e radios privadas da empresa. source_page nunca e tratada como stream.';


--
-- Name: COLUMN radio_station.channel_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.radio_station.channel_type IS 'RADIO para emissoras e THEMATIC para canais musicais continuos por genero.';


