    CONSTRAINT radio_stream_source_stream_status_check CHECK ((stream_status = ANY (ARRAY['ONLINE'::text, 'OFFLINE'::text, 'UNKNOWN'::text, 'INVALID'::text, 'PLAYLIST_FOUND'::text, 'RESOLVING'::text]))),
    CONSTRAINT radio_stream_source_stream_type_check CHECK (((stream_type IS NULL) OR (stream_type = ANY (ARRAY['DIRECT_STREAM'::text, 'HLS'::text]))))
);


