COMMENT ON TABLE public.radio_stream_source IS 'Fontes priorizadas dos canais tematicos. O frontend recebe somente a melhor fonte online pelo contrato de radio_station.';


--
-- Name: recebimento_por_documento; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.recebimento_por_documento AS
 WITH titulo AS (
         SELECT t.id,
                CASE
                    WHEN (t.ordemservicoid IS NOT NULL) THEN 'OS'::text
                    ELSE 'VENDA'::text
                END AS tipo_documento,
            COALESCE(t.ordemservicoid, t.vendaid) AS documento_id,
            GREATEST((COALESCE(t.valor, (0)::numeric) - GREATEST(COALESCE(t.valor_acrescimos, (0)::numeric), (0)::numeric)), (0)::numeric) AS face,
            LEAST(GREATEST(COALESCE(t.valor_baixado, (0)::numeric), (0)::numeric), GREATEST((COALESCE(t.valor, (0)::numeric) - GREATEST(COALESCE(t.valor_acrescimos, (0)::numeric), (0)::numeric)), (0)::numeric)) AS pago,
            t.pendente,
            t.pagamento_multiplo_id
           FROM public.transacao t
          WHERE ((t.is_deleted = false) AND (upper((t.tipo)::text) = 'RECEITA'::text) AND (t.evento_financeiro_id IS NULL) AND (t.baixa_de_transacao_id IS NULL) AND ((t.ordemservicoid IS NOT NULL) OR (t.vendaid IS NOT NULL)))
        )
 SELECT titulo.id AS transacao_id,
    titulo.tipo_documento,
    titulo.documento_id,
        CASE
            WHEN (titulo.pendente AND (titulo.pago > (0)::numeric)) THEN titulo.pago
            ELSE titulo.face
        END AS valor,
        CASE
            WHEN (titulo.pendente AND (titulo.pago > (0)::numeric)) THEN false
            ELSE titulo.pendente
        END AS pendente,
    titulo.pagamento_multiplo_id
   FROM titulo
  WHERE ((NOT (titulo.pendente AND (titulo.pago > (0)::numeric))) OR (titulo.pago > (0)::numeric))
UNION ALL
 SELECT titulo.id AS transacao_id,
    titulo.tipo_documento,
    titulo.documento_id,
    round((titulo.face - titulo.pago), 2) AS valor,
    true AS pendente,
    titulo.pagamento_multiplo_id
   FROM titulo
  WHERE (titulo.pendente AND (titulo.pago > (0)::numeric) AND (titulo.face > titulo.pago))
UNION ALL
 SELECT t.id AS transacao_id,
    r.tipo_documento,
    r.documento_id,
    r.valor,
    t.pendente,
    t.pagamento_multiplo_id
   FROM (public.pagamento_multiplo_rateio r
     JOIN public.transacao t ON ((t.id = r.transacao_id)))
  WHERE (t.is_deleted = false);


--
-- Name: VIEW recebimento_por_documento; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.recebimento_por_documento IS 'Fonte única de "quanto esta OS ou venda recebeu". Unifica o vínculo direto, o rateio do pagamento múltiplo e a baixa parcial — que emite duas linhas, a paga e a que falta.';


