CREATE TABLE public.site_product_link (
    id bigint NOT NULL,
    empresa_id integer NOT NULL,
    produto_id integer NOT NULL,
    status text DEFAULT 'RASCUNHO'::text NOT NULL,
    titulo_site text,
    descricao_site text,
    usar_preco_erp boolean DEFAULT true NOT NULL,
    preco_site numeric(14,2),
    estoque_seguranca integer DEFAULT 0 NOT NULL,
    estoque_maximo_site integer,
    destaque boolean DEFAULT false NOT NULL,
    slug text,
    url_publica text,
    sync_version bigint DEFAULT 0 NOT NULL,
    sync_status text DEFAULT 'NAO_SINCRONIZADO'::text NOT NULL,
    last_synced_at timestamp with time zone,
    last_sync_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT site_product_link_estoque_maximo_site_check CHECK (((estoque_maximo_site IS NULL) OR (estoque_maximo_site >= 0))),
    CONSTRAINT site_product_link_estoque_seguranca_check CHECK ((estoque_seguranca >= 0)),
    CONSTRAINT site_product_link_preco_site_check CHECK (((preco_site IS NULL) OR (preco_site >= (0)::numeric))),
    CONSTRAINT site_product_link_status_check CHECK ((status = ANY (ARRAY['RASCUNHO'::text, 'PUBLICADO'::text, 'PAUSADO'::text, 'ERRO'::text]))),
    CONSTRAINT site_product_link_sync_status_check CHECK ((sync_status = ANY (ARRAY['NAO_SINCRONIZADO'::text, 'PENDENTE'::text, 'SINCRONIZADO'::text, 'ERRO'::text])))
);


--
-- Name: TABLE site_product_link; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.site_product_link IS 'Configuração do produto no canal Loja própria. Não interfere em produto.exibirPdv.';


--
-- Name: COLUMN site_product_link.usar_preco_erp; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.site_product_link.usar_preco_erp IS 'Quando true, publica produto.precovenda. Quando false, exige preco_site.';


--
-- Name: COLUMN site_product_link.estoque_seguranca; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.site_product_link.estoque_seguranca IS 'Quantidade mantida fora do saldo publicável da loja.';


--
-- Name: site_catalog_export; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.site_catalog_export WITH (security_invoker='true') AS
 SELECT link.id AS product_link_id,
    link.empresa_id,
    p.id AS produto_id,
    link.sync_version,
    link.status,
    link.sync_status,
    link.last_synced_at,
    link.last_sync_error,
    COALESCE(NULLIF(btrim(link.titulo_site), ''::text), NULLIF(btrim(p."tituloMarketplace"), ''::text), p.titulo) AS titulo,
    COALESCE(NULLIF(btrim(link.descricao_site), ''::text), NULLIF(btrim(p."descricaoMarketplace"), ''::text), ''::text) AS descricao,
        CASE
            WHEN link.usar_preco_erp THEN p.precovenda
            ELSE link.preco_site
        END AS preco,
    LEAST(GREATEST((COALESCE(p.estoque, 0) - link.estoque_seguranca), 0), COALESCE(link.estoque_maximo_site, 2147483647)) AS estoque,
    p.referencia,
    p.fabricante,
    p.grupo_produto_id,
    grupo.nome AS grupo_nome,
    p."imgUrl" AS imagem_principal,
    p.conservacao,
    p.codigobarras,
    link.destaque,
    link.slug,
    ((link.status = 'PUBLICADO'::text) AND (COALESCE(p.is_deleted, false) = false) AND (COALESCE(grupo."exibirSite", true) = true)) AS visible,
    GREATEST(link.updated_at, COALESCE(p.updatedat, p.createdat), (COALESCE(grupo.updatedat, grupo.createdat))::timestamp with time zone) AS source_updated_at
   FROM ((public.site_product_link link
     JOIN public.produto p ON ((p.id = link.produto_id)))
     LEFT JOIN public.produtogrupo grupo ON ((grupo.id = p.grupo_produto_id)));


--
-- Name: site_catalog_sync_queue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.site_catalog_sync_queue (
    id bigint NOT NULL,
    empresa_id integer NOT NULL,
    product_link_id bigint NOT NULL,
    produto_id integer NOT NULL,
    event_id uuid DEFAULT gen_random_uuid() NOT NULL,
    desired_version bigint NOT NULL,
    status text DEFAULT 'PENDENTE'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    locked_at timestamp with time zone,
    next_retry_at timestamp with time zone,
    last_error text,
    processed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT site_catalog_sync_queue_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT site_catalog_sync_queue_status_check CHECK ((status = ANY (ARRAY['PENDENTE'::text, 'PROCESSANDO'::text, 'PROCESSADA'::text, 'ERRO'::text])))
);


