--
-- Name: system_notification; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_notification (
    id bigint NOT NULL,
    usuario_id uuid NOT NULL,
    category text DEFAULT 'SYSTEM'::text NOT NULL,
    priority text DEFAULT 'INFO'::text NOT NULL,
    title text NOT NULL,
    message text NOT NULL,
    href text,
    source text NOT NULL,
    source_event_id text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    telegram_sent_at timestamp with time zone,
    telegram_attempts integer DEFAULT 0 NOT NULL,
    telegram_next_retry_at timestamp with time zone,
    telegram_locked_at timestamp with time zone,
    telegram_last_error text,
    telegram_message_id bigint,
    CONSTRAINT system_notification_category_check CHECK ((category = ANY (ARRAY['MARKETPLACE'::text, 'SALES'::text, 'STOCK'::text, 'FINANCIAL'::text, 'SYSTEM'::text]))),
    CONSTRAINT system_notification_message_check CHECK (((length(btrim(message)) >= 1) AND (length(btrim(message)) <= 1000))),
    CONSTRAINT system_notification_priority_check CHECK ((priority = ANY (ARRAY['INFO'::text, 'SUCCESS'::text, 'WARNING'::text, 'CRITICAL'::text]))),
    CONSTRAINT system_notification_source_check CHECK (((length(btrim(source)) >= 1) AND (length(btrim(source)) <= 80))),
    CONSTRAINT system_notification_source_event_check CHECK (((length(btrim(source_event_id)) >= 1) AND (length(btrim(source_event_id)) <= 240))),
    CONSTRAINT system_notification_title_check CHECK (((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 160)))
);


