-- Name: telegram_usuario_preferencia; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.telegram_usuario_preferencia (
    usuario_id uuid NOT NULL,
    chat_id bigint,
    telegram_user_id bigint,
    telegram_username text,
    telegram_nome text,
    vinculado_em timestamp with time zone,
    ativo boolean DEFAULT true NOT NULL,
    modo text DEFAULT 'CRIACAO_FINALIZACAO'::text NOT NULL,
    escopo text DEFAULT 'MINHAS'::text NOT NULL,
    notificar_criacao boolean DEFAULT true NOT NULL,
    status_selecionados text[] DEFAULT '{}'::text[] NOT NULL,
    ultimo_erro text,
    ultimo_teste_em timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notificar_financeiro_diario boolean DEFAULT false NOT NULL,
    horario_resumo_financeiro time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    financeiro_incluir_atrasadas boolean DEFAULT true NOT NULL,
    financeiro_enviar_sem_contas boolean DEFAULT false NOT NULL,
    estoque_eventos_selecionados text[] DEFAULT '{}'::text[] NOT NULL,
    fiscal_eventos_selecionados text[] DEFAULT '{}'::text[] NOT NULL,
    notificar_receber_diario boolean DEFAULT false NOT NULL,
    horario_resumo_receber time without time zone DEFAULT '08:00:00'::time without time zone NOT NULL,
    receber_incluir_vencidas boolean DEFAULT true NOT NULL,
    receber_enviar_sem_contas boolean DEFAULT false NOT NULL,
    notificar_marketplace boolean DEFAULT false NOT NULL,
    financeiro_eventos_selecionados text[] DEFAULT '{}'::text[] NOT NULL,
    financeiro_valor_minimo numeric(14,2) DEFAULT 0 NOT NULL,
    financeiro_origens_selecionadas text[] DEFAULT '{}'::text[] NOT NULL,
    financeiro_bancos_selecionados bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    marketplace_topicos_selecionados text[],
    notificar_site boolean DEFAULT false NOT NULL,
    CONSTRAINT telegram_preferencia_escopo_check CHECK ((escopo = ANY (ARRAY['TODAS'::text, 'MINHAS'::text, 'MEU_SETOR'::text]))),
    CONSTRAINT telegram_preferencia_estoque_eventos_check CHECK ((estoque_eventos_selecionados <@ ARRAY['ENTRADA_REGISTRO'::text, 'ENTRADA_ESTORNO'::text, 'SAIDA_MANUAL_REGISTRO'::text, 'SAIDA_MANUAL_ESTORNO'::text, 'VENDA_REGISTRO'::text, 'VENDA_ESTORNO'::text, 'ORDEM_SERVICO_REGISTRO'::text, 'ORDEM_SERVICO_ESTORNO'::text])),
    CONSTRAINT telegram_preferencia_financeiro_eventos_check CHECK ((financeiro_eventos_selecionados <@ ARRAY['CONTA_PAGAR_CRIADA'::text, 'CONTA_RECEBER_CRIADA'::text, 'MOVIMENTO_CAIXA_CRIADO'::text, 'CONTA_PAGAR_LIQUIDADA'::text, 'CONTA_RECEBER_LIQUIDADA'::text, 'BAIXA_ESTORNADA'::text, 'LANCAMENTO_EXCLUIDO'::text, 'TRANSFERENCIA_ENTRE_CONTAS'::text])),
    CONSTRAINT telegram_preferencia_financeiro_origens_check CHECK ((financeiro_origens_selecionadas <@ ARRAY['AVULSO'::text, 'ORDEM_SERVICO'::text, 'VENDA'::text, 'ENTRADA'::text])),
    CONSTRAINT telegram_preferencia_financeiro_valor_minimo_check CHECK ((financeiro_valor_minimo >= (0)::numeric)),
    CONSTRAINT telegram_preferencia_fiscal_eventos_check CHECK ((fiscal_eventos_selecionados <@ ARRAY['NFE_AUTORIZADA'::text, 'NFE_REJEITADA'::text, 'NFE_DENEGADA'::text, 'NFE_CANCELADA'::text, 'NFE_RESULTADO_INCERTO'::text, 'NFSE_AUTORIZADA'::text, 'NFSE_REJEITADA'::text, 'NFSE_CANCELADA'::text, 'DFE_RECEBIDA'::text, 'DFE_CANCELADA'::text])),
    CONSTRAINT telegram_preferencia_modo_check CHECK ((modo = ANY (ARRAY['CRIACAO'::text, 'CRIACAO_FINALIZACAO'::text, 'TODOS'::text, 'PERSONALIZADO'::text]))),
    CONSTRAINT telegram_preferencia_status_check CHECK ((status_selecionados <@ ARRAY['AGUARDANDO_CHECKLIST'::text, 'ORCAMENTO'::text, 'APROVACAO_ORCAMENTO'::text, 'ORCAMENTO_APROVADO'::text, 'ORCAMENTO_RECUSADO'::text, 'EM_ANDAMENTO'::text, 'PAGAMENTO'::text, 'SEM_COBRANCA'::text, 'CONCLUIDO'::text, 'CANCELADO'::text]))
);


