--
-- Name: transacao_cliente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.transacao_cliente AS
 SELECT t.id AS transacao_id,
    COALESCE(t.cliente_id, os.clienteid, v.clienteid) AS cliente_id,
    t.valor,
    t.valor_acrescimos,
    t.valor_baixado,
    t.pendente,
    t.data,
    t.vencimento_em,
    t.pago_em,
    t.ordemservicoid,
    t.vendaid,
    t.metodopagamento,
    t.origem
   FROM ((public.transacao t
     LEFT JOIN public.ordemservico os ON ((os.id = t.ordemservicoid)))
     LEFT JOIN public.venda v ON ((v.id = t.vendaid)))
  WHERE ((t.tipo = 'RECEITA'::public.tipos_transacao) AND (t.is_deleted = false) AND (t.evento_financeiro_id IS NULL));


--
-- Name: VIEW transacao_cliente; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.transacao_cliente IS 'Titulos a receber com o dono resolvido (cliente_id, senao OS, senao venda). Nao infere vinculo.';


