--

CREATE TABLE public.usoconsumo_entrada (
    id bigint NOT NULL,
    fornecedor_id integer,
    fiscal boolean DEFAULT false NOT NULL,
    chave_nfe text,
    numero_nota text,
    serie_nota text,
    data_emissao timestamp with time zone,
    tipo text DEFAULT 'COMPRA_FORNECEDOR'::text NOT NULL,
    origem text DEFAULT 'MANUAL'::text NOT NULL,
    status text DEFAULT 'CONFIRMADA'::text NOT NULL,
    valor_total numeric(14,2) DEFAULT 0 NOT NULL,
    documento_fiscal_recebido_id bigint,
    created_by uuid,
    cancelada_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    cancelada_at timestamp with time zone,
    motivo_cancelamento text,
    observacao text,
    escopo text DEFAULT 'USOCONSUMO'::text NOT NULL,
    CONSTRAINT usoconsumo_entrada_escopo_check CHECK ((escopo = ANY (ARRAY['USOCONSUMO'::text, 'GERAL'::text, 'MISTO'::text]))),
    CONSTRAINT usoconsumo_entrada_fiscal_check CHECK (((NOT fiscal) OR ((chave_nfe ~ '^[0-9]{44}$'::text) AND (fornecedor_id IS NOT NULL)))),
    CONSTRAINT usoconsumo_entrada_motivo_cancelamento_check CHECK (((status <> 'CANCELADA'::text) OR (NULLIF(btrim(motivo_cancelamento), ''::text) IS NOT NULL))),
    CONSTRAINT usoconsumo_entrada_origem_check CHECK ((origem = ANY (ARRAY['AJUSTE_RAPIDO'::text, 'MANUAL'::text, 'NFE_TERCEIRO'::text, 'INVENTARIO'::text]))),
    CONSTRAINT usoconsumo_entrada_status_check CHECK ((status = ANY (ARRAY['CONFIRMADA'::text, 'CANCELADA'::text]))),
    CONSTRAINT usoconsumo_entrada_valor_total_check CHECK ((valor_total >= (0)::numeric))
);


