--
-- Name: usoconsumo_movimento_autor; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.usoconsumo_movimento_autor AS
 SELECT DISTINCT u.id,
    u.nome,
    movimento.escopo
   FROM (public.usuario u
     JOIN LATERAL ( SELECT e.escopo
           FROM public.usoconsumo_entrada e
          WHERE (e.created_by = u.id)
        UNION
         SELECT s.escopo
           FROM public.usoconsumo_saida s
          WHERE (s.created_by = u.id)) movimento ON (true));


--
-- Name: VIEW usoconsumo_movimento_autor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.usoconsumo_movimento_autor IS 'Usuarios com pelo menos uma entrada ou saida, por estoque simples (`escopo`).';


