    valor_unitario_compra numeric(14,4) NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT usoconsumo_movimento_entrada_quantidade_check CHECK ((quantidade > 0)),
    CONSTRAINT usoconsumo_movimento_entrada_saldo_anterior_check CHECK ((saldo_anterior >= 0)),
    CONSTRAINT usoconsumo_movimento_entrada_saldo_resultante_check CHECK ((saldo_resultante >= 0)),
    CONSTRAINT usoconsumo_movimento_entrada_tipo_check CHECK ((tipo = ANY (ARRAY['ENTRADA'::text, 'CANCELAMENTO'::text]))),
    CONSTRAINT usoconsumo_movimento_entrada_valor_unitario_compra_check CHECK ((valor_unitario_compra >= (0)::numeric))
);


