);


--
-- Name: usoconsumo_movimento_historico; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.usoconsumo_movimento_historico AS
 SELECT 'entrada'::text AS sentido,
    e.id,
    e.escopo,
    e.created_at,
    e.status,
    e.valor_total,
    e.numero_nota,
    e.tipo,
    te.nome AS tipo_nome,
    e.origem,
    NULL::text AS motivo,
    NULL::text AS motivo_nome,
    e.observacao,
    f.nomerazaosocial AS parte,
    (COALESCE(e.fiscal, false) OR (NULLIF(btrim(COALESCE(e.numero_nota, ''::text)), ''::text) IS NOT NULL) OR (e.origem = 'NFE_TERCEIRO'::text)) AS fiscal,
    itens.resumo AS itens_resumo,
    e.created_by,
    u.nome AS criador_nome,
    NULL::integer AS saida_ordemservicoid,
    lower(concat_ws(' '::text, (e.id)::text, e.numero_nota, f.nomerazaosocial, replace(COALESCE(e.tipo, ''::text), '_'::text, ' '::text), te.nome, e.observacao, itens.resumo, u.nome, 'entrada', e.status,
        CASE
            WHEN (COALESCE(e.fiscal, false) OR (e.numero_nota IS NOT NULL)) THEN 'nf-e nota fiscal'::text
            ELSE NULL::text
        END)) AS busca
   FROM ((((public.usoconsumo_entrada e
     LEFT JOIN public.tipos_entrada te ON ((te.codigo = e.tipo)))
     LEFT JOIN public.fornecedor f ON ((f.id = e.fornecedor_id)))
     LEFT JOIN public.usuario u ON ((u.id = e.created_by)))
     LEFT JOIN LATERAL ( SELECT string_agg((((((COALESCE(NULLIF(btrim(COALESCE(ei.titulo, ''::text)), ''::text), i.titulo, 'Item'::text) || ' ('::text) || ei.quantidade) || ' '::text) || (ei.unidade)::text) || ')'::text), ', '::text ORDER BY ei.id) AS resumo
           FROM (public.usoconsumo_entrada_item ei
             LEFT JOIN public.usoconsumo_item i ON ((i.id = ei.item_id)))
          WHERE (ei.entrada_id = e.id)) itens ON (true))
UNION ALL
 SELECT 'saida'::text AS sentido,
    s.id,
    s.escopo,
    s.created_at,
    s.status,
    NULL::numeric AS valor_total,
    NULL::text AS numero_nota,
    NULL::text AS tipo,
    NULL::text AS tipo_nome,
    NULL::text AS origem,
    s.motivo,
    tms.nome AS motivo_nome,
    s.observacao,
    COALESCE(NULLIF(btrim(COALESCE(s.funcionario, ''::text)), ''::text), NULLIF(btrim(COALESCE(s.setor, ''::text)), ''::text), cc.nome) AS parte,
    false AS fiscal,
    itens.resumo AS itens_resumo,
    s.created_by,
    u.nome AS criador_nome,
    s.ordemservicoid AS saida_ordemservicoid,
    lower(concat_ws(' '::text, (s.id)::text, replace(COALESCE(s.motivo, ''::text), '_'::text, ' '::text), tms.nome, s.observacao, s.funcionario, s.setor, cc.nome, itens.resumo, u.nome, (s.ordemservicoid)::text,
        CASE
            WHEN (s.ordemservicoid IS NOT NULL) THEN 'os ordem de servico'::text
            ELSE NULL::text
        END, 'saida', s.status)) AS busca
   FROM ((((public.usoconsumo_saida s
     LEFT JOIN public.tipos_motivo_saida tms ON ((tms.codigo = s.motivo)))
     LEFT JOIN public.centrosdecusto cc ON ((cc.id = s.centro_custo_id)))
     LEFT JOIN public.usuario u ON ((u.id = s.created_by)))
     LEFT JOIN LATERAL ( SELECT string_agg((((((COALESCE(i.titulo, 'Item'::text) || ' ('::text) || si.quantidade) || ' '::text) || (i.unidade)::text) || ')'::text), ', '::text ORDER BY si.id) AS resumo
           FROM (public.usoconsumo_saida_item si
             LEFT JOIN public.usoconsumo_item i ON ((i.id = si.item_id)))
          WHERE (si.saida_id = s.id)) itens ON (true));


--
-- Name: VIEW usoconsumo_movimento_historico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.usoconsumo_movimento_historico IS 'Entradas e saidas dos estoques simples (uso e consumo e geral/avulso) em uma linha do tempo unica, separadas por `escopo`, com a OS que consumiu o item.';


--
-- Name: COLUMN usoconsumo_movimento_historico.saida_ordemservicoid; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.usoconsumo_movimento_historico.saida_ordemservicoid IS 'OS que registrou o consumo. Preenchida, a saida so pode ser cancelada pela ordem de servico.';


--
-- Name: usoconsumo_movimento_financeiro_historico; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.usoconsumo_movimento_financeiro_historico AS
 SELECT sentido,
    id,
    escopo,
    created_at,
    status,
    valor_total,
    numero_nota,
    tipo,
    tipo_nome,
    origem,
    motivo,
    motivo_nome,
    observacao,
    parte,
    fiscal,
    itens_resumo,
    created_by,
    criador_nome,
    saida_ordemservicoid,
    busca,
        CASE
            WHEN (sentido = 'entrada'::text) THEN (EXISTS ( SELECT 1
               FROM public.transacao transacao
              WHERE ((transacao.usoconsumo_entrada_id = historico.id) AND (transacao.is_deleted = false))))
            ELSE NULL::boolean
        END AS financeiro_lancado
   FROM public.usoconsumo_movimento_historico historico;


--
-- Name: VIEW usoconsumo_movimento_financeiro_historico; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.usoconsumo_movimento_financeiro_historico IS 'Historico dos estoques simples acrescido do indicador de lancamento financeiro ativo da entrada.';


