--

CREATE TRIGGER auditoria_cliente_saldo_movimento_delete AFTER DELETE ON public.cliente_saldo_movimento FOR EACH ROW WHEN ((old.origem = 'MANUAL'::text)) EXECUTE FUNCTION public.registrar_auditoria();


--
-- Name: cliente_saldo_movimento auditoria_cliente_saldo_movimento_update; Type: TRIGGER; Schema: public; Owner: -
--

CREATE TRIGGER auditoria_cliente_saldo_movimento_update AFTER UPDATE ON public.cliente_saldo_movimento FOR EACH ROW WHEN (((old.origem = 'MANUAL'::text) AND (((old.sentido IS DISTINCT FROM new.sentido) OR (old.valor IS DISTINCT FROM new.valor)) OR (old.motivo IS DISTINCT FROM new.motivo)))) EXECUTE FUNCTION public.registrar_auditoria();


